        private void Awake()
        {
            LoadSavedSettings();
            ConfigureRuntimePerformance();
            SliceGeneratedSheets();
            BuildWorld();
            BuildProceduralAudio();
            BuildUi();
            ConfigureRunSeed(false);
            StartStage(1);
            ShowTitle();
        }

        private void ConfigureRuntimePerformance()
        {
            int targetRate = CurrentTargetFrameRate();
            QualitySettings.vSyncCount = 0;
            Application.targetFrameRate = targetRate;
            Time.fixedDeltaTime = 1f / targetRate;
            Time.maximumDeltaTime = .10f;
        }

        private int CurrentTargetFrameRate()
        {
            return frameRateMode == 0 ? BatteryFrameRate : SmoothFrameRate;
        }

        private void Update()
        {
            float dt = Time.deltaTime;
            ApplySafeArea();
            UpdateLocalDataClearConfirmation();
            if (hitStopTimer > 0 && !paused)
            {
                hitStopTimer -= Time.unscaledDeltaTime;
                if (hitStopTimer <= 0) Time.timeScale = ModalWantsTimeFreeze() ? 0f : 1f;
            }
            attackCooldown -= dt;
            dodgeCooldown -= dt;
            invulnTimer -= dt;
            perfectDodgeWindow -= dt;
            enemyThreatHintCooldown -= dt;
            hapticCooldownTimer -= Time.unscaledDeltaTime;
            lightHitWorldTextCooldown = Mathf.Max(0f, lightHitWorldTextCooldown - dt);
            lightHitConfirmCooldown = Mathf.Max(0f, lightHitConfirmCooldown - dt);
            attackStepWorldTextCooldown = Mathf.Max(0f, attackStepWorldTextCooldown - dt);
            attackBreakReadyCueCooldown = Mathf.Max(0f, attackBreakReadyCueCooldown - dt);
            skillBufferIntentCueCooldown = Mathf.Max(0f, skillBufferIntentCueCooldown - dt);
            comboFinisherWorldTextCooldown = Mathf.Max(0f, comboFinisherWorldTextCooldown - dt);
            minorFloatingDamageTextCooldown = Mathf.Max(0f, minorFloatingDamageTextCooldown - dt);
            comboTimer -= dt;
            heroActionLockTimer -= dt;
            attackBufferTimer -= dt;
            attackBufferConfirmTimer -= dt;
            jumpBufferTimer -= dt;
            dodgeBufferTimer -= dt;
            dodgeBufferConfirmTimer -= dt;
            groundedGraceTimer -= dt;
            platformDropThroughTimer = Mathf.Max(0f, platformDropThroughTimer - dt);
            if (platformDropThroughTimer <= 0f) platformDropThroughTarget = null;
            foreach (var key in skillCooldowns.Keys.ToList()) skillCooldowns[key] -= dt;
            foreach (var key in skillBufferTimers.Keys.ToList()) skillBufferTimers[key] -= dt;
            if (!titleActive && !paused && !inputLocked && (!victoryPanel || !victoryPanel.gameObject.activeSelf))
                runTime += dt;
            HandleRoomRewardHotkeys();
            TickGameplayInputWatchdogs();
            PruneInvalidEnemies();
            RecoverHungRuneRollIfPossible();
            RecoverMovementInputLockIfPossible();
            ReconcileMovementSegmentWithPlayerPosition();

            if (!inputLocked)
            {
                ReadKeyboardAndMove(dt);
                UpdateTutorialProgress();
                if (Input.GetKeyDown(KeyCode.J) || Input.GetKeyDown(KeyCode.Space) || ControllerAttackDown()) RequestBasicAttack();
                if ((touchAttackHeld || Input.GetKey(KeyCode.J) || Input.GetKey(KeyCode.Space) || ControllerAttackHeld()) && attackCooldown <= 0) RequestBasicAttack();
                if (autoAttackEnabled && attackCooldown <= 0 && TryPrepareAutoAttack()) RequestBasicAttack();
                if (attackBufferTimer > 0 && attackCooldown <= 0) ConsumeBufferedAttack();
                if (Input.GetKeyDown(KeyCode.K) || ControllerJumpDown()) RequestJump();
                if (Input.GetKeyDown(KeyCode.LeftShift) || Input.GetKeyDown(KeyCode.RightShift) || ControllerDodgeDown()) RequestDodge();
                TryConsumeDodgeBuffer();
                if (Input.GetKeyDown(KeyCode.U) || ControllerSkill1Down()) RequestSkill(SkillKind.SlashWave);
                TryConsumeBufferedSkills();
                if (Input.GetKeyDown(KeyCode.R) || ControllerRuneDown()) TryOpenRune();
                if (Input.GetKeyDown(KeyCode.F) || ControllerInteractDown()) TryOpenShop();
            }
            else if (shopPanel && shopPanel.gameObject.activeSelf && (Input.GetKeyDown(KeyCode.F) || ControllerInteractDown()))
                CloseShop();
            if (inputLocked)
            {
                touchAttackHeld = false;
                attackBufferTimer = 0f;
                jumpBufferTimer = 0f;
                dodgeBufferTimer = 0f;
                ClearSkillBuffers();
                ClearPlatformDropThrough();
                jumpAxisHeldLastFrame = false;
                ResetJoystickIntentLock();
                ClearAutoAimTargetCue();
                HideSkillAimPreview();
            }
            if (Input.GetKeyDown(KeyCode.Escape) || Input.GetKeyDown(KeyCode.P) || ControllerMenuDown())
            {
                if (achievementPanel && achievementPanel.gameObject.activeSelf) ToggleAchievementPanel();
                else if (runeCodexPanel && runeCodexPanel.gameObject.activeSelf) ToggleRuneCodexPanel();
                else if (aboutPanel && aboutPanel.gameObject.activeSelf) ToggleAboutPanel();
                else TogglePause();
            }

            UpdateCameraFollow();
            gateBlockHintCooldown = Mathf.Max(0f, gateBlockHintCooldown - dt);
            proceedHintTimer = Mathf.Max(0f, proceedHintTimer - dt);
            UpdateEnemies(dt);
            UpdateHitEffects(dt);
            UpdateFloatingDamageTexts(dt);
            UpdateMergedCoinPickupText(dt);
            UpdateMergedResourcePickupText(dt);
            UpdateCompanionPet(dt);
            UpdatePickups(dt);
            UpdateProgressGate();
            ReconcileMovementSegmentWithPlayerPosition();
            UpdateUi();
            EnsureHeroVisualState();
            SyncHeroContrastSilhouette();
            UpdateHeroPosePunch();
            UpdateControlFeedback();
            UpdateSkillAimPreview();
            CheckStageClear();
        }

        private static bool ControllerAttackDown()
        {
            return Input.GetKeyDown(KeyCode.JoystickButton2);
        }

        private static bool ControllerAttackHeld()
        {
            return Input.GetKey(KeyCode.JoystickButton2);
        }

        private static bool ControllerJumpDown()
        {
            return Input.GetKeyDown(KeyCode.JoystickButton0);
