        }

        private void OnApplicationPause(bool pauseStatus)
        {
            if (pauseStatus) ApplyLifecyclePause();
            else lifecyclePauseApplied = false;
        }

        private void OnApplicationFocus(bool hasFocus)
        {
            if (!hasFocus) ApplyLifecyclePause();
        }

        private void ApplyLifecyclePause()
        {
            if (lifecyclePauseApplied) return;
            lifecyclePauseApplied = true;
            SaveSettings();
            PlayerPrefs.Save();
            touchAttackHeld = false;
            touchMoveActive = false;
            ResetJoystickIntentLock();
            ResetQuickRunIntent();
            ClearAutoAimTargetCue();
            HideSkillAimPreview();
            attackBufferTimer = 0f;
            jumpBufferTimer = 0f;
            dodgeBufferTimer = 0f;
            ClearSkillBuffers();
            ClearPlatformDropThrough();
            groundedGraceTimer = 0f;
            movementStuckTimer = 0f;
            lastMovementFrameX = player ? player.transform.position.x : 0f;
            jumpAxisHeldLastFrame = false;
            jumpHeldLastFrame = false;
            touchJumpHeld = false;
            jumpCutApplied = false;
            if (titleActive || (victoryPanel && victoryPanel.gameObject.activeSelf) || (settingsPanel && settingsPanel.gameObject.activeSelf) || (achievementPanel && achievementPanel.gameObject.activeSelf) || (runeCodexPanel && runeCodexPanel.gameObject.activeSelf) || (aboutPanel && aboutPanel.gameObject.activeSelf) || (shopPanel && shopPanel.gameObject.activeSelf))
            {
                inputLocked = true;
                Time.timeScale = ModalWantsTimeFreeze() ? 0f : Time.timeScale;
                return;
            }
            if (!pausePanel) return;
            paused = true;
            pausePanel.gameObject.SetActive(true);
            SetPauseReason("应用恢复：战斗已冻结，触控输入已清空");
            inputLocked = true;
            Time.timeScale = 0f;
            noticeText.text = "应用已暂停：返回后点继续战斗";
        }

        private void SliceGeneratedSheets()
        {
            heroSprites = SliceHeroSheet(heroSheet, 220);
            heroFrameVisibility.Clear();
            lastVisibleHeroFrame = 0;
            enemySprites = SliceTrimmed(ChromaKeyGeneratedBackdrop(enemySheet), 6, 4, 220, true);
            uiSprites = Slice(uiSheet, 5, 3, 100);
            platformSprites = SliceTrimmed(ChromaKeyGeneratedBackdrop(platformSheet), 4, 1, 180, true);
            groundWallSprite = CreateGroundWallSprite(groundWallTexture, 180);
            foregroundPropSprites = SliceTrimmed(foregroundPropsSheet, 6, 1, 180);
            foregroundGrassSprite = CreateTrimmedSprite(ChromaKeyGreen(foregroundGrassTexture), 180);
            airDecorSprites = airDecorSheet ? SliceTrimmed(ChromaKeyGeneratedBackdrop(airDecorSheet), 6, 1, 180) : Array.Empty<Sprite>();
            controlUiSprites = SliceTrimmed(controlUiSheet, 4, 4, 180);
            runeUiSprites = SliceTrimmed(runeUiSheet, 2, 2, 180);
            combatVfxSprites = SliceTrimmed(combatVfxSheet, 3, 3, 180);
            externalQuickSlashSprites = SpritesFromTextures(externalQuickSlashFrames, 220);
            externalSwordArcSprites = SpritesFromTextures(externalSwordArcFrames, 220);
            externalSwordWaveSprites = SpritesFromTextures(externalSwordWaveFrames, 220);
            externalLightningSprites = SpritesFromTextures(externalLightningFrames, 220);
            externalHeavyBurstSprites = SpritesFromTextures(externalHeavyBurstFrames, 220);
            externalRuneEnergySprites = SpritesFromTextures(externalRuneEnergyFrames, 220);
            externalBossImpactSprites = SpritesFromTextures(externalBossImpactFrames, 220);
            companionPetSprites = SliceTrimmed(companionPetSheet, 4, 2, 220);
        }

        private void BuildWorld()
        {
            cam = Camera.main;
            if (!cam)
            {
                var go = new GameObject("Main Camera");
                cam = go.AddComponent<Camera>();
                go.tag = "MainCamera";
            }
            cam.orthographic = true;
            cam.orthographicSize = 6.8f;
            cam.transform.position = new Vector3(-1.5f, 0, -10);
            Color stageSkyColor = new Color(.56f, .80f, .93f, 1f);
            cam.backgroundColor = stageSkyColor;
            if (!FindObjectOfType<AudioListener>()) cam.gameObject.AddComponent<AudioListener>();
            audioSource = cam.GetComponent<AudioSource>();
            if (!audioSource) audioSource = cam.gameObject.AddComponent<AudioSource>();
            audioSource.playOnAwake = false;
            audioSource.spatialBlend = 0f;
            var musicGo = new GameObject("MusicAudioSource");
            musicGo.transform.SetParent(cam.transform, false);
            musicSource = musicGo.AddComponent<AudioSource>();
            musicSource.playOnAwake = false;
            musicSource.loop = true;
            musicSource.spatialBlend = 0f;

            world = new GameObject("AdventureKingStyleWorld").transform;
            enemyRoot = new GameObject("Enemies").transform; enemyRoot.SetParent(world);
            fxRoot = new GameObject("Effects").transform; fxRoot.SetParent(world);
            propRoot = new GameObject("AdventureProps").transform; propRoot.SetParent(world);

            if (stageBackground)
            {
                RectObj("StageSkySeamGuardBackdrop", world, new Vector2(19, .1f), new Vector2(67.2f, 16.2f), stageSkyColor, -11);
                var bg = new GameObject("GeneratedForestStage");
                bg.transform.SetParent(world);
                bg.transform.position = new Vector3(19, .1f, 2);
                var sr = bg.AddComponent<SpriteRenderer>();
                sr.sprite = stageBackground;
                sr.sortingOrder = -10;
                FitSpriteToWorld(sr, 60.5f, 15.4f);
                RectObj("BackgroundDepthUnifierWash", world, new Vector2(19, .1f), new Vector2(66.4f, 15.6f), new Color(.68f, .88f, 1f, .002f), -9);
                BuildBackgroundArtifactMasks();
                BuildAirDecorationLayer();
            }
            else
            {
                RectObj("FallbackSky", world, new Vector2(19, .2f), new Vector2(60, 10), C("#7EC8FF"), -10);
                BuildAirDecorationLayer();
            }

            foregroundReadabilityBand = CircleObj("ForegroundReadabilitySoftEllipse_NoPlate", world, new Vector2(-6.25f, GroundY + .72f), .50f, new Color(.015f, .035f, .045f, 0f), -2);
            foregroundReadabilityBand.transform.localScale = new Vector3(3.2f, .32f, 1f);
            BuildMainSolidGroundFloor();
            BuildForegroundSceneDressing();
            BuildAdventureReferenceForegroundLayer();

            player = new GameObject("Hero_Lightblade");
            player.transform.SetParent(world);
            player.transform.position = new Vector3(-6.25f, GroundY + .72f, 0);
            playerSprite = player.AddComponent<SpriteRenderer>();
            playerSprite.sprite = FirstVisibleHeroSprite();
            playerSprite.sortingOrder = 34;
            ApplyHeroSpriteGroundingOffset();
            var contrast = new GameObject("HeroContrastSilhouette");
            contrast.transform.SetParent(player.transform);
            contrast.transform.localPosition = new Vector3(.006f, -.014f, .04f);
            playerContrastShadow = contrast.AddComponent<SpriteRenderer>();
            playerContrastShadow.sprite = playerSprite.sprite;
            playerContrastShadow.sortingOrder = 20;
            playerContrastShadow.color = Color.clear;
            playerContrastShadow.enabled = false;
            player.transform.localScale = Vector3.one * HeroBaseVisualScale;
            BuildHeroReadableBody();
            RestoreHeroRenderer();
            playerReadabilityAura = CircleObj("HeroReadabilityAura_DisabledNoGroundBlob", player.transform, new Vector2(0, -.38f), .82f, Color.clear, 4);
            playerReadabilityAura.transform.localScale = new Vector3(1.28f, .34f, 1f);
            playerReadabilityAura.SetActive(false);
            heroLandingPredictor = CircleObj("HeroLandingPredictor", world, new Vector2(player.transform.position.x, GroundY + .18f), .48f, Color.clear, 4).GetComponent<SpriteRenderer>();
            heroLandingPredictor.transform.localScale = new Vector3(1.55f, .28f, 1f);
            heroLandingPredictorEdge = RectObj("HeroLandingPredictorEdgeLine", heroLandingPredictor.transform, Vector2.zero, new Vector2(.66f, .030f), Color.clear, 5).GetComponent<SpriteRenderer>();

            companionPet = new GameObject("CompanionSpirit");
            companionPet.transform.SetParent(world);
            companionPet.transform.position = player.transform.position + new Vector3(-1.70f, 1.74f, 0);
            companionSprite = companionPet.AddComponent<SpriteRenderer>();
            companionSprite.sprite = companionPetSprites.Length > 0 ? companionPetSprites[0] : SpriteCache.Circle;
            companionSprite.sortingOrder = 1;
            companionSprite.color = new Color(1f, 1f, 1f, .78f);
            companionPet.transform.localScale = Vector3.one * .46f;

            BuildWorldControlHints();
        }

