            AddAirDecorSprite(root, "AirDecor_PaintedCanopy_Left_NoCollision", 0, new Vector2(-2.10f, GroundY + 14.08f), new Vector2(7.60f, 2.78f), new Color(.78f, .94f, 1f, .24f), -8);
            AddAirDecorSprite(root, "AirDecor_PaintedCanopy_Mid_NoCollision", 0, new Vector2(18.60f, GroundY + 14.16f), new Vector2(6.70f, 2.36f), new Color(.76f, .92f, 1f, .15f), -9);
            AddAirDecorSprite(root, "AirDecor_PaintedCanopy_Right_NoCollision", 5, new Vector2(42.80f, GroundY + 14.06f), new Vector2(7.20f, 2.62f), new Color(.78f, .94f, 1f, .20f), -8);
            AddAirDecorSprite(root, "AirDecor_PaintedRuinArch_Back_NoCollision", 1, new Vector2(13.90f, GroundY + 14.02f), new Vector2(4.64f, 2.22f), new Color(.70f, .92f, 1f, .14f), -9);
            AddAirDecorSprite(root, "AirDecor_PaintedCloudMist_Mid_NoCollision", 2, new Vector2(25.20f, GroundY + 14.08f), new Vector2(7.20f, 2.12f), new Color(.72f, .94f, 1f, .13f), -10);
            AddAirDecorSprite(root, "AirDecor_PaintedCloudMist_Left_NoCollision", 2, new Vector2(7.60f, GroundY + 14.04f), new Vector2(5.90f, 1.76f), new Color(.72f, .94f, 1f, .09f), -10);
            AddAirDecorSprite(root, "AirDecor_PaintedVineCluster_Right_NoCollision", 3, new Vector2(34.20f, GroundY + 14.04f), new Vector2(2.00f, 2.42f), new Color(.72f, .94f, 1f, .15f), -8);
            AddAirDecorSprite(root, "AirDecor_PaintedFloatingStone_Mid_NoCollision", 4, new Vector2(29.60f, GroundY + 14.12f), new Vector2(1.48f, 1.48f), new Color(.74f, .94f, 1f, .18f), -7);
            AddProceduralCloudBank(root, "AirDecor_SoftCloudBank_BackHigh_NoCollision", new Vector2(15.2f, GroundY + 14.16f), 1.12f, .034f, -10);
            AddProceduralCloudBank(root, "AirDecor_SoftCloudBank_RightHigh_NoCollision", new Vector2(36.8f, GroundY + 14.04f), .86f, .028f, -10);
            BuildAdventureAirCanopyComposition(root);
