        private void BuildAdventureAirCanopyComposition(Transform root)
        {
            if (!root) return;

            AddProceduralCanopyCeiling(root, "AirDecor_TreetopCluster_CeilingLeft_NoCollision", new Vector2(2.80f, GroundY + 14.10f), 1.18f, .20f, -7);
            AddProceduralCanopyCeiling(root, "AirDecor_TreetopCluster_CeilingMid_NoCollision", new Vector2(18.70f, GroundY + 14.00f), 1.08f, .16f, -8);
            AddProceduralCanopyCeiling(root, "AirDecor_TreetopCluster_CeilingRight_NoCollision", new Vector2(37.60f, GroundY + 14.08f), 1.20f, .18f, -7);

            AddProceduralUpperCanopyRim(root, "AirDecor_UpperCanopyRim_LeftHigh_NoCollision", new Vector2(-5.60f, GroundY + 13.94f), .92f, .18f, -6);
            AddProceduralUpperCanopyRim(root, "AirDecor_UpperCanopyRim_CenterHigh_NoCollision", new Vector2(20.30f, GroundY + 14.06f), 1.08f, .14f, -8);
            AddProceduralUpperCanopyRim(root, "AirDecor_UpperCanopyRim_RightHigh_NoCollision", new Vector2(44.80f, GroundY + 14.12f), .98f, .17f, -6);

            AddProceduralNearCanopyFrame(root, "AirDecor_NearCanopyFrame_LeftHigh_NoCollision", new Vector2(-6.70f, GroundY + 13.96f), .82f, .12f, -5, false);
            AddProceduralNearCanopyFrame(root, "AirDecor_NearCanopyFrame_RightHigh_NoCollision", new Vector2(46.40f, GroundY + 14.14f), .84f, .12f, -5, true);

            AddProceduralCanopy(root, "AirDecor_TreetopCluster_DepthLeafShelfA_NoCollision", new Vector2(9.40f, GroundY + 14.12f), .78f, .105f, -8);
            AddProceduralCanopy(root, "AirDecor_TreetopCluster_DepthLeafShelfB_NoCollision", new Vector2(30.80f, GroundY + 14.16f), .86f, .115f, -8);
            AddProceduralVineCurtain(root, "AirDecor_VineCurtain_DepthLeft_NoCollision", new Vector2(6.10f, GroundY + 14.08f), 1.10f, .095f, -7);
            AddProceduralVineCurtain(root, "AirDecor_VineCurtain_DepthMid_NoCollision", new Vector2(23.80f, GroundY + 14.16f), 1.22f, .082f, -8);
            AddProceduralVineCurtain(root, "AirDecor_VineCurtain_DepthRight_NoCollision", new Vector2(39.20f, GroundY + 14.18f), 1.06f, .088f, -7);

            AddProceduralBrokenArch(root, "AirDecor_RuinedArchSilhouette_BackHigh_NoCollision", new Vector2(11.90f, GroundY + 14.02f), .50f, .085f, -9);
            AddProceduralBrokenArch(root, "AirDecor_RuinedArchSilhouette_RightHigh_NoCollision", new Vector2(34.90f, GroundY + 14.08f), .46f, .070f, -9);
            BuildAdventureAirCeilingContinuity(root);
        }

        private void BuildAdventureAirCeilingContinuity(Transform root)
        {
            if (!root) return;

            AddProceduralCanopy(root, "AirDecor_CeilingContinuityLeafMass_LeftHigh_NoCollision", new Vector2(6.20f, GroundY + 14.24f), .58f, .060f, -9);
            AddProceduralCanopy(root, "AirDecor_CeilingContinuityLeafMass_MidHigh_NoCollision", new Vector2(23.10f, GroundY + 14.32f), .66f, .054f, -10);
            AddProceduralCanopy(root, "AirDecor_CeilingContinuityLeafMass_RightHigh_NoCollision", new Vector2(39.90f, GroundY + 14.20f), .58f, .058f, -9);
            AddProceduralUpperSkyBranch(root, "AirDecor_CeilingContinuityBranch_LeftHigh_NoCollision", new Vector2(7.80f, GroundY + 14.16f), 1.10f, .048f, -10, false);
            AddProceduralUpperSkyBranch(root, "AirDecor_CeilingContinuityBranch_MidHigh_NoCollision", new Vector2(24.20f, GroundY + 14.28f), 1.28f, .042f, -11, true);
            AddProceduralUpperSkyBranch(root, "AirDecor_CeilingContinuityBranch_RightHigh_NoCollision", new Vector2(40.70f, GroundY + 14.14f), 1.04f, .046f, -10, true);
            AddProceduralBrokenArch(root, "AirDecor_CeilingContinuityRuinTrace_MidHigh_NoCollision", new Vector2(25.90f, GroundY + 14.18f), .34f, .040f, -11);
            AddProceduralFloatingStone(root, "AirDecor_CeilingContinuityTinyStone_LeftHigh_NoCollision", new Vector2(12.20f, GroundY + 14.06f), .42f, .040f, -10);
            AddProceduralFloatingStone(root, "AirDecor_CeilingContinuityTinyStone_RightHigh_NoCollision", new Vector2(35.80f, GroundY + 14.10f), .38f, .038f, -10);
        }

        private void AddProceduralUpperSkyBranch(Transform parent, string name, Vector2 pos, float scale, float alpha, int order, bool flip)
        {
            float dir = flip ? -1f : 1f;
            var limb = RectObj(name + "_SoftLimb_NoCollision", parent, pos, new Vector2(2.30f * scale, .038f * scale), new Color(.080f, .070f, .048f, alpha), order);
            limb.transform.localRotation = Quaternion.Euler(0f, 0f, dir * -7f);
            for (int i = 0; i < 7; i++)
            {
                float t = i / 6f;
                float x = pos.x + dir * Mathf.Lerp(-1.00f, 1.08f, t) * scale;
                float y = pos.y + Mathf.Sin(t * Mathf.PI) * .12f * scale + .055f * scale;
                var leaf = CircleObj(name + "_LeafBreakup_NoCollision_" + i, parent, new Vector2(x, y), .50f, new Color(.19f, .39f, .12f, alpha * .76f), order + 1);
                leaf.transform.localScale = new Vector3((.24f + (i % 3) * .050f) * scale, (.070f + (i % 2) * .018f) * scale, 1f);
                leaf.transform.localRotation = Quaternion.Euler(0f, 0f, dir * (-14f + i * 3.2f));
            }
        }

        private void AddAirDecorSprite(Transform parent, string name, int spriteIndex, Vector2 pos, Vector2 size, Color color, int order)
        {
            if (airDecorSprites == null || spriteIndex < 0 || spriteIndex >= airDecorSprites.Length || !airDecorSprites[spriteIndex]) return;
            var decor = SpriteObj(name, parent, airDecorSprites[spriteIndex], pos, size, color, order);
            decor.transform.localPosition = new Vector3(pos.x, pos.y, .08f);
        }

        private void AddAirDecorBeam(Transform parent, string name, Vector2 pos, Vector2 size, float rotation, float alpha)
        {
            var beam = RectObj(name, parent, pos, size, new Color(.82f, .95f, 1f, alpha), -9);
            beam.transform.localRotation = Quaternion.Euler(0f, 0f, rotation);
        }

        private void AddProceduralCanopy(Transform parent, string name, Vector2 pos, float scale, float alpha, int order)
        {
            for (int i = 0; i < 9; i++)
            {
                float t = i / 8f;
                float x = pos.x + Mathf.Lerp(-1.42f, 1.42f, t) * scale;
                float y = pos.y + Mathf.Sin(t * Mathf.PI) * .34f * scale + ((i % 2 == 0) ? .05f : -.04f) * scale;
                float w = (.72f + (i % 3) * .18f) * scale;
                float h = (.18f + (i % 4) * .035f) * scale;
                var leaf = CircleObj(name + "_SoftLeafEllipse_" + i, parent, new Vector2(x, y), .50f, new Color(.13f, .34f, .10f, alpha * .86f), order);
                leaf.transform.localScale = new Vector3(w, h, 1f);
                leaf.transform.localRotation = Quaternion.Euler(0f, 0f, -12f + i * 3.4f);
                var highlight = CircleObj(name + "_SoftLeafHighlight_" + i, parent, new Vector2(x + .04f * scale, y + h * .18f), .50f, new Color(.54f, .75f, .22f, alpha * .18f), order + 1);
                highlight.transform.localScale = new Vector3(w * .46f, h * .26f, 1f);
            }
            var vine = RectObj(name + "_HangingRoot", parent, new Vector2(pos.x + .62f * scale, pos.y - .46f * scale), new Vector2(.030f * scale, .78f * scale), new Color(.11f, .26f, .075f, alpha * .62f), order + 1);
            vine.transform.localRotation = Quaternion.Euler(0f, 0f, -6f);
        }

        private void AddProceduralCloudBank(Transform parent, string name, Vector2 pos, float scale, float alpha, int order)
        {
            for (int i = 0; i < 7; i++)
            {
                float t = i / 6f;
                float x = pos.x + Mathf.Lerp(-1.85f, 1.85f, t) * scale;
                float y = pos.y + Mathf.Sin(t * Mathf.PI) * .18f * scale + ((i % 2 == 0) ? .035f : -.025f) * scale;
                float w = (.86f + (i % 3) * .22f) * scale;
                float h = (.20f + (i % 2) * .055f) * scale;
                var soft = CircleObj(name + "_SoftEllipse_" + i, parent, new Vector2(x, y), .50f, new Color(.72f, .90f, 1f, alpha), order);
                soft.transform.localScale = new Vector3(w, h, 1f);

                var shade = CircleObj(name + "_SoftEllipseShade_" + i, parent, new Vector2(x + .05f * scale, y - h * .22f), .50f, new Color(.42f, .66f, .80f, alpha * .22f), order + 1);
                shade.transform.localScale = new Vector3(w * .58f, h * .26f, 1f);
            }
        }

        private void AddProceduralCanopyCeiling(Transform parent, string name, Vector2 pos, float scale, float alpha, int order)
        {
            for (int i = 0; i < 14; i++)
            {
                float t = i / 13f;
                float x = pos.x + Mathf.Lerp(-2.30f, 2.30f, t) * scale;
                float y = pos.y + Mathf.Sin(t * Mathf.PI * 1.25f) * .18f * scale - (i % 3) * .035f * scale;
                float w = (.54f + (i % 4) * .13f) * scale;
                float h = (.13f + (i % 3) * .028f) * scale;
                Color body = i % 4 == 0
                    ? new Color(.34f, .52f, .16f, alpha * .52f)
                    : new Color(.12f, .31f, .10f, alpha * .74f);
                var leaf = CircleObj(name + "_SoftLeafEllipse_" + i, parent, new Vector2(x, y), .50f, body, order);
                leaf.transform.localScale = new Vector3(w, h, 1f);
                leaf.transform.localRotation = Quaternion.Euler(0f, 0f, -18f + i * 2.7f);

                if (i % 3 == 1)
                {
                    var glint = CircleObj(name + "_SkyRimLeafHighlight_" + i, parent, new Vector2(x - .05f * scale, y + h * .16f), .50f, new Color(.62f, .78f, .25f, alpha * .10f), order + 1);
                    glint.transform.localScale = new Vector3(w * .42f, h * .22f, 1f);
                }
            }

            for (int i = 0; i < 4; i++)
            {
                float x = pos.x + (i - 1.5f) * .78f * scale;
                var shadowLeaf = CircleObj(name + "_SoftLeafShadow_" + i, parent, new Vector2(x, pos.y - .19f * scale - (i % 2) * .035f * scale), .50f, new Color(.10f, .24f, .09f, alpha * .075f), order);
                shadowLeaf.transform.localScale = new Vector3(.34f * scale, .075f * scale, 1f);
                shadowLeaf.transform.localRotation = Quaternion.Euler(0f, 0f, -6f + i * 3f);
            }
        }

        private void AddProceduralUpperCanopyRim(Transform parent, string name, Vector2 pos, float scale, float alpha, int order)
        {
            for (int i = 0; i < 16; i++)
            {
                float t = i / 15f;
                float x = pos.x + Mathf.Lerp(-2.75f, 2.75f, t) * scale;
                float y = pos.y - Mathf.Abs(Mathf.Sin(t * Mathf.PI * 1.1f)) * .22f * scale - (i % 2) * .035f * scale;
                float w = (.52f + (i % 5) * .12f) * scale;
                float h = (.15f + (i % 4) * .034f) * scale;
                Color body = i % 5 == 0
                    ? new Color(.48f, .66f, .20f, alpha * .38f)
                    : new Color(.095f, .25f, .085f, alpha * .80f);
                var leaf = CircleObj(name + "_SoftLeafEllipse_" + i, parent, new Vector2(x, y), .50f, body, order);
                leaf.transform.localScale = new Vector3(w, h, 1f);
                leaf.transform.localRotation = Quaternion.Euler(0f, 0f, -16f + i * 2.2f);
            }

            for (int i = 0; i < 6; i++)
            {
                float x = pos.x + (i - 2.5f) * .82f * scale;
                float length = (.34f + (i % 3) * .15f) * scale;
                var vine = RectObj(name + "_ScreenTopVine_NoCollision_" + i, parent, new Vector2(x, pos.y - .18f * scale - length * .50f), new Vector2(.024f * scale, length), new Color(.085f, .23f, .065f, alpha * .80f), order + 1);
                vine.transform.localRotation = Quaternion.Euler(0f, 0f, -7f + i * 2.8f);
                if (i % 2 == 0)
                {
                    var leaf = CircleObj(name + "_VineLeafEllipse_" + i, parent, new Vector2(x + .045f * scale, pos.y - .34f * scale - length * .35f), .50f, new Color(.30f, .52f, .14f, alpha * .46f), order + 2);
                    leaf.transform.localScale = new Vector3(.12f * scale, .045f * scale, 1f);
                    leaf.transform.localRotation = Quaternion.Euler(0f, 0f, 24f);
                }
            }
        }

        private void AddProceduralNearCanopyFrame(Transform parent, string name, Vector2 pos, float scale, float alpha, int order, bool flip)
        {
            float dir = flip ? -1f : 1f;
            for (int i = 0; i < 6; i++)
            {
                float t = i / 5f;
                float x = pos.x + dir * Mathf.Lerp(-1.48f, 1.64f, t) * scale;
                float y = pos.y + Mathf.Sin(t * Mathf.PI) * .16f * scale - (i % 2) * .025f * scale;
                var branch = RectObj(name + "_ReadableBranch_NoCollision_" + i, parent, new Vector2(x, y), new Vector2((.62f - i * .035f) * scale, .040f * scale), new Color(.085f, .070f, .045f, alpha * .48f), order);
                branch.transform.localRotation = Quaternion.Euler(0f, 0f, dir * (-8f + i * 3.8f));
            }

            for (int i = 0; i < 18; i++)
            {
                float t = i / 17f;
                float x = pos.x + dir * Mathf.Lerp(-1.86f, 1.86f, t) * scale;
                float y = pos.y + .10f * scale + Mathf.Sin(t * Mathf.PI * 1.6f) * .20f * scale - (i % 3) * .030f * scale;
                float w = (.32f + (i % 5) * .055f) * scale;
                float h = (.095f + (i % 4) * .020f) * scale;
                Color c = i % 4 == 0
                    ? new Color(.50f, .68f, .20f, alpha * .48f)
                    : new Color(.12f, .33f, .095f, alpha * .76f);
                var leaf = CircleObj(name + "_SoftLeafEllipse_" + i, parent, new Vector2(x, y), .50f, c, order + 1);
                leaf.transform.localScale = new Vector3(w, h, 1f);
                leaf.transform.localRotation = Quaternion.Euler(0f, 0f, dir * (-20f + i * 2.4f));
            }

            for (int i = 0; i < 4; i++)
            {
                float x = pos.x + dir * (-.88f + i * .62f) * scale;
                float length = (.50f + (i % 3) * .16f) * scale;
                var vine = RectObj(name + "_ReadableVine_NoCollision_" + i, parent, new Vector2(x, pos.y - .14f * scale - length * .50f), new Vector2(.022f * scale, length), new Color(.070f, .22f, .060f, alpha * .74f), order + 2);
                vine.transform.localRotation = Quaternion.Euler(0f, 0f, dir * (-8f + i * 4f));
            }
        }

        private void AddProceduralDistantBridge(Transform parent, string name, Vector2 pos, float scale, float alpha, int order)
        {
            float softAlpha = alpha * .030f;
            RectObj(name + "_BackSpan_NoCollision", parent, pos, new Vector2(2.10f * scale, .026f * scale), new Color(.32f, .40f, .32f, softAlpha * .22f), order);
            RectObj(name + "_MossTop_NoCollision", parent, pos + new Vector2(0f, .040f * scale), new Vector2(1.86f * scale, .018f * scale), new Color(.28f, .48f, .18f, softAlpha * .28f), order + 1);
            for (int i = 0; i < 5; i++)
            {
                float t = i / 4f;
                float x = pos.x + Mathf.Lerp(-1.05f, 1.05f, t) * scale;
                float y = pos.y + Mathf.Sin(t * Mathf.PI) * .040f * scale;
                var leafMass = CircleObj(name + "_SoftLeafMass_NoCollision_" + i, parent, new Vector2(x, y), .50f, new Color(.22f, .42f, .18f, softAlpha), order + 1);
                leafMass.transform.localScale = new Vector3((.34f + (i % 2) * .10f) * scale, (.070f + (i % 3) * .010f) * scale, 1f);
            }
        }

        private void AddProceduralVineCurtain(Transform parent, string name, Vector2 pos, float height, float alpha, int order)
        {
            float softAlpha = alpha * .24f;
            for (int i = 0; i < 6; i++)
            {
                float x = pos.x + (i - 2.5f) * (.12f + (i % 2) * .035f);
                float h = height * (.48f + (i % 4) * .105f);
                var vine = RectObj(name + "_Vine_" + i, parent, new Vector2(x, pos.y - h * .5f), new Vector2(.012f, h), new Color(.08f, .20f, .070f, softAlpha), order);
                vine.transform.localRotation = Quaternion.Euler(0f, 0f, -13f + i * 4.8f);
                for (int j = 0; j < 3; j++)
                {
                    float side = j % 2 == 0 ? 1f : -1f;
                    var leaf = RectObj(name + "_Leaf_" + i + "_" + j, parent, new Vector2(x + side * .050f, pos.y - h * (.22f + j * .20f)), new Vector2(.070f, .020f), new Color(.33f, .56f, .16f, softAlpha * .58f), order + 1);
                    leaf.transform.localRotation = Quaternion.Euler(0f, 0f, side * (24f + j * 5f));
                }
            }
        }

        private void AddProceduralUpperBranch(Transform parent, string name, Vector2 pos, float scale, float alpha, int order, bool flip)
        {
            float dir = flip ? -1f : 1f;
            float softAlpha = alpha * .24f;
            for (int i = 0; i < 5; i++)
            {
                float t = i / 4f;
                float x = pos.x + dir * Mathf.Lerp(-.92f, 1.18f, t) * scale;
                float y = pos.y + (.04f + Mathf.Sin(t * Mathf.PI * 1.15f) * .12f) * scale;
                float w = (.46f + (i % 2) * .10f) * scale;
                float h = (.16f + (i % 3) * .026f) * scale;
                Color c = i % 2 == 0 ? new Color(.34f, .53f, .18f, softAlpha * .72f) : new Color(.18f, .38f, .12f, softAlpha);
                var leaf = CircleObj(name + "_SoftLeafEllipse_" + i, parent, new Vector2(x, y), .50f, c, order + 1);
                leaf.transform.localScale = new Vector3(w, h, 1f);
                leaf.transform.localRotation = Quaternion.Euler(0f, 0f, dir * (-8f + i * 3f));
            }
        }

        private void AddProceduralBrokenArch(Transform parent, string name, Vector2 pos, float scale, float alpha, int order)
        {
            float softAlpha = alpha * .16f;
            var left = RectObj(name + "_LeftPillar", parent, new Vector2(pos.x - .44f * scale, pos.y), new Vector2(.18f * scale, 1.22f * scale), new Color(.36f, .38f, .31f, softAlpha), order);
            left.transform.localRotation = Quaternion.Euler(0f, 0f, 2f);
            var right = RectObj(name + "_RightPillar", parent, new Vector2(pos.x + .50f * scale, pos.y - .08f * scale), new Vector2(.17f * scale, .98f * scale), new Color(.31f, .34f, .29f, softAlpha * .88f), order);
            right.transform.localRotation = Quaternion.Euler(0f, 0f, -4f);
            for (int i = 0; i < 5; i++)
            {
                float t = i / 4f;
                float x = pos.x + Mathf.Lerp(-.44f, .48f, t) * scale;
                float y = pos.y + (.60f + Mathf.Sin(t * Mathf.PI) * .34f) * scale;
                var cap = RectObj(name + "_ArchStone_" + i, parent, new Vector2(x, y), new Vector2(.30f * scale, .16f * scale), new Color(.43f, .44f, .34f, softAlpha), order + 1);
                cap.transform.localRotation = Quaternion.Euler(0f, 0f, -18f + i * 9f);
                RectObj(name + "_Moss_" + i, parent, new Vector2(x, y + .09f * scale), new Vector2(.22f * scale, .035f * scale), new Color(.25f, .42f, .12f, softAlpha * .82f), order + 2);
            }
        }

        private void AddProceduralFloatingStone(Transform parent, string name, Vector2 pos, float scale, float alpha, int order)
        {
            float softAlpha = alpha * .18f;
            for (int i = 0; i < 5; i++)
            {
                float x = pos.x + (i - 2) * .18f * scale;
                float y = pos.y + ((i % 2 == 0) ? .05f : -.04f) * scale;
                var stone = RectObj(name + "_Stone_" + i, parent, new Vector2(x, y), new Vector2((.34f - i * .018f) * scale, (.12f + (i % 2) * .035f) * scale), new Color(.33f, .32f, .24f, softAlpha), order);
                stone.transform.localRotation = Quaternion.Euler(0f, 0f, -7f + i * 3.5f);
                RectObj(name + "_Moss_" + i, parent, new Vector2(x, y + .075f * scale), new Vector2(.24f * scale, .026f * scale), new Color(.30f, .50f, .14f, softAlpha * .86f), order + 1);
            }
            RectObj(name + "_SoftAo", parent, new Vector2(pos.x, pos.y - .12f * scale), new Vector2(.96f * scale, .030f * scale), new Color(.04f, .07f, .05f, softAlpha * .24f), order - 1);
        }

        private void AddProceduralLeafDrift(Transform parent, string name, Vector2 pos, float scale, float alpha, int order)
        {
            float softAlpha = alpha * .28f;
            for (int i = 0; i < 12; i++)
            {
                float t = i / 11f;
                float x = pos.x + Mathf.Lerp(-1.12f, 1.12f, t) * scale;
                float y = pos.y + Mathf.Sin(t * Mathf.PI * 2.1f) * .22f * scale;
                Color c = i % 3 == 0 ? new Color(.72f, .68f, .25f, softAlpha * .70f) : new Color(.36f, .62f, .18f, softAlpha);
                var leaf = RectObj(name + "_Leaf_" + i, parent, new Vector2(x, y), new Vector2(.090f * scale, .024f * scale), c, order);
                leaf.transform.localRotation = Quaternion.Euler(0f, 0f, -24f + i * 8f);
            }
        }

