        private void BuildMainGroundAdventureCrossSection()
        {
            if (!world) return;

            RectObj("AdventureMainGroundCartoonTopGrassCrown_NoCollision", world, new Vector2(19f, GroundY + .555f), new Vector2(62.8f, .082f), new Color(.40f, .66f, .16f, .40f), 14);
            RectObj("AdventureMainGroundCartoonBrightGrassLip_NoCollision", world, new Vector2(19f, GroundY + .615f), new Vector2(61.8f, .024f), new Color(.76f, .88f, .34f, .16f), 15);
            RectObj("AdventureMainGroundCartoonRootDarkRim_NoCollision", world, new Vector2(19f, GroundY + .330f), new Vector2(62.8f, .052f), new Color(.060f, .14f, .045f, .24f), 9);
            RectObj("AdventureMainGroundCartoonSolidSoilFace_NoCollision", world, new Vector2(19f, GroundY - .62f), new Vector2(62.8f, 1.52f), new Color(.18f, .145f, .095f, .34f), 6);
            RectObj("AdventureMainGroundCartoonStoneBelly_NoCollision", world, new Vector2(19f, GroundY - 1.20f), new Vector2(62.8f, .58f), new Color(.095f, .086f, .066f, .30f), 5);
            RectObj("AdventureMainGroundCartoonBottomOccluder_NoBackgroundLeak", world, new Vector2(19f, GroundY - 2.20f), new Vector2(63.2f, .72f), new Color(.055f, .050f, .040f, .78f), 5);

            const int columns = 30;
            for (int i = 0; i < columns; i++)
            {
                float t = (i + .5f) / columns;
                float x = Mathf.Lerp(-10.8f, 48.8f, t);
                float rowOffset = (i % 4 - 1.5f) * .075f;
                float y = GroundY - .48f + rowOffset;
                float w = .86f + (i % 3) * .18f;
                RectObj("AdventureMainGroundRoundedStoneBlock_NoCollision_" + i, world, new Vector2(x, y), new Vector2(w, .118f), new Color(.38f, .36f, .27f, .32f), 8);
                RectObj("AdventureMainGroundStoneMossCrevice_NoCollision_" + i, world, new Vector2(x - w * .12f, y + .072f), new Vector2(w * .54f, .018f), new Color(.25f, .45f, .12f, .16f), 9);
                if (i % 2 == 0)
                {
                    float deepY = GroundY - 1.06f + (i % 5 - 2f) * .050f;
                    RectObj("AdventureMainGroundDeepStonePocket_NoCollision_" + i, world, new Vector2(x + .32f, deepY), new Vector2(w * .72f, .086f), new Color(.18f, .165f, .12f, .24f), 7);
                }
            }

            for (int i = 0; i < 34; i++)
            {
                float t = i / 33f;
                float x = Mathf.Lerp(-10.5f, 48.5f, t);
                float h = .12f + (i % 5) * .032f;
                var blade = RectObj("AdventureMainGroundFrontGrassBlade_NoCollision_" + i, world, new Vector2(x, GroundY + .505f + h * .42f), new Vector2(.026f + (i % 2) * .012f, h), new Color(.18f, .40f, .080f, .34f), 15);
                blade.transform.localRotation = Quaternion.Euler(0f, 0f, -8f + i * 1.2f);
                if (i % 3 == 0)
                    RectObj("AdventureMainGroundFrontFlowerDot_NoCollision_" + i, world, new Vector2(x + .12f, GroundY + .62f + h * .24f), new Vector2(.045f, .022f), new Color(.90f, .56f, .70f, .14f), 16);
            }

            for (int i = 0; i < 16; i++)
            {
                float x = Mathf.Lerp(-9.6f, 47.6f, (i + .5f) / 16f);
                float length = .22f + (i % 4) * .070f;
                RectObj("AdventureMainGroundHangingRootThread_NoCollision_" + i, world, new Vector2(x, GroundY + .22f - length * .50f), new Vector2(.018f, length), new Color(.11f, .30f, .065f, .20f), 10).transform.localRotation = Quaternion.Euler(0f, 0f, -7f + i * 2f);
            }
        }

