        private void AddForegroundProp(string name, int spriteIndex, Vector2 pos, Vector2 size, int order, float alpha)
        {
            if (spriteIndex < 0 || foregroundPropSprites == null || spriteIndex >= foregroundPropSprites.Length || !foregroundPropSprites[spriteIndex]) return;
            var prop = SpriteObj(name, propRoot, foregroundPropSprites[spriteIndex], pos, size, new Color(.92f, 1f, .86f, Mathf.Clamp(alpha, .12f, .52f)), order);
            prop.transform.localPosition = new Vector3(pos.x, pos.y, .02f);
        }

        private void BuildAdventureReferenceForegroundLayer()
        {
            Transform parent = propRoot ? propRoot : world;
            if (foregroundGrassSprite)
            {
                BuildGeneratedForegroundGrassStrip(parent);
                return;
            }

            RectObj("AdventureReferenceGroundRootShade", parent, new Vector2(19f, GroundY + .20f), new Vector2(62.4f, .055f), new Color(.035f, .080f, .035f, .13f), 10);
            RectObj("AdventureReferenceFrontGrassBase", parent, new Vector2(19f, GroundY + .34f), new Vector2(62.4f, .090f), new Color(.14f, .30f, .075f, .20f), 10);
            RectObj("AdventureReferenceFrontGrassHighlight", parent, new Vector2(19f, GroundY + .45f), new Vector2(62.4f, .030f), new Color(.43f, .66f, .16f, .12f), 11);

            for (int i = 0; i < 64; i++)
            {
                float x = -10.05f + i * .94f;
                float height = .18f + (i % 5) * .045f;
                float width = .018f + (i % 3) * .008f;
                float lean = (i % 4 - 1.5f) * 5.5f;
                var blade = RectObj("AdventureReferenceFrontGrassBlade_" + i, parent, new Vector2(x, GroundY + .31f + height * .48f), new Vector2(width, height), new Color(.16f, .36f, .08f, .30f), 12);
                blade.transform.localRotation = Quaternion.Euler(0f, 0f, lean);
                if (i % 8 == 0)
                {
                    var reed = RectObj("AdventureReferenceTallReed_" + i, parent, new Vector2(x + .18f, GroundY + .34f + height * .54f), new Vector2(.016f, height * 1.05f), new Color(.32f, .40f, .12f, .20f), 12);
                    reed.transform.localRotation = Quaternion.Euler(0f, 0f, -lean * .55f);
                }
            }
        }

        private void BuildGeneratedForegroundGrassStrip(Transform parent)
        {
            RectObj("AdventureReferenceGroundRootShade", parent, new Vector2(19f, GroundY + .20f), new Vector2(62.4f, .044f), new Color(.035f, .080f, .035f, .075f), 5);
            const float tileWidth = 13.15f;
            const float tileHeight = 1.34f;
            const float step = 12.92f;
            const float startX = -9.25f;
            for (int i = 0; i < 6; i++)
            {
                float x = startX + i * step;
                var tile = SpriteObj("AdventureGeneratedForegroundGrassStrip_" + i, parent, foregroundGrassSprite, new Vector2(x, GroundY + .52f), new Vector2(tileWidth, tileHeight), new Color(1f, 1f, 1f, .66f), 6);
                if (i % 2 == 1)
                    tile.transform.localScale = new Vector3(-Mathf.Abs(tile.transform.localScale.x), tile.transform.localScale.y, tile.transform.localScale.z);
            }
            RectObj("AdventureGeneratedForegroundGrassContactShade", parent, new Vector2(19f, GroundY + .40f), new Vector2(62.4f, .038f), new Color(.020f, .055f, .026f, .070f), 5);
        }

        private void BuildHeroReadableBody()
        {
            heroReadableBodyParts.Clear();
