            AddHeroReadablePart(RectObj("HeroReadableCape", player.transform, new Vector2(-.20f, -.04f), new Vector2(.54f, .92f), C("#1E63C8"), 19), .20f, false);
            AddHeroReadablePart(RectObj("HeroReadableTorso", player.transform, new Vector2(.03f, -.05f), new Vector2(.46f, .72f), C("#DCEBFF"), 19), .18f, false);
            AddHeroReadablePart(CircleObj("HeroReadableHead", player.transform, new Vector2(.05f, .52f), .27f, C("#F4FBFF"), 19), .18f, false);
            AddHeroReadablePart(RectObj("HeroReadableHair", player.transform, new Vector2(.00f, .69f), new Vector2(.52f, .18f), C("#FFFFFF"), 19), .16f, false);
            AddHeroReadablePart(RectObj("HeroReadableFaceBand", player.transform, new Vector2(.10f, .47f), new Vector2(.25f, .075f), C("#266CBB"), 19), .18f, false);
            AddHeroReadablePart(RectObj("HeroReadableLegL", player.transform, new Vector2(-.10f, -.55f), new Vector2(.17f, .44f), C("#23324A"), 19), .20f, false);
            AddHeroReadablePart(RectObj("HeroReadableLegR", player.transform, new Vector2(.17f, -.55f), new Vector2(.17f, .44f), C("#23324A"), 19), .20f, false);

            var sword = RectObj("HeroReadableBlade", player.transform, new Vector2(.46f, -.22f), new Vector2(.12f, 1.05f), C("#A7F8FF"), 19);
            sword.transform.localRotation = Quaternion.Euler(0f, 0f, -42f);
            AddHeroReadablePart(sword, 1f, false);
        }

        private void AddHeroReadablePart(GameObject part, float alpha, bool scaleWithSprite)
        {
            if (!part) return;
            part.transform.localScale = scaleWithSprite ? part.transform.localScale : new Vector3(part.transform.localScale.x / HeroBaseVisualScale, part.transform.localScale.y / HeroBaseVisualScale, 1f);
            var sr = part.GetComponent<SpriteRenderer>();
            if (!sr) return;
            var color = sr.color;
            color.a = alpha;
            sr.color = color;
            heroReadableBodyParts.Add(sr);
        }

        private void SyncHeroReadableBody()
        {
            if (heroReadableBodyParts.Count == 0) return;
            foreach (var sr in heroReadableBodyParts)
            {
                if (!sr) continue;
                sr.enabled = true;
                var color = sr.color;
                bool spriteLooksValid = playerSprite && playerSprite.sprite && playerSprite.color.a > .35f;
                bool contactAo = sr.gameObject.name == "HeroReadableContactAo_DisabledNoGroundBlob";
                color.a = spriteLooksValid ? (contactAo ? .10f : 0f) : Mathf.Max(color.a, .92f);
                if (contactAo) color.a = 0f;
                sr.color = color;
            }
        }

