        private static AudioClip MakeAmbientLoop(string name, float duration)
        {
            const int sampleRate = 22050;
            int samples = Mathf.Max(1, Mathf.CeilToInt(sampleRate * duration));
            var data = new float[samples];
            for (int i = 0; i < samples; i++)
            {
                float t = i / (float)sampleRate;
                float loopT = i / (float)samples;
                float fade = Mathf.Sin(loopT * Mathf.PI);
                float pad = Mathf.Sin(2f * Mathf.PI * 110f * t) * .10f
                    + Mathf.Sin(2f * Mathf.PI * 165f * t) * .055f
                    + Mathf.Sin(2f * Mathf.PI * 220f * t) * .035f;
                float shimmer = Mathf.Sin(2f * Mathf.PI * (330f + Mathf.Sin(t * .31f) * 8f) * t) * .018f;
                data[i] = (pad + shimmer) * fade;
            }
            var clip = AudioClip.Create(name, samples, 1, sampleRate, false);
            clip.SetData(data, 0);
            return clip;
        }

        private static AudioClip MakeTone(string name, float frequency, float duration, float volume, float sweep)
        {
            const int sampleRate = 22050;
            int samples = Mathf.Max(1, Mathf.CeilToInt(sampleRate * duration));
            var data = new float[samples];
            float phase = 0f;
            for (int i = 0; i < samples; i++)
            {
                float t = i / (float)samples;
                float hz = Mathf.Max(40f, frequency + sweep * t);
                phase += hz * Mathf.PI * 2f / sampleRate;
                float envelope = Mathf.Sin(Mathf.PI * t) * (1f - t * .35f);
                data[i] = Mathf.Sin(phase) * volume * envelope;
            }
            var clip = AudioClip.Create(name, samples, 1, sampleRate, false);
            clip.SetData(data, 0);
            return clip;
        }

        private static AudioClip MakeLayeredTone(string name, float frequency, float duration, float volume, float sweep, float harmonic, float noise)
        {
            const int sampleRate = 22050;
            int samples = Mathf.Max(1, Mathf.CeilToInt(sampleRate * duration));
            var data = new float[samples];
            float phase = 0f;
            float phase2 = 0f;
            uint seed = 2166136261u;
            for (int i = 0; i < samples; i++)
            {
                float t = i / (float)samples;
                float hz = Mathf.Max(40f, frequency + sweep * t);
                phase += hz * Mathf.PI * 2f / sampleRate;
                phase2 += hz * 1.9f * Mathf.PI * 2f / sampleRate;
                seed = seed * 16777619u + 97u;
                float noiseSample = (((seed >> 9) & 1023u) / 511.5f - 1f) * noise * Mathf.Pow(1f - t, 2.4f);
                float attack = Mathf.Clamp01(t / .08f);
                float release = Mathf.Pow(1f - t, 1.15f);
                float envelope = attack * release;
                float tone = Mathf.Sin(phase) + Mathf.Sin(phase2) * harmonic;
                data[i] = Mathf.Clamp((tone * volume * envelope) + noiseSample * volume, -1f, 1f);
            }
            var clip = AudioClip.Create(name, samples, 1, sampleRate, false);
            clip.SetData(data, 0);
            return clip;
        }

        private void BuildPlatforms()
        {
            BuildStageMapLayout(1);
        }

        private void BuildStageMapLayout(int stage)
        {
            ResetMapLayoutRoot();
            int layout = StageMapLayoutIndex(stage);
            BuildStageMapLayoutByIndex(layout);
        }

        private void BuildStageMapLayoutByIndex(int layout)
        {
            activeMapLayoutIndex = layout;
            if (layout >= 0 && layout < runMapLayoutsSeen.Length) runMapLayoutsSeen[layout] = true;
            WorldText("MapVariantLabel", mapLayoutRoot, MapLayoutName(layout), new Vector2(-6.3f, GroundY + 3.05f), 20, 14).color = C("#B9F7FF");
            switch (layout)
            {
                case 1:
                    BuildMapLayout_CanopyClimb();
                    break;
                case 2:
                    BuildMapLayout_BrokenBridge();
                    break;
                case 3:
                    BuildMapLayout_RuneRidge();
                    break;
                default:
                    BuildMapLayout_ForestApproach();
                    break;
            }
            BuildPlatformRouteBreadcrumbs();
            BuildAdventureRouteDressing(layout);
            BuildLayoutThemeDressing(layout);
            BuildRoomRouteReadabilityAnchors(layout);
            for (int i = 0; i < SegmentRights.Length - 1; i++)
                AddProgressGate("RuneProgressGate_" + (char)('A' + i), SegmentRights[i] + .18f);
            BuildRoomMarkers();
            SpriteObj("StageExitGate", mapLayoutRoot, RuneUiSprite(0), new Vector2(46.55f, GroundY + 1.35f), new Vector2(.82f, .82f), new Color(.75f, .96f, 1f, .34f), 2);
            var exitLabel = WorldText("StageExitLabel", mapLayoutRoot, "出口", new Vector2(46.55f, GroundY + 2.05f), 20, 12);
            exitLabel.color = new Color(.82f, .96f, 1f, .48f);
            BuildBossArenaLockdown();
            UpdatePlatformRouteHint();
        }

        private void ResetMapLayoutRoot()
        {
            platforms.Clear();
            platformVisuals.Clear();
            progressGates.Clear();
            roomMarkerLabels.Clear();
            roomMarkerIcons.Clear();
            roomGates.Clear();
            bossArenaLockdownRoot = null;
            bossArenaLeftLockWall = null;
            bossArenaRightLockWall = null;
            bossArenaGroundSeal = null;
            if (mapLayoutRoot)
            {
                if (Application.isPlaying) Destroy(mapLayoutRoot.gameObject);
                else DestroyImmediate(mapLayoutRoot.gameObject);
            }
            mapLayoutRoot = new GameObject("GeneratedMapLayout").transform;
            mapLayoutRoot.SetParent(world);
            mapLayoutRoot.localPosition = Vector3.zero;
        }

        private int StageMapLayoutIndex(int stage)
        {
            int seed = currentRunSeed == 0 ? 20260730 : currentRunSeed;
            return Mathf.Abs(seed + stage * 37) % 4;
        }

        private string MapLayoutName(int layout)
        {
            switch (layout)
            {
                case 1: return "地图：树冠阶梯";
                case 2: return "地图：断桥跳点";
                case 3: return "地图：符文高脊";
                default: return "地图：森林推进";
            }
        }

        private string MapLayoutShortName()
        {
            switch (activeMapLayoutIndex)
            {
                case 1: return "树冠阶梯";
                case 2: return "断桥跳点";
                case 3: return "符文高脊";
                default: return "森林推进";
            }
        }

        private string MapLayoutGoalLine()
        {
            switch (activeMapLayoutIndex)
            {
                case 1: return "路线目标：上推跳跃，攻击开箱；技能弹也能远距离开箱";
                case 2: return "路线目标：短跳过断桥，优先清弓手再开 SLOT";
                case 3: return "路线目标：沿高脊抢奖励小宝箱，保留闪避处理回落压力";
                default: return "路线目标：向右推进，踩平台开箱积攒 SLOT";
            }
        }

        private string MapLayoutRunReview()
        {
            string route = MapLayoutShortName();
            if (activeMapLayoutIndex == 1)
                return $"路线复盘：{route}  高低差较多，跳跃和技能开箱决定启封速度";
            if (activeMapLayoutIndex == 2)
                return $"路线复盘：{route}  断点多，稳定落脚和远程敌处理是主要风险";
            if (activeMapLayoutIndex == 3)
                return $"路线复盘：{route}  奖励小宝箱更偏高位，闪避回收和路线选择影响构筑成型";
            return $"路线复盘：{route}  基础推进路线，适合验证战斗到 SLOT 的节奏";
        }

