            AddProceduralFenceRun(parent, "RouteDressing_StartFence_NoCollision", new Vector2(-5.70f, GroundY + .78f), 3, .78f, .46f);
            AddProceduralMushroomPatch(parent, "RouteDressing_StartMushrooms_NoCollision", new Vector2(-4.02f, GroundY + .57f), .72f, .62f);
            AddProceduralFlowerPatch(parent, "RouteDressing_StartFlowers_NoCollision", new Vector2(-1.28f, GroundY + .58f), 1.10f, .42f);

            AddProceduralFenceRun(parent, "RouteDressing_MidFence_NoCollision", new Vector2(14.85f, GroundY + .78f), 4, .86f, .34f);
