        private void BuildAdventureRouteFootlineMemoryLayer(Transform parent, int layout)
        {
            if (!parent) return;
            AddAdventureFootlineGrassRhythm(parent, "AdventureRouteMemory_UniversalGrassRhythm_NoCollision", new float[] { -6.20f, 2.40f, 11.60f, 20.80f, 31.30f, 43.60f }, .92f, .070f);

            switch (layout)
            {
                case 1:
                    AddAdventureRootToeRhythm(parent, "AdventureRouteMemory_CanopyRootToeRhythm_NoCollision", new float[] { 6.80f, 14.60f, 23.40f, 35.10f }, .82f, .11f);
                    AddAdventureLeafFootlineRun(parent, "AdventureRouteMemory_CanopyLeafFootline_NoCollision", 28.20f, .98f, .085f);
                    break;
                case 2:
                    AddAdventureBrokenStoneFootline(parent, "AdventureRouteMemory_BrokenBridgeStoneFootline_NoCollision", new float[] { 8.40f, 16.20f, 26.10f, 38.70f }, .86f, .105f);
                    AddAdventureOldWoodFootline(parent, "AdventureRouteMemory_BrokenBridgeOldWood_NoCollision", 32.60f, .74f, .090f);
                    break;
                case 3:
                    AddAdventureRuneShardFootline(parent, "AdventureRouteMemory_RuneShardFootline_NoCollision", new float[] { 7.90f, 15.70f, 24.80f, 36.40f }, .78f, .11f);
                    AddAdventureRuneDustFootline(parent, "AdventureRouteMemory_RuneDustFootline_NoCollision", 20.40f, 1.05f, .075f);
                    break;
                default:
                    AddAdventureTinyMushroomFootline(parent, "AdventureRouteMemory_ForestTinyMushroomFootline_NoCollision", new float[] { 4.90f, 13.30f, 27.40f, 39.20f }, .78f, .12f);
                    AddAdventureOldFenceFootline(parent, "AdventureRouteMemory_ForestFenceFootline_NoCollision", 18.60f, .78f, .085f);
                    break;
            }
        }

        private void AddAdventureFootlineGrassRhythm(Transform parent, string name, float[] xs, float scale, float alpha)
        {
            for (int i = 0; i < xs.Length; i++)
            {
                float x = xs[i];
                float width = (.28f + (i % 3) * .060f) * scale;
                RectObj(name + "_MossSeat_NoCollision_" + i, parent, new Vector2(x, GroundY + .620f), new Vector2(width, .014f * scale), new Color(.26f, .48f, .12f, alpha), 11);
                RectObj(name + "_FrontBlade_NoCollision_" + i, parent, new Vector2(x - .070f * scale, GroundY + .655f), new Vector2(.020f * scale, .080f * scale), new Color(.18f, .38f, .080f, alpha * 1.45f), 12).transform.localRotation = Quaternion.Euler(0f, 0f, -8f + i * 3f);
                RectObj(name + "_BrightTip_NoCollision_" + i, parent, new Vector2(x + .075f * scale, GroundY + .682f), new Vector2(.070f * scale, .010f * scale), new Color(.68f, .82f, .28f, alpha * .52f), 13).transform.localRotation = Quaternion.Euler(0f, 0f, 5f - i * 2f);
            }
        }

        private void AddAdventureTinyMushroomFootline(Transform parent, string name, float[] xs, float scale, float alpha)
        {
            for (int i = 0; i < xs.Length; i++)
            {
                float x = xs[i];
                RectObj(name + "_Stem_NoCollision_" + i, parent, new Vector2(x, GroundY + .695f), new Vector2(.040f * scale, .13f * scale), new Color(.78f, .64f, .46f, alpha), 9);
                var cap = CircleObj(name + "_Cap_NoCollision_" + i, parent, new Vector2(x, GroundY + .775f), .50f, new Color(.82f, .18f, .12f, alpha * .92f), 10);
                cap.transform.localScale = new Vector3(.16f * scale, .070f * scale, 1f);
                CircleObj(name + "_CapDot_NoCollision_" + i, parent, new Vector2(x - .030f * scale, GroundY + .790f), .010f * scale, new Color(1f, .86f, .72f, alpha * .82f), 11);
            }
        }

        private void AddAdventureOldFenceFootline(Transform parent, string name, float x, float scale, float alpha)
        {
            for (int i = 0; i < 4; i++)
