            }
            RectObj(name + "_LowRail_NoCollision", parent, new Vector2(x, GroundY + .765f), new Vector2(.78f * scale, .024f * scale), new Color(.50f, .40f, .25f, alpha * .64f), 9).transform.localRotation = Quaternion.Euler(0f, 0f, -4f);
        }

