        private void AddProceduralPicketFenceCluster(Transform parent, string name, Vector2 pos, int count, float scale, float alpha)
        {
            int posts = Mathf.Clamp(count, 2, 7);
            for (int i = 0; i < posts; i++)
            {
                float x = pos.x + (i - (posts - 1) * .5f) * .24f * scale;
                RectObj(name + "_Post_NoCollision_" + i, parent, new Vector2(x, pos.y + .13f * scale), new Vector2(.045f * scale, .42f * scale), new Color(.86f, .82f, .62f, alpha), 8);
                RectObj(name + "_PostTip_NoCollision_" + i, parent, new Vector2(x, pos.y + .36f * scale), new Vector2(.075f * scale, .038f * scale), new Color(.96f, .92f, .70f, alpha * .60f), 9);
            }
            RectObj(name + "_BackRailA_NoCollision", parent, new Vector2(pos.x, pos.y + .22f * scale), new Vector2((posts - 1) * .29f * scale, .030f * scale), new Color(.70f, .62f, .42f, alpha * .60f), 7);
            RectObj(name + "_BackRailB_NoCollision", parent, new Vector2(pos.x, pos.y + .040f * scale), new Vector2((posts - 1) * .27f * scale, .025f * scale), new Color(.42f, .34f, .22f, alpha * .55f), 7);
        }

        private void AddProceduralHayStack(Transform parent, string name, Vector2 pos, float scale, float alpha)
        {
            for (int i = 0; i < 5; i++)
            {
                float t = i / 4f;
                float x = pos.x + Mathf.Lerp(-.28f, .28f, t) * scale;
                float y = pos.y + Mathf.Sin(t * Mathf.PI) * .10f * scale;
                RectObj(name + "_StrawBand_NoCollision_" + i, parent, new Vector2(x, y + .12f * scale), new Vector2(.24f * scale, .030f * scale), new Color(.76f, .62f, .28f, alpha), 8).transform.localRotation = Quaternion.Euler(0f, 0f, -10f + i * 5f);
            }
            RectObj(name + "_GroundAo_NoCollision", parent, pos + new Vector2(0f, .030f * scale), new Vector2(.62f * scale, .020f * scale), new Color(.030f, .040f, .020f, alpha * .24f), 6);
        }

        private void BuildCanopyRootFootCluster(Transform parent, string name, Vector2 pos, float scale, float alpha)
        {
            for (int i = 0; i < 4; i++)
            {
                float x = pos.x + (i - 1.5f) * .16f * scale;
                var root = RectObj(name + "_RootFoot_NoCollision_" + i, parent, new Vector2(x, pos.y + .16f * scale), new Vector2(.050f * scale, .50f * scale), new Color(.12f, .27f, .070f, alpha), 7);
                root.transform.localRotation = Quaternion.Euler(0f, 0f, -18f + i * 11f);
            }
            RectObj(name + "_MossSeat_NoCollision", parent, pos + new Vector2(0f, .050f * scale), new Vector2(.72f * scale, .026f * scale), new Color(.30f, .50f, .15f, alpha * .52f), 8);
        }

        private void AddProceduralLeafLitterRun(Transform parent, string name, Vector2 pos, int count, float scale, float alpha)
        {
            int leaves = Mathf.Clamp(count, 3, 12);
            for (int i = 0; i < leaves; i++)
            {
                float t = leaves <= 1 ? .5f : i / (leaves - 1f);
                float x = pos.x + Mathf.Lerp(-1.00f, 1.00f, t) * scale;
                float y = pos.y + ((i % 3) - 1) * .018f * scale;
                RectObj(name + "_Leaf_NoCollision_" + i, parent, new Vector2(x, y), new Vector2(.095f * scale, .020f * scale), new Color(.42f, .58f, .18f, alpha), 8).transform.localRotation = Quaternion.Euler(0f, 0f, -18f + i * 7f);
            }
        }

        private void BuildBrokenBridgeLowRubble(Transform parent, string name, Vector2 pos, float scale, float alpha)
        {
            for (int i = 0; i < 6; i++)
            {
                float x = pos.x + (i - 2.5f) * .14f * scale;
                float y = pos.y + ((i % 2) * .035f) * scale;
                RectObj(name + "_Stone_NoCollision_" + i, parent, new Vector2(x, y), new Vector2((.13f + (i % 3) * .030f) * scale, (.040f + (i % 2) * .012f) * scale), new Color(.38f, .36f, .27f, alpha), 8);
            }
            RectObj(name + "_MossBreak_NoCollision", parent, pos + new Vector2(.04f * scale, .090f * scale), new Vector2(.62f * scale, .014f * scale), new Color(.30f, .48f, .14f, alpha * .44f), 9);
        }

        private void BuildRuneGroundObelisk(Transform parent, string name, Vector2 pos, float scale, float alpha)
        {
            var stone = RectObj(name + "_StoneBody_NoCollision", parent, pos + new Vector2(0f, .32f * scale), new Vector2(.16f * scale, .62f * scale), new Color(.30f, .34f, .31f, alpha), 8);
            stone.transform.localRotation = Quaternion.Euler(0f, 0f, -4f);
            RectObj(name + "_RuneCore_NoCollision", parent, pos + new Vector2(.010f * scale, .40f * scale), new Vector2(.042f * scale, .23f * scale), new Color(.54f, .96f, 1f, alpha * .58f), 9);
            RectObj(name + "_BaseAo_NoCollision", parent, pos + new Vector2(0f, .050f * scale), new Vector2(.42f * scale, .022f * scale), new Color(.020f, .040f, .030f, alpha * .28f), 6);
        }

