                    RectObj(name + "_RunePin_NoCollision_" + i, parent, new Vector2(x + offset + .10f * scale, y + .062f * scale), new Vector2(.026f * scale, .034f * scale), new Color(.80f, 1f, 1f, alpha * .24f), 7);
