        private void BuildStorybookMushroomHouse(Transform parent, string name, Vector2 pos, float scale, float alpha)
        {
            RectObj(name + "_WarmStem_NoCollision", parent, pos + new Vector2(0f, .24f * scale), new Vector2(.34f * scale, .46f * scale), new Color(.74f, .64f, .46f, alpha), 6);
            var cap = CircleObj(name + "_SoftCap_NoCollision", parent, pos + new Vector2(0f, .54f * scale), .50f, new Color(.60f, .11f, .09f, alpha * .92f), 7);
