            RectObj(name + "_DoorShadow_NoCollision", parent, pos + new Vector2(0f, .18f * scale), new Vector2(.13f * scale, .22f * scale), new Color(.12f, .08f, .045f, alpha * .58f), 8);
            RectObj(name + "_CapUnderShade_NoCollision", parent, pos + new Vector2(0f, .39f * scale), new Vector2(.64f * scale, .040f * scale), new Color(.16f, .055f, .040f, alpha * .44f), 8);
