        private void BuildStorybookFenceCluster(Transform parent, string name, Vector2 pos, int posts, float scale, float alpha)
        {
            int count = Mathf.Max(2, posts);
            for (int i = 0; i < count; i++)
            {
                float x = pos.x + (i - (count - 1) * .5f) * .28f * scale;
                RectObj(name + "_Post_NoCollision_" + i, parent, new Vector2(x, pos.y + .12f * scale), new Vector2(.050f * scale, .42f * scale), new Color(.66f, .57f, .38f, alpha), 7);
