            }
            RectObj(name + "_BackRail_NoCollision", parent, pos + new Vector2(0f, .18f * scale), new Vector2((count - 1) * .36f * scale, .034f * scale), new Color(.76f, .67f, .45f, alpha * .78f), 7);
            RectObj(name + "_LowRail_NoCollision", parent, pos + new Vector2(0f, .02f * scale), new Vector2((count - 1) * .34f * scale, .030f * scale), new Color(.46f, .38f, .24f, alpha * .62f), 7);
        }

