        private void BuildLayoutThemeMidgroundStoryBackdrop(Transform parent, int layout)
        {
            switch (layout)
            {
                case 1:
                    BuildMidgroundCanopyVillage(parent, "LayoutThemeMidground_CanopyTreeVillage_NoCollision", new Vector2(17.60f, GroundY + 2.86f), .88f, .075f);
                    BuildMidgroundCanopyVillage(parent, "LayoutThemeMidground_CanopyFarTreeVillage_NoCollision", new Vector2(35.10f, GroundY + 3.10f), .64f, .052f);
                    break;
                case 2:
                    BuildMidgroundBrokenBridgeTrace(parent, "LayoutThemeMidground_BrokenBridgeLargeArch_NoCollision", new Vector2(18.25f, GroundY + 2.62f), .86f, .075f);
                    BuildMidgroundBrokenBridgeTrace(parent, "LayoutThemeMidground_BrokenBridgeFarPier_NoCollision", new Vector2(36.80f, GroundY + 3.06f), .62f, .052f);
                    break;
                case 3:
                    BuildMidgroundRuneRidgePillars(parent, "LayoutThemeMidground_RuneRidgeDistantPillars_NoCollision", new Vector2(18.60f, GroundY + 2.72f), .82f, .075f);
                    BuildMidgroundRuneRidgePillars(parent, "LayoutThemeMidground_RuneRidgeFarPillars_NoCollision", new Vector2(35.80f, GroundY + 2.98f), .62f, .052f);
                    break;
                default:
                    BuildMidgroundForestVillageRoofline(parent, "LayoutThemeMidground_ForestVillageRoofline_NoCollision", new Vector2(15.80f, GroundY + 2.36f), .78f, .080f);
                    BuildMidgroundForestVillageRoofline(parent, "LayoutThemeMidground_ForestFarRoofline_NoCollision", new Vector2(34.40f, GroundY + 2.64f), .58f, .055f);
