        private void BuildMidgroundCanopyVillage(Transform parent, string name, Vector2 pos, float scale, float alpha)
        {
            for (int i = 0; i < 3; i++)
            {
                float x = pos.x + (i - 1f) * .42f * scale;
                var trunk = RectObj(name + "_TreeTrunk_NoCollision_" + i, parent, new Vector2(x, pos.y - .34f * scale), new Vector2(.12f * scale, .92f * scale), new Color(.10f, .22f, .09f, alpha * .70f), 3);
                trunk.transform.localRotation = Quaternion.Euler(0f, 0f, -4f + i * 3f);
