        private void BuildMidgroundBrokenBridgeTrace(Transform parent, string name, Vector2 pos, float scale, float alpha)
        {
            for (int i = 0; i < 7; i++)
            {
                float t = i / 6f;
                float x = pos.x + Mathf.Lerp(-1.12f, 1.12f, t) * scale;
                float y = pos.y + Mathf.Sin(t * Mathf.PI) * .82f * scale;
                var stone = RectObj(name + "_SoftArchStone_NoCollision_" + i, parent, new Vector2(x, y), new Vector2(.28f * scale, .090f * scale), new Color(.30f, .33f, .28f, alpha), 3);
                stone.transform.localRotation = Quaternion.Euler(0f, 0f, -18f + i * 6f);
            }
            RectObj(name + "_LeftPierGhost_NoCollision", parent, pos + new Vector2(-1.18f * scale, -.50f * scale), new Vector2(.18f * scale, .78f * scale), new Color(.24f, .28f, .24f, alpha * .68f), 3);
            RectObj(name + "_RightPierGhost_NoCollision", parent, pos + new Vector2(1.18f * scale, -.50f * scale), new Vector2(.18f * scale, .72f * scale), new Color(.24f, .28f, .24f, alpha * .58f), 3);
        }

        private void BuildMidgroundRuneRidgePillars(Transform parent, string name, Vector2 pos, float scale, float alpha)
        {
            for (int i = 0; i < 5; i++)
            {
                float x = pos.x + (i - 2f) * .38f * scale;
                float h = (.72f + (i % 3) * .20f) * scale;
                var pillar = RectObj(name + "_DistantPillar_NoCollision_" + i, parent, new Vector2(x, pos.y + h * .28f), new Vector2(.16f * scale, h), new Color(.24f, .31f, .30f, alpha), 3);
                pillar.transform.localRotation = Quaternion.Euler(0f, 0f, -5f + i * 2.2f);
                RectObj(name + "_RuneSlit_NoCollision_" + i, parent, new Vector2(x, pos.y + h * .40f), new Vector2(.030f * scale, h * .30f), new Color(.46f, .96f, 1f, alpha * .42f), 4);
            }
        }

