        private void BuildThemeSoftTreeCrown(Transform parent, string name, float x, float y, float scale, float alpha)
        {
            for (int i = 0; i < 11; i++)
            {
                float t = i / 10f;
                float px = x + Mathf.Lerp(-1.42f, 1.42f, t) * scale;
                float py = y + Mathf.Sin(t * Mathf.PI) * .28f * scale - (i % 2) * .025f * scale;
                float w = (.58f + (i % 4) * .12f) * scale;
                float h = (.16f + (i % 3) * .030f) * scale;
                var leaf = CircleObj(name + "_LeafMass_NoCollision_" + i, parent, new Vector2(px, py), .50f, new Color(.13f, .34f, .10f, alpha * .76f), 6);
                leaf.transform.localScale = new Vector3(w, h, 1f);
                leaf.transform.localRotation = Quaternion.Euler(0f, 0f, -12f + i * 3.0f);
            }
            var branch = RectObj(name + "_SoftBranch_NoCollision", parent, new Vector2(x, y - .19f * scale), new Vector2(2.20f * scale, .030f * scale), new Color(.10f, .075f, .045f, alpha * .28f), 5);
            branch.transform.localRotation = Quaternion.Euler(0f, 0f, -4f);
        }

        private void BuildThemeHighLeafBridge(Transform parent, string name, float x, float y, float scale, float alpha)
        {
            for (int i = 0; i < 13; i++)
            {
                float t = i / 12f;
                float px = x + Mathf.Lerp(-2.00f, 2.00f, t) * scale;
                float py = y + Mathf.Sin(t * Mathf.PI * 1.08f) * .18f * scale;
                var leaf = CircleObj(name + "_LeafStep_NoCollision_" + i, parent, new Vector2(px, py), .50f, new Color(.18f, .40f, .12f, alpha * .64f), 6);
                leaf.transform.localScale = new Vector3((.36f + (i % 3) * .06f) * scale, (.10f + (i % 2) * .025f) * scale, 1f);
                leaf.transform.localRotation = Quaternion.Euler(0f, 0f, -10f + i * 2.4f);
            }
            RectObj(name + "_DepthStem_NoCollision", parent, new Vector2(x, y - .14f * scale), new Vector2(3.40f * scale, .016f * scale), new Color(.09f, .24f, .070f, alpha * .22f), 5);
        }

        private void BuildThemeHangingVineCluster(Transform parent, string name, float x, float y, float scale, float alpha)
        {
            for (int i = 0; i < 7; i++)
            {
                float px = x + (i - 3f) * .16f * scale;
                float length = (.34f + (i % 4) * .15f) * scale;
                var vine = RectObj(name + "_Vine_NoCollision_" + i, parent, new Vector2(px, y - length * .50f), new Vector2(.014f * scale, length), new Color(.08f, .24f, .065f, alpha * .48f), 6);
                vine.transform.localRotation = Quaternion.Euler(0f, 0f, -12f + i * 4f);
                if (i % 2 == 0)
                {
                    var leaf = CircleObj(name + "_Leaf_NoCollision_" + i, parent, new Vector2(px + .050f * scale, y - length * .62f), .50f, new Color(.30f, .52f, .14f, alpha * .34f), 7);
                    leaf.transform.localScale = new Vector3(.12f * scale, .045f * scale, 1f);
                }
            }
        }

        private void BuildThemeBrokenArchTrace(Transform parent, string name, float x, float y, float scale, float alpha)
        {
            for (int i = 0; i < 7; i++)
            {
                float t = i / 6f;
                float px = x + Mathf.Lerp(-1.05f, 1.05f, t) * scale;
                float py = y + Mathf.Sin(t * Mathf.PI) * .64f * scale;
                var stone = RectObj(name + "_ArchStone_NoCollision_" + i, parent, new Vector2(px, py), new Vector2(.22f * scale, .070f * scale), new Color(.40f, .42f, .35f, alpha * .46f), 5);
                stone.transform.localRotation = Quaternion.Euler(0f, 0f, -16f + i * 5f);
                RectObj(name + "_MossTrace_NoCollision_" + i, parent, new Vector2(px, py + .052f * scale), new Vector2(.14f * scale, .014f * scale), new Color(.30f, .48f, .16f, alpha * .34f), 6);
            }
        }

        private void BuildThemeFloatingRuneCluster(Transform parent, string name, float x, float y, float scale, float alpha)
        {
            for (int i = 0; i < 5; i++)
            {
                float angle = i * 72f * Mathf.Deg2Rad;
                float px = x + Mathf.Cos(angle) * .72f * scale;
                float py = y + Mathf.Sin(angle) * .30f * scale;
                var rune = RectObj(name + "_RuneShard_NoCollision_" + i, parent, new Vector2(px, py), new Vector2(.070f * scale, .18f * scale), new Color(.48f, .96f, 1f, alpha * .48f), 6);
                rune.transform.localRotation = Quaternion.Euler(0f, 0f, 28f + i * 18f);
                var glint = CircleObj(name + "_RuneGlint_NoCollision_" + i, parent, new Vector2(px, py + .09f * scale), .50f, new Color(.86f, 1f, 1f, alpha * .18f), 7);
                glint.transform.localScale = new Vector3(.070f * scale, .024f * scale, 1f);
            }
            RectObj(name + "_ColdMistTrace_NoCollision", parent, new Vector2(x, y - .38f * scale), new Vector2(1.72f * scale, .010f * scale), new Color(.42f, .96f, 1f, alpha * .16f), 5);
        }

        private void BuildRoomRouteReadabilityAnchors(int layout)
        {
            Transform parent = mapLayoutRoot ? mapLayoutRoot : world;
            if (!parent) return;

            for (int i = 0; i < SegmentRights.Length; i++)
            {
                float left = i == 0 ? LeftBound : SegmentRights[i - 1];
                float right = SegmentRights[i];
                float center = (left + right) * .5f;
                float span = Mathf.Max(1f, right - left);
                Color roomColor = RoomColor(Mathf.Clamp(i, 0, SegmentLabels.Length - 1));

                RectObj("RoomRouteCombatFootRibbon_NoYellowPlate_" + i, parent, new Vector2(center, GroundY + .535f), new Vector2(Mathf.Clamp(span * .42f, 1.62f, 3.65f), .018f), new Color(.040f, .075f, .038f, .070f), 8);
                RectObj("RoomRouteCombatCenterGrassBreak_NoYellowPlate_" + i, parent, new Vector2(center, GroundY + .575f), new Vector2(Mathf.Clamp(span * .20f, .72f, 1.55f), .018f), new Color(.50f, .70f, .20f, .085f), 9);
                RectObj("RoomRouteEnemyStageShadow_NoYellowPlate_" + i, parent, new Vector2(center, GroundY + .405f), new Vector2(Mathf.Clamp(span * .30f, 1.05f, 2.45f), .026f), new Color(.010f, .022f, .016f, .065f), 7);

                if (i > 0)
                    BuildRoutePebbleCluster(parent, "RoomRouteEntrancePebbles_NoCollision_" + i, left + .62f, GroundY + .565f, roomColor, false);
                if (i < SegmentRights.Length - 1)
                    BuildRoutePebbleCluster(parent, "RoomRouteExitPebbles_NoCollision_" + i, right - .74f, GroundY + .565f, roomColor, true);
            }

            BuildLayoutSpecificRouteAnchors(parent, layout);
        }

        private void BuildRoutePebbleCluster(Transform parent, string name, float x, float y, Color roomColor, bool pointsRight)
        {
            float dir = pointsRight ? 1f : -1f;
            for (int i = 0; i < 3; i++)
            {
                float offset = i * .16f * dir;
                float width = .13f - i * .018f;
                RectObj(name + "_Stone_" + i, parent, new Vector2(x + offset, y + (i % 2) * .014f), new Vector2(width, .026f), new Color(.35f, .37f, .27f, .22f), 10);
                RectObj(name + "_Moss_" + i, parent, new Vector2(x + offset - dir * .018f, y + .025f + (i % 2) * .012f), new Vector2(width * .62f, .008f), new Color(roomColor.r, Mathf.Max(roomColor.g, .60f), roomColor.b, .060f), 11);
            }
        }

        private void BuildLayoutSpecificRouteAnchors(Transform parent, int layout)
        {
            if (layout == 1)
            {
                BuildRouteClimbHint(parent, "RoomRouteClimbHint_CanopyA_NoCollision", 8.10f, GroundY + 6.92f);
                BuildRouteClimbHint(parent, "RoomRouteClimbHint_CanopyB_NoCollision", 17.30f, GroundY + 7.15f);
                BuildRouteClimbHint(parent, "RoomRouteClimbHint_CanopyC_NoCollision", 31.10f, GroundY + 6.98f);
            }
            else if (layout == 2)
            {
                BuildRouteGapEdgeStones(parent, "RoomRouteGapEdgeStones_BridgeA_NoCollision", 7.95f, GroundY + .67f);
                BuildRouteGapEdgeStones(parent, "RoomRouteGapEdgeStones_BridgeB_NoCollision", 25.10f, GroundY + .67f);
                BuildRouteGapEdgeStones(parent, "RoomRouteGapEdgeStones_BridgeC_NoCollision", 36.45f, GroundY + .67f);
            }
            else if (layout == 3)
            {
                BuildRouteRuneHighTrail(parent, "RoomRouteRuneHighTrail_A_NoCollision", 10.0f, GroundY + 6.88f);
                BuildRouteRuneHighTrail(parent, "RoomRouteRuneHighTrail_B_NoCollision", 18.15f, GroundY + 6.88f);
                BuildRouteRuneHighTrail(parent, "RoomRouteRuneHighTrail_C_NoCollision", 32.85f, GroundY + 6.88f);
            }
            else
            {
                BuildRouteGroundRestPoint(parent, "RoomRouteRestPoint_ForestA_NoCollision", 6.20f, GroundY + .66f);
                BuildRouteGroundRestPoint(parent, "RoomRouteRestPoint_ForestB_NoCollision", 25.50f, GroundY + .66f);
                BuildRouteGroundRestPoint(parent, "RoomRouteRestPoint_ForestC_NoCollision", 38.85f, GroundY + .66f);
            }
        }

        private void BuildRouteClimbHint(Transform parent, string name, float x, float y)
        {
            RectObj(name + "_RootMark_NoCollision", parent, new Vector2(x, y), new Vector2(.030f, .36f), new Color(.13f, .30f, .075f, .10f), 7);
            RectObj(name + "_LeafStep_NoCollision", parent, new Vector2(x + .10f, y + .22f), new Vector2(.18f, .022f), new Color(.32f, .54f, .16f, .070f), 8);
            RectObj(name + "_FootCue_NoYellowPlate_NoCollision", parent, new Vector2(x - .08f, y - .20f), new Vector2(.16f, .008f), new Color(.72f, .92f, .32f, .020f), 8);
        }

        private void BuildRouteGapEdgeStones(Transform parent, string name, float x, float y)
        {
            RectObj(name + "_LeftEdge_NoCollision", parent, new Vector2(x - .26f, y), new Vector2(.18f, .034f), new Color(.36f, .34f, .25f, .13f), 10);
            RectObj(name + "_RightEdge_NoCollision", parent, new Vector2(x + .26f, y + .020f), new Vector2(.18f, .034f), new Color(.34f, .32f, .24f, .12f), 10);
            RectObj(name + "_MossCue_NoYellowPlate_NoCollision", parent, new Vector2(x, y + .055f), new Vector2(.28f, .010f), new Color(.48f, .68f, .22f, .032f), 11);
        }

        private void BuildRouteRuneHighTrail(Transform parent, string name, float x, float y)
        {
            RectObj(name + "_StoneA_NoCollision", parent, new Vector2(x - .20f, y), new Vector2(.14f, .026f), new Color(.38f, .42f, .34f, .12f), 10);
