        private void AddProceduralFenceRun(Transform parent, string name, Vector2 pos, int posts, float scale, float alpha)
        {
            int count = Mathf.Max(2, posts);
            for (int i = 0; i < count; i++)
            {
                float x = pos.x + (i - (count - 1) * .5f) * .36f * scale;
                RectObj(name + "_Post_NoCollision_" + i, parent, new Vector2(x, pos.y), new Vector2(.060f * scale, .54f * scale), new Color(.72f, .67f, .48f, alpha), 9);
                RectObj(name + "_Cap_NoCollision_" + i, parent, new Vector2(x, pos.y + .29f * scale), new Vector2(.13f * scale, .045f * scale), new Color(.90f, .84f, .60f, alpha * .82f), 10);
            }
            RectObj(name + "_RailA_NoCollision", parent, pos + new Vector2(0f, .13f * scale), new Vector2((count - 1) * .44f * scale, .050f * scale), new Color(.80f, .73f, .52f, alpha), 10);
            RectObj(name + "_RailB_NoCollision", parent, pos + new Vector2(0f, -.08f * scale), new Vector2((count - 1) * .42f * scale, .042f * scale), new Color(.54f, .46f, .30f, alpha * .90f), 10);
        }

        private void AddProceduralMushroomPatch(Transform parent, string name, Vector2 pos, float scale, float alpha)
        {
            for (int i = 0; i < 5; i++)
            {
                float side = i - 2f;
                float s = scale * (.72f + (i % 3) * .12f);
                Vector2 p = pos + new Vector2(side * .12f * scale, (i % 2) * .025f * scale);
                RectObj(name + "_Stem_NoCollision_" + i, parent, p + new Vector2(0f, .09f * s), new Vector2(.050f * s, .17f * s), new Color(.93f, .84f, .64f, alpha), 12);
                CircleObj(name + "_Cap_NoCollision_" + i, parent, p + new Vector2(0f, .22f * s), .11f * s, new Color(.78f, .12f, .12f, alpha), 13);
                RectObj(name + "_CapShade_NoCollision_" + i, parent, p + new Vector2(.030f * s, .18f * s), new Vector2(.15f * s, .030f * s), new Color(.42f, .055f, .045f, alpha * .42f), 14);
            }
        }

        private void AddProceduralFlowerPatch(Transform parent, string name, Vector2 pos, float scale, float alpha)
        {
            for (int i = 0; i < 9; i++)
            {
                float t = i / 8f;
                float x = pos.x + Mathf.Lerp(-.58f, .58f, t) * scale;
                float h = (.18f + (i % 4) * .035f) * scale;
                RectObj(name + "_Stem_NoCollision_" + i, parent, new Vector2(x, pos.y + h * .45f), new Vector2(.014f * scale, h), new Color(.18f, .36f, .075f, alpha), 11);
                Color petal = i % 3 == 0 ? new Color(.96f, .50f, .62f, alpha) : i % 3 == 1 ? new Color(.78f, .88f, .28f, alpha) : new Color(.65f, .82f, 1f, alpha);
                CircleObj(name + "_Petal_NoCollision_" + i, parent, new Vector2(x, pos.y + h), .035f * scale, petal, 13);
            }
        }

