        private void BuildPlatformLandingAccents(Transform parent)
        {
            if (platforms == null || platforms.Count <= 0) return;
            for (int i = 0; i < platforms.Count; i++)
            {
                var p = platforms[i];
                float center = (p.Left + p.Right) * .5f;
                float y = p.Top + .055f;
                RectObj("RouteDressing_PlatformFootGrass_NoCollision_" + i, parent, new Vector2(center, y), new Vector2(Mathf.Clamp(p.Width * .32f, .46f, 1.08f), .018f), new Color(.68f, .86f, .24f, .045f), 13);
                RectObj("RouteDressing_PlatformLandingToeL_NoCollision_" + i, parent, new Vector2(center - Mathf.Clamp(p.Width * .11f, .16f, .34f), y + .040f), new Vector2(.13f, .020f), new Color(.70f, .88f, .28f, .060f), 14);
                RectObj("RouteDressing_PlatformLandingToeR_NoCollision_" + i, parent, new Vector2(center + Mathf.Clamp(p.Width * .11f, .16f, .34f), y + .034f), new Vector2(.12f, .018f), new Color(.50f, .72f, .20f, .050f), 14);
                RectObj("RouteDressing_PlatformLeftLeaf_NoCollision_" + i, parent, new Vector2(p.Left + .20f, y + .030f), new Vector2(.18f, .024f), new Color(.26f, .50f, .12f, .085f), 13);
                RectObj("RouteDressing_PlatformRightLeaf_NoCollision_" + i, parent, new Vector2(p.Right - .20f, y + .025f), new Vector2(.18f, .024f), new Color(.22f, .44f, .10f, .075f), 13);
            }

            var ordered = platforms.OrderBy(p => p.Left).ToList();
            for (int i = 1; i < ordered.Count; i++)
            {
                var prev = ordered[i - 1];
                var next = ordered[i];
                float gap = next.Left - prev.Right;
                float heightDelta = Mathf.Abs(next.Top - prev.Top);
                if (gap <= .18f || gap > 1.85f || heightDelta > .46f) continue;

                float midX = (prev.Right + next.Left) * .5f;
                float midY = Mathf.Lerp(prev.Top, next.Top, .5f) + .74f;
                float visualWidth = Mathf.Clamp(gap * .62f, .32f, .88f);
                RectObj("RouteDressing_PlatformGapMossEcho_NoCollision_" + i, parent, new Vector2(midX, midY), new Vector2(visualWidth * .78f, .018f), new Color(.32f, .56f, .14f, .030f), 9);
                RectObj("RouteDressing_PlatformGapStoneEcho_NoCollision_" + i, parent, new Vector2(midX, midY - .045f), new Vector2(visualWidth * .50f, .020f), new Color(.34f, .32f, .24f, .024f), 8);
                RectObj("RouteDressing_PlatformGapUnderShade_NoCollision_" + i, parent, new Vector2(midX, midY - .115f), new Vector2(visualWidth * .40f, .014f), new Color(.020f, .040f, .024f, .018f), 7);
                for (int j = 0; j < 3; j++)
                {
                    float t = (j + 1f) * .25f;
                    float arcX = Mathf.Lerp(prev.Right + .10f, next.Left - .10f, t);
                    float arcY = Mathf.Lerp(prev.Top, next.Top, t) + .98f + Mathf.Sin(t * Mathf.PI) * .30f;
                    var leaf = RectObj("RouteDressing_PlatformJumpArcLeaf_NoCollision_" + i + "_" + j, parent, new Vector2(arcX, arcY), new Vector2(.085f, .022f), new Color(.30f, .52f, .16f, .040f), 10);
                    leaf.transform.localRotation = Quaternion.Euler(0f, 0f, -12f + j * 12f);
                }
            }
        }

        private void BuildBossArenaLockdown()
        {
            bossArenaLockdownRoot = new GameObject("BossArenaLockdown");
            bossArenaLockdownRoot.transform.SetParent(mapLayoutRoot ? mapLayoutRoot : world);
            float leftX = SegmentRights[BossRoomIndex - 1] + .18f;
            float rightX = RightBound - .62f;
            float centerX = (leftX + rightX) * .5f;
            float width = Mathf.Max(1f, rightX - leftX);
            bossArenaLeftLockWall = RectObj("BossArenaLeftLockEdgeHint_ThinNoPlate", bossArenaLockdownRoot.transform, new Vector2(leftX, GroundY + 1.25f), new Vector2(.030f, 1.86f), new Color(1f, .20f, .18f, .030f), 7).GetComponent<SpriteRenderer>();
            bossArenaRightLockWall = RectObj("BossArenaRightLockEdgeHint_ThinNoPlate", bossArenaLockdownRoot.transform, new Vector2(rightX, GroundY + 1.25f), new Vector2(.030f, 1.86f), new Color(1f, .20f, .18f, .030f), 7).GetComponent<SpriteRenderer>();
            bossArenaGroundSeal = RectObj("BossArenaGroundSeal_HairlineNoPlate", bossArenaLockdownRoot.transform, new Vector2(centerX, GroundY + .17f), new Vector2(width * .42f, .014f), new Color(1f, .30f, .24f, .020f), 4).GetComponent<SpriteRenderer>();
            RectObj("BossArenaLeftLockCoreTick_NoYellowPlate", bossArenaLockdownRoot.transform, new Vector2(leftX, GroundY + 2.42f), new Vector2(.040f, .30f), new Color(1f, .32f, .28f, .060f), 8);
            RectObj("BossArenaRightLockCoreTick_NoYellowPlate", bossArenaLockdownRoot.transform, new Vector2(rightX, GroundY + 2.42f), new Vector2(.040f, .30f), new Color(1f, .32f, .28f, .060f), 8);
            RectObj("BossArenaLockTopTickL_NoYellowPlate", bossArenaLockdownRoot.transform, new Vector2(leftX + .24f, GroundY + 2.42f), new Vector2(.24f, .016f), new Color(1f, .32f, .28f, .070f), 8);
            RectObj("BossArenaLockTopTickR_NoYellowPlate", bossArenaLockdownRoot.transform, new Vector2(rightX - .24f, GroundY + 2.42f), new Vector2(.24f, .016f), new Color(1f, .32f, .28f, .070f), 8);
            bossArenaLockdownRoot.SetActive(false);
        }

        private void AddPlatform(string name, int spriteIndex, Vector2 pos, Vector2 size)
        {
            pos.y += PlatformRouteAirLift;
            var body = new GameObject(name);
            body.transform.SetParent(mapLayoutRoot ? mapLayoutRoot : world);
            body.transform.localPosition = pos;
            var sr = body.AddComponent<SpriteRenderer>();
            bool hasPlatformArt = platformSprites != null && spriteIndex < platformSprites.Length && platformSprites[spriteIndex];
            sr.sprite = hasPlatformArt ? platformSprites[spriteIndex] : SpriteCache.White;
            sr.sortingOrder = hasPlatformArt ? 8 : 1;
            if (hasPlatformArt)
            {
                var bounds = sr.sprite.bounds.size;
                body.transform.localScale = new Vector3(size.x / bounds.x, Mathf.Max(size.y * 1.18f, .78f) / bounds.y, 1);
                sr.color = Color.white;
            }
            else
            {
                body.transform.localScale = new Vector3(size.x, size.y, 1);
                sr.color = new Color(.42f, .31f, .16f, .92f);
            }
            // Every walkable platform gets an opaque footing, even when a generated sprite is present.
            BuildPlatformSolidFooting(name, pos, size);
            if (!hasPlatformArt)
            {
                BuildPlatformLandingLanguage(name, pos, size);
            }
            else
            {
                BuildPlatformArtSolidUnderside(name, pos, size);
                BuildPlatformArtContactDetails(name, pos, size);
            }
            BuildPlatformEdgeBlend(name, pos, size, hasPlatformArt);
            BuildPlatformStageModuleSilhouette(name, pos, size, hasPlatformArt);
            BuildPlatformSceneAnchors(name, pos, size, hasPlatformArt);
            BuildPlatformAdventureCartoonCrossSection(name, pos, size, hasPlatformArt);
            BuildPlatformAdventureStoneMosaic(name, pos, size, hasPlatformArt);
            BuildPlatformAdventurePlayableBlockFace(name, pos, size, hasPlatformArt);
            BuildPlatformReadableWalkableCap(name, pos, size, hasPlatformArt);
            BuildPlatformAdventureKingLandingLanguage(name, pos, size, hasPlatformArt);
            BuildPlatformAdventureKingSolidSideLanguage(name, pos, size, hasPlatformArt);
            BuildPlatformAdventureStorybookTileFace(name, pos, size, hasPlatformArt);
            BuildPlatformWalkableReadabilityTicks(name, pos, size, hasPlatformArt);
            BuildPlatformFinalPlayableTileRead(name, pos, size, hasPlatformArt);
            platforms.Add(new Platform { Left = pos.x - size.x * .5f, Right = pos.x + size.x * .5f, Top = pos.y + size.y * .5f + PlatformVisualRootToWalkableTop });
            BuildPlatformReadabilityEdges(name, body.transform, size);
            platformVisuals.Add(body);
        }

        private void BuildPlatformLandingLanguage(string name, Vector2 pos, Vector2 size)
        {
            Transform parent = mapLayoutRoot ? mapLayoutRoot : world;
            float topY = pos.y + size.y * .50f + PlatformVisualRootToWalkableTop;
            float edgeInset = Mathf.Clamp(size.x * .33f, .46f, 1.35f);
            float centerWidth = Mathf.Clamp(size.x * .46f, .82f, 1.72f);

            RectObj(name + "_AdventureLandingPadCenterStone", parent, new Vector2(pos.x, topY - .075f), new Vector2(centerWidth, .070f), new Color(.38f, .40f, .30f, .30f), 7);
            RectObj(name + "_AdventureLandingPadMossLip", parent, new Vector2(pos.x, topY + .016f), new Vector2(centerWidth * .92f, .020f), new Color(.34f, .56f, .15f, .34f), 10);
            RectObj(name + "_AdventureLandingReadableFootLine", parent, new Vector2(pos.x, topY + .052f), new Vector2(size.x * .84f, .020f), new Color(.62f, .82f, .24f, .30f), 11);
            RectObj(name + "_AdventureLandingBackSilhouetteLine", parent, new Vector2(pos.x, topY + .082f), new Vector2(size.x * .72f, .010f), new Color(.16f, .32f, .075f, .20f), 10);
            RectObj(name + "_AdventureLandingPadFootAo", parent, new Vector2(pos.x, topY - .135f), new Vector2(centerWidth * .54f, .018f), new Color(.020f, .040f, .026f, .080f), 8);
            RectObj(name + "_AdventureLandingPadLeftBrokenStone", parent, new Vector2(pos.x - edgeInset, topY - .11f), new Vector2(.30f, .080f), new Color(.24f, .23f, .17f, .30f), 7);
            RectObj(name + "_AdventureLandingPadRightBrokenStone", parent, new Vector2(pos.x + edgeInset, topY - .10f), new Vector2(.28f, .074f), new Color(.23f, .22f, .16f, .28f), 7);

            int rootCount = Mathf.Clamp(Mathf.RoundToInt(size.x * .72f), 2, 5);
            for (int i = 0; i < rootCount; i++)
            {
                float t = rootCount <= 1 ? .5f : i / (rootCount - 1f);
                float x = Mathf.Lerp(pos.x - edgeInset * .82f, pos.x + edgeInset * .82f, t);
                float length = .12f + (i % 3) * .036f;
                RectObj(name + "_AdventureLandingRootThread_" + i, parent, new Vector2(x, topY - .19f - length * .50f), new Vector2(.018f, length), new Color(.11f, .27f, .075f, .12f), 8);
            }
        }

        private void BuildPlatformArtContactDetails(string name, Vector2 pos, Vector2 size)
        {
            Transform parent = mapLayoutRoot ? mapLayoutRoot : world;
            float topY = pos.y + size.y * .50f + .08f;
            RectObj(name + "_AdventureArtUnderContactAo", parent, new Vector2(pos.x, topY - .22f), new Vector2(size.x * .62f, .030f), new Color(.045f, .058f, .034f, .040f), 7);
            RectObj(name + "_AdventureArtTopGrassCapReadable", parent, new Vector2(pos.x, topY + .012f), new Vector2(size.x * .58f, .018f), new Color(.25f, .43f, .14f, .024f), 9);
            RectObj(name + "_AdventureArtTopFootClarity", parent, new Vector2(pos.x, topY + .034f), new Vector2(size.x * .20f, .004f), new Color(.74f, .88f, .38f, .004f), 10);
            RectObj(name + "_AdventureArtRootShadowBlend_BrokenShort", parent, new Vector2(pos.x, topY - .42f), new Vector2(size.x * .38f, .026f), new Color(.030f, .048f, .025f, .030f), 6);
            RectObj(name + "_AdventureArtLeftOverhangShadow_BrokenShort", parent, new Vector2(pos.x - size.x * .43f, topY - .36f), new Vector2(.018f, .16f), new Color(.035f, .052f, .028f, .022f), 6);
            RectObj(name + "_AdventureArtRightOverhangShadow_BrokenShort", parent, new Vector2(pos.x + size.x * .43f, topY - .34f), new Vector2(.018f, .14f), new Color(.035f, .052f, .028f, .020f), 6);

            int vineCount = Mathf.Clamp(Mathf.RoundToInt(size.x * 1.15f), 3, 7);
            for (int i = 0; i < vineCount; i++)
            {
                float t = (i + .45f) / vineCount;
                float x = Mathf.Lerp(pos.x - size.x * .43f, pos.x + size.x * .43f, t);
                float length = .10f + (i % 4) * .030f;
                float width = .010f + (i % 2) * .004f;
                RectObj(name + "_AdventureArtHangingVine_" + i, parent, new Vector2(x, topY - .20f - length * .50f), new Vector2(width, length), new Color(.12f, .32f, .075f, .045f), 8);
                if (i % 2 == 0)
                    RectObj(name + "_AdventureArtVineLeaf_" + i, parent, new Vector2(x + .020f, topY - .22f - length * .28f), new Vector2(.030f, .014f), new Color(.23f, .46f, .11f, .040f), 9);
            }

            int chipCount = Mathf.Clamp(Mathf.RoundToInt(size.x * .90f), 2, 5);
            for (int i = 0; i < chipCount; i++)
            {
                float t = (i + .5f) / chipCount;
                float x = Mathf.Lerp(pos.x - size.x * .37f, pos.x + size.x * .37f, t);
                float y = topY - .46f - (i % 3) * .032f;
                RectObj(name + "_AdventureArtStoneChip_" + i, parent, new Vector2(x, y), new Vector2(.070f + (i % 2) * .020f, .014f), new Color(.18f, .17f, .12f, .030f), 8);
            }
        }

        private void BuildPlatformArtSolidUnderside(string name, Vector2 pos, Vector2 size)
        {
            Transform parent = mapLayoutRoot ? mapLayoutRoot : world;
            float topY = pos.y + size.y * .50f + .08f;
            float coreY = topY - Mathf.Max(.54f, size.y * .64f);
            float bodyHeight = Mathf.Max(.52f, size.y * .72f);
            RectObj(name + "_AdventureArtFullSolidBacking", parent, new Vector2(pos.x, coreY - bodyHeight * .01f), new Vector2(size.x * .86f, bodyHeight * .68f), new Color(.245f, .220f, .145f, .30f), 3);
            RectObj(name + "_AdventureArtHiddenDirtCore", parent, new Vector2(pos.x, coreY + bodyHeight * .02f), new Vector2(size.x * .72f, bodyHeight * .54f), new Color(.31f, .275f, .178f, .24f), 4);
            RectObj(name + "_AdventureArtDeepStoneFace_NoBackgroundLeak", parent, new Vector2(pos.x, coreY - bodyHeight * .18f), new Vector2(size.x * .58f, bodyHeight * .26f), new Color(.145f, .132f, .095f, .18f), 4);
            RectObj(name + "_AdventureArtHiddenRootBlend_BrokenShort", parent, new Vector2(pos.x, topY - .20f), new Vector2(size.x * .36f, .026f), new Color(.085f, .205f, .055f, .050f), 6);
            RectObj(name + "_AdventureArtBottomNoLeakSeal_BrokenShort", parent, new Vector2(pos.x, coreY - bodyHeight * .42f), new Vector2(size.x * .42f, .030f), new Color(.115f, .100f, .070f, .10f), 4);
            RectObj(name + "_AdventureArtLeftSolidEdgeSeal", parent, new Vector2(pos.x - size.x * .42f, coreY - bodyHeight * .07f), new Vector2(size.x * .036f, bodyHeight * .34f), new Color(.17f, .148f, .100f, .10f), 4);
            RectObj(name + "_AdventureArtRightSolidEdgeSeal", parent, new Vector2(pos.x + size.x * .42f, coreY - bodyHeight * .07f), new Vector2(size.x * .036f, bodyHeight * .34f), new Color(.16f, .138f, .096f, .095f), 4);

            int skirtCount = Mathf.Clamp(Mathf.RoundToInt(size.x * 1.55f), 4, 9);
            for (int i = 0; i < skirtCount; i++)
            {
                float t = (i + .5f) / skirtCount;
                float x = Mathf.Lerp(pos.x - size.x * .46f, pos.x + size.x * .46f, t);
                float w = size.x * (.090f + (i % 3) * .018f);
                float h = bodyHeight * (.18f + (i % 4) * .030f);
                float y = topY - .36f - h * .50f - (i % 2) * .028f;
                RectObj(name + "_AdventureArtIrregularDirtSkirt_NoLeak_" + i, parent, new Vector2(x, y), new Vector2(w * .82f, h * .82f), new Color(.20f, .175f, .115f, .12f), 4);
                RectObj(name + "_AdventureArtMossSkirtLip_NoLeak_" + i, parent, new Vector2(x - w * .10f, y + h * .48f), new Vector2(w * .58f, .016f), new Color(.16f, .35f, .080f, .055f), 6);
            }

            int chunkCount = Mathf.Clamp(Mathf.RoundToInt(size.x * 1.15f), 3, 7);
            for (int i = 0; i < chunkCount; i++)
            {
                float t = (i + .5f) / chunkCount;
                float x = Mathf.Lerp(pos.x - size.x * .43f, pos.x + size.x * .43f, t);
                float y = coreY - bodyHeight * (.02f + (i % 4) * .090f);
                RectObj(name + "_AdventureArtHiddenStonePocket_" + i, parent, new Vector2(x, y), new Vector2(size.x * (.070f + (i % 2) * .020f), .030f), new Color(.44f, .41f, .30f, .10f), 5);
                if (i % 2 == 1)
                    RectObj(name + "_AdventureArtMossyStoneFaceBreakup_" + i, parent, new Vector2(x + size.x * .035f, y - .070f), new Vector2(size.x * .045f, .024f), new Color(.22f, .32f, .12f, .080f), 5);
            }
        }

        private void BuildPlatformAdventureCartoonCrossSection(string name, Vector2 pos, Vector2 size, bool hasPlatformArt)
        {
            Transform parent = mapLayoutRoot ? mapLayoutRoot : world;
            float topY = pos.y + size.y * .50f + PlatformVisualRootToWalkableTop;
            float leftX = pos.x - size.x * .50f;
            float rightX = pos.x + size.x * .50f;
            float visualWidth = size.x * 1.04f;
            float soilHeight = Mathf.Clamp(size.y * .64f, .34f, .62f);
            float soilY = topY - .18f - soilHeight * .50f;
            float artBlend = hasPlatformArt ? .82f : 1f;

            RectObj(name + "_AdventureCartoonSolidSoilFace_NoBackgroundLeak", parent, new Vector2(pos.x, soilY), new Vector2(visualWidth * .92f, soilHeight), new Color(.20f, .17f, .105f, .42f * artBlend), 6);
            RectObj(name + "_AdventureCartoonStoneBelly_NoBackgroundLeak", parent, new Vector2(pos.x, soilY - soilHeight * .08f), new Vector2(visualWidth * .78f, soilHeight * .42f), new Color(.11f, .095f, .070f, .34f * artBlend), 5);
            RectObj(name + "_AdventureCartoonGrassCapReadable", parent, new Vector2(pos.x, topY + .034f), new Vector2(visualWidth, .104f), new Color(.38f, .64f, .18f, .72f * artBlend), 12);
            RectObj(name + "_AdventureCartoonGrassBrightLip", parent, new Vector2(pos.x, topY + .094f), new Vector2(visualWidth * .94f, .024f), new Color(.72f, .84f, .30f, .26f * artBlend), 13);
            RectObj(name + "_AdventureCartoonFootContactShade", parent, new Vector2(pos.x, topY - .022f), new Vector2(visualWidth * .76f, .026f), new Color(.020f, .040f, .022f, .13f * artBlend), 11);
            RectObj(name + "_AdventureCartoonLeftGrassWrap", parent, new Vector2(leftX + .16f, topY - .020f), new Vector2(.34f, .13f), new Color(.24f, .50f, .12f, .48f * artBlend), 12);
            RectObj(name + "_AdventureCartoonRightGrassWrap", parent, new Vector2(rightX - .16f, topY - .024f), new Vector2(.34f, .12f), new Color(.21f, .44f, .10f, .42f * artBlend), 12);

            int stoneCount = Mathf.Clamp(Mathf.RoundToInt(size.x * 1.55f), 4, 9);
            for (int i = 0; i < stoneCount; i++)
            {
                float t = stoneCount <= 1 ? .5f : i / (stoneCount - 1f);
                float x = Mathf.Lerp(leftX + .32f, rightX - .32f, t);
                float y = soilY + ((i % 3) - 1) * .042f;
                float w = .28f + (i % 3) * .055f;
                RectObj(name + "_AdventureCartoonEmbeddedStone_" + i, parent, new Vector2(x, y), new Vector2(w, .060f), new Color(.42f, .39f, .29f, .22f * artBlend), 7);
                if (i % 2 == 0)
                    RectObj(name + "_AdventureCartoonStoneMoss_" + i, parent, new Vector2(x - .035f, y + .045f), new Vector2(w * .54f, .012f), new Color(.30f, .48f, .14f, .16f * artBlend), 8);
            }

            int tuftCount = Mathf.Clamp(Mathf.RoundToInt(size.x * 1.20f), 3, 7);
            for (int i = 0; i < tuftCount; i++)
            {
                float t = tuftCount <= 1 ? .5f : i / (tuftCount - 1f);
                float x = Mathf.Lerp(leftX + .22f, rightX - .22f, t);
                float length = .10f + (i % 4) * .035f;
                RectObj(name + "_AdventureCartoonHangingGrass_" + i, parent, new Vector2(x, topY - .060f - length * .48f), new Vector2(.050f + (i % 2) * .018f, length), new Color(.13f, .32f, .070f, .30f * artBlend), 9);
            }
        }

        private void BuildPlatformAdventureStoneMosaic(string name, Vector2 pos, Vector2 size, bool hasPlatformArt)
        {
            Transform parent = mapLayoutRoot ? mapLayoutRoot : world;
            float topY = pos.y + size.y * .50f + PlatformVisualRootToWalkableTop;
            float leftX = pos.x - size.x * .50f;
            float rightX = pos.x + size.x * .50f;
            float alpha = hasPlatformArt ? .22f : .42f;
            float bodyHeight = Mathf.Clamp(size.y * .82f, .52f, .92f);
            float faceTop = topY - .18f;
            float faceBottom = faceTop - bodyHeight;

            RectObj(name + "_AdventureMosaicReadableGrassCrown_NoCollision", parent, new Vector2(pos.x, topY + .120f), new Vector2(size.x * 1.02f, .040f), new Color(.72f, .88f, .32f, .16f * alpha), 14);
            RectObj(name + "_AdventureMosaicRootDarkRim_NoCollision", parent, new Vector2(pos.x, faceTop - .030f), new Vector2(size.x * .94f, .026f), new Color(.055f, .13f, .045f, .22f * alpha), 10);

            int columns = Mathf.Clamp(Mathf.RoundToInt(size.x * 1.45f), 4, 9);
            for (int row = 0; row < 3; row++)
            {
                float rowT = row / 2f;
                float y = Mathf.Lerp(faceTop - .12f, faceBottom + .10f, rowT);
                int rowColumns = Mathf.Max(3, columns - (row % 2));
                for (int col = 0; col < rowColumns; col++)
                {
                    float t = (col + .5f) / rowColumns + (row % 2 == 0 ? 0f : .5f / rowColumns);
                    t -= Mathf.Floor(t);
                    float x = Mathf.Lerp(leftX + size.x * .12f, rightX - size.x * .12f, t);
                    float w = Mathf.Clamp(size.x / columns * (.62f + ((row + col) % 3) * .08f), .18f, .46f);
                    float h = .070f + ((row + col) % 2) * .018f;
                    Color stone = Color.Lerp(new Color(.34f, .32f, .235f, alpha), new Color(.18f, .155f, .105f, alpha * .86f), rowT * .64f);
                    RectObj(name + "_AdventureMosaicRoundedStoneBlock_NoCollision_" + row + "_" + col, parent, new Vector2(x, y), new Vector2(w, h), stone, 8);
                    if ((row + col) % 2 == 0)
                        RectObj(name + "_AdventureMosaicMossInStoneCrevice_NoCollision_" + row + "_" + col, parent, new Vector2(x - w * .18f, y + h * .58f), new Vector2(w * .46f, .010f), new Color(.24f, .44f, .13f, alpha * .38f), 9);
                }
            }

            for (int i = 0; i < 3; i++)
            {
                float drop = .14f + i * .105f;
                RectObj(name + "_AdventureMosaicLeftSideGrassRoot_NoCollision_" + i, parent, new Vector2(leftX + .12f + i * .040f, topY - drop), new Vector2(.028f, .15f + i * .030f), new Color(.12f, .32f, .070f, alpha * .46f), 11).transform.localRotation = Quaternion.Euler(0f, 0f, -8f - i * 3f);
                RectObj(name + "_AdventureMosaicRightSideGrassRoot_NoCollision_" + i, parent, new Vector2(rightX - .12f - i * .040f, topY - drop), new Vector2(.028f, .14f + i * .028f), new Color(.11f, .29f, .065f, alpha * .42f), 11).transform.localRotation = Quaternion.Euler(0f, 0f, 8f + i * 3f);
            }
        }

