            float rightX = pos.x + size.x * .50f;
            float faceHeight = Mathf.Clamp(size.y * .78f, .50f, .86f);
            float faceY = topY - .20f - faceHeight * .50f;
            float faceAlpha = hasPlatformArt ? .16f : .46f;
            float grassAlpha = hasPlatformArt ? .24f : .68f;
            float stoneAlpha = hasPlatformArt ? .15f : .42f;

            RectObj(name + "_AdventurePlayableBlockContinuousGrassCrown_NoCollision", parent, new Vector2(pos.x, topY + .050f), new Vector2(size.x * 1.10f, .082f), new Color(.38f, .66f, .18f, grassAlpha), 13);
            RectObj(name + "_AdventurePlayableBlockBrightTopLip_NoCollision", parent, new Vector2(pos.x, topY + .104f), new Vector2(size.x * .90f, .020f), new Color(.76f, .90f, .34f, grassAlpha * .34f), 14);
            RectObj(name + "_AdventurePlayableBlockRootRim_NoCollision", parent, new Vector2(pos.x, topY - .030f), new Vector2(size.x * .98f, .032f), new Color(.070f, .16f, .050f, faceAlpha * .95f), 10);
            RectObj(name + "_AdventurePlayableBlockOpaqueSoilFace_NoBackgroundLeak", parent, new Vector2(pos.x, faceY), new Vector2(size.x * .98f, faceHeight), new Color(.24f, .205f, .130f, faceAlpha), 6);
            RectObj(name + "_AdventurePlayableBlockLowerStoneMass_NoBackgroundLeak", parent, new Vector2(pos.x, faceY - faceHeight * .22f), new Vector2(size.x * .78f, faceHeight * .34f), new Color(.115f, .105f, .078f, faceAlpha * .86f), 5);
            RectObj(name + "_AdventurePlayableBlockBottomOcclusion_NoBackgroundLeak", parent, new Vector2(pos.x, faceY - faceHeight * .53f), new Vector2(size.x * .54f, .032f), new Color(.060f, .054f, .038f, hasPlatformArt ? .060f : .20f), 5);
            RectObj(name + "_AdventurePlayableBlockLeftEndFace_NoCollision", parent, new Vector2(leftX + .075f, faceY + faceHeight * .05f), new Vector2(.16f, faceHeight * .78f), new Color(.15f, .128f, .086f, hasPlatformArt ? .12f : .42f), 7);
            RectObj(name + "_AdventurePlayableBlockRightEndFace_NoCollision", parent, new Vector2(rightX - .075f, faceY + faceHeight * .04f), new Vector2(.16f, faceHeight * .74f), new Color(.13f, .114f, .080f, hasPlatformArt ? .11f : .38f), 7);

            int slabCount = Mathf.Clamp(Mathf.RoundToInt(size.x * 1.35f), 4, 8);
            for (int i = 0; i < slabCount; i++)
            {
                float t = (i + .5f) / slabCount;
                float x = Mathf.Lerp(leftX + size.x * .13f, rightX - size.x * .13f, t);
                float y = faceY + faceHeight * (.22f - (i % 3) * .18f);
                float w = Mathf.Clamp(size.x / slabCount * (.56f + (i % 2) * .12f), .20f, .42f);
                RectObj(name + "_AdventurePlayableBlockReadableStoneSlab_NoCollision_" + i, parent, new Vector2(x, y), new Vector2(w, .060f), new Color(.39f, .36f, .26f, stoneAlpha), 8);
                RectObj(name + "_AdventurePlayableBlockCreviceMoss_NoCollision_" + i, parent, new Vector2(x - w * .18f, y + .043f), new Vector2(w * .48f, .010f), new Color(.24f, .42f, .12f, stoneAlpha * .42f), 9);
            }

            int grassThreadCount = Mathf.Clamp(Mathf.RoundToInt(size.x * 1.10f), 3, 7);
            for (int i = 0; i < grassThreadCount; i++)
            {
                float t = grassThreadCount <= 1 ? .5f : i / (grassThreadCount - 1f);
                float x = Mathf.Lerp(leftX + .20f, rightX - .20f, t);
                float length = .11f + (i % 4) * .032f;
                var thread = RectObj(name + "_AdventurePlayableBlockShortRootThread_NoCollision_" + i, parent, new Vector2(x, topY - .08f - length * .50f), new Vector2(.012f, length), new Color(.12f, .31f, .070f, grassAlpha * .28f), 11);
                thread.transform.localRotation = Quaternion.Euler(0f, 0f, -6f + i * 2.5f);
            }
        }

