            RectObj(name + "_AdventureReadableWalkableBrightLip_NoCollision", parent, new Vector2(pos.x, topY + .138f), new Vector2(size.x * .84f, .026f), new Color(.78f, .90f, .34f, capAlpha * .30f), 15);
