        private void BuildPlatformAdventureKingSolidSideLanguage(string name, Vector2 pos, Vector2 size, bool hasPlatformArt)
        {
            Transform parent = mapLayoutRoot ? mapLayoutRoot : world;
            float topY = pos.y + size.y * .50f + PlatformVisualRootToWalkableTop;
            float leftX = pos.x - size.x * .50f;
            float rightX = pos.x + size.x * .50f;
            float faceHeight = Mathf.Clamp(size.y * 1.08f, .72f, 1.18f);
            float faceCenterY = topY - .24f - faceHeight * .50f;
            float artBlend = hasPlatformArt ? .70f : 1f;
            float soilAlpha = hasPlatformArt ? .38f : .86f;
            float stoneAlpha = hasPlatformArt ? .30f : .70f;
            float rimAlpha = hasPlatformArt ? .32f : .76f;

            RectObj(name + "_AdventureKingSolidReadableSoilWall_NoBackgroundLeak", parent, new Vector2(pos.x, faceCenterY), new Vector2(size.x * 1.03f, faceHeight), new Color(.20f, .165f, .102f, soilAlpha), 6);
            RectObj(name + "_AdventureKingSolidReadableStoneBelly_NoBackgroundLeak", parent, new Vector2(pos.x, faceCenterY - faceHeight * .25f), new Vector2(size.x * .82f, faceHeight * .34f), new Color(.095f, .086f, .064f, stoneAlpha), 5);
            RectObj(name + "_AdventureKingSolidReadableBottomSeal_NoBackgroundLeak", parent, new Vector2(pos.x, faceCenterY - faceHeight * .54f), new Vector2(size.x * .66f, .046f), new Color(.045f, .040f, .030f, hasPlatformArt ? .12f : .30f), 5);
            RectObj(name + "_AdventureKingSolidReadableTopRootShade_NoCollision", parent, new Vector2(pos.x, topY - .044f), new Vector2(size.x * 1.06f, .072f), new Color(.045f, .105f, .035f, rimAlpha * .42f), 13);
            RectObj(name + "_AdventureKingSolidReadableGrassCrown_NoCollision", parent, new Vector2(pos.x, topY + .072f), new Vector2(size.x * 1.14f, .105f), new Color(.36f, .62f, .15f, rimAlpha), 17);
            RectObj(name + "_AdventureKingSolidReadableFootLip_NoCollision", parent, new Vector2(pos.x, topY + .150f), new Vector2(size.x * .96f, .026f), new Color(.82f, .92f, .36f, rimAlpha * .34f), 20);
            RectObj(name + "_AdventureKingSolidReadableFootAo_NoCollision", parent, new Vector2(pos.x, topY - .006f), new Vector2(size.x * .54f, .014f), new Color(.012f, .026f, .016f, hasPlatformArt ? .055f : .14f), 19);
            RectObj(name + "_AdventureKingSolidReadableLeftEnd_NoCollision", parent, new Vector2(leftX + .082f, faceCenterY + faceHeight * .05f), new Vector2(.164f, faceHeight * .82f), new Color(.12f, .102f, .068f, soilAlpha * .68f), 8);
            RectObj(name + "_AdventureKingSolidReadableRightEnd_NoCollision", parent, new Vector2(rightX - .082f, faceCenterY + faceHeight * .03f), new Vector2(.164f, faceHeight * .78f), new Color(.11f, .095f, .064f, soilAlpha * .62f), 8);

            int blockCount = Mathf.Clamp(Mathf.RoundToInt(size.x * 1.70f), 5, 11);
            for (int i = 0; i < blockCount; i++)
            {
                float t = (i + .5f) / blockCount;
                float x = Mathf.Lerp(leftX + size.x * .10f, rightX - size.x * .10f, t);
                float row = i % 3;
                float y = faceCenterY + faceHeight * (.23f - row * .18f);
                float w = Mathf.Clamp(size.x / blockCount * (.64f + (i % 3) * .08f), .18f, .46f);
                RectObj(name + "_AdventureKingSolidReadableRoundedStone_NoCollision_" + i, parent, new Vector2(x, y), new Vector2(w, .068f), new Color(.38f, .35f, .25f, stoneAlpha * artBlend), 10);
                if (i % 2 == 0)
                    RectObj(name + "_AdventureKingSolidReadableMossSeam_NoCollision_" + i, parent, new Vector2(x - w * .18f, y + .045f), new Vector2(w * .50f, .012f), new Color(.22f, .42f, .11f, rimAlpha * .20f), 11);
            }

