        }

        private void BuildPlatformAdventureStorybookTileFace(string name, Vector2 pos, Vector2 size, bool hasPlatformArt)
        {
            Transform parent = mapLayoutRoot ? mapLayoutRoot : world;
            float topY = pos.y + size.y * .50f + PlatformVisualRootToWalkableTop;
            float leftX = pos.x - size.x * .50f;
            float rightX = pos.x + size.x * .50f;
            float faceHeight = Mathf.Clamp(size.y * .86f, .54f, .94f);
            float faceY = topY - .22f - faceHeight * .50f;
            float faceAlpha = hasPlatformArt ? .18f : .50f;
            float stoneAlpha = hasPlatformArt ? .16f : .40f;
            float grassAlpha = hasPlatformArt ? .28f : .70f;

            RectObj(name + "_AdventureStorybookTileGrassShelf_NoCollision", parent, new Vector2(pos.x, topY + .078f), new Vector2(size.x * 1.08f, .074f), new Color(.38f, .66f, .17f, grassAlpha), 16);
            RectObj(name + "_AdventureStorybookTileSoilMass_NoBackgroundLeak", parent, new Vector2(pos.x, faceY), new Vector2(size.x * .96f, faceHeight), new Color(.22f, .18f, .11f, faceAlpha), 6);
            RectObj(name + "_AdventureStorybookTileStoneBelly_NoBackgroundLeak", parent, new Vector2(pos.x, faceY - faceHeight * .25f), new Vector2(size.x * .74f, faceHeight * .34f), new Color(.10f, .092f, .070f, faceAlpha * .82f), 5);
