            RectObj(name + "_AdventureStorybookTileFootAo_NoCollision", parent, new Vector2(pos.x, topY - .028f), new Vector2(size.x * .52f, .016f), new Color(.015f, .030f, .018f, hasPlatformArt ? .040f : .090f), 15);

            int blockCount = Mathf.Clamp(Mathf.RoundToInt(size.x * 1.45f), 4, 9);
