        private void BuildPlatformStageModuleSilhouette(string name, Vector2 pos, Vector2 size, bool hasPlatformArt)
        {
            Transform parent = mapLayoutRoot ? mapLayoutRoot : world;
            float topY = pos.y + size.y * .50f + PlatformVisualRootToWalkableTop;
            float bodyHeight = Mathf.Max(.66f, size.y * (hasPlatformArt ? .96f : 1.05f));
            float alpha = hasPlatformArt ? .085f : .30f;
            float edgeAlpha = hasPlatformArt ? .12f : .44f;
            float grassAlpha = hasPlatformArt ? .16f : .54f;
            float leftX = pos.x - size.x * .50f;
            float rightX = pos.x + size.x * .50f;

            RectObj(name + "_AdventurePlatformModuleSolidCore_NoCollision", parent, new Vector2(pos.x, topY - bodyHeight * .43f), new Vector2(size.x * .76f, bodyHeight * .48f), new Color(.21f, .185f, .125f, alpha), 4);
            RectObj(name + "_AdventurePlatformModuleStoneBelly_NoCollision", parent, new Vector2(pos.x, topY - bodyHeight * .62f), new Vector2(size.x * .58f, bodyHeight * .20f), new Color(.12f, .110f, .082f, alpha * .82f), 4);
            RectObj(name + "_AdventurePlatformModuleLeftEndCap_NoCollision", parent, new Vector2(leftX + size.x * .070f, topY - bodyHeight * .34f), new Vector2(size.x * .085f, bodyHeight * .46f), new Color(.15f, .130f, .088f, edgeAlpha), 5);
            RectObj(name + "_AdventurePlatformModuleRightEndCap_NoCollision", parent, new Vector2(rightX - size.x * .070f, topY - bodyHeight * .34f), new Vector2(size.x * .085f, bodyHeight * .44f), new Color(.14f, .122f, .084f, edgeAlpha * .92f), 5);
            RectObj(name + "_AdventurePlatformModuleTopGrassCushion_NoCollision", parent, new Vector2(pos.x, topY + .035f), new Vector2(size.x * .68f, .030f), new Color(.32f, .56f, .15f, grassAlpha), 12);
            RectObj(name + "_AdventurePlatformModuleFootAo_NoCollision", parent, new Vector2(pos.x, topY - bodyHeight * .78f), new Vector2(size.x * .42f, .020f), new Color(.018f, .034f, .022f, hasPlatformArt ? .020f : .13f), 5);

            int stoneBands = Mathf.Clamp(Mathf.RoundToInt(size.x * .85f), 3, 6);
            for (int i = 0; i < stoneBands; i++)
            {
                float t = (i + .5f) / stoneBands;
                float x = Mathf.Lerp(leftX + size.x * .18f, rightX - size.x * .18f, t);
                float y = topY - bodyHeight * (.35f + (i % 3) * .12f);
                float w = size.x * (.055f + (i % 2) * .020f);
                RectObj(name + "_AdventurePlatformModuleStoneBand_NoCollision_" + i, parent, new Vector2(x, y), new Vector2(w, .024f), new Color(.40f, .37f, .27f, hasPlatformArt ? .026f : .24f), 5);
                if (i % 2 == 0)
                    RectObj(name + "_AdventurePlatformModuleMossPocket_NoCollision_" + i, parent, new Vector2(x - w * .16f, y + .035f), new Vector2(w * .52f, .010f), new Color(.20f, .38f, .10f, hasPlatformArt ? .026f : .28f), 6);
            }

            int grassTufts = Mathf.Clamp(Mathf.RoundToInt(size.x * 1.10f), 3, 7);
            for (int i = 0; i < grassTufts; i++)
            {
                float t = (i + .45f) / grassTufts;
                float x = Mathf.Lerp(leftX + size.x * .12f, rightX - size.x * .12f, t);
                float h = .070f + (i % 3) * .024f;
                var blade = RectObj(name + "_AdventurePlatformModuleTopGrassBlade_NoCollision_" + i, parent, new Vector2(x, topY + .045f + h * .42f), new Vector2(.014f, h), new Color(.20f, .42f, .085f, grassAlpha * .72f), 13);
                blade.transform.localRotation = Quaternion.Euler(0f, 0f, -7f + i * 3.5f);
            }

            for (int i = 0; i < 3; i++)
            {
                float x = i == 0 ? leftX + size.x * .18f : i == 1 ? pos.x : rightX - size.x * .18f;
                float w = size.x * (.060f + i * .010f);
                RectObj(name + "_AdventurePlatformModuleBottomChunk_NoCollision_" + i, parent, new Vector2(x, topY - bodyHeight * (.84f + i * .018f)), new Vector2(w, .034f), new Color(.10f, .092f, .070f, hasPlatformArt ? .036f : .26f), 4);
            }
        }

        private void BuildPlatformSceneAnchors(string name, Vector2 pos, Vector2 size, bool hasPlatformArt)
        {
            Transform parent = mapLayoutRoot ? mapLayoutRoot : world;
            float platformBottom = pos.y - size.y * .50f + .04f;
            float groundTop = GroundY + .54f;
            float supportHeight = platformBottom - groundTop;
            if (supportHeight <= .34f) return;

            int supportCount = hasPlatformArt ? (size.x >= 3.0f ? 2 : 1) : (size.x >= 3.7f ? 2 : 1);
            float spread = supportCount == 1 ? 0f : size.x * .23f;
            for (int i = 0; i < supportCount; i++)
            {
                float offset = supportCount == 1 ? 0f : Mathf.Lerp(-spread, spread, i);
                float x = pos.x + offset;
                float centerY = groundTop + supportHeight * .50f;
                float pillarWidth = Mathf.Clamp(size.x * (supportCount == 1 ? .14f : .095f), .20f, .40f);
                float alpha = hasPlatformArt ? .095f : .34f;
                RectObj(name + "_AdventurePlatformStoneSupportPillar_NoCollision_" + i, parent, new Vector2(x, centerY), new Vector2(pillarWidth * .34f, supportHeight * .60f), new Color(.18f, .165f, .115f, alpha * .30f), 3);
                RectObj(name + "_AdventurePlatformSupportMossFace_NoCollision_" + i, parent, new Vector2(x - pillarWidth * .18f, centerY + supportHeight * .18f), new Vector2(pillarWidth * .16f, supportHeight * .26f), new Color(.16f, .34f, .095f, alpha * .26f), 4);
                RectObj(name + "_AdventurePlatformSupportDarkSide_NoCollision_" + i, parent, new Vector2(x + pillarWidth * .28f, centerY), new Vector2(pillarWidth * .052f, supportHeight * .40f), new Color(.065f, .070f, .050f, alpha * .28f), 4);
                RectObj(name + "_AdventurePlatformSupportBaseAo_NoCollision_" + i, parent, new Vector2(x, groundTop - .045f), new Vector2(pillarWidth * 1.42f, .038f), new Color(.025f, .040f, .024f, hasPlatformArt ? .055f : .16f), 5);

                int seamCount = Mathf.Clamp(Mathf.RoundToInt(supportHeight * 1.3f), 2, 5);
                for (int j = 0; j < seamCount; j++)
                {
                    float t = (j + .5f) / seamCount;
                    float y = Mathf.Lerp(groundTop + .12f, platformBottom - .12f, t);
                    RectObj(name + "_AdventurePlatformSupportStoneSeam_NoCollision_" + i + "_" + j, parent, new Vector2(x + ((j % 2 == 0) ? -.035f : .040f), y), new Vector2(pillarWidth * .40f, .014f), new Color(.42f, .39f, .29f, hasPlatformArt ? .034f : .22f), 5);
                    RectObj(name + "_AdventurePlatformBrokenPierStone_NoCollision_" + i + "_" + j, parent, new Vector2(x + ((j % 2 == 0) ? -.025f : .032f), y - .050f), new Vector2(pillarWidth * (.40f + (j % 2) * .080f), .030f), new Color(.32f, .31f, .23f, hasPlatformArt ? .070f : .32f), 5);
                    if (j % 2 == 0)
                        RectObj(name + "_AdventurePlatformPierMossChip_NoCollision_" + i + "_" + j, parent, new Vector2(x - pillarWidth * .16f, y - .015f), new Vector2(pillarWidth * .24f, .012f), new Color(.22f, .40f, .11f, hasPlatformArt ? .052f : .24f), 6);
                }
            }

            int vineCount = Mathf.Clamp(Mathf.RoundToInt(size.x * .55f), 2, 4);
            for (int i = 0; i < vineCount; i++)
            {
                float t = (i + .50f) / vineCount;
                float x = Mathf.Lerp(pos.x - size.x * .38f, pos.x + size.x * .38f, t);
                float length = Mathf.Clamp(supportHeight * (.28f + (i % 3) * .09f), .28f, .86f);
                RectObj(name + "_AdventurePlatformHangingRoot_NoCollision_" + i, parent, new Vector2(x, platformBottom - length * .50f), new Vector2(.012f + (i % 2) * .005f, length * .58f), new Color(.11f, .28f, .075f, hasPlatformArt ? .085f : .42f), 6);
            }

            if (hasPlatformArt)
            {
                int shardCount = Mathf.Clamp(Mathf.RoundToInt(size.x * 1.05f), 3, 6);
                for (int i = 0; i < shardCount; i++)
                {
                    float t = (i + .50f) / shardCount;
                    float x = Mathf.Lerp(pos.x - size.x * .32f, pos.x + size.x * .32f, t);
                    float y = groundTop + supportHeight * (.26f + (i % 3) * .13f);
                    RectObj(name + "_AdventurePlatformBackfillBrokenStone_NoCollision_" + i, parent, new Vector2(x, y), new Vector2(size.x * (.055f + (i % 2) * .018f), .030f), new Color(.32f, .31f, .23f, .060f), 3);
                    RectObj(name + "_AdventurePlatformBackfillRootThread_NoCollision_" + i, parent, new Vector2(x + .04f, y + .08f), new Vector2(.012f, Mathf.Clamp(supportHeight * .14f, .12f, .28f)), new Color(.10f, .26f, .070f, .055f), 4);
                }

                int leafCount = Mathf.Clamp(Mathf.RoundToInt(size.x * 1.35f), 4, 8);
                for (int i = 0; i < leafCount; i++)
                {
                    float t = (i + .35f) / leafCount;
                    float x = Mathf.Lerp(pos.x - size.x * .38f, pos.x + size.x * .38f, t);
                    float y = groundTop + supportHeight * (.54f + (i % 2) * .09f);
                    RectObj(name + "_AdventurePlatformBackfillLeafFleck_NoCollision_" + i, parent, new Vector2(x, y), new Vector2(.070f + (i % 2) * .022f, .016f), new Color(.18f, .38f, .10f, .055f), 5);
                }
            }
        }

        private void BuildPlatformSolidFooting(string name, Vector2 pos, Vector2 size)
        {
            Transform parent = mapLayoutRoot ? mapLayoutRoot : world;
            float topY = pos.y + size.y * .50f + .08f;
            float grassRootY = topY - .15f;
            float dirtY = topY - Mathf.Max(.44f, size.y * .62f);
            float underY = topY - Mathf.Max(.78f, size.y * .98f);
            float bodyHeight = Mathf.Max(.62f, size.y * .92f);
            float underHeight = Mathf.Max(.22f, size.y * .34f);

            RectObj(name + "_AdventureSolidDirtCore", parent, new Vector2(pos.x, dirtY), new Vector2(size.x * 1.02f, bodyHeight), new Color(.22f, .19f, .13f, .98f), 2);
            RectObj(name + "_AdventureSolidDirtWarmFace", parent, new Vector2(pos.x, dirtY + bodyHeight * .18f), new Vector2(size.x * .96f, bodyHeight * .42f), new Color(.33f, .27f, .17f, .38f), 3);
            RectObj(name + "_AdventureSolidStoneMass", parent, new Vector2(pos.x, underY), new Vector2(size.x * .88f, underHeight), new Color(.12f, .105f, .080f, .96f), 2);
            RectObj(name + "_AdventureSolidGrassRootBand", parent, new Vector2(pos.x, grassRootY), new Vector2(size.x * 1.06f, .18f), new Color(.13f, .30f, .070f, .99f), 4);
            RectObj(name + "_AdventureSolidGrassFace", parent, new Vector2(pos.x, grassRootY + .062f), new Vector2(size.x * 1.04f, .16f), new Color(.24f, .46f, .12f, .98f), 4);
            RectObj(name + "_AdventureSolidWalkableGrassCap", parent, new Vector2(pos.x, topY), new Vector2(size.x * 1.08f, .14f), new Color(.42f, .66f, .20f, .99f), 5);
            RectObj(name + "_AdventureSolidSunlitTopEdge", parent, new Vector2(pos.x, topY + .074f), new Vector2(size.x * .82f, .026f), new Color(.72f, .88f, .34f, .54f), 6);
            RectObj(name + "_AdventureSolidUndersideAo", parent, new Vector2(pos.x, underY - underHeight * .50f), new Vector2(size.x * .72f, .024f), new Color(.07f, .075f, .040f, .08f), 3);
            RectObj(name + "_AdventureSolidLeftBrokenEdge", parent, new Vector2(pos.x - size.x * .52f, dirtY - bodyHeight * .05f), new Vector2(size.x * .08f, bodyHeight * .58f), new Color(.19f, .175f, .12f, .82f), 3);
            RectObj(name + "_AdventureSolidRightBrokenEdge", parent, new Vector2(pos.x + size.x * .52f, dirtY - bodyHeight * .03f), new Vector2(size.x * .07f, bodyHeight * .52f), new Color(.18f, .165f, .115f, .78f), 3);

            int capBlockCount = Mathf.Clamp(Mathf.RoundToInt(size.x * 1.25f), 3, 7);
            for (int i = 0; i < capBlockCount; i++)
            {
                float t = (i + .5f) / capBlockCount;
                float x = Mathf.Lerp(pos.x - size.x * .45f, pos.x + size.x * .45f, t);
                float w = size.x * (.105f + (i % 3) * .020f);
                float y = topY - .045f - (i % 2) * .010f;
                RectObj(name + "_AdventureSolidTopStoneBlock_" + i, parent, new Vector2(x, y), new Vector2(w, .070f), new Color(.31f, .33f, .24f, .40f), 5);
                RectObj(name + "_AdventureSolidTopMossPatch_" + i, parent, new Vector2(x - w * .12f, topY + .030f + (i % 2) * .008f), new Vector2(w * .82f, .034f), new Color(.32f, .55f, .16f, .58f), 7);
            }

            int seamCount = Mathf.Clamp(Mathf.RoundToInt(size.x), 2, 5);
            for (int i = 0; i < seamCount; i++)
            {
                float t = (i + .5f) / seamCount;
                float x = Mathf.Lerp(pos.x - size.x * .38f, pos.x + size.x * .38f, t);
                float y = dirtY + ((i % 2 == 0) ? .090f : -.070f);
                float w = Mathf.Lerp(size.x * .12f, size.x * .20f, (i % 3) / 2f);
                RectObj(name + "_AdventureSolidStonePocket_" + i, parent, new Vector2(x, y), new Vector2(w, .040f), new Color(.40f, .38f, .29f, .28f), 6);
                RectObj(name + "_AdventureSolidDirtGrain_" + i, parent, new Vector2(x + .20f, y - .18f), new Vector2(w * .55f, .022f), new Color(.45f, .41f, .30f, .12f), 6);
            }

            int chunkCount = Mathf.Clamp(Mathf.RoundToInt(size.x * 1.28f), 3, 7);
            for (int i = 0; i < chunkCount; i++)
            {
                float t = (i + .5f) / chunkCount;
                float x = Mathf.Lerp(pos.x - size.x * .42f, pos.x + size.x * .42f, t);
                float drop = .035f + (i % 4) * .030f;
                float w = size.x * (.11f + (i % 3) * .020f);
                float h = .050f + (i % 2) * .030f;
                RectObj(name + "_AdventureSolidUnevenBottomChunk_" + i, parent, new Vector2(x, underY - underHeight * .46f - drop), new Vector2(w, h), new Color(.10f, .090f, .065f, .74f), 3);
            }

            int tuftCount = Mathf.Clamp(Mathf.RoundToInt(size.x * 1.15f), 2, 6);
            for (int i = 0; i < tuftCount; i++)
            {
                float t = (i + .5f) / tuftCount;
                float x = Mathf.Lerp(pos.x - size.x * .45f, pos.x + size.x * .45f, t);
                float length = .11f + (i % 3) * .034f;
                RectObj(name + "_AdventureSolidGrassTuft_" + i, parent, new Vector2(x, grassRootY - length * .30f), new Vector2(.060f + (i % 2) * .034f, length), new Color(.15f, .35f, .075f, .74f), 6);
            }
        }

        private void BuildPlatformRouteBreadcrumbs()
        {
            if (!mapLayoutRoot || platforms.Count <= 0) return;
            if (ShouldSuppressPersistentPlatformRouteBreadcrumbs()) return;
            var ordered = platforms
                .OrderBy(p => (p.Left + p.Right) * .5f)
                .ToList();

            int rewardHintCount = 0;
            float lastRewardHintX = -999f;
            for (int i = 0; i < ordered.Count; i++)
            {
                Platform platform = ordered[i];
                float centerX = (platform.Left + platform.Right) * .5f;
                float routeY = platform.Top + .08f;
                bool elevated = routeY > GroundY + 1.60f;
                bool rewardLane = elevated && i % 2 == 0 && rewardHintCount < 3 && centerX - lastRewardHintX >= 8.4f;
                if (!rewardLane) continue;
                rewardHintCount++;
                lastRewardHintX = centerX;

                RectObj("PlatformRouteBreadcrumbTick_NoYellowPlate_" + i, mapLayoutRoot, new Vector2(centerX, routeY), new Vector2(Mathf.Clamp(platform.Width * .04f, .05f, .08f), .0015f), new Color(.74f, .96f, 1f, .002f), 5);
                RectObj("PlatformRouteRewardNudge_NoYellowPlate_" + i, mapLayoutRoot, new Vector2(centerX + Mathf.Min(.10f, platform.Width * .04f), routeY + .05f), new Vector2(.014f, .0015f), new Color(.86f, 1f, 1f, .002f), 6);

                if (i <= 0) continue;
                Platform previous = ordered[i - 1];
                float previousCenterX = (previous.Left + previous.Right) * .5f;
                float distance = centerX - previousCenterX;
                if (distance <= 0f || distance > 5.8f) continue;

                float midX = (centerX + previousCenterX) * .5f;
                float midY = Mathf.Lerp(previous.Top, platform.Top, .58f) + .20f;
                float lineWidth = Mathf.Clamp(distance * .10f, .18f, .42f);
                RectObj("PlatformRouteBreadcrumbLine_NoYellowPlate_" + i, mapLayoutRoot, new Vector2(midX, midY), new Vector2(lineWidth, .0015f), new Color(.60f, .93f, 1f, .0015f), 4);
            }
        }

        private static bool ShouldSuppressPersistentPlatformRouteBreadcrumbs()
        {
            return true;
        }

        public string DebugAuditMapLayoutReachability(int layout)
        {
            ResetMapLayoutRoot();
            BuildStageMapLayoutByIndex(Mathf.Clamp(layout, 0, 3));
            var ordered = platforms
                .OrderBy(p => (p.Left + p.Right) * .5f)
                .ToList();
            var lines = new List<string>
            {
                $"layout={Mathf.Clamp(layout, 0, 3)} name={MapLayoutName(activeMapLayoutIndex)} platforms={ordered.Count}"
            };

            float groundTop = GroundY + .72f;
            float previousRight = 0f;
            float previousTop = groundTop;
            int warnings = 0;
            for (int i = 0; i < ordered.Count; i++)
            {
                Platform p = ordered[i];
                float gap = i == 0 ? 0f : Mathf.Max(0f, p.Left - previousRight);
                float climb = p.Top - previousTop;
                string grade = RouteJumpGrade(gap, climb);
                if (grade.StartsWith("风险", StringComparison.Ordinal)) warnings++;
                lines.Add($"  {i:00}: x={((p.Left + p.Right) * .5f):0.00} width={p.Width:0.00} gap={gap:0.00} climb={climb:0.00} top={p.Top:0.00} {grade}");
                previousRight = Mathf.Max(previousRight, p.Right);
                previousTop = p.Top;
            }

            for (int i = 0; i < SegmentRights.Length; i++)
            {
                float left = i == 0 ? LeftBound : SegmentRights[i - 1];
                float right = SegmentRights[i];
                int roomPlatformCount = ordered.Count(p => p.Right >= left + .35f && p.Left <= right - .35f);
                bool routeGroundAnchor = true;
                bool exitCue = i < SegmentRights.Length - 1 || i == BossRoomIndex;
                bool enoughPlayableLanguage = roomPlatformCount > 0 || i == BossRoomIndex;
                if (!routeGroundAnchor || !exitCue || !enoughPlayableLanguage) warnings++;
                lines.Add($"  room-readability-{i}: platforms={roomPlatformCount} combatLane={(routeGroundAnchor ? "ok" : "missing")} exitCue={(exitCue ? "ok" : "missing")} {(enoughPlayableLanguage ? "ok" : "thin")}");
            }

            var airDecorNames = world
                ? world.GetComponentsInChildren<Transform>(true)
                    .Where(t => t && t.name.StartsWith("AirDecor_", StringComparison.Ordinal))
                    .Select(t => t.name)
                    .ToList()
                : new List<string>();
            int airDecorCount = airDecorNames.Count;
            int topFillCount = airDecorNames.Count(name =>
                name.Contains("TreetopCluster")
                || name.Contains("UpperBranch")
                || name.Contains("CanopyCeiling")
                || name.Contains("UpperCanopyRim")
                || name.Contains("NearCanopyFrame")
                || name.Contains("ThinVines")
                || name.Contains("Painted"));
            int paintedSpriteCount = airDecorNames.Count(name => name.Contains("Painted"));
            int cloudBankCount = airDecorNames.Count(name => name.Contains("SoftCloudBank"));
            int cloudEllipseCount = airDecorNames.Count(name => name.Contains("SoftCloudBank") && name.Contains("SoftEllipse"));
            int cloudRectRiskCount = airDecorNames.Count(name => name.Contains("SoftCloudBank") && (name.Contains("_Puff_") || name.Contains("_Underside_") || name.Contains("_HorizonBlend")));
            int softLeafEllipseCount = airDecorNames.Count(name => name.Contains("SoftLeafEllipse"));
            int branchRectRiskCount = airDecorNames.Count(name => name.Contains("_LeafMass_") || name.Contains("_Branch_"));
            bool airDecorNoCollision = airDecorNames.All(name => name.Contains("NoCollision"));
            bool airDecorOk = airDecorCount >= 36 && topFillCount >= 8 && paintedSpriteCount >= 8 && cloudBankCount >= 8 && airDecorNoCollision;
            bool airCloudShapeOk = cloudEllipseCount >= 24 && cloudRectRiskCount == 0;
            bool airLeafShapeOk = paintedSpriteCount >= 8 && branchRectRiskCount == 0;
            if (!airDecorOk) warnings++;
            if (!airCloudShapeOk) warnings++;
            if (!airLeafShapeOk) warnings++;
            lines.Add($"  air-decoration: count={airDecorCount} topFill={topFillCount} painted={paintedSpriteCount} cloudBank={cloudBankCount} noCollision={airDecorNoCollision} {(airDecorOk ? "ok" : "thin")}");
            lines.Add($"  air-cloud-shape: ellipse={cloudEllipseCount} rectRisk={cloudRectRiskCount} {(airCloudShapeOk ? "ok" : "dirty-rect-risk")}");
            lines.Add($"  air-leaf-shape: painted={paintedSpriteCount} softEllipse={softLeafEllipseCount} rectRisk={branchRectRiskCount} {(airLeafShapeOk ? "ok" : "dirty-rect-risk")}");

            for (int i = 0; i < SegmentRights.Length - 1; i++)
            {
                float doorGap = SegmentRights[i] + .18f - previousRight;
                if (doorGap > 5.4f)
                {
                    warnings++;
                    lines.Add($"  gate-{i}: risk long approach gap={doorGap:0.00}");
                }
            }

            string report = string.Join("\n", lines) + $"\nwarnings={warnings}";
            Debug.Log(report);
            return report;
        }

        public string DebugAuditMovementUnstuck()
        {
            if (!player)
                throw new InvalidOperationException("Movement audit requires the player object.");

            var lines = new List<string> { "movement-unstuck-audit" };
            int warnings = 0;

            Vector3 originalPlayerPosition = player.transform.position;
            float originalVerticalVelocity = verticalVelocity;
            bool originalGrounded = grounded;
            bool originalInputLocked = inputLocked;
            bool originalRollingRune = rollingRune;
            bool originalChoosingReward = choosingRoomReward;
            bool originalStageRuneResolved = stageRuneResolved;
            bool originalTitleActive = titleActive;
            bool originalPaused = paused;
            bool originalControlEditMode = controlEditMode;
            int originalSegment = currentSegment;
            var originalEnemyDeadStates = enemies.Select(enemy => new { enemy, dead = enemy.Dead }).ToList();

            inputLocked = true;
            rollingRune = false;
            choosingRoomReward = false;
            stageRuneResolved = false;
            titleActive = false;
            paused = false;
            controlEditMode = false;
            if (titlePanel) titlePanel.gameObject.SetActive(false);
            if (pausePanel) pausePanel.gameObject.SetActive(false);
            if (settingsPanel) settingsPanel.gameObject.SetActive(false);
            if (shopPanel) shopPanel.gameObject.SetActive(false);
            if (achievementPanel) achievementPanel.gameObject.SetActive(false);
            if (runeCodexPanel) runeCodexPanel.gameObject.SetActive(false);
            if (aboutPanel) aboutPanel.gameObject.SetActive(false);
            RecoverMovementInputLockIfPossible();
            if (inputLocked)
            {
                warnings++;
                lines.Add("  input-lock: failed to recover when no gameplay modal is open");
            }
            else
            {
                lines.Add("  input-lock: recovered when no gameplay modal is open");
            }

            inputLocked = true;
            stageRuneResolved = true;
            if (runePanel) runePanel.gameObject.SetActive(false);
            if (victoryPanel) victoryPanel.gameObject.SetActive(false);
            RecoverMovementInputLockIfPossible();
            if (inputLocked)
            {
                warnings++;
                lines.Add("  stage-rune-lock: failed to recover after rune resolved without a visible modal");
            }
            else
            {
                lines.Add("  stage-rune-lock: recovered after rune resolved without a visible modal");
            }
            stageRuneResolved = false;

            for (int segment = 0; segment < SegmentRights.Length - 1; segment++)
            {
                currentSegment = segment;
                float roomStart = segment > 0 ? SegmentRights[segment - 1] : LeftBound;
                float expectedMinRight = SegmentRights[segment] - LockedGateStopBuffer - .001f;
                float movementRight = CurrentMovementRight();
                bool internalRoomReachable = movementRight >= expectedMinRight && movementRight > roomStart + 1.0f;
                if (!internalRoomReachable) warnings++;
                lines.Add($"  segment-{segment}: start={roomStart:0.00} movementRight={movementRight:0.00} expected>={expectedMinRight:0.00} {(internalRoomReachable ? "ok" : "blocked")}");
            }

            for (int segment = 0; segment < SegmentRights.Length - 1; segment++)
            {
                currentSegment = segment;
                float gateEnemyX = SegmentRights[segment] + .30f;
                var fakeEnemyRoot = new GameObject("DebugGateOverlapEnemy_" + segment);
                fakeEnemyRoot.transform.SetParent(world ? world : transform);
                fakeEnemyRoot.transform.position = new Vector3(gateEnemyX, GroundY + .72f, 0f);
                var fakeEnemy = new Fighter
                {
                    Kind = EnemyKind.Slime,
                    Root = fakeEnemyRoot,
                    Hp = 1f,
                    MaxHp = 1f,
                    Dead = false
                };
                enemies.Add(fakeEnemy);
                float movementRight = CurrentMovementRight();
                bool reachable = movementRight >= gateEnemyX + .22f;
                if (!reachable) warnings++;
                lines.Add($"  gate-overlap-enemy-{segment}: enemyX={gateEnemyX:0.00} movementRight={movementRight:0.00} {(reachable ? "ok" : "blocked")}");
                enemies.Remove(fakeEnemy);
                if (Application.isPlaying) Destroy(fakeEnemyRoot);
                else DestroyImmediate(fakeEnemyRoot);
            }

            for (int segment = 0; segment < SegmentRights.Length - 1; segment++)
            {
                currentSegment = segment;
                float staleBlockerX = segment > 0 ? SegmentRights[segment - 1] + .18f : LeftBound + 1.2f;
                var staleEnemyRoot = new GameObject("DebugStaleRoomBlocker_" + segment);
                staleEnemyRoot.transform.SetParent(world ? world : transform);
                staleEnemyRoot.transform.position = new Vector3(staleBlockerX, GroundY + .72f, 0f);
                var staleEnemy = new Fighter
                {
                    Kind = EnemyKind.Mushroom,
                    Root = staleEnemyRoot,
                    Hp = 1f,
                    MaxHp = 1f,
                    Dead = false
                };
                enemies.Add(staleEnemy);
                float crossedX = Mathf.Min(SegmentRights[segment] + ForcedSegmentCatchupMargin + .18f, RightBound - .6f);
                player.transform.position = new Vector3(crossedX, StableSupportYAtX(crossedX) + .02f, 0f);
                ReconcileMovementSegmentWithPlayerPosition();
                float movementRight = CurrentMovementRight();
                bool escaped = currentSegment >= Mathf.Clamp(SegmentIndexForX(crossedX), 0, SegmentRights.Length - 1) && movementRight > crossedX + .75f;
                if (!escaped) warnings++;
                lines.Add($"  stale-blocker-crossed-gate-{segment}: playerX={crossedX:0.00} segment={currentSegment} movementRight={movementRight:0.00} {(escaped ? "ok" : "blocked")}");
                enemies.Remove(staleEnemy);
                if (Application.isPlaying) Destroy(staleEnemyRoot);
                else DestroyImmediate(staleEnemyRoot);
            }

            for (int segment = 0; segment < SegmentRights.Length - 1; segment++)
            {
                foreach (var enemy in enemies)
                {
                    if (enemy != null)
                        enemy.Dead = true;
                }

                currentSegment = segment;
                float stalePlayerX = Mathf.Min(SegmentRights[segment] + .56f, RightBound - .6f);
                player.transform.position = new Vector3(stalePlayerX, StableSupportYAtX(stalePlayerX) + .02f, 0f);
                ReconcileMovementSegmentWithPlayerPosition();
                bool caughtUp = currentSegment >= Mathf.Clamp(SegmentIndexForX(stalePlayerX), 0, SegmentRights.Length - 1);
                if (!caughtUp) warnings++;
                lines.Add($"  stale-segment-catchup-{segment}: playerX={stalePlayerX:0.00} segment={currentSegment} {(caughtUp ? "ok" : "blocked")}");

                foreach (var state in originalEnemyDeadStates)
                    state.enemy.Dead = state.dead;
            }

            for (int segment = 0; segment < SegmentRights.Length - 1; segment++)
            {
                foreach (var enemy in enemies)
                {
                    if (enemy != null)
                        enemy.Dead = true;
                }

                currentSegment = segment;
                float gateEdgeX = Mathf.Min(SegmentRights[segment] - OpenRouteRightIntentGateGrace * .50f, RightBound - 1.0f);
                player.transform.position = new Vector3(gateEdgeX, StableSupportYAtX(gateEdgeX) + .02f, 0f);
                float beforeRight = Mathf.Min(CurrentMovementRight(), gateEdgeX + .05f);
                float afterRight = OpenRouteRightIntentFallback(gateEdgeX, beforeRight);
                bool opened = ShouldForceOpenRouteOnRightIntent(gateEdgeX, beforeRight) && afterRight >= gateEdgeX + OpenRouteRightIntentFallbackBoost - .02f;
                if (!opened) warnings++;
                lines.Add($"  open-route-right-intent-{segment}: playerX={gateEdgeX:0.00} before={beforeRight:0.00} after={afterRight:0.00} {(opened ? "ok" : "blocked")}");

                foreach (var state in originalEnemyDeadStates)
                    state.enemy.Dead = state.dead;
            }

            currentSegment = SegmentRights.Length - 1;
            float bossMovementRight = CurrentMovementRight();
            if (bossMovementRight < SegmentRights[SegmentRights.Length - 1] - .001f)
            {
                warnings++;
                lines.Add($"  boss-segment: movementRight={bossMovementRight:0.00} blocked");
            }
            else
            {
                lines.Add($"  boss-segment: movementRight={bossMovementRight:0.00} ok");
            }

            for (int i = 0; i < platforms.Count; i++)
            {
                var p = platforms[i];
                float[] sampleXs =
                {
                    (p.Left + p.Right) * .5f,
                    p.Left + PlatformLandingEdgeSnapInset + .035f,
                    p.Right - PlatformLandingEdgeSnapInset - .035f
                };
                bool platformOk = true;
                foreach (float sampleX in sampleXs)
                {
                    float supportY = StableSupportYAtX(sampleX);
                    if (Mathf.Abs(supportY - p.Top) > .025f)
                    {
                        platformOk = false;
                        lines.Add($"  platform-{i}: support mismatch x={sampleX:0.00} support={supportY:0.00} top={p.Top:0.00}");
                    }
                }
                if (!platformOk) warnings++;
                else lines.Add($"  platform-{i}: support top={p.Top:0.00} width={p.Width:0.00} ok");
            }

            for (int i = 0; i < platforms.Count; i++)
            {
                var p = platforms[i];
                player.transform.position = new Vector3((p.Left + p.Right) * .5f, p.Top - .18f, 0f);
                verticalVelocity = -.20f;
                grounded = false;
                NormalizePlayerSupport(true);
                float snappedY = player.transform.position.y;
                if (Mathf.Abs(snappedY - p.Top) > .025f)
                {
                    warnings++;
                    lines.Add($"  platform-unstick-{i}: failed snapped={snappedY:0.00} top={p.Top:0.00}");
                }
                else
                {
                    lines.Add($"  platform-unstick-{i}: snapped top={p.Top:0.00} ok");
                }

                float leftEdgeSample = p.Left + PlatformLandingEdgeSnapInset + PlatformLandingStableEdgeTolerance * .50f;
                float rightEdgeSample = p.Right - PlatformLandingEdgeSnapInset - PlatformLandingStableEdgeTolerance * .50f;
                float leftSupportY = StableSupportYAtX(leftEdgeSample, p.Top + PlatformSupportUnstickTolerance);
                float rightSupportY = StableSupportYAtX(rightEdgeSample, p.Top + PlatformSupportUnstickTolerance);
                bool edgeStable = Mathf.Abs(leftSupportY - p.Top) <= .025f && Mathf.Abs(rightSupportY - p.Top) <= .025f;
                if (!edgeStable)
                {
                    warnings++;
                    lines.Add($"  platform-edge-stability-{i}: left={leftSupportY:0.00} right={rightSupportY:0.00} top={p.Top:0.00} blocked");
                }
                else
                {
                    lines.Add($"  platform-edge-stability-{i}: top={p.Top:0.00} ok");
                }
            }

            for (int segment = 0; segment < SegmentRights.Length; segment++)
            {
                bool ok = DebugCanWalkClearedSegment(segment, out float finalX, out float expectedX, out int stuckFrames);
                if (!ok) warnings++;
                string label = segment == SegmentRights.Length - 1 ? "boss" : segment.ToString();
                lines.Add($"  walk-sim-{label}: final={finalX:0.00} expected>={expectedX:0.00} stuckFrames={stuckFrames} {(ok ? "ok" : "blocked")}");
            }

            bool visualPocketOk = DebugCanRecoverVisualGroundPocket(out float pocketBeforeX, out float pocketAfterX);
            if (!visualPocketOk) warnings++;
            lines.Add($"  visual-ground-pocket-recover: before={pocketBeforeX:0.00} after={pocketAfterX:0.00} {(visualPocketOk ? "ok" : "blocked")}");

            bool openRoutePocketOk = DebugCanWidenOpenRouteStuckRecovery(out float routePocketBeforeX, out float routePocketBeforeRight, out float routePocketAfterRight);
            if (!openRoutePocketOk) warnings++;
            lines.Add($"  open-route-stuck-widen: playerX={routePocketBeforeX:0.00} right={routePocketBeforeRight:0.00}->{routePocketAfterRight:0.00} {(openRoutePocketOk ? "ok" : "blocked")}");

            bool gateSoftReleaseOk = DebugCanGateEdgeSoftReleaseNudge(out float softBeforeX, out float softAfterX);
            if (!gateSoftReleaseOk) warnings++;
            lines.Add($"  gate-edge-soft-release: before={softBeforeX:0.00} after={softAfterX:0.00} {(gateSoftReleaseOk ? "ok" : "blocked")}");

            bool openRouteIntentNudgeOk = DebugCanOpenRouteIntentSoftNudge(out float nudgeBeforeX, out float nudgeAfterX);
            if (!openRouteIntentNudgeOk) warnings++;
            lines.Add($"  open-route-intent-soft-nudge: before={nudgeBeforeX:0.00} after={nudgeAfterX:0.00} {(openRouteIntentNudgeOk ? "ok" : "blocked")}");

            for (int segment = 0; segment < SegmentRights.Length - 1; segment++)
            {
                bool ok = DebugCanWalkCombatLockedSegment(segment, out float finalX, out float expectedX, out int stuckFrames);
                if (!ok) warnings++;
                lines.Add($"  combat-pocket-walk-{segment}: final={finalX:0.00} expected>={expectedX:0.00} stuckFrames={stuckFrames} {(ok ? "ok" : "blocked")}");
            }

            for (int i = 0; i < platforms.Count; i++)
            {
                bool ok = DebugCanApproachVisibleEnemyFromPlatform(platforms[i], out float finalX, out float expectedX, out int stuckFrames);
                if (!ok) warnings++;
                lines.Add($"  platform-visible-enemy-approach-{i}: final={finalX:0.00} expected>={expectedX:0.00} stuckFrames={stuckFrames} {(ok ? "ok" : "blocked")}");
            }

            for (int segment = 0; segment < SegmentRights.Length - 1; segment++)
            {
                bool ok = DebugCanAttackLungeTowardVisibleEnemy(segment, out float beforeX, out float afterX, out float allowedRight);
                if (!ok) warnings++;
                lines.Add($"  visible-enemy-attack-lunge-{segment}: before={beforeX:0.00} after={afterX:0.00} allowed={allowedRight:0.00} {(ok ? "ok" : "blocked")}");
            }

            for (int i = 0; i < platforms.Count; i++)
            {
                bool leftOk = DebugCanLeavePlatformEdge(platforms[i], -1, out float leftFinalX, out int leftStuckFrames);
                bool rightOk = DebugCanLeavePlatformEdge(platforms[i], 1, out float rightFinalX, out int rightStuckFrames);
                if (!leftOk || !rightOk) warnings++;
                lines.Add($"  platform-leave-{i}: leftFinal={leftFinalX:0.00} leftStuck={leftStuckFrames} rightFinal={rightFinalX:0.00} rightStuck={rightStuckFrames} {((leftOk && rightOk) ? "ok" : "blocked")}");
            }

            foreach (var state in originalEnemyDeadStates)
                state.enemy.Dead = state.dead;
            player.transform.position = originalPlayerPosition;
            verticalVelocity = originalVerticalVelocity;
            grounded = originalGrounded;
            currentSegment = originalSegment;
            inputLocked = originalInputLocked;
            rollingRune = originalRollingRune;
            choosingRoomReward = originalChoosingReward;
            stageRuneResolved = originalStageRuneResolved;
            titleActive = originalTitleActive;
            paused = originalPaused;
            controlEditMode = originalControlEditMode;

            string report = string.Join("\n", lines) + $"\nwarnings={warnings}";
            Debug.Log(report);
            return report;
        }

        private bool DebugCanRecoverVisualGroundPocket(out float beforeX, out float afterX)
        {
            beforeX = 0f;
            afterX = 0f;
            if (!player) return false;

            Vector3 savedPlayerPosition = player.transform.position;
            float savedVerticalVelocity = verticalVelocity;
            bool savedGrounded = grounded;
            bool savedInputLocked = inputLocked;
            bool savedRollingRune = rollingRune;
            bool savedChoosingReward = choosingRoomReward;
            bool savedStageRuneResolved = stageRuneResolved;
            bool savedTitleActive = titleActive;
            bool savedPaused = paused;
            bool savedControlEditMode = controlEditMode;
            int savedSegment = currentSegment;
            float savedMovementStuckTimer = movementStuckTimer;
            float savedLastMovementFrameX = lastMovementFrameX;
            var savedEnemyDeadStates = enemies.Select(enemy => new { enemy, dead = enemy.Dead }).ToList();

            try
            {
                foreach (var enemy in enemies)
                    if (enemy != null) enemy.Dead = true;

                inputLocked = false;
                rollingRune = false;
                choosingRoomReward = false;
                stageRuneResolved = false;
                titleActive = false;
                paused = false;
                controlEditMode = false;
                currentSegment = 1;

                beforeX = SegmentRights[0] + .34f;
                float beforeY = StableSupportYAtX(beforeX);
                player.transform.position = new Vector3(beforeX, beforeY, 0f);
                verticalVelocity = 0f;
                grounded = true;
                movementStuckTimer = MovementStuckRecoverDelay;
                lastMovementFrameX = beforeX;

                RecoverPlayerIfMovementStuck(1f, beforeX, beforeY, false, 1f / 60f);
                afterX = player.transform.position.x;
                return afterX >= beforeX + MovementStuckRecoverMinAdvance;
            }
            finally
            {
                foreach (var state in savedEnemyDeadStates)
                    state.enemy.Dead = state.dead;
                player.transform.position = savedPlayerPosition;
                verticalVelocity = savedVerticalVelocity;
                grounded = savedGrounded;
                inputLocked = savedInputLocked;
                rollingRune = savedRollingRune;
                choosingRoomReward = savedChoosingReward;
                stageRuneResolved = savedStageRuneResolved;
                titleActive = savedTitleActive;
                paused = savedPaused;
                controlEditMode = savedControlEditMode;
                currentSegment = savedSegment;
                movementStuckTimer = savedMovementStuckTimer;
                lastMovementFrameX = savedLastMovementFrameX;
                ClearPlatformDropThrough();
            }
        }

