        private bool DebugCanAttackLungeTowardVisibleEnemy(int segment, out float beforeX, out float afterX, out float allowedRight)
        {
            beforeX = 0f;
            afterX = 0f;
            allowedRight = 0f;
            if (!player) return false;

            Vector3 savedPlayerPosition = player.transform.position;
            float savedVerticalVelocity = verticalVelocity;
            bool savedGrounded = grounded;
            bool savedInputLocked = inputLocked;
            bool savedRollingRune = rollingRune;
            bool savedChoosingReward = choosingRoomReward;
            bool savedStageRuneResolved = stageRuneResolved;
            bool savedTitleActive = titleActive;
            bool savedPaused = paused;
            bool savedControlEditMode = controlEditMode;
            int savedSegment = currentSegment;
            int savedFacing = facing;
            var savedEnemyDeadStates = enemies.Select(enemy => new { enemy, dead = enemy.Dead }).ToList();

            GameObject probeRoot = null;
            Fighter probeEnemy = null;
            try
            {
                inputLocked = false;
                rollingRune = false;
                choosingRoomReward = false;
                stageRuneResolved = false;
                titleActive = false;
                paused = false;
                controlEditMode = false;
                currentSegment = Mathf.Clamp(segment, 0, SegmentRights.Length - 1);
                foreach (var enemy in enemies)
                    if (enemy != null) enemy.Dead = true;

                float baseRight = CurrentMovementRight();
                beforeX = Mathf.Clamp(baseRight - .14f, LeftBound + .8f, RightBound - 1.3f);
                float enemyX = Mathf.Clamp(baseRight + .58f, beforeX + .44f, RightBound - .62f);
                probeRoot = new GameObject("DebugVisibleEnemyAttackLungeTarget");
                probeRoot.transform.SetParent(world ? world : transform);
                probeRoot.transform.position = new Vector3(enemyX, GroundedEnemyY(EnemyKind.Mushroom), 0f);
                probeEnemy = new Fighter
                {
                    Kind = EnemyKind.Mushroom,
                    Root = probeRoot,
                    Hp = 1f,
                    MaxHp = 1f,
                    Dead = false
                };
                enemies.Add(probeEnemy);

                allowedRight = AllowedMovementRight(beforeX);
                player.transform.position = new Vector3(beforeX, StableSupportYAtX(beforeX), 0f);
                verticalVelocity = 0f;
                grounded = true;
                facing = 1;
                ApplyAttackLunge(3);
                afterX = player.transform.position.x;

                bool hasForwardRoom = allowedRight >= beforeX + .18f;
                bool extensionUseful = allowedRight > baseRight + .18f || baseRight >= RightBound - .80f;
                return hasForwardRoom && extensionUseful && afterX > beforeX + .08f;
            }
            finally
            {
                if (probeEnemy != null) enemies.Remove(probeEnemy);
                if (probeRoot)
                {
                    if (Application.isPlaying) Destroy(probeRoot);
                    else DestroyImmediate(probeRoot);
                }
                foreach (var state in savedEnemyDeadStates)
                    state.enemy.Dead = state.dead;
                player.transform.position = savedPlayerPosition;
                verticalVelocity = savedVerticalVelocity;
                grounded = savedGrounded;
                inputLocked = savedInputLocked;
                rollingRune = savedRollingRune;
                choosingRoomReward = savedChoosingReward;
                stageRuneResolved = savedStageRuneResolved;
                titleActive = savedTitleActive;
                paused = savedPaused;
                controlEditMode = savedControlEditMode;
                currentSegment = savedSegment;
                facing = savedFacing;
                ClearPlatformDropThrough();
            }
        }

        private bool DebugCanWalkClearedSegment(int segment, out float finalX, out float expectedX, out int stuckFrames)
        {
            finalX = 0f;
            expectedX = 0f;
            stuckFrames = 0;
            if (!player) return false;

            Vector3 savedPlayerPosition = player.transform.position;
            float savedVerticalVelocity = verticalVelocity;
            bool savedGrounded = grounded;
            bool savedInputLocked = inputLocked;
            bool savedRollingRune = rollingRune;
            bool savedChoosingReward = choosingRoomReward;
            bool savedStageRuneResolved = stageRuneResolved;
            bool savedTitleActive = titleActive;
            bool savedPaused = paused;
            bool savedControlEditMode = controlEditMode;
            int savedSegment = currentSegment;
            var savedEnemyDeadStates = enemies.Select(enemy => new { enemy, dead = enemy.Dead }).ToList();

            try
            {
                foreach (var enemy in enemies)
                {
                    if (enemy != null)
                        enemy.Dead = true;
                }

                inputLocked = false;
                rollingRune = false;
                choosingRoomReward = false;
                stageRuneResolved = false;
                titleActive = false;
                paused = false;
                controlEditMode = false;
                currentSegment = Mathf.Clamp(segment, 0, SegmentRights.Length - 1);
                ClearPlatformDropThrough();

                float segmentLeft = currentSegment > 0 ? SegmentRights[currentSegment - 1] : LeftBound;
                float startX = Mathf.Clamp(segmentLeft + .48f, LeftBound + .48f, RightBound - .48f);
                float movementRight = CurrentMovementRight();
                expectedX = Mathf.Max(startX, movementRight - .26f);
                player.transform.position = new Vector3(startX, StableSupportYAtX(startX) + .02f, 0f);
                verticalVelocity = 0f;
                grounded = true;
                NormalizePlayerSupport(true);

                const float simulatedDt = 1f / 60f;
                const float simulatedSpeed = 4.2f;
                int longestStuckRun = 0;
                int currentStuckRun = 0;

                int maxSteps = Mathf.CeilToInt((expectedX - startX + 1.4f) / (simulatedSpeed * simulatedDt)) + 45;
                for (int step = 0; step < maxSteps; step++)
                {
                    Vector3 before = player.transform.position;
                    Vector3 pos = before;
                    movementRight = CurrentMovementRight();
                    pos.x = Mathf.Clamp(pos.x + simulatedSpeed * simulatedDt, LeftBound, movementRight);
                    pos.y = StableSupportYAtX(pos.x, pos.y + PlatformSupportUnstickTolerance);
                    player.transform.position = pos;
                    verticalVelocity = 0f;
                    grounded = true;
                    NormalizePlayerSupport(true);
                    ReconcileMovementSegmentWithPlayerPosition();

                    float moved = player.transform.position.x - before.x;
                    if (moved < .002f && player.transform.position.x < expectedX - .04f)
                    {
                        currentStuckRun++;
                        longestStuckRun = Mathf.Max(longestStuckRun, currentStuckRun);
                    }
                    else
                    {
                        currentStuckRun = 0;
                    }

                    if (player.transform.position.x >= expectedX - .02f)
                        break;
                    if (currentStuckRun > 18)
                        break;
                }

                finalX = player.transform.position.x;
                stuckFrames = longestStuckRun;
                return finalX >= expectedX - .04f && stuckFrames <= 18;
            }
            finally
            {
                foreach (var state in savedEnemyDeadStates)
                    state.enemy.Dead = state.dead;
                player.transform.position = savedPlayerPosition;
                verticalVelocity = savedVerticalVelocity;
                grounded = savedGrounded;
                inputLocked = savedInputLocked;
                rollingRune = savedRollingRune;
                choosingRoomReward = savedChoosingReward;
                stageRuneResolved = savedStageRuneResolved;
                titleActive = savedTitleActive;
                paused = savedPaused;
                controlEditMode = savedControlEditMode;
                currentSegment = savedSegment;
                ClearPlatformDropThrough();
            }
        }

        private bool DebugCanWalkCombatLockedSegment(int segment, out float finalX, out float expectedX, out int stuckFrames)
        {
            finalX = 0f;
            expectedX = 0f;
            stuckFrames = 0;
            if (!player) return false;

            Vector3 savedPlayerPosition = player.transform.position;
            float savedVerticalVelocity = verticalVelocity;
            bool savedGrounded = grounded;
            bool savedInputLocked = inputLocked;
            bool savedRollingRune = rollingRune;
            bool savedChoosingReward = choosingRoomReward;
            bool savedStageRuneResolved = stageRuneResolved;
            bool savedTitleActive = titleActive;
            bool savedPaused = paused;
            bool savedControlEditMode = controlEditMode;
            int savedSegment = currentSegment;
            var savedEnemyDeadStates = enemies.Select(enemy => new { enemy, dead = enemy.Dead }).ToList();

            try
            {
                var blockingEnemies = enemies
                    .Where(enemy => enemy?.Root && IsXInSegment(enemy.Root.transform.position.x, segment))
                    .ToList();
                if (blockingEnemies.Count <= 0)
                {
                    finalX = expectedX = segment > 0 ? SegmentRights[segment - 1] : LeftBound;
                    return true;
                }

                foreach (var enemy in enemies)
                {
                    if (enemy == null) continue;
                    enemy.Dead = !blockingEnemies.Contains(enemy);
                }
                foreach (var enemy in blockingEnemies)
                    enemy.Dead = false;

                inputLocked = false;
                rollingRune = false;
                choosingRoomReward = false;
                stageRuneResolved = false;
                titleActive = false;
                paused = false;
                controlEditMode = false;
                currentSegment = Mathf.Clamp(segment, 0, SegmentRights.Length - 1);
                ClearPlatformDropThrough();

                float segmentLeft = currentSegment > 0 ? SegmentRights[currentSegment - 1] : LeftBound;
                float startX = Mathf.Clamp(segmentLeft + .52f, LeftBound + .52f, RightBound - .52f);
                float farthestEnemyX = blockingEnemies.Max(enemy => enemy.Root.transform.position.x);
                expectedX = Mathf.Min(CurrentMovementRight() - .18f, farthestEnemyX + .58f);
                player.transform.position = new Vector3(startX, StableSupportYAtX(startX) + .02f, 0f);
                verticalVelocity = 0f;
                grounded = true;
                NormalizePlayerSupport(true);

                const float simulatedDt = 1f / 60f;
                const float simulatedSpeed = 4.2f;
                int currentStuckRun = 0;
                for (int step = 0; step < 260; step++)
                {
                    Vector3 before = player.transform.position;
                    Vector3 pos = before;
                    float movementRight = IntentAwareMovementRight(before.x, 1f);
                    pos.x = Mathf.Clamp(pos.x + simulatedSpeed * simulatedDt, LeftBound, movementRight);
                    pos.y = StableSupportYAtX(pos.x, pos.y + PlatformSupportUnstickTolerance);
                    player.transform.position = pos;
                    verticalVelocity = 0f;
                    grounded = true;
                    NormalizePlayerSupport(true);
                    ReconcileMovementSegmentWithPlayerPosition();

                    float moved = player.transform.position.x - before.x;
                    if (moved < .002f && player.transform.position.x < expectedX - .04f)
                    {
                        currentStuckRun++;
                        stuckFrames = Mathf.Max(stuckFrames, currentStuckRun);
                    }
                    else
                    {
                        currentStuckRun = 0;
                    }

                    if (player.transform.position.x >= expectedX - .02f)
                        break;
                    if (currentStuckRun > 14)
                        break;
                }

                finalX = player.transform.position.x;
                return finalX >= expectedX - .04f && stuckFrames <= 14;
            }
            finally
            {
                foreach (var state in savedEnemyDeadStates)
                    state.enemy.Dead = state.dead;
                player.transform.position = savedPlayerPosition;
                verticalVelocity = savedVerticalVelocity;
                grounded = savedGrounded;
                inputLocked = savedInputLocked;
                rollingRune = savedRollingRune;
                choosingRoomReward = savedChoosingReward;
                stageRuneResolved = savedStageRuneResolved;
                titleActive = savedTitleActive;
                paused = savedPaused;
                controlEditMode = savedControlEditMode;
                currentSegment = savedSegment;
                ClearPlatformDropThrough();
            }
        }

        private bool DebugCanLeavePlatformEdge(Platform platform, int direction, out float finalX, out int stuckFrames)
        {
            finalX = 0f;
            stuckFrames = 0;
            if (!player || platform == null) return false;

            Vector3 savedPlayerPosition = player.transform.position;
            float savedVerticalVelocity = verticalVelocity;
            bool savedGrounded = grounded;
            bool savedInputLocked = inputLocked;
            bool savedRollingRune = rollingRune;
            bool savedChoosingReward = choosingRoomReward;
            bool savedStageRuneResolved = stageRuneResolved;
            bool savedTitleActive = titleActive;
            bool savedPaused = paused;
            bool savedControlEditMode = controlEditMode;
            int savedSegment = currentSegment;
            var savedEnemyDeadStates = enemies.Select(enemy => new { enemy, dead = enemy.Dead }).ToList();

            try
            {
                inputLocked = false;
                rollingRune = false;
                choosingRoomReward = false;
                stageRuneResolved = false;
                titleActive = false;
                paused = false;
                controlEditMode = false;
                currentSegment = Mathf.Clamp(SegmentIndexForX((platform.Left + platform.Right) * .5f), 0, SegmentRights.Length - 1);
                foreach (var enemy in enemies)
                {
                    if (enemy?.Root && IsXInSegment(enemy.Root.transform.position.x, currentSegment))
                        enemy.Dead = true;
                }
                ClearPlatformDropThrough();

                float startX = direction < 0
                    ? platform.Left + PlatformLandingEdgeSnapInset + PlatformLandingStableEdgeTolerance + .08f
                    : platform.Right - PlatformLandingEdgeSnapInset - PlatformLandingStableEdgeTolerance - .08f;
                float targetX = direction < 0 ? platform.Left - .28f : platform.Right + .28f;
                player.transform.position = new Vector3(startX, platform.Top, 0f);
                verticalVelocity = 0f;
                grounded = true;

                const float simulatedDt = 1f / 60f;
                const float simulatedSpeed = 4.2f;
                int currentStuckRun = 0;
                for (int step = 0; step < 88; step++)
                {
                    Vector3 before = player.transform.position;
                    Vector3 pos = before;
                    float movementRight = IntentAwareMovementRight(before.x, direction);
                    pos.x = Mathf.Clamp(pos.x + direction * simulatedSpeed * simulatedDt, LeftBound, movementRight);
                    ApplyPlatformEdgeHorizontalEscape(ref pos, direction, before.x, movementRight);
                    pos.y = StableSupportYAtX(pos.x, pos.y + PlatformSupportUnstickTolerance);
                    player.transform.position = pos;
                    verticalVelocity = 0f;
                    grounded = true;
                    NormalizePlayerSupport(true);

                    float moved = Mathf.Abs(player.transform.position.x - before.x);
                    bool reached = direction < 0 ? player.transform.position.x <= targetX : player.transform.position.x >= targetX;
                    if (moved < .002f && !reached)
                    {
                        currentStuckRun++;
                        stuckFrames = Mathf.Max(stuckFrames, currentStuckRun);
                    }
                    else
                    {
                        currentStuckRun = 0;
                    }

                    if (reached) break;
                    if (currentStuckRun > 10) break;
                }

                finalX = player.transform.position.x;
                bool reachedTarget = direction < 0 ? finalX <= targetX + .04f : finalX >= targetX - .04f;
                return reachedTarget && stuckFrames <= 10;
            }
            finally
            {
                foreach (var state in savedEnemyDeadStates)
                    state.enemy.Dead = state.dead;
                player.transform.position = savedPlayerPosition;
                verticalVelocity = savedVerticalVelocity;
                grounded = savedGrounded;
                inputLocked = savedInputLocked;
                rollingRune = savedRollingRune;
                choosingRoomReward = savedChoosingReward;
                stageRuneResolved = savedStageRuneResolved;
                titleActive = savedTitleActive;
                paused = savedPaused;
                controlEditMode = savedControlEditMode;
                currentSegment = savedSegment;
                ClearPlatformDropThrough();
            }
        }

        private bool DebugCanApproachVisibleEnemyFromPlatform(Platform platform, out float finalX, out float expectedX, out int stuckFrames)
        {
            finalX = 0f;
            expectedX = 0f;
            stuckFrames = 0;
            if (!player || platform == null) return false;

            Vector3 savedPlayerPosition = player.transform.position;
            float savedVerticalVelocity = verticalVelocity;
            bool savedGrounded = grounded;
            bool savedInputLocked = inputLocked;
            bool savedRollingRune = rollingRune;
            bool savedChoosingReward = choosingRoomReward;
            bool savedStageRuneResolved = stageRuneResolved;
            bool savedTitleActive = titleActive;
            bool savedPaused = paused;
            bool savedControlEditMode = controlEditMode;
            int savedSegment = currentSegment;
            var savedEnemyDeadStates = enemies.Select(enemy => new { enemy, dead = enemy.Dead }).ToList();

            GameObject probeRoot = null;
            Fighter probeEnemy = null;
            try
            {
                inputLocked = false;
                rollingRune = false;
                choosingRoomReward = false;
                stageRuneResolved = false;
                titleActive = false;
                paused = false;
                controlEditMode = false;
                currentSegment = Mathf.Clamp(SegmentIndexForX((platform.Left + platform.Right) * .5f), 0, SegmentRights.Length - 1);
                foreach (var enemy in enemies)
                    if (enemy != null) enemy.Dead = true;

                float startX = Mathf.Clamp(platform.Left + platform.Width * .34f, platform.Left + .18f, platform.Right - .18f);
                float enemyX = Mathf.Min(platform.Right + 2.15f, SegmentRights[Mathf.Clamp(currentSegment + 1, 0, SegmentRights.Length - 1)] - .62f);
                if (enemyX <= startX + .85f) enemyX = Mathf.Min(startX + 1.65f, RightBound - .8f);
                probeRoot = new GameObject("DebugVisibleCombatApproachEnemy");
                probeRoot.transform.SetParent(world ? world : transform);
                probeRoot.transform.position = new Vector3(enemyX, GroundedEnemyY(EnemyKind.Mushroom), 0f);
                probeEnemy = new Fighter
                {
                    Kind = EnemyKind.Mushroom,
                    Root = probeRoot,
                    Hp = 1f,
                    MaxHp = 1f,
                    Dead = false
                };
                enemies.Add(probeEnemy);

                expectedX = Mathf.Max(startX + .72f, enemyX - .52f);
                player.transform.position = new Vector3(startX, platform.Top, 0f);
                verticalVelocity = 0f;
                grounded = true;
                ClearPlatformDropThrough();

                const float simulatedDt = 1f / 60f;
                const float simulatedSpeed = 4.2f;
                int currentStuckRun = 0;
                for (int step = 0; step < 130; step++)
                {
                    Vector3 before = player.transform.position;
                    Vector3 pos = before;
                    float movementRight = IntentAwareMovementRight(before.x, 1f);
                    pos.x = Mathf.Clamp(pos.x + simulatedSpeed * simulatedDt, LeftBound, movementRight);
                    pos.y = StableSupportYAtX(pos.x, pos.y + PlatformSupportUnstickTolerance);
                    player.transform.position = pos;
                    verticalVelocity = 0f;
                    grounded = true;
                    NormalizePlayerSupport(true);

                    float moved = player.transform.position.x - before.x;
                    if (moved < .002f && player.transform.position.x < expectedX - .04f)
                    {
                        currentStuckRun++;
                        stuckFrames = Mathf.Max(stuckFrames, currentStuckRun);
                    }
                    else
                    {
                        currentStuckRun = 0;
                    }

                    if (player.transform.position.x >= expectedX - .02f)
                        break;
                    if (currentStuckRun > 10)
                        break;
                }

                finalX = player.transform.position.x;
                return finalX >= expectedX - .04f && stuckFrames <= 10;
            }
            finally
            {
                if (probeEnemy != null) enemies.Remove(probeEnemy);
                if (probeRoot)
                {
                    if (Application.isPlaying) Destroy(probeRoot);
                    else DestroyImmediate(probeRoot);
                }
                foreach (var state in savedEnemyDeadStates)
                    state.enemy.Dead = state.dead;
                player.transform.position = savedPlayerPosition;
                verticalVelocity = savedVerticalVelocity;
                grounded = savedGrounded;
                inputLocked = savedInputLocked;
                rollingRune = savedRollingRune;
                choosingRoomReward = savedChoosingReward;
                stageRuneResolved = savedStageRuneResolved;
                titleActive = savedTitleActive;
                paused = savedPaused;
                controlEditMode = savedControlEditMode;
                currentSegment = savedSegment;
                ClearPlatformDropThrough();
            }
        }

