            warnings += DebugAuditEnemyAttackInterruptionCase(EnemyKind.Slime, false, HitTier.Light, lines);
            warnings += DebugAuditEnemyAttackInterruptionCase(EnemyKind.Archer, false, HitTier.Light, lines);
            warnings += DebugAuditEnemyAttackInterruptionCase(EnemyKind.Mushroom, true, HitTier.Heavy, lines);
            warnings += DebugAuditEnemyAttackInterruptionCase(EnemyKind.Archer, true, HitTier.Skill, lines);
            warnings += DebugAuditEnemyAttackStartupSuppressedCase(EnemyKind.Mushroom, HitTier.Light, lines);
            warnings += DebugAuditEnemyAttackStartupSuppressedCase(EnemyKind.Archer, HitTier.Skill, lines);
            warnings += DebugAuditEnemyHitReactFrameSuppressesStartupCase(EnemyKind.Mushroom, HitTier.Light, lines);
            warnings += DebugAuditEnemyHitReactFrameSuppressesStartupCase(EnemyKind.Archer, HitTier.Skill, lines);
            warnings += DebugAuditEnemyWindupHitCancelCase(EnemyKind.Mushroom, false, HitTier.Light, lines);
            warnings += DebugAuditEnemyWindupHitCancelCase(EnemyKind.Archer, false, HitTier.Light, lines);
            warnings += DebugAuditEnemyWindupHitCancelCase(EnemyKind.Archer, true, HitTier.Skill, lines);
            warnings += DebugAuditEnemyFreezeInterruptCase(EnemyKind.Mushroom, false, lines);
            warnings += DebugAuditEnemyFreezeInterruptCase(EnemyKind.Archer, true, lines);

            string report = string.Join("\n", lines) + $"\nwarnings={warnings}";
