        }

        public string DebugAuditCombatRoomPacing()
        {
            PruneInvalidEnemies();
            var lines = new List<string> { "combat-room-pacing-audit" };
            int warnings = 0;
            for (int segment = 0; segment < SegmentRights.Length; segment++)
            {
                var roomEnemies = EnemiesInSegment(segment)
                    .Where(enemy => enemy != null && !enemy.Dead && enemy.Root && enemy.Root.activeInHierarchy)
                    .OrderBy(enemy => enemy.Root.transform.position.x)
                    .ToList();
                int minCount = RoomEnemyMinCounts[Mathf.Clamp(segment, 0, RoomEnemyMinCounts.Length - 1)];
                int maxCount = RoomEnemyMaxCounts[Mathf.Clamp(segment, 0, RoomEnemyMaxCounts.Length - 1)];
                int archerCount = roomEnemies.Count(enemy => enemy.Kind == EnemyKind.Archer);
                int bossCount = roomEnemies.Count(enemy => enemy.Boss);
                int eliteCount = roomEnemies.Count(enemy => enemy.Elite);
                float closestGap = ClosestEnemyGap(roomEnemies);
                bool entranceGapOk = RoomEntranceGapOk(segment, roomEnemies);
                bool exitGapOk = RoomExitGapOk(segment, roomEnemies);
                bool countOk = roomEnemies.Count >= minCount && roomEnemies.Count <= maxCount;
                bool archerOk = segment == BossRoomIndex ? archerCount <= 1 : archerCount <= 2;
                bool bossOk = segment == BossRoomIndex ? bossCount == 1 : bossCount == 0;
                bool eliteOk = segment == EliteRoomIndex ? eliteCount >= 1 : eliteCount <= 1;
                bool spacingOk = roomEnemies.Count <= 1 || closestGap >= (segment == BossRoomIndex ? 1.55f : 1.08f);
                bool ok = countOk && archerOk && bossOk && eliteOk && spacingOk && entranceGapOk && exitGapOk;
                if (!ok) warnings++;
                lines.Add($"  room-{segment}: enemies={roomEnemies.Count}/{minCount}-{maxCount} archers={archerCount} boss={bossCount} elite={eliteCount} closestGap={closestGap:0.00} entranceSafe={entranceGapOk} exitSafe={exitGapOk} {(ok ? "ok" : "failed")}");
            }

            string report = string.Join("\n", lines) + $"\nwarnings={warnings}";
            Debug.Log(report);
            return report;
        }

        public string DebugAuditCombatHitFeel()
        {
            var lines = new List<string> { "combat-hit-feel-audit" };
            int warnings = 0;

            warnings += DebugAuditCombatHitFeelCondition("hitstop-heavy-skill-light",
                HeavyHitStopDuration > SkillHitStopDuration && SkillHitStopDuration > LightHitStopDuration,
                $"light={LightHitStopDuration:0.000} skill={SkillHitStopDuration:0.000} heavy={HeavyHitStopDuration:0.000}", lines);
            warnings += DebugAuditCombatHitFeelCondition("lunge-heavy-light",
                HeavyHitFrameLunge > LightHitFrameLunge,
                $"light={LightHitFrameLunge:0.000} heavy={HeavyHitFrameLunge:0.000}", lines);

            var normal = new Fighter { Kind = EnemyKind.Mushroom, Hp = 1000f, MaxHp = 1000f };
            var archer = new Fighter { Kind = EnemyKind.Archer, Hp = 1000f, MaxHp = 1000f };
            var boss = new Fighter { Kind = EnemyKind.Boss, Boss = true, Hp = 10000f, MaxHp = 10000f };

            float normalLightStun = EnemyHitStunDuration(normal, HitTier.Light);
            float normalSkillStun = EnemyHitStunDuration(normal, HitTier.Skill);
            float normalHeavyStun = EnemyHitStunDuration(normal, HitTier.Heavy);
            warnings += DebugAuditCombatHitFeelCondition("normal-stun-heavy-skill-light",
                normalHeavyStun > normalSkillStun && normalSkillStun > normalLightStun,
                $"light={normalLightStun:0.00} skill={normalSkillStun:0.00} heavy={normalHeavyStun:0.00}", lines);
            var chainedHitEnemy = new Fighter { Kind = EnemyKind.Mushroom, Hp = 1000f, MaxHp = 1000f };
            chainedHitEnemy.HitStun = normalHeavyStun;
            chainedHitEnemy.HitStun = Mathf.Max(chainedHitEnemy.HitStun, EnemyHitStunDuration(chainedHitEnemy, HitTier.Light));
            warnings += DebugAuditCombatHitFeelCondition("hit-stun-never-downgrades",
                chainedHitEnemy.HitStun >= normalHeavyStun - .001f,
                $"afterLight={chainedHitEnemy.HitStun:0.00} heavy={normalHeavyStun:0.00}", lines);

            float normalLightDelay = EnemyPostHitAttackDelay(normal, HitTier.Light);
            float normalSkillDelay = EnemyPostHitAttackDelay(normal, HitTier.Skill);
            float normalHeavyDelay = EnemyPostHitAttackDelay(normal, HitTier.Heavy);
            warnings += DebugAuditCombatHitFeelCondition("normal-delay-heavy-skill-light",
                normalHeavyDelay > normalSkillDelay && normalSkillDelay > normalLightDelay,
                $"light={normalLightDelay:0.00} skill={normalSkillDelay:0.00} heavy={normalHeavyDelay:0.00}", lines);
            warnings += DebugAuditCombatHitFeelCondition("normal-post-stun-recovery-buffer",
                normalLightDelay >= normalLightStun + EnemyPostHitRecoveryAfterStunMin - .001f
                && normalSkillDelay >= normalSkillStun + EnemyPostHitRecoveryAfterStunMin - .001f
                && normalHeavyDelay >= normalHeavyStun + EnemyPostHitRecoveryAfterStunMin - .001f,
                $"min={EnemyPostHitRecoveryAfterStunMin:0.00} lightGap={normalLightDelay - normalLightStun:0.00} skillGap={normalSkillDelay - normalSkillStun:0.00} heavyGap={normalHeavyDelay - normalHeavyStun:0.00}", lines);

            float normalLightPush = EnemyKnockbackForce(normal, HitTier.Light, 1f);
            float normalSkillPush = EnemyKnockbackForce(normal, HitTier.Skill, 1.18f);
            float normalHeavyPush = EnemyKnockbackForce(normal, HitTier.Heavy, 1.35f);
            warnings += DebugAuditCombatHitFeelCondition("normal-push-heavy-skill-light",
                normalHeavyPush > normalSkillPush && normalSkillPush > normalLightPush,
                $"light={normalLightPush:0.00} skill={normalSkillPush:0.00} heavy={normalHeavyPush:0.00}", lines);
            warnings += DebugAuditCombatHitFeelCondition("post-hit-player-clearance-stronger",
                EnemyPostHitPlayerClearBuffer > EnemyPlayerReadabilityBuffer
                && EnemyPostHitPlayerClearStrength > EnemyPlayerReadabilityStrength
                && EnemyPostHitPlayerClearMaxStep >= EnemyPlayerReadabilityMaxStep,
                $"normal={EnemyPlayerReadabilityBuffer:0.00}/{EnemyPlayerReadabilityStrength:0.00}/{EnemyPlayerReadabilityMaxStep:0.000} postHit={EnemyPostHitPlayerClearBuffer:0.00}/{EnemyPostHitPlayerClearStrength:0.00}/{EnemyPostHitPlayerClearMaxStep:0.000}", lines);

            float archerHeavyDelay = EnemyPostHitAttackDelay(archer, HitTier.Heavy);
            warnings += DebugAuditCombatHitFeelCondition("archer-heavy-delay-longer",
                archerHeavyDelay > normalHeavyDelay,
                $"normal={normalHeavyDelay:0.00} archer={archerHeavyDelay:0.00}", lines);
            float archerLightStun = EnemyHitStunDuration(archer, HitTier.Light);
            float archerLightDelay = EnemyPostHitAttackDelay(archer, HitTier.Light);
            warnings += DebugAuditCombatHitFeelCondition("archer-post-stun-aim-reset-buffer",
                archerLightDelay >= archerLightStun + ArcherPostHitRecoveryAfterStunMin - .001f,
                $"min={ArcherPostHitRecoveryAfterStunMin:0.00} gap={archerLightDelay - archerLightStun:0.00}", lines);

            float bossHeavyDelay = EnemyPostHitAttackDelay(boss, HitTier.Heavy);
            warnings += DebugAuditCombatHitFeelCondition("boss-heavy-delay-controlled",
                bossHeavyDelay < normalHeavyDelay,
                $"boss={bossHeavyDelay:0.00} normal={normalHeavyDelay:0.00}", lines);

            string report = string.Join("\n", lines) + $"\nwarnings={warnings}";
            Debug.Log(report);
            return report;
        }

        private static int DebugAuditCombatHitFeelCondition(string label, bool ok, string detail, List<string> lines)
        {
            lines.Add($"  {label}: {detail} {(ok ? "ok" : "failed")}");
            return ok ? 0 : 1;
        }

        public string DebugAuditHudReadability()
        {
            var lines = new List<string> { "hud-readability-audit" };
            int warnings = 0;

            warnings += DebugAuditHudText("objective", objectiveText, TopHudPrimaryFontSize, 1010f, 94f, lines);
            warnings += DebugAuditHudText("notice", noticeText, TopHudNoticeFontSize, 1188f, 96f, lines);
            warnings += DebugAuditHudText("tutorial", tutorialText, TopHudSecondaryFontSize, 720f, 70f, lines);
            warnings += DebugAuditHudText("stage", stageText, 64, 760f, 84f, lines);

            int visibleSkills = VisibleHudSkills().Count();
            bool skillCountOk = visibleSkills == 1;
            if (!skillCountOk) warnings++;
            lines.Add($"  visible-skills={visibleSkills} {(skillCountOk ? "ok" : "failed")}");

            bool objectiveCombatAlphaReadable = .34f >= .30f;
            bool noticeImportantAlphaReadable = .62f >= .55f;
            if (!objectiveCombatAlphaReadable || !noticeImportantAlphaReadable) warnings++;
            lines.Add($"  combat-objective-alpha=.34 {(objectiveCombatAlphaReadable ? "ok" : "failed")}");
            lines.Add($"  important-notice-alpha=.62 {(noticeImportantAlphaReadable ? "ok" : "failed")}");

            string report = string.Join("\n", lines) + $"\nwarnings={warnings}";
            Debug.Log(report);
            return report;
        }

        private static int DebugAuditHudText(string label, Text text, int minFontSize, float minWidth, float minHeight, List<string> lines)
        {
            bool exists = text != null;
            int fontSize = exists ? text.fontSize : 0;
            Vector2 size = exists ? text.rectTransform.sizeDelta : Vector2.zero;
            bool ok = exists && fontSize >= minFontSize && size.x >= minWidth && size.y >= minHeight;
            lines.Add($"  {label}: font={fontSize}/{minFontSize} size={size.x:0}x{size.y:0} {(ok ? "ok" : "failed")}");
            return ok ? 0 : 1;
        }

        private static float ClosestEnemyGap(List<Fighter> roomEnemies)
        {
            if (roomEnemies == null || roomEnemies.Count <= 1) return 99f;
            float closest = 99f;
            for (int i = 1; i < roomEnemies.Count; i++)
                closest = Mathf.Min(closest, Mathf.Abs(roomEnemies[i].Root.transform.position.x - roomEnemies[i - 1].Root.transform.position.x));
            return closest;
        }

        private static bool RoomEntranceGapOk(int segment, List<Fighter> roomEnemies)
        {
            if (roomEnemies == null || roomEnemies.Count == 0 || segment == ShopRoomIndex) return true;
            float safeLeft = RoomCombatSafeLeft(segment) - .001f;
            return roomEnemies.All(enemy => enemy != null && enemy.Root && enemy.Root.transform.position.x >= safeLeft);
        }

        private static bool RoomExitGapOk(int segment, List<Fighter> roomEnemies)
        {
            if (roomEnemies == null || roomEnemies.Count == 0 || segment == ShopRoomIndex) return true;
            if (segment == BossRoomIndex)
                return roomEnemies.Where(enemy => enemy != null && enemy.Root && !enemy.Boss).All(enemy => enemy.Root.transform.position.x <= RoomCombatSafeRight(segment) + .001f);
            float safeRight = RoomCombatSafeRight(segment) + .001f;
            return roomEnemies.All(enemy => enemy != null && enemy.Root && enemy.Root.transform.position.x <= safeRight);
        }

        private int DebugAuditEnemyAttackInterruptionCase(EnemyKind kind, bool elite, HitTier tier, List<string> lines)
        {
            var root = new GameObject("DebugInterruptEnemy_" + kind + "_" + tier);
            root.transform.SetParent(enemyRoot ? enemyRoot : transform);
            root.transform.position = new Vector3(SegmentCenters[Mathf.Clamp(currentSegment, 0, SegmentCenters.Length - 1)], GroundedEnemyY(kind), 0f);
            var sprite = root.AddComponent<SpriteRenderer>();
            var enemy = new Fighter
            {
                Kind = kind,
                Root = root,
                Sprite = sprite,
                Hp = 1000f,
                MaxHp = 1000f,
                AttackTimer = 0f,
                AttackLockTimer = 0f,
                AttackToken = 12,
                Attacking = true,
                Elite = elite,
                BaseScale = Vector3.one
            };

            int tokenAtWindup = enemy.AttackToken;
            float expectedDelay = EnemyPostHitAttackDelay(enemy, tier);
            enemy.HitStun = EnemyHitStunDuration(enemy, tier);
            InterruptEnemyAttackOnHit(enemy, tier);

            bool interrupted = EnemyAttackInterrupted(enemy, tokenAtWindup);
            bool attackStopped = !enemy.Attacking;
            bool tokenInvalidated = enemy.AttackToken != tokenAtWindup;
            bool lockHeld = enemy.AttackLockTimer >= expectedDelay - .001f && enemy.AttackTimer >= expectedDelay - .001f;
            bool stunHeld = enemy.HitStun >= EnemyHitStunDuration(enemy, tier) - .001f;
            string statusLabel = EnemyStatusLabel(enemy, tier);
            bool statusReadable = elite || kind == EnemyKind.Boss || !string.IsNullOrEmpty(statusLabel);
            bool poseHeld = DebugEnemyHitReactDuration(kind, tier) >= (kind == EnemyKind.Boss ? .12f : tier == HitTier.Light ? .20f : tier == HitTier.Skill ? .23f : .26f) - .001f;
            bool ok = interrupted && attackStopped && tokenInvalidated && lockHeld && stunHeld && statusReadable && poseHeld;
            string label = $"{(elite ? "elite-" : "")}{kind}-{tier}";
            lines.Add($"  {label}: interrupted={interrupted} stopped={attackStopped} token={tokenInvalidated} lock={lockHeld} stun={stunHeld} status={statusLabel} pose={DebugEnemyHitReactDuration(kind, tier):0.00} {(ok ? "ok" : "failed")}");

            if (Application.isPlaying) Destroy(root);
            else DestroyImmediate(root);
            return ok ? 0 : 1;
        }

        private int DebugAuditEnemyAttackStartupSuppressedCase(EnemyKind kind, HitTier tier, List<string> lines)
        {
            var root = new GameObject("DebugSuppressedStartupEnemy_" + kind + "_" + tier);
            root.transform.SetParent(enemyRoot ? enemyRoot : transform);
            root.transform.position = new Vector3(SegmentCenters[Mathf.Clamp(currentSegment, 0, SegmentCenters.Length - 1)], GroundedEnemyY(kind), 0f);
            var sprite = root.AddComponent<SpriteRenderer>();
            var enemy = new Fighter
            {
                Kind = kind,
                Root = root,
                Sprite = sprite,
                Hp = 1000f,
                MaxHp = 1000f,
                AttackTimer = 0f,
                AttackToken = 21,
                Attacking = false,
                BaseScale = Vector3.one
            };
            enemy.AttackLockTimer = EnemyPostHitAttackDelay(enemy, tier);
            enemy.HitStun = EnemyHitStunDuration(enemy, tier);

            bool suppressed = EnemyActionSuppressed(enemy);
            bool canStart = CanEnemyStartAttack(enemy);
            bool timerReadyButBlocked = enemy.AttackTimer <= 0f && !canStart;
            bool tokenStable = enemy.AttackToken == 21;
            bool ok = suppressed && timerReadyButBlocked && tokenStable;
            lines.Add($"  attack-startup-suppressed-{kind}-{tier}: suppressed={suppressed} canStart={canStart} readyBlocked={timerReadyButBlocked} tokenStable={tokenStable} {(ok ? "ok" : "failed")}");

            if (Application.isPlaying) Destroy(root);
            else DestroyImmediate(root);
            return ok ? 0 : 1;
        }

