            lines.Add($"  hit-react-frame-suppressed-{kind}-{tier}: suppressed={suppressed} canStart={canStart} readyBlocked={timerReadyButBlocked} stopped={attackStopped} {(ok ? "ok" : "failed")}");

            if (Application.isPlaying) Destroy(root);
            else DestroyImmediate(root);
            return ok ? 0 : 1;
        }

        private int DebugAuditEnemyWindupHitCancelCase(EnemyKind kind, bool elite, HitTier tier, List<string> lines)
        {
            var root = new GameObject("DebugWindupCancelEnemy_" + kind + "_" + tier);
            root.transform.SetParent(enemyRoot ? enemyRoot : transform);
            root.transform.position = new Vector3(SegmentCenters[Mathf.Clamp(currentSegment, 0, SegmentCenters.Length - 1)], GroundedEnemyY(kind), 0f);
            var sprite = root.AddComponent<SpriteRenderer>();
            var intentText = root.AddComponent<TextMesh>();
            intentText.text = kind == EnemyKind.Archer ? "射击" : "近战";
            intentText.color = Color.white;
            var enemy = new Fighter
            {
                Kind = kind,
                Root = root,
                Sprite = sprite,
                IntentText = intentText,
                Hp = 1000f,
                MaxHp = 1000f,
                AttackTimer = 0f,
                AttackLockTimer = 0f,
                AttackToken = 44,
                Attacking = true,
                Elite = elite,
                BaseScale = Vector3.one
            };

            int tokenAtWindup = enemy.AttackToken;
            InterruptEnemyAttackOnHit(enemy, tier);

            bool interrupted = EnemyAttackInterrupted(enemy, tokenAtWindup);
            bool attackStopped = !enemy.Attacking;
            bool tokenInvalidated = enemy.AttackToken != tokenAtWindup;
            bool lockHeld = enemy.AttackLockTimer >= EnemyPostHitAttackDelay(enemy, tier) - .001f;
            bool canStart = CanEnemyStartAttack(enemy);
            bool intentCleared = enemy.IntentText && string.IsNullOrEmpty(enemy.IntentText.text) && enemy.IntentText.color.a <= .001f;
            bool ok = interrupted && attackStopped && tokenInvalidated && lockHeld && !canStart && intentCleared;
            string label = $"windup-hit-cancel-{(elite ? "elite-" : "")}{kind}-{tier}";
            lines.Add($"  {label}: interrupted={interrupted} stopped={attackStopped} token={tokenInvalidated} lock={lockHeld} canStart={canStart} intentCleared={intentCleared} {(ok ? "ok" : "failed")}");

            if (Application.isPlaying) Destroy(root);
            else DestroyImmediate(root);
            return ok ? 0 : 1;
        }

        private int DebugAuditEnemyFreezeInterruptCase(EnemyKind kind, bool elite, List<string> lines)
        {
            var root = new GameObject("DebugFreezeInterruptEnemy_" + kind);
            root.transform.SetParent(enemyRoot ? enemyRoot : transform);
            root.transform.position = new Vector3(SegmentCenters[Mathf.Clamp(currentSegment, 0, SegmentCenters.Length - 1)], GroundedEnemyY(kind), 0f);
            var sprite = root.AddComponent<SpriteRenderer>();
