                Hp = 1000f,
                MaxHp = 1000f,
                AttackTimer = 0f,
                AttackLockTimer = 0f,
                AttackToken = 31,
                Attacking = true,
                Elite = elite,
                BaseScale = Vector3.one
            };

            int tokenAtWindup = enemy.AttackToken;
            ApplyEnemyFreeze(enemy, .70f);

            bool interrupted = EnemyAttackInterrupted(enemy, tokenAtWindup);
            bool attackStopped = !enemy.Attacking;
            bool tokenInvalidated = enemy.AttackToken != tokenAtWindup;
            bool lockHeld = enemy.AttackLockTimer > .20f && enemy.AttackTimer > .20f;
            bool canStart = CanEnemyStartAttack(enemy);
            bool intentCleared = enemy.IntentText && string.IsNullOrEmpty(enemy.IntentText.text) && enemy.IntentText.color.a <= .001f;
            bool ok = interrupted && attackStopped && tokenInvalidated && lockHeld && !canStart && intentCleared;
            string label = $"{(elite ? "elite-" : "")}{kind}-freeze";
            lines.Add($"  {label}: interrupted={interrupted} stopped={attackStopped} token={tokenInvalidated} lock={lockHeld} canStart={canStart} intentCleared={intentCleared} {(ok ? "ok" : "failed")}");

            if (Application.isPlaying) Destroy(root);
            else DestroyImmediate(root);
            return ok ? 0 : 1;
        }

        private static float DebugEnemyHitReactDuration(EnemyKind kind, HitTier tier)
        {
            if (kind == EnemyKind.Boss) return .12f;
            if (tier == HitTier.Heavy) return .26f;
            if (tier == HitTier.Skill) return .23f;
            return .20f;
        }

        private static string RouteJumpGrade(float gap, float climb)
        {
            if (gap <= 1.55f && climb <= 1.30f) return "舒适";
            if (gap <= 2.95f && climb <= 2.25f) return "偏紧但可读";
            if (gap <= 4.60f && climb <= 3.65f) return "需要二段跳";
            return "风险：跳距/高差过大";
        }

        private void BuildPlatformReadabilityEdges(string name, Transform parent, Vector2 size)
        {
            Color top = new Color(.78f, .98f, 1f, .006f);
            Color ao = new Color(.01f, .020f, .018f, .014f);
            float topY = size.y * .50f - .018f;
            RectObj(name + "_PlatformWalkableSoftTop_NoFrame", parent, new Vector2(0, topY), new Vector2(Mathf.Clamp(size.x * .22f, .18f, .42f), .0025f), top, 3);
            RectObj(name + "_PlatformContactAo_SoftThin", parent, new Vector2(0, -size.y * .50f + .026f), new Vector2(size.x * .16f, .005f), ao, 0);
        }

