        private void BuildRoomMarkers()
        {
            roomMarkerLabels.Clear();
            roomMarkerIcons.Clear();
            roomGates.Clear();
            for (int i = 0; i < SegmentCenters.Length; i++)
            {
                var root = new GameObject("RoomGate_" + i);
                root.transform.SetParent(mapLayoutRoot ? mapLayoutRoot : world);
                root.transform.localPosition = new Vector3(SegmentCenters[i], GroundY + .46f, 0);
                RectObj("RoomGateInvisibleFrame_NoVisualPlate_" + i, root.transform, new Vector2(0, -.32f), new Vector2(.72f, .055f), Color.clear, 1);
                RectObj("RoomGateInvisiblePillarL_NoVisualPlate_" + i, root.transform, new Vector2(-.34f, -.26f), new Vector2(.045f, .18f), Color.clear, 1);
                RectObj("RoomGateInvisiblePillarR_NoVisualPlate_" + i, root.transform, new Vector2(.34f, -.26f), new Vector2(.045f, .18f), Color.clear, 1);
                var leftDoor = RectObj("RoomGateInvisibleDoorL_NoVisualPlate_" + i, root.transform, new Vector2(-.11f, -.27f), new Vector2(.12f, .14f), Color.clear, 1).GetComponent<SpriteRenderer>();
                var rightDoor = RectObj("RoomGateInvisibleDoorR_NoVisualPlate_" + i, root.transform, new Vector2(.11f, -.27f), new Vector2(.12f, .14f), Color.clear, 1).GetComponent<SpriteRenderer>();
                var lockGlow = CircleObj("RoomGateInvisibleLockGlow_NoVisualPlate_" + i, root.transform, new Vector2(0, -.23f), .18f, Color.clear, 1).GetComponent<SpriteRenderer>();
                var icon = SpriteObj("RoomGateInvisibleIcon_NoVisualPlate_" + i, root.transform, RuneUiSprite(i == ShopRoomIndex ? 1 : 0), new Vector2(0, -.18f), new Vector2(.22f, .22f), Color.clear, 1).GetComponent<SpriteRenderer>();
                var specialBand = RectObj("RoomGateInvisibleSpecialBand_NoVisualPlate_" + i, root.transform, new Vector2(0, -.98f), new Vector2(1.20f, .10f), Color.clear, 3).GetComponent<SpriteRenderer>();
                var specialBadge = WorldText("RoomGateSpecialBadge_" + i, root.transform, "", new Vector2(0, -.98f), 14, 5);
                var label = WorldText("RoomGateLabel_" + i, root.transform, "", new Vector2(0, .10f), 16, 5);
                var state = WorldText("RoomGateState_" + i, root.transform, "", new Vector2(0, -1.16f), 13, 5);
                roomMarkerIcons.Add(icon);
                roomMarkerLabels.Add(label);
                roomGates.Add(new RoomGateState { Root = root, Icon = icon, LeftDoor = leftDoor, RightDoor = rightDoor, LockGlow = lockGlow, SpecialBand = specialBand, Label = label, StateLabel = state, SpecialBadge = specialBadge });
            }
            UpdateRoomMarkers();
        }

