        private void ApplySafeArea()
        {
            if (!safeAreaRoot) return;
            Rect safe = Screen.safeArea;
            if (safe.width <= 0 || safe.height <= 0) safe = new Rect(0, 0, Screen.width, Screen.height);
            if (safe == lastAppliedSafeArea) return;
            lastAppliedSafeArea = safe;
            Vector2 min = safe.position;
            Vector2 max = safe.position + safe.size;
            min.x = Screen.width > 0 ? Mathf.Clamp01(min.x / Screen.width) : 0f;
            min.y = Screen.height > 0 ? Mathf.Clamp01(min.y / Screen.height) : 0f;
            max.x = Screen.width > 0 ? Mathf.Clamp01(max.x / Screen.width) : 1f;
            max.y = Screen.height > 0 ? Mathf.Clamp01(max.y / Screen.height) : 1f;
            safeAreaRoot.anchorMin = min;
            safeAreaRoot.anchorMax = max;
            safeAreaRoot.offsetMin = Vector2.zero;
            safeAreaRoot.offsetMax = Vector2.zero;
        }

        private void BuildMinimap(Transform parent)
        {
            minimapNodes.Clear();
            var root = UIBox("RouteMinimap", parent, new Vector2(0, -226), new Vector2(560, 58), new Vector2(.5f, 1), new Vector2(.5f, 1), new Color(.02f, .04f, .08f, .10f));
            routeMinimapGroup = root.gameObject.AddComponent<CanvasGroup>();
            minimapText = UIText("RouteMinimapText", root, "", 18, TextAnchor.MiddleCenter, new Vector2(0, -30), new Vector2(520, 28), new Vector2(.5f, .5f), new Vector2(.5f, .5f));
            minimapText.color = Color.clear;
            platformRouteHintText = UIText("PlatformRouteHintText", root, "", 26, TextAnchor.MiddleCenter, new Vector2(0, -64), new Vector2(700, 36), new Vector2(.5f, .5f), new Vector2(.5f, .5f));
            FitHudText(platformRouteHintText, 18, 26);
            platformRouteHintText.color = Color.clear;
            for (int i = 0; i < SegmentRights.Length; i++)
            {
                float x = -218f + i * 62f;
                if (i > 0)
                    UIBox("RouteLine_" + i, root, new Vector2(x - 30f, 3), new Vector2(42, 5), new Vector2(.5f, .5f), new Vector2(.5f, .5f), new Color(.35f, .55f, .72f, .18f));
                var node = UICircle("RouteNode_" + i, root, new Vector2(x, 3), new Vector2(36, 36), new Vector2(.5f, .5f), new Vector2(.5f, .5f), C("#52677A")).GetComponent<Image>();
                string label = i == ShopRoomIndex ? "店" : i == EliteRoomIndex ? "精" : i == BossRoomIndex ? "王" : (i + 1).ToString();
                UIText("RouteNodeLabel_" + i, node.transform, label, 19, TextAnchor.MiddleCenter, Vector2.zero, new Vector2(40, 32), new Vector2(.5f, .5f), new Vector2(.5f, .5f));
                minimapNodes.Add(node);
            }
        }

