        private void ApplyVisibleSkillSet()
        {
            // v0.1 keeps one active skill visible so the right-hand mobile controls stay readable.
            RectTransform[] buttons = { skill1ButtonUi, skill2ButtonUi, skill3ButtonUi, skill4ButtonUi };
            for (int i = 0; i < buttons.Length; i++)
                SetSkillButtonVisible(buttons[i], i < MaxVisibleCombatSkills);
        }

        private static void SetSkillButtonVisible(RectTransform button, bool visible)
        {
            if (!button) return;
            var group = button.GetComponent<CanvasGroup>();
            if (!group) group = button.gameObject.AddComponent<CanvasGroup>();
            group.alpha = visible ? 1f : 0f;
            group.interactable = visible;
            group.blocksRaycasts = visible;
            button.gameObject.SetActive(visible);
        }

        private void ApplyControlLayout()
        {
            if (!attackButtonUi) return;
            float scale = controlSizeMode == 0 ? .88f : controlSizeMode == 2 ? 1.14f : 1f;
            Vector2 reachOffset = controlReachMode == 0 ? new Vector2(10f, 32f) : controlReachMode == 2 ? new Vector2(110f, 36f) : new Vector2(62f, 22f);
            float bossFocusAttackScale = bossFocusControlLayoutActive ? BossFocusAttackButtonScale : 1f;
            float bossFocusSkillScale = bossFocusControlLayoutActive ? .80f : 1f;
            float bossFocusUtilityScale = bossFocusControlLayoutActive ? .76f : 1f;
            if (compactControls)
            {
                SetControlButton(attackButtonUi, ControlAnchoredPosition("Attack", new Vector2(-34, 178), reachOffset), new Vector2(226, 226) * scale * bossFocusAttackScale);
                SetControlButton(jumpButtonUi, ControlAnchoredPosition("Jump", new Vector2(-218, 202), reachOffset), new Vector2(136, 136) * scale * bossFocusUtilityScale);
                SetControlButton(dodgeButtonUi, ControlAnchoredPosition("Dodge", new Vector2(-170, 332), reachOffset), new Vector2(126, 126) * scale * bossFocusUtilityScale);
                SetControlButton(skill1ButtonUi, ControlAnchoredPosition("Skill1", new Vector2(-96, 438), reachOffset), new Vector2(130, 130) * scale * bossFocusSkillScale);
                SetControlButton(runeButtonUi, ControlAnchoredPosition("RuneOpen", new Vector2(-190, 512), reachOffset), new Vector2(134, 134) * scale * bossFocusUtilityScale);
            }
            else
            {
                SetControlButton(attackButtonUi, ControlAnchoredPosition("Attack", new Vector2(-36, 188), reachOffset), new Vector2(232, 232) * scale * bossFocusAttackScale);
                SetControlButton(jumpButtonUi, ControlAnchoredPosition("Jump", new Vector2(-226, 218), reachOffset), new Vector2(146, 146) * scale * bossFocusUtilityScale);
                SetControlButton(dodgeButtonUi, ControlAnchoredPosition("Dodge", new Vector2(-178, 356), reachOffset), new Vector2(134, 134) * scale * bossFocusUtilityScale);
                SetControlButton(skill1ButtonUi, ControlAnchoredPosition("Skill1", new Vector2(-100, 462), reachOffset), new Vector2(136, 136) * scale * bossFocusSkillScale);
                SetControlButton(runeButtonUi, ControlAnchoredPosition("RuneOpen", new Vector2(-198, 536), reachOffset), new Vector2(140, 140) * scale * bossFocusUtilityScale);
            }
            ApplyCombatControlOpacity();
            ApplyHitConfirmSafeLayout();
            UpdateControlEditHint();
        }

        private void RefreshBossFocusControlLayoutIfNeeded()
        {
            bool active = BossFocusControlDeclutterActive();
            if (bossFocusControlLayoutActive == active) return;
            bossFocusControlLayoutActive = active;
            ApplyControlLayout();
        }

        private void ApplyHitConfirmSafeLayout()
        {
            Vector2 center = compactControls ? new Vector2(-790, 366) : new Vector2(-860, 382);
            if (controlReachMode == 0) center.x -= 34f;
            if (controlReachMode == 2) center.x -= 104f;
            if (bossFocusControlLayoutActive)
            {
                center.x -= compactControls ? 92f : 118f;
                center.y += compactControls ? 36f : 48f;
            }
            SetHitConfirmHudPosition(center);
        }

        private void SetHitConfirmHudPosition(Vector2 center)
        {
            if (hitConfirmBackplate) hitConfirmBackplate.rectTransform.anchoredPosition = center;
            if (hitConfirmText) hitConfirmText.rectTransform.anchoredPosition = center + new Vector2(-22, 0);
            if (hitConfirmTierText) hitConfirmTierText.rectTransform.anchoredPosition = center + new Vector2(-24, 30);
            if (hitConfirmImpactBarRoot) hitConfirmImpactBarRoot.anchoredPosition = center + new Vector2(-22, -34);
        }

        private Vector2 ControlAnchoredPosition(string controlId, Vector2 basePosition, Vector2 reachOffset)
        {
            return basePosition + ControlReachOffsetForButton(controlId, reachOffset) + combatControlCustomOffset + CombatButtonOffset(controlId);
        }

        private Vector2 ControlReachOffsetForButton(string controlId, Vector2 reachOffset)
        {
            Vector2 bossFocus = bossFocusControlLayoutActive ? BossFocusButtonOffset(controlId) : Vector2.zero;
            if (controlId == "Attack") return reachOffset + bossFocus;
            if (controlId == "Jump" || controlId == "Dodge")
                return new Vector2(reachOffset.x * .38f, reachOffset.y * .58f) + bossFocus;
            if (controlId == "RuneOpen")
                return new Vector2(reachOffset.x * .20f, reachOffset.y * .70f) + bossFocus;
            return new Vector2(reachOffset.x * .30f, reachOffset.y * .70f) + bossFocus;
        }

        private static Vector2 BossFocusButtonOffset(string controlId)
        {
            if (controlId == "Attack") return new Vector2(122f, -22f);
            if (controlId == "Jump") return new Vector2(92f, -18f);
            if (controlId == "Dodge") return new Vector2(88f, -18f);
            if (controlId == "RuneOpen") return new Vector2(72f, -16f);
            return new Vector2(82f, -18f);
        }

        private Vector2 CombatButtonOffset(string controlId)
        {
            return combatButtonCustomOffsets.TryGetValue(controlId, out var offset) ? offset : Vector2.zero;
        }

        private static void SetControlButton(RectTransform button, Vector2 anchoredPosition, Vector2 size)
        {
            if (!button) return;
            size.x = Mathf.Max(size.x, CombatControlMinTouchSize);
            size.y = Mathf.Max(size.y, CombatControlMinTouchSize);
            anchoredPosition = ClampCombatControlPosition(anchoredPosition, size);
            button.anchoredPosition = anchoredPosition;
            button.sizeDelta = size;
            RefreshCombatButtonChildren(button, size);
        }

        private static void RefreshCombatButtonChildren(RectTransform button, Vector2 size)
        {
            if (!button) return;
            for (int i = 0; i < button.childCount; i++)
            {
                var child = button.GetChild(i) as RectTransform;
                if (!child) continue;
                string childName = child.name;
                if (childName.EndsWith("ReadyGlow", StringComparison.Ordinal))
                    child.sizeDelta = size * 1.18f;
                else if (childName.EndsWith("Cooldown", StringComparison.Ordinal))
                    child.sizeDelta = size * .90f;
                else if (childName.EndsWith("Rim", StringComparison.Ordinal))
                    child.sizeDelta = size * .92f;
                else if (childName == "Label")
                {
                    child.sizeDelta = size * .62f;
                    child.anchoredPosition = new Vector2(0, -size.y * .18f);
                    var label = child.GetComponent<Text>();
                    if (label)
                    {
                        label.fontSize = CombatButtonLabelSize(button.name);
                        label.resizeTextForBestFit = true;
                        label.resizeTextMinSize = Mathf.Max(16, label.fontSize - 8);
                        label.resizeTextMaxSize = label.fontSize;
                    }
                }
                else if (childName.EndsWith("CostText", StringComparison.Ordinal))
                {
                    child.sizeDelta = new Vector2(size.x * .76f, Mathf.Max(28f, size.y * .20f));
                    child.anchoredPosition = new Vector2(0, -size.y * .30f);
                }
                else if (childName.EndsWith("StateText", StringComparison.Ordinal))
                {
                    child.sizeDelta = new Vector2(size.x * .72f, Mathf.Max(26f, size.y * .18f));
                    child.anchoredPosition = new Vector2(0, size.y * .35f);
                }
                else if (childName.EndsWith("BufferText", StringComparison.Ordinal))
                {
                    child.sizeDelta = new Vector2(size.x * .76f, Mathf.Max(26f, size.y * .18f));
                    child.anchoredPosition = new Vector2(0, -size.y * .36f);
                }
            }
        }

        private static int CombatButtonLabelSize(string buttonName)
        {
            if (buttonName == "Attack") return 36;
            if (buttonName == "RuneOpen") return 32;
            if (buttonName == "Jump") return 28;
            if (buttonName == "Dodge") return 26;
            return 24;
        }

        private static Vector2 ClampCombatControlPosition(Vector2 anchoredPosition, Vector2 size)
        {
            float rightLimit = -(size.x * .5f + CombatControlSafeMargin);
            float leftLimit = Mathf.Min(CombatControlLeftLimit, rightLimit - 1f);
            float bottomLimit = size.y * .5f + CombatControlBottomSafeMargin;
            float topLimit = Mathf.Max(bottomLimit + 1f, CombatControlTopLimit);
            anchoredPosition.x = Mathf.Clamp(anchoredPosition.x, leftLimit, rightLimit);
            anchoredPosition.y = Mathf.Clamp(anchoredPosition.y, bottomLimit, topLimit);
            return anchoredPosition;
        }

        private void ApplyCombatControlOpacity()
        {
            ApplyVisibleSkillSet();
            bool blockedByRunePanel = rollingRune || (runePanel && runePanel.gameObject.activeSelf);
            bool bossFocusControls = BossFocusControlDeclutterActive();
            float baseAlpha = blockedByRunePanel ? .08f : CombatControlAlpha();
            UpdateControlDockVisual(blockedByRunePanel, bossFocusControls);
            foreach (var button in CombatControlButtons())
            {
                if (!button) continue;
                var group = button.GetComponent<CanvasGroup>();
                if (!group) group = button.gameObject.AddComponent<CanvasGroup>();
                group.alpha = CombatControlVisualAlpha(button, baseAlpha, bossFocusControls);
                group.interactable = !blockedByRunePanel;
                group.blocksRaycasts = !blockedByRunePanel;
            }
        }

        private float CombatControlVisualAlpha(RectTransform button, float baseAlpha, bool bossFocusControls)
        {
            if (!button) return baseAlpha;
            if (!bossFocusControls) return NormalCombatControlVisualAlpha(button, baseAlpha);
            if (button == attackButtonUi) return Mathf.Clamp01(Mathf.Max(baseAlpha, .42f));
            if (button == jumpButtonUi || button == dodgeButtonUi) return Mathf.Clamp01(Mathf.Min(Mathf.Min(baseAlpha, BossFocusUtilityButtonAlpha), .28f));
            if (button == runeButtonUi)
            {
                bool runeActionReady = shrineAvailable || CanUseShopInteraction();
                bool runeNearReady = fateEnergy >= RuneAnticipationThreshold;
                if (runeActionReady) return Mathf.Clamp01(Mathf.Max(baseAlpha, .50f));
                if (runeNearReady) return Mathf.Clamp01(Mathf.Min(baseAlpha, .18f));
                return .024f;
            }
            if (IsReadySkillButton(button)) return Mathf.Clamp01(Mathf.Max(Mathf.Min(baseAlpha, BossFocusSkillButtonAlpha), .18f));
            return Mathf.Clamp01(Mathf.Min(baseAlpha, .048f));
        }

        private float NormalCombatControlVisualAlpha(RectTransform button, float baseAlpha)
        {
            if (button == attackButtonUi) return Mathf.Clamp01(Mathf.Min(baseAlpha, .32f));
            if (button == jumpButtonUi || button == dodgeButtonUi) return Mathf.Clamp01(Mathf.Min(baseAlpha, .26f));
            if (button == runeButtonUi)
            {
                bool runeActionReady = shrineAvailable || CanUseShopInteraction();
                bool runeNearReady = fateEnergy >= RuneAnticipationThreshold;
                if (runeActionReady) return Mathf.Clamp01(Mathf.Max(Mathf.Min(baseAlpha, .42f), .34f));
                if (runeNearReady) return Mathf.Clamp01(Mathf.Max(Mathf.Min(baseAlpha, .28f), .20f));
                return Mathf.Clamp01(Mathf.Min(baseAlpha, .16f));
            }
            if (IsReadySkillButton(button)) return Mathf.Clamp01(Mathf.Min(baseAlpha, .24f));
            return Mathf.Clamp01(Mathf.Min(baseAlpha, .14f));
        }

        private bool IsReadySkillButton(RectTransform button)
        {
            if (!button) return false;
            if (button == skill1ButtonUi) return SkillButtonReady(SkillKind.SlashWave);
            if (button == skill2ButtonUi) return SkillButtonReady(SkillKind.Fireball);
            if (button == skill3ButtonUi) return SkillButtonReady(SkillKind.FrostNova);
            if (button == skill4ButtonUi) return SkillButtonReady(SkillKind.ThunderStrike);
            return false;
        }

        private bool SkillButtonReady(SkillKind skill)
        {
            float cd = skillCooldowns.TryGetValue(skill, out var value) ? Mathf.Max(0f, value) : 0f;
            return !CombatControlsLocked() && cd <= .05f && mp >= SkillCost(skill);
        }

        private bool BossFocusControlDeclutterActive()
        {
            return BossFocusHudActive() && !controlEditMode && !shrineAvailable && !CanUseShopInteraction();
        }

        private void UpdateControlDockVisual(bool blockedByRunePanel, bool bossFocusControls)
        {
            if (!controlDockImage) return;
            float alpha = blockedByRunePanel ? .018f : bossFocusControls ? .004f : CombatControlAlpha() * .030f;
            controlDockImage.color = new Color(.02f, .03f, .05f, alpha);
        }

        private IEnumerable<RectTransform> CombatControlButtons()
        {
            yield return attackButtonUi;
            yield return jumpButtonUi;
            yield return dodgeButtonUi;
            yield return runeButtonUi;
            if (SkillVisibleOnHud(SkillKind.SlashWave)) yield return skill1ButtonUi;
        }

        private float CombatControlAlpha()
        {
            return controlOpacityMode == 0 ? .24f : controlOpacityMode == 2 ? .50f : .34f;
        }

