        private void BuildOnboardingStep(RectTransform root, int index, string number, string title, string body, Color color)
        {
            float x = -300f + (index % 2) * 600f;
            float y = index < 2 ? -736f : -916f;
            UIBox("OnboardingStepCard_" + index, root, new Vector2(x + 150, y - 20), new Vector2(520, 148), new Vector2(.5f, 1), new Vector2(.5f, 1), new Color(.01f, .035f, .055f, .46f));
            var icon = UICircle("OnboardingStepIcon_" + index, root, new Vector2(x - 54, y), new Vector2(82, 82), new Vector2(.5f, 1), new Vector2(.5f, 1), color);
            UIText("OnboardingStepNumber_" + index, icon, number, 36, TextAnchor.MiddleCenter, Vector2.zero, new Vector2(76, 64), new Vector2(.5f, .5f), new Vector2(.5f, .5f));
            var titleText = UIText("OnboardingStepTitle_" + index, root, title, 34, TextAnchor.MiddleLeft, new Vector2(x + 32, y + 24), new Vector2(390, 44), new Vector2(.5f, 1), new Vector2(.5f, 1));
            FitHudText(titleText, 26, 34);
            var detail = UIText("OnboardingStepBody_" + index, root, body, 25, TextAnchor.UpperLeft, new Vector2(x + 32, y - 36), new Vector2(420, 68), new Vector2(.5f, 1), new Vector2(.5f, 1));
            detail.color = C("#DDF7FF");
            FitHudText(detail, 19, 25);
        }

