        private static void MakeUiPassthrough(RectTransform rect)
        {
            if (!rect) return;
            var image = rect.GetComponent<Image>();
            if (image) image.raycastTarget = false;
        }

        private void StartStage(int stage)
        {
            stageIndex = stage;
            currentSegment = 0;
            lastRoomCueSegment = -1;
            roomBannerTimer = 0;
            RollRoomModifiers();
            Array.Clear(roomPerfectDodgeStart, 0, roomPerfectDodgeStart.Length);
            Array.Clear(roomEnterRunTime, 0, roomEnterRunTime.Length);
            Array.Clear(roomQuickRunStart, 0, roomQuickRunStart.Length);
            claimedRoomRewards.Clear();
            foreach (var e in enemies.ToArray()) if (e.Root) Destroy(e.Root);
            enemies.Clear();
            foreach (var fx in hitEffects.ToArray()) if (fx.Root) Destroy(fx.Root);
            hitEffects.Clear();
            foreach (var vessel in runeVessels.ToArray()) if (vessel.Root) Destroy(vessel.Root);
            runeVessels.Clear();
            foreach (var pickup in pickups.ToArray()) if (pickup.Root) Destroy(pickup.Root);
            pickups.Clear();
            if (shopKeeper) Destroy(shopKeeper);
            if (slotShrine) Destroy(slotShrine);
            shrineAvailable = false;
            currentShrineCompletesStage = false;
            stageRuneResolved = false;
            rollingRune = false;
            lastRuneShrineSpawnTime = -999f;
            lastRuneRollFinishTime = -999f;
            automaticRuneShrinesThisStage = 0;
            choosingRoomReward = false;
            finalVictorySequenceRunning = false;
            BuildStageMapLayout(stage);
            pendingRoomRewards.Clear();
            rewardHistory.Clear();
            shopVisitedThisStage = false;
            shopHealSoldThisStage = false;
            shopRuneSoldThisStage = false;
            if (runePanel) runePanel.gameObject.SetActive(false);
            if (shopPanel) shopPanel.gameObject.SetActive(false);
            if (roomRewardPanel) roomRewardPanel.gameObject.SetActive(false);
            player.transform.position = new Vector3(-6.25f, GroundY + .72f, 0);
            movementStuckTimer = 0f;
            lastMovementFrameX = player.transform.position.x;
            facing = 1;
            cameraLookAheadX = CameraBaseLookAhead;
            RestoreHeroRenderer();
            playerSprite.flipX = false;
            SetHeroFrame(0);
            cam.transform.position = new Vector3(-1.5f, 0, -10);
            foreach (var gate in progressGates)
                if (gate) gate.SetActive(true);
            UpdateRoomMarkers();
            if (stage == 1)
            {
                tutorialStartX = player.transform.position.x;
                if (!tutorialCompleted) tutorialStep = 0;
            }
            UpdateWorldControlHintVisibility(0);
            string stageName = stage == 1 ? "第 1 关：精灵森林入口" : stage == 2 ? "第 2 关：蘑菇营地" : "第 3 关：森林守卫";
            noticeText.text = $"{stageName}  |  {MapLayoutGoalLine()}";
            if (stage == 1)
            {
                SpawnEnemy(EnemyKind.Mushroom, 1.8f);
                SpawnRandomEncounter(6.4f, 1);
                SpawnEnemy(EnemyKind.Archer, 11.6f);
                SpawnEnemy(EnemyKind.Mushroom, 13.7f, true);
                SpawnRandomEncounter(24.4f, 1);
                SpawnEnemy(EnemyKind.Archer, 31.5f, true);
                SpawnRandomEncounter(38.8f, 2);
                SpawnRandomEncounter(45.1f, 2);
                SpawnRuneVesselOnPlatform("BrokenRuneJar_A", 5.3f, .26f);
                SpawnRuneVesselOnPlatform("BrokenRuneJar_C", 33.2f, .20f);
                SpawnShopKeeper(19.4f);
            }
            else if (stage == 2)
            {
                SpawnRandomEncounter(3.2f, 1);
                SpawnEnemy(EnemyKind.Mushroom, 7.2f);
                SpawnEnemy(EnemyKind.Archer, 10.9f);
                SpawnRandomEncounter(14.2f, 2);
                SpawnRandomEncounter(25.4f, 2);
                SpawnEnemy(EnemyKind.Archer, 32.3f, true);
                SpawnRandomEncounter(39.2f, 2);
                SpawnEnemy(EnemyKind.Mushroom, 45.2f, true);
                SpawnRuneVesselOnPlatform("BrokenRuneJar_D", 8.8f, .18f);
                SpawnRuneVesselOnPlatform("BrokenRuneJar_F", 37.2f, .22f);
                SpawnShopKeeper(19.1f);
            }
            else
            {
                SpawnRandomEncounter(2.8f, 2);
                SpawnRandomEncounter(7.6f, 2);
                SpawnEnemy(EnemyKind.Archer, 12.8f);
                SpawnRandomEncounter(25.4f, 3);
                SpawnEnemy(EnemyKind.Mushroom, 32.4f, true);
                SpawnRandomEncounter(39.1f, 3);
                SpawnEnemy(EnemyKind.Boss, 44.6f);
                SpawnEnemy(EnemyKind.Archer, 43.4f);
                SpawnRuneVesselOnPlatform("BrokenRuneJar_G", 9.8f, .20f);
                SpawnRuneVesselOnPlatform("BrokenRuneJar_I", 36.4f, .26f);
                SpawnShopKeeper(19.2f);
            }
            NormalizeRoomCombatPacing(stage);
            TriggerRoomEnterCue(currentSegment);
        }

        private void RollRoomModifiers()
        {
            for (int i = 0; i < roomModifiers.Length; i++)
            {
                if (i == ShopRoomIndex || i == BossRoomIndex) roomModifiers[i] = RoomModifier.Stable;
                else if (i == EliteRoomIndex) roomModifiers[i] = rng.NextDouble() < .55 ? RoomModifier.Precision : RoomModifier.Strong;
                else
                {
                    double roll = rng.NextDouble();
                    roomModifiers[i] = roll < .22 ? RoomModifier.Swift
                        : roll < .42 ? RoomModifier.Strong
                        : roll < .62 ? RoomModifier.FateSurge
                        : roll < .80 ? RoomModifier.JarCache
                        : roll < .92 ? RoomModifier.Precision
                        : RoomModifier.Stable;
                }
                roomObjectives[i] = RoomObjectiveForModifier(roomModifiers[i], i);
            }
        }

        private static RoomObjective RoomObjectiveForModifier(RoomModifier modifier, int segment)
        {
            if (segment == ShopRoomIndex || segment == BossRoomIndex) return RoomObjective.ClearEnemies;
            if (modifier == RoomModifier.Swift) return RoomObjective.TimedClear;
            if (modifier == RoomModifier.JarCache) return RoomObjective.BreakRuneCache;
            if (modifier == RoomModifier.Precision) return RoomObjective.PrecisionDodge;
            return RoomObjective.ClearEnemies;
        }

        private void SpawnRandomEncounter(float x, int threat)
        {
            double roll = rng.NextDouble();
            bool elite = threat >= 3 && rng.NextDouble() < .22f;
            if (roll < .34)
            {
                SpawnEnemy(EnemyKind.Slime, x, elite);
                if (threat >= 2) SpawnEnemy(EnemyKind.Mushroom, x + 1.15f);
            }
            else if (roll < .67)
            {
                SpawnEnemy(EnemyKind.Mushroom, x, elite);
                if (threat >= 2) SpawnEnemy(EnemyKind.Archer, x + 1.25f);
            }
            else
            {
                SpawnEnemy(EnemyKind.Archer, x, elite);
                if (threat >= 2) SpawnEnemy(EnemyKind.Slime, x - .95f);
            }
            if (threat >= 3 && rng.NextDouble() < .35f)
                SpawnEnemy(rng.NextDouble() < .5 ? EnemyKind.Mushroom : EnemyKind.Slime, x + 1.55f);
        }

        private void NormalizeRoomCombatPacing(int stage)
        {
            PruneInvalidEnemies();
            for (int segment = 0; segment < SegmentRights.Length; segment++)
            {
                int minCount = RoomEnemyMinCounts[Mathf.Clamp(segment, 0, RoomEnemyMinCounts.Length - 1)];
                int maxCount = RoomEnemyMaxCounts[Mathf.Clamp(segment, 0, RoomEnemyMaxCounts.Length - 1)];
                var roomEnemies = EnemiesInSegment(segment).ToList();

                if (segment == ShopRoomIndex)
                {
                    CullExtraRoomEnemies(roomEnemies, 0);
                    continue;
                }

                if (segment == BossRoomIndex)
                {
                    EnsureBossRoomComposition(roomEnemies);
                    continue;
                }

                while (roomEnemies.Count < minCount)
                {
                    float x = RoomCombatSpawnX(segment, roomEnemies.Count);
                    EnemyKind kind = RoomFallbackEnemyKind(stage, segment, roomEnemies.Count);
                    bool elite = segment == EliteRoomIndex && !roomEnemies.Any(enemy => enemy.Elite);
                    SpawnEnemy(kind, x, elite);
                    roomEnemies = EnemiesInSegment(segment).ToList();
                }

                if (roomEnemies.Count > maxCount)
                {
                    CullExtraRoomEnemies(roomEnemies, maxCount);
                    roomEnemies = EnemiesInSegment(segment).ToList();
                }

                SpreadRoomEnemiesForReadability(roomEnemies, segment);
            }
        }

        private IEnumerable<Fighter> EnemiesInSegment(int segment)
        {
            return enemies.Where(enemy => enemy != null && enemy.Root && IsXInSegment(enemy.Root.transform.position.x, segment));
        }

        private void EnsureBossRoomComposition(List<Fighter> roomEnemies)
        {
            bool hasBoss = roomEnemies.Any(enemy => enemy.Boss);
            if (!hasBoss) SpawnEnemy(EnemyKind.Boss, 44.6f);

            roomEnemies = EnemiesInSegment(BossRoomIndex).ToList();
            foreach (var enemy in roomEnemies)
            {
                if (enemy == null || enemy.Boss) continue;
                if (enemy.Root) DestroyRuntimeObject(enemy.Root, 0f);
                enemy.Dead = true;
            }
            PruneInvalidEnemies();

            SpawnEnemy(EnemyKind.Archer, RoomCombatSafeLeft(BossRoomIndex) + BossRoomGuardEntranceOffset);
            PositionBossRoomActors();
        }

        private void PositionBossRoomActors()
        {
            var boss = EnemiesInSegment(BossRoomIndex).FirstOrDefault(enemy => enemy.Boss);
            var guard = EnemiesInSegment(BossRoomIndex).FirstOrDefault(enemy => !enemy.Boss && enemy.Kind == EnemyKind.Archer);
            if (guard != null && guard.Root)
                guard.Root.transform.position = new Vector3(RoomCombatSafeLeft(BossRoomIndex) + BossRoomGuardEntranceOffset, GroundedEnemyY(guard.Kind), guard.Root.transform.position.z);
            if (boss != null && boss.Root)
                boss.Root.transform.position = new Vector3(45.25f, GroundedEnemyY(boss.Kind), boss.Root.transform.position.z);
        }

        private void CullExtraRoomEnemies(List<Fighter> roomEnemies, int maxCount)
        {
            if (roomEnemies == null || roomEnemies.Count <= maxCount) return;
            var keep = roomEnemies
                .OrderByDescending(enemy => enemy.Boss)
                .ThenByDescending(enemy => enemy.Elite)
                .ThenBy(enemy => enemy.Kind == EnemyKind.Archer ? 0 : 1)
                .ThenBy(enemy => Mathf.Abs(enemy.Root.transform.position.x - SegmentCenters[Mathf.Clamp(SegmentIndexForX(enemy.Root.transform.position.x), 0, SegmentCenters.Length - 1)]))
                .Take(maxCount)
                .ToHashSet();
            foreach (var enemy in roomEnemies)
            {
                if (keep.Contains(enemy)) continue;
                if (enemy.Root) DestroyRuntimeObject(enemy.Root, 0f);
                enemy.Dead = true;
            }
            PruneInvalidEnemies();
        }

        private float RoomCombatSpawnX(int segment, int index)
        {
            float left = RoomCombatSafeLeft(segment);
            float right = RoomCombatSafeRight(segment);
            float center = SegmentCenters[Mathf.Clamp(segment, 0, SegmentCenters.Length - 1)];
            float offset = (index - .5f) * 1.28f;
            return Mathf.Clamp(center + offset, left, right);
        }

        private static float RoomCombatSafeLeft(int segment)
        {
            return segment == 0 ? LeftBound + 1.70f : SegmentRights[Mathf.Clamp(segment - 1, 0, SegmentRights.Length - 1)] + RoomEnemyEntranceSafeGap;
        }

        private static float RoomCombatSafeRight(int segment)
        {
            float exitGap = segment == BossRoomIndex ? BossRoomEnemyExitSafeGap : RoomEnemyExitSafeGap;
            return SegmentRights[Mathf.Clamp(segment, 0, SegmentRights.Length - 1)] - exitGap;
        }

        private EnemyKind RoomFallbackEnemyKind(int stage, int segment, int index)
        {
            if (segment == EliteRoomIndex) return index == 0 ? EnemyKind.Mushroom : EnemyKind.Archer;
            if (segment == 2 || segment == 6) return index % 2 == 0 ? EnemyKind.Archer : EnemyKind.Slime;
            if (stage >= 2 && index % 3 == 2) return EnemyKind.Archer;
            return index % 2 == 0 ? EnemyKind.Mushroom : EnemyKind.Slime;
        }

        private void SpreadRoomEnemiesForReadability(List<Fighter> roomEnemies, int segment)
        {
            if (roomEnemies == null || roomEnemies.Count <= 0) return;
            float left = RoomCombatSafeLeft(segment);
            float right = RoomCombatSafeRight(segment);
            if (right <= left) return;

            var ordered = roomEnemies.OrderBy(enemy => enemy.Root.transform.position.x).ToList();
            float minGap = segment == BossRoomIndex ? 1.85f : 1.35f;
            for (int i = 0; i < ordered.Count; i++)
            {
                Fighter enemy = ordered[i];
                if (enemy == null || !enemy.Root) continue;
                float targetX = Mathf.Clamp(enemy.Root.transform.position.x, left, right);
                if (i > 0)
                    targetX = Mathf.Max(targetX, ordered[i - 1].Root.transform.position.x + minGap);
                float maxAllowed = right - (ordered.Count - 1 - i) * minGap;
                targetX = Mathf.Min(targetX, maxAllowed);
                targetX = Mathf.Clamp(targetX, left, right);
                enemy.Root.transform.position = new Vector3(targetX, GroundedEnemyY(enemy.Kind), enemy.Root.transform.position.z);
            }
        }

        private void SpawnShopKeeper(float x)
