            RectObj("ShopPostL", shopKeeper.transform, new Vector2(-.38f, .05f), new Vector2(.045f, .52f), C("#675138"), 3);
            RectObj("ShopPostR", shopKeeper.transform, new Vector2(.38f, .05f), new Vector2(.045f, .52f), C("#675138"), 3);
