        private void SpawnRuneVessel(string name, float x, float shrineChance)
        {
            SpawnRuneVessel(name, x, shrineChance, GroundY + .65f, false, -1);
        }

        private void SpawnRuneVesselOnPlatform(string name, float x, float shrineChance)
        {
            SpawnRuneVessel(name, x, shrineChance, PlatformRewardChestY(x), true, -1);
        }

        private void SpawnObjectiveRuneVessel(string name, int segment, float x, float shrineChance)
        {
            SpawnRuneVessel(name, x, shrineChance, PlatformRewardChestY(x), true, segment);
        }

        private void SpawnRuneVessel(string name, float x, float shrineChance, float y, bool platformReward, int objectiveSegment)
        {
            var root = new GameObject(name);
            root.transform.SetParent(propRoot);
            root.transform.position = new Vector3(x, y, 0);
            BuildRuneChestVisual(name, root.transform, platformReward, objectiveSegment >= 0);
            BuildPlatformRewardGuide(name, root.transform, platformReward, objectiveSegment >= 0);
            runeVessels.Add(new RuneVessel { Root = root, Hp = objectiveSegment >= 0 ? 38f : 28f, ShrineChance = shrineChance, Broken = false, PlatformReward = platformReward, ObjectiveSegment = objectiveSegment });
        }

        private void BuildRuneChestVisual(string name, Transform parent, bool platformReward, bool objective)
        {
            float scale = platformReward ? PlatformRuneChestVisualScale : GroundRuneChestVisualScale;
            if (objective) scale += ObjectiveRuneChestVisualScaleBonus;
            Color wood = objective ? C("#7A4D1F") : C("#68421E");
            Color lid = objective ? C("#9A6428") : C("#845422");
            Color metal = objective ? C("#9EDFE8") : C("#8FA5A8");
            var shadow = CircleObj(name + "_ChestContactAo_CleanEllipse", parent, new Vector2(0, -.33f * scale), .50f, new Color(.012f, .020f, .016f, objective ? .34f : .26f), 1);
            shadow.transform.localScale = new Vector3(.70f * scale, .12f * scale, 1f);
            RectObj(name + "_ChestBody", parent, new Vector2(0, -.08f * scale), new Vector2(.58f * scale, .34f * scale), wood, 3);
            RectObj(name + "_ChestLid", parent, new Vector2(0, .16f * scale), new Vector2(.62f * scale, .20f * scale), lid, 4);
            RectObj(name + "_ChestRim", parent, new Vector2(0, .03f * scale), new Vector2(.66f * scale, .055f * scale), metal, 5);
            RectObj(name + "_ChestBandL", parent, new Vector2(-.20f * scale, -.04f * scale), new Vector2(.045f * scale, .36f * scale), new Color(metal.r, metal.g, metal.b, .82f), 5);
            RectObj(name + "_ChestBandR", parent, new Vector2(.20f * scale, -.04f * scale), new Vector2(.045f * scale, .36f * scale), new Color(metal.r, metal.g, metal.b, .82f), 5);
            RectObj(name + "_ChestLock", parent, new Vector2(0, -.03f * scale), new Vector2(.10f * scale, .115f * scale), C("#B8F7FF"), 6);
            SpriteObj(name + "_ChestGleam", parent, CombatVfxSprite(0), new Vector2(.18f * scale, .22f * scale), new Vector2(.20f * scale, .030f * scale), new Color(.72f, 1f, 1f, objective ? .18f : .10f), 6);
            BuildRuneChestReadableSilhouette(name, parent, scale, metal, objective);
            BuildRuneChestCompactReadabilityDetails(name, parent, scale, metal, objective);
        }

        private void BuildRuneChestReadableSilhouette(string name, Transform parent, float scale, Color metal, bool objective)
        {
            Color darkEdge = new Color(.05f, .025f, .012f, .62f);
            RectObj(name + "_ChestReadableOuterEdge", parent, new Vector2(0, -.08f * scale), new Vector2(.66f * scale, .40f * scale), darkEdge, 2);
            RectObj(name + "_ChestReadableTopEdge", parent, new Vector2(0, .27f * scale), new Vector2(.70f * scale, .055f * scale), new Color(.02f, .035f, .04f, .50f), 2);
            RectObj(name + "_ChestReadableKeyhole", parent, new Vector2(0, -.035f * scale), new Vector2(.048f * scale, .108f * scale), new Color(.05f, .035f, .02f, .78f), 7);
            RectObj(name + "_ChestReadableFloorAo", parent, new Vector2(0, -.42f * scale), new Vector2(.74f * scale, .055f * scale), new Color(.01f, .018f, .018f, .32f), 2);
            if (!objective) return;
            RectObj(name + "_ChestObjectiveCornerL", parent, new Vector2(-.33f * scale, .18f * scale), new Vector2(.085f * scale, .15f * scale), new Color(metal.r, metal.g, metal.b, .86f), 7);
            RectObj(name + "_ChestObjectiveCornerR", parent, new Vector2(.33f * scale, .18f * scale), new Vector2(.085f * scale, .15f * scale), new Color(metal.r, metal.g, metal.b, .86f), 7);
        }

        private void BuildRuneChestCompactReadabilityDetails(string name, Transform parent, float scale, Color metal, bool objective)
        {
            Color clampColor = new Color(metal.r, metal.g, metal.b, objective ? .76f : .58f);
            RectObj(name + "_ChestReadableSideClampL", parent, new Vector2(-.32f * scale, -.045f * scale), new Vector2(.030f * scale, .26f * scale), clampColor, 7);
            RectObj(name + "_ChestReadableSideClampR", parent, new Vector2(.32f * scale, -.045f * scale), new Vector2(.030f * scale, .26f * scale), clampColor, 7);
            RectObj(name + "_ChestReadableHingeTick", parent, new Vector2(0, .245f * scale), new Vector2(.18f * scale, .026f * scale), new Color(.88f, 1f, 1f, objective ? .42f : .30f), 8);
            RectObj(name + "_ChestReadableBasePixelFeetL", parent, new Vector2(-.20f * scale, -.285f * scale), new Vector2(.10f * scale, .030f * scale), new Color(.026f, .020f, .014f, .50f), 7);
            RectObj(name + "_ChestReadableBasePixelFeetR", parent, new Vector2(.20f * scale, -.285f * scale), new Vector2(.10f * scale, .030f * scale), new Color(.026f, .020f, .014f, .50f), 7);
        }

        private void BuildPlatformRewardGuide(string name, Transform parent, bool platformReward, bool objective)
        {
            if (!platformReward && !objective) return;
            Color guideColor = objective ? C("#9FF8FF") : C("#BFEFFF");
            RectObj((objective ? "ObjectiveRuneGuide_NoTexturePlate_" : "PlatformRewardGuide_NoTexturePlate_") + name, parent, new Vector2(0, -.48f), new Vector2(.07f, .002f), new Color(guideColor.r, guideColor.g, guideColor.b, objective ? .006f : 0f), 2);
            if (platformReward)
            {
                RectObj((objective ? "ObjectiveRuneLandingLine_NoTexturePlate_" : "PlatformRewardLandingLine_NoTexturePlate_") + name, parent, new Vector2(0, -.62f), new Vector2(.10f, .002f), new Color(guideColor.r, guideColor.g, guideColor.b, objective ? .007f : 0f), 2);
                RectObj((objective ? "ObjectiveRuneJumpNeedleL_NoTexturePlate_" : "PlatformRewardJumpNeedleL_NoTexturePlate_") + name, parent, new Vector2(-.32f, -.42f), new Vector2(.032f, .002f), new Color(guideColor.r, guideColor.g, guideColor.b, objective ? .008f : 0f), 3);
                RectObj((objective ? "ObjectiveRuneJumpNeedleR_NoTexturePlate_" : "PlatformRewardJumpNeedleR_NoTexturePlate_") + name, parent, new Vector2(.32f, -.42f), new Vector2(.032f, .002f), new Color(guideColor.r, guideColor.g, guideColor.b, objective ? .008f : 0f), 3);
                RectObj((objective ? "ObjectiveRuneChestAnchorTick_NoTexturePlate_" : "PlatformRewardChestAnchorTick_NoTexturePlate_") + name, parent, new Vector2(0, -.18f), new Vector2(.038f, .002f), new Color(.92f, 1f, 1f, objective ? .010f : 0f), 4);
            }
            string text = objective ? "奖励箱" : "小宝箱";
            var guideText = WorldText((objective ? "ObjectiveRuneGuideText_" : "PlatformRewardGuideText_") + name, parent, text, new Vector2(0, .74f), objective ? 13 : 12, 5);
            guideText.text = "";
            guideText.color = new Color(guideColor.r, guideColor.g, guideColor.b, 0f);
        }

        private float PlatformRewardY(float x)
        {
            var platform = platforms
                .Where(p => x > p.Left - .45f && x < p.Right + .45f)
                .OrderByDescending(p => p.Top)
                .FirstOrDefault();
            return platform != null ? platform.Top - .07f : GroundY + .65f;
        }

        private float PlatformRewardChestY(float x)
        {
            var platform = platforms
                .Where(p => x > p.Left - .45f && x < p.Right + .45f)
                .OrderByDescending(p => p.Top)
                .FirstOrDefault();
            return platform != null ? platform.Top + PlatformRewardChestLift : GroundY + .72f;
        }

        private void SpawnEnemy(EnemyKind kind, float x, bool elite = false)
        {
            var root = new GameObject(elite ? "Elite_" + kind : kind.ToString());
            root.transform.SetParent(enemyRoot);
            root.transform.position = new Vector3(x, GroundY + EnemyFootingHeight(kind), 0);
            var sr = root.AddComponent<SpriteRenderer>();
            sr.sortingOrder = kind == EnemyKind.Boss ? 13 : 12;
            int spriteIndex = EnemyIdleSpriteIndex(kind);
            spriteIndex = ResolveCleanEnemySpriteIndex(kind, spriteIndex);
            sr.sprite = enemySprites.Length > spriteIndex ? enemySprites[spriteIndex] : SpriteCache.White;
            sr.color = EnemyBaseTint(kind, elite);
            float scale = kind == EnemyKind.Boss ? 2.05f : kind == EnemyKind.Slime ? .98f : kind == EnemyKind.Archer ? 1.05f : 1.08f;
            root.transform.localScale = new Vector3(scale, scale, 1);
            var enemyShadow = CircleObj("EnemyContactAo_CleanEllipse", root.transform, new Vector2(0, kind == EnemyKind.Boss ? -.82f : -.58f), .50f, new Color(.010f, .018f, .014f, kind == EnemyKind.Boss ? .24f : .18f), 2);
            enemyShadow.transform.localScale = new Vector3(kind == EnemyKind.Boss ? 1.58f : .68f, kind == EnemyKind.Boss ? .24f : .11f, 1f);
            var silhouetteRoot = new GameObject("EnemyReadabilitySilhouette");
            silhouetteRoot.transform.SetParent(root.transform);
            silhouetteRoot.transform.localPosition = new Vector3(.035f, -.040f, .035f);
            var silhouette = silhouetteRoot.AddComponent<SpriteRenderer>();
            silhouette.sprite = sr.sprite;
            silhouette.sortingOrder = sr.sortingOrder - 1;
            silhouette.color = Color.clear;
            silhouette.enabled = false;
            BuildEnemyTypeReadabilityMarks(root.transform, kind, elite);
            BuildEnemyCuteBodyLanguage(root.transform, kind, elite);
            BuildEnemyStorybookPoseAnchors(root.transform, kind, elite);
            BuildEnemyCartoonOutlineLayer(root.transform, kind, elite);
            BuildEnemyAdventureBodyVolumes(root.transform, kind, elite);
            BuildEnemyAdventureKingStyleSilhouette(root.transform, kind, elite);
            BuildEnemyCartoonReactionAnchors(root.transform, kind, elite);
            BuildEnemyReadableFaceAndFooting(root.transform, kind, elite);
            BuildEnemyAdventureKingRoleReadabilityBadges(root.transform, kind, elite);
            BuildEnemyStorybookReadableOverlay(root.transform, kind, elite, sr.sortingOrder);
            BuildEnemyFinalStorybookSilhouette(root.transform, kind, elite, sr.sortingOrder);
            BuildEnemyAdventureMotionBodyLanguage(root.transform, kind, elite, sr.sortingOrder);
            BuildEnemySceneIntegratedPolish(root.transform, kind, elite, sr.sortingOrder);
            BuildEnemyFinalCutePlayableSilhouette(root.transform, kind, elite, sr.sortingOrder);
            BuildEnemyAdventureKingSceneFitLayer(root.transform, kind, elite, sr.sortingOrder);
            BuildEnemyHitIdentityAnchors(root.transform, kind, elite, sr.sortingOrder);
            var f = new Fighter
            {
                Kind = kind,
                Root = root,
                Sprite = sr,
                ReadabilitySilhouette = silhouette,
                Hp = kind == EnemyKind.Boss ? 580 : kind == EnemyKind.Archer ? 120 : 150,
                MaxHp = kind == EnemyKind.Boss ? 580 : kind == EnemyKind.Archer ? 120 : 150,
                Damage = kind == EnemyKind.Boss ? 28 : kind == EnemyKind.Archer ? 14 : 18,
                Speed = kind == EnemyKind.Boss ? 1.1f : kind == EnemyKind.Archer ? 1f : 1.8f,
                AttackRange = kind == EnemyKind.Archer ? 6.4f : kind == EnemyKind.Boss ? 7.2f : 1.2f,
                BaseScale = root.transform.localScale,
                Boss = kind == EnemyKind.Boss,
                Elite = elite
            };
            if (elite)
            {
                f.Hp *= 1.55f;
                f.MaxHp *= 1.55f;
                f.Damage *= 1.18f;
                f.Speed *= .92f;
                sr.color = EnemyBaseTint(kind, true);
                var eliteAura = CircleObj("EliteToxicAura_ThinNoPlate", root.transform, new Vector2(0, -.12f), 1.18f, new Color(.18f, 1f, .46f, .080f), 2);
                eliteAura.transform.localScale = new Vector3(1.42f, .34f, 1f);
                RectObj("EliteToxicAuraNeedle_ThinNoPlate", root.transform, new Vector2(0, -.58f), new Vector2(.52f, .018f), new Color(.70f, 1f, .78f, .11f), 5);
                var eliteLabel = WorldText("EliteLabel", root.transform, "精英", new Vector2(0, 1.25f), 20, 18);
                eliteLabel.color = new Color(.62f, 1f, .38f, .70f);
            }
            ApplyTrialHeatToEnemy(f);
            ApplyRoomModifierToEnemy(f);
            f.BaseColor = sr.color;
            f.IntentRing = CircleObj("EnemyIntentReadRing", root.transform, new Vector2(0, -.44f), kind == EnemyKind.Boss ? 1.45f : .82f, Color.clear, kind == EnemyKind.Boss ? 7 : 5).GetComponent<SpriteRenderer>();
            f.IntentText = WorldText("EnemyIntentReadText", root.transform, "", new Vector2(0, kind == EnemyKind.Boss ? 2.0f : 1.34f), kind == EnemyKind.Boss ? 24 : 18, 24);
            f.IntentText.color = Color.clear;
            f.StatusText = WorldText("EnemyStatusText", root.transform, "", new Vector2(0, kind == EnemyKind.Boss ? 2.42f : 1.62f), kind == EnemyKind.Boss ? 22 : 17, 24);
            f.StatusText.color = Color.clear;
            f.HpFill = CreateEnemyHpBar(root.transform, out f.HpBarRoot);
            ApplyEnemyHpBarVisibility(f, 0f);
            enemies.Add(f);
        }

        private static float EnemyFootingHeight(EnemyKind kind)
        {
            if (kind == EnemyKind.Boss) return 1.12f;
            if (kind == EnemyKind.Slime) return .84f;
            if (kind == EnemyKind.Archer) return .94f;
            if (kind == EnemyKind.Mushroom) return .96f;
            return .90f;
        }

        private void BuildEnemyHitIdentityAnchors(Transform parent, EnemyKind kind, bool elite, int baseOrder)
        {
            if (!parent || kind == EnemyKind.Boss) return;
            float eliteBoost = elite ? 1.18f : 1f;
            int order = baseOrder + 5;
            RectObj("EnemyHitIdentityFreezeFootAnchor_NoPlate", parent, new Vector2(0f, -.63f), new Vector2(kind == EnemyKind.Archer ? .32f : kind == EnemyKind.Slime ? .54f : .42f, .005f), new Color(.74f, .96f, 1f, .030f * eliteBoost), order);
            if (kind == EnemyKind.Archer)
            {
                RectObj("EnemyHitIdentityArcherBowStringAnchor_NoPlate", parent, new Vector2(.40f, .20f), new Vector2(.006f, .54f), new Color(.92f, 1f, 1f, .040f * eliteBoost), order);
                RectObj("EnemyHitIdentityArcherShoulderBrace_NoPlate", parent, new Vector2(.18f, .28f), new Vector2(.18f, .008f), new Color(.72f, .96f, 1f, .034f * eliteBoost), order);
            }
            else if (kind == EnemyKind.Slime)
            {
                RectObj("EnemyHitIdentitySlimeSquashAnchor_NoPlate", parent, new Vector2(0f, -.24f), new Vector2(.54f, .008f), new Color(.70f, 1f, .84f, .040f * eliteBoost), order);
                CircleObj("EnemyHitIdentitySlimeGlossAnchor_NoPlate", parent, new Vector2(.16f, .34f), .022f, new Color(.92f, 1f, .94f, .042f * eliteBoost), order);
            }
            else if (kind == EnemyKind.Mushroom)
            {
                RectObj("EnemyHitIdentityMushroomCapBrace_NoPlate", parent, new Vector2(0f, .51f), new Vector2(.54f, .008f), new Color(1f, .78f, .70f, .040f * eliteBoost), order);
                RectObj("EnemyHitIdentityMushroomStemBrace_NoPlate", parent, new Vector2(0f, .04f), new Vector2(.24f, .008f), new Color(1f, .86f, .66f, .030f * eliteBoost), order);
            }
        }

        private void BuildEnemyTypeReadabilityMarks(Transform parent, EnemyKind kind, bool elite)
        {
            if (!parent) return;
            Color markColor = elite ? C("#A8FFC8") : kind == EnemyKind.Archer ? C("#BFEFFF") : kind == EnemyKind.Boss ? C("#FF6B6B") : C("#DCEFFF");
            if (kind == EnemyKind.Archer)
            {
                RectObj("EnemyArcherReadMarkBow_Thin", parent, new Vector2(.34f, .22f), new Vector2(.026f, .24f), new Color(markColor.r, markColor.g, markColor.b, .070f), 4);
                RectObj("EnemyArcherReadMarkString_Thin", parent, new Vector2(.38f, .22f), new Vector2(.008f, .24f), new Color(.04f, .070f, .075f, .10f), 5);
                RectObj("EnemyArcherReadMarkFeather_CuteThin", parent, new Vector2(-.20f, .62f), new Vector2(.12f, .022f), new Color(.78f, .96f, 1f, .080f), 5);
            }
            else if (kind == EnemyKind.Boss)
            {
                RectObj("EnemyBossReadMarkCore", parent, new Vector2(0, .54f), new Vector2(.36f, .12f), new Color(markColor.r, markColor.g, markColor.b, .34f), 5);
                RectObj("EnemyBossReadMarkBase_DisabledNoGroundBlob", parent, new Vector2(0, -.82f), new Vector2(.98f, .070f), Color.clear, 3);
            }
            else if (kind == EnemyKind.Slime)
            {
                CircleObj("EnemySlimeReadMarkGloss_Cute", parent, new Vector2(-.18f, .42f), .070f, new Color(.86f, 1f, .96f, .13f), 5);
                RectObj("EnemySlimeReadMarkSquashLine_CuteThin", parent, new Vector2(.04f, -.12f), new Vector2(.34f, .018f), new Color(.66f, 1f, .82f, .065f), 5);
            }
            else if (kind == EnemyKind.Mushroom)
            {
                RectObj("EnemyMushroomReadMarkCapStripe_Cute", parent, new Vector2(0, .58f), new Vector2(.42f, .034f), new Color(.98f, .82f, .72f, .11f), 5);
                CircleObj("EnemyMushroomReadMarkCheek_Cute", parent, new Vector2(.24f, .20f), .040f, new Color(1f, .72f, .66f, .10f), 5);
                RectObj("EnemyMeleeReadMarkClawL_Thin", parent, new Vector2(-.30f, .16f), new Vector2(.024f, .15f), new Color(markColor.r, markColor.g, markColor.b, .052f), 4);
                RectObj("EnemyMeleeReadMarkClawR_Thin", parent, new Vector2(.30f, .16f), new Vector2(.024f, .15f), new Color(markColor.r, markColor.g, markColor.b, .052f), 4);
            }
            else
            {
                RectObj("EnemyMeleeReadMarkClawL_Thin", parent, new Vector2(-.30f, .16f), new Vector2(.024f, .15f), new Color(markColor.r, markColor.g, markColor.b, .060f), 4);
                RectObj("EnemyMeleeReadMarkClawR_Thin", parent, new Vector2(.30f, .16f), new Vector2(.024f, .15f), new Color(markColor.r, markColor.g, markColor.b, .060f), 4);
            }
            var foot = RectObj("EnemyTypeFootSignature_DisabledNoGroundBlob", parent, new Vector2(0, -.66f), kind == EnemyKind.Boss ? new Vector2(1.04f, .038f) : new Vector2(.28f, .010f), Color.clear, 3);
            foot.transform.localRotation = Quaternion.Euler(0, 0, elite ? 0f : kind == EnemyKind.Archer ? -4f : 4f);
            if (!elite) return;
            RectObj("EliteReadableCrownBar_ThinNoPlate", parent, new Vector2(0, 1.08f), new Vector2(.44f, .034f), new Color(.70f, 1f, .78f, .16f), 6);
            RectObj("EliteReadableCrownTip_ThinNoPlate", parent, new Vector2(0, 1.17f), new Vector2(.14f, .052f), new Color(.70f, 1f, .78f, .14f), 6);
        }

        private static Color EnemyBaseTint(EnemyKind kind, bool elite)
        {
            Color baseTint = kind == EnemyKind.Boss ? new Color(.98f, 1f, .96f, 1f)
                : kind == EnemyKind.Archer ? new Color(.86f, .96f, 1f, 1f)
                : kind == EnemyKind.Slime ? new Color(.86f, 1f, .92f, 1f)
                : kind == EnemyKind.Mushroom ? new Color(1f, .90f, .84f, 1f)
                : Color.white;
            if (!elite) return baseTint;
            return Color.Lerp(baseTint, new Color(.74f, 1f, .84f, 1f), .22f);
        }

        private void BuildEnemyCuteBodyLanguage(Transform parent, EnemyKind kind, bool elite)
        {
            if (!parent || kind == EnemyKind.Boss) return;
            float eliteBoost = elite ? 1.18f : 1f;
            if (kind == EnemyKind.Archer)
