                RectObj("EnemyCuteArcherColdEarL_ThinNoPlate", parent, new Vector2(-.22f, .56f), new Vector2(.052f, .18f), new Color(.72f, .92f, 1f, .060f * eliteBoost), 5).transform.localRotation = Quaternion.Euler(0f, 0f, -18f);
                RectObj("EnemyCuteArcherColdEarR_ThinNoPlate", parent, new Vector2(.12f, .56f), new Vector2(.052f, .17f), new Color(.72f, .92f, 1f, .052f * eliteBoost), 5).transform.localRotation = Quaternion.Euler(0f, 0f, 16f);
                RectObj("EnemyCuteArcherTinyQuiver_ThinNoPlate", parent, new Vector2(-.36f, .10f), new Vector2(.060f, .22f), new Color(.46f, .68f, .72f, .058f * eliteBoost), 4).transform.localRotation = Quaternion.Euler(0f, 0f, -10f);
                CircleObj("EnemyCuteArcherEyeGlint_NoPlate", parent, new Vector2(.13f, .33f), .024f, new Color(.90f, 1f, 1f, .075f * eliteBoost), 6);
            }
            else if (kind == EnemyKind.Slime)
            {
                CircleObj("EnemyCuteSlimeBubbleGlossA_NoPlate", parent, new Vector2(-.10f, .36f), .042f, new Color(.86f, 1f, .94f, .090f * eliteBoost), 6);
                CircleObj("EnemyCuteSlimeBubbleGlossB_NoPlate", parent, new Vector2(.10f, .28f), .026f, new Color(.86f, 1f, .94f, .065f * eliteBoost), 6);
                RectObj("EnemyCuteSlimeSoftBellySquash_ThinNoPlate", parent, new Vector2(.02f, -.21f), new Vector2(.42f, .014f), new Color(.48f, .92f, .70f, .060f * eliteBoost), 5);
                RectObj("EnemyCuteSlimeSideWobble_ThinNoPlate", parent, new Vector2(-.31f, .05f), new Vector2(.018f, .12f), new Color(.48f, .92f, .70f, .044f * eliteBoost), 5).transform.localRotation = Quaternion.Euler(0f, 0f, -10f);
            }
            else if (kind == EnemyKind.Mushroom)
