        private void ApplyRoomModifierToEnemy(Fighter enemy)
        {
            if (enemy == null || enemy.Boss || !enemy.Root) return;
            var modifier = RoomModifierAtPosition(enemy.Root.transform.position.x);
            if (modifier == RoomModifier.Swift)
            {
                enemy.Speed *= 1.18f;
                enemy.AttackTimer *= .85f;
                enemy.Sprite.color = Color.Lerp(EnemyBaseTint(enemy.Kind, enemy.Elite), new Color(.86f, 1f, 1f, 1f), .18f);
            }
            else if (modifier == RoomModifier.Strong)
            {
                enemy.Hp *= 1.16f;
                enemy.MaxHp *= 1.16f;
                enemy.Damage *= 1.12f;
                enemy.Sprite.color = Color.Lerp(EnemyBaseTint(enemy.Kind, enemy.Elite), new Color(1f, .84f, .80f, 1f), .20f);
            }
            else if (modifier == RoomModifier.Precision)
            {
                enemy.Speed *= 1.06f;
                enemy.Sprite.color = Color.Lerp(EnemyBaseTint(enemy.Kind, enemy.Elite), new Color(.94f, .91f, 1f, 1f), .16f);
            }
        }

        private void ApplyTrialHeatToEnemy(Fighter enemy)
        {
            if (enemy == null || trialHeatLevel <= 0) return;
            float hpScale = TrialHeatEnemyHpScale();
            float damageScale = TrialHeatEnemyDamageScale();
            float speedScale = TrialHeatEnemySpeedScale();
            enemy.Hp *= hpScale;
            enemy.MaxHp *= hpScale;
            enemy.Damage *= damageScale;
            enemy.Speed *= speedScale;
            if (enemy.Sprite && !enemy.Elite)
                enemy.Sprite.color = Color.Lerp(EnemyBaseTint(enemy.Kind, false), new Color(1f, .76f, .72f, 1f), trialHeatLevel / 6f);
        }

        private Image CreateEnemyHpBar(Transform parent, out RectTransform hpBarRoot)
        {
            var go = new GameObject("EnemyHpCanvas", typeof(RectTransform), typeof(Canvas));
            go.transform.SetParent(parent);
            go.transform.localPosition = new Vector3(0, .92f, 0);
            go.transform.localScale = Vector3.one * .01f;
            hpBarRoot = go.GetComponent<RectTransform>();
            var c = go.GetComponent<Canvas>();
            c.renderMode = RenderMode.WorldSpace;
            c.sortingOrder = 6;
            var bg = UIBox("Bg", go.transform, Vector2.zero, new Vector2(110, 9), new Vector2(.5f, .5f), new Vector2(.5f, .5f), new Color(.14f, .04f, .05f, .68f));
            return UIFillBox("Fill", bg, new Vector2(110, 9), C("#D83A3A")).GetComponent<Image>();
        }

        private void ReadKeyboardAndMove(float dt)
        {
            float x = CurrentHorizontalMoveInput();
            bool up = Input.GetKey(KeyCode.W) || Input.GetKey(KeyCode.UpArrow);
            bool down = Input.GetKey(KeyCode.S) || Input.GetKey(KeyCode.DownArrow);
            if (touchMoveActive)
            {
                up |= JoystickAllowsJumpAxis() && touchMoveInput.y > JoystickJumpAxisThreshold;
                down |= touchMoveInput.y < -.58f;
            }
            UpdateQuickRunIntent(x, down, dt);
            UpdateQuickRunAirCarry(x, down, dt);
            bool quickRun = QuickRunActive(x, down);
            bool quickRunAirCarry = QuickRunAirCarryActive(x, down);
            TrackQuickRunRoomUsage(quickRun, dt);
            float speed = (down ? 2.4f : 4.2f) * moveMultiplier * ((quickRun || quickRunAirCarry) ? QuickRunSpeedMultiplier : 1f);
            var pos = player.transform.position;
            bool wasGrounded = grounded;
            float beforeX = pos.x;
            float beforeY = pos.y;
            pos.x += x * speed * dt;
            float movementRight = IntentAwareMovementRight(beforeX, x);
            bool gateActuallyLocked = CurrentGateActuallyLocksPlayer(currentSegment);
            bool pushedIntoLockedGate = x > .12f && beforeX < movementRight - .02f && pos.x > movementRight + .01f && gateActuallyLocked;
            bool pressedAgainstLockedGate = x > .12f && beforeX >= movementRight - .025f && gateActuallyLocked;
            pos.x = Mathf.Clamp(pos.x, LeftBound, movementRight);
            ApplyGateEdgeSoftReleaseNudge(ref pos, x, beforeX, movementRight);
            ApplyOpenRouteIntentUnstickNudge(ref pos, x, beforeX, movementRight);
            ApplyPlatformEdgeHorizontalEscape(ref pos, x, beforeX, movementRight);
            if (pushedIntoLockedGate || pressedAgainstLockedGate) ShowLockedGateBump();
            verticalVelocity -= 18f * dt;
            pos.y += verticalVelocity * dt;
            float landingY = GroundY + .72f;
            Platform landingPlatform = null;
            bool assistedPlatformLanding = false;
            float assistedLandingX = pos.x;
            grounded = false;
            foreach (var p in platforms)
            {
                if (platformDropThroughTimer > 0f && p == platformDropThroughTarget) continue;
                bool crossingTop = beforeY >= p.Top - .08f && pos.y <= p.Top && verticalVelocity <= .12f;
                if (!crossingTop) continue;
                float landingEdgeAssistX = PlatformLandingEdgeAssistX + (quickRunAirCarry ? QuickRunLandingEdgeAssistBonus : 0f);
                bool inside = pos.x > p.Left && pos.x < p.Right;
                bool nearLeftEdge = !inside && pos.x >= p.Left - landingEdgeAssistX && pos.x <= p.Left && x > .05f;
                bool nearRightEdge = !inside && pos.x <= p.Right + landingEdgeAssistX && pos.x >= p.Right && x < -.05f;
                if (!inside && !nearLeftEdge && !nearRightEdge) continue;
                if (p.Top < landingY) continue;
                landingY = p.Top;
                landingPlatform = p;
                assistedPlatformLanding = nearLeftEdge || nearRightEdge;
                assistedLandingX = nearLeftEdge
                    ? p.Left + PlatformLandingEdgeSnapInset + PlatformLandingStableEdgeTolerance
                    : nearRightEdge
                        ? p.Right - PlatformLandingEdgeSnapInset - PlatformLandingStableEdgeTolerance
                        : pos.x;
            }
            if (pos.y <= landingY)
            {
                pos.y = landingY;
                if (assistedPlatformLanding && landingPlatform != null)
                    pos.x = Mathf.Clamp(assistedLandingX, landingPlatform.Left + PlatformLandingEdgeSnapInset + PlatformLandingStableEdgeTolerance, landingPlatform.Right - PlatformLandingEdgeSnapInset - PlatformLandingStableEdgeTolerance);
                verticalVelocity = 0;
                grounded = true;
                groundedGraceTimer = .10f;
                airJumpsRemaining = MaxAirJumps;
                if (!wasGrounded)
                {
                    player.transform.position = pos;
                    ContinueQuickRunAfterLanding(x, quickRunAirCarry);
                    SpawnFootDust("LandDust", .9f, .26f);
                    if (assistedPlatformLanding) SpawnPlatformLandingAssistCue(pos);
                    TriggerHeroPosePunch(new Vector2(1.10f, .88f), .13f);
                }
            }
            player.transform.position = pos;
            bool jumpHeld = up || touchJumpHeld || Input.GetKey(KeyCode.K) || Input.GetKey(KeyCode.JoystickButton0);
            if (up && !jumpAxisHeldLastFrame) RequestJump();
            if (!jumpHeld && jumpHeldLastFrame) CutJumpHeight();
            jumpHeldLastFrame = jumpHeld;
            jumpAxisHeldLastFrame = up;
            TryConsumeJumpBuffer();
            if (Mathf.Abs(x) > .05f)
            {
                facing = x > 0 ? 1 : -1;
                playerSprite.flipX = facing < 0;
                if (heroActionLockTimer <= 0)
                {
                    walkAnimTimer += dt;
                    float runFps = RunAnimFps * (quickRun ? 1.10f : 1f);
                    SetHeroFrame(HeroRunFrames[Mathf.FloorToInt(walkAnimTimer * runFps) % HeroRunFrames.Length]);
                    if (grounded)
                    {
                        runFootstepTimer -= dt;
                        if (runFootstepTimer <= 0f)
                        {
                            runFootstepTimer = quickRun ? QuickRunFootstepInterval : RunFootstepInterval;
                            SpawnFootDust(quickRun ? "QuickRunStepDust_NoYellowPlate" : "RunStepDust", quickRun ? .56f : .46f, quickRun ? .13f : .12f);
                            TriggerHeroPosePunch(quickRun ? new Vector2(1.050f, .980f) : new Vector2(1.035f, .985f), quickRun ? .060f : .055f);
                        }
                    }
                }
                dashRuneFootTraceTimer -= dt;
                if (dashRuneLevel > 0 && grounded && dashRuneFootTraceTimer <= 0)
                {
                    dashRuneFootTraceTimer = Mathf.Max(.24f, .36f - dashRuneLevel * .018f);
                    SpawnTimedRect("DashRuneFootTraceCleanTick_NoTexturePlate", player.transform.position + Vector3.down * .52f - Vector3.right * facing * .12f, new Vector2(.18f, .004f), new Color(.52f, .96f, 1f, .009f), 4, .024f);
                }
            }
            else if (grounded && attackCooldown <= 0)
            {
                runFootstepTimer = 0f;
                if (heroActionLockTimer <= 0)
                {
                    heroAnimTimer += dt;
                    SetHeroFrame(HeroIdleFrames[Mathf.FloorToInt(heroAnimTimer * IdleAnimFps) % HeroIdleFrames.Length]);
                }
            }
            else if (!grounded && attackCooldown <= 0)
            {
                runFootstepTimer = 0f;
                if (heroActionLockTimer <= 0) SetHeroFrame(verticalVelocity >= 0 ? HeroJumpFrame : HeroFallFrame);
            }
            NormalizePlayerSupport(false);
            RecoverPlayerIfMovementStuck(x, beforeX, beforeY, pushedIntoLockedGate || pressedAgainstLockedGate, dt);
            UpdateHeroLandingPredictor();
        }

        private void RecoverPlayerIfMovementStuck(float horizontalInput, float beforeX, float beforeY, bool intentionallyBlockedByGate, float dt)
        {
            if (!player || titleActive || paused || inputLocked || rollingRune || intentionallyBlockedByGate)
            {
                movementStuckTimer = 0f;
                return;
            }

            Vector3 pos = player.transform.position;
            bool hasMoveIntent = Mathf.Abs(horizontalInput) >= MovementStuckRecoverInputThreshold;
            float frameMoved = Mathf.Max(Mathf.Abs(pos.x - beforeX), Mathf.Abs(pos.x - lastMovementFrameX));
            bool movedEnough = frameMoved >= MovementStuckRecoverDistanceThreshold;
            bool pinnedVertically = grounded || Mathf.Abs(pos.y - beforeY) < MovementStuckRecoverDistanceThreshold;
            float movementRight = AllowedMovementRight(pos.x);
            bool atHorizontalLimit = horizontalInput < 0f
                ? pos.x <= LeftBound + MovementStuckRecoverDistanceThreshold
                : pos.x >= movementRight - MovementStuckRecoverDistanceThreshold;
            bool recoverableFalseRightClamp = horizontalInput > 0f && atHorizontalLimit && IsRecoverableFalseRightClamp(pos.x, movementRight);
            bool recoverableOpenRouteRightLimit = horizontalInput > 0f
                && atHorizontalLimit
                && !CurrentGateActuallyLocksPlayer(currentSegment)
                && ShouldForceOpenRouteOnRightIntent(pos.x, movementRight);
            if (!hasMoveIntent || movedEnough || !pinnedVertically || (atHorizontalLimit && !recoverableFalseRightClamp && !recoverableOpenRouteRightLimit))
            {
                movementStuckTimer = 0f;
                lastMovementFrameX = pos.x;
                return;
            }

            movementStuckTimer += dt;
            if (movementStuckTimer < MovementStuckRecoverDelay) return;

            if (horizontalInput > MovementStuckRecoverInputThreshold && !CurrentGateActuallyLocksPlayer(currentSegment))
                movementRight = OpenRouteStuckRecoveryRight(pos.x, movementRight);

            if (recoverableFalseRightClamp)
            {
                ReconcileMovementSegmentWithPlayerPosition();
                movementRight = RecoverableFalseClampMovementRight(pos.x, movementRight);
            }
            if (horizontalInput > MovementStuckRecoverInputThreshold && ShouldForceOpenRouteOnRightIntent(pos.x, movementRight))
                movementRight = OpenRouteRightIntentFallback(pos.x, movementRight);

            if (!TryFindMovementStuckRecovery(pos, Mathf.Sign(horizontalInput), beforeY, movementRight, out Vector3 recovered))
            {
                if (!TryEmergencyOpenRouteRelease(pos, horizontalInput, movementRight, out recovered))
                {
                    movementStuckTimer = 0f;
                    lastMovementFrameX = pos.x;
                    return;
                }
            }

            pos = recovered;
            player.transform.position = pos;
            verticalVelocity = 0f;
            grounded = true;
            groundedGraceTimer = .10f;
            ClearPlatformDropThrough();
            movementStuckTimer = 0f;
            lastMovementFrameX = pos.x;
            SpawnTimedSprite("MovementStuckAutoRecoverFootPin_NoYellowPlate", CombatVfxSprite(0), pos + Vector3.down * .50f, new Vector2(.18f, .010f), new Color(.72f, .96f, 1f, .035f), 7, .060f);
            NormalizePlayerSupport(true);
        }

        private bool TryEmergencyOpenRouteRelease(Vector3 pos, float horizontalInput, float movementRight, out Vector3 recovered)
        {
            recovered = pos;
            if (horizontalInput <= MovementStuckRecoverInputThreshold) return false;
            if (CurrentGateActuallyLocksPlayer(currentSegment)) return false;

            ReconcileMovementSegmentWithPlayerPosition();
            float releaseRight = OpenRouteStuckRecoveryRight(pos.x, movementRight);
            releaseRight = Mathf.Max(releaseRight, OpenRouteRightIntentFallback(pos.x, movementRight));
            float candidateX = Mathf.Min(releaseRight, pos.x + OpenRouteEmergencyReleaseNudge);
            if (candidateX <= pos.x + MovementStuckRecoverMinAdvance) return false;

            float supportY = StableSupportYAtX(candidateX, pos.y + PlatformSupportUnstickTolerance + MovementStuckSupportCeilingBonus);
            recovered = new Vector3(candidateX, supportY, pos.z);
            return true;
        }

        private bool TryFindMovementStuckRecovery(Vector3 pos, float direction, float beforeY, float movementRight, out Vector3 recovered)
        {
            recovered = pos;
            if (Mathf.Abs(direction) < .50f) return false;

            float supportCeiling = Mathf.Max(beforeY, pos.y) + PlatformSupportUnstickTolerance + MovementStuckSupportCeilingBonus;
            if (TryRecoverOffPlatformEdge(pos, direction, movementRight, supportCeiling, out recovered))
                return true;

            for (int i = 1; i <= MovementStuckRecoverProbeCount; i++)
            {
                float offset = MovementStuckRecoverNudge * i;
                float candidateX = Mathf.Clamp(pos.x + direction * offset, LeftBound, movementRight);
                float advance = Mathf.Abs(candidateX - pos.x);
                if (advance < MovementStuckRecoverMinAdvance) continue;

                float candidateY = StableSupportYAtX(candidateX, supportCeiling);
                if (candidateY > supportCeiling + PlatformSupportSnapEpsilon) continue;

                recovered = new Vector3(candidateX, candidateY, pos.z);
                return true;
            }

            return false;
        }

        private bool TryRecoverOffPlatformEdge(Vector3 pos, float direction, float movementRight, float supportCeiling, out Vector3 recovered)
        {
            recovered = pos;
            Platform platform = CurrentStandingPlatformAt(pos, PlatformSupportUnstickTolerance + PlatformEdgeEscapeSupportToleranceBonus + MovementStuckSupportCeilingBonus);
            if (platform == null) return false;

            float edgeX = direction > 0f
                ? platform.Right + PlatformLandingEdgeAssistX + PlatformEdgeStuckRecoveryOutset
                : platform.Left - PlatformLandingEdgeAssistX - PlatformEdgeStuckRecoveryOutset;
            float candidateX = Mathf.Clamp(edgeX, LeftBound, movementRight);
            if (Mathf.Abs(candidateX - pos.x) < MovementStuckRecoverMinAdvance) return false;

            float candidateY = StableSupportYAtX(candidateX, supportCeiling);
            if (candidateY > supportCeiling + PlatformSupportSnapEpsilon) return false;

            recovered = new Vector3(candidateX, candidateY, pos.z);
            return true;
        }

        private void ApplyGateEdgeSoftReleaseNudge(ref Vector3 pos, float horizontalInput, float beforeX, float movementRight)
        {
            if (horizontalInput <= MovementStuckRecoverInputThreshold) return;
            if (currentSegment < 0 || currentSegment >= SegmentRights.Length - 1) return;
            if (CurrentGateActuallyLocksPlayer(currentSegment)) return;

            float gateX = SegmentRights[currentSegment];
            if (beforeX < gateX - GateEdgeSoftReleaseRange || beforeX > gateX + GateEdgeSoftReleaseRange) return;

            float targetX = Mathf.Min(movementRight, beforeX + GateEdgeSoftReleaseNudge);
            if (targetX <= pos.x + .004f) return;
            pos.x = Mathf.Clamp(targetX, LeftBound, movementRight);
        }

        private void ApplyOpenRouteIntentUnstickNudge(ref Vector3 pos, float horizontalInput, float beforeX, float movementRight)
        {
            if (horizontalInput <= MovementStuckRecoverInputThreshold) return;
            if (currentSegment < 0 || currentSegment >= SegmentRights.Length - 1) return;
            if (CurrentGateActuallyLocksPlayer(currentSegment)) return;
            if (!ShouldForceOpenRouteOnRightIntent(beforeX, movementRight) && !IsRecoverableFalseRightClamp(beforeX, movementRight)) return;

            float targetRight = OpenRouteRightIntentFallback(beforeX, movementRight);
            if (targetRight <= beforeX + MovementStuckRecoverMinAdvance) return;
            float targetX = Mathf.Min(targetRight, beforeX + OpenRouteIntentSoftNudge);
            if (targetX <= pos.x + .006f) return;
            pos.x = Mathf.Clamp(targetX, LeftBound, targetRight);
        }

        private float OpenRouteStuckRecoveryRight(float playerX, float movementRight)
        {
            if (CurrentGateActuallyLocksPlayer(currentSegment)) return movementRight;
            int playerSegment = Mathf.Clamp(SegmentIndexForX(playerX), 0, SegmentRights.Length - 1);
            int routeSegment = Mathf.Max(currentSegment, playerSegment);
            float nextOpen = routeSegment >= SegmentRights.Length - 1 ? RightBound : NextOpenMovementRight(routeSegment);
            float boosted = Mathf.Max(movementRight, playerX + MovementStuckOpenRouteBoost, nextOpen);
            return Mathf.Clamp(boosted, LeftBound, RightBound);
        }

        private bool ShouldForceOpenRouteOnRightIntent(float playerX, float movementRight)
        {
            if (currentSegment < 0 || currentSegment >= SegmentRights.Length - 1) return false;
            if (CurrentGateActuallyLocksPlayer(currentSegment)) return false;
            if (movementRight >= RightBound - .12f) return false;
            float gateX = SegmentRights[Mathf.Clamp(currentSegment, 0, SegmentRights.Length - 1)];
            if (playerX < gateX - OpenRouteRightIntentGateGrace) return false;
            if (PlayerHasOnlyOptionalBlockersAhead(currentSegment, playerX)) return true;
            return CurrentRoomCanAdvance(currentSegment)
                || RoomBlockingEnemyCount(currentSegment) <= 0
                || StaleBehindEnemyLockShouldCatchUp(currentSegment, playerX)
                || GateEdgeSoftUnlockShouldCatchUp(currentSegment, playerX);
        }

        private bool PlayerHasOnlyOptionalBlockersAhead(int segment, float playerX)
        {
            if (segment < 0 || segment >= SegmentRights.Length - 1) return false;
            if (RoomBlockingEnemyCount(segment) > 0) return false;
            return ActivePlatformRuneVesselInSegment(segment) || playerX >= SegmentRights[segment] - OpenRouteRightIntentGateGrace;
        }

        private float OpenRouteRightIntentFallback(float playerX, float movementRight)
        {
            int playerSegment = Mathf.Clamp(SegmentIndexForX(playerX), 0, SegmentRights.Length - 1);
            int routeSegment = Mathf.Max(currentSegment, playerSegment);
            float nextOpen = routeSegment >= SegmentRights.Length - 1 ? RightBound : NextOpenMovementRight(routeSegment);
            float boosted = Mathf.Max(movementRight, playerX + OpenRouteRightIntentFallbackBoost, nextOpen);
            return Mathf.Clamp(boosted, LeftBound, RightBound);
        }

        private void ApplyPlatformEdgeHorizontalEscape(ref Vector3 pos, float horizontalInput, float beforeX, float movementRight)
        {
            if (!grounded || Mathf.Abs(horizontalInput) < MovementStuckRecoverInputThreshold) return;
            Platform platform = CurrentStandingPlatformAt(new Vector3(beforeX, pos.y, pos.z), PlatformSupportUnstickTolerance + PlatformEdgeEscapeSupportToleranceBonus);
            if (platform == null) return;
            float edgeEscapeMovementRight = Mathf.Max(movementRight, IntentAwareMovementRight(beforeX, horizontalInput));

            if (horizontalInput > 0f)
            {
                float rightSupportEdge = platform.Right - PlatformLandingEdgeSnapInset;
                if (beforeX < rightSupportEdge - PlatformEdgeHorizontalEscapeGrace) return;
                if (pos.x > rightSupportEdge + PlatformSupportSnapEpsilon) return;
                float targetX = Mathf.Min(edgeEscapeMovementRight, platform.Right + PlatformLandingEdgeAssistX + PlatformEdgeHorizontalEscapeNudge);
                if (targetX > pos.x + .010f) pos.x = targetX;
            }
            else
            {
                float leftSupportEdge = platform.Left + PlatformLandingEdgeSnapInset;
                if (beforeX > leftSupportEdge + PlatformEdgeHorizontalEscapeGrace) return;
                if (pos.x < leftSupportEdge - PlatformSupportSnapEpsilon) return;
                float targetX = Mathf.Max(LeftBound, platform.Left - PlatformLandingEdgeAssistX - PlatformEdgeHorizontalEscapeNudge);
                if (targetX < pos.x - .010f) pos.x = targetX;
            }
        }

        private bool IsRecoverableFalseRightClamp(float playerX, float movementRight)
        {
            if (movementRight >= RightBound - .12f) return false;
            if (currentSegment < 0 || currentSegment >= SegmentRights.Length) return false;
            if (CurrentRoomCanAdvance(currentSegment) || RoomBlockingEnemyCount(currentSegment) <= 0) return true;
            if (ActivePlatformRuneVesselInSegment(currentSegment)) return true;

            var target = NearestBlockingEnemyForLockedGate();
            return target != null && target.Root && target.Root.transform.position.x > playerX + .34f;
        }

        private float RecoverableFalseClampMovementRight(float playerX, float movementRight)
        {
            int playerSegment = Mathf.Clamp(SegmentIndexForX(playerX), 0, SegmentRights.Length - 1);
            int targetSegment = Mathf.Max(currentSegment, playerSegment);
            float nextOpen = targetSegment >= SegmentRights.Length - 1 ? RightBound : NextOpenMovementRight(targetSegment);
            float boosted = Mathf.Max(movementRight, playerX + FalseRightClampRecoverBoost, VisibleCombatApproachMovementRight(playerX), nextOpen);
            return Mathf.Clamp(boosted, LeftBound, RightBound);
        }

        private float IntentAwareMovementRight(float playerX, float horizontalInput)
        {
            float movementRight = AllowedMovementRight(playerX);
            if (horizontalInput > MovementStuckRecoverInputThreshold && IsRecoverableFalseRightClamp(playerX, movementRight))
                return RecoverableFalseClampMovementRight(playerX, movementRight);
            if (horizontalInput > MovementStuckRecoverInputThreshold && ShouldForceOpenRouteOnRightIntent(playerX, movementRight))
                return OpenRouteRightIntentFallback(playerX, movementRight);
            return movementRight;
        }

        private float ClampIntentAwarePlayerX(float playerX, float targetX, float horizontalIntent)
        {
            return Mathf.Clamp(targetX, LeftBound, IntentAwareMovementRight(playerX, horizontalIntent));
        }

        private void NormalizePlayerSupport(bool forceSnap)
        {
            if (!player || titleActive || paused || rollingRune || platformDropThroughTimer > 0f) return;
            Vector3 pos = player.transform.position;
            float supportY = StableSupportYAtX(pos.x, pos.y + PlatformSupportUnstickTolerance);
            bool sunkIntoSupport = pos.y < supportY - PlatformSupportSnapEpsilon;
            bool groundedButOffSupport = grounded && Mathf.Abs(pos.y - supportY) > PlatformSupportSnapEpsilon && pos.y < supportY + PlatformSupportUnstickTolerance;
            if (!forceSnap && !sunkIntoSupport && !groundedButOffSupport) return;

            pos.y = supportY;
            pos.x = ClampIntentAwarePlayerX(pos.x, pos.x, facing);
            player.transform.position = pos;
            if (verticalVelocity < .12f) verticalVelocity = 0f;
            grounded = true;
            groundedGraceTimer = .10f;
            airJumpsRemaining = MaxAirJumps;
            ClearPlatformDropThrough();
        }

        private float StableSupportYAtX(float x)
        {
            return StableSupportYAtX(x, float.PositiveInfinity);
        }

        private float StableSupportYAtX(float x, float currentY)
        {
            float y = GroundY + .72f;
            foreach (var p in platforms)
            {
                if (!HasStablePlatformSupportAtX(p, x)) continue;
                if (p.Top > currentY + .045f) continue;
                if (p.Top > y) y = p.Top;
            }
            return y;
        }

        private static bool HasStablePlatformSupportAtX(Platform platform, float x)
        {
            if (platform == null) return false;
            return x >= platform.Left + PlatformLandingEdgeSnapInset && x <= platform.Right - PlatformLandingEdgeSnapInset;
        }

        private void UpdateHeroLandingPredictor()
        {
            if (!heroLandingPredictor || !player) return;
            if (grounded || inputLocked || titleActive)
            {
                heroLandingPredictor.color = Color.clear;
                if (heroLandingPredictorEdge) heroLandingPredictorEdge.color = Color.clear;
                return;
            }
            float predictedX = PredictedLandingX();
            Platform landingPlatform = PredictedLandingPlatform(predictedX, player.transform.position.y);
            float landingY = landingPlatform != null ? landingPlatform.Top : GroundY + .72f;
            heroLandingPredictor.transform.position = new Vector3(predictedX, landingY - .54f, 0f);
            float distance = Mathf.Clamp(player.transform.position.y - landingY, .05f, 3.4f);
            float alpha = Mathf.Lerp(landingPlatform != null ? .024f : .016f, landingPlatform != null ? .008f : .006f, distance / 3.4f) * (effectsIntensity > .75f ? .78f : .52f);
            Color color = verticalVelocity <= 0f ? C("#9FF8FF") : C("#BFEFFF");
            heroLandingPredictor.color = new Color(color.r, color.g, color.b, alpha);
            float pulse = 1f + Mathf.Sin(Time.time * 8f) * .045f;
            float widthScale = landingPlatform != null ? Mathf.Clamp(landingPlatform.Width * .46f, .92f, 1.62f) : 1.36f;
            heroLandingPredictor.transform.localScale = new Vector3(widthScale * pulse, landingPlatform != null ? .27f : .22f, 1f);
            if (heroLandingPredictorEdge)
            {
                float edgeAlpha = Mathf.Clamp01(alpha + (landingPlatform != null ? .006f : .004f));
                heroLandingPredictorEdge.color = new Color(.96f, 1f, 1f, edgeAlpha);
                float edgeWidth = landingPlatform != null ? Mathf.Clamp(landingPlatform.Width * .30f, .72f, 1.18f) : .82f;
                heroLandingPredictorEdge.transform.localScale = new Vector3(edgeWidth + Mathf.Sin(Time.time * 8f) * .018f, 1f, 1f);
            }
        }

        private float CurrentHorizontalMoveInput()
        {
            float x = Input.GetAxisRaw("Horizontal");
            if (Input.GetKey(KeyCode.A) || Input.GetKey(KeyCode.LeftArrow)) x = -1f;
            if (Input.GetKey(KeyCode.D) || Input.GetKey(KeyCode.RightArrow)) x = 1f;
            if (touchMoveActive) x = touchMoveInput.x;
            return Mathf.Clamp(x, -1f, 1f);
        }

        private void UpdateQuickRunIntent(float horizontalInput, bool down, float dt)
        {
            quickRunCueTimer = Mathf.Max(0f, quickRunCueTimer - dt);
            if (CombatControlsLocked() || Mathf.Abs(horizontalInput) < .05f || down)
            {
                quickRunTimer = Mathf.Max(0f, quickRunTimer - dt * 2.4f);
                return;
            }

            int dir = horizontalInput > 0f ? 1 : -1;
            bool keyboardTap = dir > 0
                ? Input.GetKeyDown(KeyCode.D) || Input.GetKeyDown(KeyCode.RightArrow)
                : Input.GetKeyDown(KeyCode.A) || Input.GetKeyDown(KeyCode.LeftArrow);
            if (keyboardTap)
            {
                float now = Time.unscaledTime;
                float lastTap = dir > 0 ? lastRightTapTime : lastLeftTapTime;
                if (now - lastTap <= QuickRunInputWindow) ActivateQuickRun(dir);
                if (dir > 0) lastRightTapTime = now;
                else lastLeftTapTime = now;
            }

            if (JoystickFullTiltQuickRun(horizontalInput))
                ActivateQuickRun(dir, .16f);

            if (quickRunDirection == dir && quickRunTimer > 0f)
                quickRunTimer = Mathf.Max(0f, quickRunTimer - dt);
            else
                quickRunTimer = Mathf.Max(0f, quickRunTimer - dt * 2.0f);
        }

        private bool JoystickFullTiltQuickRun(float horizontalInput)
        {
            return touchMoveActive
                && Mathf.Abs(horizontalInput) >= QuickRunJoystickThreshold
                && Mathf.Abs(touchMoveInput.x) > Mathf.Abs(touchMoveInput.y) * 1.15f;
        }

        private bool QuickRunActive(float horizontalInput, bool down)
        {
            if (down || quickRunTimer <= 0f || !grounded || Mathf.Abs(horizontalInput) < .65f) return false;
            return quickRunDirection == (horizontalInput > 0f ? 1 : -1);
        }

        private void UpdateQuickRunAirCarry(float horizontalInput, bool down, float dt)
        {
            if (down || inputLocked || Mathf.Abs(horizontalInput) < QuickRunAirCarryMinInput)
            {
                quickRunAirCarryTimer = Mathf.Max(0f, quickRunAirCarryTimer - dt * 2.6f);
                return;
            }
            if (grounded)
            {
                quickRunAirCarryTimer = 0f;
                return;
            }
            quickRunAirCarryTimer = Mathf.Max(0f, quickRunAirCarryTimer - dt);
        }

        private bool QuickRunAirCarryActive(float horizontalInput, bool down)
        {
            if (down || grounded || quickRunAirCarryTimer <= 0f || Mathf.Abs(horizontalInput) < QuickRunAirCarryMinInput) return false;
            return quickRunAirCarryDirection == (horizontalInput > 0f ? 1 : -1);
        }

        private void StartQuickRunJumpCarry()
        {
            float horizontalInput = CurrentHorizontalMoveInput();
            if (Mathf.Abs(horizontalInput) < .55f || quickRunTimer <= 0f) return;
            int direction = horizontalInput > 0f ? 1 : -1;
            if (quickRunDirection != direction) return;
            quickRunAirCarryDirection = direction;
            quickRunAirCarryTimer = QuickRunAirCarryDuration;
            quickRunCameraTimer = Mathf.Max(quickRunCameraTimer, .24f);
            SpawnQuickRunJumpCarryCue(direction);
        }

        private void SpawnQuickRunJumpCarryCue(int direction)
        {
            if (!player || !fxRoot) return;
            Vector3 basePos = player.transform.position + Vector3.down * .50f;
            SpawnTimedRect("QuickRunJumpCarryFootLine_NoYellowPlate", basePos - Vector3.right * direction * .16f, new Vector2(.38f, .008f), new Color(.72f, .96f, 1f, .050f), 8, .060f);
            SpawnTimedRect("QuickRunJumpCarryLiftTick_NoYellowPlate", basePos + Vector3.right * direction * .18f + Vector3.up * .12f, new Vector2(.18f, .006f), new Color(.92f, 1f, 1f, .054f), 8, .055f);
        }

        private void ContinueQuickRunAfterLanding(float horizontalInput, bool carriedQuickRun)
        {
            if (!carriedQuickRun || Mathf.Abs(horizontalInput) < .55f) return;
            int direction = horizontalInput > 0f ? 1 : -1;
            if (quickRunAirCarryDirection != direction) return;
            quickRunDirection = direction;
            quickRunTimer = Mathf.Max(quickRunTimer, QuickRunLandingCarryDuration);
            quickRunCameraTimer = Mathf.Max(quickRunCameraTimer, .20f);
            SpawnQuickRunLandingCarryCue(direction);
        }

        private void SpawnQuickRunLandingCarryCue(int direction)
        {
            if (!player || !fxRoot) return;
            Vector3 basePos = player.transform.position + Vector3.down * .52f;
            SpawnTimedRect("QuickRunLandingCarryFootLine_NoYellowPlate", basePos - Vector3.right * direction * .18f, new Vector2(.32f, .007f), new Color(.72f, .96f, 1f, .046f), 8, .055f);
            SpawnTimedRect("QuickRunLandingCarryForwardTick_NoYellowPlate", basePos + Vector3.right * direction * .22f + Vector3.up * .04f, new Vector2(.14f, .006f), new Color(.92f, 1f, 1f, .050f), 8, .050f);
        }

        private void TrackQuickRunRoomUsage(bool quickRun, float dt)
        {
            quickRunCameraTimer = Mathf.Max(0f, quickRunCameraTimer - dt);
            if (!quickRun) return;
            quickRunTimeThisRun += dt;
            quickRunCameraTimer = .24f;
        }

        private void ActivateQuickRun(int direction, float minimumDuration = QuickRunHoldDuration)
        {
            int nextDirection = direction >= 0 ? 1 : -1;
            bool alreadyRunning = quickRunDirection == nextDirection && quickRunTimer > .05f;
            quickRunDirection = nextDirection;
            quickRunTimer = Mathf.Max(quickRunTimer, minimumDuration);
            if (alreadyRunning || quickRunCueTimer > 0f || !grounded || !player) return;
            quickRunCueTimer = .18f;
            SpawnQuickRunStartCue(quickRunDirection);
        }

        private void SpawnQuickRunStartCue(int direction)
        {
            Vector3 basePos = player.transform.position + Vector3.down * .52f;
            SpawnTimedRect("QuickRunStartFootLine_NoYellowPlate", basePos - Vector3.right * direction * .12f, new Vector2(.34f, .008f), new Color(.72f, .96f, 1f, .055f), 8, .055f);
            SpawnTimedRect("QuickRunSpeedTick_NoYellowPlate", basePos - Vector3.right * direction * .34f + Vector3.up * .035f, new Vector2(.16f, .006f), new Color(.92f, 1f, 1f, .060f), 8, .050f);
        }

        private float PredictedLandingX()
        {
            if (!player) return LeftBound;
            float horizontal = CurrentHorizontalMoveInput();
            float intent = Mathf.Abs(horizontal);
            float fallFactor = Mathf.Clamp01(Mathf.Abs(verticalVelocity) / 8f + .22f);
            float lead = Mathf.Lerp(LandingPredictorHorizontalLead * .32f, LandingPredictorMaxLeadX, intent * fallFactor);
            float predictedX = player.transform.position.x + horizontal * lead;
            return Mathf.Clamp(predictedX, LeftBound, AllowedMovementRight(player.transform.position.x));
        }

        private void SpawnPlatformLandingAssistCue(Vector3 position)
        {
            if (!fxRoot) return;
            SpawnTimedSprite("PlatformLandingEdgeAssistPin_NoYellowPlate", CombatVfxSprite(0), position + new Vector3(facing * .18f, -.46f, 0f), new Vector2(.020f, .006f), new Color(.72f, .92f, 1f, .006f), 8, .028f);
        }

        private Platform PredictedLandingPlatform(float x, float currentY)
        {
            Platform best = null;
            foreach (var p in platforms)
            {
                if (x <= p.Left || x >= p.Right || currentY < p.Top - .12f) continue;
                if (best == null || p.Top > best.Top) best = p;
            }
            return best;
        }

        private void UpdateCameraFollow()
        {
            if (!cam || !player) return;
            float halfWidth = cam.orthographicSize * cam.aspect;
            float lookAhead = ComputeCameraLookAhead();
            cameraLookAheadX = Mathf.Lerp(cameraLookAheadX, lookAhead, Time.deltaTime * CameraLookAheadLerp);
            float targetX = Mathf.Clamp(player.transform.position.x + cameraLookAheadX, -1.5f, RightBound - halfWidth + .45f);
            float targetY = Mathf.Clamp(player.transform.position.y - .15f, -.2f, 1.8f);
            if (TryGetCombatCameraThreat(out var threat))
            {
                Vector3 playerPos = player.transform.position;
                Vector3 threatPos = threat.Root.transform.position;
                float side = Mathf.Sign(threatPos.x - playerPos.x);
                float threatBias = threat.Boss ? .48f : threat.Elite ? .42f : .34f;
                float threatTargetX = Mathf.Lerp(playerPos.x, threatPos.x, threatBias) + side * .28f;
                targetX = Mathf.Clamp(Mathf.Lerp(targetX, threatTargetX, CameraThreatFocusBlend), -1.5f, RightBound - halfWidth + .45f);
                float threatTargetY = Mathf.Clamp(Mathf.Lerp(playerPos.y, threatPos.y, .28f) - .10f, -.2f, 1.8f);
                targetY = Mathf.Lerp(targetY, threatTargetY, CameraThreatVerticalBlend);
            }
            if (BossRightHandUiAvoidanceActive())
                targetX = Mathf.Clamp(targetX + BossRightHandUiFinalCameraShift, -1.5f, RightBound - halfWidth + .45f);
            var pos = cam.transform.position;
            pos.x = Mathf.Lerp(pos.x, targetX, Time.deltaTime * 4.5f);
            pos.y = Mathf.Lerp(pos.y, targetY, Time.deltaTime * 2.8f);
            if (cameraShakeTimer > 0)
            {
                cameraShakeTimer -= Time.deltaTime;
                pos.x += UnityEngine.Random.Range(-cameraShakeAmount, cameraShakeAmount);
                pos.y += UnityEngine.Random.Range(-cameraShakeAmount, cameraShakeAmount);
                cameraShakeAmount = Mathf.Lerp(cameraShakeAmount, 0, Time.deltaTime * 8f);
            }
            cam.transform.position = pos;
            if (worldHints) worldHints.position = new Vector3(pos.x, 0, 0);
            UpdateWorldControlHintVisibility(Time.deltaTime);
        }

        private bool TryGetCombatCameraThreat(out Fighter threat)
        {
            threat = null;
            if (!player || titleActive || paused || inputLocked) return false;
            Vector3 playerPos = player.transform.position;
            float maxDistance = BossFocusHudActive() ? CameraThreatFocusMaxDistance * 1.65f : CameraThreatFocusMaxDistance;
            threat = enemies
                .Where(e => e != null && !e.Dead && e.Root && (e.Boss || IsXInSegment(e.Root.transform.position.x, currentSegment)))
                .Where(e => Mathf.Abs(e.Root.transform.position.x - playerPos.x) <= maxDistance)
                .OrderByDescending(e => e.Boss ? 5 : e.Elite ? 4 : e.Kind == EnemyKind.Archer ? 3 : e.Kind == EnemyKind.Slime ? 2 : 1)
                .ThenBy(e => Vector2.Distance(e.Root.transform.position, playerPos))
                .FirstOrDefault();
            return threat != null;
        }

        private float ComputeCameraLookAhead()
        {
            float horizontal = touchMoveActive ? touchMoveInput.x : Input.GetAxisRaw("Horizontal");
            if (Input.GetKey(KeyCode.A) || Input.GetKey(KeyCode.LeftArrow)) horizontal -= 1f;
            if (Input.GetKey(KeyCode.D) || Input.GetKey(KeyCode.RightArrow)) horizontal += 1f;
            float intent = Mathf.Abs(horizontal) > .18f ? Mathf.Sign(horizontal) : facing;
            float magnitude = Mathf.Clamp01(Mathf.Abs(horizontal));
            bool advancing = intent > 0f;
            float baseDistance = advancing ? Mathf.Lerp(CameraBaseLookAhead, CameraForwardLookAhead, magnitude) : CameraBacktrackLookAhead;
            float roomEndGap = CurrentSegmentRight() - player.transform.position.x;
            if (roomEndGap < 4.2f)
                baseDistance = Mathf.Min(baseDistance, Mathf.Lerp(.82f, CameraBaseLookAhead, Mathf.Clamp01(roomEndGap / 4.2f)));
            if (advancing && quickRunCameraTimer > 0f)
                baseDistance += QuickRunCameraLookAheadBonus * Mathf.Clamp01(magnitude);
            if (BossRightHandUiAvoidanceActive())
                baseDistance += BossRightHandUiSafeLookAhead;
            return Mathf.Max(.72f, baseDistance * (advancing ? 1f : .72f));
        }

        private bool BossRightHandUiAvoidanceActive()
        {
            if (!player || !BossFocusHudActive()) return false;
            var boss = enemies.FirstOrDefault(e => e.Boss && !e.Dead && e.Root);
            if (boss == null) return false;
            return boss.Root.transform.position.x > player.transform.position.x - .5f;
        }

        private void RequestJump()
        {
            if (controlEditMode) return;
            if (inputLocked) return;
            if (ShouldDropThroughPlatform(out Platform platform))
            {
                DropThroughPlatform(platform);
                return;
            }
            jumpBufferTimer = JumpInputBufferDuration;
            TryConsumeJumpBuffer();
        }

        private bool ShouldDropThroughPlatform(out Platform platform)
        {
            platform = null;
            if (!grounded || !player) return false;
            if (!DownInputHeldForDropThrough()) return false;
            platform = CurrentStandingPlatform();
            return platform != null;
        }

        private bool DownInputHeldForDropThrough()
        {
            if (Input.GetKey(KeyCode.S) || Input.GetKey(KeyCode.DownArrow)) return true;
            if (Input.GetAxisRaw("Vertical") < -.58f) return true;
            return touchMoveActive && touchMoveInput.y < -.58f;
        }

        private Platform CurrentStandingPlatform()
        {
            if (!player) return null;
            return CurrentStandingPlatformAt(player.transform.position, .16f);
        }

        private Platform CurrentStandingPlatformAt(Vector3 pos, float verticalTolerance)
        {
            Platform best = null;
            foreach (var p in platforms)
            {
                if (pos.x < p.Left + PlatformLandingEdgeSnapInset - PlatformLandingStableEdgeTolerance || pos.x > p.Right - PlatformLandingEdgeSnapInset + PlatformLandingStableEdgeTolerance) continue;
                if (Mathf.Abs(pos.y - p.Top) > verticalTolerance) continue;
                if (best == null || p.Top > best.Top) best = p;
            }
            return best;
        }

        private void DropThroughPlatform(Platform platform)
        {
            if (platform == null || !player) return;
            platformDropThroughTarget = platform;
            platformDropThroughTimer = PlatformDropThroughDuration;
            grounded = false;
            groundedGraceTimer = 0f;
            jumpBufferTimer = 0f;
            verticalVelocity = Mathf.Min(verticalVelocity, PlatformDropThroughVelocity);
            var pos = player.transform.position;
            pos.y -= .12f;
            player.transform.position = pos;
            SpawnPlatformDropThroughCue(pos);
            TriggerHeroPosePunch(new Vector2(.96f, 1.05f), .080f);
            ShowHeroActionBeat("下落穿台", new[] { HeroFallFrame }, JumpAnimFps, .34f, "下方向 + 跳跃 / 只穿当前平台", C("#BDEAFF"));
        }

        private void SpawnPlatformDropThroughCue(Vector3 position)
        {
            if (!fxRoot) return;
            SpawnTimedSprite("PlatformDropThroughFootLine_NoYellowPlate", CombatVfxSprite(0), position + Vector3.down * .58f, new Vector2(.24f, .006f), new Color(.70f, .94f, 1f, .018f), 7, .040f);
            SpawnTimedSprite("PlatformDropThroughDownTick_NoYellowPlate", CombatVfxSprite(0), position + new Vector3(0f, -.72f, 0f), new Vector2(.026f, .040f), new Color(.90f, 1f, 1f, .020f), 8, .045f);
        }

        private void ClearPlatformDropThrough()
        {
            platformDropThroughTimer = 0f;
            platformDropThroughTarget = null;
        }

        private void TryConsumeJumpBuffer()
        {
            if (jumpBufferTimer <= 0f || inputLocked || !player) return;
            bool canGroundJump = grounded || groundedGraceTimer > 0f;
            if (!canGroundJump && airJumpsRemaining <= 0) return;
            Jump(!canGroundJump);
            jumpBufferTimer = 0f;
        }

        private void Jump(bool airJump = false)
        {
            if (controlEditMode) return;
            bool canGroundJump = grounded || groundedGraceTimer > 0f;
            if ((!canGroundJump && (!airJump || airJumpsRemaining <= 0)) || inputLocked) return;
            if (airJump)
            {
                airJumpsRemaining--;
                SpawnAirJumpFeedback();
            }
            else
            {
                StartQuickRunJumpCarry();
                SpawnFootDust("JumpDust", .74f, .2f);
                airJumpsRemaining = MaxAirJumps;
            }
            verticalVelocity = airJump ? 7.75f : 8.6f;
            grounded = false;
            groundedGraceTimer = 0f;
            jumpCutApplied = false;
            TriggerHeroPosePunch(new Vector2(.90f, 1.10f), .12f);
            PlayHeroFrames(HeroJumpFrames, JumpAnimFps, .12f);
            ShowHeroActionBeat(airJump ? "二段跳" : "起跳", HeroJumpFrames, JumpAnimFps, .46f, airJump ? "空中补跳 / 调整落点" : "PointerDown 立即起跳 / 松手截跳", C("#BDEAFF"));
        }

        private void SpawnAirJumpFeedback()
        {
            if (!player || !fxRoot) return;
            Vector3 pos = player.transform.position + new Vector3(-facing * .10f, -.28f, 0);
            var ring = SpawnTimedRect("AirJumpCrispRing_NoTexturePlate", pos, new Vector2(.62f, .022f), new Color(.70f, .96f, 1f, .18f), 6, .09f);
            if (ring) ring.transform.localScale = new Vector3(Mathf.Abs(ring.transform.localScale.x) * -facing, ring.transform.localScale.y, 1f);
            var cut = SpawnTimedRect("AirJumpLiftTick_NoTexturePlate", pos + Vector3.up * .10f, new Vector2(.52f, .020f), new Color(.90f, 1f, 1f, .20f), 8, .09f);
            if (cut) cut.transform.localRotation = Quaternion.Euler(0, 0, facing * -10f);
        }

        private void CutJumpHeight()
        {
            if (grounded || jumpCutApplied || verticalVelocity <= JumpCutMinVelocity) return;
            verticalVelocity *= JumpCutVelocityMultiplier;
            jumpCutApplied = true;
            SpawnJumpCutFeedback();
        }

