        {
            if (!player || !fxRoot) return;
            var dust = SpawnTimedRect("JumpCutDustCleanLine_NoTexturePlate", player.transform.position + new Vector3(-facing * .08f, -.38f, 0), new Vector2(.50f, .018f), new Color(.82f, .94f, 1f, .095f), 5, .065f);
            dust.transform.localScale = new Vector3(Mathf.Abs(dust.transform.localScale.x) * -facing, dust.transform.localScale.y, 1f);
