        private void RequestBasicAttack()
        {
            if (controlEditMode)
            {
                PulseControlButton(attackButtonUi);
                return;
            }
            if (inputLocked) return;
            PulseControlButton(attackButtonUi);
            if (attackCooldown <= 0)
            {
                attackBufferTimer = 0f;
                BasicAttack();
                return;
            }
            attackBufferTimer = AttackInputBufferDuration;
        }

        private void ConsumeBufferedAttack()
        {
            if (attackBufferTimer <= 0f || attackCooldown > 0f || inputLocked) return;
            string label = combo == 2 ? "破势" : "接刀";
            attackBufferTimer = 0f;
            attackBufferConfirmTimer = .24f;
            SpawnAttackBufferConsumedCue(label);
            BasicAttack();
        }

        private bool TryPrepareAutoAttack()
        {
            if (!autoAttackEnabled || inputLocked || !player || !grounded || rollingRune) return false;
            float bestDistance = float.MaxValue;
            float targetDx = 0f;
            GameObject targetRoot = null;
            bool found = false;
            Vector3 origin = player.transform.position;

            foreach (var e in enemies)
            {
                if (e == null || e.Dead || !e.Root) continue;
                Vector3 delta = e.Root.transform.position - origin;
                float distance = Mathf.Abs(delta.x) + Mathf.Abs(delta.y) * .35f;
                if (Mathf.Abs(delta.x) > 3.15f || Mathf.Abs(delta.y) > 1.9f || distance >= bestDistance) continue;
                bestDistance = distance;
                targetDx = delta.x;
                targetRoot = e.Root;
                found = true;
            }

            foreach (var vessel in runeVessels)
            {
                if (vessel.Broken || !vessel.Root) continue;
                Vector3 delta = vessel.Root.transform.position - origin;
                float distance = Mathf.Abs(delta.x) + Mathf.Abs(delta.y) * .45f;
                if (Mathf.Abs(delta.x) > 2.75f || Mathf.Abs(delta.y) > 1.9f || distance >= bestDistance) continue;
                bestDistance = distance;
                targetDx = delta.x;
                targetRoot = vessel.Root;
                found = true;
            }

            if (!found) return false;
            if (Mathf.Abs(targetDx) > .12f)
            {
                facing = targetDx > 0 ? 1 : -1;
                if (playerSprite) playerSprite.flipX = facing < 0;
            }
            ShowAutoAimTargetCue(targetRoot, "自动攻击");
            return true;
        }

        private void TriggerSkillButton(RectTransform button, SkillKind skill)
        {
            if (!SkillVisibleOnHud(skill)) return;
            PulseControlButton(button);
            if (controlEditMode) return;
            HideSkillAimPreview();
            RequestSkill(skill);
        }

        private void RequestSkill(SkillKind skill)
        {
            if (controlEditMode) return;
            if (!SkillVisibleOnHud(skill)) return;
            if (inputLocked) return;
            HideSkillAimPreview();
            if (CastSkill(skill)) return;
            if (mp < SkillCost(skill))
            {
                if (noticeText) noticeText.text = "魔力不足";
                return;
            }
            float cd = SkillCooldownRemaining(skill);
            if (cd <= SkillInputBufferDuration + .035f)
                QueueSkillBuffer(skill, SkillChainWindowLocked() ? SkillChainInputBufferDuration : SkillInputBufferDuration);
        }

        private void TryConsumeBufferedSkills()
        {
            if (inputLocked || controlEditMode) return;
            foreach (SkillKind skill in SkillBufferOrder())
            {
                if (!SkillBuffered(skill)) continue;
                if (CastSkill(skill, true))
                {
                    skillBufferTimers[skill] = 0f;
                    return;
                }
            }
        }

        private bool SkillBuffered(SkillKind skill)
        {
            return skillBufferTimers.TryGetValue(skill, out float timer) && timer > .03f;
        }

        private bool SkillChainWindowLocked()
        {
            return heroActionLockTimer > SkillChainActionLockThreshold || attackCooldown > SkillChainAttackCooldownThreshold;
        }

        private void QueueSkillBuffer(SkillKind skill, float duration)
        {
            bool newlyQueued = !SkillBuffered(skill);
            skillBufferTimers[skill] = Mathf.Max(skillBufferTimers.TryGetValue(skill, out float timer) ? timer : 0f, duration);
            if (newlyQueued) SpawnSkillBufferIntentCue(skill);
        }

        private float SkillCooldownRemaining(SkillKind skill)
        {
            return skillCooldowns.TryGetValue(skill, out float cd) ? Mathf.Max(0f, cd) : 0f;
        }

        private static IEnumerable<SkillKind> SkillBufferOrder()
        {
            yield return SkillKind.SlashWave;
            yield return SkillKind.Fireball;
            yield return SkillKind.FrostNova;
            yield return SkillKind.ThunderStrike;
        }

        private void ClearSkillBuffers()
        {
            skillBufferTimers.Clear();
        }

        private void SpawnSkillBufferConsumedCue(SkillKind skill)
        {
            RectTransform button = SkillButtonFor(skill);
            if (!button) return;
            Color color = SkillButtonSignalColor(skill);
            var tick = UIBox("SkillBufferConsumedTick", button, new Vector2(0, 82), new Vector2(76, 7), new Vector2(.5f, .5f), new Vector2(.5f, .5f), new Color(color.r, color.g, color.b, .48f));
            var ring = UICircle("SkillBufferConsumedRing", button, Vector2.zero, new Vector2(124, 124), new Vector2(.5f, .5f), new Vector2(.5f, .5f), new Color(.64f, 1f, .96f, .075f));
            DestroyRuntimeObject(tick ? tick.gameObject : null, .12f);
            DestroyRuntimeObject(ring ? ring.gameObject : null, .16f);
            if (player && fxRoot)
                SpawnTimedRect("SkillBufferReleaseFootSnap_NoTexturePlate", (Vector2)player.transform.position + new Vector2(facing * .22f, -.50f), new Vector2(.54f, .016f), new Color(color.r, color.g, color.b, .11f), 6, .070f);
        }

        private void SpawnSkillBufferIntentCue(SkillKind skill)
        {
            if (skillBufferIntentCueCooldown > 0f) return;
            skillBufferIntentCueCooldown = .18f;
            RectTransform button = SkillButtonFor(skill);
            Color color = SkillButtonSignalColor(skill);
            if (button)
            {
                var tick = UIBox("SkillChainQueuedTick", button, new Vector2(0, 88), new Vector2(82, 7), new Vector2(.5f, .5f), new Vector2(.5f, .5f), new Color(color.r, color.g, color.b, .38f));
                var tickImage = tick ? tick.GetComponent<Image>() : null;
                if (tickImage) tickImage.raycastTarget = false;
                DestroyRuntimeObject(tick ? tick.gameObject : null, .12f);

                var ring = UICircle("SkillChainQueuedRing", button, Vector2.zero, new Vector2(142, 142), new Vector2(.5f, .5f), new Vector2(.5f, .5f), new Color(.64f, 1f, .96f, .060f));
                var ringImage = ring ? ring.GetComponent<Image>() : null;
                if (ringImage) ringImage.raycastTarget = false;
                DestroyRuntimeObject(ring ? ring.gameObject : null, .16f);
            }
            if (player && fxRoot)
                SpawnTimedRect("SkillChainQueuedFootLine_NoTexturePlate", (Vector2)player.transform.position + new Vector2(facing * .18f, -.52f), new Vector2(.46f, .014f), new Color(color.r, color.g, color.b, .085f), 5, .065f);
        }

        private void RequestDodge()
        {
            if (controlEditMode) return;
            if (inputLocked) return;
            dodgeBufferTimer = DodgeInputBufferDuration;
            TryConsumeDodgeBuffer();
        }

        private void TryConsumeDodgeBuffer()
        {
            if (dodgeBufferTimer <= 0f || inputLocked || dodgeCooldown > 0f) return;
            bool buffered = dodgeBufferTimer < DodgeInputBufferDuration - .035f;
            Dodge();
            if (buffered) SpawnDodgeBufferConsumedCue();
            dodgeBufferTimer = 0f;
        }

        private void Dodge()
        {
            if (controlEditMode) return;
            if (inputLocked || dodgeCooldown > 0) return;
            float baseCooldown = Mathf.Max(.42f, .72f - dashRuneLevel * .06f);
            dodgeCooldown = assistMode ? Mathf.Max(.34f, baseCooldown * AssistDodgeCooldownScale) : baseCooldown;
            invulnTimer = Mathf.Max(invulnTimer, .28f + dashRuneLevel * .025f + (assistMode ? AssistInvulnBonus : 0f));
            perfectDodgeWindow = Mathf.Max(perfectDodgeWindow, .24f + dashRuneLevel * .018f + (assistMode ? AssistPerfectDodgeWindowBonus : 0f));
            perfectDodgeReady = true;
            heroActionLockTimer = Mathf.Max(heroActionLockTimer, .18f);
            SetHeroFrame(HeroDodgeFrame);
            TriggerHeroPosePunch(new Vector2(1.16f, .90f), .16f);
            ShowHeroActionBeat("闪避", new[] { HeroDodgeFrame }, 6.25f, .48f, "无敌窗 + 完美闪避窗同步", C("#79F6FF"));
            SpawnTimedRect("HeroDodgeCleanStreak_NoEchoBody_NoTexturePlate", player.transform.position + new Vector3(-facing * .42f, -.18f, 0), new Vector2(.70f, .018f), new Color(.54f, .96f, 1f, .095f), 8, .070f);
            float distance = 1.65f + dashRuneLevel * .18f;
            var pos = player.transform.position;
            pos.x = ClampIntentAwarePlayerX(pos.x, pos.x + facing * distance, facing);
            player.transform.position = pos;
            SpawnFootDust("DodgeDust", 1.25f, .24f);
            SpawnTimedRect("DodgeGroundSkid_NoTexturePlate", player.transform.position + Vector3.down * .50f, new Vector2(.70f, .014f), new Color(.52f, .96f, 1f, .065f), 4, .075f);
            if (dashRuneLevel > 0)
                SpawnTimedRect("DodgeRuneTraceCleanLine_NoTexturePlate", player.transform.position - Vector3.right * facing * .65f + Vector3.down * .34f, new Vector2(.82f, .014f), new Color(.52f, .96f, 1f, .080f), 4, .085f);
        }

        private void BasicAttack()
        {
            if (attackCooldown > 0 || inputLocked) return;
            AdvanceTutorial(1);
            AutoFaceNearestEnemy(4.8f + swordRuneLevel * .35f, "锁定");
            attackBufferTimer = 0;
            if (comboTimer <= 0) combo = 0;
            combo = (combo % 3) + 1;
            comboTimer = AttackComboWindow;
            attackCooldown = combo == 3 ? .5f : .34f;
            if (combo == 1) PlayHeroFrames(HeroAttack1Frames, LightAttackAnimFps, .24f);
            else if (combo == 2) PlayHeroFrames(HeroAttack2Frames, LightAttackAnimFps, .24f);
            else PlayHeroFrames(HeroAttack3Frames, HeavyAttackAnimFps, .34f);
            ShowHeroActionBeat(combo == 3 ? "三连破势" : combo == 2 ? "二连起手" : "一斩起手", combo == 3 ? HeroAttack3Frames : combo == 2 ? HeroAttack2Frames : HeroAttack1Frames, combo == 3 ? HeavyAttackAnimFps : LightAttackAnimFps, combo == 3 ? .72f : .54f, combo == 3 ? "约 0.12 秒命中帧" : "约 0.075 秒命中帧", combo == 3 ? C("#9FF8FF") : C("#BDEAFF"));
            TriggerHeroPosePunch(combo == 3 ? new Vector2(1.18f, .90f) : new Vector2(1.08f, .96f), combo == 3 ? .18f : .11f);
            PlaySfx(combo == 3 ? sfxHeavyHit : sfxSlash, combo == 3 ? .72f : .85f);
            ApplyAttackLunge(combo);
            SpawnFootDust(combo == 3 ? "HeavyAttackDust" : "AttackDust", combo == 3 ? .76f : .48f, .090f);
            SpawnHeroAttackCleanPoseCue(combo);
            float range = combo == 3 ? 2.25f : 1.75f;
            range += swordRuneLevel * .18f;
            float damage = (combo == 3 ? 54 : 32) * attackMultiplier * (1f + swordRuneLevel * .04f);
            float hitDelay = combo == 3 ? .12f : .075f;
            StartCoroutine(ResolveMeleeAttack(range, damage, combo, hitDelay));
        }

        private void ApplyAttackLunge(int comboStep)
        {
            if (!player) return;
            if (!grounded)
            {
                ApplyAirAttackStabilizer(comboStep);
                return;
            }
            float distance = comboStep == 3 ? .20f : .11f;
            var pos = player.transform.position;
            pos.x = ClampIntentAwarePlayerX(pos.x, pos.x + facing * distance, facing);
            player.transform.position = pos;
        }

        private void ApplyAirAttackStabilizer(int comboStep)
        {
            if (!player || grounded) return;
            float drift = comboStep == 3 ? AirAttackHeavyDrift : AirAttackLightDrift;
            var pos = player.transform.position;
            pos.x = ClampIntentAwarePlayerX(pos.x, pos.x + facing * drift, facing);
            player.transform.position = pos;
            if (verticalVelocity < AirAttackFallBrakeVelocity)
                verticalVelocity = Mathf.Lerp(verticalVelocity, AirAttackFallBrakeVelocity, comboStep == 3 ? .72f : .58f);
            SpawnAirAttackStabilizeCue(comboStep);
        }

        private void SpawnAirAttackStabilizeCue(int comboStep)
        {
            if (!player || !fxRoot) return;
            float alphaScale = effectsIntensity > .75f ? 1f : .66f;
            Color color = comboStep == 3 ? C("#B6F7FF") : C("#BDEAFF");
            var line = SpawnTimedRect("AirAttackStabilizeLine_NoTexturePlate", (Vector2)player.transform.position + new Vector2(facing * .42f, -.36f), comboStep == 3 ? new Vector2(.44f, .012f) : new Vector2(.28f, .010f), new Color(color.r, color.g, color.b, (comboStep == 3 ? .040f : .026f) * alphaScale), 8, .045f);
            if (line) line.transform.localScale = new Vector3(Mathf.Abs(line.transform.localScale.x) * facing, line.transform.localScale.y, 1f);
            SpawnTimedRect("AirAttackFallBrakeTick_NoTexturePlate", (Vector2)player.transform.position + new Vector2(-facing * .18f, -.50f), new Vector2(.08f, .008f), new Color(.94f, 1f, 1f, .030f * alphaScale), 8, .040f);
        }

        private void SpawnFootDust(string name, float width, float life)
        {
            if (!player || !grounded) return;
            bool motionDust = name.StartsWith("RunStep", StringComparison.Ordinal)
                || name.StartsWith("Land", StringComparison.Ordinal)
                || name.StartsWith("Jump", StringComparison.Ordinal)
                || name.StartsWith("Dodge", StringComparison.Ordinal);
            bool attackDust = name.StartsWith("Attack", StringComparison.Ordinal) || name.StartsWith("HeavyAttack", StringComparison.Ordinal);
            float cleanWidth = motionDust ? Mathf.Min(width, name.StartsWith("Dodge", StringComparison.Ordinal) ? .34f : name.StartsWith("Land", StringComparison.Ordinal) ? .30f : .22f) : Mathf.Min(width, attackDust ? .32f : .54f);
            float cleanHeight = motionDust ? .006f : attackDust ? .006f : .014f;
            float cleanAlpha = motionDust ? .008f : attackDust ? .010f : .028f;
            float tickAlpha = motionDust ? .014f : attackDust ? .016f : .040f;
            var dust = SpawnTimedSprite(name + "_NoTexturePlateFootLine_CombatVfx0", CombatVfxSprite(0), player.transform.position + new Vector3(-facing * .16f, -.58f, 0), new Vector2(cleanWidth, cleanHeight), new Color(.76f, .96f, 1f, cleanAlpha), 3, Mathf.Min(life, motionDust ? .065f : attackDust ? .040f : .11f));
            if (dust) dust.transform.localScale = new Vector3(Mathf.Abs(dust.transform.localScale.x) * -facing, dust.transform.localScale.y, 1);
            SpawnTimedSprite(name + "_FootTick_NoTexturePlate_CombatVfx0", CombatVfxSprite(0), player.transform.position + new Vector3(facing * .10f, -.52f, 0), new Vector2(motionDust ? .042f : attackDust ? .050f : .10f, motionDust ? .006f : attackDust ? .006f : .012f), new Color(.94f, 1f, 1f, tickAlpha), 4, Mathf.Min(life, motionDust ? .034f : attackDust ? .030f : .060f));
        }

