        private bool MeleeHit(float range, float damage, int attackFacing, int comboStep)
        {
            bool hit = false;
            var origin = player.transform.position;
            foreach (var e in enemies.ToArray())
            {
                if (e.Dead) continue;
                float dx = (e.Root.transform.position.x - origin.x) * attackFacing;
                float dy = Mathf.Abs(e.Root.transform.position.y - origin.y);
                if (dx > .1f && dx < range && dy < 1.7f)
                {
                    hit = true;
                    DamageEnemy(e, damage, new Vector2(attackFacing, .18f), comboStep == 3 ? HitTier.Heavy : HitTier.Light);
                    if (thunderRuneLevel > 0 && rng.NextDouble() < .18f + thunderRuneLevel * .08f)
                        ChainLightning(e);
                }
            }
            return hit;
        }

        private bool MeleeHitRuneVessels(float range, float damage, int attackFacing, int comboStep)
        {
            bool hit = false;
            var origin = player.transform.position;
            foreach (var vessel in runeVessels.ToArray())
            {
                if (vessel.Broken || !vessel.Root) continue;
                float dx = (vessel.Root.transform.position.x - origin.x) * attackFacing;
                float dy = Mathf.Abs(vessel.Root.transform.position.y - origin.y);
                if (dx <= .05f || dx >= range + .3f || dy >= 1.8f) continue;
                hit = true;
                DamageRuneVessel(vessel, damage, new Vector2(attackFacing, .12f), comboStep == 3 ? HitTier.Heavy : HitTier.Light);
            }
            return hit;
        }

        private IEnumerator ResolveMeleeAttack(float range, float damage, int comboAtStart, float delay)
        {
            int attackFacing = facing;
            yield return new WaitForSeconds(delay);
            if (!player || inputLocked) yield break;
            bool enemyHit = MeleeHit(range, damage, attackFacing, comboAtStart);
            bool vesselHit = MeleeHitRuneVessels(range, damage, attackFacing, comboAtStart);
            if (enemyHit || vesselHit)
            {
                ApplyAttackHitFrameImpulse(comboAtStart, attackFacing);
                ShowHeroActionBeat(comboAtStart == 3 ? "破势命中帧" : "轻击命中帧", comboAtStart == 3 ? HeroAttack3Frames : comboAtStart == 2 ? HeroAttack2Frames : HeroAttack1Frames, comboAtStart == 3 ? HeavyAttackAnimFps : LightAttackAnimFps, comboAtStart == 3 ? .58f : .44f, comboAtStart == 3 ? "重定格 + 强回弹" : "短定格 + 按钮回弹", comboAtStart == 3 ? C("#B6F7FF") : C("#FFFFFF"));
                SpawnMeleeImpactBeat(range, attackFacing, comboAtStart);
                if (comboAtStart == 3)
                    SpawnComboFinisherBreakCue(range, attackFacing, enemyHit, vesselHit);
            }
            StartCoroutine(FlashSlash(range, attackFacing, comboAtStart));
            if (comboAtStart == 3 && swordRuneLevel >= 2)
                SpawnProjectile((Vector2)player.transform.position + new Vector2(attackFacing * 1.1f, .28f), new Vector2(attackFacing * (7.2f + swordRuneLevel), 0), 28f * attackMultiplier, true, C("#66D9FF"), 1, 4, .45f);
        }

        private void ApplyAttackHitFrameImpulse(int comboStep, int attackFacing)
        {
            if (!player || !grounded) return;
            float distance = comboStep == 3 ? HeavyHitFrameLunge : LightHitFrameLunge;
            var pos = player.transform.position;
            pos.x = ClampIntentAwarePlayerX(pos.x, pos.x + attackFacing * distance, attackFacing);
            player.transform.position = pos;
            TriggerHeroPosePunch(comboStep == 3 ? new Vector2(1.14f, .91f) : new Vector2(1.07f, .96f), comboStep == 3 ? .12f : .075f);
        }

        private void DamageRuneVessel(RuneVessel vessel, float damage, Vector2 hitDir, HitTier tier, SkillKind? sourceSkill = null)
        {
            if (vessel.Broken || !vessel.Root) return;
            vessel.Hp -= damage;
            ShowHitConfirm(tier, false);
            PulseHitConfirmButton(tier, false, sourceSkill);
            TriggerHitFrameBeat(tier, false, vessel.Root.transform.position + Vector3.up * .35f, sourceSkill);
            float tierScale = tier == HitTier.Heavy ? 1.18f : tier == HitTier.Skill ? 1.05f : .92f;
            Color color = tier == HitTier.Skill ? C("#7EDCFF") : tier == HitTier.Heavy ? C("#9FF8FF") : C("#63E6FF");
            Vector3 pos = vessel.Root.transform.position + Vector3.up * .25f;
            SpawnTimedSprite("RuneJarSpark_NoYellowPlate", CombatVfxSprite(0), pos, new Vector2(.34f, .026f) * tierScale, new Color(color.r, color.g, color.b, .34f), 8, .070f);
            var slash = SpawnTimedSprite("RuneJarHitSlash_NoYellowPlate", CombatVfxSprite(0), pos + Vector3.right * Mathf.Sign(hitDir.x == 0 ? facing : hitDir.x) * .10f, new Vector2(.42f, .034f) * tierScale, new Color(1f, 1f, 1f, .36f), 9, .060f);
            if (slash) slash.transform.localScale = new Vector3(Mathf.Abs(slash.transform.localScale.x) * Mathf.Sign(hitDir.x == 0 ? facing : hitDir.x), slash.transform.localScale.y, 1);
            SpawnTimedSprite("RuneJarHitTickA_NoYellowPlate", CombatVfxSprite(0), pos + new Vector3(-.11f, .16f, 0), new Vector2(.11f, .014f) * tierScale, new Color(color.r, color.g, color.b, .28f), 9, .060f);
            SpawnTimedSprite("RuneJarHitTickB_NoYellowPlate", CombatVfxSprite(0), pos + new Vector3(.12f, .14f, 0), new Vector2(.12f, .014f) * tierScale, new Color(1f, 1f, 1f, .24f), 9, .060f);
            if (vessel.Hp <= 0) BreakRuneVessel(vessel);
        }

        private void BreakRuneVessel(RuneVessel vessel)
        {
            vessel.Broken = true;
            var pos = vessel.Root.transform.position;
            SpawnTimedSprite("RuneChestBreakSpark_NoYellowPlate", CombatVfxSprite(0), pos + Vector3.up * .12f, new Vector2(.24f, .020f), new Color(.68f, .96f, 1f, .24f), 10, .060f);
            SpawnTimedSprite("RuneChestBreakShardA_NoYellowPlate", CombatVfxSprite(0), pos + new Vector3(-.11f, .15f, 0), new Vector2(.10f, .014f), new Color(.84f, .98f, 1f, .22f), 10, .060f);
            SpawnTimedSprite("RuneChestBreakShardB_NoYellowPlate", CombatVfxSprite(0), pos + new Vector3(.12f, .12f, 0), new Vector2(.11f, .014f), new Color(.72f, .96f, 1f, .22f), 10, .064f);
            SpawnTimedSprite("RuneChestBreakTinyLockPop_NoYellowPlate", CombatVfxSprite(0), pos + Vector3.up * .18f, new Vector2(.09f, .012f), new Color(.72f, .96f, 1f, .14f), 8, .050f);
            SpawnPickupBurst(PickupKind.Coin, 18 + rng.Next(18), pos, 3);
            if (rng.NextDouble() < .42f) SpawnPickup(PickupKind.Fate, 12f, pos + Vector3.up * .25f, new Vector2(UnityEngine.Random.Range(-.9f, .9f), 1.6f));
            Destroy(vessel.Root);
            runeVessels.Remove(vessel);
            bool runeSpawnReady = RuneSpawnCooldownReady();
            bool roomClear = ActiveEnemiesInCurrentArea() <= 0;
            bool requiredObjectiveChest = vessel.ObjectiveSegment >= 0;
            float directShrineChance = Mathf.Clamp01(vessel.ShrineChance * RuneVesselImmediateShrineChanceScale);
            bool allowShrineAfterClear = roomClear && requiredObjectiveChest && runeSpawnReady && directShrineChance > 0f;
            if (!rollingRune && !shrineAvailable && allowShrineAfterClear && rng.NextDouble() < directShrineChance)
            {
                SpawnRuneShrine(false, Mathf.Clamp(pos.x + .9f, LeftBound + 2f, CurrentSegmentRight() - 1.2f));
                noticeText.text = "小宝箱开出 SLOT：靠近后点启封";
            }
            else
            {
                fateEnergy = Mathf.Min(99f, fateEnergy + (roomClear ? 12f : 7f));
                noticeText.text = roomClear ? "小宝箱转化为命运能量：继续推进" : "小宝箱已开：不打断战斗，先清敌";
            }
            HapticPulse(HapticTier.Medium);
        }

        private IEnumerator OpenRuneChestFromBrokenVessel(Vector3 worldPos)
        {
            yield return new WaitForSeconds(.10f);
            if (!rollingRune && shrineAvailable && slotShrine && Vector2.Distance(worldPos, slotShrine.transform.position) <= 2.8f)
                noticeText.text = RuneDirectOpenCooldownReady() ? "SLOT 宝箱已出现：靠近后点启封" : "命运能量已收纳：继续清敌推进";
        }

        private void PulseHitConfirmButton(HitTier tier, bool boss, SkillKind? sourceSkill)
        {
            if (tier == HitTier.Skill && sourceSkill.HasValue)
            {
                PulseControlButton(SkillButtonFor(sourceSkill.Value), boss ? .30f : .24f);
                return;
            }
