        private void PlayHeroFrames(int[] frames, float fps, float lockDuration)
        {
            if (frames == null || frames.Length == 0 || fps <= 0) return;
            heroAnimToken++;
            heroActionLockTimer = Mathf.Max(heroActionLockTimer, lockDuration);
            StartCoroutine(PlayHeroFramesRoutine(frames, fps, heroAnimToken));
        }

        private IEnumerator PlayHeroFramesRoutine(int[] frames, float fps, int token)
        {
            var wait = new WaitForSeconds(1f / fps);
            foreach (var frame in frames)
            {
                if (token != heroAnimToken) yield break;
                SetHeroFrame(frame);
                yield return wait;
            }
            if (token == heroAnimToken) RestoreHeroPoseAfterAction();
        }

        private void RestoreHeroPoseAfterAction()
        {
            if (!playerSprite) return;
            RestoreHeroRenderer();
            if (!grounded)
            {
                SetHeroFrame(verticalVelocity >= 0 ? HeroJumpFrame : HeroFallFrame);
                return;
            }
            bool movingHorizontally = Mathf.Abs(Input.GetAxisRaw("Horizontal")) > .05f || (touchMoveActive && Mathf.Abs(touchMoveInput.x) > .05f);
            SetHeroFrame(movingHorizontally ? HeroRunFrames[0] : HeroIdleFrames[0]);
        }

        private void SetHeroFrame(int index)
        {
            if (!playerSprite) return;
            RestoreHeroRenderer();
            if (heroSprites == null || index < 0 || index >= heroSprites.Length)
            {
                UseEmergencyHeroSprite();
                return;
            }
            if (!HeroFrameHasVisibleBody(index))
            {
                index = Mathf.Clamp(lastVisibleHeroFrame, 0, heroSprites.Length - 1);
                if (!HeroFrameHasVisibleBody(index)) index = FirstVisibleHeroFrame();
            }
            if (index < 0 || !HeroFrameHasVisibleBody(index))
            {
                UseEmergencyHeroSprite();
                return;
            }
            playerSprite.sprite = heroSprites[index];
            playerSprite.color = Color.white;
            ApplyHeroSpriteGroundingOffset();
            lastVisibleHeroFrame = index;
            SyncHeroContrastSilhouette();
        }

        private void UseEmergencyHeroSprite()
        {
            if (!playerSprite) return;
            playerSprite.sprite = FirstVisibleHeroSprite();
            playerSprite.color = C("#DDF7FF");
            playerSprite.enabled = true;
            playerSprite.sortingOrder = 34;
            ApplyHeroSpriteGroundingOffset();
            if (player) player.transform.localScale = new Vector3(HeroBaseVisualScale * .82f, HeroBaseVisualScale * 1.20f, 1f);
            SyncHeroContrastSilhouette();
        }

        private void RestoreHeroRenderer()
        {
            if (!playerSprite) return;
            playerSprite.enabled = true;
            if (playerSprite.color.a < .35f) playerSprite.color = Color.white;
            playerSprite.sortingOrder = 34;
            ApplyHeroSpriteGroundingOffset();
            if (player && heroPosePunchTimer <= 0f) player.transform.localScale = Vector3.one * HeroBaseVisualScale;
            if (companionSprite) companionSprite.sortingOrder = 1;
            SyncHeroReadableBody();
            SyncHeroContrastSilhouette();
            if (playerReadabilityAura)
            {
                var auraRenderer = playerReadabilityAura.GetComponent<SpriteRenderer>();
                if (auraRenderer)
                {
                    auraRenderer.enabled = false;
                    auraRenderer.sortingOrder = 4;
                    auraRenderer.color = Color.clear;
                }
            }
        }

        private void ApplyHeroSpriteGroundingOffset()
        {
            if (!playerSprite) return;
            playerSprite.transform.localPosition = new Vector3(0f, HeroSpriteGroundingOffsetY, 0f);
        }

        private void SyncHeroContrastSilhouette()
        {
            if (!playerContrastShadow || !playerSprite) return;
            playerContrastShadow.sprite = playerSprite.sprite;
            playerContrastShadow.flipX = playerSprite.flipX;
            playerContrastShadow.enabled = false;
            playerContrastShadow.sortingOrder = Mathf.Max(0, playerSprite.sortingOrder - 1);
            playerContrastShadow.transform.localPosition = new Vector3(playerSprite.flipX ? -.006f : .006f, -.014f, .04f);
            playerContrastShadow.color = Color.clear;
        }

        private void TriggerHeroPosePunch(Vector2 peakScale, float duration)
        {
            if (!player || duration <= 0f) return;
            heroPosePunchPeak = peakScale;
            heroPosePunchDuration = duration;
            heroPosePunchTimer = duration;
        }

        private void UpdateHeroPosePunch()
        {
            if (!player || heroPosePunchTimer <= 0f || heroPosePunchDuration <= 0f) return;
            heroPosePunchTimer -= Time.deltaTime;
            float progress = 1f - Mathf.Clamp01(heroPosePunchTimer / heroPosePunchDuration);
            float pulse = Mathf.Sin(progress * Mathf.PI);
            Vector2 scale = Vector2.Lerp(Vector2.one, heroPosePunchPeak, pulse);
            player.transform.localScale = new Vector3(HeroBaseVisualScale * scale.x, HeroBaseVisualScale * scale.y, 1f);
        }

        private void EnsureHeroVisualState()
        {
            if (!playerSprite) return;
            bool invalidSprite = !playerSprite.sprite;
            bool hiddenRenderer = !playerSprite.enabled || playerSprite.color.a < .35f || playerSprite.sortingOrder < 30;
            bool invalidScale = player && player.transform.localScale.sqrMagnitude < .5f;
            if (!invalidSprite && !hiddenRenderer && !invalidScale) return;

            RestoreHeroRenderer();
            if (!invalidSprite) return;

            int frame = Mathf.Clamp(lastVisibleHeroFrame, 0, heroSprites != null ? heroSprites.Length - 1 : 0);
            if (!HeroFrameHasVisibleBody(frame)) frame = FirstVisibleHeroFrame();
            if (frame >= 0 && heroSprites != null && frame < heroSprites.Length)
            {
                playerSprite.sprite = heroSprites[frame];
                lastVisibleHeroFrame = frame;
                playerSprite.color = Color.white;
                return;
            }
            UseEmergencyHeroSprite();
        }

        private int FirstVisibleHeroFrame()
        {
            if (heroSprites == null) return -1;
            for (int i = 0; i < heroSprites.Length; i++)
            {
                if (HeroFrameHasVisibleBody(i)) return i;
            }
            return heroSprites.Length > 0 && heroSprites[0] ? 0 : -1;
        }

        private Sprite FirstVisibleHeroSprite()
        {
            int frame = FirstVisibleHeroFrame();
            if (frame >= 0 && heroSprites != null && frame < heroSprites.Length && heroSprites[frame])
            {
                lastVisibleHeroFrame = frame;
                return heroSprites[frame];
            }
            return SpriteCache.Circle ? SpriteCache.Circle : SpriteCache.White;
        }

        private bool HeroFrameHasVisibleBody(int index)
        {
            if (heroFrameVisibility.TryGetValue(index, out bool visible)) return visible;
            if (heroSprites == null || index < 0 || index >= heroSprites.Length || !heroSprites[index])
            {
                heroFrameVisibility[index] = false;
                return false;
            }

            var sprite = heroSprites[index];
            var texture = sprite.texture;
            if (!texture)
            {
                heroFrameVisibility[index] = false;
                return false;
            }

            int solidPixels = 0;
            var rect = sprite.rect;
            int minX = Mathf.Clamp(Mathf.FloorToInt(rect.xMin), 0, texture.width - 1);
            int maxX = Mathf.Clamp(Mathf.CeilToInt(rect.xMax), 0, texture.width);
            int minY = Mathf.Clamp(Mathf.FloorToInt(rect.yMin), 0, texture.height - 1);
            int maxY = Mathf.Clamp(Mathf.CeilToInt(rect.yMax), 0, texture.height);
            Color32[] pixels;
            try
            {
                pixels = texture.GetPixels32();
            }
            catch (UnityException)
            {
                heroFrameVisibility[index] = true;
                return true;
            }
            for (int y = minY; y < maxY; y += 2)
            {
                int row = y * texture.width;
                for (int x = minX; x < maxX; x += 2)
                {
                    if (pixels[row + x].a > 24 && ++solidPixels >= 80)
                    {
                        heroFrameVisibility[index] = true;
                        return true;
                    }
                }
            }

            heroFrameVisibility[index] = false;
            return false;
        }

        private static bool SpriteHasGeneratedBackdropPlate(Sprite sprite)
        {
            if (!sprite || !sprite.texture) return true;
            Texture2D texture = sprite.texture;
            Color32[] pixels;
            try
            {
                pixels = texture.GetPixels32();
            }
            catch (UnityException)
            {
                return false;
            }

            Rect rect = sprite.rect;
            int minX = Mathf.Clamp(Mathf.FloorToInt(rect.xMin), 0, texture.width - 1);
            int maxX = Mathf.Clamp(Mathf.CeilToInt(rect.xMax), 0, texture.width);
            int minY = Mathf.Clamp(Mathf.FloorToInt(rect.yMin), 0, texture.height - 1);
            int maxY = Mathf.Clamp(Mathf.CeilToInt(rect.yMax), 0, texture.height);
            int total = 0;
            int warm = 0;
            int edgeTotal = 0;
            int edgeWarm = 0;

            for (int y = minY; y < maxY; y += 2)
            {
                int row = y * texture.width;
                bool edgeY = y <= minY + 4 || y >= maxY - 5;
                for (int x = minX; x < maxX; x += 2)
                {
                    var p = pixels[row + x];
                    if (p.a <= 32) continue;
                    bool edge = edgeY || x <= minX + 4 || x >= maxX - 5;
                    bool plate = LooksLikeGeneratedBackdropPlate(p) || LooksLikePaleGeneratedBackdrop(p);
                    total++;
                    if (edge) edgeTotal++;
                    if (!plate) continue;
                    warm++;
                    if (edge) edgeWarm++;
                }
            }

            if (total <= 0) return true;
            float warmRatio = warm / (float)total;
            float edgeWarmRatio = edgeTotal > 0 ? edgeWarm / (float)edgeTotal : 0f;
            return warmRatio > .34f || (edgeWarm >= 20 && edgeWarmRatio > .42f);
        }

        private bool CastSkill(SkillKind skill, bool buffered = false)
        {
            if (controlEditMode || inputLocked) return false;
            if (SkillCooldownRemaining(skill) > 0f) return false;
            if (SkillChainWindowLocked()) return false;
            float cost = SkillCost(skill);
            if (mp < cost) { if (noticeText) noticeText.text = "魔力不足"; return false; }
            HideSkillAimPreview();
            AutoFaceNearestEnemy(skill == SkillKind.ThunderStrike || skill == SkillKind.FrostNova ? 7.5f : 10.5f, "技能目标");
            mp -= cost;
            skillCooldowns[skill] = SkillMaxCooldown(skill);
            skillBufferTimers[skill] = 0f;
            if (buffered) SpawnSkillBufferConsumedCue(skill);
            int releaseFrame = skill == SkillKind.SlashWave ? 28 : skill == SkillKind.Fireball ? 29 : skill == SkillKind.FrostNova ? 30 : 31;
            PlayHeroFrames(SkillFrames(releaseFrame), SkillAnimFps, .28f);
            ShowHeroActionBeat(SkillLabel(skill) + "起手", SkillFrames(releaseFrame), SkillAnimFps, .66f, "2 帧蓄势后约 0.125 秒释放", SkillButtonSignalColor(skill));
            TriggerHeroPosePunch(SkillPosePunch(skill), .18f);
            SpawnHeroSkillCutCue(skill);
            PulseControlButton(SkillButtonFor(skill), .22f);
            PlaySfx(sfxSkillCast, skill == SkillKind.ThunderStrike ? .95f : .72f);
            SpawnSkillCastCue(skill);
            StartCoroutine(ResolveSkillCast(skill, facing, .125f));
            return true;
        }

        private void SpawnHeroSkillCutCue(SkillKind skill)
        {
            if (!player || !fxRoot) return;
            Color color = SkillButtonReadyColor(skill);
            Vector2 pos = player.transform.position;
