            SpawnTimedSprite("HeroSkillSharpCastCore_NoEchoBody_NoYellowPlate", CombatVfxSprite(0), pos + new Vector2(facing * .22f, .34f), new Vector2(.20f, .010f), new Color(color.r, color.g, color.b, .10f * HeroActionVfxAlphaScale), 12, .022f);
            SpawnTimedSprite("HeroSkillPoseReadableWhiteEdge_NoTexturePlate", CombatVfxSprite(0), pos + new Vector2(facing * .34f, .54f), new Vector2(.24f, .010f), new Color(.96f, 1f, 1f, .18f * HeroActionVfxAlphaScale), 15, .020f);
            SpawnTimedSprite("HeroSkillClearHandTick_NoTexturePlate", CombatVfxSprite(0), pos + new Vector2(facing * .54f, .42f), new Vector2(.09f, .009f), new Color(color.r, color.g, color.b, .18f * HeroActionVfxAlphaScale), 15, .022f);
            SpawnTimedSprite("HeroSkillHandSparkPin_ThinNoBlur", CombatVfxSprite(0), pos + new Vector2(facing * .62f, .49f), new Vector2(.06f, .012f), new Color(.96f, 1f, 1f, .18f * HeroActionVfxAlphaScale), 16, .020f);
            SpawnTimedSprite("HeroSkillFootAnchorAo_DisabledNoGroundBlob", CombatVfxSprite(0), pos + new Vector2(0, -.62f), new Vector2(.42f, .020f), Color.clear, 2, .060f);
            if (skill == SkillKind.FrostNova || skill == SkillKind.ThunderStrike)
            {
                SpawnTimedSprite("HeroSkillSharpGroundCue_NoYellowPlate", CombatVfxSprite(0), pos + new Vector2(0, -.43f), new Vector2(skill == SkillKind.ThunderStrike ? .28f : .34f, .005f), new Color(color.r, color.g, color.b, alpha * .050f), 9, .022f);
                SpawnTimedSprite("HeroSkillSharpCoreCue_NoYellowPlate", CombatVfxSprite(0), pos + new Vector2(0, .38f), new Vector2(.26f, .012f), new Color(color.r, color.g, color.b, .16f * HeroActionVfxAlphaScale), 10, .030f);
                SpawnTimedSprite("HeroSkillSharpReleaseRing_NoYellowPlate", CombatVfxSprite(0), pos + new Vector2(0, -.30f), new Vector2(skill == SkillKind.ThunderStrike ? .32f : .40f, .005f), new Color(color.r, color.g, color.b, .020f * HeroActionVfxAlphaScale), 8, .028f);
                return;
            }

            var cut = SpawnTimedSprite("HeroSkillSharpCutCue_NoYellowPlate", CombatVfxSprite(0), pos + new Vector2(facing * .54f, .46f), new Vector2(.42f, .010f), new Color(color.r, color.g, color.b, alpha * .24f), 10, .026f);
            if (cut) cut.transform.localScale = new Vector3(Mathf.Abs(cut.transform.localScale.x) * facing, cut.transform.localScale.y, 1f);
            var edge = SpawnTimedSprite("HeroSkillSharpDirectionEdge_NoYellowPlate", CombatVfxSprite(0), pos + new Vector2(facing * .74f, .18f), new Vector2(.40f, .008f), new Color(.90f, 1f, 1f, .12f * HeroActionVfxAlphaScale), 11, .024f);
            if (edge) edge.transform.localScale = new Vector3(Mathf.Abs(edge.transform.localScale.x) * facing, edge.transform.localScale.y, 1f);
            SpawnTimedSprite("HeroSkillSharpFootCue_NoYellowPlate", CombatVfxSprite(0), pos + new Vector2(-facing * .12f, -.44f), new Vector2(.12f, .004f), new Color(.86f, .98f, 1f, .010f), 8, .020f);
        }

        private Vector2 SkillPosePunch(SkillKind skill)
        {
            if (skill == SkillKind.FrostNova) return new Vector2(1.04f, 1.12f);
            if (skill == SkillKind.ThunderStrike) return new Vector2(.94f, 1.16f);
            return new Vector2(1.13f, .93f);
        }

        private RectTransform SkillButtonFor(SkillKind skill)
        {
            if (skill == SkillKind.SlashWave) return skill1ButtonUi;
            if (skill == SkillKind.Fireball) return skill2ButtonUi;
            if (skill == SkillKind.FrostNova) return skill3ButtonUi;
            if (skill == SkillKind.ThunderStrike) return skill4ButtonUi;
            return null;
        }

        private static int[] SkillFrames(int releaseFrame)
        {
            return new[] { HeroSkillChargeFrames[0], HeroSkillChargeFrames[1], releaseFrame };
        }

        private static string SkillLabel(SkillKind skill)
        {
            if (skill == SkillKind.SlashWave) return "剑气";
            if (skill == SkillKind.Fireball) return "炎弹";
            if (skill == SkillKind.FrostNova) return "冰环";
            return "雷击";
        }

        private static float SkillCost(SkillKind skill)
        {
            return skill == SkillKind.ThunderStrike ? 36f : 24f;
        }

        private static float SkillMaxCooldown(SkillKind skill)
        {
            return skill == SkillKind.ThunderStrike ? 5.5f : 3.5f;
        }

        private bool SkillCanPreview(SkillKind skill)
        {
            if (controlEditMode || inputLocked || !player) return false;
            if (skillCooldowns.TryGetValue(skill, out float cd) && cd > .03f) return false;
            return mp >= SkillCost(skill);
        }

        private void ShowSkillAimPreview(SkillKind skill)
        {
            HideSkillAimPreview();
            if (!SkillCanPreview(skill) || !fxRoot) return;
            skillAimPreviewSkill = skill;
            skillAimPreviewRoot = new GameObject("SkillAimPreview");
            skillAimPreviewRoot.transform.SetParent(fxRoot);
            skillAimPreviewRoot.transform.position = player.transform.position;
            Color color = SkillButtonReadyColor(skill);
            color.a = effectsIntensity > .75f ? .060f : .038f;
            if (skill == SkillKind.SlashWave || skill == SkillKind.Fireball)
            {
                float range = skill == SkillKind.Fireball ? 6.2f : 7.4f;
                var guide = SpriteObj("SkillAimPreviewGuideLine_NoPlate", skillAimPreviewRoot.transform, CombatVfxSprite(0), new Vector2(facing * range * .46f, .34f), new Vector2(range * .82f, .010f), color, 6);
                guide.transform.localScale = new Vector3(Mathf.Abs(guide.transform.localScale.x) * facing, guide.transform.localScale.y, 1f);
                var edge = SpriteObj("SkillAimPreviewEdgeLine", skillAimPreviewRoot.transform, CombatVfxSprite(0), new Vector2(facing * range * .88f, .34f), new Vector2(.08f, .010f), new Color(.94f, 1f, 1f, .10f), 7);
                edge.transform.localScale = new Vector3(Mathf.Abs(edge.transform.localScale.x) * facing, edge.transform.localScale.y, 1f);
                var midTick = SpriteObj("SkillAimPreviewMidTick_NoPlate", skillAimPreviewRoot.transform, CombatVfxSprite(0), new Vector2(facing * range * .55f, .34f), new Vector2(.052f, .008f), new Color(.94f, 1f, 1f, .060f), 7);
                midTick.transform.localScale = new Vector3(Mathf.Abs(midTick.transform.localScale.x) * facing, midTick.transform.localScale.y, 1f);
                SpriteObj("SkillAimPreviewFootAnchor", skillAimPreviewRoot.transform, CombatVfxSprite(0), new Vector2(0, -.48f), new Vector2(.20f, .006f), new Color(color.r, color.g, color.b, .030f), 5);
                return;
            }

            float radius = skill == SkillKind.FrostNova ? 2.4f + frostRuneLevel * .32f : 3.8f;
            var ring = SpriteObj("SkillAimPreviewThinAreaLine", skillAimPreviewRoot.transform, CombatVfxSprite(0), new Vector2(0f, skill == SkillKind.ThunderStrike ? .04f : -.10f), new Vector2(radius * 1.46f, .010f), color, 6);
            ring.transform.localPosition = new Vector3(0f, skill == SkillKind.ThunderStrike ? .04f : -.10f, 0f);
            SpriteObj("SkillAimPreviewLeftBoundary", skillAimPreviewRoot.transform, CombatVfxSprite(0), new Vector2(-radius, .10f), new Vector2(.060f, .010f), new Color(.94f, 1f, 1f, .090f), 7);
            SpriteObj("SkillAimPreviewRightBoundary", skillAimPreviewRoot.transform, CombatVfxSprite(0), new Vector2(radius, .10f), new Vector2(.060f, .010f), new Color(.94f, 1f, 1f, .090f), 7);
            SpriteObj("SkillAimPreviewFootAnchor", skillAimPreviewRoot.transform, CombatVfxSprite(0), new Vector2(0, -.48f), new Vector2(.20f, .006f), new Color(color.r, color.g, color.b, .030f), 5);
        }

        private void UpdateSkillAimPreview()
        {
            if (!skillAimPreviewRoot || !skillAimPreviewSkill.HasValue || !player) return;
            SkillKind skill = skillAimPreviewSkill.Value;
            if (!SkillCanPreview(skill))
            {
                HideSkillAimPreview();
                return;
            }
            skillAimPreviewRoot.transform.position = player.transform.position;
            if (skill != SkillKind.SlashWave && skill != SkillKind.Fireball) return;
            float range = skill == SkillKind.Fireball ? 6.2f : 7.4f;
            var guide = skillAimPreviewRoot.transform.Find("SkillAimPreviewGuideLine_NoPlate");
            if (guide)
            {
                guide.localPosition = new Vector3(facing * range * .46f, .34f, 0f);
                guide.localScale = new Vector3(Mathf.Abs(guide.localScale.x) * facing, guide.localScale.y, guide.localScale.z);
            }
            var edge = skillAimPreviewRoot.transform.Find("SkillAimPreviewEdgeLine");
            if (edge)
            {
                edge.localPosition = new Vector3(facing * range * .92f, .34f, 0f);
                edge.localScale = new Vector3(Mathf.Abs(edge.localScale.x) * facing, edge.localScale.y, edge.localScale.z);
            }
            var midTick = skillAimPreviewRoot.transform.Find("SkillAimPreviewMidTick_NoPlate");
            if (midTick)
            {
                midTick.localPosition = new Vector3(facing * range * .55f, .34f, 0f);
                midTick.localScale = new Vector3(Mathf.Abs(midTick.localScale.x) * facing, midTick.localScale.y, midTick.localScale.z);
            }
        }

        private void HideSkillAimPreview()
        {
            skillAimPreviewSkill = null;
            if (!skillAimPreviewRoot) return;
            Destroy(skillAimPreviewRoot);
            skillAimPreviewRoot = null;
        }

        private IEnumerator ResolveSkillCast(SkillKind skill, int castFacing, float delay)
        {
            yield return new WaitForSeconds(delay);
            if (!player) yield break;
            int releaseFrame = skill == SkillKind.SlashWave ? 28 : skill == SkillKind.Fireball ? 29 : skill == SkillKind.FrostNova ? 30 : 31;
            ShowHeroActionBeat(SkillLabel(skill) + "释放帧", new[] { releaseFrame }, SkillAnimFps, .52f, "释放帧生效 / 命中后回弹技能键", SkillButtonSignalColor(skill));
            SpawnSkillReleaseBeat(skill, castFacing);
            if (skill == SkillKind.SlashWave) SpawnProjectile((Vector2)player.transform.position + new Vector2(castFacing * .9f, .25f), new Vector2(castFacing * 8f, 0), 58 * attackMultiplier, true, C("#66D9FF"), 1, 4, .58f, "", skill);
            if (skill == SkillKind.Fireball) SpawnProjectile((Vector2)player.transform.position + new Vector2(castFacing * .9f, .4f), new Vector2(castFacing * 6f, 0), 72 * attackMultiplier, true, C("#E67E22"), 2, 3, .62f, "", skill);
            if (skill == SkillKind.FrostNova)
            {
                float radius = 2.4f + frostRuneLevel * .32f;
                SpawnTimedSprite("FrostNovaEdge_ThinNoBlur", CombatVfxSprite(0), player.transform.position + Vector3.down * .06f, new Vector2(radius * .92f, .016f), new Color(.88f, .99f, 1f, .22f), 13, .046f);
                SpawnTimedSprite("FrostNovaInnerLine_ThinNoBlur", CombatVfxSprite(0), player.transform.position + Vector3.up * .16f, new Vector2(radius * .56f, .010f), new Color(.56f, .92f, 1f, .18f), 12, .042f);
                SpawnTimedSprite("FrostNovaCrispCenterLine_ThinNoBlur", CombatVfxSprite(0), player.transform.position + Vector3.up * .08f, new Vector2(radius * .34f, .012f), new Color(.94f, 1f, 1f, .30f), 14, .044f);
                SpawnTimedSprite("FrostNovaCastPosePin_ThinNoBlur", CombatVfxSprite(0), player.transform.position + Vector3.down * .52f, new Vector2(.34f, .010f), new Color(.90f, 1f, 1f, .24f), 14, .046f);
                SpawnTimedSprite("FrostNovaCrispShardA_ThinNoBlur", CombatVfxSprite(0), player.transform.position + Vector3.up * .30f + Vector3.right * .34f, new Vector2(.30f, .014f), new Color(.90f, 1f, 1f, .42f), 14, .050f);
                SpawnTimedSprite("FrostNovaCrispShardB_ThinNoBlur", CombatVfxSprite(0), player.transform.position + Vector3.up * .30f + Vector3.left * .34f, new Vector2(.30f, .014f), new Color(.90f, 1f, 1f, .42f), 14, .050f);
                foreach (var e in enemies.ToArray())
                    if (Vector2.Distance(e.Root.transform.position, player.transform.position) < radius + .2f)
                    {
                        ApplyEnemyFreeze(e, e.Boss ? .45f : 1.15f + frostRuneLevel * .12f);
                        DamageEnemy(e, (44 + frostRuneLevel * 8) * attackMultiplier, ((Vector2)e.Root.transform.position - (Vector2)player.transform.position).normalized + Vector2.up * .15f, HitTier.Skill, skill);
                        SpawnSkillSpecificImpact(skill, e.Root.transform.position + Vector3.up * (e.Boss ? 1.0f : .55f), ((Vector2)e.Root.transform.position - (Vector2)player.transform.position).normalized, e.Boss);
                    }
            }
            if (skill == SkillKind.ThunderStrike)
            {
                int count = 3 + Mathf.Min(2, thunderRuneLevel);
                foreach (var e in enemies.OrderBy(e => Mathf.Abs(e.Root.transform.position.x - player.transform.position.x)).Take(count).ToArray())
                {
                    SpawnTimedSprite("ThunderCrispVerticalSpine", CombatVfxSprite(0), e.Root.transform.position + Vector3.up * .92f, new Vector2(.020f, 1.46f), new Color(.78f, .98f, 1f, .28f), 14, .050f);
                    SpawnTimedSprite("ThunderCrispSideBranchA", CombatVfxSprite(0), e.Root.transform.position + Vector3.up * 1.16f + Vector3.right * .12f, new Vector2(.24f, .012f), new Color(.55f, .94f, 1f, .22f), 13, .044f);
                    SpawnTimedSprite("ThunderCrispSideBranchB", CombatVfxSprite(0), e.Root.transform.position + Vector3.up * .70f + Vector3.left * .12f, new Vector2(.22f, .012f), new Color(.90f, .98f, 1f, .20f), 13, .044f);
                    SpawnTimedSprite("ThunderCrispContactLine", CombatVfxSprite(0), e.Root.transform.position + Vector3.down * .18f, new Vector2(.46f, .014f), new Color(.72f, .96f, 1f, .26f), 13, .050f);
                    DamageEnemy(e, (88 + thunderRuneLevel * 10) * attackMultiplier, Vector2.up, HitTier.Skill, skill);
                    SpawnSkillSpecificImpact(skill, e.Root.transform.position + Vector3.up * (e.Boss ? 1.0f : .58f), Vector2.up, e.Boss);
                }
            }
        }

        private void SpawnSkillReleaseBeat(SkillKind skill, int castFacing)
        {
            if (!player || !fxRoot) return;
            Color color = SkillButtonReadyColor(skill);
            Vector2 pos = player.transform.position;
            float power = skill == SkillKind.ThunderStrike ? 1.25f : skill == SkillKind.FrostNova ? 1.12f : 1f;
            SpawnHeroSkillReleaseFrameAnchor(skill, castFacing, color, power);
            SpawnTimedSprite("SkillReleaseCrispCore_ThinNoBlur", CombatVfxSprite(0), pos + new Vector2(castFacing * .28f, .10f), new Vector2(.30f, .010f) * power, new Color(color.r, color.g, color.b, .16f * HeroActionVfxAlphaScale), 12, .030f);
            var needle = SpawnTimedSprite("SkillReleaseNeedleLine_ThinNoBlur", CombatVfxSprite(0), pos + new Vector2(castFacing * .52f, .46f), new Vector2(.34f, .006f) * power, new Color(.96f, 1f, 1f, .14f * HeroActionVfxAlphaScale), 14, .026f);
            if (needle) needle.transform.localScale = new Vector3(Mathf.Abs(needle.transform.localScale.x) * castFacing, needle.transform.localScale.y, 1);
            var launchSpine = SpawnTimedSprite("SkillReleaseLaunchSpine_ThinNoBlur", CombatVfxSprite(0), pos + new Vector2(castFacing * .76f, .42f), new Vector2(.42f, .007f) * power, new Color(color.r, color.g, color.b, .11f * HeroActionVfxAlphaScale), 13, .026f);
            if (launchSpine) launchSpine.transform.localScale = new Vector3(Mathf.Abs(launchSpine.transform.localScale.x) * castFacing, launchSpine.transform.localScale.y, 1f);
            var launchHand = SpawnTimedSprite("SkillReleaseHandLaunchTick_ThinNoBlur", CombatVfxSprite(0), pos + new Vector2(castFacing * .80f, .50f), new Vector2(.10f, .009f) * power, new Color(.96f, 1f, 1f, .20f * HeroActionVfxAlphaScale), 15, .024f);
            if (launchHand) launchHand.transform.localScale = new Vector3(Mathf.Abs(launchHand.transform.localScale.x) * castFacing, launchHand.transform.localScale.y, 1f);
            var handEdge = SpawnTimedSprite("SkillReleaseHandEdgePin_ThinNoBlur", CombatVfxSprite(0), pos + new Vector2(castFacing * .66f, .52f), new Vector2(.12f, .008f) * power, new Color(.96f, 1f, 1f, .18f * HeroActionVfxAlphaScale), 15, .024f);
            if (handEdge) handEdge.transform.localScale = new Vector3(Mathf.Abs(handEdge.transform.localScale.x) * castFacing, handEdge.transform.localScale.y, 1);
            SpawnTimedSprite("SkillReleaseFootSnap_ThinNoBlur", CombatVfxSprite(0), pos + new Vector2(0, -.56f), new Vector2(.30f, .007f) * power, new Color(color.r, color.g, color.b, .070f * HeroActionVfxAlphaScale), 9, .030f);
            SpawnHeroSkillReleaseCrispFrameClamp(skill, castFacing, color, power);
            SpawnHeroSkillCrispPoseBracket(skill, castFacing, color, power);
            SpawnSkillReleaseEdgeClamp(skill, castFacing, color, power);
            SpawnHeroSkillFrameReadabilityTriad(skill, castFacing, color, power);
            SpawnHeroSkillReleaseThreeBeatRead(skill, castFacing, color, power);
            if (skill == SkillKind.SlashWave || skill == SkillKind.Fireball)
            {
                var band = SpawnTimedSprite("SkillReleaseForwardBand_ThinNoBlur", CombatVfxSprite(0), pos + new Vector2(castFacing * .66f, .30f), new Vector2(.38f, .005f) * power, new Color(1f, 1f, 1f, .070f * HeroActionVfxAlphaScale), 13, .022f);
                if (band) band.transform.localScale = new Vector3(Mathf.Abs(band.transform.localScale.x) * castFacing, band.transform.localScale.y, 1);
            }
            else
            {
                SpawnTimedSprite("SkillReleaseGroundPulse_ThinNoBlur", CombatVfxSprite(0), pos + new Vector2(0, -.44f), new Vector2(skill == SkillKind.ThunderStrike ? .30f : .40f, .005f), new Color(color.r, color.g, color.b, .060f * HeroActionVfxAlphaScale), 12, .026f);
            }
            ShakeCamera(skill == SkillKind.ThunderStrike ? .028f : .018f, .080f);
            if (skill == SkillKind.ThunderStrike || skill == SkillKind.FrostNova) TriggerCombatFlash(.055f, .075f);
        }

        private void SpawnHeroSkillReleaseCrispFrameClamp(SkillKind skill, int castFacing, Color color, float power)
        {
            if (!player || !fxRoot) return;
            Vector2 pos = player.transform.position;
            float dir = castFacing >= 0 ? 1f : -1f;
            float alphaScale = effectsIntensity > .75f ? 1f : .72f;
            var handClamp = SpawnTimedSprite("HeroSkillReleaseHandFrameClamp_NoEchoBody_NoYellowPlate", CombatVfxSprite(0), pos + new Vector2(dir * .72f, .52f), new Vector2(.11f, .006f) * power, new Color(.96f, 1f, 1f, .18f * HeroActionVfxAlphaScale * alphaScale), 16, .018f);
            if (handClamp) handClamp.transform.localScale = new Vector3(Mathf.Abs(handClamp.transform.localScale.x) * dir, handClamp.transform.localScale.y, 1f);
            var torsoClamp = SpawnTimedSprite("HeroSkillReleaseTorsoFrameClamp_NoEchoBody_NoYellowPlate", CombatVfxSprite(0), pos + new Vector2(dir * .22f, .34f), new Vector2(.16f, .005f) * power, new Color(color.r, color.g, color.b, .12f * HeroActionVfxAlphaScale * alphaScale), 14, .020f);
            if (torsoClamp) torsoClamp.transform.localScale = new Vector3(Mathf.Abs(torsoClamp.transform.localScale.x) * dir, torsoClamp.transform.localScale.y, 1f);
            SpawnTimedSprite("HeroSkillReleaseFootFrameClamp_NoEchoBody_NoYellowPlate", CombatVfxSprite(0), pos + new Vector2(0f, -.58f), new Vector2(skill == SkillKind.ThunderStrike ? .24f : .30f, .006f) * power, new Color(color.r, color.g, color.b, .075f * HeroActionVfxAlphaScale * alphaScale), 10, .022f);
        }

