        private void SpawnHeroSkillFrameReadabilityTriad(SkillKind skill, int castFacing, Color color, float power)
        {
            if (!player || !fxRoot) return;
            Vector2 pos = player.transform.position;
            float dir = castFacing >= 0 ? 1f : -1f;
            float alphaScale = effectsIntensity > .75f ? 1f : .62f;
            var handPin = SpawnTimedSprite("HeroSkillFrameReadHandPin_NoEchoBody_NoYellowPlate_ThinNoBlur", CombatVfxSprite(0), pos + new Vector2(dir * .70f, .50f), new Vector2(.10f, .005f) * power, new Color(.96f, 1f, 1f, .16f * HeroActionVfxAlphaScale * alphaScale), 16, .016f);
            if (handPin) handPin.transform.localScale = new Vector3(Mathf.Abs(handPin.transform.localScale.x) * dir, handPin.transform.localScale.y, 1f);
            var torsoAxis = SpawnTimedSprite("HeroSkillFrameReadTorsoAxis_NoEchoBody_NoYellowPlate_ThinNoBlur", CombatVfxSprite(0), pos + new Vector2(dir * .18f, .34f), new Vector2(.18f, .005f) * power, new Color(color.r, color.g, color.b, .10f * HeroActionVfxAlphaScale * alphaScale), 14, .018f);
            if (torsoAxis) torsoAxis.transform.localScale = new Vector3(Mathf.Abs(torsoAxis.transform.localScale.x) * dir, torsoAxis.transform.localScale.y, 1f);
            SpawnTimedSprite("HeroSkillFrameReadFootPlant_NoEchoBody_NoYellowPlate_ThinNoBlur", CombatVfxSprite(0), pos + new Vector2(-dir * .04f, -.57f), new Vector2(.24f, .005f) * power, new Color(.72f, .96f, 1f, .070f * HeroActionVfxAlphaScale * alphaScale), 10, .020f);
            if (skill == SkillKind.SlashWave || skill == SkillKind.Fireball)
            {
                var forwardCut = SpawnTimedSprite("HeroSkillFrameReadForwardCut_NoEchoBody_NoYellowPlate_ThinNoBlur", CombatVfxSprite(0), pos + new Vector2(dir * .84f, .30f), new Vector2(.22f, .0045f) * power, new Color(.96f, 1f, 1f, .11f * HeroActionVfxAlphaScale * alphaScale), 15, .018f);
                if (forwardCut) forwardCut.transform.localScale = new Vector3(Mathf.Abs(forwardCut.transform.localScale.x) * dir, forwardCut.transform.localScale.y, 1f);
            }
