        private bool ShouldShowSkillCastWorldText(SkillKind skill)
        {
            if (tutorialStep <= 2 && currentSegment <= 1) return true;
            if (ActiveEnemiesInCurrentArea() > 0) return false;
            return shrineAvailable || CanUseShopInteraction() || skill == SkillKind.FrostNova || skill == SkillKind.ThunderStrike;
        }

        private void SpawnProjectile(Vector2 pos, Vector2 velocity, float damage, bool playerOwned, Color color, int vfxIndex = -1, int impactVfxIndex = -1, float radius = .42f, string sourceLabel = "", SkillKind? sourceSkill = null)
        {
            bool fireball = sourceSkill == SkillKind.Fireball;
            bool thunder = sourceSkill == SkillKind.ThunderStrike;
            Vector2 coreSize = playerOwned
                ? new Vector2(fireball ? .34f : thunder ? .28f : .42f, fireball ? .046f : .038f)
                : new Vector2(.36f, .034f);
            Color coreColor = playerOwned
                ? fireball ? new Color(.68f, .95f, 1f, .48f) : new Color(.76f, .97f, 1f, .56f)
                : new Color(color.r, color.g, color.b, .58f);
            var fx = RectObj(playerOwned ? "PlayerSkillProjectileCore_NoPlate" : "EnemyProjectileCore_NoPlate", fxRoot, pos, coreSize, coreColor, 8);
            // PlayerAttackUsesProceduralCleanSlashOnly: external slash sheets are kept for later curation, but disabled here to avoid dirty transparent edges.
            if (velocity.x < 0) fx.transform.localScale = new Vector3(-Mathf.Abs(fx.transform.localScale.x), fx.transform.localScale.y, 1);
            if (playerOwned) AddPlayerSkillProjectileReadability(fx, velocity, color, sourceSkill);
            else AddEnemyProjectileReadability(fx, velocity, color);
            hitEffects.Add(new HitFx { Root = fx, Renderer = fx.GetComponent<SpriteRenderer>(), Velocity = velocity, Damage = damage, Life = 2.2f, Radius = radius, ImpactVfxIndex = impactVfxIndex, Tier = playerOwned ? HitTier.Skill : HitTier.Light, PlayerOwned = playerOwned, Piercing = false, SourceLabel = sourceLabel, SourceSkill = sourceSkill });
        }

        private void AddPlayerSkillProjectileReadability(GameObject fx, Vector2 velocity, Color color, SkillKind? sourceSkill)
        {
            if (!fx) return;
            float dir = Mathf.Abs(velocity.x) < .05f ? facing : Mathf.Sign(velocity.x);
            Color edgeColor = sourceSkill == SkillKind.Fireball ? C("#BFEFFF") : sourceSkill == SkillKind.ThunderStrike ? C("#B8F7FF") : C("#DDFBFF");
            var trail = RectObj("PlayerSkillReadableTrail_ThinNoBlur", fx.transform, new Vector2(-dir * .30f, 0f), new Vector2(.50f, .022f), new Color(edgeColor.r, edgeColor.g, edgeColor.b, .11f), 10);
            trail.transform.localScale = new Vector3(Mathf.Abs(trail.transform.localScale.x), trail.transform.localScale.y, 1);
            var edge = RectObj("PlayerSkillLeadingEdge_ThinNoBlur", fx.transform, new Vector2(dir * .36f, 0f), new Vector2(.038f, .22f), new Color(edgeColor.r, edgeColor.g, edgeColor.b, .58f), 12);
            edge.transform.localScale = new Vector3(Mathf.Abs(edge.transform.localScale.x), edge.transform.localScale.y, 1);
            var spine = RectObj("PlayerSkillCrispSpine_ThinNoBlur", fx.transform, new Vector2(-dir * .02f, .01f), new Vector2(.54f, .016f), new Color(.94f, 1f, 1f, .56f), 12);
            spine.transform.localScale = new Vector3(Mathf.Abs(spine.transform.localScale.x), spine.transform.localScale.y, 1);
            if (sourceSkill == SkillKind.Fireball)
                RectObj("PlayerSkillHotCore_ThinNoBlur", fx.transform, Vector2.zero, new Vector2(.16f, .026f), new Color(1f, .50f, .22f, .18f), 11);
        }

        private void AddEnemyProjectileReadability(GameObject fx, Vector2 velocity, Color color)
        {
            if (!fx) return;
            float dir = Mathf.Abs(velocity.x) < .05f ? 1f : Mathf.Sign(velocity.x);
            var needle = RectObj("EnemyProjectileNeedle_NoPlate", fx.transform, new Vector2(dir * .18f, .01f), new Vector2(.30f, .010f), new Color(color.r, color.g, color.b, .18f), 10);
            needle.transform.localScale = new Vector3(Mathf.Abs(needle.transform.localScale.x), needle.transform.localScale.y, 1);
            RectObj("EnemyProjectileHeadTick_NoPlate", fx.transform, new Vector2(dir * .32f, 0f), new Vector2(.040f, .030f), new Color(1f, .82f, .84f, .20f), 11);
        }

        private Fighter AutoFaceNearestEnemy(float radius, string cueLabel)
        {
            if (!autoAimEnabled || !player || enemies.Count == 0) return null;
            var origin = player.transform.position;
            var target = enemies
                .Where(e => !e.Dead && e.Root && Mathf.Abs(e.Root.transform.position.x - origin.x) <= radius && Mathf.Abs(e.Root.transform.position.y - origin.y) < 2.8f)
                .OrderBy(e => Vector2.Distance(e.Root.transform.position, origin))
                .FirstOrDefault();
            if (target == null) return null;
            facing = target.Root.transform.position.x >= origin.x ? 1 : -1;
            playerSprite.flipX = facing < 0;
            ShowAutoAimTargetCue(target.Root, cueLabel);
            return target;
        }

        private void ShowAutoAimTargetCue(GameObject target, string label)
        {
            if (!target || !fxRoot || !autoAimEnabled) return;
            autoAimCueCooldown -= Time.deltaTime;
            if (autoAimCueTarget == target && autoAimCueCooldown > 0f) return;
            autoAimCueTarget = target;
            autoAimCueCooldown = .34f;

            Vector3 pos = target.transform.position;
            SpawnTimedSprite("AutoAimTargetFootReticle_NoText_NoTexturePlate", CombatVfxSprite(0), pos + Vector3.down * .18f, new Vector2(.48f, .020f), new Color(.50f, .92f, 1f, .14f), 8, .10f);
            SpawnTimedSprite("AutoAimTargetMark_NoText_NoTexturePlate", CombatVfxSprite(0), pos + Vector3.up * .82f, new Vector2(.30f, .034f), new Color(.90f, 1f, 1f, .22f), 10, .10f);
            SpawnTimedSprite("AutoAimTargetNeedleLine_NoText_NoTexturePlate", CombatVfxSprite(0), pos + Vector3.up * 1.06f, new Vector2(.16f, .020f), new Color(.90f, 1f, 1f, .20f), 10, .085f);
        }

        private void ClearAutoAimTargetCue()
        {
            autoAimCueTarget = null;
            autoAimCueCooldown = 0f;
        }

        private void UpdateEnemies(float dt)
        {
            PruneInvalidEnemies();
            foreach (var e in enemies.ToArray())
            {
                if (e == null || e.Dead || !e.Root) continue;
                UpdateEnemyHpPulse(e, dt);
                var p = player.transform.position;
                var ep = e.Root.transform.position;
                ep = RepairEnemyPlayablePosition(e, ep);
                e.Root.transform.position = ep;
                if (currentSegment < progressGates.Count && ep.x > CurrentSegmentRight() + .8f)
                    continue;
                UpdateEnemyHitReaction(e, dt);
                UpdateEnemyMotionPose(e, dt);
                UpdateEnemyReadabilitySilhouette(e, dt);
                UpdateEnemyStatusReadability(e, dt);
                e.WasMoving = false;
                e.AttackLockTimer = Mathf.Max(0f, e.AttackLockTimer - dt);
                if (e.HitStun > 0)
                {
                    e.HitStun -= dt;
                    e.Attacking = false;
                    SetEnemySprite(e, EnemyHitSpriteIndex(e.Kind));
                    ep += (Vector3)(e.Knockback * dt);
                    e.Knockback = Vector2.Lerp(e.Knockback, Vector2.zero, dt * 8f);
                    ep.x = Mathf.Clamp(ep.x, LeftBound, RightBound);
                    ep.y = Mathf.Lerp(ep.y, GroundedEnemyY(e.Kind) + EnemyHitVisualLift(e.Kind), dt * 18f);
                    ep = ApplyEnemySeparation(e, ep, dt);
                    e.Root.transform.position = ep;
                    continue;
                }
                ep.y = Mathf.Lerp(ep.y, GroundedEnemyY(e.Kind), dt * 10f);
                float dist = Mathf.Abs(p.x - ep.x);
                int dir = p.x > ep.x ? 1 : -1;
                e.Sprite.flipX = dir < 0;
                UpdateEnemyIntentReadability(e, dist, dt);
                if (e.FrozenTimer > 0f)
                {
                    ep = ApplyEnemySeparation(e, ep, dt);
                    e.Root.transform.position = ep;
                    SetEnemySprite(e, EnemyIdleSpriteIndex(e.Kind));
                    continue;
                }
                e.AttackTimer -= dt;
                if (e.AttackLockTimer > 0f)
                {
                    ep = ApplyEnemySeparation(e, ep, dt);
                    e.Root.transform.position = ep;
                    SetEnemySprite(e, EnemyHitSpriteIndex(e.Kind));
                    continue;
                }
                if (e.Kind == EnemyKind.Boss && !e.PhaseTwo && e.Hp < e.MaxHp * .5f)
                {
                    e.PhaseTwo = true;
                    SetEnemySprite(e, 23);
                    noticeText.text = "Boss 碎甲狂暴：雷阵展开";
                    SetBossAttackCue("阶段变化：碎甲狂暴，雷击加入循环", 2.8f);
                    SpawnBossPhaseTransition(e);
                    StartCoroutine(BossThunderField(e));
                }
                if (e.Elite) UpdateEliteAura(e, dt);
                if (EnemyActionSuppressed(e))
                {
                    e.Attacking = false;
                    continue;
                }
                if (dist > e.AttackRange)
                {
                    e.Attacking = false;
                    e.WasMoving = true;
                    e.MoveAnimTimer += dt;
                    ep.x += dir * e.Speed * dt;
                    ep.x = Mathf.Clamp(ep.x, LeftBound, RightBound);
                    ep = ApplyEnemySeparation(e, ep, dt);
                    e.Root.transform.position = ep;
                    SetEnemySprite(e, EnemyMoveSpriteIndex(e.Kind, e.MoveAnimTimer));
                }
                else if (CanEnemyStartAttack(e))
                {
                    ep = ApplyEnemySeparation(e, ep, dt);
                    e.Root.transform.position = ep;
                    e.AttackTimer = EnemyAttackCooldown(e.Kind);
                    int attackToken = ++e.AttackToken;
                    e.Attacking = true;
                    if (e.Kind == EnemyKind.Archer)
                    {
                        StartCoroutine(ArcherAttack(e, dir, attackToken));
                    }
                    else if (e.Kind == EnemyKind.Boss)
                        StartCoroutine(BossAttack(e, dir, attackToken));
                    else
                        StartCoroutine(EnemyMelee(e, dir, attackToken));
                }
            }
        }

        private Vector3 RepairEnemyPlayablePosition(Fighter e, Vector3 ep)
        {
            if (e == null || e.Dead || !e.Root) return ep;
            float groundedY = GroundedEnemyY(e.Kind);
            if (float.IsNaN(ep.x) || float.IsInfinity(ep.x)) ep.x = SegmentCenters[Mathf.Clamp(currentSegment, 0, SegmentCenters.Length - 1)];
            if (float.IsNaN(ep.y) || float.IsInfinity(ep.y) || ep.y < GroundY + .05f || ep.y > GroundY + 5.8f)
                ep.y = groundedY;

            int segment = Mathf.Clamp(SegmentIndexForX(ep.x), 0, SegmentRights.Length - 1);
            float segmentLeft = segment > 0 ? SegmentRights[segment - 1] + .45f : LeftBound + .45f;
            float segmentRight = SegmentRights[segment] - .45f;
            if (segment == currentSegment && !CurrentRoomCanAdvance(currentSegment))
                segmentRight = Mathf.Min(segmentRight, CurrentMovementRight() - .34f);
            if (segmentRight <= segmentLeft) segmentRight = segmentLeft + .20f;
            ep.x = Mathf.Clamp(ep.x, segmentLeft, segmentRight);
            return ep;
        }

        private Vector3 ApplyEnemySeparation(Fighter e, Vector3 ep, float dt)
        {
            if (e == null || e.Boss || e.Dead || !e.Root) return ep;
            int segment = SegmentIndexForX(ep.x);
            float push = 0f;
            foreach (var other in enemies)
            {
                if (other == null || other == e || other.Dead || other.Boss || !other.Root) continue;
                Vector3 op = other.Root.transform.position;
                if (!IsXInSegment(op.x, segment)) continue;
                if (Mathf.Abs(op.y - ep.y) > EnemySeparationVerticalBand) continue;
                float minDistance = e.Elite || other.Elite ? EnemySeparationEliteRadius : EnemySeparationRadius;
                float delta = ep.x - op.x;
                float abs = Mathf.Abs(delta);
                if (abs >= minDistance) continue;
                float sign = abs > .015f ? Mathf.Sign(delta) : e.Root.GetInstanceID() > other.Root.GetInstanceID() ? 1f : -1f;
                push += sign * (minDistance - abs) / minDistance;
            }
            float frameScale = Mathf.Clamp(dt * 60f, .45f, 1.25f);
            if (player && IsXInSegment(player.transform.position.x, segment) && Mathf.Abs(player.transform.position.y - ep.y) <= EnemySeparationVerticalBand)
            {
                float playerDelta = ep.x - player.transform.position.x;
                float playerAbs = Mathf.Abs(playerDelta);
                bool postHitLocked = e.HitStun > 0f || e.AttackLockTimer > 0f;
                float playerBuffer = postHitLocked ? EnemyPostHitPlayerClearBuffer : EnemyPlayerReadabilityBuffer;
                if (playerAbs < playerBuffer)
                {
                    float sign = playerAbs > .015f ? Mathf.Sign(playerDelta) : e.Root.GetInstanceID() % 2 == 0 ? 1f : -1f;
                    float playerPush = sign * (playerBuffer - playerAbs) / playerBuffer;
                    float strength = postHitLocked ? EnemyPostHitPlayerClearStrength : EnemyPlayerReadabilityStrength;
                    float limit = (postHitLocked ? EnemyPostHitPlayerClearMaxStep : EnemyPlayerReadabilityMaxStep) * frameScale;
                    ep.x += Mathf.Clamp(playerPush * strength * dt, -limit, limit);
                }
            }
            if (Mathf.Abs(push) > .001f)
                ep.x += Mathf.Clamp(push * EnemySeparationStrength * dt, -EnemySeparationMaxStep * frameScale, EnemySeparationMaxStep * frameScale);
            float segmentLeft = segment > 0 ? SegmentRights[segment - 1] + .30f : LeftBound + .30f;
            float segmentRight = SegmentRights[Mathf.Clamp(segment, 0, SegmentRights.Length - 1)] - .30f;
            if (segment == currentSegment && !CurrentRoomCanAdvance(currentSegment))
                segmentRight = Mathf.Min(segmentRight, CurrentMovementRight() - .18f);
            ep.x = Mathf.Clamp(ep.x, segmentLeft, segmentRight);
            return ep;
        }

        private static int EnemyIdleSpriteIndex(EnemyKind kind)
        {
            if (kind == EnemyKind.Mushroom) return 0;
            if (kind == EnemyKind.Archer) return 6;
            if (kind == EnemyKind.Slime) return 12;
            return 18;
        }

        private static int EnemyMoveSpriteIndex(EnemyKind kind, float animTimer = 0f)
        {
            int step = Mathf.FloorToInt(animTimer * 10f) % 2;
            if (kind == EnemyKind.Mushroom) return 2 + step;
            if (kind == EnemyKind.Archer) return 8 + step;
            if (kind == EnemyKind.Slime) return 14 + step;
            return 20 + step;
        }

        private static int EnemyHitSpriteIndex(EnemyKind kind)
        {
            if (kind == EnemyKind.Mushroom) return 5;
            if (kind == EnemyKind.Archer) return 11;
            if (kind == EnemyKind.Slime) return 17;
            return 23;
        }

        private static float GroundedEnemyY(EnemyKind kind)
        {
            return GroundY + EnemyFootingHeight(kind);
        }

        private static float EnemyHitVisualLift(EnemyKind kind)
        {
            if (kind == EnemyKind.Mushroom) return .18f;
            if (kind == EnemyKind.Archer) return .06f;
            if (kind == EnemyKind.Slime) return .05f;
            return 0f;
        }

        private void UpdateEnemyHpPulse(Fighter e, float dt)
        {
            if (!e.HpFill) return;
            e.HpPulse = Mathf.MoveTowards(e.HpPulse, 0f, dt * 5.5f);
            e.HpVisibleTimer = Mathf.Max(0f, e.HpVisibleTimer - dt);
            float scale = 1f + e.HpPulse * .18f;
            e.HpFill.transform.parent.localScale = new Vector3(scale, scale, 1);
            e.HpFill.color = Color.Lerp(C("#D83A3A"), C("#FFFFFF"), e.HpPulse);
            float dist = player && e.Root ? Vector2.Distance(player.transform.position, e.Root.transform.position) : 99f;
            bool threat = e.Root && player && Mathf.Abs(e.Root.transform.position.x - player.transform.position.x) <= e.AttackRange + .65f && e.AttackTimer < EnemyAttackCooldown(e.Kind) * .42f;
            float alpha = e.Boss ? .18f : e.Elite ? .72f : e.HpVisibleTimer > 0f ? .46f : threat ? .12f : dist < 1.25f ? .06f : 0f;
            ApplyEnemyHpBarVisibility(e, alpha);
        }

        private void ApplyEnemyHpBarVisibility(Fighter e, float alpha)
        {
            if (e == null || !e.HpBarRoot) return;
            var graphics = e.HpBarRoot.GetComponentsInChildren<Graphic>(true);
            for (int i = 0; i < graphics.Length; i++)
            {
                var color = graphics[i].color;
                graphics[i].color = new Color(color.r, color.g, color.b, alpha);
            }
        }

        private void UpdateEnemyIntentReadability(Fighter e, float distanceToPlayer, float dt)
        {
            if (e == null || e.Dead) return;
            bool inThreatRange = distanceToPlayer <= e.AttackRange + (e.Boss ? 1.2f : .65f);
            float charge = inThreatRange ? Mathf.Clamp01(1f - e.AttackTimer / EnemyAttackCooldown(e.Kind)) : 0f;
            Color color = EnemyIntentWarnColor(e);
            float pulse = .72f + Mathf.PingPong(Time.time * (e.Boss ? 3.2f : 4.6f), .28f);
            if (e.IntentRing)
            {
                float alpha = Mathf.Lerp(0f, e.Boss ? .46f : e.Elite ? .24f : 0f, charge) * effectsIntensity;
                e.IntentRing.color = new Color(color.r, color.g, color.b, alpha);
                float baseScale = e.Boss ? 1.0f : .72f;
                e.IntentRing.transform.localScale = e.Boss || e.Elite
                    ? new Vector3(baseScale + charge * .28f * pulse, (baseScale * .34f) + charge * .12f, 1f)
                    : new Vector3(baseScale + charge * .14f * pulse, (baseScale * .18f) + charge * .045f, 1f);
            }
            if (!e.IntentText) return;
            float textThreshold = e.Boss || e.Elite ? .55f : 1.01f;
            if (charge < textThreshold)
            {
                e.IntentText.text = "";
                e.IntentText.color = Color.clear;
                return;
            }
            e.IntentText.text = charge > .82f ? EnemyIntentVerb(e.Kind) : e.Boss ? "警戒" : "";
            e.IntentText.color = new Color(color.r, color.g, color.b, Mathf.Lerp(.46f, .92f, charge));
            e.IntentText.transform.localScale = Vector3.one * Mathf.Lerp(.88f, 1.08f, charge);
            if (charge > .78f && enemyThreatHintCooldown <= 0f && player)
            {
                e.ReadabilitySilhouetteTimer = Mathf.Max(e.ReadabilitySilhouetteTimer, EnemySilhouetteThreatDuration);
                enemyThreatHintCooldown = e.Boss ? .42f : .58f;
                SpawnDodgeNowHint(e, color);
                ShowDamageDirection(e.Root.transform.position);
            }
        }

        private static Color EnemyIntentWarnColor(Fighter e)
        {
            if (e == null) return new Color(1f, .36f, .42f, 1f);
            if (e.Boss) return new Color(1f, .32f, .36f, 1f);
            if (e.Elite) return new Color(.56f, 1f, .46f, 1f);
            return e.Kind == EnemyKind.Archer ? new Color(1f, .34f, .46f, 1f) : new Color(1f, .30f, .40f, 1f);
        }

        private void SpawnDodgeNowHint(Fighter e, Color color)
        {
            if (e == null || e.Dead || !e.Root || !fxRoot) return;
            string label = dodgeCooldown <= .05f ? "闪避" : "拉开";
            if (e.Boss || e.Elite)
                ShowThreatAlert(ThreatAlertTitle(e), label == "闪避" ? "现在闪避，离开预警范围" : "闪避冷却中，先拉开距离", e.Boss ? .86f : .66f, color);
            Vector3 pos = e.Root.transform.position + Vector3.up * (e.Boss ? 2.45f : 1.64f);
            if (e.Boss || e.Elite)
            {
                SpawnTimedRect("EnemyThreatDodgeHintNeedle_NoTexturePlate", pos + Vector3.down * .10f, e.Boss ? new Vector2(.46f, .026f) : new Vector2(.24f, .014f), new Color(color.r, color.g, color.b, e.Boss ? .34f : .16f), 12, .12f);
                var text = WorldText("EnemyThreatDodgeHint", fxRoot, label, pos + Vector3.up * .08f, e.Boss ? 22 : 18, 34);
                text.color = new Color(color.r, color.g, color.b, e.Boss ? .74f : .66f);
                AnimateFloatingWorldText(text, new Vector2(0, .12f), .24f, 1.06f);
            }
            else
            {
                SpawnTimedRect("MinorEnemyThreatNeedleLine_NoYellowPlate", pos, new Vector2(.10f, .0035f), new Color(color.r, color.g, color.b, .036f), 12, .052f);
                SpawnTimedRect("MinorEnemyThreatFootLine_NoYellowPlate", e.Root.transform.position + Vector3.down * .42f, new Vector2(.16f, .0035f), new Color(color.r, color.g, color.b, .018f), 8, .052f);
            }
            if (e.Boss || e.Elite)
                SpawnTimedRect("EnemyThreatThinFootPulse_NoTexturePlate", e.Root.transform.position + Vector3.down * .50f, e.Boss ? new Vector2(1.48f, .030f) : new Vector2(.46f, .012f), new Color(color.r, color.g, color.b, e.Boss ? .22f : .070f), e.Boss ? 8 : 7, .14f);
        }

        private string ThreatAlertTitle(Fighter e)
        {
            if (e == null) return "高危前摇";
            if (e.Boss) return "Boss 高危前摇";
            if (e.Elite) return "精英毒素压迫";
            if (e.Kind == EnemyKind.Archer) return "弓手瞄准";
            return "近战扑击";
        }

        private void ApplyEnemyFreeze(Fighter e, float duration)
        {
            if (e == null || e.Dead || duration <= 0f) return;
            e.FrozenTimer = Mathf.Max(e.FrozenTimer, duration);
            e.Attacking = false;
            e.AttackToken++;
            e.AttackTimer = Mathf.Max(e.AttackTimer, Mathf.Min(duration, e.Boss ? .42f : .85f));
            e.AttackLockTimer = Mathf.Max(e.AttackLockTimer, Mathf.Min(duration, e.Boss ? .30f : .64f));
            ClearEnemyIntentOnHit(e);
            if (e.Sprite) e.Sprite.color = new Color(.72f, .94f, 1f, 1f);
            SpawnTimedSprite("EnemyFreezeStatusFx_NoTexturePlate", CombatVfxSprite(0), e.Root.transform.position + Vector3.up * (e.Boss ? 1.18f : .62f), e.Boss ? new Vector2(1.20f, .036f) : new Vector2(.78f, .030f), new Color(.78f, .96f, 1f, .50f), 9, .18f);
        }

        private void UpdateEnemyStatusReadability(Fighter e, float dt)
        {
            if (e == null || e.Dead) return;
            if (e.HitStun > 0f)
            {
                string label = EnemyStatusLabel(e, e.HitReactTier);
                Color color = e.HitReactTier == HitTier.Heavy ? C("#9FF8FF") : e.HitReactTier == HitTier.Skill ? C("#7EDCFF") : C("#FFFFFF");
                SetEnemyStatusText(e, label, color, true);
                return;
            }

            if (e.FrozenTimer > 0f)
            {
                e.FrozenTimer = Mathf.Max(0f, e.FrozenTimer - dt);
                SetEnemyStatusText(e, e.Boss ? "短暂冻结" : "冻结", C("#9FEAFF"), true);
                return;
            }

            if (e.Sprite && e.Sprite.color != e.BaseColor)
            {
                e.Sprite.color = e.BaseColor;
            }

            if (e.Boss && e.PhaseTwo)
            {
                SetEnemyStatusText(e, "狂暴", C("#FF8A6A"), true);
                return;
            }

            if (e.Elite)
            {
                bool nearPlayer = player && e.Root && Vector2.Distance(player.transform.position, e.Root.transform.position) <= EliteStatusLabelDistance;
                if (nearPlayer) SetEnemyStatusText(e, "毒素光环", C("#9DFF7A"), false);
                else ClearEnemyStatusText(e);
                return;
            }

            ClearEnemyStatusText(e);
        }

        private static string EnemyStatusLabel(Fighter e, HitTier tier)
        {
            bool compact = e != null && !e.Boss && !e.Elite;
            if (tier == HitTier.Heavy) return compact ? "破势" : "破势硬直";
            if (tier == HitTier.Skill) return compact ? "术式" : "术式硬直";
            return compact ? "停" : "硬直";
        }

        private void TriggerEnemyHitReaction(Fighter e, HitTier tier, Vector2 hitDir)
        {
            if (e == null || !e.Root) return;
            e.HitReactTier = tier;
            e.HitReactDuration = e.Boss ? .12f : tier == HitTier.Heavy ? .26f : tier == HitTier.Skill ? .23f : .20f;
            e.HitReactTimer = e.HitReactDuration;
            if (tier == HitTier.Heavy)
                e.HitReactPeak = e.Boss ? new Vector2(1.05f, .96f) : new Vector2(1.24f, .80f);
            else if (tier == HitTier.Skill)
                e.HitReactPeak = e.Boss ? new Vector2(1.04f, .97f) : new Vector2(1.18f, .85f);
            else
                e.HitReactPeak = e.Boss ? new Vector2(1.025f, .985f) : new Vector2(1.14f, .88f);
            e.ReadabilitySilhouetteTimer = 0f;
            SetEnemySprite(e, EnemyHitSpriteIndex(e.Kind));
            SpawnEnemyRecoilHitLines(e, hitDir, tier);
            SpawnEnemyHitDirectionCue(e, hitDir, tier);
            SpawnEnemyHitStunBodyClamp(e, hitDir, tier);
            SpawnEnemyHitIdentityFreezeCue(e, hitDir, tier);
        }

        private void SpawnEnemyRecoilHitLines(Fighter e, Vector2 hitDir, HitTier tier)
        {
