            float height = e.Boss ? .026f : tier == HitTier.Light ? .010f : .016f;
            SpawnTimedSprite("EnemyRecoilContactLine_NoEchoBody", CombatVfxSprite(0), pos + new Vector2(-dir * (e.Boss ? .34f : .16f), e.Boss ? .62f : .30f), new Vector2(width, height), new Color(color.r, color.g, color.b, alpha * .42f), 9, tier == HitTier.Light ? .032f : .052f);
            SpawnTimedSprite("EnemyRecoilFootContactAo_CleanEllipse", SpriteCache.Circle, pos + new Vector2(-dir * .08f, e.Boss ? -.76f : -.48f), new Vector2(width * .72f, e.Boss ? .050f : .032f), new Color(.010f, .018f, .014f, e.Boss ? .070f : .050f), 8, tier == HitTier.Light ? .030f : .044f);
            SpawnTimedSprite("EnemyRecoilHitPin_NoEchoBody", CombatVfxSprite(0), pos + new Vector2(dir * (e.Boss ? .42f : .22f), e.Boss ? .78f : .42f), new Vector2(width * .14f, Mathf.Max(.008f, height * .54f)), new Color(color.r, color.g, color.b, alpha * .52f), 10, tier == HitTier.Light ? .030f : .045f);
