        private void UpdateEnemyHitReaction(Fighter e, float dt)
        {
            if (e == null || !e.Root) return;
            if (e.BaseScale == Vector3.zero) e.BaseScale = e.Root.transform.localScale;
            if (e.HitReactTimer > 0f && e.HitReactDuration > 0f)
            {
                e.HitReactTimer = Mathf.Max(0f, e.HitReactTimer - dt);
                float progress = 1f - Mathf.Clamp01(e.HitReactTimer / e.HitReactDuration);
                float pulse = Mathf.Sin(progress * Mathf.PI);
                Vector2 poseScale = Vector2.Lerp(Vector2.one, e.HitReactPeak, pulse);
                var target = new Vector3(e.BaseScale.x * poseScale.x, e.BaseScale.y * poseScale.y, e.BaseScale.z);
                e.Root.transform.localScale = Vector3.Lerp(e.Root.transform.localScale, target, dt * 24f);
                return;
            }
            e.Root.transform.localScale = Vector3.Lerp(e.Root.transform.localScale, e.BaseScale, dt * 14f);
        }

        private void UpdateEnemyMotionPose(Fighter e, float dt)
        {
            if (e == null || !e.Root || e.HitReactTimer > 0f) return;
            e.AnimTimer += dt;
            float pulse = Mathf.Sin(e.AnimTimer * (e.Attacking ? 18f : e.WasMoving ? 14f : 7.4f));
            float step = Mathf.Abs(Mathf.Sin(e.MoveAnimTimer * 12.6f));
            Vector3 scale = e.BaseScale;
            if (e.HitStun > 0f)
            {
                scale.x *= 1.08f + Mathf.Abs(pulse) * .035f;
                scale.y *= .88f;
            }
            else if (e.Attacking)
            {
                scale.x *= 1.05f + Mathf.Max(0f, pulse) * .035f;
                scale.y *= .94f;
                if (!e.Boss)
                    scale.y *= 1f - step * .018f;
            }
            else if (e.WasMoving && !e.Boss)
            {
                float kindBounce = e.Kind == EnemyKind.Slime ? .040f : e.Kind == EnemyKind.Mushroom ? .032f : .024f;
                float squash = e.Kind == EnemyKind.Slime ? .030f : .018f;
                scale.x *= 1f + step * squash;
                scale.y *= 1f + step * kindBounce - step * squash * .55f;
            }
            else
            {
                float idleAmp = e.Boss ? .004f : e.Kind == EnemyKind.Slime ? .014f : .010f;
                scale.x *= 1f + pulse * idleAmp;
                scale.y *= 1f - pulse * idleAmp * .78f;
            }
            e.Root.transform.localScale = Vector3.Lerp(e.Root.transform.localScale, scale, dt * 14f);
        }

        private void UpdateEnemyReadabilitySilhouette(Fighter e, float dt)
        {
            if (e == null || !e.ReadabilitySilhouette || !e.Sprite)
                return;
            e.ReadabilitySilhouetteTimer = Mathf.Max(0f, e.ReadabilitySilhouetteTimer - dt);
            e.ReadabilitySilhouette.sprite = e.Sprite.sprite;
            e.ReadabilitySilhouette.flipX = e.Sprite.flipX;
            e.ReadabilitySilhouette.sortingOrder = e.Sprite.sortingOrder - 1;
            bool hitLocked = e.HitStun > 0f || e.AttackLockTimer > 0f;
            bool threat = e.Attacking || e.ReadabilitySilhouetteTimer > 0f;
            float alpha = hitLocked ? EnemyEnvironmentSilhouetteHitAlpha : threat ? EnemyEnvironmentSilhouetteThreatAlpha : EnemyEnvironmentSilhouetteIdleAlpha;
            if (e.Boss) alpha *= .78f;
            if (e.Elite) alpha = Mathf.Min(.26f, alpha + .035f);
            float sideOffset = e.Sprite.flipX ? -.045f : .045f;
            e.ReadabilitySilhouette.transform.localPosition = new Vector3(sideOffset, -.060f, .035f);
            e.ReadabilitySilhouette.color = new Color(.018f, .050f, .042f, alpha * effectsIntensity);
            e.ReadabilitySilhouette.enabled = alpha > .010f;
        }

        private void SetEnemyStatusText(Fighter e, string label, Color color, bool pulse)
        {
            if (e == null || !e.StatusText) return;
            if (string.IsNullOrEmpty(label))
            {
                ClearEnemyStatusText(e);
                return;
            }
            e.StatusText.text = label;
            bool minor = !e.Boss && !e.Elite;
            e.StatusText.fontSize = e.Boss ? 22 : e.Elite ? 17 : 14;
            float baseAlpha = minor ? .42f : pulse ? .72f : .64f;
            float pulseAlpha = minor ? .10f : .18f;
            float alpha = pulse ? baseAlpha + Mathf.Sin(Time.time * 7f) * pulseAlpha : baseAlpha;
            e.StatusText.color = new Color(color.r, color.g, color.b, Mathf.Clamp01(alpha));
            float scale = pulse ? 1f + Mathf.Sin(Time.time * 7f) * (minor ? .030f : .06f) : 1f;
            e.StatusText.transform.localScale = new Vector3(scale, scale, 1f);
        }

        private static void ClearEnemyStatusText(Fighter e)
        {
            if (e == null || !e.StatusText) return;
            e.StatusText.text = "";
            e.StatusText.color = Color.clear;
            e.StatusText.transform.localScale = Vector3.one;
        }

        private static float EnemyAttackCooldown(EnemyKind kind)
        {
            return kind == EnemyKind.Boss ? 1.25f : kind == EnemyKind.Archer ? 1.5f : .95f;
        }

        private static string EnemyIntentVerb(EnemyKind kind)
        {
            if (kind == EnemyKind.Boss) return "危险";
            if (kind == EnemyKind.Archer) return "瞄准";
            return "突袭";
        }

        private void UpdateEliteAura(Fighter elite, float dt)
        {
            elite.AuraTimer -= dt;
            if (elite.AuraTimer > 0) return;
            elite.AuraTimer = .72f;
            var pos = elite.Root.transform.position;
            var pulse = SpawnTimedSprite("ElitePoisonPulse_NoYellowPlate", CombatVfxSprite(0), pos + Vector3.down * .2f, new Vector2(2.05f, .036f), new Color(.45f, 1f, .35f, .16f), 7, .20f);
            AddDangerPattern(pulse, DangerPatternKind.ToxicWaves, C("#C8FF9A"), 4);
            SpawnTimedSprite("ElitePoisonSafeEdge_NoYellowPlate", CombatVfxSprite(0), pos + Vector3.down * .2f, new Vector2(2.14f, .026f), new Color(.58f, 1f, .76f, .16f), 8, .18f);
            if (Mathf.Abs(player.transform.position.x - pos.x) < 1.7f && Mathf.Abs(player.transform.position.y - pos.y) < 1.45f)
                DamagePlayer(7f + stageIndex * 1.5f, "毒素光环", pos);
        }

        private void SetEnemySprite(Fighter enemy, int index)
        {
            if (enemy == null || !enemy.Sprite || enemySprites == null || index < 0 || index >= enemySprites.Length) return;
            index = ResolveCleanEnemySpriteIndex(enemy.Kind, index);
            enemy.Sprite.sprite = enemySprites[index];
            if (enemy.ReadabilitySilhouette) enemy.ReadabilitySilhouette.sprite = enemy.Sprite.sprite;
        }

        private int ResolveCleanEnemySpriteIndex(EnemyKind kind, int requestedIndex)
        {
            if (EnemyFrameIsClean(requestedIndex)) return requestedIndex;
            int idle = EnemyIdleSpriteIndex(kind);
            if (idle >= 0 && idle < enemySprites.Length && EnemyFrameIsClean(idle)) return idle;
            return requestedIndex;
        }

        private bool EnemyFrameIsClean(int index)
        {
            if (enemyFrameClean.TryGetValue(index, out bool clean)) return clean;
            clean = enemySprites != null
                && index >= 0
                && index < enemySprites.Length
                && enemySprites[index]
                && !SpriteHasGeneratedBackdropPlate(enemySprites[index]);
            enemyFrameClean[index] = clean;
            return clean;
        }

        private IEnumerator ResetEnemySpriteAfter(Fighter enemy, int index, float delay)
        {
            yield return new WaitForSeconds(delay);
            if (enemy != null && !enemy.Dead) SetEnemySprite(enemy, index);
        }

        private void UpdateCompanionPet(float dt)
        {
            if (!companionPet || !companionSprite || !player) return;
            petAnimTimer += dt;
            petAttackTimer -= dt;
            bool activeCombat = ActiveEnemiesInCurrentArea() > 0 && !titleActive && !paused && !inputLocked;
            bool bossFocus = BossFocusHudActive();
            float backOffset = bossFocus ? CompanionBossFocusBackOffset : activeCombat ? 3.85f : 1.62f;
            float yOffset = bossFocus ? CompanionBossFocusYOffset : activeCombat ? 2.22f : 1.72f + Mathf.Sin(Time.time * 4.2f) * .08f;
            var desired = player.transform.position + new Vector3(-facing * backOffset, yOffset, 0);
            companionPet.transform.position = Vector3.Lerp(companionPet.transform.position, desired, dt * (activeCombat ? 3.2f : 5.2f));
            companionPet.transform.localScale = Vector3.one * (bossFocus ? CompanionBossFocusScale : activeCombat ? CompanionCombatScale : .46f);
            companionSprite.sortingOrder = activeCombat ? 0 : 2;
            companionSprite.color = bossFocus ? new Color(1f, 1f, 1f, CompanionBossFocusAlpha) : activeCombat ? new Color(1f, 1f, 1f, CompanionCombatAlpha) : new Color(1f, 1f, 1f, .78f);
            companionSprite.flipX = facing < 0;
            int idleFrame = Mathf.FloorToInt(petAnimTimer * 7f) % 2;
            companionSprite.sprite = companionPetSprites.Length > idleFrame ? companionPetSprites[idleFrame] : companionSprite.sprite;

            if (inputLocked || petAttackTimer > 0 || enemies.Count == 0) return;
            var target = enemies
                .Where(e => !e.Dead && e.Root && Mathf.Abs(e.Root.transform.position.x - player.transform.position.x) < 8.4f)
                .OrderBy(e => Vector2.Distance(e.Root.transform.position, player.transform.position))
                .FirstOrDefault();
            if (target == null) return;
            petAttackTimer = 2.25f;
            companionSprite.sprite = companionPetSprites.Length > 4 ? companionPetSprites[4] : companionSprite.sprite;
            var dir = ((Vector2)target.Root.transform.position + Vector2.up * .45f - (Vector2)companionPet.transform.position).normalized;
            Vector2 sparkSize = bossFocus ? new Vector2(.18f, .046f) : new Vector2(.24f, .064f);
            float sparkAlpha = bossFocus ? CompanionBossFocusSparkAlpha : .12f;
            float sparkRadius = bossFocus ? CompanionBossFocusSparkRadius : .28f;
            SpawnCompanionCastCue(companionPet.transform.position, dir, bossFocus);
            var fx = SpriteObj("CompanionSpark_NoOcclude", fxRoot, companionPetSprites.Length > 5 ? companionPetSprites[5] : CombatVfxSprite(1), companionPet.transform.position, sparkSize, new Color(.78f, .98f, 1f, sparkAlpha), 5);
            if (dir.x < 0) fx.transform.localScale = new Vector3(-Mathf.Abs(fx.transform.localScale.x), fx.transform.localScale.y, 1);
            hitEffects.Add(new HitFx { Root = fx, Renderer = fx.GetComponent<SpriteRenderer>(), Velocity = dir * 7.5f, Damage = 24f * attackMultiplier, Life = 1.4f, Radius = sparkRadius, ImpactVfxIndex = 4, Tier = HitTier.Skill, PlayerOwned = true, Piercing = false });
        }

        private void SpawnCompanionCastCue(Vector3 origin, Vector2 dir, bool bossFocus)
        {
            if (!fxRoot) return;
            float alphaScale = bossFocus ? .55f : 1f;
            Vector2 safeDir = dir.sqrMagnitude > .001f ? dir.normalized : Vector2.right * facing;
            float angle = Mathf.Atan2(safeDir.y, safeDir.x) * Mathf.Rad2Deg;
            var hand = SpawnTimedSprite("CompanionCastHandTick_NoOcclude_NoYellowPlate", CombatVfxSprite(0), origin + (Vector3)(safeDir * .16f), bossFocus ? new Vector2(.070f, .006f) : new Vector2(.095f, .008f), new Color(.78f, .98f, 1f, .075f * alphaScale), 5, .075f);
            if (hand) hand.transform.localRotation = Quaternion.Euler(0f, 0f, angle);
            var aim = SpawnTimedSprite("CompanionCastAimNeedle_NoOcclude_NoYellowPlate", CombatVfxSprite(0), origin + (Vector3)(safeDir * .28f) + Vector3.down * .020f, bossFocus ? new Vector2(.12f, .004f) : new Vector2(.18f, .005f), new Color(.86f, 1f, 1f, .052f * alphaScale), 5, .070f);
            if (aim) aim.transform.localRotation = Quaternion.Euler(0f, 0f, angle);
            SpawnTimedSprite("CompanionCastBackFlicker_NoOcclude_NoYellowPlate", CombatVfxSprite(0), origin - (Vector3)(safeDir * .10f), bossFocus ? new Vector2(.045f, .004f) : new Vector2(.060f, .005f), new Color(.72f, .96f, 1f, .040f * alphaScale), 4, .060f);
        }

        private IEnumerator BossAttack(Fighter boss, int dir, int attackToken)
        {
            int pattern = rng.Next(boss.PhaseTwo ? 3 : 2);
            if (pattern == 0)
            {
                SetBossAttackCue("巨拳砸地：离开红框，砸地后反击", 1.25f);
                ShowThreatAlert("Boss 巨拳砸地", "离开斜纹地面框，砸地收招后贴身输出", 1.05f, C("#FF6B5A"));
                PlaySfx(sfxBossWarn, .72f);
                SetEnemySprite(boss, 20);
                SpawnEnemyIntent(boss.Root.transform.position, "!");
                SpawnBossAttackReadabilityMarker(boss, "砸地前摇", C("#FF7A5A"), .55f);
                var warn = RectObj("BossGroundPoundWarn_NoYellowPlate", fxRoot, (Vector2)boss.Root.transform.position + new Vector2(dir * 1.9f, -.45f), new Vector2(3.85f, .082f), new Color(1f, .10f, .08f, .076f), 8);
                AddDangerPattern(warn, DangerPatternKind.Stripes, new Color(1f, .34f, .30f, .032f), 5);
                var warnCenterLine = RectObj("BossGroundPoundWarnCenterLine_NoYellowPlate", fxRoot, warn.transform.position, new Vector2(3.92f, .020f), new Color(1f, .34f, .30f, .20f), 10);
                var warnFrontTick = RectObj("BossGroundPoundWarnFrontTick_NoYellowPlate", fxRoot, warn.transform.position + Vector3.right * dir * 2.02f, new Vector2(.095f, .064f), new Color(1f, .40f, .34f, .22f), 11);
                var warnBackTick = RectObj("BossGroundPoundWarnBackTick_NoYellowPlate", fxRoot, warn.transform.position - Vector3.right * dir * 1.90f, new Vector2(.076f, .052f), new Color(1f, .40f, .34f, .15f), 10);
                var arrow = RectObj("BossSlamDirectionArrow_NoYellowPlate", fxRoot, (Vector2)boss.Root.transform.position + new Vector2(dir * 1.04f, .08f), new Vector2(.70f, .024f), new Color(1f, .42f, .34f, .13f), 9);
                arrow.transform.localScale = new Vector3(Mathf.Abs(arrow.transform.localScale.x) * dir, arrow.transform.localScale.y, 1f);
                Destroy(arrow, .55f);
                SpawnDangerCountdown("BossSlamCountdown", "砸地", warn.transform.position + Vector3.up * .82f, .55f, C("#FF8A6A"), boss, attackToken);
                yield return new WaitForSeconds(.55f);
                if (EnemyAttackInterrupted(boss, attackToken))
                {
                    DestroyBossWarns(warn, warnCenterLine, warnFrontTick, warnBackTick);
                    ApplyInterruptedEnemyAttackRecovery(boss);
                    yield break;
                }
                SetEnemySprite(boss, 21);
                SpawnTimedSprite("BossGroundPoundImpactLine_NoYellowPlate", CombatVfxSprite(0), warn.transform.position + Vector3.up * .18f, new Vector2(3.12f, .058f), new Color(1f, .92f, .88f, .40f), 11, .15f);
                SpawnTimedSprite("BossGroundPoundImpactEdge_NoYellowPlate", CombatVfxSprite(0), warn.transform.position + Vector3.right * dir * .66f + Vector3.up * .30f, new Vector2(1.08f, .026f), new Color(.96f, 1f, 1f, .30f), 12, .12f);
                SpawnTimedSprite("BossGroundPoundDustTick_NoYellowPlate", CombatVfxSprite(0), warn.transform.position + Vector3.down * .02f, new Vector2(1.62f, .034f), new Color(1f, .48f, .38f, .24f), 9, .13f);
                ShakeCamera(.040f, .13f);
                if (Mathf.Abs(player.transform.position.x - warn.transform.position.x) < 2.0f && Mathf.Abs(player.transform.position.y - warn.transform.position.y) < 1.6f)
                    DamagePlayer(boss.Damage + 10, "Boss 砸地", warn.transform.position);
                DestroyBossWarns(warn, warnCenterLine, warnFrontTick, warnBackTick);
                SpawnBossCounterWindowCue(boss, "砸地收招", C("#9FF8FF"), .62f);
            }
            else if (pattern == 1)
            {
                SetBossAttackCue("旋转激光：跳过射线，收束后反击", 1.15f);
                ShowThreatAlert("Boss 旋转激光", "跳过射线或贴近缝隙，收束后用技能", 1.0f, C("#FF7777"));
                PlaySfx(sfxBossWarn, .68f);
                SetEnemySprite(boss, 22);
                SpawnEnemyIntent(boss.Root.transform.position, "!!");
                SpawnBossAttackReadabilityMarker(boss, "激光前摇", C("#FF7777"), .45f);
                var laser = RectObj("BossLaserWarn_NoYellowPlate", fxRoot, (Vector2)boss.Root.transform.position + new Vector2(dir * 2.9f, .45f), new Vector2(5.95f, .066f), new Color(1f, .10f, .10f, .070f), 8);
                AddDangerPattern(laser, DangerPatternKind.Stripes, new Color(1f, .34f, .30f, .027f), 7);
                var laserCenterLine = RectObj("BossLaserWarnCenterLine_NoYellowPlate", fxRoot, laser.transform.position, new Vector2(6.04f, .018f), new Color(1f, .34f, .30f, .19f), 10);
                var laserExitTick = RectObj("BossLaserWarnExitTick_NoYellowPlate", fxRoot, laser.transform.position + Vector3.right * dir * 3.06f, new Vector2(.082f, .060f), new Color(1f, .38f, .34f, .20f), 11);
                SpawnTimedSprite("BossLaserJumpHintNeedle_NoTexturePlate", CombatVfxSprite(0), laser.transform.position + Vector3.up * .78f, new Vector2(.42f, .022f), new Color(1f, .62f, .58f, .18f), 12, .16f);
                var jumpHint = WorldText("BossLaserJumpHint", fxRoot, "跳", laser.transform.position + Vector3.up * .96f, 20, 32);
                jumpHint.color = C("#FFD6D6");
                Destroy(jumpHint.gameObject, .48f);
                SpawnDangerCountdown("BossLaserCountdown", "激光", laser.transform.position + Vector3.up * .52f, .45f, C("#FF7777"), boss, attackToken);
                yield return new WaitForSeconds(.45f);
                if (EnemyAttackInterrupted(boss, attackToken))
                {
                    DestroyBossWarns(laser, laserCenterLine, laserExitTick);
                    ApplyInterruptedEnemyAttackRecovery(boss);
                    yield break;
                }
                var beam = RectObj("BossLaserBeam_NoTexturePlate", fxRoot, laser.transform.position, new Vector2(6.35f, .24f), new Color(.46f, .92f, 1f, .22f), 9);
                RectObj("BossLaserBeamWhiteCore_NoTexturePlate", beam.transform, Vector2.zero, new Vector2(6.28f, .050f), new Color(.94f, 1f, 1f, .34f), 10);
                Destroy(beam, .28f);
                ShakeCamera(.026f, .10f);
                if (Mathf.Abs(player.transform.position.x - laser.transform.position.x) < 3.2f && Mathf.Abs(player.transform.position.y - laser.transform.position.y) < .85f)
                    DamagePlayer(boss.Damage + 6, "Boss 激光", laser.transform.position);
                DestroyBossWarns(laser, laserCenterLine, laserExitTick);
                SpawnBossCounterWindowCue(boss, "激光收束", C("#9FF8FF"), .58f);
            }
            else
            {
                if (EnemyAttackInterrupted(boss, attackToken))
                {
                    ApplyInterruptedEnemyAttackRecovery(boss);
                    yield break;
                }
                SetBossAttackCue("雷阵召唤：看十字落点，结束后反击", 1.35f);
                ShowThreatAlert("Boss 雷阵召唤", "连续看十字落点，保留闪避等雷阵结束", 1.15f, C("#FF8A6A"));
                PlaySfx(sfxBossWarn, .80f);
                yield return BossThunderField(boss, attackToken);
            }
            if (boss != null && !boss.Dead)
            {
                boss.Attacking = false;
                SetEnemySprite(boss, EnemyIdleSpriteIndex(boss.Kind));
            }
        }

        private void DestroyBossWarns(params GameObject[] warns)
        {
            foreach (var warn in warns)
            {
                if (warn) Destroy(warn);
            }
        }

        private void SetBossAttackCue(string value, float duration)
        {
            bossAttackCue = value;
            bossAttackCueTimer = Mathf.Max(bossAttackCueTimer, duration);
        }

        private void ShowThreatAlert(string label, string advice, float duration, Color color)
        {
            threatAlertLabel = label;
            threatAlertAdvice = advice;
            threatAlertColor = color;
            threatAlertTimer = Mathf.Max(threatAlertTimer, duration);
        }

        private void SpawnBossAttackReadabilityMarker(Fighter boss, string label, Color color, float duration)
        {
            if (boss == null || boss.Dead || !boss.Root || !fxRoot) return;
            Vector2 pos = boss.Root.transform.position;
            SpawnTimedSprite("BossAttackReadabilityNeedleLine_NoTexturePlate", CombatVfxSprite(0), pos + new Vector2(0, 2.30f), new Vector2(.72f, .026f), new Color(color.r, color.g, color.b, .34f), 13, Mathf.Min(duration, .30f));
            SpawnTimedSprite("BossAttackReadabilityFootLine_NoTexturePlate", CombatVfxSprite(0), pos + new Vector2(0, -.54f), new Vector2(1.18f, .016f), new Color(color.r, color.g, color.b, .075f), 7, Mathf.Min(duration, .22f));
            var text = WorldText("BossAttackReadabilityMarker", fxRoot, ShortBossAttackReadabilityLabel(label), pos + new Vector2(0, 2.46f), 20, 36);
            text.color = new Color(color.r, color.g, color.b, .70f);
            AnimateFloatingWorldText(text, new Vector2(0, .08f), Mathf.Min(duration, .30f), 1.04f);
        }

        private static string ShortBossAttackReadabilityLabel(string label)
        {
            if (string.IsNullOrEmpty(label)) return "前摇";
            if (label.Contains("砸地")) return "砸地";
            if (label.Contains("激光")) return "激光";
            if (label.Contains("雷阵")) return "雷阵";
            return label.Length > 2 ? label.Substring(0, 2) : label;
        }

        private void SpawnBossCounterWindowCue(Fighter boss, string label, Color color, float duration)
        {
            if (boss == null || boss.Dead || !boss.Root || !fxRoot) return;
            Vector2 pos = boss.Root.transform.position;
            bossAttackCue = $"反击窗口：{label}";
            bossAttackCueTimer = Mathf.Max(bossAttackCueTimer, duration);
            var text = WorldText("BossCounterWindowCue", fxRoot, "反击", pos + new Vector2(0, 2.20f), 24, 38);
            text.color = new Color(color.r, color.g, color.b, .74f);
            AnimateFloatingWorldText(text, new Vector2(0, .14f), Mathf.Min(duration, .46f), 1.04f);
            SpawnTimedSprite("BossCounterWindowRing_NoTexturePlate", CombatVfxSprite(0), pos + new Vector2(0, -.42f), new Vector2(1.34f, .018f), new Color(color.r, color.g, color.b, .085f), 9, Mathf.Min(duration, .28f));
            SpawnTimedSprite("BossCounterWindowCore_NoTexturePlate", CombatVfxSprite(0), pos + new Vector2(0, .62f), new Vector2(.92f, .026f), new Color(color.r, color.g, color.b, .20f), 8, Mathf.Min(duration, .22f));
            SpawnBossCounterAttackGuide(boss, color, duration);
        }

        private void SpawnBossCounterAttackGuide(Fighter boss, Color color, float duration)
        {
            if (boss == null || boss.Dead || !boss.Root || !fxRoot || !player) return;
            Vector2 bossPos = boss.Root.transform.position;
            Vector2 playerPos = player.transform.position;
            float dirToBoss = Mathf.Sign(bossPos.x - playerPos.x);
            if (Mathf.Abs(dirToBoss) < .05f) dirToBoss = facing;
            Vector2 arrowPos = playerPos + new Vector2(dirToBoss * 1.34f, .48f);
            float alphaScale = effectsIntensity > .75f ? 1f : .70f;
            var arrow = SpawnTimedSprite("BossCounterWindowAttackArrow_NoTexturePlate", CombatVfxSprite(0), arrowPos, new Vector2(1.18f, .028f), new Color(color.r, color.g, color.b, .24f * alphaScale), 14, Mathf.Min(duration, .34f));
            if (arrow) arrow.transform.localScale = new Vector3(Mathf.Abs(arrow.transform.localScale.x) * dirToBoss, arrow.transform.localScale.y, 1f);
            SpawnTimedSprite("BossCounterWindowAttackPath_NoTexturePlate", CombatVfxSprite(0), playerPos + new Vector2(dirToBoss * .74f, -.50f), new Vector2(1.08f, .022f), new Color(color.r, color.g, color.b, .12f * alphaScale), 5, Mathf.Min(duration, .36f));
            var hint = WorldText("BossCounterWindowDpsHint", fxRoot, "输出", arrowPos + Vector2.up * .30f, 18, 34);
            hint.color = new Color(color.r, color.g, color.b, .68f * alphaScale);
            AnimateFloatingWorldText(hint, new Vector2(dirToBoss * .06f, .12f), Mathf.Min(duration, .36f), 1.04f);
        }

        private void SpawnBossPhaseTransition(Fighter boss)
        {
            if (boss == null || !boss.Root || !fxRoot) return;
            Vector3 pos = boss.Root.transform.position;
            SpawnTimedSprite("BossPhaseCore_NoYellowPlate", CombatVfxSprite(0), pos + Vector3.up * 1.05f, new Vector2(1.72f, .040f), new Color(1f, .42f, .36f, .34f), 12, .18f);
            SpawnTimedSprite("BossPhaseLine_NoYellowPlate", CombatVfxSprite(0), pos + Vector3.up * .62f, new Vector2(2.10f, .030f), new Color(.96f, 1f, 1f, .22f), 13, .16f);
            var text = WorldText("BossPhaseText", fxRoot, "碎甲狂暴\n雷阵加入", (Vector2)pos + new Vector2(0, 2.75f), 34, 38);
            text.color = C("#FFB6A8");
            Destroy(text.gameObject, 1.2f);
            TriggerCombatFlash(.16f, .18f);
            ShakeCamera(.08f, .26f);
            HapticPulse();
        }

        private IEnumerator ArcherAttack(Fighter e, int dir, int attackToken)
        {
            if (e == null || e.Dead || !e.Root) yield break;
            SetEnemySprite(e, 10);
            SpawnEnemyIntent(e.Root.transform.position, "瞄", false);
            Color warnColor = EnemyIntentWarnColor(e);
            SpawnMinorEnemyWindupPoseLockCue(e, dir, true, warnColor);
            var aim = RectObj("ArcherAimThinWarnLine_NoYellowPlate", fxRoot, (Vector2)e.Root.transform.position + new Vector2(dir * 2.35f, .35f), new Vector2(2.45f, .0025f), new Color(warnColor.r, warnColor.g, warnColor.b, .005f), 8);
            AddDangerPattern(aim, DangerPatternKind.Stripes, new Color(warnColor.r, warnColor.g, warnColor.b, .0012f), 6);
            var aimEdge = RectObj("ArcherAimEdgeTick_NoYellowPlate", fxRoot, (Vector2)e.Root.transform.position + new Vector2(dir * 3.68f, .35f), new Vector2(.026f, .004f), new Color(warnColor.r, warnColor.g, warnColor.b, .014f), 9);
            var tip = RectObj("ArcherAimTipNoPlateTick", fxRoot, (Vector2)e.Root.transform.position + new Vector2(dir * 3.74f, .35f), new Vector2(.008f, .008f), new Color(warnColor.r, warnColor.g, warnColor.b, .012f), 9);
            var aimBodyTick = RectObj("ArcherAimMidTick_NoTexturePlate", fxRoot, (Vector2)e.Root.transform.position + new Vector2(dir * 2.18f, .35f), new Vector2(.045f, .004f), new Color(warnColor.r, warnColor.g, warnColor.b, .018f), 9);
            var aimMuzzleTick = RectObj("ArcherAimMuzzleTick_NoTexturePlate", fxRoot, (Vector2)e.Root.transform.position + new Vector2(dir * .50f, .35f), new Vector2(.034f, .004f), new Color(.96f, 1f, 1f, .018f), 9);
            SpawnDangerCountdown("ArcherShotCountdown", "射击", aim.transform.position + Vector3.up * .48f, .28f, warnColor, e, attackToken);
            yield return new WaitForSeconds(.28f);
            bool interrupted = EnemyAttackInterrupted(e, attackToken);
            if (!interrupted)
                SpawnProjectile(e.Root.transform.position + Vector3.up * .35f, new Vector2(dir * 5.5f, 0), e.Damage, false, warnColor, 6, -1, .48f, "远程射击");
            if (aim) Destroy(aim);
            if (aimEdge) Destroy(aimEdge);
            if (tip) Destroy(tip);
            if (aimBodyTick) Destroy(aimBodyTick);
            if (aimMuzzleTick) Destroy(aimMuzzleTick);
            if (interrupted)
            {
                ApplyInterruptedEnemyAttackRecovery(e);
                yield break;
            }
            if (e != null && !e.Dead)
            {
                e.Attacking = false;
                SetEnemySprite(e, EnemyIdleSpriteIndex(e.Kind));
            }
        }

        private void SpawnEnemyIntent(Vector3 position, string label, bool showText = true)
        {
            if (!showText)
            {
                var needle = SpawnTimedRect("MinorEnemyIntentNeedleLine_NoTexturePlate", position + Vector3.up * 1.34f, new Vector2(.14f, .006f), new Color(1f, .34f, .46f, .060f), 12, .075f);
                if (needle) needle.transform.localScale = new Vector3(Mathf.Abs(needle.transform.localScale.x), needle.transform.localScale.y, 1f);
                return;
            }
            SpawnTimedRect("EnemyIntentTextNeedleLine_NoTexturePlate", position + Vector3.up * 1.34f, new Vector2(.36f, .028f), new Color(1f, .34f, .46f, .28f), 12, .16f);
            SpawnTimedRect("EnemyIntentTextFootTick_NoTexturePlate", position + Vector3.up * 1.18f, new Vector2(.20f, .022f), new Color(.96f, 1f, 1f, .24f), 12, .14f);
            var text = WorldText("EnemyIntentText", fxRoot, label, position + Vector3.up * 1.36f, 28, 32);
            text.color = new Color(1f, .34f, .46f, .78f);
            Destroy(text.gameObject, .34f);
        }

        private void SpawnDangerCountdown(string name, string label, Vector3 position, float duration, Color color, Fighter trackedAttack = null, int attackToken = -1)
        {
            if (!fxRoot || duration <= 0) return;
            if (MinorEnemyDangerCountdown(name))
            {
                StartCoroutine(MinorEnemyDangerCountdownRoutine(name, position, duration, color, trackedAttack, attackToken));
                return;
            }
            StartCoroutine(DangerCountdownRoutine(name, label, position, duration, color, trackedAttack, attackToken));
        }

        private static bool MinorEnemyDangerCountdown(string name)
        {
            return name.StartsWith("ArcherShot", StringComparison.Ordinal) || name.StartsWith("EnemyMelee", StringComparison.Ordinal);
        }

        private IEnumerator MinorEnemyDangerCountdownRoutine(string name, Vector3 position, float duration, Color color, Fighter trackedAttack = null, int attackToken = -1)
        {
            var bar = RectObj(name + "NoTexturePlateLine_MicroNeedle", fxRoot, position, new Vector2(.090f, .0025f), new Color(color.r, color.g, color.b, .010f), 9);
            var tick = RectObj(name + "NoTexturePlateTick_MicroNeedle", bar.transform, new Vector2(.045f, 0f), new Vector2(.006f, .0035f), new Color(.96f, 1f, 1f, .018f), 10);
            float remaining = duration;
            while (remaining > 0f)
            {
                if (trackedAttack != null && attackToken >= 0 && EnemyAttackInterrupted(trackedAttack, attackToken)) break;
                if (!bar) yield break;
                float t = Mathf.Clamp01(remaining / duration);
                bar.transform.localScale = new Vector3(Mathf.Lerp(.18f, 1f, t), 1f, 1f);
                if (tick) tick.transform.localPosition = new Vector3(Mathf.Lerp(-.052f, .055f, t), 0f, 0f);
                remaining -= Time.deltaTime;
                yield return null;
            }
            if (tick) Destroy(tick);
            if (bar) Destroy(bar);
        }

        private IEnumerator DangerCountdownRoutine(string name, string label, Vector3 position, float duration, Color color, Fighter trackedAttack = null, int attackToken = -1)
        {
            var bar = RectObj(name + "BossNoPlateLine", fxRoot, position, new Vector2(.86f, .034f), new Color(color.r, color.g, color.b, .46f), 11);
            var tick = RectObj(name + "BossNoPlateTick", bar.transform, new Vector2(.43f, 0f), new Vector2(.090f, .050f), new Color(.96f, 1f, 1f, .58f), 12);
            var text = WorldText(name + "BossNoPlateNumber", fxRoot, "", (Vector2)position + new Vector2(0, .22f), 18, 33);
            float remaining = duration;
            while (remaining > 0)
            {
                if (trackedAttack != null && attackToken >= 0 && EnemyAttackInterrupted(trackedAttack, attackToken)) break;
                if (!bar && !text) yield break;
                float t = Mathf.Clamp01(remaining / duration);
                if (bar) bar.transform.localScale = new Vector3(Mathf.Lerp(.20f, 1f, t), 1f, 1f);
                if (tick) tick.transform.localPosition = new Vector3(Mathf.Lerp(-.39f, .43f, t), 0f, 0f);
                if (text)
                {
                    text.text = remaining.ToString("0.0");
                    text.color = new Color(color.r, color.g, color.b, Mathf.Lerp(.56f, .82f, Mathf.PingPong(Time.time * 5f, 1f)));
                    text.transform.localScale = Vector3.one * Mathf.Lerp(1.04f, 1f, t);
                }
                remaining -= Time.deltaTime;
                yield return null;
            }
            if (tick) Destroy(tick);
            if (bar) Destroy(bar);
            if (text) Destroy(text.gameObject);
        }

        private void SpawnMinorEnemyWindupPoseLockCue(Fighter e, int dir, bool ranged, Color warnColor)
        {
            if (e == null || e.Dead || !e.Root || !fxRoot) return;
            Vector3 pos = e.Root.transform.position;
            float alphaScale = effectsIntensity > .75f ? 1f : .62f;
            SpawnTimedRect(ranged ? "EnemyWindupPoseLockAimNeedle_NoTexturePlate" : "EnemyWindupPoseLockMeleeNeedle_NoTexturePlate",
                pos + new Vector3(dir * (ranged ? .50f : .34f), ranged ? .36f : .18f, 0f),
                ranged ? new Vector2(.12f, .004f) : new Vector2(.10f, .004f),
                new Color(warnColor.r, warnColor.g, warnColor.b, .020f * alphaScale), 9, ranged ? .18f : .14f);
            SpawnTimedRect("EnemyWindupPoseLockFootBrace_NoTexturePlate",
                pos + new Vector3(-dir * .10f, -.48f, 0f),
                new Vector2(ranged ? .16f : .13f, .004f),
                new Color(.96f, 1f, 1f, .018f * alphaScale), 8, ranged ? .18f : .14f);
            SpawnTimedRect("EnemyWindupPoseLockBodyPin_NoTexturePlate",
                pos + new Vector3(0f, ranged ? .22f : .12f, 0f),
                new Vector2(.010f, ranged ? .13f : .10f),
                new Color(warnColor.r, warnColor.g, warnColor.b, .014f * alphaScale), 8, ranged ? .16f : .12f);
        }

        private IEnumerator BossThunderField(Fighter boss, int attackToken = -1)
        {
            SetEnemySprite(boss, 23);
            SpawnBossAttackReadabilityMarker(boss, "雷阵三连", C("#FF8A6A"), .55f);
            for (int i = 0; i < 3; i++)
            {
                if (attackToken >= 0 && EnemyAttackInterrupted(boss, attackToken))
                {
                    ApplyInterruptedEnemyAttackRecovery(boss);
                    yield break;
                }
                var p = player.transform.position;
                var warn = RectObj("BossThunderThinCrosshairWarn_NoYellowPlate", fxRoot, new Vector2(p.x + UnityEngine.Random.Range(-1.6f, 1.6f), GroundY + .2f), new Vector2(.72f, .026f), new Color(1f, .20f, .10f, .052f), 8);
                AddDangerPattern(warn, DangerPatternKind.Crosshair, new Color(1f, .38f, .32f, .055f), 4);
                SpawnTimedSprite("BossThunderLandingEdgeTick_NoYellowPlate", CombatVfxSprite(0), warn.transform.position + Vector3.right * .34f, new Vector2(.10f, .020f), new Color(1f, .42f, .34f, .14f), 12, .28f);
                SpawnDangerCountdown("BossThunderCountdown", "雷击", warn.transform.position + Vector3.up * .72f, .38f, C("#FF8A6A"), boss, attackToken);
                yield return new WaitForSeconds(.38f);
                if (attackToken >= 0 && EnemyAttackInterrupted(boss, attackToken))
                {
                    if (warn) Destroy(warn);
                    ApplyInterruptedEnemyAttackRecovery(boss);
                    yield break;
                }
                SpawnTimedSprite("BossThunderStrikeSpine_NoYellowPlate", CombatVfxSprite(0), warn.transform.position + Vector3.up * 1.18f, new Vector2(.050f, 2.35f), new Color(.88f, .98f, 1f, .54f), 11, .16f);
                SpawnTimedSprite("BossThunderStrikeContact_NoYellowPlate", CombatVfxSprite(0), warn.transform.position + Vector3.up * .08f, new Vector2(.78f, .030f), new Color(.72f, .96f, 1f, .30f), 10, .13f);
                if (Vector2.Distance(player.transform.position, warn.transform.position) < 1.15f)
                    DamagePlayer(boss.Damage + 4, "Boss 雷阵", warn.transform.position);
                if (warn) Destroy(warn);
                yield return new WaitForSeconds(.12f);
            }
            SpawnBossCounterWindowCue(boss, "雷阵结束", C("#9FF8FF"), .68f);
        }

        private IEnumerator EnemyMelee(Fighter e, int dir, int attackToken)
        {
            if (e == null || e.Dead || !e.Root || !player) yield break;
            SetEnemySprite(e, e.Kind == EnemyKind.Slime ? 16 : e.Kind == EnemyKind.Mushroom ? 4 : EnemyIdleSpriteIndex(e.Kind));
            SpawnEnemyIntent(e.Root.transform.position, "!", e.Elite);
            Color warnColor = EnemyIntentWarnColor(e);
            SpawnMinorEnemyWindupPoseLockCue(e, dir, false, warnColor);
            var groundWarn = RectObj("EnemyMeleeThinGroundWarn_NoYellowPlate", fxRoot, (Vector2)e.Root.transform.position + new Vector2(dir * .68f, -.46f), new Vector2(.18f, .0025f), new Color(warnColor.r, warnColor.g, warnColor.b, .0045f), 7);
            AddDangerPattern(groundWarn, DangerPatternKind.Stripes, new Color(warnColor.r, warnColor.g, warnColor.b, .0012f), 3);
            var footMark = RectObj("EnemyMeleeFootMark_NoYellowPlate", fxRoot, (Vector2)e.Root.transform.position + new Vector2(dir * .42f, -.42f), new Vector2(.032f, .0035f), new Color(warnColor.r, warnColor.g, warnColor.b, .010f), 7);
            var warn = RectObj("EnemyMeleeFrontEdgeWarn_NoYellowPlate", fxRoot, (Vector2)e.Root.transform.position + new Vector2(dir * .70f, .08f), new Vector2(.10f, .004f), new Color(warnColor.r, warnColor.g, warnColor.b, .012f), 8);
            warn.transform.localScale = new Vector3(warn.transform.localScale.x * dir, warn.transform.localScale.y, 1);
            var heelTick = RectObj("EnemyMeleeWindupHeelTick_NoTexturePlate", fxRoot, (Vector2)e.Root.transform.position + new Vector2(-dir * .18f, -.48f), new Vector2(.040f, .004f), new Color(.96f, 1f, 1f, .016f), 8);
            var frontNeedle = RectObj("EnemyMeleeFrontNeedleTick_NoTexturePlate", fxRoot, (Vector2)e.Root.transform.position + new Vector2(dir * .88f, -.38f), new Vector2(.055f, .004f), new Color(warnColor.r, warnColor.g, warnColor.b, .018f), 8);
            Vector3 countdownPos = warn ? warn.transform.position + Vector3.up * .72f : e.Root.transform.position + Vector3.up * .72f;
            SpawnDangerCountdown("EnemyMeleeCountdown", "近战", countdownPos, .22f, warnColor, e, attackToken);
            yield return new WaitForSeconds(.22f);
            if (EnemyAttackInterrupted(e, attackToken) || !player)
            {
                DestroyEnemyMeleeWarns(warn, groundWarn, footMark, heelTick, frontNeedle);
                ApplyInterruptedEnemyAttackRecovery(e);
                yield break;
            }
            if (Mathf.Abs(player.transform.position.x - e.Root.transform.position.x) < e.AttackRange + .35f && Mathf.Abs(player.transform.position.y - e.Root.transform.position.y) < 1.6f)
                DamagePlayer(e.Damage, e.Elite ? "精英近战" : "近战突袭", e.Root.transform.position);
            DestroyEnemyMeleeWarns(warn, groundWarn, footMark, heelTick, frontNeedle);
            if (!e.Dead)
            {
                e.Attacking = false;
                SetEnemySprite(e, EnemyIdleSpriteIndex(e.Kind));
            }
        }

        private static bool EnemyAttackInterrupted(Fighter e, int attackToken)
        {
            return EnemyActionSuppressed(e) || e.AttackToken != attackToken;
        }

        private static bool CanEnemyStartAttack(Fighter e)
        {
            return !EnemyActionSuppressed(e) && e.AttackTimer <= 0f && !e.Attacking;
        }

        private static bool EnemyActionSuppressed(Fighter e)
        {
            return e == null || e.Dead || !e.Root || e.HitStun > 0f || e.HitReactTimer > 0f || e.FrozenTimer > 0f || e.AttackLockTimer > 0f;
        }

        private void ApplyInterruptedEnemyAttackRecovery(Fighter e)
        {
            if (e == null || e.Dead) return;
            e.Attacking = false;
            float recovery = e.Boss ? .20f : e.HitStun > 0f ? .68f : .36f;
            e.AttackTimer = Mathf.Max(e.AttackTimer, recovery);
            e.AttackLockTimer = Mathf.Max(e.AttackLockTimer, recovery);
            if (e.IntentText)
            {
                e.IntentText.text = "";
                e.IntentText.color = Color.clear;
            }
            if (e.HitStun <= 0f && e.Root)
                SetEnemySprite(e, EnemyIdleSpriteIndex(e.Kind));
        }

        private static void DestroyEnemyMeleeWarns(params GameObject[] warns)
        {
            foreach (var warn in warns)
            {
                if (warn) Destroy(warn);
            }
        }

        private void UpdateHitEffects(float dt)
        {
            foreach (var fx in hitEffects.ToArray())
            {
                fx.Life -= dt;
                if (!fx.Root || fx.Life <= 0)
                {
                    if (fx.Root) Destroy(fx.Root);
                    hitEffects.Remove(fx);
                    continue;
                }
                Vector3 fxPosition = fx.Root.transform.position + (Vector3)(fx.Velocity * dt);
                fx.Root.transform.position = fxPosition;
                if (fx.PlayerOwned)
                {
                    bool consumed = false;
                    foreach (var vessel in runeVessels.ToArray())
                    {
                        if (vessel.Broken || !vessel.Root) continue;
                        Vector3 vesselPosition = vessel.Root.transform.position;
                        if (Vector2.Distance(fxPosition, vesselPosition) < fx.Radius + .35f)
                        {
                            DamageRuneVessel(vessel, fx.Damage, fx.Velocity.normalized, fx.Tier, fx.SourceSkill);
                            if (!fx.Piercing)
                            {
                                if (fx.Root) Destroy(fx.Root);
                                hitEffects.Remove(fx);
                                consumed = true;
                            }
                            break;
                        }
                    }
                    if (consumed) continue;
                    foreach (var e in enemies.ToArray())
                    {
                        if (e == null || e.Dead || !e.Root) continue;
                        Vector3 enemyPosition = e.Root.transform.position;
                        bool boss = e.Boss;
                        if (Vector2.Distance(fxPosition, enemyPosition) < fx.Radius)
                        {
                            DamageEnemy(e, fx.Damage, fx.Velocity.normalized, fx.Tier, fx.SourceSkill);
                            if (fx.SourceSkill.HasValue)
                                SpawnSkillSpecificImpact(fx.SourceSkill.Value, enemyPosition + Vector3.up * (boss ? 1.0f : .58f), fx.Velocity.normalized, boss);
                            if (fx.ImpactVfxIndex >= 0)
                            {
                                float impactDir = Mathf.Sign(Mathf.Abs(fx.Velocity.x) < .05f ? facing : fx.Velocity.x);
                                var impactLine = SpawnTimedSprite("SkillImpactCleanLine_ThinNoBlur", CombatVfxSprite(0), enemyPosition + Vector3.up * .42f, new Vector2(.86f, .028f), new Color(.92f, 1f, 1f, .44f), 13, .070f);
                                if (impactLine) impactLine.transform.localScale = new Vector3(Mathf.Abs(impactLine.transform.localScale.x) * impactDir, impactLine.transform.localScale.y, 1f);
                                var impactEdge = SpawnTimedSprite("SkillImpactForwardEdgeTick_ThinNoBlur", CombatVfxSprite(0), enemyPosition + Vector3.up * .52f + Vector3.right * impactDir * .34f, new Vector2(.18f, .032f), new Color(.96f, 1f, 1f, .58f), 14, .062f);
                                if (impactEdge) impactEdge.transform.localScale = new Vector3(Mathf.Abs(impactEdge.transform.localScale.x) * impactDir, impactEdge.transform.localScale.y, 1f);
                            }
                            if (!fx.Piercing) { if (fx.Root) Destroy(fx.Root); hitEffects.Remove(fx); break; }
                        }
                    }
                }
                else if (player && Vector2.Distance(fxPosition, player.transform.position) < .7f)
                {
                    DamagePlayer(fx.Damage, string.IsNullOrEmpty(fx.SourceLabel) ? "敌方弹幕" : fx.SourceLabel, fxPosition);
                    if (fx.Root) Destroy(fx.Root);
                    hitEffects.Remove(fx);
                }
            }
        }

        private void DamageEnemy(Fighter e, float amount, Vector2 hitDir, HitTier tier = HitTier.Light, SkillKind? sourceSkill = null)
        {
            e.Hp -= amount;
            ShowHitConfirm(tier, e.Boss);
            PulseHitConfirmButton(tier, e.Boss, sourceSkill);
            comboHits++;
            highestComboThisRun = Mathf.Max(highestComboThisRun, comboHits);
            comboDisplayTimer = 1.4f;
            CheckComboMilestone(tier, e.Boss);
            float tierPower = tier == HitTier.Heavy ? 1.35f : tier == HitTier.Skill ? 1.18f : 1f;
            TriggerHitFrameBeat(tier, e.Boss, e.Root.transform.position + Vector3.up * (e.Boss ? .95f : .55f), sourceSkill);
            PlaySfx(tier == HitTier.Heavy ? sfxHeavyHit : tier == HitTier.Skill ? sfxSkillCast : sfxHit, Mathf.Clamp01((e.Boss ? 1f : .78f) * tierPower));
            e.HitStun = Mathf.Max(e.HitStun, EnemyHitStunDuration(e, tier));
            InterruptEnemyAttackOnHit(e, tier);
            e.Knockback = hitDir.normalized * EnemyKnockbackForce(e, tier, tierPower);
            if (tier == HitTier.Heavy) ApplyHeavyBreakPush(e, hitDir);
            if (tier != HitTier.Light) SpawnEnemyKnockbackTravelCue(e, hitDir, tier);
            e.HpPulse = 1f;
            e.HpVisibleTimer = e.Boss ? .20f : e.Elite ? 1.65f : tier == HitTier.Light ? .48f : .72f;
            TriggerEnemyHitReaction(e, tier, hitDir);
            if (e.HpFill) e.HpFill.rectTransform.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, 110 * Mathf.Clamp01(e.Hp / e.MaxHp));
            StartCoroutine(SpriteFlash(e.Sprite, Color.white));
            SpawnHitImpact(e.Root.transform.position + Vector3.up * (e.Boss ? 1.05f : .58f), hitDir, amount, e.Boss, tier);
            SpawnHitTierConfirmation(e.Root.transform.position + Vector3.up * (e.Boss ? .78f : .36f), hitDir, e.Boss, tier);
            ShowMergedDamageText(e, amount, tier, hitDir);
            if (tier == HitTier.Heavy) HapticPulse(HapticTier.Heavy);
            if (e.Hp > 0) return;
            e.Dead = true;
            ClearFloatingDamageText(e);
            var deathPos = e.Root.transform.position;
            SpawnEnemyDeathBurst(e, deathPos);
            if (e.Boss) SpawnBossDefeatCeremony(deathPos);
            killsThisRun++;
            GrantTrialExp(e.Boss ? 80f : e.Elite ? 42f : 20f, deathPos);
            float coinReward = e.Boss ? 300 : e.Elite ? 95 : 35;
            float fateReward = e.Boss ? 100f : e.Elite ? 32f : 12f;
            SpawnKillRewardConfirmation(e, deathPos, coinReward, fateReward);
            SpawnPickupBurst(PickupKind.Coin, coinReward, deathPos, e.Boss ? 9 : e.Elite ? 5 : 2);
            SpawnPickup(PickupKind.Fate, fateReward, deathPos + Vector3.up * .35f, new Vector2(UnityEngine.Random.Range(-.7f, .7f), 2.0f));
            if (!e.Boss && rng.NextDouble() < (e.Elite ? .45 : .16))
                SpawnPickup(PickupKind.Heal, maxHp * .06f, deathPos + Vector3.up * .25f, new Vector2(UnityEngine.Random.Range(-.6f, .6f), 1.8f));
            if (e.Elite && !shrineAvailable)
            {
                fateEnergy = Mathf.Min(99f, fateEnergy + (RuneSpawnCooldownReady() ? 32f : 18f));
                noticeText.text = "精英能量已收纳：清完本房后再启封";
            }
            int deathSegment = SegmentIndexForX(deathPos.x);
            enemies.Remove(e);
            if (e.Root) Destroy(e.Root);
            if (!e.Boss && deathSegment == currentSegment && RoomBlockingEnemyCount(deathSegment) <= 0)
                SpawnLastEnemyRoomClearCue(deathPos, deathSegment);
        }

        private float TrialLevelRequiredExp()
        {
            return TrialLevelBaseExp + (trialLevel - 1) * TrialLevelStepExp;
        }

        private int TrialExpPercent()
        {
            return Mathf.Clamp(Mathf.FloorToInt(exp / Mathf.Max(1f, TrialLevelRequiredExp()) * 100f), 0, 99);
        }

        private void GrantTrialExp(float amount, Vector3 position)
        {
            exp += Mathf.Max(0f, amount);
            float requirement = TrialLevelRequiredExp();
            while (trialLevel < TrialLevelCap && exp >= requirement)
            {
                exp -= requirement;
                TrialLevelUp(position);
                requirement = TrialLevelRequiredExp();
            }
        }

        private void TrialLevelUp(Vector3 position)
        {
            trialLevel++;
            maxHp += 10f;
            maxMp += 5f;
            hp = Mathf.Min(maxHp, hp + 22f);
            mp = Mathf.Min(maxMp, mp + 16f);
            attackMultiplier += .025f;
            if (noticeText) noticeText.text = $"试炼等级提升：Lv{trialLevel}";
            SpawnTimedSprite("TrialLevelUpFootLine", CombatVfxSprite(0), position + Vector3.down * .34f, new Vector2(1.30f, .052f), new Color(.74f, .96f, 1f, .52f), 10, .34f);
            SpawnTimedSprite("TrialLevelUpCoreTick", CombatVfxSprite(0), position + Vector3.up * .30f, new Vector2(1.12f, .066f), new Color(.72f, .96f, 1f, .44f), 10, .30f);
            var text = WorldText("TrialLevelUpText", fxRoot, $"Lv{trialLevel}  成长", (Vector2)position + new Vector2(0, 1.44f), 26, 34);
            text.color = C("#B8F7FF");
            AnimateFloatingWorldText(text, new Vector2(0, .38f), .54f, 1.10f);
            PlaySfx(sfxRuneReward, .46f);
            HapticPulse(HapticTier.Medium);
        }

        private static float EnemyHitStunDuration(Fighter e, HitTier tier)
        {
            if (e == null) return .18f;
            if (e.Boss) return tier == HitTier.Heavy ? .11f : tier == HitTier.Skill ? .095f : .075f;
            float baseStun = tier == HitTier.Heavy ? 1.02f : tier == HitTier.Skill ? .78f : .58f;
            if (e.Kind == EnemyKind.Archer) baseStun += .12f;
            if (e.Elite) baseStun *= .76f;
            return baseStun;
        }

        private static float EnemyPostHitAttackDelay(Fighter e, HitTier tier)
        {
            if (e == null) return .18f;
            float delay;
            if (e.Boss)
            {
                delay = tier == HitTier.Heavy ? .24f : tier == HitTier.Skill ? .18f : .14f;
            }
            else
            {
                delay = tier == HitTier.Heavy ? 1.32f : tier == HitTier.Skill ? 1.04f : .86f;
                if (e.Kind == EnemyKind.Archer) delay += .20f;
                if (e.Elite) delay *= .82f;
            }
            float recoveryBuffer = e.Boss ? BossPostHitRecoveryAfterStunMin : e.Kind == EnemyKind.Archer ? ArcherPostHitRecoveryAfterStunMin : EnemyPostHitRecoveryAfterStunMin;
            return Mathf.Max(delay, EnemyHitStunDuration(e, tier) + recoveryBuffer);
        }

        private void InterruptEnemyAttackOnHit(Fighter e, HitTier tier)
        {
            if (e == null) return;
            e.Attacking = false;
            e.AttackToken++;
            float lockDuration = EnemyPostHitAttackDelay(e, tier);
            e.AttackTimer = Mathf.Max(e.AttackTimer, lockDuration);
            e.AttackLockTimer = Mathf.Max(e.AttackLockTimer, lockDuration);
            ClearEnemyIntentOnHit(e);
            if (e.Root)
            {
                SpawnTimedSprite("EnemyAttackInterruptedFootTick_NoYellowPlate", CombatVfxSprite(0), e.Root.transform.position + Vector3.down * (e.Boss ? .76f : .48f), e.Boss ? new Vector2(.52f, .014f) : new Vector2(.26f, .008f), new Color(.82f, .96f, 1f, e.Boss ? .055f : .030f), 8, .055f);
                SpawnTimedSprite("EnemyAttackInterruptedPoseBrace_NoYellowPlate", CombatVfxSprite(0), e.Root.transform.position + Vector3.down * (e.Boss ? .58f : .38f) + Vector3.right * .10f, e.Boss ? new Vector2(.74f, .018f) : new Vector2(.34f, .006f), new Color(.72f, .96f, 1f, e.Boss ? .080f : .038f), 9, e.Boss ? .075f : .060f);
                SpawnTimedSprite("EnemyAttackInterruptedStopPin_NoYellowPlate", CombatVfxSprite(0), e.Root.transform.position + Vector3.up * (e.Boss ? .78f : .34f), e.Boss ? new Vector2(.13f, .14f) : new Vector2(.060f, .070f), new Color(.96f, 1f, 1f, e.Boss ? .13f : .070f), 10, e.Boss ? .075f : .060f);
