        }

        private void ClearEnemyIntentOnHit(Fighter e)
        {
            if (e == null) return;
            if (e.IntentText)
            {
                e.IntentText.text = "";
                e.IntentText.color = Color.clear;
            }
            if (e.IntentRing) e.IntentRing.color = Color.clear;
            e.ReadabilitySilhouetteTimer = Mathf.Max(e.ReadabilitySilhouetteTimer, e.Boss ? .10f : .22f);
        }

        private static float EnemyKnockbackForce(Fighter e, HitTier tier, float tierPower)
        {
            if (e == null) return 2.4f;
            if (e.Boss) return 1.0f * tierPower;
            float force = tier == HitTier.Heavy ? 4.85f : tier == HitTier.Skill ? 3.42f : 2.62f;
            if (e.Elite) force *= .86f;
            return force;
        }

        private void ApplyHeavyBreakPush(Fighter e, Vector2 hitDir)
        {
            if (e == null || e.Boss || !e.Root || !fxRoot) return;
            float dir = Mathf.Abs(hitDir.x) < .05f ? facing : Mathf.Sign(hitDir.x);
            e.HitStun = Mathf.Max(e.HitStun, e.Elite ? .38f : .48f);
            e.AttackTimer = Mathf.Max(e.AttackTimer, e.Elite ? .34f : .46f);
            e.Knockback += new Vector2(dir * (e.Elite ? 1.08f : 1.62f), .20f);
            float alphaScale = effectsIntensity > .75f ? 1f : .66f;
            Vector3 foot = e.Root.transform.position + Vector3.down * .50f;
            var pushLine = SpawnTimedSprite("EnemyHeavyBreakPushLine_NoYellowPlate", CombatVfxSprite(0), foot + Vector3.right * dir * .20f, new Vector2(e.Elite ? 1.08f : .86f, .026f), new Color(.74f, .96f, 1f, .32f * alphaScale), 10, .11f);
            if (pushLine) pushLine.transform.localScale = new Vector3(Mathf.Abs(pushLine.transform.localScale.x) * dir, pushLine.transform.localScale.y, 1f);
            SpawnTimedSprite("EnemyHeavyBreakStopPin_NoYellowPlate", CombatVfxSprite(0), foot + Vector3.right * dir * (e.Elite ? .62f : .50f), new Vector2(.11f, .10f), new Color(.96f, 1f, 1f, .38f * alphaScale), 11, .10f);
            SpawnTimedSprite("EnemyHeavyBreakLiftTick_NoYellowPlate", CombatVfxSprite(0), e.Root.transform.position + Vector3.up * .30f + Vector3.right * dir * .18f, new Vector2(.58f, .026f), new Color(.86f, .98f, 1f, .32f * alphaScale), 11, .095f);
        }

        private void SpawnEnemyKnockbackTravelCue(Fighter e, Vector2 hitDir, HitTier tier)
        {
            if (e == null || e.Boss || !e.Root || !fxRoot) return;
            float dir = Mathf.Abs(hitDir.x) < .05f ? facing : Mathf.Sign(hitDir.x);
            Vector3 pos = e.Root.transform.position;
            bool heavy = tier == HitTier.Heavy;
            Color color = heavy ? C("#9FF8FF") : C("#7EDCFF");
            float alphaScale = effectsIntensity > .75f ? 1f : .70f;
            float width = e.Elite ? heavy ? 1.18f : .96f : heavy ? .94f : .76f;
            float travel = e.Elite ? heavy ? .52f : .40f : heavy ? .44f : .34f;

            var skid = SpawnTimedSprite(heavy ? "EnemyHeavyKnockbackTravelSkid_NoTexturePlate" : "EnemySkillKnockbackTravelSkid_NoTexturePlate", CombatVfxSprite(0), pos + new Vector3(-dir * .12f, -.53f, 0f), new Vector2(width, heavy ? .024f : .020f), new Color(color.r, color.g, color.b, (heavy ? .18f : .14f) * alphaScale), 8, heavy ? .13f : .10f);
            if (skid) skid.transform.localScale = new Vector3(Mathf.Abs(skid.transform.localScale.x) * -dir, skid.transform.localScale.y, 1f);
            var trail = SpawnTimedSprite(heavy ? "EnemyHeavyKnockbackTravelTrail_NoTexturePlate" : "EnemySkillKnockbackTravelTrail_NoTexturePlate", CombatVfxSprite(0), pos + new Vector3(-dir * travel, .18f, 0f), new Vector2(width * .84f, heavy ? .030f : .024f), new Color(.94f, 1f, 1f, (heavy ? .22f : .16f) * alphaScale), 10, heavy ? .11f : .085f);
            if (trail) trail.transform.localScale = new Vector3(Mathf.Abs(trail.transform.localScale.x) * -dir, trail.transform.localScale.y, 1f);
            SpawnTimedSprite(heavy ? "EnemyHeavyKnockbackStopNeedle_NoTexturePlate" : "EnemySkillKnockbackStopNeedle_NoTexturePlate", CombatVfxSprite(0), pos + new Vector3(dir * .28f, -.40f, 0f), new Vector2(.070f, heavy ? .15f : .12f), new Color(color.r, color.g, color.b, (heavy ? .24f : .17f) * alphaScale), 10, heavy ? .12f : .09f);
        }

        private void ShowMergedDamageText(Fighter e, float amount, HitTier tier, Vector2 hitDir)
        {
            if (e == null || !e.Root || !fxRoot) return;
            bool existing = e.FloatingDamageText && e.FloatingDamageTimer > 0f;
            if (!existing && !ShouldShowFloatingDamageText(e, tier)) return;
            e.FloatingDamageAmount = existing ? e.FloatingDamageAmount + amount : amount;
            e.FloatingDamageTier = StrongerDamageTier(e.FloatingDamageTier, tier);
            e.FloatingDamageBoss = e.Boss;
            e.FloatingDamageTimer = e.Boss ? .54f : e.Elite ? e.FloatingDamageTier == HitTier.Light ? .46f : .58f : e.FloatingDamageTier == HitTier.Light ? .28f : .42f;
            e.FloatingDamageDuration = Mathf.Max(e.FloatingDamageDuration, e.FloatingDamageTimer);
            float side = Mathf.Sign(Mathf.Abs(hitDir.x) < .05f ? facing : hitDir.x);
            e.FloatingDamageAnchor = e.Root.transform.position + new Vector3(side * .12f, e.Boss ? 1.72f : 1.18f, 0f);
            if (!e.FloatingDamageText)
            {
                e.FloatingDamageText = WorldText("MergedDamageText", fxRoot, "", e.FloatingDamageAnchor, DamageTextFontSize(e), 30);
            }
            UpdateMergedDamageTextVisual(e, 0f);
        }

        private bool ShouldShowFloatingDamageText(Fighter e, HitTier tier)
        {
            if (e == null) return false;
            if (e.Boss || e.Elite || tier != HitTier.Light) return true;
            if (ActiveEnemiesInCurrentArea() <= 1 && comboHits <= 4) return true;
            if (minorFloatingDamageTextCooldown > 0f) return false;
            minorFloatingDamageTextCooldown = MinorFloatingDamageTextCooldownDuration;
            return true;
        }

        private static HitTier StrongerDamageTier(HitTier current, HitTier incoming)
        {
            if (current == HitTier.Heavy || incoming == HitTier.Heavy) return HitTier.Heavy;
            if (current == HitTier.Skill || incoming == HitTier.Skill) return HitTier.Skill;
            return HitTier.Light;
        }

        private static int DamageTextFontSize(Fighter e)
        {
            if (e == null) return 32;
            if (e.FloatingDamageBoss) return 34;
            if (e.FloatingDamageTier == HitTier.Heavy) return e.Elite ? 34 : 28;
            if (e.FloatingDamageTier == HitTier.Skill) return e.Elite ? 32 : 27;
            return e.Elite ? 28 : 0;
        }

        private static Color DamageTextColor(Fighter e)
        {
            if (e == null) return Color.white;
            if (e.FloatingDamageBoss) return C("#DDFBFF");
            if (e.FloatingDamageTier == HitTier.Heavy) return C("#9FF8FF");
            if (e.FloatingDamageTier == HitTier.Skill) return C("#7EDCFF");
            return new Color(.86f, .94f, 1f, .62f);
        }

        private static string DamageTextLabel(Fighter e)
        {
            if (e == null) return "";
            if (e.FloatingDamageBoss) return "BOSS ";
            if (e.FloatingDamageTier == HitTier.Heavy) return "破势 ";
            if (e.FloatingDamageTier == HitTier.Skill) return "术式 ";
            return "";
        }

        private void UpdateFloatingDamageTexts(float dt)
        {
            foreach (var e in enemies.ToArray())
            {
                if (e == null || !e.FloatingDamageText) continue;
                e.FloatingDamageTimer -= dt;
                if (e.FloatingDamageTimer <= 0f || e.Dead || !e.Root)
                {
                    ClearFloatingDamageText(e);
                    continue;
                }
                UpdateMergedDamageTextVisual(e, dt);
            }
        }

        private void UpdateMergedDamageTextVisual(Fighter e, float dt)
        {
            if (e == null || !e.FloatingDamageText) return;
            float duration = Mathf.Max(.01f, e.FloatingDamageDuration);
            float t = Mathf.Clamp01(1f - e.FloatingDamageTimer / duration);
            bool minor = !e.Boss && !e.Elite;
            if (minor && e.FloatingDamageTier == HitTier.Light)
            {
                e.FloatingDamageText.text = "";
                e.FloatingDamageText.color = Color.clear;
                return;
            }
            float pop = 1f + Mathf.Sin(Mathf.Clamp01(t * 1.8f) * Mathf.PI) * (minor ? e.FloatingDamageTier == HitTier.Light ? .035f : .08f : e.FloatingDamageTier == HitTier.Light ? .08f : .16f);
            Vector3 follow = e.Root ? e.Root.transform.position + new Vector3(0f, e.Boss ? 1.72f : 1.18f, 0f) : e.FloatingDamageAnchor;
            e.FloatingDamageAnchor = Vector3.Lerp(e.FloatingDamageAnchor, follow, dt * 8f);
            e.FloatingDamageText.transform.position = e.FloatingDamageAnchor + Vector3.up * Mathf.Lerp(0f, minor ? e.FloatingDamageTier == HitTier.Light ? .18f : .30f : e.FloatingDamageTier == HitTier.Light ? .34f : .52f, t);
            e.FloatingDamageText.transform.localScale = Vector3.one * pop;
            e.FloatingDamageText.fontSize = DamageTextFontSize(e);
            e.FloatingDamageText.text = DamageTextLabel(e) + Mathf.CeilToInt(e.FloatingDamageAmount).ToString();
            Color color = DamageTextColor(e);
            float fadeStart = minor ? .46f : .62f;
            float fade = t < fadeStart ? 1f : Mathf.Lerp(1f, 0f, (t - fadeStart) / Mathf.Max(.01f, 1f - fadeStart));
            e.FloatingDamageText.color = new Color(color.r, color.g, color.b, color.a * fade);
        }

        private static void ClearFloatingDamageText(Fighter e)
        {
            if (e == null) return;
            if (e.FloatingDamageText) Destroy(e.FloatingDamageText.gameObject);
            e.FloatingDamageText = null;
            e.FloatingDamageAmount = 0f;
            e.FloatingDamageTimer = 0f;
            e.FloatingDamageDuration = 0f;
            e.FloatingDamageTier = HitTier.Light;
        }

        private void TriggerHitFrameBeat(HitTier tier, bool boss, Vector3 position, SkillKind? sourceSkill = null)
        {
            float stop = tier == HitTier.Heavy ? HeavyHitStopDuration : tier == HitTier.Skill ? SkillHitStopDurationFor(sourceSkill, boss) : LightHitStopDuration;
            if (boss) stop += tier == HitTier.Heavy ? .026f : .018f;
            HitStop(stop);

            float tierPower = tier == HitTier.Heavy ? 1.35f : tier == HitTier.Skill ? 1.18f : 1f;
            float flash = boss ? .18f : tier == HitTier.Light ? .065f : tier == HitTier.Skill ? .11f : .15f;
            float shake = boss ? .072f : tier == HitTier.Light ? .028f : tier == HitTier.Skill ? .045f : .062f;
            TriggerCombatFlash(flash * tierPower, boss ? .12f : tier == HitTier.Light ? .075f : .105f);
            ShakeCamera(shake * tierPower, boss ? .16f : tier == HitTier.Light ? .09f : .14f);
            if (tier == HitTier.Skill && sourceSkill.HasValue)
                SpawnSkillHitRhythmSignature(sourceSkill.Value, position, boss);
            if (!ShouldShowHitFrameWorldText(tier, boss))
                return;

            string label = boss ? "BOSS 命中帧" : tier == HitTier.Heavy ? "破势定格" : tier == HitTier.Skill ? "术式定格" : "命中帧";
            Color color = boss ? C("#9FF8FF") : tier == HitTier.Heavy ? C("#9FF8FF") : tier == HitTier.Skill ? C("#7EDCFF") : C("#FFFFFF");
            var text = WorldText("HitFrameBeatText", fxRoot, label, (Vector2)position + new Vector2(0, boss ? .62f : .44f), boss ? 28 : tier == HitTier.Light ? 20 : 24, 34);
            text.color = new Color(color.r, color.g, color.b, effectsIntensity > .75f ? .92f : .68f);
            AnimateFloatingWorldText(text, new Vector2(0, boss ? .42f : .30f), boss ? .44f : .34f, tier == HitTier.Light ? 1.06f : 1.14f);
        }

        private static float SkillHitStopDurationFor(SkillKind? sourceSkill, bool boss)
        {
            if (!sourceSkill.HasValue) return SkillHitStopDuration;
            float stop = sourceSkill.Value == SkillKind.ThunderStrike ? .078f
                : sourceSkill.Value == SkillKind.Fireball ? .064f
                : sourceSkill.Value == SkillKind.SlashWave ? .056f
                : .048f;
            return boss ? stop + .010f : stop;
        }

        private void SpawnSkillHitRhythmSignature(SkillKind skill, Vector3 position, bool boss)
        {
            if (!fxRoot) return;
            float scale = boss ? 1.28f : 1f;
            if (skill == SkillKind.SlashWave)
            {
                SpawnTimedSprite("SkillRhythmSlashCut_StopFrame_NoYellowPlate", CombatVfxSprite(0), position + Vector3.right * facing * .18f, new Vector2(.64f, .012f) * scale, new Color(.90f, 1f, 1f, .22f), 15, .044f);
                SpawnTimedSprite("SkillRhythmSlashFootPin_NoYellowPlate", CombatVfxSprite(0), position + Vector3.down * .36f, new Vector2(.34f, .008f) * scale, new Color(.62f, .96f, 1f, .090f), 12, .046f);
                return;
            }
            if (skill == SkillKind.Fireball)
            {
                SpawnTimedSprite("SkillRhythmFireBurstColdEdge_NoYellowPlate", CombatVfxSprite(0), position + Vector3.up * .02f, new Vector2(.46f, .012f) * scale, new Color(.74f, .96f, 1f, .16f), 15, .050f);
                SpawnTimedSprite("SkillRhythmFireHotCoreSmall_NoYellowPlate", CombatVfxSprite(0), position + Vector3.up * .16f, new Vector2(.22f, .010f) * scale, new Color(1f, .48f, .28f, .12f), 14, .040f);
                return;
            }
            if (skill == SkillKind.FrostNova)
            {
                SpawnTimedSprite("SkillRhythmFrostLockLine_NoYellowPlate", CombatVfxSprite(0), position + Vector3.down * .20f, new Vector2(.52f, .010f) * scale, new Color(.62f, .94f, 1f, .14f), 14, .052f);
                SpawnTimedSprite("SkillRhythmFrostLiftTick_NoYellowPlate", CombatVfxSprite(0), position + Vector3.up * .38f, new Vector2(.24f, .010f) * scale, new Color(.94f, 1f, 1f, .20f), 15, .044f);
                return;
            }
            SpawnTimedSprite("SkillRhythmThunderStopSpine_NoYellowPlate", CombatVfxSprite(0), position + Vector3.up * .42f, new Vector2(.018f, .62f) * scale, new Color(.90f, 1f, 1f, .24f), 15, .052f);
            SpawnTimedSprite("SkillRhythmThunderGroundSnap_NoYellowPlate", CombatVfxSprite(0), position + Vector3.down * .32f, new Vector2(.46f, .010f) * scale, new Color(.62f, .96f, 1f, .14f), 14, .052f);
        }

        private bool ShouldShowHitFrameWorldText(HitTier tier, bool boss)
        {
            if (boss || tier != HitTier.Light) return true;
            if (lightHitWorldTextCooldown > 0f) return false;
            lightHitWorldTextCooldown = .46f;
            return ActiveEnemiesInCurrentArea() <= 1;
        }

