            SpawnTimedSprite("EnemyBreakLine_NoYellowPlate", CombatVfxSprite(0), deathPos + Vector3.up * (e.Boss ? .85f : .36f), new Vector2(e.Boss ? 1.95f : e.Elite ? 1.08f : .42f, e.Boss ? .034f : e.Elite ? .026f : .018f), new Color(1, 1, 1, e.Boss ? .34f : e.Elite ? .24f : .10f), 11, e.Boss ? .13f : e.Elite ? .09f : .060f);
