        private void SpawnEnemyBreakReadableDebris(Fighter e, Vector3 deathPos, Color color, float scale)
        {
            if (!fxRoot) return;
            float size = e.Boss ? .44f : e.Elite ? .28f : .12f;
            int count = e.Boss ? 5 : e.Elite ? 4 : 1;
            for (int i = 0; i < count; i++)
            {
                float side = i % 2 == 0 ? 1f : -1f;
                Vector2 offset = new Vector2(side * (.18f + i * .08f), .18f + i * .07f);
