                if (chip) chip.transform.localRotation = Quaternion.Euler(0, 0, side * (18f + i * 9f));
            }
            SpawnTimedSprite("EnemyBreakGroundConfirm_NoYellowPlate", CombatVfxSprite(0), deathPos + Vector3.down * .38f, new Vector2(e.Boss ? 1.45f : e.Elite ? .86f : .38f, e.Boss ? .034f : e.Elite ? .026f : .018f), new Color(.02f, .06f, .08f, e.Boss ? .24f : e.Elite ? .16f : .10f), 4, e.Boss || e.Elite ? .14f : .080f);
        }

        private void SpawnEnemyCuteBreakBits(Fighter e, Vector3 deathPos, Color color)
        {
            if (!fxRoot || e == null) return;
            if (e.Boss)
            {
                for (int i = 0; i < 3; i++)
                {
                    float side = i == 1 ? 0f : i == 0 ? -1f : 1f;
                    var shard = SpawnTimedSprite("EnemyCuteBreakBossCoreShard_NoYellowPlate", CombatVfxSprite(0), deathPos + new Vector3(side * .32f, 1.10f + i * .08f, 0f), new Vector2(.20f, .024f), new Color(.96f, 1f, 1f, .16f), 12, .13f);
                    if (shard) shard.transform.localRotation = Quaternion.Euler(0f, 0f, -18f + i * 18f);
                }
                return;
            }

            int count = e.Elite ? 3 : 2;
            for (int i = 0; i < count; i++)
            {
                float side = i % 2 == 0 ? -1f : 1f;
                Vector3 pos = deathPos + new Vector3(side * (.12f + i * .08f), .34f + i * .085f, 0f);
                if (e.Kind == EnemyKind.Slime)
                {
                    var bubble = SpawnTimedSprite("EnemyCuteBreakSlimeBubble_NoPlate", SpriteCache.Circle, pos, new Vector2(.070f + i * .012f, .030f + i * .006f), new Color(.74f, 1f, .90f, e.Elite ? .13f : .085f), 11, e.Elite ? .11f : .080f);
                    if (bubble) bubble.transform.localRotation = Quaternion.Euler(0f, 0f, side * (8f + i * 7f));
                }
                else if (e.Kind == EnemyKind.Archer)
                {
