        private void SpawnLastEnemyRoomClearCue(Vector3 deathPos, int segment)
        {
            if (!fxRoot) return;
            int index = Mathf.Clamp(segment, 0, SegmentRights.Length - 1);
            bool optionalChest = ActivePlatformRuneVesselInSegment(index);
            Color color = optionalChest ? C("#9FF8FF") : C("#BFEFFF");
            float alphaScale = effectsIntensity > .75f ? 1f : .70f;
            Vector3 foot = player ? player.transform.position + Vector3.down * .58f : deathPos + Vector3.down * .42f;
            float gateX = index < progressGates.Count ? SegmentRights[index] + .18f : SegmentRights[index];
            float dir = Mathf.Sign(gateX - foot.x);
            if (Mathf.Abs(dir) < .05f) dir = 1f;

            SpawnTimedSprite("LastEnemyRoomClearSnap_NoTexturePlate", CombatVfxSprite(0), deathPos + Vector3.up * .36f, new Vector2(.54f, .026f), new Color(color.r, color.g, color.b, .20f * alphaScale), 12, .10f);
            SpawnTimedSprite("LastEnemyRoomClearGroundConfirm_NoTexturePlate", CombatVfxSprite(0), deathPos + Vector3.down * .42f, new Vector2(.64f, .020f), new Color(.94f, 1f, 1f, .13f * alphaScale), 8, .10f);
            var route = SpawnTimedSprite("LastEnemyRoomClearRouteLine_NoTexturePlate", CombatVfxSprite(0), foot + Vector3.right * dir * .74f, new Vector2(optionalChest ? .86f : 1.08f, .020f), new Color(color.r, color.g, color.b, .10f * alphaScale), 7, .24f);
            if (route) route.transform.localScale = new Vector3(Mathf.Abs(route.transform.localScale.x) * dir, route.transform.localScale.y, 1f);
            for (int i = 0; i < 2; i++)
            {
                var tick = SpawnTimedSprite("LastEnemyRoomClearProceedTick_NoTexturePlate", CombatVfxSprite(0), foot + new Vector3(dir * (.42f + i * .44f), .08f + i * .012f, 0f), new Vector2(.16f, .020f), new Color(.86f, 1f, 1f, .15f * alphaScale), 8, .16f + i * .045f);
                if (tick) tick.transform.localScale = new Vector3(Mathf.Abs(tick.transform.localScale.x) * dir, tick.transform.localScale.y, 1f);
            }
            var pin = SpawnTimedSprite("LastEnemyRoomClearPlayerDestinationPin_NoTexturePlate", CombatVfxSprite(0), foot + new Vector3(dir * (optionalChest ? 1.16f : 1.30f), .11f, 0f), new Vector2(.038f, .072f), new Color(.86f, 1f, 1f, .080f * alphaScale), 9, .18f);
            if (pin) pin.transform.localScale = new Vector3(Mathf.Abs(pin.transform.localScale.x) * dir, pin.transform.localScale.y, 1f);
            proceedHintTimer = Mathf.Max(proceedHintTimer, optionalChest ? 1.15f : 1.35f);
        }

