        private void AnimateFloatingWorldText(TextMesh text, Vector2 drift, float duration, float popScale)
        {
            if (!text) return;
            StartCoroutine(AnimateFloatingWorldTextRoutine(text, drift, duration, popScale));
        }

        private IEnumerator AnimateFloatingWorldTextRoutine(TextMesh text, Vector2 drift, float duration, float popScale)
        {
            if (!text) yield break;
            var tr = text.transform;
            Vector3 startPos = tr.position;
            Vector3 startScale = tr.localScale;
            Color baseColor = text.color;
            float elapsed = 0f;
            while (elapsed < duration && text)
            {
                elapsed += Time.deltaTime;
                float t = Mathf.Clamp01(elapsed / duration);
                float pop = t < .18f ? Mathf.Lerp(popScale, 1f, t / .18f) : 1f + Mathf.Sin(t * Mathf.PI) * .06f;
                tr.position = startPos + (Vector3)(drift * EaseOutCubic(t));
                tr.localScale = startScale * pop;
                float alpha = t < .58f ? 1f : Mathf.Lerp(1f, 0f, (t - .58f) / .42f);
                text.color = new Color(baseColor.r, baseColor.g, baseColor.b, baseColor.a * alpha);
                yield return null;
            }
            if (text) Destroy(text.gameObject);
        }

        private static float EaseOutCubic(float t)
        {
            t = Mathf.Clamp01(t);
            float inv = 1f - t;
            return 1f - inv * inv * inv;
        }

        private void TriggerCombatFlash(float strength, float duration)
        {
            float flashScale = VisualFlashScale();
            combatFlashStrength = Mathf.Max(combatFlashStrength, Mathf.Min(strength * flashScale, MaxFlashStrength()));
            combatFlashTimer = Mathf.Max(combatFlashTimer, Mathf.Min(duration * flashScale, MaxFlashDuration()));
        }

        private void DamagePlayer(float amount)
        {
            DamagePlayer(amount, "环境伤害", player ? player.transform.position : Vector3.zero);
        }

        private void DamagePlayer(float amount, Vector3 threatPosition)
        {
            DamagePlayer(amount, "敌方伤害", threatPosition);
        }

        private void DamagePlayer(float amount, string sourceLabel, Vector3 threatPosition)
        {
            if (inputLocked) return;
            if (invulnTimer > 0)
            {
                TryTriggerPerfectDodge(threatPosition);
                return;
            }
            if (assistMode) amount *= AssistDamageScale;
            invulnTimer = .45f;
            hp -= amount;
            damageTakenThisRun++;
            RecordDamageSource(sourceLabel);
            PlaySfx(sfxPlayerHurt, 1f);
            HapticPulse(HapticTier.Heavy);
            comboHits = 0;
            comboDisplayTimer = 0;
            ShowDamageDirection(threatPosition);
            ShowHurtRecoveryHint(sourceLabel);
            PlayHeroFrames(HeroHurtFrames, HurtAnimFps, .18f);
            StartCoroutine(SpriteFlash(playerSprite, Color.white));
            SpawnPlayerHurtCue();
            var damageText = WorldText("PlayerDamageText", fxRoot, "-" + Mathf.CeilToInt(amount), player.transform.position + Vector3.up * 1.45f, 28, 30);
            damageText.color = C("#FF7777");
            AnimateFloatingWorldText(damageText, new Vector2(-facing * .18f, .64f), .62f, 1.12f);
            ShakeCamera(.08f, .16f);
            if (hp <= 0)
            {
                hp = 0;
                noticeText.text = $"挑战失败：最后受击 {lastDamageSource}";
                SpawnPlayerDefeatCeremony(threatPosition);
                ShowVictory(false);
            }
        }

        private void SpawnPlayerDefeatCeremony(Vector3 threatPosition)
        {
            if (!player || !fxRoot) return;
            Color color = C("#FF7A6B");
            SpawnTimedSprite("PlayerDefeatCore_NoYellowPlate", CombatVfxSprite(0), player.transform.position + Vector3.up * .45f, new Vector2(1.42f, .040f), new Color(color.r, color.g, color.b, effectsIntensity > .75f ? .40f : .26f), 12, .20f);
            SpawnTimedSprite("PlayerDefeatGroundLine_NoYellowPlate", CombatVfxSprite(0), player.transform.position + Vector3.down * .48f, new Vector2(1.68f, .034f), new Color(1f, 1f, 1f, effectsIntensity > .75f ? .34f : .24f), 11, .18f);
            var text = WorldText("PlayerDefeatText", fxRoot, $"倒下：{lastDamageSource}", (Vector2)player.transform.position + new Vector2(0, 2.0f), 30, 36);
            text.color = color;
            AnimateFloatingWorldText(text, new Vector2(0, .62f), .92f, 1.14f);
            if (threatPosition != Vector3.zero)
                SpawnTimedSprite("PlayerDefeatSourceMark_NoYellowPlate", CombatVfxSprite(0), threatPosition + Vector3.up * .65f, new Vector2(.72f, .030f), new Color(1f, .30f, .22f, effectsIntensity > .75f ? .32f : .20f), 12, .22f);
            TriggerCombatFlash(.11f, .10f);
            ShakeCamera(.07f, .18f);
        }

        private void RecordDamageSource(string sourceLabel)
        {
            string key = string.IsNullOrEmpty(sourceLabel) ? "未知伤害" : sourceLabel;
            lastDamageSource = key;
            damageSourceHits[key] = damageSourceHits.TryGetValue(key, out int count) ? count + 1 : 1;
        }

        private bool TryTriggerPerfectDodge(Vector3 threatPosition)
        {
            if (!perfectDodgeReady || perfectDodgeWindow <= 0f || !player || inputLocked) return false;
            perfectDodgeReady = false;
            perfectDodgeWindow = 0f;
            perfectDodgesThisRun++;
            Vector3 pos = player.transform.position;
            Color color = C("#9FF8FF");
            SpawnTimedSprite("PerfectDodgeFlash_NoYellowPlate", CombatVfxSprite(0), pos + Vector3.up * .05f, new Vector2(1.18f, .034f), new Color(color.r, color.g, color.b, .42f), 12, .10f);
            SpawnTimedSprite("PerfectDodgeLine_NoYellowPlate", CombatVfxSprite(0), pos + Vector3.up * .35f, new Vector2(1.46f, .026f), new Color(1f, 1f, 1f, .50f), 13, .085f);
            float dx = pos.x - threatPosition.x;
            float side = Mathf.Abs(dx) < .05f ? facing : Mathf.Sign(dx);
            var text = WorldText("PerfectDodgeText", fxRoot, "极闪", (Vector2)pos + new Vector2(0, 1.50f), 24, 34);
            text.color = color;
            AnimateFloatingWorldText(text, new Vector2(side * .10f, .44f), .42f, 1.10f);
            GainFateEnergy(10f + dashRuneLevel * 2f, pos + Vector3.up * .4f);
            int cleared = ClearNearbyEnemyProjectiles(pos, 2.25f + dashRuneLevel * .18f);
            if (cleared > 0)
            {
                SpawnTimedSprite("PerfectDodgeClearPulse_NoYellowPlate", CombatVfxSprite(0), pos + Vector3.up * .08f, new Vector2(1.62f, .030f), new Color(.62f, .96f, 1f, .34f), 12, .095f);
                var clearText = WorldText("PerfectDodgeClearText", fxRoot, "清弹", (Vector2)pos + new Vector2(0, 2.05f), 18, 30);
                clearText.color = C("#B6F7FF");
                AnimateFloatingWorldText(clearText, new Vector2(0, .24f), .32f, 1.04f);
            }
            TriggerCombatFlash(.12f, .12f);
            ShakeCamera(.035f, .16f);
            HitStop(.045f);
            PlaySfx(sfxRuneReward, .55f);
            HapticPulse(HapticTier.Medium);
            return true;
        }

        private int ClearNearbyEnemyProjectiles(Vector3 center, float radius)
        {
            int cleared = 0;
            float radiusSqr = radius * radius;
            foreach (var fx in hitEffects.ToArray())
            {
                if (fx.PlayerOwned || fx.Root == null) continue;
                if (((Vector2)fx.Root.transform.position - (Vector2)center).sqrMagnitude > radiusSqr) continue;
                SpawnTimedSprite("EnemyProjectileClear_NoYellowPlate", CombatVfxSprite(0), fx.Root.transform.position, new Vector2(.46f, .026f), new Color(.72f, .96f, 1f, .34f), 10, .090f);
                Destroy(fx.Root);
                hitEffects.Remove(fx);
                cleared++;
            }
            return cleared;
        }

