        {
            if (!player) return;
            Vector2 dir = (Vector2)(threatPosition - player.transform.position);
            if (dir.sqrMagnitude < .04f) dir = new Vector2(-facing, .15f);
            damageDirectionVector = dir.normalized;
            damageDirectionTimer = .72f;
        }

        private void SpawnPickupBurst(PickupKind kind, float totalAmount, Vector3 center, int count)
        {
            count = Mathf.Max(1, count);
            float remaining = totalAmount;
            for (int i = 0; i < count; i++)
            {
                float amount = i == count - 1 ? remaining : Mathf.Max(1f, Mathf.Round(totalAmount / count));
                remaining -= amount;
                SpawnPickup(kind, amount, center + Vector3.up * .25f, new Vector2(UnityEngine.Random.Range(-.82f, .82f), UnityEngine.Random.Range(1.05f, 1.85f)));
            }
        }

        private void SpawnPickup(PickupKind kind, float amount, Vector3 position, Vector2 velocity)
        {
            var root = new GameObject("Pickup_" + kind);
            root.transform.SetParent(fxRoot);
            root.transform.position = position;
            Sprite sprite = kind == PickupKind.Coin ? CombatVfxSprite(7) : kind == PickupKind.Heal ? SpriteCache.Circle : RuneUiSprite(0);
            Color color = kind == PickupKind.Coin ? C("#FFD95A") : kind == PickupKind.Heal ? C("#FF6B7A") : C("#63E6FF");
            var sr = root.AddComponent<SpriteRenderer>();
            sr.sprite = sprite ? sprite : SpriteCache.Circle;
            sr.color = color;
            sr.sortingOrder = 9;
            Vector2 targetSize = kind == PickupKind.Coin ? new Vector2(.30f, .30f) : kind == PickupKind.Heal ? new Vector2(.26f, .26f) : new Vector2(.40f, .40f);
            Vector2 bounds = sr.sprite ? (Vector2)sr.sprite.bounds.size : Vector2.one;
            root.transform.localScale = new Vector3(targetSize.x / Mathf.Max(.01f, bounds.x), targetSize.y / Mathf.Max(.01f, bounds.y), 1);
            pickups.Add(new Pickup { Root = root, Kind = kind, Amount = amount, Life = 6f, Velocity = velocity });
        }

        private void UpdatePickups(float dt)
        {
            if (!player) return;
            pickupMagnetTrailTimer = Mathf.Max(0f, pickupMagnetTrailTimer - dt);
            Vector2 playerPos = player.transform.position + Vector3.up * .4f;
            foreach (var pickup in pickups.ToArray())
            {
                if (!pickup.Root)
                {
                    pickups.Remove(pickup);
                    continue;
                }
                pickup.Life -= dt;
                var pos = (Vector2)pickup.Root.transform.position;
                float dist = Vector2.Distance(pos, playerPos);
                if (dist < 2.8f)
                {
                    var dir = (playerPos - pos).normalized;
                    pickup.Velocity = Vector2.Lerp(pickup.Velocity, dir * Mathf.Lerp(5.5f, 10.5f, 1f - Mathf.Clamp01(dist / 2.8f)), dt * 8f);
                    if (dist > .58f && dist < 2.35f && pickupMagnetTrailTimer <= 0f)
                    {
                        pickupMagnetTrailTimer = .055f;
                        SpawnPickupMagnetTrail(pickup.Kind, pos, playerPos);
                    }
                }
                else
                {
                    pickup.Velocity += Vector2.down * 5.2f * dt;
                    pickup.Velocity *= 1f - Mathf.Clamp01(dt * 1.8f);
                }
                pos += pickup.Velocity * dt;
                if (pos.y < GroundY + .36f)
                {
                    pos.y = GroundY + .36f;
                    pickup.Velocity.y = Mathf.Abs(pickup.Velocity.y) * .28f;
                }
                pickup.Root.transform.position = pos + Vector2.up * (Mathf.Sin(Time.time * 6f + pickup.Amount) * .035f);
                if (dist < .42f)
                    CollectPickup(pickup);
                else if (pickup.Life <= 0)
                {
                    Destroy(pickup.Root);
                    pickups.Remove(pickup);
                }
            }
        }

        private void CollectPickup(Pickup pickup)
        {
            if (!pickup.Root) return;
            Vector3 collectPos = pickup.Root.transform.position;
            if (pickup.Kind == PickupKind.Coin)
            {
                coins += Mathf.Max(1, Mathf.RoundToInt(pickup.Amount));
                PlaySfx(sfxPickup, .50f);
            }
            else if (pickup.Kind == PickupKind.Heal)
            {
                hp = Mathf.Min(maxHp, hp + pickup.Amount);
                PlaySfx(sfxPickup, .58f);
            }
            else
            {
                GainFateEnergy(pickup.Amount, collectPos);
                PlaySfx(sfxPickup, .64f);
            }
            if (pickup.Kind == PickupKind.Coin)
                ShowMergedCoinPickupText(pickup.Amount, collectPos);
            else
                ShowMergedResourcePickupText(pickup.Kind, pickup.Amount, collectPos);
            Color collectColor = pickup.Kind == PickupKind.Coin ? C("#FFD95A") : pickup.Kind == PickupKind.Heal ? C("#FF7A8A") : C("#63E6FF");
            SpawnTimedSprite("PickupCollectFx_CleanTick", CombatVfxSprite(0), collectPos, new Vector2(.24f, .022f), new Color(collectColor.r, collectColor.g, collectColor.b, pickup.Kind == PickupKind.Coin ? .18f : .28f), 10, .060f);
            Destroy(pickup.Root);
            pickups.Remove(pickup);
        }

        private void SpawnPickupMagnetTrail(PickupKind kind, Vector2 from, Vector2 to)
        {
            Color color = kind == PickupKind.Coin ? C("#E8F6C8") : kind == PickupKind.Heal ? C("#FF8EA0") : C("#63E6FF");
            Vector2 mid = Vector2.Lerp(from, to, .42f);
            Vector2 delta = to - from;
            float length = Mathf.Clamp(delta.magnitude * .26f, .16f, .48f);
            var trail = SpawnTimedSprite("PickupMagnetTrail_CleanThrottled", CombatVfxSprite(0), mid, new Vector2(length, .016f), new Color(color.r, color.g, color.b, kind == PickupKind.Coin ? .095f : .14f), 7, .050f);
            if (trail && Mathf.Abs(delta.x) > .04f)
                trail.transform.localScale = new Vector3(Mathf.Abs(trail.transform.localScale.x) * Mathf.Sign(delta.x), trail.transform.localScale.y, 1f);
        }

        private void ShowMergedCoinPickupText(float amount, Vector3 position)
        {
            mergedCoinPickupAmount += Mathf.Max(1f, Mathf.Round(amount));
            if (!ShouldShowCoinPickupWorldText(mergedCoinPickupAmount))
                return;
            mergedCoinPickupTimer = .42f;
            mergedCoinPickupAnchor = position + Vector3.up * .64f;
            if (!mergedCoinPickupText)
                mergedCoinPickupText = WorldText("MergedCoinPickupText", fxRoot, "", mergedCoinPickupAnchor, 20, 30);
            UpdateMergedCoinPickupText(0f);
        }

        private bool ShouldShowCoinPickupWorldText(float mergedAmount)
        {
            if (rollingRune || inputLocked) return false;
            if (ActiveEnemiesInCurrentArea() <= 0) return true;
            if (mergedAmount >= CombatCoinWorldTextThreshold) return true;
            return false;
        }

        private void UpdateMergedCoinPickupText(float dt)
        {
            if (!mergedCoinPickupText) return;
            mergedCoinPickupTimer -= dt;
            if (mergedCoinPickupTimer <= 0f)
            {
                Destroy(mergedCoinPickupText.gameObject);
                mergedCoinPickupText = null;
                mergedCoinPickupAmount = 0f;
                return;
            }
            float t = Mathf.Clamp01(1f - mergedCoinPickupTimer / .42f);
            mergedCoinPickupText.text = $"+{Mathf.RoundToInt(mergedCoinPickupAmount)} 金币";
            mergedCoinPickupText.transform.position = mergedCoinPickupAnchor + Vector3.up * Mathf.Lerp(0f, .22f, t);
            float pop = 1f + Mathf.Sin(Mathf.Clamp01(t * 1.8f) * Mathf.PI) * .055f;
            mergedCoinPickupText.transform.localScale = Vector3.one * pop;
            float alpha = t < .48f ? .58f : Mathf.Lerp(.58f, 0f, (t - .48f) / .52f);
            Color color = C("#FFD95A");
            mergedCoinPickupText.color = new Color(color.r, color.g, color.b, alpha);
        }

        private void ShowMergedResourcePickupText(PickupKind kind, float amount, Vector3 position)
        {
            if (kind == PickupKind.Heal) mergedHealPickupAmount += Mathf.Ceil(amount);
            if (kind == PickupKind.Fate) mergedFatePickupAmount += Mathf.Ceil(amount);
            mergedResourcePickupTimer = .60f;
            mergedResourcePickupAnchor = position + Vector3.up * .82f;
            if (!mergedResourcePickupText)
                mergedResourcePickupText = WorldText("MergedResourcePickupText", fxRoot, "", mergedResourcePickupAnchor, 20, 30);
            UpdateMergedResourcePickupText(0f);
        }

        private void UpdateMergedResourcePickupText(float dt)
        {
            if (!mergedResourcePickupText) return;
            mergedResourcePickupTimer -= dt;
            if (mergedResourcePickupTimer <= 0f)
            {
                Destroy(mergedResourcePickupText.gameObject);
                mergedResourcePickupText = null;
                mergedHealPickupAmount = 0f;
                mergedFatePickupAmount = 0f;
                return;
            }
            string heal = mergedHealPickupAmount > 0f ? $"+{Mathf.RoundToInt(mergedHealPickupAmount)} 生命" : "";
            string fate = mergedFatePickupAmount > 0f ? $"+{Mathf.RoundToInt(mergedFatePickupAmount)}% 命运" : "";
            mergedResourcePickupText.text = string.IsNullOrEmpty(heal) ? fate : string.IsNullOrEmpty(fate) ? heal : $"{heal}  {fate}";
            float t = Mathf.Clamp01(1f - mergedResourcePickupTimer / .60f);
            mergedResourcePickupText.transform.position = mergedResourcePickupAnchor + Vector3.up * Mathf.Lerp(0f, .24f, t);
            mergedResourcePickupText.transform.localScale = Vector3.one * (1f + Mathf.Sin(Mathf.Clamp01(t * 1.8f) * Mathf.PI) * .055f);
            float alpha = t < .60f ? .82f : Mathf.Lerp(.82f, 0f, (t - .60f) / .40f);
            Color color = mergedFatePickupAmount > 0f ? C("#63E6FF") : C("#FF7A8A");
            mergedResourcePickupText.color = new Color(color.r, color.g, color.b, alpha);
        }

        private void GainFateEnergy(float amount, Vector3 sourcePosition)
        {
            if (rollingRune || shrineAvailable) return;
            fateEnergy += amount;
            if (fateEnergy < 100f) return;
            if (ActiveEnemiesInCurrentArea() > 0)
            {
                fateEnergy = 99f;
                noticeText.text = "命运能量临界：清完本房后再开宝箱";
                return;
            }
            if (!RuneSpawnCooldownReady())
            {
                fateEnergy = 99f;
                noticeText.text = "命运能量临界：先推进，稍后再启封";
                return;
            }
            if (!CurrentSegmentAllowsAutomaticRuneShrine())
            {
                fateEnergy = 99f;
                noticeText.text = "命运能量临界：留到关键房启封";
                return;
            }
            if (!AutomaticRuneShrineQuotaReady())
            {
                fateEnergy = 99f;
                noticeText.text = "本关奖励 SLOT 已出现过：继续推进到商店或 Boss";
                return;
            }
            fateEnergy -= 100f;
            PlaySfx(sfxRuneReward, .9f);
            SpawnTimedSprite("FateEnergyFullFx_NoYellowPlate", CombatVfxSprite(0), sourcePosition + Vector3.up * .45f, new Vector2(1.12f, .032f), new Color(.88f, 1f, 1f, .42f), 8, .18f);
            ConsumeAutomaticRuneShrineQuota();
            SpawnRuneShrine(false, Mathf.Clamp(player.transform.position.x + 2.5f, LeftBound + 2f, CurrentSegmentRight() - 1.2f));
            noticeText.text = "命运能量已满：SLOT 宝箱出现，靠近后点启封";
        }

        private void CheckStageClear()
        {
            if (finalVictorySequenceRunning) return;
            if (inputLocked) return;
            if (enemies.Any(e => e != null && !e.Dead && e.Root && e.Root.activeInHierarchy)) return;
            if (!stageRuneResolved && !shrineAvailable)
            {
                string rewardText = GrantRoomClearReward(SegmentRights.Length - 1);
                SpawnRuneShrine(true);
                noticeText.text = $"{rewardText}  |  SLOT 宝箱出现：靠近后点启封";
                return;
            }
            if (!stageRuneResolved || shrineAvailable) return;
            if (stageIndex < 3)
            {
                noticeText.text = "关卡清空，进入下一关";
                StartCoroutine(NextStageAfterDelay());
            }
            else
            {
                StartCoroutine(FinalVictorySequence());
            }
        }

        private IEnumerator FinalVictorySequence()
        {
            finalVictorySequenceRunning = true;
            inputLocked = true;
            noticeText.text = "最终命运已启封：试炼完成";
            if (player) SpawnTimedSprite("FinalVictoryAura_NoYellowPlate", CombatVfxSprite(0), player.transform.position + Vector3.up * .35f, new Vector2(2.10f, .040f), new Color(.55f, .95f, 1f, .38f), 12, .28f);
            var text = WorldText("FinalVictoryText", fxRoot, "试炼完成\n命运流派已成型", player ? (Vector2)player.transform.position + new Vector2(0, 2.35f) : new Vector2(SegmentCenters[BossRoomIndex], GroundY + 2.4f), 36, 38);
            text.color = C("#FFD95A");
            Destroy(text.gameObject, 1.35f);
            SetHeroFrame(HeroVictoryFrame);
            PlaySfx(sfxRuneReward, 1f);
            HapticPulse(HapticTier.Reward);
            TriggerCombatFlash(.18f, .28f);
            ShakeCamera(.06f, .28f);
            yield return new WaitForSeconds(1.05f);
            finalVictorySequenceRunning = false;
            ShowVictory(true);
        }

        private void SpawnRuneShrine(bool completesStage, float? forcedX = null)
        {
            lastRuneShrineSpawnTime = Time.time;
            shrineAvailable = true;
            currentShrineCompletesStage = completesStage;
            if (slotShrine) Destroy(slotShrine);
            slotShrine = new GameObject("RuneSealShrine");
            slotShrine.transform.SetParent(world);
            slotShrine.transform.position = new Vector3(forcedX ?? Mathf.Clamp(player.transform.position.x + 3.2f, -2f, RightBound - 3f), GroundY + 1.25f, 0);
            CircleObj("RuneShrineHalo", slotShrine.transform, Vector2.zero, .54f, new Color(.12f, .95f, 1f, .075f), 3);
            BuildRuneChestVisual("RuneShrineChest", slotShrine.transform, false, completesStage);
            SpriteObj("RuneShrineGate", slotShrine.transform, RuneUiSprite(0), new Vector2(0, .26f), new Vector2(.56f, .56f), new Color(1f, 1f, 1f, .46f), 5);
            SpawnTimedSprite("RuneShrineAura_NoYellowPlate", CombatVfxSprite(0), slotShrine.transform.position + Vector3.up * .16f, new Vector2(.42f, .016f), new Color(1, 1, 1, .10f), 4, .16f);
            worldRuneText = WorldText("RuneShrineLabel", slotShrine.transform, "", new Vector2(0, 1.12f), 18, 8);
            worldRuneText.color = Color.clear;
            noticeText.text = completesStage ? "SLOT 宝箱出现：靠近后点启封" : "奖励宝箱出现：靠近后点启封";
        }

        private void TryContextInteract()
        {
            if (shrineAvailable)
            {
                TryOpenRune();
                return;
            }
            if (CanUseShopInteraction())
            {
                TryOpenShop();
                return;
            }
            noticeText.text = currentSegment == ShopRoomIndex ? "清空当前区域后可打开符文补给" : "寻找 SLOT 宝箱或符文商人";
        }

        private void TryOpenRune()
        {
            if (!shrineAvailable || rollingRune || !slotShrine) return;
            if (!currentShrineCompletesStage && ActiveEnemiesInCurrentArea() > 0)
            {
                noticeText.text = "先清敌，再启封 SLOT 宝箱";
                return;
            }
            if (Vector2.Distance(player.transform.position, slotShrine.transform.position) > 2.2f)
            {
                noticeText.text = "靠近 SLOT 宝箱才能启封";
                return;
            }
            AdvanceTutorial(4);
            StartCoroutine(RollRune());
        }

        private bool RuneSpawnCooldownReady()
        {
            return Time.time - lastRuneShrineSpawnTime >= RuneShrineSpawnCooldownSeconds
                && Time.time - lastRuneRollFinishTime >= RuneShrineSpawnCooldownSeconds;
        }

        private bool RuneDirectOpenCooldownReady()
        {
            return Time.time - lastRuneRollFinishTime >= RuneChestDirectOpenCooldownSeconds
                && Time.time - lastRuneShrineSpawnTime >= RuneChestDirectOpenCooldownSeconds;
        }

        private bool CanUseShopInteraction()
        {
            return shopKeeper && shopPanel && !rollingRune && !shrineAvailable && currentSegment == ShopRoomIndex && ActiveEnemiesInCurrentArea() <= 0;
        }

        private void TryOpenShop()
        {
            if (!shopKeeper || !shopPanel || rollingRune || shrineAvailable) return;
            if (ActiveEnemiesInCurrentArea() > 0)
            {
                noticeText.text = "先清理当前区域，再使用补给";
                return;
            }
            if (Vector2.Distance(player.transform.position, shopKeeper.transform.position) > 2.4f)
            {
                noticeText.text = "靠近符文商人才能补给";
                return;
            }
            shopVisitedThisStage = true;
            inputLocked = true;
            shopPanel.gameObject.SetActive(true);
            RefreshShopAffordability(false);
            noticeText.text = "符文商人：回血或用本局金币召出奖励 SLOT";
            AdvanceTutorial(6);
        }

        private void CloseShop()
        {
            if (!shopPanel) return;
            shopPanel.gameObject.SetActive(false);
            inputLocked = ModalWantsTimeFreeze();
            Time.timeScale = ModalWantsTimeFreeze() ? 0f : 1f;
        }

        private void BuyShopHeal()
        {
            if (shopHealSoldThisStage)
            {
                shopOfferText.text = "生命补给已售罄";
                RefreshShopAffordability(true);
                return;
            }
            if (coins < 50)
            {
                shopOfferText.text = $"金币不足：回血还差 {50 - coins}";
                RefreshShopAffordability(true);
                return;
            }
            coins -= 50;
            hp = Mathf.Min(maxHp, hp + maxHp * .5f);
            shopHealSoldThisStage = true;
            PlaySfx(sfxShop, .9f);
            shopOfferText.text = $"已恢复生命  当前金币 {coins}";
            SpawnTimedSprite("ShopHealFx_NoYellowPlate", CombatVfxSprite(0), player.transform.position + Vector3.up * .2f, new Vector2(1.05f, .030f), new Color(.88f, 1f, 1f, .36f), 8, .18f);
            RefreshShopAffordability(true);
            UpdateUi();
        }

        private void BuyShopRune()
        {
            if (shopRuneSoldThisStage)
            {
                shopOfferText.text = "奖励 SLOT 已售罄";
                RefreshShopAffordability(true);
                return;
            }
            if (coins < 100)
            {
                shopOfferText.text = $"本局金币不足：还差 {100 - coins}";
                RefreshShopAffordability(true);
                return;
            }
            coins -= 100;
            shopRuneSoldThisStage = true;
            PlaySfx(sfxShop, .9f);
            CloseShop();
            SpawnRuneShrine(false, Mathf.Clamp(shopKeeper.transform.position.x + 1.8f, LeftBound + 2f, RightBound - 2.5f));
            noticeText.text = "商人启封了 SLOT 宝箱：靠近后点启封";
            UpdateUi();
        }

        private void RefreshShopAffordability(bool preserveMessage)
        {
            if (!shopPanel || !shopPanel.gameObject.activeSelf) return;
            bool canHeal = !shopHealSoldThisStage && coins >= 50;
            bool canRune = !shopRuneSoldThisStage && coins >= 100;
            UpdateShopItem(shopHealButton, shopHealPriceText, shopHealStateText, shopHealAdviceText, shopHealRecommendText, canHeal, shopHealSoldThisStage, 50, C("#2E9D66"), "恢复 50% 生命", ShopHealAdvice(), ShopRecommendationBadge(RoomRewardKind.Heal, canHeal, shopHealSoldThisStage));
            UpdateShopItem(shopRuneButton, shopRunePriceText, shopRuneStateText, shopRuneAdviceText, shopRuneRecommendText, canRune, shopRuneSoldThisStage, 100, C("#20A8B8"), "本局金币启封", ShopRuneAdvice(), ShopRecommendationBadge(RoomRewardKind.Fate, canRune, shopRuneSoldThisStage));
            if (shopDecisionText) shopDecisionText.text = BuildShopDecisionText(canHeal, canRune);
            if (shopOfferText && !preserveMessage)
                shopOfferText.text = $"当前金币 {coins}  生命 {Mathf.CeilToInt(hp)}/{Mathf.CeilToInt(maxHp)}";
        }

        private static void UpdateShopButton(RectTransform button, bool available, string label, Color baseColor)
        {
            if (!button) return;
            var image = button.GetComponent<Image>();
            if (image) image.color = available ? baseColor : new Color(.36f, .42f, .48f, .86f);
            var text = button.GetComponentInChildren<Text>();
            if (text && !string.IsNullOrEmpty(label)) text.text = label;
        }

        private void UpdateShopItem(RectTransform button, Text priceText, Text stateText, Text adviceText, Text recommendText, bool available, bool sold, int price, Color baseColor, string readyText, string advice, string badge)
        {
            UpdateShopButton(button, available, "", baseColor);
            int shortage = Mathf.Max(0, price - coins);
            if (priceText)
            {
                priceText.text = sold ? "售罄" : $"{price} 金币";
                priceText.color = sold ? new Color(1f, 1f, 1f, .56f) : available ? C("#FFD66B") : C("#FF9A7A");
            }
            if (stateText)
            {
                stateText.text = sold ? "已购买" : available ? readyText : $"还差 {shortage} 金币";
                stateText.color = sold ? new Color(1f, 1f, 1f, .56f) : available ? C("#DDF7FF") : C("#FF9A7A");
            }
            if (adviceText)
            {
                adviceText.text = sold ? "本关已限购" : advice;
                adviceText.color = sold ? new Color(1f, 1f, 1f, .46f) : available ? new Color(.84f, .95f, 1f, .82f) : new Color(1f, .78f, .62f, .74f);
            }
            if (recommendText)
            {
                bool showBadge = !string.IsNullOrEmpty(badge);
                recommendText.gameObject.SetActive(showBadge);
                recommendText.text = showBadge ? badge : "";
                recommendText.color = badge == "优先" ? C("#FFE17A") : badge == "成型" || badge == "补强" ? C("#8FFFF6") : C("#DDF7FF");
                var plate = recommendText.transform.parent ? recommendText.transform.parent.Find(recommendText.name.Replace("RecommendBadge", "RecommendPlate")) : null;
                var plateImage = plate ? plate.GetComponent<Image>() : null;
                if (plateImage)
                {
                    plateImage.gameObject.SetActive(showBadge);
                    plateImage.color = new Color(.02f, .04f, .08f, showBadge ? .58f : 0f);
                }
            }
        }

        private string ShopRecommendationBadge(RoomRewardKind kind, bool available, bool sold)
        {
            if (sold) return "";
            float hpRatio = hp / Mathf.Max(1f, maxHp);
            int buildLevel = swordRuneLevel + dashRuneLevel + frostRuneLevel + thunderRuneLevel + shieldRuneLevel;
            if (kind == RoomRewardKind.Heal)
            {
                if (hpRatio <= .35f) return "优先";
                if (hpRatio <= .62f && available) return "推荐";
                if (hpRatio < .76f && currentSegment >= ShopRoomIndex) return "Boss前";
                return "";
            }
            if (hpRatio <= .35f && !shopHealSoldThisStage) return "";
            if (runeCount < 2) return "成型";
            if (buildLevel < 4) return "补强";
            return available ? "节奏" : "";
        }

        private string BuildShopDecisionText(bool canHeal, bool canRune)
        {
            float hpRatio = hp / Mathf.Max(1f, maxHp);
            if (shopHealSoldThisStage && shopRuneSoldThisStage) return "售罄：离开推进";
            if (hpRatio <= .35f && !shopHealSoldThisStage) return canHeal ? "低血：先回血" : "低血：金币不足";
            if (runeCount < 2 && !shopRuneSoldThisStage) return canRune ? "成型：买 SLOT" : "成型：差金币";
            if (currentSegment >= EliteRoomIndex && !shopHealSoldThisStage && hpRatio < .70f) return canHeal ? "Boss 前：补生命" : "Boss 前：稳住距离";
            if (!shopRuneSoldThisStage && canRune) return "安全：买 SLOT";
            if (!shopHealSoldThisStage && canHeal) return "可回血：离开前决定";
            return "金币不足：清房开箱";
        }

        private string ShopHealAdvice()
        {
            float hpRatio = hp / Mathf.Max(1f, maxHp);
            if (shopHealSoldThisStage) return "本关已限购";
            if (hpRatio <= .35f) return coins >= 50 ? "低血回血" : "先攒 50";
            if (currentSegment >= EliteRoomIndex) return coins >= 50 ? "Boss 前容错" : "留钱回血";
            if (shieldRuneLevel > 0 || frostRuneLevel > 0) return "容错足，看 SLOT";
            return "稳健续航";
        }

        private string ShopRuneAdvice()
        {
            float hpRatio = hp / Mathf.Max(1f, maxHp);
            if (shopRuneSoldThisStage) return "本关已限购";
            if (hpRatio <= .35f && !shopHealSoldThisStage) return "低血先回血";
            if (runeCount < 2) return coins >= 100 ? "尽快成型" : "攒 100";
            if (swordRuneLevel + dashRuneLevel + frostRuneLevel + thunderRuneLevel + shieldRuneLevel < 4) return "补强打法";
            if (currentSegment >= EliteRoomIndex) return "Boss 前补强";
            return "买节奏";
        }

        private IEnumerator RollRune()
        {
            rollingRune = true;
            inputLocked = true;
            CaptureRuneBuildSnapshot();
            if (runePanel)
            {
                runePanel.SetAsLastSibling();
                runePanel.gameObject.SetActive(true);
            }
            PrepareRuneChestOpeningPanel();
            yield return PlayRuneChestOpeningSequence();
            if (runeBuildDeltaText) runeBuildDeltaText.text = "变化：符文石启封中";
            if (runeBuildDeltaText) runeBuildDeltaText.color = C("#DDF7FF");
            string a = "?", b = "?", c = "?";
            for (int i = 0; i < 18; i++)
            {
                a = runeSymbols[rng.Next(runeSymbols.Length)];
                b = runeSymbols[rng.Next(runeSymbols.Length)];
                c = runeSymbols[rng.Next(runeSymbols.Length)];
                SetRunePanelSlots(a, b, c, "SLOT 启封中", "符文石正在减速，等待命运共鸣", false);
                if (worldRuneText) worldRuneText.text = "";
                if (i % 4 == 0) PlaySfx(sfxRuneRoll, .45f);
                yield return new WaitForSeconds(.055f + i * .006f);
            }
            if (rng.NextDouble() < .55) b = a;
            if (rng.NextDouble() < .28) c = a;
            bool triple = a == b && b == c;
            bool pair = a == b || a == c || b == c;
            SetRunePanelSlots(a, b, c, triple ? "三星共鸣" : pair ? "二星共鸣" : "逆运祝福", pair ? "流派强化" : "保底回血", true);
            if (worldRuneText) worldRuneText.text = "";
            ApplyRuneReward(a, b, c);
            if (runeRewardText) runeRewardText.text = RunePanelRewardText();
            if (runeBuildDeltaText) runeBuildDeltaText.text = RuneBuildDeltaText();
            if (runeBuildDeltaText) runeBuildDeltaText.color = triple ? C("#FFE17A") : pair ? C("#9FF8FF") : C("#9FE6B8");
            PlaySfx(sfxRuneReward, 1f);
            HapticPulse(HapticTier.Reward);
            yield return new WaitForSeconds(1.05f);
            if (slotShrine) Destroy(slotShrine);
            shrineAvailable = false;
            if (currentShrineCompletesStage) stageRuneResolved = true;
            currentShrineCompletesStage = false;
            rollingRune = false;
            lastRuneRollFinishTime = Time.time;
            inputLocked = false;
            if (runePanel) runePanel.gameObject.SetActive(false);
            TriggerRoomEnterCue(currentSegment);
        }

        private IEnumerator PlayRuneChestOpeningSequence()
        {
            SetRuneChestRewardOptionsVisible(false);
            if (runeChestPhaseText) runeChestPhaseText.text = "1/3 宝箱开盖";
            if (runePanelText) runePanelText.text = "宝箱正在开盖";
            if (runeChestBodyUi) runeChestBodyUi.localScale = new Vector3(.985f, .985f, 1f);
            if (runeChestGlowUi) runeChestGlowUi.GetComponent<Image>().color = new Color(.13f, .84f, 1f, .045f);
            yield return new WaitForSeconds(.12f);

            SetRuneChestOpenState(true);
            SpawnRuneChestUiOpenFlash();
            yield return new WaitForSeconds(.18f);

            if (runeChestPhaseText) runeChestPhaseText.text = "2/3 符文启封";
            if (runePanelText) runePanelText.text = "选择槽显现";
            SetRuneChestRewardOptionsVisible(true);
            SpawnRuneChestRewardTrayReveal();
            yield return new WaitForSeconds(.08f);
        }

        private void SpawnRuneChestRewardTrayReveal()
        {
            if (!runePanel) return;
            var clamp = UIBox("RuneChestRewardTrayRevealClamp", runePanel, new Vector2(0, -188), new Vector2(1548, 10), new Vector2(.5f, .5f), new Vector2(.5f, .5f), new Color(.78f, .98f, 1f, .24f));
            Destroy(clamp.gameObject, .12f);
            for (int i = 0; i < runeSlotRoots.Count; i++)
            {
                if (!runeSlotRoots[i]) continue;
                runeSlotRoots[i].localScale = Vector3.one * 1.035f;
                StartCoroutine(ResetRuneSlotScale(runeSlotRoots[i], .10f));
            }
        }

        private IEnumerator ResetRuneSlotScale(RectTransform slot, float duration)
        {
            float timer = duration;
            while (timer > 0f && slot)
            {
                timer -= Time.deltaTime;
                float t = 1f - Mathf.Clamp01(timer / duration);
                float scale = Mathf.Lerp(1.035f, 1f, t);
                slot.localScale = Vector3.one * scale;
                yield return null;
            }
            if (slot) slot.localScale = Vector3.one;
        }

        private void PrepareRuneChestOpeningPanel()
        {
            if (runePanelText) runePanelText.text = "宝箱开盖";
            if (runeRewardText) runeRewardText.text = "三枚符文即将弹出";
            if (runeBuildDeltaText) runeBuildDeltaText.text = "变化：等待结果";
            if (runeChestPhaseText) runeChestPhaseText.text = "1/3 宝箱开盖";
            if (runeResonanceGradeText)
            {
                runeResonanceGradeText.text = "开启宝箱 · 触发 SLOT";
                runeResonanceGradeText.color = new Color(.82f, .96f, 1f, .82f);
            }
            SetRuneChestOpenState(false);
            SetRuneChestRewardOptionsVisible(false);
            for (int i = 0; i < runeSlotTexts.Count; i++)
            {
                if (runeSlotTexts[i])
                {
                    runeSlotTexts[i].text = "";
                    runeSlotTexts[i].fontSize = 236;
                    runeSlotTexts[i].color = new Color(.86f, .98f, 1f, .42f);
                }
                if (i < runeSlotBackplates.Count && runeSlotBackplates[i])
                    runeSlotBackplates[i].color = new Color(.06f, .14f, .20f, .24f);
            }
        }

        private void SpawnRuneChestUiOpenFlash()
        {
            if (!runePanel) return;
            var line = UIBox("RuneChestOpenUiLine", runePanel, new Vector2(0, 132), new Vector2(830, 8), new Vector2(.5f, .5f), new Vector2(.5f, .5f), new Color(.80f, .98f, 1f, .34f));
            Destroy(line.gameObject, .12f);
            var core = UICircle("RuneChestOpenUiCore", runePanel, new Vector2(0, 148), new Vector2(360, 92), new Vector2(.5f, .5f), new Vector2(.5f, .5f), new Color(.38f, .96f, 1f, .045f));
            Destroy(core.gameObject, .14f);
            var reveal = UIBox("RuneChestOpenUiRevealBeam", runePanel, new Vector2(0, 86), new Vector2(520, 6), new Vector2(.5f, .5f), new Vector2(.5f, .5f), new Color(.78f, .98f, 1f, .26f));
            Destroy(reveal.gameObject, .14f);
        }

        private void SetRunePanelSlots(string a, string b, string c, string stateText, string rewardText, bool resolved)
        {
            if (runePanelText) runePanelText.text = stateText;
            if (runeRewardText) runeRewardText.text = rewardText;
            if (runeComplianceText) runeComplianceText.text = RuneComplianceLine();
            if (runeChestPhaseText) runeChestPhaseText.text = resolved ? "3/3 共鸣结算" : "2/3 符文启封";
            SetRuneChestRewardOptionsVisible(true);
            SetRuneChestOpenState(resolved || rollingRune);
            UpdateRuneResonanceGrade(a, b, c, resolved);
            string[] values = { a, b, c };
            bool triple = a == b && b == c;
            bool pair = a == b || a == c || b == c;
            string key = triple ? a : pair ? (a == b || a == c ? a : b) : "";
            for (int i = 0; i < runeSlotTexts.Count && i < values.Length; i++)
            {
                var symbol = values[i];
                runeSlotTexts[i].text = symbol;
                runeSlotTexts[i].color = RuneSymbolColor(symbol);
                runeSlotTexts[i].fontSize = resolved ? 284 : 236;
                if (i >= runeSlotBackplates.Count || !runeSlotBackplates[i]) continue;
                bool matched = pair && symbol == key;
                runeSlotBackplates[i].color = resolved
                    ? matched ? new Color(1f, .84f, .32f, .72f) : new Color(.10f, .18f, .25f, .94f)
                    : new Color(.07f + i * .012f, .18f, .24f, .78f);
            }
        }

        private void SetRuneChestOpenState(bool opened)
        {
            if (runeChestLidUi)
            {
                runeChestLidUi.anchoredPosition = opened ? new Vector2(0, 286) : new Vector2(0, 206);
                runeChestLidUi.localRotation = Quaternion.identity;
                runeChestLidUi.localScale = opened ? new Vector3(.96f, .52f, 1f) : Vector3.one;
            }
            if (runeChestGlowUi)
            {
                runeChestGlowUi.sizeDelta = opened ? new Vector2(1120, 450) : new Vector2(900, 386);
                runeChestGlowUi.anchoredPosition = opened ? new Vector2(0, 146) : new Vector2(0, 116);
                runeChestGlowUi.GetComponent<Image>().color = opened ? new Color(.20f, .95f, 1f, .12f) : new Color(.13f, .84f, 1f, .085f);
            }
            if (runeChestBodyUi)
                runeChestBodyUi.localScale = opened ? new Vector3(1.03f, 1f, 1f) : Vector3.one;
        }

        private void SetRuneChestRewardOptionsVisible(bool visible)
        {
            if (runeChestOpenedRewardTrayUi) runeChestOpenedRewardTrayUi.gameObject.SetActive(visible);
            for (int i = 0; i < runeSlotRoots.Count; i++)
            {
                if (runeSlotRoots[i]) runeSlotRoots[i].gameObject.SetActive(visible);
            }
        }

        private void UpdateRuneResonanceGrade(string a, string b, string c, bool resolved)
        {
            if (!runeResonanceGradeText) return;
            if (!resolved)
            {
                runeResonanceGradeText.text = "启封中...";
                runeResonanceGradeText.color = new Color(.82f, .96f, 1f, .76f);
                return;
            }
            bool triple = a == b && b == c;
            bool pair = a == b || a == c || b == c;
            if (triple)
            {
                runeResonanceGradeText.text = "★★★ 三星共鸣：核心流派成型";
                runeResonanceGradeText.color = C("#FFD66B");
            }
            else if (pair)
            {
                runeResonanceGradeText.text = "★★ 二星共鸣：战斗能力强化";
                runeResonanceGradeText.color = C("#7EDCFF");
            }
            else
            {
                runeResonanceGradeText.text = "逆运祝福：无共鸣保底回血";
                runeResonanceGradeText.color = C("#8FF7A7");
            }
        }

        private static Color RuneSymbolColor(string symbol)
        {
            if (symbol == "剑") return C("#FF6B5E");
            if (symbol == "闪") return C("#56E7FF");
            if (symbol == "冰") return C("#BCEBFF");
            if (symbol == "雷") return C("#FFD66B");
            if (symbol == "盾") return C("#8FF7A7");
            if (symbol == "财") return C("#FFB84D");
            return Color.white;
        }

        private static string RuneComplianceLine()
        {
            return "本局战斗奖励，无真钱付费/现金价值；约25%三星、57%二星、18%逆运祝福保底回血。";
        }

        private static string RuneOddsHudLine()
        {
            return "概率 25/57/18 · 无现金价值";
        }

        private void ApplyRuneReward(string a, string b, string c)
        {
            bool triple = a == b && b == c;
            bool pair = a == b || a == c || b == c;
            string key = triple ? a : pair ? (a == b || a == c ? a : b) : "";
            runeCount++;
            if (!pair)
            {
                hp = Mathf.Min(maxHp, hp + maxHp * .2f);
                lastRune = "逆运祝福：生命恢复";
                lastRuneDetail = "保底恢复 20% 生命，稳住血线继续推进";
                RecordRuneHistory(lastRune);
                noticeText.text = $"{lastRune}  |  {lastRuneDetail}";
                SpawnTimedSprite("RuneRewardAura_NoYellowPlate", CombatVfxSprite(0), player.transform.position, new Vector2(1.28f, .034f), new Color(.88f, 1f, 1f, .30f), 8, .18f);
                return;
            }
            float scale = triple ? 1f : .38f;
            if (key == "剑") { swordRuneLevel += triple ? 2 : 1; attackMultiplier += .22f * scale; lastRune = triple ? "三星共鸣：剑气分裂" : "二星共鸣：剑气变宽"; }
            else if (key == "闪") { dashRuneLevel += triple ? 2 : 1; moveMultiplier += .18f * scale; lastRune = triple ? "三星共鸣：闪避留痕" : "二星共鸣：移动提升"; }
            else if (key == "冰") { frostRuneLevel += triple ? 2 : 1; maxMp += 18f * scale; mp = maxMp; lastRune = triple ? "三星共鸣：冰霜新星扩大" : "二星共鸣：魔力提升"; }
            else if (key == "雷") { thunderRuneLevel += triple ? 2 : 1; skillCooldowns[SkillKind.ThunderStrike] = 0; attackMultiplier += .12f * scale; lastRune = triple ? "三星共鸣：连锁电弧" : "二星共鸣：雷伤提升"; }
            else if (key == "盾") { shieldRuneLevel += triple ? 2 : 1; maxHp += 32f * scale; hp += 32f * scale; lastRune = triple ? "三星共鸣：坚盾护体" : "二星共鸣：生命提升"; }
            else { coins += triple ? 150 : 45; lastRune = triple ? "三星共鸣：贪婪金币" : "二星共鸣：金币"; }
            lastRuneDetail = RuneTacticalHint(key, triple);
            RecordRuneHistory(lastRune);
            noticeText.text = $"{lastRune}  |  {lastRuneDetail}";
            SpawnTimedSprite(triple ? "RuneTripleRewardAura_NoYellowPlate" : "RunePairRewardAura_NoYellowPlate", CombatVfxSprite(0), player.transform.position, new Vector2((triple ? 1.56f : 1.20f) + runeCount * .025f, triple ? .040f : .032f), new Color(triple ? .98f : .72f, triple ? 1f : .96f, 1f, triple ? .36f : .26f), 8, triple ? .22f : .16f);
        }

        private string RunePanelRewardText()
        {
            return $"{lastRune}\n{CurrentBuildStyle()} · {ShortRuneTacticalHint(lastRuneDetail)}";
        }

        private void CaptureRuneBuildSnapshot()
        {
            runeSnapshotSwordLevel = swordRuneLevel;
            runeSnapshotDashLevel = dashRuneLevel;
            runeSnapshotFrostLevel = frostRuneLevel;
            runeSnapshotThunderLevel = thunderRuneLevel;
            runeSnapshotShieldLevel = shieldRuneLevel;
            runeSnapshotBuildStyle = CurrentBuildStyle();
        }

        private string RuneBuildDeltaText()
        {
            var changes = new List<string>();
            AppendRuneDelta(changes, "剑", runeSnapshotSwordLevel, swordRuneLevel);
            AppendRuneDelta(changes, "闪", runeSnapshotDashLevel, dashRuneLevel);
            AppendRuneDelta(changes, "冰", runeSnapshotFrostLevel, frostRuneLevel);
            AppendRuneDelta(changes, "雷", runeSnapshotThunderLevel, thunderRuneLevel);
            AppendRuneDelta(changes, "盾", runeSnapshotShieldLevel, shieldRuneLevel);
            int beforeTotal = runeSnapshotSwordLevel + runeSnapshotDashLevel + runeSnapshotFrostLevel + runeSnapshotThunderLevel + runeSnapshotShieldLevel;
            int afterTotal = swordRuneLevel + dashRuneLevel + frostRuneLevel + thunderRuneLevel + shieldRuneLevel;
            if (changes.Count == 0)
            {
                if (lastRune.Contains("贪婪") || lastRune.Contains("金币"))
                    return $"变化：金币补给 · {runeSnapshotBuildStyle} Lv{beforeTotal}";
                return $"变化：回血保底 · {runeSnapshotBuildStyle} Lv{beforeTotal}";
            }
            return $"变化：{string.Join(" / ", changes.Take(3).ToArray())} · Lv{beforeTotal}->{afterTotal}";
        }

        private static void AppendRuneDelta(List<string> changes, string label, int before, int after)
        {
            if (after > before) changes.Add($"{label}{before}->{after}");
        }

        private string CurrentBuildStyle()
        {
            int maxLevel = Mathf.Max(swordRuneLevel, dashRuneLevel, frostRuneLevel, thunderRuneLevel, shieldRuneLevel);
            if (maxLevel <= 0) return "未成型";
            if (swordRuneLevel == maxLevel) return "光剑压制";
            if (dashRuneLevel == maxLevel) return "闪避游击";
            if (frostRuneLevel == maxLevel) return "冰环控场";
            if (thunderRuneLevel == maxLevel) return "雷链清场";
            return "坚盾续航";
        }

        private static string RuneTacticalHint(string key, bool triple)
        {
            if (key == "剑") return triple ? "第三段后用剑气清后排" : "普攻范围变宽，贴近连斩更稳";
            if (key == "闪") return triple ? "用闪避穿过敌群留下电弧" : "移动更快，拉开远程射线";
            if (key == "冰") return triple ? "冰环控住近身敌人再接三连" : "魔力上限提高，技能循环更宽裕";
            if (key == "雷") return triple ? "优先击杀小怪触发连锁电弧" : "雷击伤害提升，适合点杀精英";
            if (key == "盾") return triple ? "容错提高，可以主动贴 Boss 抢输出" : "生命提高，先稳住血线推进";
            return triple ? "金币充足，去商店用本局金币召出下一次 SLOT" : "补金币，优先留给商店启封";
        }

        private static string ShortRuneTacticalHint(string detail)
        {
            if (string.IsNullOrEmpty(detail)) return "打法已改变";
            if (detail.Contains("剑气")) return "三连后清后排";
            if (detail.Contains("普攻范围")) return "贴身连斩更稳";
            if (detail.Contains("闪避")) return "穿怪留痕";
            if (detail.Contains("移动")) return "走位更快";
            if (detail.Contains("冰环")) return "控住再三连";
            if (detail.Contains("魔力")) return "技能循环更宽";
            if (detail.Contains("连锁")) return "击杀触发雷链";
            if (detail.Contains("雷击")) return "点杀精英";
            if (detail.Contains("Boss")) return "贴身抢输出";
            if (detail.Contains("生命") || detail.Contains("血线")) return "血线更稳";
            if (detail.Contains("金币")) return "商店再启封";
            return detail.Length > 14 ? detail.Substring(0, 14) : detail;
        }

        private void RecordRuneHistory(string runeName)
        {
            if (string.IsNullOrEmpty(runeName)) return;
            runeHistory.Add($"{runeCount}. {runeName} - {CurrentBuildStyle()}");
            if (runeHistory.Count > 12) runeHistory.RemoveAt(0);
        }

        private float CurrentSegmentRight()
        {
            int index = Mathf.Clamp(currentSegment, 0, SegmentRights.Length - 1);
            return SegmentRights[index];
        }

        private float CurrentMovementRight()
        {
            float right = CurrentSegmentRight();
            if (currentSegment >= SegmentRights.Length - 1) return right;
            bool canAdvance = CurrentRoomCanAdvance(currentSegment);
            if (!canAdvance && RoomBlockingEnemyCount(currentSegment) <= 0)
                canAdvance = true;
            if (!canAdvance && player && StaleBehindEnemyLockShouldCatchUp(currentSegment, player.transform.position.x))
                canAdvance = true;
            if (!canAdvance && player && GateEdgeSoftUnlockShouldCatchUp(currentSegment, player.transform.position.x))
                canAdvance = true;
            float movementRight = canAdvance
                ? NextOpenMovementRight(currentSegment)
                : LockedRoomMovementRight(currentSegment);
            if (player && !canAdvance)
                movementRight = Mathf.Max(movementRight, Mathf.Min(CombatPocketMovementRight(currentSegment), player.transform.position.x + LockedGateFallbackReachAllowance));
            if (player)
            {
                int playerSegment = Mathf.Clamp(SegmentIndexForX(player.transform.position.x), 0, SegmentRights.Length - 1);
                if (playerSegment > currentSegment && player.transform.position.x > SegmentRights[currentSegment] + ForcedSegmentCatchupMargin)
                    movementRight = Mathf.Max(movementRight, playerSegment >= SegmentRights.Length - 1 ? SegmentRights[playerSegment] : NextOpenMovementRight(playerSegment));
            }
            return movementRight;
        }

        private float AllowedMovementRight(float playerX)
        {
            return Mathf.Max(CurrentMovementRight(), VisibleCombatApproachMovementRight(playerX));
        }

        private float VisibleCombatApproachMovementRight(float playerX)
        {
            int playerSegment = Mathf.Clamp(SegmentIndexForX(playerX), 0, SegmentRights.Length - 1);
            int pocketSegment = Mathf.Clamp(playerSegment + 2, 0, SegmentRights.Length - 1);
            float pocketRight = SegmentRights[pocketSegment];
            float nearestForwardEnemy = enemies
                .Where(e => e != null && !e.Dead && e.Root && e.Root.activeInHierarchy)
                .Select(e => e.Root.transform.position.x)
                .Where(x => x >= playerX - .20f && x <= pocketRight + .35f)
                .DefaultIfEmpty(float.NegativeInfinity)
                .Min();

            if (float.IsNegativeInfinity(nearestForwardEnemy))
                return LeftBound;

            return Mathf.Min(pocketRight, Mathf.Max(playerX + FalseClampEscapeForwardAllowance, nearestForwardEnemy + VisibleCombatApproachPadding));
        }

        private float LockedRoomMovementRight(int segment)
        {
            float right = SegmentRights[Mathf.Clamp(segment, 0, SegmentRights.Length - 1)];
            float pocketRight = CombatPocketMovementRight(segment);
            float lockedRight = Mathf.Min(pocketRight, right + LockedGateCombatReachAllowance);
            float furthestBlockingEnemy = enemies
                .Where(e => IsBlockingEnemyInSegment(e, segment))
                .Select(e => e.Root.transform.position.x)
                .DefaultIfEmpty(right - LockedGateStopBuffer)
                .Max();
            if (furthestBlockingEnemy > right - .02f)
                lockedRight = Mathf.Min(pocketRight, Mathf.Max(lockedRight, furthestBlockingEnemy + .48f));
            return Mathf.Max(LeftBound, Mathf.Max(lockedRight, pocketRight - LockedGateStopBuffer));
        }

        private void ReconcileMovementSegmentWithPlayerPosition()
        {
            if (!player || titleActive || rollingRune) return;
            int playerSegment = Mathf.Clamp(SegmentIndexForX(player.transform.position.x), 0, SegmentRights.Length - 1);
            if (playerSegment <= currentSegment) return;

            int targetSegment = currentSegment;
            for (int segment = currentSegment; segment < playerSegment; segment++)
            {
                bool physicallyPastGate = player.transform.position.x > SegmentRights[segment] + ForcedSegmentCatchupMargin;
                bool staleBehindLock = StaleBehindEnemyLockShouldCatchUp(segment, player.transform.position.x);
                bool gateEdgeSoftUnlock = GateEdgeSoftUnlockShouldCatchUp(segment, player.transform.position.x);
                if (!CurrentRoomCanAdvance(segment) && !staleBehindLock && !gateEdgeSoftUnlock && !physicallyPastGate && player.transform.position.x <= NextOpenMovementRight(segment) - LockedGateStopBuffer) break;
                targetSegment = segment + 1;
            }
            if (targetSegment <= currentSegment) return;

            currentSegment = Mathf.Clamp(targetSegment, 0, SegmentRights.Length - 1);
            UpdateRoomMarkers();
        }

        private bool StaleBehindEnemyLockShouldCatchUp(int segment, float playerX)
        {
            if (segment < 0 || segment >= SegmentRights.Length - 1) return false;
            float gateX = SegmentRights[segment];
            if (playerX <= gateX + StaleBehindEnemyGateMargin) return false;
            var blockers = enemies
                .Where(e => IsBlockingEnemyInSegment(e, segment))
                .Where(e => e.Root)
                .ToList();
            if (blockers.Count <= 0) return false;
            return blockers.All(e => e.Root.transform.position.x < playerX - StaleBehindEnemyUnlockMargin);
        }

        private bool GateEdgeSoftUnlockShouldCatchUp(int segment, float playerX)
        {
            if (segment < 0 || segment >= SegmentRights.Length - 1) return false;
            if (CurrentRoomCanAdvance(segment)) return false;
            float gateX = SegmentRights[segment];
            if (playerX < gateX - GateEdgeSoftUnlockRange) return false;
            var blockers = enemies
                .Where(e => IsBlockingEnemyInSegment(e, segment))
                .Where(e => e.Root)
                .ToList();
            if (blockers.Count <= 0) return false;
            return blockers.All(e => e.Root.transform.position.x < playerX - GateEdgeSoftUnlockBehindMargin);
        }

        private float CombatPocketMovementRight(int segment)
        {
            int pocket = Mathf.Clamp(segment + 2, 0, SegmentRights.Length - 1);
            return SegmentRights[pocket];
        }

        private float NextOpenMovementRight(int segment)
        {
            int next = Mathf.Clamp(segment + 1, 0, SegmentRights.Length - 1);
            return SegmentRights[next];
        }

        private int SegmentIndexForX(float x)
        {
            for (int i = 0; i < SegmentRights.Length; i++)
            {
                if (x <= SegmentRights[i] + .35f) return i;
            }
            return SegmentRights.Length - 1;
        }

        private RoomModifier RoomModifierAtPosition(float x)
        {
            return roomModifiers[Mathf.Clamp(SegmentIndexForX(x), 0, roomModifiers.Length - 1)];
        }

        private bool IsXInSegment(float x, int segment)
        {
            if (segment < 0 || segment >= SegmentRights.Length) return false;
            float right = SegmentRights[segment] + .35f;
            float left = segment > 0 ? SegmentRights[segment - 1] - .25f : LeftBound - .5f;
            return x > left && x <= right;
        }

        private bool ActivePlatformRuneVesselInSegment(int segment)
        {
            return runeVessels.Any(v => !v.Broken && v.Root && v.PlatformReward && IsXInSegment(v.Root.transform.position.x, segment));
        }

        private RuneVessel NearestPlatformRuneVesselInSegment(int segment)
        {
            if (!player) return null;
            float playerX = player.transform.position.x;
            return runeVessels
                .Where(v => !v.Broken && v.Root && v.PlatformReward && IsXInSegment(v.Root.transform.position.x, segment))
                .OrderBy(v => Mathf.Abs(v.Root.transform.position.x - playerX))
                .FirstOrDefault();
        }

        private RoomModifier CurrentRoomModifier()
        {
            return roomModifiers[Mathf.Clamp(currentSegment, 0, roomModifiers.Length - 1)];
        }

        private static string RoomModifierName(RoomModifier modifier)
        {
            if (modifier == RoomModifier.Swift) return "疾行";
            if (modifier == RoomModifier.Strong) return "强袭";
            if (modifier == RoomModifier.FateSurge) return "命运涌流";
            if (modifier == RoomModifier.JarCache) return "罐藏";
            if (modifier == RoomModifier.Precision) return "精准试炼";
            return "稳态";
        }

        private static string RoomModifierHint(RoomModifier modifier)
        {
            if (modifier == RoomModifier.Swift) return "限时清房，成功额外奖励";
            if (modifier == RoomModifier.Strong) return "敌人更硬更痛，房间奖励更高";
            if (modifier == RoomModifier.FateSurge) return "清房命运能量提高";
            if (modifier == RoomModifier.JarCache) return "平台小宝箱出现，打开可加速 SLOT";
            if (modifier == RoomModifier.Precision) return "极限闪避奖励提高";
            return "标准战斗条件";
        }

        private string CurrentRoomTitle()
        {
            return RoomTitle(Mathf.Clamp(currentSegment, 0, SegmentRights.Length - 1));
        }

        private string RoomTitle(int index)
        {
            index = Mathf.Clamp(index, 0, SegmentLabels.Length - 1);
            string title;
            if (index == 0) title = stageIndex == 1 ? "入口战斗房" : "推进战斗房";
            else if (index == 1) title = "短兵遭遇房";
            else if (index == 2) title = "远程伏击房";
            else if (index == ShopRoomIndex) title = "符文商店房";
            else if (index == 4) title = "混合战斗房";
            else if (index == EliteRoomIndex) title = "毒素精英房";
            else if (index == 6) title = "终战准备房";
            else title = stageIndex == 3 ? "守护者 Boss 房" : "终段战斗房";
            var modifier = roomModifiers[Mathf.Clamp(index, 0, roomModifiers.Length - 1)];
            return modifier == RoomModifier.Stable ? title : $"{title}·{RoomModifierName(modifier)}";
        }

        private Color RoomColor(int index)
        {
            if (index == ShopRoomIndex) return C("#60D98B");
            if (index == EliteRoomIndex) return C("#A7E65A");
            if (stageIndex == 3 && index == BossRoomIndex) return C("#FF6B6B");
            if (index == currentSegment) return C("#8FFFF6");
            return C("#7EDCFF");
        }

        private void UpdateRoomMarkers()
        {
            for (int i = 0; i < roomMarkerLabels.Count; i++)
            {
                var color = RoomColor(i);
                if (roomMarkerLabels[i])
                {
                    roomMarkerLabels[i].text = RoomTitle(i);
                    bool active = i == currentSegment;
                    bool special = i == ShopRoomIndex || i == EliteRoomIndex || (stageIndex == 3 && i == BossRoomIndex);
                    bool near = player && Mathf.Abs(player.transform.position.x - SegmentCenters[i]) < 4.6f;
                    float labelAlpha = active && near ? .20f : near && special ? .12f : 0f;
                    roomMarkerLabels[i].color = new Color(color.r, color.g, color.b, labelAlpha);
                }
                if (i < roomMarkerIcons.Count && roomMarkerIcons[i])
                    roomMarkerIcons[i].color = i < currentSegment
                        ? Color.clear
                        : i == currentSegment
                            ? Color.clear
                            : Color.clear;
                if (i < roomGates.Count)
                    UpdateRoomGateVisual(roomGates[i], i, color);
            }
            UpdateProgressGateVisuals();
        }

        private void UpdateProgressGateVisuals()
        {
            for (int i = 0; i < progressGates.Count; i++)
            {
                var gate = progressGates[i];
                if (!gate) continue;
                bool activeLockedGate = i == currentSegment && CurrentGateActuallyLocksPlayer(i);
                gate.SetActive(activeLockedGate);
                if (!activeLockedGate) continue;

                float pulse = .12f + Mathf.Sin(Time.time * 5.8f) * .030f;
                int enemiesLeft = RoomBlockingEnemyCount(i);
                float nearAlpha = LockedGateNearPlayerAlpha(gate);
                foreach (var sr in gate.GetComponentsInChildren<SpriteRenderer>())
                {
                    bool rune = sr.gameObject.name.Contains("_Rune");
                    bool door = sr.gameObject.name.Contains("_Door");
                    bool seal = sr.gameObject.name.Contains("_GroundSeal");
                    bool needle = sr.gameObject.name.Contains("_NearPlayerRuneNeedle");
                    bool tick = sr.gameObject.name.Contains("_NearPlayerGroundTick");
                    sr.color = rune
                        ? new Color(1f, 1f, 1f, pulse * .54f * nearAlpha)
                        : door
                            ? Color.clear
                            : seal
                                ? new Color(.18f, .92f, 1f, (.026f + pulse * .10f) * nearAlpha)
                                : needle
                                    ? new Color(.56f, .96f, 1f, (.052f + pulse * .15f) * nearAlpha)
                                    : tick
                                        ? new Color(.78f, 1f, .96f, (.055f + pulse * .13f) * nearAlpha)
                                        : Color.clear;
                }
                foreach (var tm in gate.GetComponentsInChildren<TextMesh>())
                {
                    bool arrow = tm.gameObject.name.Contains("_RightArrow");
                    if (!arrow) tm.text = enemiesLeft > 0 ? $"清敌 {enemiesLeft}" : "可通行";
                    tm.color = Color.clear;
                }
            }
        }

        private float LockedGateNearPlayerAlpha(GameObject gate)
        {
            if (!gate || !player) return 0f;
            float dx = Mathf.Abs(player.transform.position.x - gate.transform.position.x);
            float startFade = 4.15f;
            float fullFade = 1.20f;
            float t = Mathf.InverseLerp(startFade, fullFade, dx);
            bool pressingRight = player.transform.position.x > gate.transform.position.x - 1.05f && CurrentHorizontalMoveInput() > .12f;
            return Mathf.Clamp01(pressingRight ? Mathf.Max(t, .82f) : t);
        }

        private void ShowLockedGateBump()
        {
            if (gateBlockHintCooldown > 0f) return;
            gateBlockHintCooldown = .95f;
            string reason = LockedGateHintText();
            if (noticeText) noticeText.text = reason;
            if (currentSegment >= 0 && currentSegment < progressGates.Count && progressGates[currentSegment])
            {
                Vector3 gatePos = progressGates[currentSegment].transform.position;
                SpawnTimedSprite("LockedGateBumpEdgeTick_NoYellowPlate", CombatVfxSprite(0), gatePos + Vector3.up * .40f, new Vector2(.32f, .016f), new Color(.62f, .96f, 1f, .14f), 8, .10f);
                SpawnTimedSprite("LockedGateGroundSealPulse_NoYellowPlate", CombatVfxSprite(0), gatePos + Vector3.down * 1.02f, new Vector2(.42f, .014f), new Color(.56f, .96f, 1f, .075f), 8, .095f);
                SpawnLockedGateEnemyRouteCue(gatePos);
            }
            PlaySfx(sfxHit, .28f);
        }

        private void SpawnLockedGateEnemyRouteCue(Vector3 gatePos)
        {
            if (!fxRoot || !player || RoomBlockingEnemyCount(currentSegment) <= 0) return;
            Fighter target = NearestBlockingEnemyForLockedGate();
            if (target == null || !target.Root) return;

            Vector3 playerFoot = player.transform.position + Vector3.down * .56f;
            Vector3 enemyFoot = target.Root.transform.position + Vector3.down * (target.Boss ? .78f : .48f);
            bool targetBehindPlayer = enemyFoot.x < playerFoot.x - .20f;
            float dir = Mathf.Sign(enemyFoot.x - playerFoot.x);
            if (Mathf.Abs(dir) < .05f) dir = Mathf.Sign(gatePos.x - playerFoot.x);
            if (Mathf.Abs(dir) < .05f) dir = 1f;
            if (targetBehindPlayer && noticeText) noticeText.text = "门未开 · 回头清敌";

            Color cueColor = target.Boss ? C("#FF8A7A") : target.Elite ? C("#A8FF7A") : C("#9FF8FF");
            float alphaScale = effectsIntensity > .75f ? 1f : .68f;
            float routeDistance = Mathf.Clamp(Mathf.Abs(enemyFoot.x - playerFoot.x), .65f, 2.25f);
            var guide = SpawnTimedSprite("LockedGateNearestEnemyRouteLine_NoYellowPlate", CombatVfxSprite(0), playerFoot + Vector3.right * dir * routeDistance * .42f, new Vector2(routeDistance * .50f, .010f), new Color(cueColor.r, cueColor.g, cueColor.b, .065f * alphaScale), 8, .18f);
            if (guide) guide.transform.localScale = new Vector3(Mathf.Abs(guide.transform.localScale.x) * dir, guide.transform.localScale.y, 1f);

            int tickCount = Mathf.Clamp(Mathf.CeilToInt(routeDistance / .62f), 1, 3);
            for (int i = 0; i < tickCount; i++)
            {
                Vector3 tickPos = playerFoot + new Vector3(dir * (.42f + i * .42f), .06f + i * .012f, 0f);
                var tick = SpawnTimedSprite("LockedGateNearestEnemyRouteTick_NoYellowPlate", CombatVfxSprite(0), tickPos, new Vector2(.12f, .010f), new Color(.94f, 1f, 1f, .12f * alphaScale), 9, .12f + i * .035f);
                if (tick) tick.transform.localScale = new Vector3(Mathf.Abs(tick.transform.localScale.x) * dir, tick.transform.localScale.y, 1f);
            }

            SpawnTimedSprite("LockedGateNearestEnemyTargetFootPin_NoYellowPlate", CombatVfxSprite(0), enemyFoot, new Vector2(target.Boss ? .92f : target.Elite ? .62f : .42f, .016f), new Color(cueColor.r, cueColor.g, cueColor.b, (target.Boss ? .17f : .13f) * alphaScale), 10, .20f);
            SpawnTimedSprite("LockedGateNearestEnemyTargetBracket_NoYellowPlate", CombatVfxSprite(0), target.Root.transform.position + Vector3.up * (target.Boss ? 1.06f : .55f), new Vector2(target.Boss ? .72f : target.Elite ? .46f : .30f, .014f), new Color(.96f, 1f, 1f, .14f * alphaScale), 10, .16f);
        }

        private Fighter NearestBlockingEnemyForLockedGate()
        {
            if (!player) return null;
            return enemies
                .Where(enemy => IsBlockingEnemyInSegment(enemy, currentSegment))
                .OrderBy(enemy => Mathf.Abs(enemy.Root.transform.position.x - player.transform.position.x))
                .FirstOrDefault();
        }

        private string LockedGateHintText()
        {
            int enemiesLeft = RoomBlockingEnemyCount(currentSegment);
            if (enemiesLeft > 0) return $"门未开 · 清敌 {enemiesLeft}";
            if (currentSegment >= 0 && currentSegment < roomObjectives.Length && OptionalRoomObjectiveAllowsAdvance(currentSegment))
                return "可选开箱，不锁路，继续向右";
            return "通路已开 · 向右";
        }

        private void UpdateRoomGateVisual(RoomGateState gate, int index, Color roomColor)
        {
            if (gate == null || !gate.Root) return;
            bool completed = index < currentSegment;
            bool active = index == currentSegment;
            bool special = index == ShopRoomIndex || index == EliteRoomIndex || (stageIndex == 3 && index == BossRoomIndex);
            Color doorColor = Color.clear;
            if (gate.LeftDoor)
            {
                gate.LeftDoor.color = doorColor;
                gate.LeftDoor.transform.localPosition = completed ? new Vector3(-.17f, -.27f, 0) : new Vector3(-.11f, -.27f, 0);
            }
            if (gate.RightDoor)
            {
                gate.RightDoor.color = doorColor;
                gate.RightDoor.transform.localPosition = completed ? new Vector3(.17f, -.27f, 0) : new Vector3(.11f, -.27f, 0);
            }
            if (gate.LockGlow)
            {
                gate.LockGlow.color = Color.clear;
                gate.LockGlow.gameObject.SetActive(!completed);
            }
            if (gate.StateLabel)
            {
                string state = CurrentRoomGateStateText(index);
                bool combatActive = ActiveEnemiesInCurrentArea() > 0;
                bool specialRoom = index == ShopRoomIndex || index == EliteRoomIndex || index == BossRoomIndex;
                bool nearPlayer = player && Mathf.Abs(player.transform.position.x - SegmentCenters[Mathf.Clamp(index, 0, SegmentCenters.Length - 1)]) < RoomGateStateTextNearDistance;
                bool showState = !completed && !combatActive && nearPlayer && specialRoom;
                gate.StateLabel.text = showState ? state : "";
                float stateAlpha = active ? .18f + Mathf.Sin(Time.time * 5.4f) * .030f : .12f;
                gate.StateLabel.color = showState ? new Color(roomColor.r, roomColor.g, roomColor.b, stateAlpha * (effectsIntensity > .75f ? 1f : .72f)) : Color.clear;
                gate.StateLabel.transform.localScale = Vector3.one * (active ? .98f : .92f);
            }
            UpdateRoomGateSpecialBadge(gate, index, completed, active, roomColor);
        }

        private void UpdateRoomGateSpecialBadge(RoomGateState gate, int index, bool completed, bool active, Color roomColor)
        {
            if (gate == null) return;
            string badge = RoomGateSpecialBadgeLabel(index);
            bool combatActive = ActiveEnemiesInCurrentArea() > 0;
            bool nearPlayer = player && Mathf.Abs(player.transform.position.x - SegmentCenters[Mathf.Clamp(index, 0, SegmentCenters.Length - 1)]) < RoomGateSpecialBadgeNearDistance;
            bool show = !completed && !string.IsNullOrEmpty(badge) && nearPlayer && !combatActive;
            float alphaScale = effectsIntensity > .75f ? 1f : .72f;
            float pulse = active ? .42f + Mathf.Sin(Time.time * 5.2f) * .080f : .26f;
            Color color = RoomGateSpecialBadgeColor(index);
            if (gate.SpecialBand)
            {
                gate.SpecialBand.gameObject.SetActive(show);
                float bandAlpha = show ? Mathf.Clamp01((active ? pulse * .10f : pulse * .070f) * alphaScale) : 0f;
                gate.SpecialBand.color = new Color(color.r, color.g, color.b, bandAlpha);
                gate.SpecialBand.transform.localScale = new Vector3(1f + (active ? Mathf.Sin(Time.time * 6.4f) * .025f : 0f), 1f, 1f);
            }
            if (!gate.SpecialBadge) return;
            gate.SpecialBadge.text = show ? badge : "";
            gate.SpecialBadge.color = show ? new Color(color.r, color.g, color.b, Mathf.Clamp01(pulse * .22f * alphaScale)) : Color.clear;
            gate.SpecialBadge.transform.localScale = Vector3.one * (active ? .98f : .88f);
        }

        private static string RoomGateSpecialBadgeLabel(int index)
        {
            if (index == ShopRoomIndex) return "补给";
            if (index == EliteRoomIndex) return "精英";
            if (index == BossRoomIndex) return "BOSS";
            return "";
        }

        private Color RoomGateSpecialBadgeColor(int index)
        {
            if (index == ShopRoomIndex) return C("#77FFAE");
            if (index == EliteRoomIndex) return C("#A7E65A");
            if (stageIndex == 3 && index == BossRoomIndex) return C("#FF8A66");
            if (index == BossRoomIndex) return C("#FF8A66");
            return new Color(.86f, .96f, 1f, .72f);
        }

        private string CurrentRoomGateStateText(int index)
        {
            if (shrineAvailable) return "待启封";
            if (index == ShopRoomIndex) return ActiveEnemiesInCurrentArea() > 0 ? "清场" : "可补给";
            if (index == EliteRoomIndex) return "精英锁定";
            if (index == BossRoomIndex) return stageIndex == 3 ? "Boss 锁定" : "终段锁定";
            if (RoomBlockingEnemyCount(index) <= 0 && index >= 0 && index < roomObjectives.Length && roomObjectives[index] == RoomObjective.BreakRuneCache && ActivePlatformRuneVesselInSegment(index)) return "可选开箱";
            var modifier = roomModifiers[Mathf.Clamp(index, 0, roomModifiers.Length - 1)];
            if (RoomBlockingEnemyCount(index) > 0 && index >= 0 && index < roomObjectives.Length && roomObjectives[index] == RoomObjective.TimedClear) return "限时清房";
            if (ActiveEnemiesInCurrentArea() > 0 && modifier != RoomModifier.Stable) return RoomModifierName(modifier);
            return ActiveEnemiesInCurrentArea() > 0 ? "战斗中" : "可通行";
        }

        private void UpdatePlatformRewardGuideDeclutter()
        {
            if (!propRoot || !player) return;
            foreach (var label in propRoot.GetComponentsInChildren<TextMesh>(true))
            {
                if (!label) continue;
                bool platformGuide = label.gameObject.name.Contains("PlatformRewardGuideText_");
                bool objectiveGuide = label.gameObject.name.Contains("ObjectiveRuneGuideText_");
                if (!platformGuide && !objectiveGuide) continue;
                float distance = Vector2.Distance(label.transform.position, player.transform.position);
                bool currentRoomGuide = IsXInSegment(label.transform.position.x, currentSegment);
                bool close = distance < 2.6f;
                bool cleared = ActiveEnemiesInCurrentArea() <= 0;
                float alpha = close && cleared ? .58f : objectiveGuide && currentRoomGuide && cleared && distance < 4.2f ? .14f : 0f;
                Color baseColor = objectiveGuide ? C("#9FF8FF") : C("#BFEFFF");
                label.text = close && cleared ? (objectiveGuide ? "奖励箱" : "小宝箱") : "";
                label.color = new Color(baseColor.r, baseColor.g, baseColor.b, alpha);
            }
        }

        private void TriggerRoomEnterCue(int segment)
        {
            if (segment < 0 || segment >= SegmentCenters.Length || segment == lastRoomCueSegment || !fxRoot) return;
            lastRoomCueSegment = segment;
            roomPerfectDodgeStart[segment] = perfectDodgesThisRun;
            roomEnterRunTime[segment] = runTime;
            roomQuickRunStart[segment] = quickRunTimeThisRun;
            roomBannerTimer = 2.2f;
            string title = RoomTitle(segment);
            string subtitle = RoomEnterSubtitle(segment);
            Color color = RoomColor(segment);
            noticeText.text = $"进入：{title}  |  {subtitle}";
            var pos = new Vector2(SegmentCenters[segment], GroundY + 2.65f);
            string worldLabel = RoomEnterWorldLabel(segment);
            if (!string.IsNullOrEmpty(worldLabel))
            {
                var text = WorldText("RoomEnterCue", fxRoot, worldLabel, pos, segment == BossRoomIndex ? 30 : 22, 34);
                text.color = new Color(color.r, color.g, color.b, segment == BossRoomIndex ? .82f : .56f);
                DestroyRuntimeObject(text.gameObject, segment == BossRoomIndex ? .92f : .54f);
            }
            SpawnTimedSprite("RoomEnterGroundLine_NoYellowPlate", CombatVfxSprite(0), new Vector2(SegmentCenters[segment], GroundY + .32f), new Vector2(segment == BossRoomIndex ? 1.62f : .86f, segment == BossRoomIndex ? .034f : .024f), new Color(color.r, color.g, color.b, segment == BossRoomIndex ? .20f : .12f), 5, segment == BossRoomIndex ? .20f : .14f);
            SpawnModifierRoomBonus(segment);
            if (segment == ShopRoomIndex)
                SpawnTimedSprite("ShopRoomWelcomeFx_NoYellowPlate", CombatVfxSprite(0), new Vector2(SegmentCenters[segment], GroundY + 1.25f), new Vector2(.54f, .026f), new Color(.82f, 1f, 1f, .22f), 7, .22f);
            else if (segment == EliteRoomIndex)
            {
                SpawnTimedSprite("EliteRoomWarningFx_NoYellowPlate", CombatVfxSprite(0), new Vector2(SegmentCenters[segment], GroundY + 1.1f), new Vector2(.96f, .030f), new Color(.45f, 1f, .35f, .20f), 8, .18f);
                TriggerCombatFlash(.08f, .12f);
            }
            else if (segment == BossRoomIndex)
            {
                var lockWarn = RectObj("BossRoomLockWarn_NoYellowPlate", fxRoot, new Vector2(SegmentRights[BossRoomIndex - 1] + .28f, GroundY + 1.6f), new Vector2(.055f, 2.45f), new Color(1f, .12f, .08f, .18f), 8);
                DestroyRuntimeObject(lockWarn, 1.1f);
                SpawnTimedSprite("BossRoomWarningFx_NoYellowPlate", CombatVfxSprite(0), new Vector2(SegmentCenters[segment], GroundY + 1.2f), new Vector2(1.45f, .034f), new Color(1f, .16f, .12f, .22f), 8, .20f);
                PlaySfx(sfxBossWarn, .86f);
                TriggerCombatFlash(.14f, .18f);
                ShakeCamera(.055f, .22f);
            }
            SpawnRoomCombatWaveCue(segment);
        }

        private void SpawnRoomCombatWaveCue(int segment)
        {
            if (!fxRoot || segment == ShopRoomIndex) return;
            var roomEnemies = enemies
                .Where(e => e != null && !e.Dead && e.Root && IsXInSegment(e.Root.transform.position.x, segment))
                .OrderBy(e => e.Root.transform.position.x)
                .Take(3)
                .ToList();
            if (roomEnemies.Count <= 0) return;

            bool bossRoom = segment == BossRoomIndex;
            Vector2 center = new Vector2(SegmentCenters[Mathf.Clamp(segment, 0, SegmentCenters.Length - 1)], GroundY + .52f);
            Color laneColor = bossRoom ? C("#FF8A7A") : segment == EliteRoomIndex ? C("#A8FF7A") : C("#8FFFF6");
            SpawnTimedSprite("RoomWaveEntryLane_NoYellowPlate", CombatVfxSprite(0), center, new Vector2(bossRoom ? 1.46f : .94f, bossRoom ? .030f : .022f), new Color(laneColor.r, laneColor.g, laneColor.b, bossRoom ? .20f : .13f), 6, bossRoom ? .22f : .14f);

            foreach (var enemy in roomEnemies)
                SpawnRoomWaveEnemyPin(enemy, bossRoom);
        }

        private void SpawnRoomWaveEnemyPin(Fighter enemy, bool bossRoom)
        {
            if (enemy == null || !enemy.Root) return;
            Vector3 pos = enemy.Root.transform.position;
            bool highThreat = enemy.Boss || enemy.Elite || enemy.Kind == EnemyKind.Archer;
            Color color = enemy.Boss ? C("#FF7A68") : enemy.Elite ? C("#A8FF7A") : enemy.Kind == EnemyKind.Archer ? C("#FFB6A8") : C("#BDEAFF");
            float alphaScale = effectsIntensity > .75f ? 1f : .72f;
            SpawnTimedSprite("RoomWaveEnemyEntryPin_NoYellowPlate", CombatVfxSprite(0), pos + Vector3.down * .58f, new Vector2(highThreat ? .52f : .34f, highThreat ? .024f : .018f), new Color(color.r, color.g, color.b, (highThreat ? .22f : .12f) * alphaScale), 7, bossRoom ? .20f : .13f);
            if (highThreat)
                SpawnTimedSprite("RoomWaveThreatBracket_NoYellowPlate", CombatVfxSprite(0), pos + Vector3.up * (enemy.Boss ? .82f : .46f), new Vector2(enemy.Boss ? .72f : .42f, .020f), new Color(color.r, color.g, color.b, (enemy.Boss ? .24f : .16f) * alphaScale), 8, bossRoom ? .22f : .14f);
        }

        private string RoomEnterWorldLabel(int segment)
        {
            if (segment == BossRoomIndex) return "Boss 房";
            if (segment == EliteRoomIndex) return "精英";
            if (segment == ShopRoomIndex) return "补给";
            if (roomModifiers[Mathf.Clamp(segment, 0, roomModifiers.Length - 1)] != RoomModifier.Stable) return RoomModifierName(roomModifiers[Mathf.Clamp(segment, 0, roomModifiers.Length - 1)]);
            return "";
        }

        private string RoomEnterSubtitle(int segment)
        {
            var modifier = roomModifiers[Mathf.Clamp(segment, 0, roomModifiers.Length - 1)];
            if (modifier == RoomModifier.JarCache && segment != ShopRoomIndex && segment != BossRoomIndex)
                return "跳上平台打开小宝箱，加速 SLOT";
            if (modifier != RoomModifier.Stable && segment != ShopRoomIndex && segment != BossRoomIndex)
                return $"{RoomModifierName(modifier)}：{RoomModifierHint(modifier)}";
            if (segment == ShopRoomIndex) return "清场后靠近商人，点补给";
            if (segment == EliteRoomIndex) return "毒素光环精英，留意绿色范围";
            if (segment == BossRoomIndex) return stageIndex == 3 ? "Boss 房锁定，躲红区找输出窗口" : "终段战斗，击破守卫";
            if (segment == 2) return "弓手伏击，先读瞄准线";
            if (segment == 6) return "终战前压缩资源，准备启封";
            return "清敌、拾取、寻找 SLOT";
        }

        private void SpawnModifierRoomBonus(int segment)
        {
            if (segment < 0 || segment >= roomModifiers.Length) return;
            if (roomModifiers[segment] != RoomModifier.JarCache) return;
            float x = Mathf.Clamp(SegmentCenters[segment] + UnityEngine.Random.Range(-.85f, .85f), LeftBound + 1.8f, RightBound - 2.5f);
