        private static string ShortRoomTitle(string title)
        {
            if (string.IsNullOrEmpty(title)) return "";
            int dot = title.IndexOf('·');
            if (dot > 0) title = title.Substring(0, dot);
            return title
                .Replace("普通战斗房", "战斗房")
                .Replace("远程伏击房", "伏击房")
                .Replace("符文商店房", "商店")
                .Replace("混合战斗房", "混战房")
                .Replace("毒素精英房", "精英房")
                .Replace("终战准备房", "准备房")
                .Replace("守护者 Boss 房", "Boss 房")
                .Replace("终段战斗房", "终段房");
        }

        private void AnimateRoomGateOpen(RoomGateState gate, Color color)
        {
            if (gate == null || !gate.Root) return;
            if (gate.StateLabel)
            {
                gate.StateLabel.text = "开启";
                gate.StateLabel.color = C("#6CE6B6");
            }
            if (gate.LockGlow) gate.LockGlow.gameObject.SetActive(false);
            if (gate.LeftDoor) StartCoroutine(SlideDoorPanel(gate.LeftDoor.transform, new Vector3(-.52f, -.70f, 0), color));
            if (gate.RightDoor) StartCoroutine(SlideDoorPanel(gate.RightDoor.transform, new Vector3(.52f, -.70f, 0), color));
        }

        private IEnumerator SlideDoorPanel(Transform panel, Vector3 targetLocalPosition, Color color)
        {
            if (!panel) yield break;
            var renderer = panel.GetComponent<SpriteRenderer>();
            Vector3 start = panel.localPosition;
            Color startColor = renderer ? renderer.color : Color.white;
            float elapsed = 0f;
            const float duration = .28f;
            while (elapsed < duration && panel)
            {
                elapsed += Time.deltaTime;
                float t = Mathf.Clamp01(elapsed / duration);
                panel.localPosition = Vector3.Lerp(start, targetLocalPosition, EaseOutCubic(t));
                if (renderer) renderer.color = Color.Lerp(startColor, new Color(color.r, color.g, color.b, .22f), t);
                yield return null;
            }
        }

        private void UpdateProgressGate()
        {
            if (rollingRune) return;
            while (currentSegment < progressGates.Count && CurrentRoomCanAdvance(currentSegment))
            {
                int clearedSegment = currentSegment;
                string rewardText = GrantRoomClearReward(currentSegment);
                if (currentSegment < progressGates.Count && progressGates[currentSegment])
                {
                    PlayGateOpenFx(progressGates[currentSegment], currentSegment);
                    progressGates[currentSegment].SetActive(false);
                }
                currentSegment++;
                UpdateRoomMarkers();
                bool optionalChestLeft = ActivePlatformRuneVesselInSegment(clearedSegment);
                if (shrineAvailable)
                    noticeText.text = $"{rewardText}  |  SLOT 已开启，可选启封，也可继续推进";
                else if (optionalChestLeft)
                    noticeText.text = $"{rewardText}  |  上一房小宝箱可选，不锁路，继续向右";
                else
                    noticeText.text = $"{rewardText}  |  进入：{CurrentRoomTitle()}";
                TriggerRoomEnterCue(currentSegment);
                if (currentSegment == ShopRoomIndex && !shopVisitedThisStage) break;
            }
        }

        private bool CurrentRoomCanAdvance(int segment)
        {
            if (RoomBlockingEnemyCount(segment) > 0) return false;
            if (OptionalRoomObjectiveAllowsAdvance(segment)) return true;
            if (segment < 0 || segment >= roomObjectives.Length) return true;
            return true;
        }

        private bool CurrentGateActuallyLocksPlayer(int segment)
        {
            if (segment < 0 || segment >= SegmentRights.Length - 1) return false;
            if (CurrentRoomCanAdvance(segment)) return false;
            if (RoomBlockingEnemyCount(segment) <= 0) return false;
            if (player && StaleBehindEnemyLockShouldCatchUp(segment, player.transform.position.x)) return false;
            if (player && GateEdgeSoftUnlockShouldCatchUp(segment, player.transform.position.x)) return false;
            return true;
        }

        private int RoomBlockingEnemyCount(int segment)
        {
            return ActiveEnemiesInSegment(segment);
        }

        private bool OptionalRoomObjectiveAllowsAdvance(int segment)
        {
            if (segment < 0 || segment >= roomObjectives.Length) return true;
            var objective = roomObjectives[segment];
            return objective == RoomObjective.BreakRuneCache
                || objective == RoomObjective.PrecisionDodge
                || objective == RoomObjective.TimedClear;
        }

        private int ActiveEnemiesInSegment(int segment)
        {
            if (segment < 0 || segment >= SegmentRights.Length) return 0;
            PruneInvalidEnemies();
            return enemies.Count(e => IsBlockingEnemyInSegment(e, segment));
        }

        private void PruneInvalidEnemies()
        {
            for (int i = enemies.Count - 1; i >= 0; i--)
            {
                var e = enemies[i];
                if (e == null || !e.Root)
                    enemies.RemoveAt(i);
            }
        }

        private bool IsBlockingEnemyInSegment(Fighter e, int segment)
        {
            if (e == null || e.Dead || !e.Root || !e.Root.activeInHierarchy) return false;
            Vector3 pos = e.Root.transform.position;
            if (!IsXInSegment(pos.x, segment)) return false;
            return pos.y > GroundY - .40f && pos.y < GroundY + 6.2f;
        }

        private string GrantRoomClearReward(int segment)
        {
            if (claimedRoomRewards.Contains(stageIndex * 10 + segment)) return "前方符文屏障解除";
            claimedRoomRewards.Add(stageIndex * 10 + segment);

            int coinReward = 24 + stageIndex * 8 + segment * 6;
            var modifier = roomModifiers[Mathf.Clamp(segment, 0, roomModifiers.Length - 1)];
            float extraFate = modifier == RoomModifier.FateSurge ? 18f : modifier == RoomModifier.Precision ? (PrecisionObjectiveSucceeded(segment) ? 8f : 0f) : 0f;
            bool timedSuccess = TimedClearSucceeded(segment);
            bool swiftSuccess = SwiftObjectiveSucceeded(segment);
            if (modifier == RoomModifier.Swift)
            {
                coinReward += swiftSuccess ? 34 : 12;
                if (swiftSuccess) extraFate += 10f;
            }
            if (modifier == RoomModifier.Strong) coinReward += 24;
            if (modifier != RoomModifier.Stable && segment != ShopRoomIndex && segment != BossRoomIndex) modifiedRoomsClearedThisRun++;
            string rewardText;
            if (segment == ShopRoomIndex)
            {
                hp = Mathf.Min(maxHp, hp + maxHp * .16f);
                coinReward += 18;
                rewardText = $"清空商店房：+{coinReward} 金币，生命小幅恢复";
            }
            else if (segment == EliteRoomIndex)
            {
                coinReward += 42;
                fateEnergy = Mathf.Min(99f, fateEnergy + 46f);
                rewardText = $"清空精英房：+{coinReward} 金币，命运能量 +46%";
            }
            else
            {
                fateEnergy = Mathf.Min(99f, fateEnergy + 20f + segment * 4f + extraFate);
                string challenge = SwiftChallengeRewardSuffix(modifier, swiftSuccess);
                rewardText = extraFate > 0
                    ? $"清空{RoomTitle(segment)}：+{coinReward} 金币，命运能量额外提升{challenge}"
                    : $"清空{RoomTitle(segment)}：+{coinReward} 金币，命运能量提升{challenge}";
            }

            coins += coinReward;
            PlaySfx(sfxRuneReward, .55f);
            SpawnTimedSprite("RoomClearRewardFx_NoYellowPlate", CombatVfxSprite(0), new Vector2(SegmentCenters[Mathf.Clamp(segment, 0, SegmentCenters.Length - 1)], GroundY + 1.25f), new Vector2(.44f, .022f), new Color(1f, 1f, 1f, .12f), 8, .085f);
            var text = WorldText("RoomClearRewardText", fxRoot, RoomClearRewardWorldToken(segment, extraFate), new Vector2(SegmentCenters[Mathf.Clamp(segment, 0, SegmentCenters.Length - 1)], GroundY + 2.12f), 16, 24);
            text.color = new Color(.74f, .96f, 1f, .30f);
            Destroy(text.gameObject, .28f);
            SpawnRoomClearPerformanceCue(segment, modifier, timedSuccess, swiftSuccess);
            bool spawnedRuneShrine = TrySpawnFateShrineAfterSafeRoomClear(segment);
            if (!spawnedRuneShrine) MaybeOfferRoomRewardChoice(segment);
            return rewardText;
        }

        private static string RoomClearRewardWorldToken(int segment, float extraFate)
        {
            if (segment == ShopRoomIndex) return "+金币 +生命";
            if (segment == EliteRoomIndex) return "+金币 +命运";
            return extraFate > 0f ? "+金币 +命运↑" : "+金币 +命运";
        }

        private bool TrySpawnFateShrineAfterSafeRoomClear(int segment)
        {
            if (rollingRune || shrineAvailable || choosingRoomReward || segment == ShopRoomIndex || segment == BossRoomIndex) return false;
            if (!RoomClearAllowsAutomaticRuneShrine(segment)) return false;
            if (ActiveEnemiesInCurrentArea() > 0 || fateEnergy < 99f || !RuneSpawnCooldownReady()) return false;
            if (!AutomaticRuneShrineQuotaReady())
            {
                fateEnergy = 99f;
                noticeText.text = "本关奖励 SLOT 已收束：继续推进";
                return false;
            }
            fateEnergy = 0f;
            ConsumeAutomaticRuneShrineQuota();
            SpawnRuneShrine(false, Mathf.Clamp(SegmentCenters[Mathf.Clamp(segment, 0, SegmentCenters.Length - 1)] + 1.5f, LeftBound + 2f, CurrentSegmentRight() - 1.2f));
            noticeText.text = "清房奖励：SLOT 宝箱出现，靠近后点启封";
            return true;
        }

        private bool CurrentSegmentAllowsAutomaticRuneShrine()
        {
            return RoomClearAllowsAutomaticRuneShrine(currentSegment);
        }

        private bool AutomaticRuneShrineQuotaReady()
        {
            return automaticRuneShrinesThisStage < MaxAutomaticRuneShrinesPerStage;
        }

        private void ConsumeAutomaticRuneShrineQuota()
        {
            automaticRuneShrinesThisStage = Mathf.Min(MaxAutomaticRuneShrinesPerStage, automaticRuneShrinesThisStage + 1);
        }

        private static bool RoomClearAllowsAutomaticRuneShrine(int segment)
        {
            return segment == EliteRoomIndex || segment == BossRoomIndex - 1;
        }

        private void SpawnRoomClearPerformanceCue(int segment, RoomModifier modifier, bool timedSuccess, bool swiftSuccess)
        {
            if (!fxRoot) return;
            string rating = RoomClearRatingLabel(segment, modifier, swiftSuccess);
            Vector2 pos = new Vector2(SegmentCenters[Mathf.Clamp(segment, 0, SegmentCenters.Length - 1)], GroundY + 2.46f);
            var text = WorldText("RoomClearPerformanceText", fxRoot, rating, pos, 18, 25);
            Color color = swiftSuccess || timedSuccess || highestComboThisRun >= 12 ? C("#8FFFF6") : C("#BFEFFF");
            text.color = new Color(color.r, color.g, color.b, .42f);
            AnimateFloatingWorldText(text, new Vector2(0, .12f), .34f, 1.02f);
            SpawnTimedSprite("RoomClearPerformanceRing", CombatVfxSprite(0), pos + Vector2.down * .30f, new Vector2(.76f, .034f), new Color(.50f, .95f, 1f, .10f), 8, .14f);
        }

        private string RoomClearRatingLabel(int segment, RoomModifier modifier, bool swiftSuccess)
        {
            int enemiesCleared = Mathf.Max(1, killsThisRun);
            if (modifier == RoomModifier.Swift && swiftSuccess) return "疾行清房";
            if (modifier == RoomModifier.Precision && PrecisionObjectiveSucceeded(segment)) return "精准闪避";
            if (highestComboThisRun >= 20) return "极限压制";
            if (highestComboThisRun >= 12) return "连击压制";
            if (perfectDodgesThisRun >= 2) return "闪避反击";
            return enemiesCleared > 0 ? "清房完成" : "通路开启";
        }

        private void MaybeOfferRoomRewardChoice(int segment)
        {
            if (choosingRoomReward) return;
            if (shrineAvailable) return;
            if (segment == ShopRoomIndex || segment == BossRoomIndex) return;
            if (roomRewardsChosenThisRun >= MaxCriticalRoomRewardsPerRun) return;
            if (!RoomRewardChoiceAllowedForSegment(segment)) return;
            pendingRoomRewards.Clear();
            var pool = new List<RoomRewardKind> { RoomRewardKind.Heal, RoomRewardKind.Coin, RoomRewardKind.Fate, RoomRewardKind.Attack, RoomRewardKind.Speed, RoomRewardKind.Shield };
            if (segment == EliteRoomIndex) pool.Insert(0, RoomRewardKind.Attack);
            if (segment == 6) pool.Insert(0, RoomRewardKind.Speed);
            while (pendingRoomRewards.Count < 3 && pool.Count > 0)
            {
                int pick = rng.Next(pool.Count);
                var kind = pool[pick];
                pool.RemoveAt(pick);
                pendingRoomRewards.Add(CreateRoomRewardOption(kind, BaseRoomRewardAmount(kind, segment), RollRewardRarity(segment)));
            }
            MarkRecommendedRoomReward();
            AutoApplyRoomRewardChoice(segment);
        }

        private static bool RoomRewardChoiceAllowedForSegment(int segment)
        {
            return segment == EliteRoomIndex || segment == BossRoomIndex - 1;
        }

        private void AutoApplyRoomRewardChoice(int segment)
        {
            if (pendingRoomRewards.Count <= 0) return;
            var option = pendingRoomRewards.FirstOrDefault(reward => reward != null && reward.Recommended) ?? pendingRoomRewards[0];
            ApplyRoomRewardOption(option);
            RecordRoomReward(option);
            pendingRoomRewards.Clear();
            choosingRoomReward = false;
            inputLocked = false;
            Time.timeScale = 1f;
            if (roomRewardPanel) roomRewardPanel.gameObject.SetActive(false);
            noticeText.text = $"{RoomTitle(segment)}奖励：{option.Title}  |  不打断移动，继续推进";
            SpawnTimedSprite("RoomRewardAutoGrantFx_NoYellowPlate", CombatVfxSprite(0), player ? player.transform.position + Vector3.up * .36f : new Vector3(SegmentCenters[Mathf.Clamp(segment, 0, SegmentCenters.Length - 1)], GroundY + 1.2f, 0f), new Vector2(.82f, .026f), new Color(.82f, 1f, .96f, .20f), 8, .12f);
            PlaySfx(sfxRuneReward, .8f);
        }

        private void HandleRoomRewardHotkeys()
        {
            if (!choosingRoomReward) return;
            if (Input.GetKeyDown(KeyCode.Alpha1) || Input.GetKeyDown(KeyCode.Keypad1) || ControllerReward1Down()) ChooseRoomReward(0);
            if (Input.GetKeyDown(KeyCode.Alpha2) || Input.GetKeyDown(KeyCode.Keypad2) || ControllerReward2Down()) ChooseRoomReward(1);
            if (Input.GetKeyDown(KeyCode.Alpha3) || Input.GetKeyDown(KeyCode.Keypad3) || ControllerReward3Down()) ChooseRoomReward(2);
        }

        private void RefreshRoomRewardCards()
        {
            if (roomRewardHintText) roomRewardHintText.text = RoomRewardDecisionHint();
            for (int i = 0; i < pendingRoomRewards.Count; i++)
            {
                var option = pendingRoomRewards[i];
                if (i < roomRewardButtonTexts.Count && roomRewardButtonTexts[i])
                    roomRewardButtonTexts[i].text = RoomRewardCompactTitle(option);
                if (i < roomRewardButtonImages.Count && roomRewardButtonImages[i])
                    roomRewardButtonImages[i].color = option.Recommended ? Color.Lerp(RewardRarityColor(option.Rarity), C("#FFD66B"), .26f) : RewardRarityColor(option.Rarity);
                if (i < roomRewardRarityStrips.Count && roomRewardRarityStrips[i])
                    roomRewardRarityStrips[i].color = option.Recommended ? C("#FFD66B") : RewardRarityAccentColor(option.Rarity);
                if (i < roomRewardTypeTexts.Count && roomRewardTypeTexts[i])
                {
                    roomRewardTypeTexts[i].text = RoomRewardPickBadge(i, option);
                    roomRewardTypeTexts[i].color = RoomRewardTypeColor(option.Kind);
                }
                if (i < roomRewardRecommendTexts.Count && roomRewardRecommendTexts[i])
                {
                    roomRewardRecommendTexts[i].gameObject.SetActive(option.Recommended);
                    roomRewardRecommendTexts[i].text = option.Recommended ? $"推荐 · {ShortRoomRewardRecommendation(option.Recommendation)}" : "";
                }
                if (i < roomRewardRecommendPlateImages.Count && roomRewardRecommendPlateImages[i])
                    roomRewardRecommendPlateImages[i].color = option.Recommended ? new Color(.09f, .070f, .018f, .34f) : Color.clear;
                if (i < roomRewardIconImages.Count && roomRewardIconImages[i])
                {
                    roomRewardIconImages[i].sprite = RoomRewardIconSprite(option.Kind);
                    roomRewardIconImages[i].color = RoomRewardIconColor(option.Kind);
                    roomRewardIconImages[i].preserveAspect = true;
                }
                if (i < roomRewardValueTexts.Count && roomRewardValueTexts[i])
                {
                    roomRewardValueTexts[i].text = RoomRewardValueText(option);
                    roomRewardValueTexts[i].color = RewardRarityAccentColor(option.Rarity);
                }
                if (i < roomRewardHintTexts.Count && roomRewardHintTexts[i])
                {
                    option.Hint = RoomRewardSynergyHint(option);
                    roomRewardHintTexts[i].text = option.Hint;
                    roomRewardHintTexts[i].color = new Color(.86f, .96f, 1f, option.Rarity == RewardRarity.Common ? .72f : .92f);
                }
            }
        }

        private string RoomRewardDecisionHint()
        {
            int recommendedIndex = pendingRoomRewards.FindIndex(option => option != null && option.Recommended);
            if (recommendedIndex < 0 || recommendedIndex >= pendingRoomRewards.Count) return "选择 1 项强化";
            var option = pendingRoomRewards[recommendedIndex];
            return $"推荐 {recommendedIndex + 1} · {ShortRoomRewardRecommendation(option.Recommendation)}";
        }

        private static string RoomRewardCompactTitle(RoomRewardOption option)
        {
            return option == null ? "" : option.Title;
        }

        private static string RoomRewardPickBadge(int index, RoomRewardOption option)
        {
            return option == null ? "" : $"{index + 1} {RoomRewardTypeLabel(option.Kind)}";
        }

        private static string ShortRoomRewardRecommendation(string reason)
        {
            if (string.IsNullOrEmpty(reason)) return "当前局势";
            if (reason.Length <= 8) return reason;
            if (reason.Contains("Boss")) return "Boss 前";
            if (reason.Contains("低血")) return "低血";
            if (reason.Contains("商店")) return "商店前";
            if (reason.Contains("流派") || reason.Contains("成型")) return "流派";
            if (reason.Contains("闪避")) return "闪避流";
            return reason.Substring(0, 8);
        }

        private void MarkRecommendedRoomReward()
        {
            if (pendingRoomRewards.Count == 0) return;
            int bestIndex = 0;
            float bestScore = float.MinValue;
            for (int i = 0; i < pendingRoomRewards.Count; i++)
            {
                var option = pendingRoomRewards[i];
                option.Recommended = false;
                option.RecommendationScore = RoomRewardRecommendationScore(option);
                option.Recommendation = RoomRewardRecommendationReason(option);
                if (option.RecommendationScore > bestScore)
                {
                    bestScore = option.RecommendationScore;
                    bestIndex = i;
                }
            }
            pendingRoomRewards[bestIndex].Recommended = true;
        }

        private float RoomRewardRecommendationScore(RoomRewardOption option)
        {
            if (option == null) return float.MinValue;
            float hpRatio = maxHp <= 0f ? 1f : hp / maxHp;
            bool bossSoon = currentSegment >= 5;
            bool shopSoon = currentSegment < ShopRoomIndex;
            int buildLevel = swordRuneLevel + dashRuneLevel + frostRuneLevel + thunderRuneLevel + shieldRuneLevel;
            float score = option.Rarity == RewardRarity.Epic ? .75f : option.Rarity == RewardRarity.Rare ? .35f : 0f;

            if (option.Kind == RoomRewardKind.Heal)
            {
                if (hpRatio < .35f) score += 3.1f;
                else if (hpRatio < .55f) score += 1.75f;
                else score += .35f;
                if (bossSoon) score += .75f;
                if (damageTakenThisRun >= 3) score += .55f;
            }
            else if (option.Kind == RoomRewardKind.Coin)
            {
                if (shopSoon) score += 1.45f;
                if (coins < 100 && currentSegment <= ShopRoomIndex) score += 1f;
                if (buildLevel < 3) score += .35f;
            }
            else if (option.Kind == RoomRewardKind.Fate)
            {
                if (fateEnergy < 80f) score += 1.25f;
                if (buildLevel < 3) score += 1.25f;
                if (currentSegment >= EliteRoomIndex) score += .55f;
            }
            else if (option.Kind == RoomRewardKind.Attack)
            {
                score += 1.05f;
                if (swordRuneLevel > 0 || thunderRuneLevel > 0) score += .75f;
                if (bossSoon) score += .9f;
                if (killsThisRun < 10 && runTime > 210f) score += .35f;
            }
            else if (option.Kind == RoomRewardKind.Speed)
            {
                score += .75f;
                if (dashRuneLevel > 0) score += .65f;
                if (bossSoon) score += .75f;
                if (perfectDodgesThisRun < 2 && damageTakenThisRun > 0) score += .35f;
            }
            else if (option.Kind == RoomRewardKind.Shield)
            {
                score += .8f;
                if (hpRatio < .58f) score += 1.35f;
                if (shieldRuneLevel > 0) score += .6f;
                if (bossSoon || damageTakenThisRun >= 2) score += .85f;
            }

            return score;
        }

        private string RoomRewardRecommendationReason(RoomRewardOption option)
        {
            if (option == null) return "当前局势";
            float hpRatio = maxHp <= 0f ? 1f : hp / maxHp;
            bool bossSoon = currentSegment >= 5;
            bool shopSoon = currentSegment < ShopRoomIndex;
            int buildLevel = swordRuneLevel + dashRuneLevel + frostRuneLevel + thunderRuneLevel + shieldRuneLevel;

            if (option.Kind == RoomRewardKind.Heal)
                return hpRatio < .45f ? "低血保命" : bossSoon ? "Boss 前稳血" : "稳住容错";
            if (option.Kind == RoomRewardKind.Coin)
                return shopSoon ? "商店前攒钱" : "留钱买启封";
            if (option.Kind == RoomRewardKind.Fate)
                return buildLevel < 3 ? "加快流派成型" : "加快启封";
            if (option.Kind == RoomRewardKind.Attack)
                return bossSoon ? "Boss 前补爆发" : "提高清场";
            if (option.Kind == RoomRewardKind.Speed)
                return dashRuneLevel > 0 ? "强化闪避流" : "走位更稳";
            return shieldRuneLevel > 0 || bossSoon || damageTakenThisRun > 0 ? "提高容错" : "新手稳局";
        }

        private float BaseRoomRewardAmount(RoomRewardKind kind, int segment)
        {
            if (kind == RoomRewardKind.Heal) return Mathf.Round(maxHp * (.16f + segment * .01f));
            if (kind == RoomRewardKind.Coin) return 70f + stageIndex * 18f + segment * 8f;
            if (kind == RoomRewardKind.Fate) return 24f + segment * 4f;
            if (kind == RoomRewardKind.Attack) return .055f + segment * .004f;
            if (kind == RoomRewardKind.Speed) return .045f + segment * .003f;
            return 14f + stageIndex * 4f + segment * 2f;
        }

        private RewardRarity RollRewardRarity(int segment)
        {
            double roll = rng.NextDouble();
            double epicChance = segment >= EliteRoomIndex ? .18 : .10;
            double rareChance = segment >= 4 ? .42 : .34;
            if (roll < epicChance) return RewardRarity.Epic;
            if (roll < rareChance) return RewardRarity.Rare;
            return RewardRarity.Common;
        }

        private static float RarityMultiplier(RewardRarity rarity)
        {
            if (rarity == RewardRarity.Epic) return 1.65f;
            if (rarity == RewardRarity.Rare) return 1.28f;
            return 1f;
        }

        private static string RarityLabel(RewardRarity rarity)
        {
            if (rarity == RewardRarity.Epic) return "史诗";
            if (rarity == RewardRarity.Rare) return "稀有";
            return "普通";
        }

        private static Color RewardRarityColor(RewardRarity rarity)
        {
            if (rarity == RewardRarity.Epic) return C("#8E44AD");
            if (rarity == RewardRarity.Rare) return C("#1C8ED6");
            return C("#2E7D66");
        }

        private static Color RewardRarityAccentColor(RewardRarity rarity)
        {
            if (rarity == RewardRarity.Epic) return C("#F2B5FF");
            if (rarity == RewardRarity.Rare) return C("#8DDBFF");
            return C("#A8FFD0");
        }

        private Sprite RoomRewardIconSprite(RoomRewardKind kind)
        {
            if (kind == RoomRewardKind.Heal) return ControlSprite(9);
            if (kind == RoomRewardKind.Coin) return RuneUiSprite(1);
            if (kind == RoomRewardKind.Fate) return RuneUiSprite(0);
            if (kind == RoomRewardKind.Attack) return ControlSprite(2);
            if (kind == RoomRewardKind.Speed) return CombatVfxSprite(0);
            return ControlSprite(15);
        }

        private Color RoomRewardIconColor(RoomRewardKind kind)
        {
            if (kind == RoomRewardKind.Heal) return C("#FF6B7A");
            if (kind == RoomRewardKind.Coin) return C("#FFD66B");
            if (kind == RoomRewardKind.Fate) return C("#55E9FF");
            if (kind == RoomRewardKind.Attack) return C("#FF7A5A");
            if (kind == RoomRewardKind.Speed) return C("#70F5D0");
            return C("#D0D7E2");
        }

        private static string RoomRewardTypeLabel(RoomRewardKind kind)
        {
            if (kind == RoomRewardKind.Attack) return "输出";
            if (kind == RoomRewardKind.Heal || kind == RoomRewardKind.Shield) return "生存";
            if (kind == RoomRewardKind.Speed) return "机动";
            if (kind == RoomRewardKind.Coin) return "经济";
            if (kind == RoomRewardKind.Fate) return "SLOT";
            return "通用";
        }

        private Color RoomRewardTypeColor(RoomRewardKind kind)
        {
            if (kind == RoomRewardKind.Attack) return C("#FFB29E");
            if (kind == RoomRewardKind.Heal || kind == RoomRewardKind.Shield) return C("#CFE8FF");
            if (kind == RoomRewardKind.Speed) return C("#A8FFE6");
            if (kind == RoomRewardKind.Coin) return C("#FFE28A");
            if (kind == RoomRewardKind.Fate) return C("#8FFFF6");
            return new Color(.86f, .96f, 1f, .82f);
        }

        private string RoomRewardValueText(RoomRewardOption option)
        {
            if (option.Kind == RoomRewardKind.Heal) return $"+{Mathf.CeilToInt(option.Amount)} HP";
            if (option.Kind == RoomRewardKind.Coin) return $"+{Mathf.CeilToInt(option.Amount)} 金币";
            if (option.Kind == RoomRewardKind.Fate) return $"+{Mathf.CeilToInt(option.Amount)}% 命运";
            if (option.Kind == RoomRewardKind.Attack) return $"+{Mathf.RoundToInt(option.Amount * 100)}% 攻击";
            if (option.Kind == RoomRewardKind.Speed) return $"+{Mathf.RoundToInt(option.Amount * 100)}% 移速";
            return $"+{Mathf.CeilToInt(option.Amount)} 生命上限";
        }

        private string RoomRewardSynergyHint(RoomRewardOption option)
        {
            if (option == null) return "";
            bool bossSoon = currentSegment >= 5;
            bool shopSoon = currentSegment < ShopRoomIndex;
            int buildLevel = swordRuneLevel + dashRuneLevel + frostRuneLevel + thunderRuneLevel + shieldRuneLevel;

            if (option.Kind == RoomRewardKind.Heal)
                return hp < maxHp * .45f ? "低血优先" : bossSoon ? "Boss 前稳血" : "补容错";
            if (option.Kind == RoomRewardKind.Coin)
                return shopSoon ? "攒钱买 SLOT" : "留钱启封";
            if (option.Kind == RoomRewardKind.Fate)
                return fateEnergy >= 70f ? "快开 SLOT" : buildLevel <= 2 ? "加速成型" : "补启封节奏";
            if (option.Kind == RoomRewardKind.Attack)
                return swordRuneLevel > 0 || thunderRuneLevel > 0 ? "强化剑/雷" : bossSoon ? "Boss 前爆发" : "清房更快";
            if (option.Kind == RoomRewardKind.Speed)
                return dashRuneLevel > 0 ? "配合闪避流" : bossSoon ? "躲 Boss 大招" : "平台走位";
            return shieldRuneLevel > 0 || bossSoon ? "坚盾持久战" : "新手稳局";
        }

        private RoomRewardOption CreateRoomRewardOption(RoomRewardKind kind, float amount, RewardRarity rarity)
        {
            amount *= RarityMultiplier(rarity);
            if (kind == RoomRewardKind.Heal) return new RoomRewardOption { Kind = kind, Rarity = rarity, Amount = amount, Title = "生命补给", Detail = $"+{Mathf.CeilToInt(amount)} 生命" };
            if (kind == RoomRewardKind.Coin) return new RoomRewardOption { Kind = kind, Rarity = rarity, Amount = amount, Title = "金币储备", Detail = $"+{Mathf.CeilToInt(amount)} 金币" };
            if (kind == RoomRewardKind.Fate) return new RoomRewardOption { Kind = kind, Rarity = rarity, Amount = amount, Title = "命运充能", Detail = $"命运能量 +{Mathf.CeilToInt(amount)}%" };
            if (kind == RoomRewardKind.Attack) return new RoomRewardOption { Kind = kind, Rarity = rarity, Amount = amount, Title = "锋刃校准", Detail = $"攻击倍率 +{Mathf.RoundToInt(amount * 100)}%" };
            if (kind == RoomRewardKind.Speed) return new RoomRewardOption { Kind = kind, Rarity = rarity, Amount = amount, Title = "疾步节律", Detail = $"移动倍率 +{Mathf.RoundToInt(amount * 100)}%" };
            return new RoomRewardOption { Kind = kind, Rarity = rarity, Amount = amount, Title = "临时护盾", Detail = $"+{Mathf.CeilToInt(amount)} 最大生命" };
        }

        private void ChooseRoomReward(int index)
        {
            if (!choosingRoomReward || index < 0 || index >= pendingRoomRewards.Count) return;
            var option = pendingRoomRewards[index];
            ApplyRoomRewardOption(option);
            RecordRoomReward(option);
            pendingRoomRewards.Clear();
            choosingRoomReward = false;
            if (roomRewardPanel) roomRewardPanel.gameObject.SetActive(false);
            inputLocked = ModalWantsTimeFreeze();
            Time.timeScale = ModalWantsTimeFreeze() ? 0f : 1f;
            noticeText.text = $"已选择：{option.Title}  |  继续推进";
            SpawnTimedSprite("RoomRewardChosenFx_NoYellowPlate", CombatVfxSprite(0), player.transform.position + Vector3.up * .35f, new Vector2(1.10f, .030f), new Color(.88f, 1f, 1f, .34f), 8, .16f);
            PlaySfx(sfxRuneReward, .9f);
            HapticPulse(HapticTier.Reward);
            TriggerRoomEnterCue(currentSegment);
        }

        private void RecordRoomReward(RoomRewardOption option)
        {
            if (option == null) return;
            roomRewardsChosenThisRun++;
            string hint = string.IsNullOrEmpty(option.Hint) ? RoomRewardSynergyHint(option) : option.Hint;
            rewardHistory.Add($"{rewardHistory.Count + 1}. {RarityLabel(option.Rarity)} {option.Title}：{option.Detail}  {hint}");
            if (rewardHistory.Count > 12) rewardHistory.RemoveAt(0);
        }

        private void ApplyRoomRewardOption(RoomRewardOption option)
        {
            if (option.Kind == RoomRewardKind.Heal) hp = Mathf.Min(maxHp, hp + option.Amount);
            else if (option.Kind == RoomRewardKind.Coin) coins += Mathf.CeilToInt(option.Amount);
            else if (option.Kind == RoomRewardKind.Fate) GainFateEnergy(option.Amount, player.transform.position + Vector3.up * .45f);
            else if (option.Kind == RoomRewardKind.Attack) attackMultiplier += option.Amount;
            else if (option.Kind == RoomRewardKind.Speed) moveMultiplier += option.Amount;
            else
            {
                maxHp += option.Amount;
                hp += option.Amount;
            }
        }

        private void UpdateTutorialProgress()
        {
            if (tutorialCompleted || titleActive || stageIndex != 1 || !player) return;
            tutorialPulseTimer += Time.deltaTime;
            if (tutorialStep == 0 && Mathf.Abs(player.transform.position.x - tutorialStartX) > 1.2f)
                AdvanceTutorial(0);
            if (tutorialStep == 2 && ActiveEnemiesInCurrentArea() <= 0)
                AdvanceTutorial(2);
            if (tutorialStep == 3 && shrineAvailable)
                AdvanceTutorial(3);
            if (tutorialStep == 5 && currentSegment >= 1)
                AdvanceTutorial(5);
        }

        private void UpdateWorldControlHintVisibility(float dt)
        {
            if (!worldHints) return;
            bool modalOpen = inputLocked || titleActive || paused || rollingRune || shrineAvailable || (shopPanel && shopPanel.gameObject.activeSelf);
            bool earlyTutorial = !tutorialCompleted && stageIndex == 1 && tutorialStep <= 1;
            bool beforeCombat = currentSegment == 0 && ActiveEnemiesInCurrentArea() <= 0 && runTime < WorldHintDisplaySeconds;
            bool movedEnough = player && Mathf.Abs(player.transform.position.x - tutorialStartX) > 1.15f;
            bool attacking = attackCooldown > .05f || comboTimer > .05f || touchAttackHeld;
            bool shouldShow = earlyTutorial && beforeCombat && !modalOpen && !movedEnough && !attacking;
            if (!shouldShow)
            {
                HideWorldControlHintsImmediate();
                return;
            }
            worldHints.gameObject.SetActive(true);
            float alpha = Mathf.Clamp01(1f - runTime / WorldHintDisplaySeconds) * (WorldHintMaxAlpha + Mathf.Sin(Time.unscaledTime * 4.5f) * .035f);
            ApplyWorldHintAlpha(worldHints, alpha);
        }

        private void HideWorldControlHintsImmediate()
        {
            if (!worldHints) return;
            ApplyWorldHintAlpha(worldHints, 0f);
            worldHints.gameObject.SetActive(false);
        }

        private static void ApplyWorldHintAlpha(Transform root, float alpha)
        {
            if (!root) return;
            foreach (var sr in root.GetComponentsInChildren<SpriteRenderer>(true))
            {
                if (!sr) continue;
                var c = sr.color;
                sr.color = new Color(c.r, c.g, c.b, Mathf.Clamp01(alpha));
            }
            foreach (var text in root.GetComponentsInChildren<TextMesh>(true))
            {
                if (!text) continue;
                var c = text.color;
                text.color = new Color(c.r, c.g, c.b, Mathf.Clamp01(alpha * 1.35f));
            }
        }

        private void AdvanceTutorial(int completedStep)
        {
            if (tutorialCompleted || completedStep != tutorialStep) return;
            tutorialStep++;
            tutorialPulseTimer = 0f;
            if (tutorialStep >= 7)
            {
                tutorialCompleted = true;
                PlayerPrefs.SetInt("DestinyRanger.TutorialCompleted", 1);
                PlayerPrefs.Save();
                noticeText.text = "继续推进，寻找 SLOT";
            }
        }

        private string TutorialHint()
        {
            if (tutorialCompleted || stageIndex != 1) return "";
            switch (tutorialStep)
            {
                case 0: return "1/7 移动";
                case 1: return "2/7 三连攻击";
                case 2: return "3/7 清敌开路";
                case 3: return "4/7 靠近 SLOT";
                case 4: return "5/7 启封符文";
                case 5: return "6/7 向右推进";
                case 6: return "7/7 商店补给";
                default: return "";
            }
        }

        private void ChainLightning(Fighter source)
        {
            var target = enemies
                .Where(e => e != source && !e.Dead && e.Root && Vector2.Distance(e.Root.transform.position, source.Root.transform.position) < 5.2f)
                .OrderBy(e => Vector2.Distance(e.Root.transform.position, source.Root.transform.position))
                .FirstOrDefault();
            if (target == null) return;
            var from = source.Root.transform.position + Vector3.up * .55f;
            var to = target.Root.transform.position + Vector3.up * .55f;
            var mid = (from + to) * .5f;
            var fx = SpriteObj("ChainLightning", fxRoot, CombatVfxSprite(5), mid, new Vector2(.75f, Vector2.Distance(from, to)), Color.white, 9);
            fx.transform.rotation = Quaternion.Euler(0, 0, Vector2.SignedAngle(Vector2.up, to - from));
            Destroy(fx, .18f);
            DamageEnemy(target, 18f + thunderRuneLevel * 6f, (to - from).normalized, HitTier.Skill);
        }

