            SpawnTimedSprite("PreviewSlashFootAnchor_NoYellowPlate", CombatVfxSprite(0), player.transform.position + new Vector3(.34f, -.52f, 0), new Vector2(.16f, .004f), new Color(.72f, .96f, 1f, .018f), 8, 4f);
