                SetEnemySprite(e, EnemyHitSpriteIndex(e.Kind));
                SpawnEnemyHitStunBodyClamp(e, Vector2.right, e.HitReactTier);
                if (e.ReadabilitySilhouette)
                {
                    e.ReadabilitySilhouetteTimer = Mathf.Max(e.ReadabilitySilhouetteTimer, EnemySilhouetteHitDuration);
                    UpdateEnemyReadabilitySilhouette(e, 0f);
