            SpawnTimedSprite("MotionCleanPreviewEnemyFootContact_CleanEllipse", SpriteCache.Circle, new Vector2(-1.55f, GroundY + .18f), new Vector2(.44f, .070f), new Color(.010f, .018f, .014f, .080f), 8, 10f);
