        private void HitStop(float duration)
        {
            if (paused || duration <= 0) return;
            hitStopTimer = Mathf.Max(hitStopTimer, duration);
            Time.timeScale = .18f;
        }

        private void ShakeCamera(float amount, float duration)
        {
            float shakeScale = CameraShakeScale();
            cameraShakeAmount = Mathf.Max(cameraShakeAmount, amount * shakeScale);
            cameraShakeTimer = Mathf.Max(cameraShakeTimer, duration * Mathf.Lerp(.55f, 1f, shakeScale));
        }

        private float VisualFlashScale()
        {
            return effectsIntensity > .75f ? 1f : .34f;
        }

        private float CameraShakeScale()
        {
            return effectsIntensity > .75f ? 1f : .42f;
        }

        private float DangerVignetteScale()
        {
            return effectsIntensity > .75f ? 1f : .58f;
        }

        private float MaxFlashStrength()
        {
            return effectsIntensity > .75f ? .32f : .075f;
        }

        private float MaxFlashDuration()
        {
            return effectsIntensity > .75f ? .24f : .095f;
        }

        private IEnumerator NextStageAfterDelay()
        {
            inputLocked = true;
            yield return new WaitForSeconds(1.2f);
            inputLocked = false;
            hp = Mathf.Min(maxHp, hp + 50);
            mp = maxMp;
            StartStage(stageIndex + 1);
        }

        private void ShowVictory(bool win)
        {
            inputLocked = true;
            victoryPanel.gameObject.SetActive(true);
            if (win) SetHeroFrame(HeroVictoryFrame);
            clearedNewBestTime = win && (bestClearTime <= 0 || runTime < bestClearTime);
            clearedNewKillRecord = killsThisRun > bestRunKills;
            if (clearedNewBestTime)
            {
                bestClearTime = runTime;
                PlayerPrefs.SetFloat("DestinyRanger.BestClearTime", bestClearTime);
            }
            if (clearedNewKillRecord)
            {
                bestRunKills = killsThisRun;
                PlayerPrefs.SetInt("DestinyRanger.BestRunKills", bestRunKills);
            }
            UpdateDailyTrialRecords(win);
            PlayerPrefs.Save();
            if (victoryTitleText)
            {
                victoryTitleText.text = win ? "试炼通关" : "挑战失败";
                victoryTitleText.color = win ? C("#FFD95A") : C("#FF7A6B");
            }
            if (victoryRestartButtonText) victoryRestartButtonText.text = win ? "再次挑战" : "重新挑战";
            if (victoryCauseText) victoryCauseText.text = BuildVictoryCauseLine(win);
            if (victoryStatsText) victoryStatsText.text = BuildRunSummary(win);
            if (victoryAssistNoteText) victoryAssistNoteText.text = BuildVictoryAssistNote(win);
        }

        private string BuildVictoryCauseLine(bool win)
        {
            if (win)
            {
                if (clearedNewBestTime) return "亮点：刷新最佳时间";
                if (damageTakenThisRun <= 1) return "亮点：防守稳定";
                if (runeCount >= 3) return "亮点：流派成型";
                return "亮点：完成战斗-启封闭环";
            }
            string source = string.IsNullOrEmpty(lastDamageSource) ? PrimaryDamageSource() : lastDamageSource;
            if (runeCount <= 0) return $"倒在 {source} · 先启封 SLOT";
            if (damageTakenThisRun >= 5) return $"倒在 {source} · 优先盾/冰";
            if (highestComboThisRun < 6) return $"倒在 {source} · 练三连破势";
            if (perfectDodgesThisRun <= 0 && (source.Contains("Boss") || source.Contains("弓手") || source.Contains("弹幕"))) return $"倒在 {source} · 保留闪避";
            return $"倒在 {source} · 补短板";
        }

        private string BuildVictoryAssistNote(bool win)
        {
            if (assistMode) return "辅助模式只改动作容错；再次挑战沿用当前设置。";
            if (!win && damageTakenThisRun >= 4) return "受伤压力高：可回标题开启辅助模式。";
            if (win && trialHeatLevel >= 2) return "高热通关已计入本地成就。";
            if (dailyTrialMode) return "今日试炼只保存本机最佳；无联网排行。";
            return "再次挑战重置本局构筑；返回标题可调热度/辅助。";
        }

        private string BuildRunSummary(bool win)
        {
            string bestTime = bestClearTime > 0 ? FormatTime(bestClearTime) : "--:--";
            string pace = BuildFinalPaceText();
            string killRecord = bestRunKills > 0
                ? clearedNewKillRecord ? "本局刷新击杀纪录" : killsThisRun >= bestRunKills ? "追平击杀纪录" : $"距击杀纪录 {bestRunKills - killsThisRun}"
                : "暂无击杀纪录";
            string runes = CompactRunLedger(runeHistory, 2, "未启封");
            string rewards = CompactRunLedger(rewardHistory, 2, "未选择");
            string build =
                $"剑{swordRuneLevel}  闪{dashRuneLevel}  冰{frostRuneLevel}  雷{thunderRuneLevel}  盾{shieldRuneLevel}";
            string opener = win ? BuildWinSummaryLine(bestTime) : BuildFailureSummaryLine();
            string badges = BuildRunBadgeLine(win);
            string achievements = UnlockRunAchievements(win);
            string nextChallenge = BuildNextRunChallenge(win);
            string runDiagnosis = BuildRunDiagnosis(win);
            string recommendedBuild = BuildRecommendedNextBuild(win);
            string buildReview = BuildRunBuildReview(win);
            string dailyLine = BuildDailyTrialRunRecordLine();
            string damageSources = BuildDamageSourceSummary();
            return
                $"{opener}\n" +
                $"核心：热度 {TrialHeatLabel()}  {pace}  击败 {killsThisRun}  金币 {coins}  Lv{trialLevel} {TrialExpPercent()}%\n" +
                $"表现：最高连击 {highestComboThisRun}  受伤 {damageTakenThisRun}  极闪 {perfectDodgesThisRun}  SLOT {runeCount}\n" +
                $"徽章：{badges}  {achievements}\n" +
                $"{dailyLine}" +
                $"{nextChallenge}\n" +
                $"{runDiagnosis}\n" +
                $"{MapLayoutRunReview()}\n" +
                $"{buildReview}\n" +
                $"{recommendedBuild}\n" +
                $"{BuildFirstRunAssistAdvice(win)}" +
                $"{damageSources}\n" +
                $"构筑等级：{build}\n" +
                $"最近符文：{runes}\n" +
                $"房间奖励：{rewards}";
        }

        private static string CompactRunLedger(List<string> history, int maxItems, string emptyText)
        {
            if (history == null || history.Count <= 0) return emptyText;
            var recent = history.Skip(Mathf.Max(0, history.Count - maxItems)).Select(CompactLedgerEntry).ToArray();
            return string.Join(" / ", recent);
        }

        private static string CompactLedgerEntry(string value)
        {
            if (string.IsNullOrEmpty(value)) return "";
            string compact = value.Replace("\n", " ").Replace("  ", " ").Trim();
            const int maxLength = 26;
            return compact.Length <= maxLength ? compact : compact.Substring(0, maxLength - 1) + "...";
        }

        private string BuildFirstRunAssistAdvice(bool win)
        {
            if (win) return "";
            if (!assistMode && damageTakenThisRun >= 4)
                return "操作建议：设置里可开启辅助模式，降低受伤压力，先熟悉 Boss/精英前摇。\n";
            if (!autoAttackEnabled && highestComboThisRun < 6)
                return "操作建议：可开启自动攻击或长按攻击键，先稳定打出三连破势。\n";
            if (runeCount <= 0)
                return "操作建议：优先清房、开平台小宝箱，先启封一次 SLOT 改变打法。\n";
            if (perfectDodgesThisRun <= 0 && (lastDamageSource.Contains("Boss") || lastDamageSource.Contains("弹幕") || lastDamageSource.Contains("弓手")))
                return "操作建议：看到“闪避/拉开”提示时先保留闪避，极限闪避会获得命运能量。\n";
            return "操作建议：失败后先看受伤来源，下一局围绕盾/冰/闪避构筑提高容错。\n";
        }

        private string BuildDamageSourceSummary()
        {
            if (damageTakenThisRun <= 0 || damageSourceHits.Count == 0) return "受伤来源：无";
            var top = damageSourceHits
                .OrderByDescending(pair => pair.Value)
                .ThenBy(pair => pair.Key)
                .Take(3)
                .Select(pair => $"{pair.Key}×{pair.Value}");
            return $"受伤来源：{string.Join("  ", top.ToArray())}    最后一击：{lastDamageSource}";
        }

        private string BuildRunDiagnosis(bool win)
        {
            if (runeCount <= 0) return "问题诊断：构筑未启动，战斗收益没有转化成 SLOT 变化";
            if (!win && damageTakenThisRun >= 5) return $"问题诊断：受伤过多，主要压力来自 {PrimaryDamageSource()}";
            if (!win && currentSegment <= ShopRoomIndex) return "问题诊断：前半段资源不足，进商店前缺少金币或启封次数";
            if (!win && perfectDodgesThisRun <= 0 && (lastDamageSource.Contains("Boss") || lastDamageSource.Contains("弓手") || lastDamageSource.Contains("弹幕"))) return "问题诊断：远程/Boss 前摇没有转成闪避收益";
            if (highestComboThisRun < 8) return "问题诊断：连段不稳定，第三段破势和命中收益偏少";
            if (win && damageTakenThisRun <= 0) return "问题诊断：防守表现优秀，可以开始追求速通或高热度";
            if (win && runTime > 900f) return "问题诊断：通关稳定但清场偏慢，输出/连锁流派不足";
            if (win && runeCount < 3) return "问题诊断：通关完成，但 SLOT 启封次数偏少，构筑变化还不够充分";
            return "问题诊断：基础循环成立，下一局可以围绕更明确的流派目标优化";
        }

        private string BuildRunBuildReview(bool win)
        {
            int total = swordRuneLevel + dashRuneLevel + frostRuneLevel + thunderRuneLevel + shieldRuneLevel;
            string style = CurrentBuildStyle();
            string grade = BuildGradeLabel(BuildScore(win, total));
            string focus = BuildFocusRuneLabel();
            string weakness = BuildWeaknessLabel(win, total);
            if (total <= 0) return "构筑复盘：未成型  评分 D  主轴：无  短板：缺少第一枚核心符文";
            return $"构筑复盘：{style} Lv{total}  评分 {grade}  主轴：{focus}  短板：{weakness}";
        }

        private float BuildScore(bool win, int total)
        {
            float score = total * 12f + runeCount * 6f + highestComboThisRun * .7f + perfectDodgesThisRun * 4f;
            if (win) score += 18f;
            if (damageTakenThisRun <= 1) score += 10f;
            score -= damageTakenThisRun * 5f;
            if (runTime <= 900f && win) score += 8f;
            if (roomRewardsChosenThisRun >= 2) score += 6f;
            return Mathf.Clamp(score, 0f, 100f);
        }

        private static string BuildGradeLabel(float score)
        {
            if (score >= 86f) return "S";
            if (score >= 72f) return "A";
            if (score >= 56f) return "B";
            if (score >= 38f) return "C";
            return "D";
        }

        private string BuildFocusRuneLabel()
        {
            var focus = new List<string>();
            int maxLevel = Mathf.Max(swordRuneLevel, dashRuneLevel, frostRuneLevel, thunderRuneLevel, shieldRuneLevel);
            if (maxLevel <= 0) return "未启动";
            if (swordRuneLevel == maxLevel) focus.Add("剑");
            if (dashRuneLevel == maxLevel) focus.Add("闪");
            if (frostRuneLevel == maxLevel) focus.Add("冰");
            if (thunderRuneLevel == maxLevel) focus.Add("雷");
            if (shieldRuneLevel == maxLevel) focus.Add("盾");
            return string.Join("+", focus.Take(2).ToArray()) + $" Lv{maxLevel}";
        }

        private string BuildWeaknessLabel(bool win, int total)
        {
            if (runeCount < 3) return "启封次数少";
            if (damageTakenThisRun >= 4) return "防守容错不足";
            if (highestComboThisRun < 8) return "破势连段少";
            if (perfectDodgesThisRun <= 0 && (dashRuneLevel > 0 || lastDamageSource.Contains("弹幕") || lastDamageSource.Contains("弓手"))) return "闪避收益未转化";
            if (win && runTime > 900f) return "清场速度偏慢";
            if (total >= 6 && Mathf.Max(swordRuneLevel, dashRuneLevel, frostRuneLevel, thunderRuneLevel, shieldRuneLevel) <= 2) return "符文分散";
            return win ? "可挑战更高热度" : "Boss/精英应对不稳";
        }

        private string BuildRecommendedNextBuild(bool win)
        {
            if (runeCount <= 0) return "推荐构筑：先拿任意核心符文，优先开平台小宝箱和商店 SLOT";
            if (damageTakenThisRun >= 4 || lastDamageSource.Contains("毒素") || lastDamageSource.Contains("Boss")) return "推荐构筑：盾/冰优先，增加容错后再贴身打三连破势";
            if (perfectDodgesThisRun <= 0 && (dashRuneLevel <= 0 || lastDamageSource.Contains("弓手") || lastDamageSource.Contains("激光"))) return "推荐构筑：闪避游击优先，利用留痕和极限闪避换命运能量";
            if (highestComboThisRun < 10) return "推荐构筑：冰环控场或坚盾续航，给自己稳定打满三段的窗口";
            if (runTime > 900f || killsThisRun < 22) return "推荐构筑：剑/雷优先，提高清房速度和连锁收割";
            if (win && damageTakenThisRun <= 1) return "推荐构筑：剑/雷速通路线，尝试 H2 热度或 15 分钟内通关";
            return "推荐构筑：围绕当前最高等级符文继续叠加，避免平均分散导致打法不成型";
        }

        private string PrimaryDamageSource()
        {
            if (damageSourceHits.Count == 0) return lastDamageSource;
            return damageSourceHits.OrderByDescending(pair => pair.Value).ThenBy(pair => pair.Key).First().Key;
        }

        private string BuildNextRunChallenge(bool win)
        {
            if (!win)
            {
                int room = Mathf.Clamp(currentSegment + 1, 1, SegmentRights.Length);
                if (runeCount <= 0) return "下局挑战：优先清房攒满命运能量，先启封第一个 SLOT";
                if (room <= ShopRoomIndex) return "下局挑战：带 100 金币进入商店，购买一次奖励 SLOT";
                return "下局挑战：保留闪避处理精英/Boss 前摇，先活到最终启封";
            }
            if (damageTakenThisRun > 0) return "下局挑战：尝试少受伤通关，优先拿盾/冰提高容错";
            if (runTime > 900f) return "下局挑战：15 分钟内通关，优先拿剑/雷提高清场速度";
            if (runeCount < 3) return "下局挑战：完成 3 次关键启封，优先精英、商店和 Boss 前节点";
            if (perfectDodgesThisRun < 3) return "下局挑战：完成 3 次极限闪避，把技术走位转成命运能量";
            if (highestComboThisRun < 20) return "下局挑战：打出 20 连击，利用冰环或盾构筑稳定站场";
            return "下局挑战：刷新最佳时间，寻找更快的剑/雷清场路线";
        }

        private string BuildDailyTrialRunRecordLine()
        {
            if (!dailyTrialMode) return "";
            string time = dailyBestTime > 0f ? FormatTime(dailyBestTime) : "--:--";
            string kills = dailyBestKills > 0 ? dailyBestKills.ToString() : "--";
            string status = dailyBestTimeUpdatedThisRun && dailyBestKillsUpdatedThisRun ? "刷新今日时间和击败" :
                dailyBestTimeUpdatedThisRun ? "刷新今日最佳时间" :
                dailyBestKillsUpdatedThisRun ? "刷新今日最高击败" : "今日记录未刷新";
            return $"今日试炼：{status}    今日最佳 {time}/K{kills}\n";
        }

        private string BuildRunBadgeLine(bool win)
        {
            var badges = new List<string>();
            if (win) badges.Add("试炼完成");
            if (win && damageTakenThisRun == 0) badges.Add("无伤通关");
            if (win && runTime <= 900f) badges.Add("15分速通");
            if (runeCount >= 3) badges.Add("命运常客");
            if (perfectDodgesThisRun >= 3) badges.Add("精准游侠");
            if (highestComboThisRun >= 20) badges.Add("连击压制");
            if (roomRewardsChosenThisRun >= 2) badges.Add("清房规划");
            if (modifiedRoomsClearedThisRun >= 4) badges.Add("适应试炼");
            if (shieldRuneLevel >= 2 && damageTakenThisRun <= 2) badges.Add("坚盾续航");
            if (win && trialHeatLevel >= 2) badges.Add("高热通关");
            if (win && RunSawLayout(1)) badges.Add("树冠路线");
            if (win && RunSawLayout(2)) badges.Add("断桥路线");
            if (win && RunSawLayout(3)) badges.Add("高脊路线");
            if (badges.Count == 0) badges.Add(win ? "稳健通关" : "继续试炼");
            return string.Join(" / ", badges.Take(4).ToArray());
        }

        private string UnlockRunAchievements(bool win)
        {
            var unlockedNow = new List<string>();
            TryUnlockAchievement("ClearTrial", win, unlockedNow);
            TryUnlockAchievement("NoDamageClear", win && damageTakenThisRun == 0, unlockedNow);
            TryUnlockAchievement("FastClear15", win && runTime <= 900f, unlockedNow);
            TryUnlockAchievement("RuneRegular", runeCount >= 3, unlockedNow);
            TryUnlockAchievement("PerfectRanger", perfectDodgesThisRun >= 3, unlockedNow);
            TryUnlockAchievement("ComboPress", highestComboThisRun >= 20, unlockedNow);
            TryUnlockAchievement("RoomPlanner", roomRewardsChosenThisRun >= 2, unlockedNow);
            TryUnlockAchievement("AdaptiveTrial", modifiedRoomsClearedThisRun >= 4, unlockedNow);
            TryUnlockAchievement("ShieldSustain", shieldRuneLevel >= 2 && damageTakenThisRun <= 2, unlockedNow);
            TryUnlockAchievement("HeatClear", win && trialHeatLevel >= 2, unlockedNow);
            TryUnlockAchievement("CanopyMaster", win && RunSawLayout(1), unlockedNow);
            TryUnlockAchievement("BrokenBridgeMaster", win && RunSawLayout(2), unlockedNow);
            TryUnlockAchievement("RuneRidgeMaster", win && RunSawLayout(3), unlockedNow);
            TryUnlockAchievement("RouteArchivist", win
                && unlockedAchievements.Contains("CanopyMaster")
                && unlockedAchievements.Contains("BrokenBridgeMaster")
                && unlockedAchievements.Contains("RuneRidgeMaster"), unlockedNow);
            if (unlockedNow.Count > 0) PlayerPrefs.Save();
            return unlockedNow.Count > 0 ? "新成就：" + string.Join(" / ", unlockedNow.Take(3).ToArray()) : $"成就进度：{unlockedAchievements.Count}/{AchievementIds.Length}";
        }

        private bool RunSawLayout(int layout)
        {
            return layout >= 0 && layout < runMapLayoutsSeen.Length && runMapLayoutsSeen[layout];
        }

        private void TryUnlockAchievement(string id, bool condition, List<string> unlockedNow)
        {
            if (!condition || unlockedAchievements.Contains(id)) return;
            unlockedAchievements.Add(id);
            PlayerPrefs.SetInt(AchievementKey(id), 1);
            unlockedNow.Add(AchievementName(id));
        }

        private static string AchievementName(string id)
        {
            if (id == "ClearTrial") return "试炼完成";
            if (id == "NoDamageClear") return "无伤通关";
            if (id == "FastClear15") return "15分速通";
            if (id == "RuneRegular") return "命运常客";
            if (id == "PerfectRanger") return "精准游侠";
            if (id == "ComboPress") return "连击压制";
            if (id == "RoomPlanner") return "清房规划";
            if (id == "AdaptiveTrial") return "适应试炼";
            if (id == "ShieldSustain") return "坚盾续航";
            if (id == "HeatClear") return "高热通关";
            if (id == "CanopyMaster") return "树冠熟手";
            if (id == "BrokenBridgeMaster") return "断桥熟手";
            if (id == "RuneRidgeMaster") return "高脊熟手";
            if (id == "RouteArchivist") return "路线档案";
            return id;
        }

        private static string AchievementKey(string id)
        {
            return "DestinyRanger.Achievement." + id;
        }

        private string BuildWinSummaryLine(string bestTime)
        {
            return $"本局结果：{RunModeLabel()}通关    用时 {FormatTime(runTime)}    最佳 {bestTime}    完成房间 {SegmentRights.Length}/{SegmentRights.Length}";
        }

        private string BuildFailureSummaryLine()
        {
            int room = Mathf.Clamp(currentSegment + 1, 1, SegmentRights.Length);
            float roomSpan = SegmentRights[Mathf.Clamp(currentSegment, 0, SegmentRights.Length - 1)] - (currentSegment > 0 ? SegmentRights[currentSegment - 1] : LeftBound);
            float roomStart = currentSegment > 0 ? SegmentRights[currentSegment - 1] : LeftBound;
            float roomProgress = player ? Mathf.Clamp01((player.transform.position.x - roomStart) / Mathf.Max(1f, roomSpan)) : 0f;
            int progress = Mathf.RoundToInt(((room - 1) + roomProgress) / SegmentRights.Length * 100f);
            string nextGoal = runeCount <= 0 ? "下次目标：先启封第一个 SLOT" : room <= ShopRoomIndex ? "下次目标：带金币进入商店补给" : "下次目标：保留闪避处理精英/Boss 前摇";
            return $"本局结果：{RunModeLabel()}失败    倒在 {CurrentRoomTitle()}  房间 {room}/{SegmentRights.Length}  推进 {Mathf.Clamp(progress, 0, 99)}%  用时 {FormatTime(runTime)}  最后一击：{lastDamageSource}\n{nextGoal}";
        }

        private string RunModeLabel()
        {
            return dailyTrialMode ? "今日试炼 " : "";
        }

        private string BuildFinalPaceText()
        {
            if (clearedNewBestTime) return "本局刷新最佳时间";
            if (bestClearTime <= 0) return "暂无最佳时间";
            float delta = runTime - bestClearTime;
            if (Mathf.Abs(delta) < .5f) return "追平最佳时间";
            return delta < 0 ? $"比最佳快 {FormatTime(-delta)}" : $"比最佳慢 {FormatTime(delta)}";
        }

        private static string FormatTime(float seconds)
        {
            int total = Mathf.Max(0, Mathf.FloorToInt(seconds));
            return $"{total / 60:00}:{total % 60:00}";
        }

        private void RestartGame()
        {
            bool repeatDaily = dailyTrialMode;
            ResetRunState();
            ConfigureRunSeed(repeatDaily);
            if (titlePanel) titlePanel.gameObject.SetActive(false);
            if (pausePanel) pausePanel.gameObject.SetActive(false);
            if (settingsPanel) settingsPanel.gameObject.SetActive(false);
            if (achievementPanel) achievementPanel.gameObject.SetActive(false);
            if (runeCodexPanel) runeCodexPanel.gameObject.SetActive(false);
            titleActive = false;
            paused = false;
            Time.timeScale = 1f;
            inputLocked = false;
            StartStage(1);
        }

        private void ReturnToTitle()
        {
            ResetRunState();
            ConfigureRunSeed(false);
            StartStage(1);
            ShowTitle();
        }

        private void ShowTitle()
        {
            titleActive = true;
            paused = false;
            inputLocked = true;
            Time.timeScale = 0f;
            if (titlePanel) titlePanel.gameObject.SetActive(true);
            if (onboardingPanel) onboardingPanel.gameObject.SetActive(false);
            if (pausePanel) pausePanel.gameObject.SetActive(false);
            if (settingsPanel) settingsPanel.gameObject.SetActive(false);
            if (victoryPanel) victoryPanel.gameObject.SetActive(false);
            if (achievementPanel) achievementPanel.gameObject.SetActive(false);
            if (runeCodexPanel) runeCodexPanel.gameObject.SetActive(false);
            if (aboutPanel) aboutPanel.gameObject.SetActive(false);
            UpdateTrialHeatTitleUi();
            noticeText.text = "准备开始试炼";
        }

        private string BuildTitleStatsText()
        {
            string bestTime = bestClearTime > 0 ? FormatTime(bestClearTime) : "--:--";
            string bestKills = bestRunKills > 0 ? bestRunKills.ToString() : "--";
            string daily = BuildDailyTrialTitleStats();
            return $"最佳 {bestTime} · K{bestKills} · {TrialHeatLabel()} · {daily} · 成就 {unlockedAchievements.Count}/{AchievementIds.Length}";
        }

        private string BuildTitleModeGuideText()
        {
            if (assistMode) return "辅助已开：先熟悉 Boss 前摇；今日试炼只记本机最佳。";
            if (trialHeatLevel >= 2) return "H2+ 挑战热度：适合首通后冲成就；SLOT 概率不变。";
            if (!unlockedAchievements.Contains("ClearTrial")) return "推荐：先完成首通；今日试炼是当天固定路线。";
            if (!unlockedAchievements.Contains("RuneRegular")) return "推荐：把 SLOT 留给精英、商店和 Boss 前节点，目标单局关键启封 3 次。";
            if (!unlockedAchievements.Contains("RouteArchivist")) return "推荐：刷不同路线，练跳跃、开箱和 Boss 前准备。";
            if (!unlockedAchievements.Contains("HeatClear")) return "推荐：切到 H2+ 追高热通关；今日只作本机挑战。";
            return "推荐：普通刷最佳时间；今日刷本机记录；热度不改概率。";
        }

        private void UpdateTrialHeatTitleUi()
        {
            if (titleHeatButtonText) titleHeatButtonText.text = "热度 " + TrialHeatLabel();
            if (titleStatsText) titleStatsText.text = BuildTitleStatsText();
            if (titleModeGuideText) titleModeGuideText.text = BuildTitleModeGuideText();
        }

        private void CycleTrialHeatLevel()
        {
            trialHeatLevel = (trialHeatLevel + 1) % 4;
            SaveSettings();
            UpdateTrialHeatTitleUi();
            if (noticeText) noticeText.text = $"试炼热度：{TrialHeatLabel()}";
            PlaySfx(sfxShop, .75f);
            HapticPulse(HapticTier.Medium);
        }

        private string TrialHeatLabel()
        {
            if (trialHeatLevel <= 0) return "标准";
            return "H" + Mathf.Clamp(trialHeatLevel, 0, 3);
        }

        private float TrialHeatEnemyHpScale()
        {
            return 1f + Mathf.Clamp(trialHeatLevel, 0, 3) * .11f;
        }

        private float TrialHeatEnemyDamageScale()
        {
            return 1f + Mathf.Clamp(trialHeatLevel, 0, 3) * .08f;
        }

        private float TrialHeatEnemySpeedScale()
        {
            return 1f + Mathf.Clamp(trialHeatLevel, 0, 3) * .045f;
        }

        private string BuildDailyTrialTitleStats()
        {
            int seed = DailyTrialSeed();
            string time = savedDailySeed == seed && dailyBestTime > 0f ? FormatTime(dailyBestTime) : "--:--";
            string kills = savedDailySeed == seed && dailyBestKills > 0 ? dailyBestKills.ToString() : "--";
            return $"今日 {time}/K{kills}";
        }

        private void StartRunFromTitle()
        {
            StartRunFromTitle(false);
        }

        private void StartDailyTrialFromTitle()
        {
            StartRunFromTitle(true);
        }

        private void StartRunFromTitle(bool daily)
        {
            pendingDailyTrialStart = daily;
            if (!onboardingSeen && onboardingPanel)
            {
                onboardingReplayMode = false;
                UpdateOnboardingButtonLabels();
                if (titlePanel) titlePanel.gameObject.SetActive(false);
                onboardingPanel.gameObject.SetActive(true);
                inputLocked = true;
                Time.timeScale = 0f;
                return;
            }
            BeginRunFromTitle();
        }

        private void ConfirmOnboardingAndStart()
        {
            if (onboardingReplayMode)
            {
                CloseOnboardingReplay();
                return;
            }
            onboardingSeen = true;
            PlayerPrefs.SetInt("DestinyRanger.OnboardingSeen", 1);
            PlayerPrefs.Save();
            if (onboardingPanel) onboardingPanel.gameObject.SetActive(false);
            BeginRunFromTitle();
        }

        private void DismissOnboardingOnly()
        {
            if (onboardingReplayMode)
            {
                CloseOnboardingReplay();
                return;
            }
            onboardingSeen = true;
            PlayerPrefs.SetInt("DestinyRanger.OnboardingSeen", 1);
            PlayerPrefs.Save();
            if (onboardingPanel) onboardingPanel.gameObject.SetActive(false);
            if (titlePanel) titlePanel.gameObject.SetActive(true);
            inputLocked = true;
            Time.timeScale = 0f;
        }

        private void ShowOnboardingReplayFromSettings()
        {
            if (!onboardingPanel) return;
            onboardingReplayMode = true;
            UpdateOnboardingButtonLabels();
            if (settingsPanel) settingsPanel.gameObject.SetActive(false);
            onboardingPanel.gameObject.SetActive(true);
            inputLocked = true;
            Time.timeScale = 0f;
            PlaySfx(sfxShop, .65f);
        }

        private void CloseOnboardingReplay()
        {
            onboardingReplayMode = false;
            if (onboardingPanel) onboardingPanel.gameObject.SetActive(false);
            if (settingsPanel) settingsPanel.gameObject.SetActive(true);
            UpdateOnboardingButtonLabels();
            UpdateSettingsText();
            inputLocked = true;
            Time.timeScale = 0f;
        }

        private void UpdateOnboardingButtonLabels()
        {
            if (onboardingStartButtonText) onboardingStartButtonText.text = onboardingReplayMode ? "返回设置" : "开始试炼";
            if (onboardingSkipButtonText) onboardingSkipButtonText.text = onboardingReplayMode ? "关闭简报" : "以后不再提示";
        }

        private void BeginRunFromTitle()
        {
            onboardingReplayMode = false;
            UpdateOnboardingButtonLabels();
            ResetRunState();
            ConfigureRunSeed(pendingDailyTrialStart);
            pendingDailyTrialStart = false;
            titleActive = false;
            if (titlePanel) titlePanel.gameObject.SetActive(false);
            if (onboardingPanel) onboardingPanel.gameObject.SetActive(false);
            if (settingsPanel) settingsPanel.gameObject.SetActive(false);
            Time.timeScale = 1f;
            inputLocked = false;
            StartStage(1);
        }

        private void ConfigureRunSeed(bool daily)
        {
            dailyTrialMode = daily;
            pendingDailyTrialStart = false;
            currentRunSeed = daily ? DailyTrialSeed() : UnityEngine.Random.Range(100000, 999999);
            rng = new System.Random(currentRunSeed);
        }

        private static int DailyTrialSeed()
        {
            return 700000 + (System.DateTime.Now.Year % 100) * 1000 + System.DateTime.Now.DayOfYear;
        }

        private void UpdateDailyTrialRecords(bool win)
        {
            if (!dailyTrialMode) return;
            int seed = DailyTrialSeed();
            if (savedDailySeed != seed)
            {
                savedDailySeed = seed;
                dailyBestTime = 0f;
                dailyBestKills = 0;
            }
            bool changed = false;
            dailyBestTimeUpdatedThisRun = false;
            dailyBestKillsUpdatedThisRun = false;
            if (killsThisRun > dailyBestKills)
            {
                dailyBestKills = killsThisRun;
                dailyBestKillsUpdatedThisRun = true;
                changed = true;
            }
            if (win && (dailyBestTime <= 0f || runTime < dailyBestTime))
            {
                dailyBestTime = runTime;
                dailyBestTimeUpdatedThisRun = true;
                changed = true;
            }
            if (!changed) return;
            PlayerPrefs.SetInt("DestinyRanger.DailySeed", savedDailySeed);
            PlayerPrefs.SetFloat("DestinyRanger.DailyBestTime", dailyBestTime);
            PlayerPrefs.SetInt("DestinyRanger.DailyBestKills", dailyBestKills);
        }

        private void ResetRunState()
        {
            maxHp = BaseMaxHp;
            maxMp = BaseMaxMp;
            hp = maxHp;
            mp = maxMp;
            exp = 0;
            trialLevel = 1;
            coins = 0;
            combo = 0;
            comboHits = 0;
            runeCount = 0;
            fateEnergy = 0;
            runTime = 0;
            killsThisRun = 0;
            damageTakenThisRun = 0;
            damageSourceHits.Clear();
            lastDamageSource = "无";
            perfectDodgesThisRun = 0;
            roomRewardsChosenThisRun = 0;
            highestComboThisRun = 0;
            modifiedRoomsClearedThisRun = 0;
            quickRunTimeThisRun = 0f;
            clearedNewBestTime = false;
            clearedNewKillRecord = false;
            dailyBestTimeUpdatedThisRun = false;
            dailyBestKillsUpdatedThisRun = false;
            Array.Clear(runMapLayoutsSeen, 0, runMapLayoutsSeen.Length);
            runeHistory.Clear();
            rewardHistory.Clear();
            cleanWorldVfxBudget.Clear();
            pendingRoomRewards.Clear();
            lastRune = "未启封";
            lastRuneDetail = "寻找 SLOT 改变流派";
            attackBufferTimer = 0f;
            jumpBufferTimer = 0f;
            dodgeBufferTimer = 0f;
            ClearSkillBuffers();
            ClearPlatformDropThrough();
            groundedGraceTimer = 0f;
            jumpAxisHeldLastFrame = false;
            jumpHeldLastFrame = false;
            touchJumpHeld = false;
            jumpCutApplied = false;
            airJumpsRemaining = MaxAirJumps;
            ResetJoystickIntentLock();
            ResetQuickRunIntent();
            ClearAutoAimTargetCue();
            HideSkillAimPreview();
            heroPosePunchTimer = 0f;
            heroPosePunchDuration = 0f;
            runFootstepTimer = 0f;
            attackMultiplier = 1f;
            moveMultiplier = 1f;
            swordRuneLevel = 0;
            dashRuneLevel = 0;
            frostRuneLevel = 0;
            thunderRuneLevel = 0;
            shieldRuneLevel = 0;
            heroActionLockTimer = 0;
            choosingRoomReward = false;
            finalVictorySequenceRunning = false;
            if (victoryPanel) victoryPanel.gameObject.SetActive(false);
            if (roomRewardPanel) roomRewardPanel.gameObject.SetActive(false);
        }

        private void UpdateUi()
        {
            hpFill.rectTransform.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, HudStatusBarFillWidth * Mathf.Clamp01(hp / maxHp));
            mpFill.rectTransform.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, HudStatusBarFillWidth * Mathf.Clamp01(mp / maxMp));
            if (fateFill) fateFill.rectTransform.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, HudStatusBarFillWidth * Mathf.Clamp01(fateEnergy / 100f));
            hpText.text = $"生命 {Mathf.CeilToInt(hp)}/{Mathf.CeilToInt(maxHp)}";
            mpText.text = $"精力 {Mathf.CeilToInt(mp)}/{Mathf.CeilToInt(maxMp)}";
            if (fateText) fateText.text = $"命运 {Mathf.FloorToInt(fateEnergy)}%";
            coinText.text = $"金币 {coins}";
            stageText.text = $"第 {stageIndex}/3 关";
            int currentAreaEnemies = ActiveEnemiesInCurrentArea();
            bool bossFocus = BossFocusHudActive();
            bool previewHudReadable = mapPreviewHudMode;
            bool explorationQuietHud = ExplorationQuietHudActive(currentAreaEnemies);
            UpdateRuneHudText(currentAreaEnemies, bossFocus, previewHudReadable, explorationQuietHud);
            UpdateNextSlotHintText();
            UpdateRuneOddsText();
            bool declutterHud = CombatHudDeclutterActive(currentAreaEnemies);
            if (stageText)
                stageText.color = bossFocus ? Color.clear : new Color(1f, 1f, 1f, previewHudReadable ? .62f : explorationQuietHud ? .36f : 1f);
            if (stageBannerImage)
                stageBannerImage.color = bossFocus ? new Color(1f, 1f, 1f, 0f) : new Color(1f, 1f, 1f, previewHudReadable ? .18f : explorationQuietHud ? .06f : .62f);
            if (runProgressText)
            {
                runProgressText.text = BuildRunProgressText();
                float progressAlpha = bossFocus ? .04f : previewHudReadable ? .18f : explorationQuietHud ? .08f : declutterHud ? .14f : .34f;
                runProgressText.color = new Color(.75f, .94f, 1f, progressAlpha);
            }
            UpdateRuneBadges();
            UpdateBuildStyleHud();
            UpdateRoomMarkers();
            UpdatePlatformRewardGuideDeclutter();
            UpdateForegroundReadabilityBand(currentAreaEnemies, bossFocus, declutterHud);
            UpdateHeroLandingPredictor();
            roomBannerTimer = Mathf.Max(0, roomBannerTimer - Time.deltaTime);
            comboMilestoneTimer = Mathf.Max(0f, comboMilestoneTimer - Time.deltaTime);
            if (roomTitleText)
            {
                bool showRoomTitle = !bossFocus && roomBannerTimer > 1.35f && !shrineAvailable && currentAreaEnemies <= 0;
                roomTitleText.text = showRoomTitle ? CurrentRoomTitle() : "";
                Color roomColor = RoomColor(Mathf.Clamp(currentSegment, 0, SegmentRights.Length - 1));
                float roomAlpha = showRoomTitle ? Mathf.Clamp01((roomBannerTimer - 1.35f) / .35f) * .36f : 0f;
                roomTitleText.color = new Color(roomColor.r, roomColor.g, roomColor.b, roomAlpha);
                if (roomTitleBackplate)
                    roomTitleBackplate.color = new Color(.02f, .04f, .08f, roomAlpha * .30f);
            }
            if (tutorialText)
            {
                string hint = TutorialHint();
                tutorialText.text = hint;
                bool showHint = !bossFocus && !string.IsNullOrEmpty(hint) && (tutorialStep <= 1 || roomBannerTimer > 0f || shrineAvailable || CanUseShopInteraction());
                tutorialText.color = showHint
                    ? new Color(.78f, .96f, 1f, .72f)
                    : new Color(1, 1, 1, 0);
                if (tutorialBackplate)
                    tutorialBackplate.color = showHint ? new Color(.02f, .055f, .085f, .12f) : new Color(.02f, .06f, .10f, 0f);
            }
            string objectiveLine = CompactObjectiveTextForHud(currentAreaEnemies);
            if (objectiveLine != lastObjectiveHudText)
            {
                ShowObjectiveHudTransitionCue(lastObjectiveHudText, objectiveLine, currentAreaEnemies);
                lastObjectiveHudText = objectiveLine;
            }
            objectiveText.text = objectiveLine;
            float objectiveAlpha = bossFocus ? .10f : previewHudReadable ? .42f : explorationQuietHud ? .18f : currentAreaEnemies > 0 ? .34f : shrineAvailable || CanUseShopInteraction() ? .70f : .42f;
            objectiveText.color = currentAreaEnemies > 0
                ? new Color(.92f, .98f, 1f, objectiveAlpha)
                : new Color(.86f, .96f, 1f, objectiveAlpha);
            if (objectiveBackplate)
                objectiveBackplate.color = new Color(.02f, .04f, .08f, objectiveAlpha * (bossFocus ? .10f : previewHudReadable ? .12f : currentAreaEnemies > 0 ? .08f : .22f));
            UpdateNoticeHud(currentAreaEnemies);
            UpdateTargetCompass(currentAreaEnemies);
            UpdateFirstRunNudge(currentAreaEnemies);
            comboDisplayTimer -= Time.deltaTime;
            if (comboDisplayTimer <= 0)
            {
                comboHits = 0;
                comboMilestoneLevel = 0;
            }
            UpdateComboMeter();
            UpdateHitConfirmHud();
            UpdateHeroActionBeatHud();
            UpdateVisibleSkillHud();
            UpdateSecondsText(dodgeCooldownText, dodgeCooldown);
            UpdateControlStateTexts();
            UpdateRuneReadyText();
            RefreshBossFocusControlLayoutIfNeeded();
            ApplyCombatControlOpacity();
            UpdateMinimap();
            UpdateBossHud();
            UpdateBossArenaLockdown();
            UpdateThreatAlertHud();
            if (dangerVignette)
            {
                float lowHp = Mathf.Clamp01(1f - hp / Mathf.Max(1f, maxHp));
                float flash = invulnTimer > 0 ? .16f * DangerVignetteScale() : 0f;
                dangerVignette.color = new Color(.85f, .04f, .02f, Mathf.Clamp01((lowHp * .22f + flash) * DangerVignetteScale()));
            }
            UpdateLowHealthHint();
            UpdateHurtRecoveryHint();
            UpdateDamageDirectionCue();
            if (combatFlash)
            {
                combatFlashTimer -= Time.deltaTime;
                float alpha = combatFlashTimer > 0 ? combatFlashStrength * Mathf.Clamp01(combatFlashTimer / .12f) : 0f;
                combatFlash.color = new Color(.82f, .96f, 1f, Mathf.Clamp01(alpha));
                if (combatFlashTimer <= 0) combatFlashStrength = Mathf.MoveTowards(combatFlashStrength, 0f, Time.deltaTime * 3f);
            }
            mp = Mathf.Min(maxMp, mp + Time.deltaTime * 8f);
        }

        private void UpdateDamageDirectionCue()
        {
            if (!damageDirectionCue) return;
            damageDirectionTimer = Mathf.Max(0f, damageDirectionTimer - Time.deltaTime);
            if (damageDirectionTimer <= 0f)
            {
                damageDirectionCue.color = Color.clear;
                return;
            }

            var rt = damageDirectionCue.rectTransform;
            bool horizontal = Mathf.Abs(damageDirectionVector.x) >= Mathf.Abs(damageDirectionVector.y);
            float alpha = Mathf.Clamp01(damageDirectionTimer / .72f) * .42f * DangerVignetteScale();
            damageDirectionCue.color = new Color(1f, .08f, .04f, alpha);
            if (horizontal)
            {
                bool right = damageDirectionVector.x > 0f;
                rt.anchorMin = right ? new Vector2(.965f, 0f) : new Vector2(0f, 0f);
                rt.anchorMax = right ? Vector2.one : new Vector2(.035f, 1f);
            }
            else
            {
                bool top = damageDirectionVector.y > 0f;
                rt.anchorMin = top ? new Vector2(0f, .93f) : Vector2.zero;
                rt.anchorMax = top ? Vector2.one : new Vector2(1f, .07f);
            }
            rt.offsetMin = Vector2.zero;
            rt.offsetMax = Vector2.zero;
        }

        private void UpdateLowHealthHint()
        {
            if (!lowHealthHintText || !lowHealthHintBackplate) return;
            float hpRatio = hp / Mathf.Max(1f, maxHp);
            bool show = hpRatio <= .30f && hp > 0f && !titleActive && !inputLocked;
            float alpha = show ? Mathf.Lerp(.62f, .92f, .5f + Mathf.Sin(Time.time * 5.2f) * .5f) : 0f;
            lowHealthHintBackplate.color = new Color(.16f, .03f, .04f, alpha * .62f);
            lowHealthHintText.color = new Color(1f, .86f, .74f, alpha);
            lowHealthHintText.text = show ? LowHealthHintText() : "";
        }

        private string LowHealthHintText()
        {
            if (CanUseShopInteraction() && coins >= 50 && !shopHealSoldThisStage) return "生命危险：靠近商人点补给，50 金币恢复生命";
            if (currentSegment < ShopRoomIndex) return "生命危险：先稳住距离，推进到商店房回血";
            if (shieldRuneLevel > 0 || frostRuneLevel > 0) return "生命危险：利用盾/冰容错，等闪避冷却后再进攻";
            return "生命危险：优先闪避红区，寻找盾/冰/生命房间奖励";
        }

        private void ShowHurtRecoveryHint(string sourceLabel)
        {
            hurtRecoveryHintTimer = .92f;
            hurtRecoveryHint = BuildHurtRecoveryHint(sourceLabel);
        }

        private string BuildHurtRecoveryHint(string sourceLabel)
        {
            sourceLabel = string.IsNullOrEmpty(sourceLabel) ? "" : sourceLabel;
            if (sourceLabel.Contains("Boss")) return "受击恢复：短暂无敌，先离开 Boss 红区";
            if (sourceLabel.Contains("弹幕") || sourceLabel.Contains("远程") || sourceLabel.Contains("弓手")) return "受击恢复：短暂无敌，横移拉开等闪避";
            if (hp <= maxHp * .32f && CanUseShopInteraction() && coins >= 50) return "受击恢复：短暂无敌，靠近商人补给";
            if (shieldRuneLevel > 0 || frostRuneLevel > 0) return "受击恢复：短暂无敌，用盾/冰稳住节奏";
            return "受击恢复：短暂无敌，拉开半步再反击";
        }

        private void UpdateHurtRecoveryHint()
        {
            if (!hurtRecoveryText || !hurtRecoveryBackplate) return;
            hurtRecoveryHintTimer = Mathf.Max(0f, hurtRecoveryHintTimer - Time.deltaTime);
            bool show = hurtRecoveryHintTimer > 0f && hp > 0f && !titleActive && !string.IsNullOrEmpty(hurtRecoveryHint);
            float alpha = show ? Mathf.Clamp01(hurtRecoveryHintTimer / .24f) * (effectsIntensity > .75f ? .88f : .68f) : 0f;
            hurtRecoveryBackplate.color = new Color(.10f, .03f, .04f, alpha * .58f);
            hurtRecoveryText.text = show ? hurtRecoveryHint : "";
            hurtRecoveryText.color = new Color(1f, .86f, .74f, alpha);
        }

        private void UpdateNoticeHud(int currentAreaEnemies)
        {
            if (!noticeText) return;
            string rawText = noticeText.text ?? "";
            string text = CompactNoticeCopyForHud(rawText);
            if (text != lastNoticeHudText)
            {
                lastNoticeHudText = text;
                noticeVisibleTimer = string.IsNullOrEmpty(text) ? 0f : NoticeVisibleSecondsForHud(text);
            }
            else
            {
                noticeVisibleTimer = Mathf.Max(0f, noticeVisibleTimer - Time.deltaTime);
            }
            noticeText.text = text;
            bool debugRouteNotice = text.Contains("地图验证") || text.Contains("路线目标") || text.Contains("路线复盘");
            bool important = shrineAvailable
                || choosingRoomReward
                || currentAreaEnemies <= 0 && (text.Contains("奖励") || text.Contains("SLOT") || text.Contains("启封"))
                || text.Contains("精英")
                || text.Contains("通关")
                || text.Contains("失败")
                || text.Contains("魔力不足");
            bool bossHudActive = enemies.Any(e => e.Boss && !e.Dead && e.Root);
            if (bossHudActive && !choosingRoomReward && !shrineAvailable && !text.Contains("魔力不足")) important = false;
            bool threatActive = threatAlertTimer > 0f;
            bool combatNoticeAllowed = ShouldShowNoticeInCombat(text, currentAreaEnemies, threatActive, bossHudActive);
            bool transient = !debugRouteNotice && threatActive;
            bool stickyInteraction = shrineAvailable || choosingRoomReward || CanUseShopInteraction();
            float lifeAlpha = stickyInteraction ? 1f : Mathf.Clamp01(noticeVisibleTimer / .28f);
            float alpha = !debugRouteNotice && combatNoticeAllowed && (important || transient) && lifeAlpha > 0f ? (bossHudActive ? .28f : threatActive ? .26f : .62f) * lifeAlpha : 0f;
            noticeText.color = new Color(1f, 1f, 1f, alpha);
            if (noticeBackplate)
                noticeBackplate.color = new Color(.02f, .04f, .08f, alpha * (threatActive ? .20f : .34f));
        }

        private static float NoticeVisibleSecondsForHud(string text)
        {
            if (string.IsNullOrEmpty(text)) return 0f;
            if (text.Contains("失败") || text.Contains("通关") || text.Contains("最终") || text.Contains("Boss 击破")) return NoticeCriticalVisibleSeconds;
            if (text.Contains("SLOT") || text.Contains("启封") || text.Contains("奖励") || text.Contains("补给") || text.Contains("商人")) return NoticeInteractionVisibleSeconds;
            if (text.Contains("Boss") || text.Contains("精英") || text.Contains("狂暴") || text.Contains("魔力不足") || text.Contains("门未开")) return NoticeThreatVisibleSeconds;
            return NoticeDefaultVisibleSeconds;
        }

        private bool ShouldShowNoticeInCombat(string text, int currentAreaEnemies, bool threatActive, bool bossHudActive)
        {
            if (currentAreaEnemies <= 0 && !bossHudActive && !threatActive) return true;
            if (string.IsNullOrEmpty(text)) return false;
            if (text.Contains("魔力不足") || text.Contains("受击") || text.Contains("失败")) return true;
            if (text.Contains("门未开") || text.Contains("清敌")) return true;
            if (threatActive && (text.Contains("Boss") || text.Contains("精英") || text.Contains("狂暴"))) return true;
            if (bossHudActive) return false;
            return false;
        }

        private string CompactNoticeCopyForHud(string text)
        {
            if (string.IsNullOrEmpty(text)) return "";
            if (text.Contains("SLOT 宝箱出现") || text.Contains("命运宝箱已打开")) return "SLOT 宝箱已出现，靠近启封";
            if (text.Contains("SLOT 已开启")) return "SLOT 已开启，可启封或继续";
            if (text.Contains("小宝箱可选，不锁路")) return "小宝箱可选，不锁路，向右推进";
            if (text.Contains("门未开")) return text;
            if (text.Contains("清掉本房敌人")) return "门未开 · 清敌";
            if (text.Contains("房间奖励")) return "选择房间奖励";
            if (text.Contains("商人启封")) return "商人召出 SLOT 宝箱";
            if (text.Contains("符文商人")) return "符文商人：补给或启封";
            if (text.Contains("地图：")) return MapLayoutShortName();
            if (text.Contains("路线目标")) return MapLayoutShortName();
            if (text.Contains("进入：")) return "进入 " + CurrentRoomTitle();
            if (text.Contains("已选择：")) return "奖励已选择，继续推进";
            if (text.Contains("基础试炼已熟悉")) return "继续推进，寻找 SLOT";
            if (text.Contains("关卡清空")) return "关卡清空，继续推进";
            if (text.Contains("最终命运已启封")) return "最终命运已启封";
            if (text.Contains("守护者巨像击破")) return "Boss 击破，最终启封";
            if (text.Contains("Boss 碎甲狂暴")) return "Boss 狂暴，雷阵展开";
            int divider = text.IndexOf("  |  ", StringComparison.Ordinal);
            if (divider >= 0) text = text.Substring(0, divider);
            return text.Length > 24 ? text.Substring(0, 24) : text;
        }

        private void UpdateFirstRunNudge(int currentAreaEnemies)
        {
            if (!firstRunNudgeText || !firstRunNudgeBackplate) return;
            string message = FirstRunNudgeMessage(currentAreaEnemies);
            bool show = !string.IsNullOrEmpty(message);
            if (CombatHudDeclutterActive(currentAreaEnemies)) show = false;
            if (tutorialText && tutorialText.color.a > .1f) show = false;
            float alpha = show ? .52f : 0f;
            firstRunNudgeBackplate.color = new Color(.02f, .07f, .10f, alpha * .24f);
            firstRunNudgeText.color = new Color(.78f, 1f, .96f, alpha);
            firstRunNudgeText.text = show ? message : "";
        }

        private string FirstRunNudgeMessage(int currentAreaEnemies)
        {
            if (tutorialCompleted || stageIndex != 1 || titleActive || paused || inputLocked || rollingRune || choosingRoomReward || controlEditMode || !player) return "";
            if ((shopPanel && shopPanel.gameObject.activeSelf) || (settingsPanel && settingsPanel.gameObject.activeSelf) || (achievementPanel && achievementPanel.gameObject.activeSelf) || (runeCodexPanel && runeCodexPanel.gameObject.activeSelf) || (aboutPanel && aboutPanel.gameObject.activeSelf)) return "";

            if (shrineAvailable) return "靠近宝箱，点启封";
            if (CanUseShopInteraction())
            {
                if (hp <= maxHp * .55f && coins >= 50 && !shopHealSoldThisStage) return "低血先补给";
                if (coins >= 100) return "100 金币可召 SLOT";
                return "金币不足，继续推进";
            }
            if (currentAreaEnemies <= 0 && ActivePlatformRuneVesselInSegment(currentSegment)) return "平台小宝箱可选";
            if (tutorialStep <= 1) return "三连斩第三段更重";
            if (runeCount <= 0 && currentSegment >= 1 && fateEnergy < 100f) return "攒能量，找 SLOT";
            if (hp <= maxHp * .36f && currentSegment < ShopRoomIndex) return "低血拉开，去商店";
            return "";
        }

        private void UpdateThreatAlertHud()
        {
            if (!threatAlertText) return;
            threatAlertTimer = Mathf.Max(0f, threatAlertTimer - Time.deltaTime);
            bool show = threatAlertTimer > 0f && !string.IsNullOrEmpty(threatAlertLabel) && !titleActive && !paused && !inputLocked;
            threatAlertText.gameObject.SetActive(show);
            if (threatAlertBackplate) threatAlertBackplate.gameObject.SetActive(show);
            if (!show)
            {
                threatAlertText.color = Color.clear;
                if (threatAlertBackplate) threatAlertBackplate.color = Color.clear;
                return;
            }

            float alpha = Mathf.Clamp01(threatAlertTimer / .64f) * (effectsIntensity > .75f ? .96f : .76f);
            bool bossFocus = BossFocusHudActive();
            Vector2 alertPos = bossFocus ? new Vector2(0, -438) : new Vector2(0, -352);
            Vector2 alertSize = bossFocus ? new Vector2(720, 56) : new Vector2(780, 60);
            Vector2 plateSize = bossFocus ? new Vector2(740, 58) : new Vector2(820, 62);
            threatAlertText.rectTransform.anchoredPosition = alertPos;
            threatAlertText.rectTransform.sizeDelta = alertSize;
            threatAlertText.fontSize = bossFocus ? 32 : 38;
            threatAlertText.text = CompactThreatAlertCopy();
            Color textColor = Color.Lerp(new Color(.96f, 1f, 1f, 1f), threatAlertColor, .38f);
            threatAlertText.color = new Color(textColor.r, textColor.g, textColor.b, alpha);
            float pop = 1f + Mathf.Sin(Mathf.Clamp01(1f - Mathf.Clamp01(threatAlertTimer / 1.1f)) * Mathf.PI) * .045f;
            threatAlertText.rectTransform.localScale = new Vector3(pop, pop, 1f);
            if (threatAlertBackplate)
            {
                threatAlertBackplate.rectTransform.anchoredPosition = alertPos;
                threatAlertBackplate.rectTransform.sizeDelta = plateSize;
                threatAlertBackplate.color = new Color(.13f, .025f, .025f, alpha * .50f);
                threatAlertBackplate.rectTransform.localScale = new Vector3(pop, pop, 1f);
            }
        }

        private string CompactThreatAlertCopy()
        {
            string title = threatAlertLabel ?? "";
            if (title.Contains("砸地")) title = "砸地";
            else if (title.Contains("激光")) title = "激光";
            else if (title.Contains("雷阵")) title = "雷阵";
            else if (title.Contains("弓手") || title.Contains("射击")) title = "射击";
            else if (title.Contains("毒")) title = "毒圈";
            else if (title.Contains("Boss")) title = "Boss";
            else title = "突袭";

            string advice = threatAlertAdvice ?? "";
            string action = advice.Contains("跳") ? "跳过"
                : advice.Contains("反击") || advice.Contains("收招") ? "等收招"
                : advice.Contains("冷却") || advice.Contains("拉开") ? "拉开"
                : advice.Contains("红") || advice.Contains("离开") ? "离开"
                : "闪避";
            return $"{title} · {action}";
        }

        private void UpdateMinimap()
        {
            bool bossFocus = BossFocusHudActive();
            int currentAreaEnemies = ActiveEnemiesInCurrentArea();
            bool quietHud = ExplorationQuietHudActive(currentAreaEnemies);
            bool combatHud = CombatHudDeclutterActive(currentAreaEnemies);
            if (routeMinimapGroup)
            {
                routeMinimapGroup.gameObject.SetActive(!bossFocus);
                float targetAlpha = bossFocus ? 0f : mapPreviewHudMode ? .60f : combatHud ? .14f : quietHud ? .20f : .72f;
                routeMinimapGroup.alpha = Application.isPlaying
                    ? Mathf.MoveTowards(routeMinimapGroup.alpha, targetAlpha, Time.unscaledDeltaTime * 8f)
                    : targetAlpha;
                routeMinimapGroup.blocksRaycasts = false;
            }
            if (bossFocus) return;
            for (int i = 0; i < minimapNodes.Count; i++)
            {
                var node = minimapNodes[i];
                if (!node) continue;
                bool completed = i < currentSegment;
                bool active = i == Mathf.Clamp(currentSegment, 0, SegmentRights.Length - 1);
                bool bossNode = stageIndex == 3 && i == minimapNodes.Count - 1;
                bool shopNode = i == ShopRoomIndex;
                bool eliteNode = i == EliteRoomIndex;
                Color color = completed ? C("#6CE6B6") : C("#52677A");
            if (active) color = shrineAvailable ? C("#20E6E6") : C("#8FFFF6");
                if (!active && shopNode) color = completed ? C("#6CE6B6") : C("#48A868");
                if (!active && eliteNode) color = completed ? C("#6CE6B6") : C("#95D65A");
                if (!active && bossNode) color = completed ? C("#6CE6B6") : C("#D85757");
                node.color = color;
            }
            if (minimapText)
            {
                minimapText.text = "";
                minimapText.color = Color.clear;
            }
            UpdatePlatformRouteHint();
        }

        private void UpdatePlatformRouteHint()
        {
            if (!platformRouteHintText) return;
            var vessel = NearestPlatformRuneVesselInSegment(currentSegment);
            int currentAreaEnemies = ActiveEnemiesInCurrentArea();
            bool roomCleared = currentAreaEnemies <= 0;
            float chestDistance = vessel != null && vessel.Root && player ? Vector2.Distance(vessel.Root.transform.position, player.transform.position) : 99f;
            bool closeToChest = chestDistance < PlatformRouteHintClearedDistance;
            bool show = vessel != null && vessel.Root && !titleActive && !choosingRoomReward && !shrineAvailable && closeToChest && roomCleared;
            platformRouteHintText.gameObject.SetActive(show);
            if (!show)
            {
                platformRouteHintText.text = "";
                platformRouteHintText.color = Color.clear;
                return;
            }
            float dx = vessel.Root.transform.position.x - player.transform.position.x;
            string side = Mathf.Abs(dx) < .8f ? "附近" : dx > 0 ? $"右{Mathf.CeilToInt(Mathf.Abs(dx))}m" : $"左{Mathf.CeilToInt(Mathf.Abs(dx))}m";
            float dy = vessel.Root.transform.position.y - player.transform.position.y;
            // 平台路线提示必须短，只在清房后显示，避免混战时抢画面。
            string action = Mathf.Abs(dx) < 1.6f
                ? dy > .55f ? "跳上打箱" : "攻击开箱"
                : dy > .55f ? "高台箱" : "顺路开箱";
            platformRouteHintText.text = $"箱 {side} · {action}";
            float alpha = .54f + Mathf.Sin(Time.unscaledTime * 4.8f) * .07f;
            platformRouteHintText.color = new Color(.74f, .96f, 1f, Mathf.Clamp01(alpha * .48f));
        }

        private void UpdateComboMeter()
        {
            if (!comboText) return;
            bool show = comboHits >= 4 && comboDisplayTimer > 0;
            bool bossFocus = BossFocusHudActive();
            comboText.gameObject.SetActive(show);
            if (comboBackplate) comboBackplate.gameObject.SetActive(show);
            if (comboHeatBarRoot) comboHeatBarRoot.gameObject.SetActive(show);
            UpdateComboMilestoneHud();
            if (!show)
            {
                comboText.rectTransform.localScale = Vector3.one;
                if (comboHeatBarRoot) comboHeatBarRoot.localScale = Vector3.one;
                return;
            }

            string rank = comboHits >= 20 ? "极限" : comboHits >= 12 ? "狂热" : comboHits >= 6 ? "连斩" : "连击";
            comboText.text = $"{comboHits} 连击 · {rank}";
            Color cold = C("#BFEFFF");
            Color hot = C("#8FFFF6");
            Color peak = C("#E8FFFF");
            float heat = Mathf.Clamp01((comboHits - 2) / 16f);
            ApplyComboHudLayout(bossFocus, heat);
            comboText.color = heat < .65f ? Color.Lerp(cold, hot, heat / .65f) : Color.Lerp(hot, peak, (heat - .65f) / .35f);
            if (comboHeatFill)
            {
                comboHeatFill.rectTransform.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, Mathf.Lerp(24f, bossFocus ? 150f : 250f, heat));
                comboHeatFill.color = comboText.color;
            }
            float hitPulse = Mathf.Clamp01((comboDisplayTimer - 1.18f) / .22f);
            float scale = 1f + hitPulse * (bossFocus ? .09f : .16f) + Mathf.Sin(Time.unscaledTime * 12f) * (bossFocus ? .014f : .025f) * heat;
            comboText.rectTransform.localScale = Vector3.Lerp(comboText.rectTransform.localScale, new Vector3(scale, scale, 1), Time.unscaledDeltaTime * 16f);
            if (comboHeatBarRoot) comboHeatBarRoot.localScale = comboText.rectTransform.localScale;
            if (comboBackplate)
            {
                comboBackplate.color = new Color(.02f, .04f, .08f, Mathf.Lerp(bossFocus ? .14f : .26f, bossFocus ? .26f : .46f, heat));
                comboBackplate.rectTransform.localScale = comboText.rectTransform.localScale;
            }
        }

        private void ApplyComboHudLayout(bool bossFocus, float heat)
        {
            Vector2 comboCenter = bossFocus ? new Vector2(-430, -142) : new Vector2(-150, -238);
            Vector2 comboSize = bossFocus ? new Vector2(270, 48) : new Vector2(390, 70);
            Vector2 plateSize = bossFocus ? new Vector2(290, 48) : new Vector2(410, 70);
            Vector2 heatCenter = bossFocus ? new Vector2(-560, -178) : new Vector2(-344, -282);
            Vector2 heatSize = bossFocus ? new Vector2(150, 6) : new Vector2(250, 10);
            if (comboBackplate)
            {
                comboBackplate.rectTransform.anchoredPosition = comboCenter;
                comboBackplate.rectTransform.sizeDelta = plateSize;
            }
            comboText.rectTransform.anchoredPosition = comboCenter + (bossFocus ? new Vector2(-10, 0) : Vector2.zero);
            comboText.rectTransform.sizeDelta = comboSize;
            comboText.fontSize = bossFocus ? 34 : 52;
            FitHudText(comboText, bossFocus ? 26 : 36, bossFocus ? 34 : 52);
            if (comboHeatBarRoot)
            {
                comboHeatBarRoot.anchoredPosition = heatCenter;
                comboHeatBarRoot.sizeDelta = heatSize;
            }
            if (comboHeatFill)
            {
                comboHeatFill.rectTransform.sizeDelta = new Vector2(Mathf.Lerp(24f, bossFocus ? 150f : 250f, heat), heatSize.y);
            }
        }

        private void CheckComboMilestone(HitTier tier, bool boss)
        {
            int level = comboHits >= 20 ? 3 : comboHits >= 12 ? 2 : comboHits >= 6 ? 1 : 0;
            if (level <= 0 || level <= comboMilestoneLevel) return;
            comboMilestoneLevel = level;
            comboMilestoneTimer = level == 3 ? 1.25f : .95f;
            string label = level == 3 ? "极限连击" : level == 2 ? "狂热压制" : "连斩启动";
            if (tier == HitTier.Heavy) label += " · 破势";
            else if (tier == HitTier.Skill) label += " · 术式";
            else if (boss) label += " · Boss";
            if (noticeText && level >= 3) noticeText.text = $"{label}：保持节奏";
            PlaySfx(level >= 2 ? sfxHeavyHit : sfxHit, level >= 3 ? .82f : .58f);
            if (level >= 2) HapticPulse(level == 3 ? HapticTier.Heavy : HapticTier.Medium);
        }

        private void UpdateComboMilestoneHud()
        {
            bool show = comboMilestoneTimer > 0f && comboMilestoneLevel > 0;
            if (comboMilestoneText)
            {
                comboMilestoneText.gameObject.SetActive(show);
                if (show)
                {
                    string label = comboMilestoneLevel == 3 ? "极限连击" : comboMilestoneLevel == 2 ? "狂热" : "连斩";
                    float alpha = Mathf.Clamp01(comboMilestoneTimer / .32f);
                    comboMilestoneText.text = label;
                    comboMilestoneText.color = comboMilestoneLevel == 3
                        ? new Color(1f, .52f, .30f, alpha)
                        : comboMilestoneLevel == 2
                            ? new Color(.55f, .96f, 1f, alpha)
                            : new Color(.70f, .96f, 1f, alpha);
                    float scale = 1f + Mathf.Sin(Time.unscaledTime * 12f) * .025f;
                    comboMilestoneText.rectTransform.localScale = new Vector3(scale, scale, 1f);
                }
            }
            if (comboMilestoneBackplate)
            {
                comboMilestoneBackplate.gameObject.SetActive(show);
                float alpha = show ? Mathf.Clamp01(comboMilestoneTimer / .32f) : 0f;
                comboMilestoneBackplate.color = new Color(.02f, .04f, .08f, alpha * .46f);
            }
        }

        private void ShowHitConfirm(HitTier tier, bool boss)
        {
            if (!hitConfirmText) return;
            bool light = tier == HitTier.Light && !boss;
            if (light && lightHitConfirmCooldown > 0f) return;
            if (light) lightHitConfirmCooldown = .30f;
            hitConfirmLightHit = light;
            hitConfirmDuration = light ? LightHitConfirmDuration : tier == HitTier.Skill ? .52f : .62f;
            hitConfirmTimer = hitConfirmDuration;
            hitConfirmImpactPower = boss ? 1f : tier == HitTier.Heavy ? 1f : tier == HitTier.Skill ? .78f : .42f;
            if (boss)
            {
                hitConfirmLabel = tier == HitTier.Skill ? "术式破甲" : tier == HitTier.Heavy ? "BOSS 破势" : "BOSS 命中";
                hitConfirmColor = C("#9FF8FF");
                hitConfirmTierLabel = tier == HitTier.Skill ? "Boss / 术式" : tier == HitTier.Heavy ? "Boss / 破势" : "Boss / 命中";
                return;
            }
            if (tier == HitTier.Heavy)
            {
                hitConfirmLabel = "破势命中";
                hitConfirmColor = C("#9FF8FF");
                hitConfirmTierLabel = "破势 / 强命中";
            }
            else if (tier == HitTier.Skill)
            {
                hitConfirmLabel = "术式命中";
                hitConfirmColor = C("#7EDCFF");
                hitConfirmTierLabel = "术式 / 范围命中";
            }
            else
            {
                hitConfirmLabel = "命中";
                hitConfirmColor = C("#FFFFFF");
                hitConfirmTierLabel = "";
            }
        }

        private void UpdateHitConfirmHud()
        {
            if (!hitConfirmText) return;
            hitConfirmTimer = Mathf.Max(0f, hitConfirmTimer - Time.deltaTime);
            bool show = hitConfirmTimer > 0f && !string.IsNullOrEmpty(hitConfirmLabel);
            bool showTier = show && !string.IsNullOrEmpty(hitConfirmTierLabel);
            hitConfirmText.gameObject.SetActive(show);
            if (hitConfirmTierText) hitConfirmTierText.gameObject.SetActive(showTier);
            if (hitConfirmBackplate) hitConfirmBackplate.gameObject.SetActive(show);
            if (hitConfirmImpactBarRoot) hitConfirmImpactBarRoot.gameObject.SetActive(show);
            if (!show)
            {
                hitConfirmText.color = Color.clear;
                if (hitConfirmTierText) hitConfirmTierText.color = Color.clear;
                hitConfirmLightHit = false;
                return;
            }

            float duration = Mathf.Max(.01f, hitConfirmDuration);
            float t = Mathf.Clamp01(hitConfirmTimer / duration);
            float alpha = Mathf.Clamp01(t * (hitConfirmLightHit ? 1.55f : 1.35f)) * (effectsIntensity > .75f ? .95f : .72f);
            float hitConfirmFocusAlpha = BossFocusControlDeclutterActive() ? .52f : 1f;
            hitConfirmText.text = hitConfirmLabel;
            hitConfirmText.fontSize = hitConfirmLightHit ? 30 : 34;
            hitConfirmText.rectTransform.sizeDelta = hitConfirmLightHit ? new Vector2(224, 48) : new Vector2(320, 60);
            hitConfirmText.color = new Color(hitConfirmColor.r, hitConfirmColor.g, hitConfirmColor.b, alpha);
            if (hitConfirmTierText && showTier)
            {
                hitConfirmTierText.fontSize = 17;
                hitConfirmTierText.rectTransform.sizeDelta = new Vector2(320, 28);
                hitConfirmTierText.text = hitConfirmTierLabel;
                hitConfirmTierText.color = new Color(.78f, .93f, 1f, alpha * .78f);
            }
            else if (hitConfirmTierText)
            {
                hitConfirmTierText.text = "";
                hitConfirmTierText.color = Color.clear;
            }
            float pop = 1f + Mathf.Sin(Mathf.Clamp01(1f - t) * Mathf.PI) * .16f;
            hitConfirmText.rectTransform.localScale = new Vector3(pop, pop, 1f);
            if (hitConfirmTierText) hitConfirmTierText.rectTransform.localScale = new Vector3(Mathf.Lerp(1f, pop, .45f), Mathf.Lerp(1f, pop, .45f), 1f);
            if (hitConfirmBackplate)
            {
                hitConfirmBackplate.rectTransform.sizeDelta = hitConfirmLightHit ? LightHitConfirmBackplateSize : StrongHitConfirmBackplateSize;
                float plateAlpha = hitConfirmLightHit ? .24f : .42f;
                hitConfirmBackplate.color = new Color(.02f, .04f, .08f, alpha * plateAlpha * hitConfirmFocusAlpha);
                hitConfirmBackplate.rectTransform.localScale = hitConfirmText.rectTransform.localScale;
            }
            if (hitConfirmImpactBarRoot)
            {
                var bg = hitConfirmImpactBarRoot.GetComponent<Image>();
                hitConfirmImpactBarRoot.sizeDelta = hitConfirmLightHit ? LightHitConfirmImpactBarSize : StrongHitConfirmImpactBarSize;
                if (bg) bg.color = new Color(.02f, .08f, .12f, alpha * (hitConfirmLightHit ? .26f : .50f) * hitConfirmFocusAlpha);
                hitConfirmImpactBarRoot.localScale = new Vector3(Mathf.Lerp(1f, pop, .32f), 1f, 1f);
            }
            if (hitConfirmImpactFill)
            {
                hitConfirmImpactFill.color = new Color(hitConfirmColor.r, hitConfirmColor.g, hitConfirmColor.b, alpha * .92f);
                float minWidth = hitConfirmLightHit ? 34f : showTier ? 76f : 54f;
                float maxWidth = hitConfirmLightHit ? 96f : showTier ? 260f : 168f;
                hitConfirmImpactFill.rectTransform.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, Mathf.Lerp(minWidth, maxWidth, Mathf.Clamp01(hitConfirmImpactPower)));
                hitConfirmImpactFill.rectTransform.SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, hitConfirmLightHit ? 8f : 10f);
            }
        }

        private void ShowHeroActionBeat(string label, int[] frames, float fps, float duration, string timing, Color color)
        {
            if (!showHeroActionBeatHud)
            {
                HideHeroActionBeatHud();
                return;
            }
            heroActionBeatLabel = label;
            heroActionBeatTiming = timing;
            heroActionBeatFps = fps;
            heroActionBeatTimer = Mathf.Max(heroActionBeatTimer, duration);
            heroActionBeatColor = color;
            if (frames != null && frames.Length > 0)
            {
                heroActionBeatStartFrame = frames.Min();
                heroActionBeatEndFrame = frames.Max();
            }
            else
            {
                heroActionBeatStartFrame = lastVisibleHeroFrame;
                heroActionBeatEndFrame = lastVisibleHeroFrame;
            }
        }

        private void UpdateHeroActionBeatHud()
        {
            if (!heroActionBeatText) return;
            if (!showHeroActionBeatHud)
            {
                HideHeroActionBeatHud();
                return;
            }
            heroActionBeatTimer = Mathf.Max(0f, heroActionBeatTimer - Time.deltaTime);
            bool show = heroActionBeatTimer > 0f && !string.IsNullOrEmpty(heroActionBeatLabel) && ShouldShowHeroActionBeatHudLabel(heroActionBeatLabel);
            heroActionBeatText.gameObject.SetActive(show);
            if (heroActionBeatBackplate) heroActionBeatBackplate.gameObject.SetActive(show);
            if (!show)
            {
                heroActionBeatText.color = Color.clear;
                if (heroActionBeatBackplate) heroActionBeatBackplate.color = Color.clear;
                return;
            }

            bool declutterHud = CombatHudDeclutterActive(ActiveEnemiesInCurrentArea());
            float alpha = Mathf.Clamp01(heroActionBeatTimer / .38f) * (effectsIntensity > .75f ? .82f : .62f) * (declutterHud ? .70f : 1f);
            string frameRange = heroActionBeatStartFrame == heroActionBeatEndFrame ? $"F{heroActionBeatStartFrame}" : $"F{heroActionBeatStartFrame}-{heroActionBeatEndFrame}";
            heroActionBeatText.text = BuildHeroActionBeatHudText(frameRange, declutterHud);
            heroActionBeatText.color = new Color(heroActionBeatColor.r, heroActionBeatColor.g, heroActionBeatColor.b, alpha);
            float pop = 1f + Mathf.Sin(Mathf.Clamp01(1f - heroActionBeatTimer / .52f) * Mathf.PI) * .035f;
            heroActionBeatText.rectTransform.localScale = new Vector3(pop, pop, 1f);
            if (heroActionBeatBackplate)
            {
                heroActionBeatBackplate.color = new Color(.02f, .04f, .08f, alpha * (declutterHud ? .22f : .42f));
                heroActionBeatBackplate.rectTransform.localScale = heroActionBeatText.rectTransform.localScale;
            }
        }

        private bool ShouldShowHeroActionBeatHudLabel(string label)
        {
            if (!CombatHudDeclutterActive(ActiveEnemiesInCurrentArea())) return true;
            if (string.IsNullOrEmpty(label)) return false;
            return label.Contains("三连")
                || label.Contains("破势")
                || label.Contains("术式")
                || label.Contains("技能")
                || label.Contains("释放");
        }

        private string BuildHeroActionBeatHudText(string frameRange, bool declutterHud)
        {
            if (declutterHud)
                return $"{heroActionBeatLabel} · {frameRange}";
            return $"{heroActionBeatLabel}  {frameRange}  {Mathf.RoundToInt(heroActionBeatFps)}FPS  当前F{lastVisibleHeroFrame}  {heroActionBeatTiming}";
        }

        private void HideHeroActionBeatHud()
        {
            heroActionBeatTimer = 0f;
            heroActionBeatLabel = "";
            if (heroActionBeatText)
            {
                heroActionBeatText.text = "";
                heroActionBeatText.color = Color.clear;
                heroActionBeatText.gameObject.SetActive(false);
            }
            if (heroActionBeatBackplate)
            {
                heroActionBeatBackplate.color = Color.clear;
                heroActionBeatBackplate.gameObject.SetActive(false);
            }
        }

        private void UpdateTargetCompass(int currentAreaEnemies)
        {
            if (!targetCompassText || !targetCompassBackplate) return;
            bool modalOpen = titleActive || rollingRune || (shopPanel && shopPanel.gameObject.activeSelf);
            if (modalOpen || !player)
            {
                SetTargetCompass(false, "", Color.clear);
                return;
            }

            Vector3 targetPos;
            Color color;
            string label;
            bool highPriority;
            if (TryFindCombatCompassTarget(currentAreaEnemies, out targetPos, out label, out color, out highPriority))
            {
                float dx = targetPos.x - player.transform.position.x;
                float dy = targetPos.y - player.transform.position.y;
                float distance = Mathf.Sqrt(dx * dx + dy * dy);
                bool offscreen = IsWorldXOutsideCamera(targetPos.x);
                if (!highPriority)
                {
                    SetTargetCompass(false, "", Color.clear);
                    return;
                }
                string arrow = dx < -0.45f ? "←" : dx > 0.45f ? "→" : dy > 0.45f ? "↑" : "↓";
                string location = offscreen ? "屏外" : dx < -0.45f ? "左侧" : dx > 0.45f ? "右侧" : dy > 0.45f ? "上方" : "附近";
                SetTargetCompass(true, $"{arrow} {label} {location} {distance:0.0}m", color);
                return;
            }

            if (TryFindObjectiveCompassTarget(out targetPos, out label, out color, out highPriority))
            {
                float dx = targetPos.x - player.transform.position.x;
                float dy = targetPos.y - player.transform.position.y;
                float distance = Mathf.Sqrt(dx * dx + dy * dy);
                bool offscreen = IsWorldXOutsideCamera(targetPos.x);
                bool objectiveCloseAndVisible = !highPriority && !offscreen && distance < 3.2f;
                if (objectiveCloseAndVisible)
                {
                    SetTargetCompass(false, "", Color.clear);
                    return;
                }
                string arrow = dx < -0.45f ? "←" : dx > 0.45f ? "→" : dy > 0.45f ? "↑" : "↓";
                string location = offscreen ? "屏外" : dx < -0.45f ? "左侧" : dx > 0.45f ? "右侧" : dy > 0.45f ? "上方" : "附近";
                SetTargetCompass(true, $"{arrow} {label} {location} {distance:0.0}m", color);
                return;
            }

            SetTargetCompass(false, "", Color.clear);
        }

        private bool TryFindCombatCompassTarget(int currentAreaEnemies, out Vector3 targetPos, out string label, out Color color, out bool highPriority)
        {
            targetPos = Vector3.zero;
            label = "";
            color = Color.white;
            highPriority = false;
            if (currentAreaEnemies <= 0 || enemies.Count == 0 || !player) return false;
            var target = enemies
                .Where(e => e != null && !e.Dead && e.Root && IsXInSegment(e.Root.transform.position.x, currentSegment))
                .OrderByDescending(EnemyCompassPriority)
                .ThenBy(e => Mathf.Abs(e.Root.transform.position.x - player.transform.position.x))
                .FirstOrDefault();
            if (target == null) return false;
            targetPos = target.Root.transform.position;
            bool offscreen = IsWorldXOutsideCamera(targetPos.x);
            label = target.Boss ? "BOSS" : target.Elite ? "精英威胁" : target.Kind == EnemyKind.Archer ? "弓手" : "敌人";
            color = target.Boss ? C("#FF7568") : target.Elite ? C("#A8FF7A") : target.Kind == EnemyKind.Archer ? C("#FFB29E") : C("#CFE8FF");
            highPriority = CombatCompassHighPriority(target, targetPos, offscreen) && (!target.Boss || offscreen);
            return true;
        }

        private bool CombatCompassHighPriority(Fighter target, Vector3 targetPos, bool offscreen)
        {
            if (target == null) return false;
            if (target.Boss || target.Elite || offscreen) return true;
            if (!player) return false;
            float distance = Vector2.Distance(targetPos, player.transform.position);
            return target.Kind == EnemyKind.Archer && distance > 6.5f;
        }

        private bool TryFindObjectiveCompassTarget(out Vector3 targetPos, out string label, out Color color, out bool highPriority)
        {
            targetPos = Vector3.zero;
            label = "";
            color = Color.white;
            highPriority = false;
            if (shrineAvailable && slotShrine)
            {
                targetPos = slotShrine.transform.position;
                label = "SLOT 宝箱";
                color = C("#8FFFF6");
                highPriority = true;
                return true;
            }
            var vessel = NearestPlatformRuneVesselInSegment(currentSegment);
            if (vessel == null || !vessel.Root) return false;
            targetPos = vessel.Root.transform.position;
            label = "平台小宝箱";
            color = C("#8FFFF6");
            highPriority = IsWorldXOutsideCamera(targetPos.x);
            return true;
        }

        private static int EnemyCompassPriority(Fighter enemy)
        {
            if (enemy.Boss) return 5;
            if (enemy.Elite) return 4;
            if (enemy.Kind == EnemyKind.Archer) return 3;
            if (enemy.Kind == EnemyKind.Slime) return 2;
            return 1;
        }

        private bool IsWorldXOutsideCamera(float x)
        {
            if (!cam) return false;
            float halfWidth = cam.orthographicSize * cam.aspect;
            float left = cam.transform.position.x - halfWidth + 1.15f;
            float right = cam.transform.position.x + halfWidth - 1.15f;
            return x < left || x > right;
        }

        private void SetTargetCompass(bool show, string value, Color color)
        {
            if (!targetCompassText || !targetCompassBackplate) return;
            bool bossFocus = BossFocusHudActive();
            targetCompassText.gameObject.SetActive(show);
            targetCompassBackplate.gameObject.SetActive(show);
            if (!show)
            {
                targetCompassText.color = Color.clear;
                targetCompassBackplate.color = new Color(.02f, .04f, .08f, 0f);
                return;
            }
            float alphaScale = effectsIntensity > .75f ? 1f : .74f;
            if (bossFocus) alphaScale *= .48f;
            float pulse = (bossFocus ? .48f : .72f) + Mathf.Sin(Time.unscaledTime * 4.8f) * (bossFocus ? .045f : .12f);
            targetCompassText.text = value;
            targetCompassText.fontSize = bossFocus ? 27 : 30;
            targetCompassText.rectTransform.sizeDelta = bossFocus ? new Vector2(600, 42) : new Vector2(700, 48);
            targetCompassText.rectTransform.anchoredPosition = bossFocus ? new Vector2(0, 392) : new Vector2(0, 430);
            targetCompassText.color = new Color(color.r, color.g, color.b, Mathf.Clamp01(pulse * alphaScale));
            targetCompassBackplate.rectTransform.sizeDelta = bossFocus ? new Vector2(610, 40) : new Vector2(720, 46);
            targetCompassBackplate.rectTransform.anchoredPosition = bossFocus ? new Vector2(0, 392) : new Vector2(0, 430);
            targetCompassBackplate.color = new Color(.02f, .04f, .08f, (bossFocus ? .10f : .20f) * alphaScale);
        }

        private string CompactObjectiveTextForHud(int currentAreaEnemies)
        {
            if (choosingRoomReward) return "选择奖励";
            if (shrineAvailable) return "开启 SLOT";
            if (currentSegment == ShopRoomIndex && currentAreaEnemies <= 0) return "补给 / 买 SLOT";
            if (currentSegment == EliteRoomIndex && currentAreaEnemies > 0) return $"精英 · 清敌 {currentAreaEnemies}";
            if (currentSegment == BossRoomIndex && currentAreaEnemies > 0) return stageIndex == 3 ? "Boss · 躲红区" : $"终段 · 清敌 {currentAreaEnemies}";
            if (currentAreaEnemies > 0) return $"清敌 {currentAreaEnemies}";
            if (proceedHintTimer > 0f) return "通路已开 · 向右";
            if (ActivePlatformRuneVesselInSegment(currentSegment)) return "宝箱可选 · 向右";
            return "向右推进";
        }

        private void ShowObjectiveHudTransitionCue(string previous, string next, int currentAreaEnemies)
        {
            if (titleActive || paused || inputLocked || !fxRoot || string.IsNullOrEmpty(previous) || string.IsNullOrEmpty(next)) return;
            bool wasClearing = previous.Contains("清敌");
            bool nowOpen = next.Contains("通路已开") || next.Contains("宝箱可选") || next.Contains("向右推进");
            if (!wasClearing || !nowOpen || currentAreaEnemies > 0) return;
            Vector3 pos = player ? player.transform.position + Vector3.up * 1.72f : new Vector3(SegmentCenters[Mathf.Clamp(currentSegment, 0, SegmentCenters.Length - 1)], GroundY + 2.0f, 0f);
            SpawnTimedSprite("RoomObjectiveClearPulse", CombatVfxSprite(0), pos + Vector3.down * .42f, new Vector2(.82f, .038f), new Color(.64f, .96f, 1f, .20f), 9, .16f);
            SpawnTimedSprite("RoomObjectiveOpenLine", CombatVfxSprite(0), pos + Vector3.right * .32f + Vector3.down * .58f, new Vector2(.72f, .030f), new Color(.86f, 1f, 1f, .24f), 10, .13f);
            SpawnRoomObjectiveProceedRouteCue(pos, next.Contains("宝箱可选"));
            SpawnTimedSprite("RoomObjectiveHudOnlyOpenTick", CombatVfxSprite(0), pos + new Vector3(.18f, .30f, 0), new Vector2(.32f, .026f), new Color(.78f, .96f, 1f, .18f), 10, .14f);
        }

        private void SpawnRoomObjectiveProceedRouteCue(Vector3 anchor, bool optionalChest)
        {
            if (!fxRoot) return;
            proceedHintTimer = Mathf.Max(proceedHintTimer, 2.15f);
            Vector3 foot = anchor + Vector3.down * 2.08f;
            SpawnTimedSprite("RoomObjectiveProceedGuideLine_NoYellowPlate", CombatVfxSprite(0), foot + Vector3.right * .88f, new Vector2(.42f, .006f), new Color(.52f, .94f, 1f, .024f), 7, .18f);
            for (int i = 0; i < 2; i++)
            {
                var arrow = SpawnTimedSprite("RoomObjectiveProceedArrow_NoYellowPlate", CombatVfxSprite(0), foot + new Vector3(.50f + i * .42f, .07f + i * .010f, 0f), new Vector2(.078f, .008f), new Color(.70f, .98f, 1f, .040f), 8, .13f + i * .035f);
                if (arrow) arrow.transform.localScale = new Vector3(Mathf.Abs(arrow.transform.localScale.x), arrow.transform.localScale.y, 1f);
                SpawnTimedSprite("RoomObjectiveProceedFootTick_NoYellowPlate", CombatVfxSprite(0), foot + new Vector3(.42f + i * .44f, -.06f, 0f), new Vector2(.040f, .006f), new Color(.94f, 1f, 1f, .042f), 8, .13f + i * .035f);
            }
            SpawnTimedSprite("RoomObjectiveProceedDestinationPin_NoYellowPlate", CombatVfxSprite(0), foot + new Vector3(1.28f, .09f, 0f), new Vector2(.048f, .090f), new Color(.86f, 1f, 1f, .10f), 9, .20f);
            SpawnTimedSprite("RoomObjectiveHudOnlyHintTick_NoYellowPlate", CombatVfxSprite(0), foot + new Vector3(.88f, .38f, 0), new Vector2(optionalChest ? .15f : .13f, .010f), new Color(.74f, .96f, 1f, .074f), 8, .12f);
        }

        private string ObjectiveTextForCurrentRoom(int currentAreaEnemies)
        {
            string title = CurrentRoomTitle();
            if (choosingRoomReward) return $"目标：{title}  选择一项房间奖励继续推进";
            if (shrineAvailable) return $"目标：{title}  靠近 SLOT 宝箱，点启封";
            if (currentSegment == ShopRoomIndex && currentAreaEnemies <= 0) return $"目标：{title}  靠近符文商人，点补给或召出 SLOT";
            if (currentSegment == EliteRoomIndex && currentAreaEnemies > 0) return $"目标：{title}  躲开绿色毒圈，击败精英";
            if (currentSegment == BossRoomIndex && currentAreaEnemies > 0) return stageIndex == 3
                ? $"目标：{title}  锁场中，躲红区并击破守护者"
                : $"目标：{title}  清空终段敌人";
            string roomGoal = RoomObjectiveText(currentSegment, currentAreaEnemies);
            if (!string.IsNullOrEmpty(roomGoal)) return $"目标：{title}  {roomGoal}";
            if (currentAreaEnemies > 0) return $"目标：{title}  击败敌人 {currentAreaEnemies} 剩余";
            return $"目标：{title} 已清空，{MapLayoutGoalLine()}";
        }

        private string RoomObjectiveText(int segment, int currentAreaEnemies)
        {
            if (segment < 0 || segment >= roomObjectives.Length) return "";
            var objective = roomObjectives[segment];
            if (objective == RoomObjective.BreakRuneCache)
            {
                bool cacheAlive = runeVessels.Any(v => !v.Broken && v.Root && v.ObjectiveSegment == segment);
                if (currentAreaEnemies > 0) return cacheAlive ? $"击败敌人 {currentAreaEnemies}，小宝箱可选" : $"击败敌人 {currentAreaEnemies} 剩余";
                return cacheAlive ? "可跳上平台开箱拿 SLOT 能量，也可继续推进" : "";
            }
            if (currentAreaEnemies <= 0 && ActivePlatformRuneVesselInSegment(segment))
                return activeMapLayoutIndex == 1 || activeMapLayoutIndex == 3
                    ? "可上高台开箱，技能弹也能触发 SLOT"
                    : "可跳上平台打开小宝箱，或向右推进";
            if (objective == RoomObjective.PrecisionDodge && currentAreaEnemies > 0)
                return PrecisionObjectiveSucceeded(segment)
                    ? $"极限闪避挑战完成，击败敌人 {currentAreaEnemies} 剩余"
                    : $"极限闪避可提高奖励，击败敌人 {currentAreaEnemies} 剩余";
            if (objective == RoomObjective.TimedClear && currentAreaEnemies > 0)
                return TimedClearRemaining(segment) > 0f
                    ? $"疾行挑战 {TimedClearRemaining(segment):0}s 内清房，疾跑推进，敌人 {currentAreaEnemies} 剩余"
                    : $"疾行挑战超时，击败敌人 {currentAreaEnemies} 剩余";
            return "";
        }

        private bool PrecisionObjectiveSucceeded(int segment)
        {
            if (segment < 0 || segment >= roomPerfectDodgeStart.Length) return false;
            return perfectDodgesThisRun > roomPerfectDodgeStart[segment];
        }

        private bool SwiftObjectiveSucceeded(int segment)
        {
            if (segment < 0 || segment >= roomEnterRunTime.Length || segment >= roomQuickRunStart.Length) return false;
            return TimedClearSucceeded(segment) && QuickRunSecondsInRoom(segment) >= QuickRunRoomRatingMinSeconds;
        }

        private float QuickRunSecondsInRoom(int segment)
        {
            if (segment < 0 || segment >= roomQuickRunStart.Length) return 0f;
            return Mathf.Max(0f, quickRunTimeThisRun - roomQuickRunStart[segment]);
        }

        private static string SwiftChallengeRewardSuffix(RoomModifier modifier, bool swiftSuccess)
        {
            if (modifier != RoomModifier.Swift) return "";
            return swiftSuccess ? "，疾行挑战完成" : "，疾行挑战未完成";
        }

        private bool TimedClearSucceeded(int segment)
        {
            return segment >= 0 && segment < roomEnterRunTime.Length && runTime - roomEnterRunTime[segment] <= TimedClearLimit(segment);
        }

        private float TimedClearRemaining(int segment)
        {
            if (segment < 0 || segment >= roomEnterRunTime.Length) return 0f;
            return Mathf.Max(0f, TimedClearLimit(segment) - (runTime - roomEnterRunTime[segment]));
        }

        private static float TimedClearLimit(int segment)
        {
            return Mathf.Clamp(24f + segment * 1.5f, 24f, 32f);
        }

        private string BuildRunProgressText()
        {
            int room = Mathf.Clamp(currentSegment + 1, 1, SegmentRights.Length);
            string pace = bestClearTime > 0
                ? runTime <= bestClearTime ? $"快{FormatTime(bestClearTime - runTime)}" : $"慢{FormatTime(runTime - bestClearTime)}"
                : FormatTime(runTime);
            string killDelta = bestRunKills > 0
                ? killsThisRun >= bestRunKills ? $"K+{killsThisRun - bestRunKills}" : $"K-{bestRunKills - killsThisRun}"
                : $"K{killsThisRun}";
            return $"{room}/{SegmentRights.Length} · Lv{trialLevel} {TrialExpPercent()}% · {pace} · {killDelta}";
        }

        private void UpdateNextSlotHintText()
        {
            if (!nextSlotHintText) return;
            int enemiesHere = ActiveEnemiesInCurrentArea();
            if (BossFocusHudActive())
            {
                nextSlotHintText.text = "";
                nextSlotHintText.color = Color.clear;
                return;
            }
            bool declutterHud = CombatHudDeclutterActive(enemiesHere);
            bool nearAnticipation = fateEnergy >= (declutterHud ? SlotHintCombatThreshold : RuneAnticipationThreshold);
            bool earlyAnticipation = !declutterHud && fateEnergy >= SlotHintEarlyThreshold;
            bool ready = rollingRune || shrineAvailable || CanUseShopInteraction() || nearAnticipation || earlyAnticipation;
            nextSlotHintText.text = ready ? BuildNextSlotHintText() : "";
            float alpha = ready ? (declutterHud ? .26f : .50f) + Mathf.Sin(Time.unscaledTime * 5.8f) * (declutterHud ? .03f : .10f) : 0f;
            Color color = shrineAvailable ? C("#8FFFF6") : CanUseShopInteraction() ? C("#9FF8FF") : fateEnergy >= RuneAnticipationThreshold ? C("#9FF8FF") : fateEnergy >= 80f ? C("#B6F7FF") : C("#BFEFFF");
            nextSlotHintText.color = new Color(color.r, color.g, color.b, Mathf.Clamp01(alpha));
        }

        private void UpdateRuneHudText(int currentAreaEnemies, bool bossFocus, bool previewHudReadable, bool explorationQuietHud)
        {
            if (!runeText) return;
            bool modalVisible = rollingRune || shrineAvailable || (runePanel && runePanel.gameObject.activeSelf) || CanUseShopInteraction();
            bool nearReady = fateEnergy >= (CombatHudDeclutterActive(currentAreaEnemies) ? SlotHintCombatThreshold : RuneAnticipationThreshold);
            bool show = !bossFocus && !titleActive && !paused && (modalVisible || nearReady || currentAreaEnemies <= 0);
            runeText.text = show ? $"SLOT {runeCount}  {Mathf.FloorToInt(fateEnergy)}%" : "";
            float alpha = modalVisible ? .72f : nearReady ? .50f : previewHudReadable ? .18f : explorationQuietHud ? .14f : .24f;
            runeText.color = show ? new Color(.82f, .96f, 1f, alpha) : Color.clear;
        }

        private void UpdateRuneOddsText()
        {
            if (!runeOddsText) return;
            bool panelVisible = runePanel && runePanel.gameObject.activeSelf;
            bool safeOpenPrompt = (rollingRune || shrineAvailable) && ActiveEnemiesInCurrentArea() <= 0 && !BossFocusHudActive();
            bool show = panelVisible || safeOpenPrompt;
            if (!show)
            {
                runeOddsText.text = "";
                runeOddsText.color = Color.clear;
                return;
            }
            runeOddsText.text = RuneOddsHudLine();
            float alpha = panelVisible ? .54f : .38f;
            if (effectsIntensity <= .75f) alpha *= .78f;
            runeOddsText.color = new Color(.80f, .92f, 1f, alpha);
        }

        private string BuildNextSlotHintText()
        {
            if (rollingRune) return "启封中";
            if (shrineAvailable) return "启封";
            if (CanUseShopInteraction())
            {
                if (coins >= 100 && !shopRuneSoldThisStage) return "商店100";
                if (!shopRuneSoldThisStage) return $"差{Mathf.Max(0, 100 - coins)}金";
                return "售罄";
            }
            if (fateEnergy >= RuneAnticipationThreshold) return $"临界{Mathf.FloorToInt(fateEnergy)}%";
            if (fateEnergy >= SlotHintEarlyThreshold) return $"差{Mathf.Max(0, Mathf.CeilToInt(RuneAnticipationThreshold - fateEnergy))}%";
            return "";
        }

        private void UpdateRuneBadges()
        {
            int[] levels = { swordRuneLevel, dashRuneLevel, frostRuneLevel, thunderRuneLevel, shieldRuneLevel };
            string[] labels = { "剑", "闪", "冰", "雷", "盾" };
            Color[] colors = { C("#66D9FF"), C("#67F5D4"), C("#86CFFF"), C("#8FFFF6"), C("#D0D7E2") };
            bool bossFocus = BossFocusHudActive();
            for (int i = 0; i < runeBadgeImages.Count && i < levels.Length; i++)
            {
                bool active = false && levels[i] > 0 && !bossFocus;
                runeBadgeImages[i].gameObject.SetActive(active);
                if (!active) continue;
                runeBadgeImages[i].color = active
                    ? new Color(colors[i].r, colors[i].g, colors[i].b, .88f)
                    : new Color(colors[i].r, colors[i].g, colors[i].b, .25f);
                if (i < runeBadgeTexts.Count && runeBadgeTexts[i])
                {
                    runeBadgeTexts[i].text = active ? labels[i] + levels[i] : labels[i];
                    runeBadgeTexts[i].color = active ? Color.white : new Color(1, 1, 1, .42f);
                }
            }
        }

        private void UpdateBuildStyleHud()
        {
            if (!buildStyleText) return;
            string style = CurrentBuildStyle();
            int total = swordRuneLevel + dashRuneLevel + frostRuneLevel + thunderRuneLevel + shieldRuneLevel;
            bool bossFocus = BossFocusHudActive();
            bool formed = total > 0 && !bossFocus;
            bool declutterHud = CombatHudDeclutterActive(ActiveEnemiesInCurrentArea());
            float alpha = formed ? declutterHud ? .14f : .50f : 0f;
            buildStyleText.text = formed
                ? $"{style} Lv{total}"
                : "";
            if (buildStyleBackplate)
                buildStyleBackplate.color = formed ? new Color(.02f, .07f, .10f, declutterHud ? .025f : .14f) : new Color(.02f, .04f, .08f, 0f);
            buildStyleText.color = formed ? new Color(.86f, .97f, 1f, alpha) : Color.clear;
        }

        private bool CombatHudDeclutterActive(int currentAreaEnemies)
        {
            if (titleActive || paused || inputLocked || rollingRune) return false;
            if (shrineAvailable || CanUseShopInteraction()) return false;
            return currentAreaEnemies > 0 || threatAlertTimer > 0f || enemies.Any(e => e.Boss && !e.Dead && e.Root);
        }

        private bool ExplorationQuietHudActive(int currentAreaEnemies)
        {
            if (mapPreviewHudMode) return false;
            if (titleActive || paused || inputLocked || rollingRune || choosingRoomReward) return false;
            if (shrineAvailable || CanUseShopInteraction()) return false;
            if (threatAlertTimer > 0f) return false;
            return currentAreaEnemies <= 0 && !enemies.Any(e => e.Boss && !e.Dead && e.Root);
        }

        private void UpdateForegroundReadabilityBand(int currentAreaEnemies, bool bossFocus, bool declutterHud)
        {
            if (!foregroundReadabilityBand) return;
            var sr = foregroundReadabilityBand.GetComponent<SpriteRenderer>();
            if (!sr) return;
            float targetAlpha = 0f;
            if (declutterHud)
            {
                float density = Mathf.Clamp01(currentAreaEnemies / 4f);
                targetAlpha = Mathf.Lerp(.008f, CombatReadabilityBandMaxAlpha, density);
                if (bossFocus) targetAlpha = BossReadabilityBandMaxAlpha;
                if (threatAlertTimer > 0f) targetAlpha = Mathf.Max(targetAlpha, ThreatReadabilityBandMaxAlpha);
            }
            if (effectsIntensity <= .75f && targetAlpha > 0f)
                targetAlpha += LowFlashReadabilityBandBonus;
            if (titleActive || paused || rollingRune || choosingRoomReward || shrineAvailable || CanUseShopInteraction())
                targetAlpha = 0f;
            Vector3 anchor = player ? player.transform.position : cam ? cam.transform.position : foregroundReadabilityBand.transform.position;
            float width = bossFocus ? 5.0f : Mathf.Lerp(2.9f, 4.2f, Mathf.Clamp01(currentAreaEnemies / 4f));
            float height = bossFocus ? .44f : .34f;
            foregroundReadabilityBand.transform.position = Vector3.Lerp(
                foregroundReadabilityBand.transform.position,
                new Vector3(anchor.x + (bossFocus ? .48f : .12f) * facing, GroundY + .48f, 0f),
                Time.deltaTime * 4.2f);
            foregroundReadabilityBand.transform.localScale = Vector3.Lerp(
                foregroundReadabilityBand.transform.localScale,
                new Vector3(width, height, 1f),
                Time.deltaTime * 5.4f);
            Color target = new Color(.012f, .028f, .038f, Mathf.Clamp01(targetAlpha));
            sr.color = Color.Lerp(sr.color, target, Time.deltaTime * (targetAlpha > sr.color.a ? 4.8f : 3.2f));
        }

        private bool BossFocusHudActive()
        {
            return !titleActive && !paused && !rollingRune && !choosingRoomReward && enemies.Any(e => e.Boss && !e.Dead && e.Root);
        }

        private void UpdateBossHud()
        {
            if (!bossHudRoot) return;
            var boss = enemies.FirstOrDefault(e => e.Boss && !e.Dead && e.Root);
            bool show = boss != null;
            bossHudRoot.gameObject.SetActive(show);
            if (!show) return;
            float ratio = Mathf.Clamp01(boss.Hp / Mathf.Max(1f, boss.MaxHp));
            if (bossHudFill)
            {
                bossHudFill.rectTransform.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, BossHudHpWidth * ratio);
                bossHudFill.color = boss.PhaseTwo ? C("#FF6B6B") : C("#D83A3A");
            }
            if (bossHudText)
                bossHudText.text = boss.PhaseTwo
                    ? $"守护者巨像 · 狂暴 {Mathf.CeilToInt(boss.Hp)}/{Mathf.CeilToInt(boss.MaxHp)}"
                    : $"守护者巨像 {Mathf.CeilToInt(boss.Hp)}/{Mathf.CeilToInt(boss.MaxHp)}";
            if (bossHudPhaseText)
            {
                bossHudPhaseText.text = boss.PhaseTwo ? "P2 · 雷阵" : "P1 · 50%碎甲";
                bossHudPhaseText.color = boss.PhaseTwo ? C("#B8F7FF") : new Color(.86f, .95f, 1f, .62f);
            }
            UpdateBossPressureHud(boss, ratio);
            if (bossHudAttackText)
            {
                bossAttackCueTimer = Mathf.Max(0f, bossAttackCueTimer - Time.deltaTime);
                bool activeCue = bossAttackCueTimer > 0f;
                bossHudAttackText.text = activeCue ? bossAttackCue : "";
                bossHudAttackText.color = activeCue ? C("#FFB6A8") : Color.clear;
            }
            if (bossResponseHintText)
            {
                bool activeCounterCue = bossAttackCueTimer > 0f && bossAttackCue.Contains("反击窗口");
                bossResponseHintText.text = activeCounterCue ? "现在贴身输出" : "";
                bossResponseHintText.color = activeCounterCue
                    ? C("#9FF8FF")
                    : Color.clear;
            }
        }

        private void UpdateBossArenaLockdown()
        {
            if (!bossArenaLockdownRoot) return;
            var boss = enemies.FirstOrDefault(e => e.Boss && !e.Dead && e.Root);
            bool active = stageIndex == 3 && currentSegment == BossRoomIndex && boss != null;
            if (bossArenaLockdownRoot.activeSelf != active) bossArenaLockdownRoot.SetActive(active);
            if (!active) return;
            float alphaScale = effectsIntensity > .75f ? 1f : .70f;
            float pulse = .55f + Mathf.Sin(Time.time * 5.2f) * .18f;
            Color wall = new Color(1f, .18f, .18f, Mathf.Clamp01((.018f + pulse * .018f) * alphaScale));
            if (bossArenaLeftLockWall) bossArenaLeftLockWall.color = wall;
            if (bossArenaRightLockWall) bossArenaRightLockWall.color = wall;
            if (bossArenaGroundSeal)
            {
                bossArenaGroundSeal.color = new Color(1f, .22f, .20f, Mathf.Clamp01((.010f + pulse * .010f) * alphaScale));
                bossArenaGroundSeal.transform.localScale = new Vector3(1f, 1f + Mathf.Sin(Time.time * 7.2f) * .025f, 1f);
            }
        }

        private string BuildBossResponseHint(Fighter boss, float hpRatio)
        {
            if (boss == null) return "";
            if (bossAttackCueTimer > 0f)
            {
                if (bossAttackCue.Contains("反击窗口")) return "应对建议：现在可以贴身输出，打第三段或交技能";
                if (bossAttackCue.Contains("巨拳")) return "应对建议：离开斜纹红框，砸地收招后贴身打第三段";
                if (bossAttackCue.Contains("激光")) return "应对建议：先跳跃或贴近缝隙，激光收束后用技能反击";
                if (bossAttackCue.Contains("雷阵")) return "应对建议：连续看十字落点，雷阵结束后再输出";
            }
            if (hpRatio < .28f) return "应对建议：终段少贪刀，等砸地/激光收招后打爆发";
            if (boss.PhaseTwo)
            {
                if (dashRuneLevel > 0) return "应对建议：闪避留痕绕场清弹，雷阵前不要提前交闪";
                if (frostRuneLevel > 0) return "应对建议：冰环留给 Boss 收招窗口，冻结后接第三段";
                return "应对建议：二阶段先躲十字落点和激光，安全后再贴身输出";
            }
            if (hpRatio < .55f) return "应对建议：接近半血先留闪避，保留闪避处理第二段";
            if (shieldRuneLevel > 0) return "应对建议：有盾可抢一轮第三段，但红框内仍要撤";
            if (swordRuneLevel > 0 || thunderRuneLevel > 0) return "应对建议：用剑气/雷击消耗，等砸地落空再近身";
            return "应对建议：贴近诱导砸地，横移出框，第三段后立刻后撤";
        }

        private void UpdateBossPressureHud(Fighter boss, float hpRatio)
        {
            if (boss == null) return;
            float pressure = boss.PhaseTwo ? Mathf.Lerp(.62f, 1f, 1f - hpRatio) : Mathf.Clamp01((1f - hpRatio) / .5f);
            Color color = boss.PhaseTwo ? C("#FF8A6A") : C("#8FFFF6");
            if (bossPressureFill)
            {
                bossPressureFill.rectTransform.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, Mathf.Lerp(14f, BossHudPressureWidth, pressure));
                bossPressureFill.color = Color.Lerp(bossPressureFill.color, color, Time.deltaTime * 10f);
            }
            if (!bossPressureText) return;
            bossPressureText.text = "";
            bossPressureText.color = Color.clear;
        }

        private int ActiveEnemiesInCurrentArea()
        {
            return ActiveEnemiesInSegment(currentSegment);
        }

