        {
            if (!runeCodexPanel) return;
            bool opening = !runeCodexPanel.gameObject.activeSelf;
            runeCodexPanel.gameObject.SetActive(opening);
            if (opening)
            {
                if (runeCodexSummaryText) runeCodexSummaryText.text = RuneCodexSummaryText();
                if (runeCodexBodyText) runeCodexBodyText.text = RuneCodexText();
                touchAttackHeld = false;
                touchMoveActive = false;
                ResetJoystickIntentLock();
                inputLocked = true;
                Time.timeScale = 0f;
            }
            else
            {
                bool modalOpen = titleActive || paused || controlEditMode || (achievementPanel && achievementPanel.gameObject.activeSelf) || (aboutPanel && aboutPanel.gameObject.activeSelf) || (settingsPanel && settingsPanel.gameObject.activeSelf) || (shopPanel && shopPanel.gameObject.activeSelf);
                inputLocked = modalOpen;
                Time.timeScale = ModalWantsTimeFreeze() ? 0f : 1f;
            }
            PlaySfx(sfxShop, .65f);
        }

