        private string BuildAchievementListText()
        {
            var lines = new List<string>();
            foreach (var id in AchievementIds)
            {
                bool unlocked = unlockedAchievements.Contains(id);
                lines.Add($"{AchievementStatusLabel(unlocked)} {AchievementName(id)} · {AchievementShortDescription(id)} · {CompactAchievementProgressText(id, unlocked)}");
            }
            return string.Join("\n", lines.ToArray());
        }

        private string BuildAchievementSummaryText()
        {
            return $"已解锁 {unlockedAchievements.Count}/{AchievementIds.Length} · {BuildTrackedAchievementHint()}\n{BuildRouteArchiveSummary()}";
        }

        private string BuildRouteArchiveSummary()
        {
            return $"路线档案：树冠 {AchievementStatusLabel(unlockedAchievements.Contains("CanopyMaster"))}  断桥 {AchievementStatusLabel(unlockedAchievements.Contains("BrokenBridgeMaster"))}  高脊 {AchievementStatusLabel(unlockedAchievements.Contains("RuneRidgeMaster"))}  汇总 {RouteMasteryUnlockedCount()}/3";
        }

        private static string AchievementStatusLabel(bool unlocked)
        {
            return unlocked ? "[完成]" : "[追踪]";
        }

        private string BuildTrackedAchievementHint()
        {
            if (!unlockedAchievements.Contains("ClearTrial")) return "推荐追踪：试炼完成 - 先击败守护者巨像";
            if (!unlockedAchievements.Contains("RuneRegular")) return "推荐追踪：命运常客 - 单局关键启封 3 次";
            if (!unlockedAchievements.Contains("PerfectRanger")) return "推荐追踪：精准游侠 - 单局极限闪避 3 次";
            if (!unlockedAchievements.Contains("FastClear15")) return "推荐追踪：疾速通关 - 15 分钟内通关";
            if (!unlockedAchievements.Contains("ComboPress")) return "推荐追踪：连击压制 - 最高连击达到 20";
            if (!unlockedAchievements.Contains("CanopyMaster")) return "推荐追踪：树冠熟手 - 遇到树冠阶梯路线时通关";
            if (!unlockedAchievements.Contains("BrokenBridgeMaster")) return "推荐追踪：断桥熟手 - 遇到断桥跳点路线时通关";
            if (!unlockedAchievements.Contains("RuneRidgeMaster")) return "推荐追踪：高脊熟手 - 遇到符文高脊路线时通关";
            if (!unlockedAchievements.Contains("RouteArchivist")) return "推荐追踪：路线档案 - 完成三种特殊路线通关";
            if (!unlockedAchievements.Contains("HeatClear")) return "推荐追踪：高热通关 - 热度 H2 或以上通关";
            if (!unlockedAchievements.Contains("NoDamageClear")) return "推荐追踪：无伤通关 - 优先拿盾/冰降低失误";
            return "推荐追踪：全部本地成就已完成，下一局挑战刷新最佳时间";
        }

        private string CompactAchievementProgressText(string id, bool unlocked)
        {
            string progress = AchievementProgressText(id, unlocked);
            if (string.IsNullOrEmpty(progress)) return "";
            return progress.Length <= 18 ? progress : progress.Substring(0, 17) + "...";
        }

        private string AchievementDescription(string id)
        {
            switch (id)
            {
                case "ClearTrial": return "击败守护者巨像";
                case "NoDamageClear": return "通关时不受伤";
                case "FastClear15": return "15 分钟内通关";
                case "RuneRegular": return "单局关键启封 3 次";
                case "PerfectRanger": return "单局极限闪避 3 次";
                case "ComboPress": return "最高连击达到 20";
                case "RoomPlanner": return "获得 2 次关键房奖励";
                case "AdaptiveTrial": return "清掉 4 个变体房间";
                case "ShieldSustain": return "坚盾流派低伤完成试炼";
                case "HeatClear": return "热度 H2 或以上通关";
                case "CanopyMaster": return "树冠阶梯路线出现在本局时通关";
                case "BrokenBridgeMaster": return "断桥跳点路线出现在本局时通关";
                case "RuneRidgeMaster": return "符文高脊路线出现在本局时通关";
                case "RouteArchivist": return "完成树冠、断桥和高脊三种路线通关";
                default: return "完成对应挑战";
            }
        }

        private string AchievementShortDescription(string id)
        {
            switch (id)
            {
                case "ClearTrial": return "击败 Boss";
                case "NoDamageClear": return "0 受伤通关";
                case "FastClear15": return "15:00 内通关";
                case "RuneRegular": return "启封 3 次";
                case "PerfectRanger": return "极限闪避 3 次";
                case "ComboPress": return "最高连击 20";
                case "RoomPlanner": return "奖励 2 次";
                case "AdaptiveTrial": return "变体房 4 间";
                case "ShieldSustain": return "盾 Lv2 且低伤";
                case "HeatClear": return "H2+ 通关";
                case "CanopyMaster": return "树冠路线通关";
                case "BrokenBridgeMaster": return "断桥路线通关";
                case "RuneRidgeMaster": return "高脊路线通关";
                case "RouteArchivist": return "三种路线收集";
                default: return AchievementDescription(id);
            }
        }

        private string AchievementProgressText(string id, bool unlocked)
        {
            if (unlocked) return "已完成，可挑战刷新最佳";
            switch (id)
            {
                case "ClearTrial": return bestClearTime > 0f ? "已通关记录" : $"房间 {Mathf.Clamp(currentSegment + 1, 1, SegmentRights.Length)}/{SegmentRights.Length}";
                case "NoDamageClear": return bestClearTime > 0f ? $"本局受伤 {damageTakenThisRun}，目标 0" : "需先完成一次通关";
                case "FastClear15": return bestClearTime > 0f ? $"最佳 {FormatTime(bestClearTime)} / 15:00" : "暂无通关时间";
                case "RuneRegular": return $"{Mathf.Min(runeCount, 3)}/3 本局关键启封";
                case "PerfectRanger": return $"{Mathf.Min(perfectDodgesThisRun, 3)}/3 本局极限闪避";
                case "ComboPress": return $"{Mathf.Min(highestComboThisRun, 20)}/20 本局最高连击";
                case "RoomPlanner": return $"{Mathf.Min(roomRewardsChosenThisRun, 2)}/2 本局关键奖励";
                case "AdaptiveTrial": return $"{Mathf.Min(modifiedRoomsClearedThisRun, 4)}/4 本局变体房";
                case "ShieldSustain": return $"盾Lv{shieldRuneLevel}/2，受伤 {damageTakenThisRun}/2";
                case "HeatClear": return $"{TrialHeatLabel()} / H2+，需通关";
                case "CanopyMaster": return RunSawLayout(1) ? "本局已遇到树冠阶梯，需通关" : "等待树冠阶梯路线";
                case "BrokenBridgeMaster": return RunSawLayout(2) ? "本局已遇到断桥跳点，需通关" : "等待断桥跳点路线";
                case "RuneRidgeMaster": return RunSawLayout(3) ? "本局已遇到符文高脊，需通关" : "等待符文高脊路线";
                case "RouteArchivist":
                    return $"{RouteMasteryUnlockedCount()}/3 特殊路线已完成";
                default: return "继续完成挑战";
            }
        }

        private int RouteMasteryUnlockedCount()
        {
            int count = 0;
            if (unlockedAchievements.Contains("CanopyMaster")) count++;
            if (unlockedAchievements.Contains("BrokenBridgeMaster")) count++;
            if (unlockedAchievements.Contains("RuneRidgeMaster")) count++;
            return count;
        }

        private void RequestClearLocalData()
        {
            if (localDataClearConfirmTimer <= 0f)
            {
                localDataClearConfirmTimer = 4f;
                UpdateAboutClearStateText("再点一次确认清除。本操作会重置设置、教程、本机成绩、今日最佳和本地成就。");
                PlaySfx(sfxShop, .55f);
                return;
            }

            ClearLocalData();
        }

        private void ClearLocalData()
        {
            foreach (var key in LocalPlayerPrefKeys)
                PlayerPrefs.DeleteKey(key);
            foreach (var id in CombatControlIds)
            {
                PlayerPrefs.DeleteKey(CombatButtonOffsetXKey(id));
                PlayerPrefs.DeleteKey(CombatButtonOffsetYKey(id));
            }
            foreach (var id in AchievementIds)
                PlayerPrefs.DeleteKey(AchievementKey(id));
            PlayerPrefs.Save();

            assistMode = false;
            autoAttackEnabled = false;
            autoAimEnabled = true;
            soundEnabled = true;
            hapticsEnabled = true;
            effectsIntensity = 1f;
            masterVolume = .85f;
            sfxVolume = .9f;
            musicVolume = .65f;
            compactControls = false;
            controlSizeMode = 1;
            controlReachMode = 2;
            controlOpacityMode = 1;
            trialHeatLevel = 0;
            controlEditMode = false;
            combatControlCustomOffset = Vector2.zero;
            combatButtonCustomOffsets.Clear();
            frameRateMode = 1;
            showHeroActionBeatHud = false;
            HideHeroActionBeatHud();
            onboardingSeen = false;
            tutorialCompleted = false;
            bestClearTime = 0f;
            bestRunKills = 0;
            savedDailySeed = 0;
            dailyBestTime = 0f;
            dailyBestKills = 0;
            unlockedAchievements.Clear();
            localDataClearConfirmTimer = 0f;

            ConfigureRuntimePerformance();
            ApplyAudioMix();
            ApplyControlLayout();
            UpdateSettingsText();
            UpdateTrialHeatTitleUi();
            if (achievementSummaryText) achievementSummaryText.text = BuildAchievementSummaryText();
            if (achievementBodyText) achievementBodyText.text = BuildAchievementListText();
            if (runeCodexSummaryText) runeCodexSummaryText.text = RuneCodexSummaryText();
            if (runeCodexBodyText) runeCodexBodyText.text = RuneCodexText();
            UpdateAboutClearStateText("本机数据已清除。当前只保留本次运行中的临时对局状态。");
            PlaySfx(sfxRuneReward, .75f);
            HapticPulse();
        }

        private void UpdateLocalDataClearConfirmation()
        {
            if (localDataClearConfirmTimer <= 0f) return;
            localDataClearConfirmTimer -= Time.unscaledDeltaTime;
            if (localDataClearConfirmTimer <= 0f)
                UpdateAboutClearStateText("可清除本机设置、教程状态、成绩记录和本地成就。");
        }

        private void UpdateAboutClearStateText(string value)
        {
            if (aboutClearStateText) aboutClearStateText.text = value;
        }

        private void UpdateAboutReleaseBlockerText()
        {
            if (aboutReleaseBlockerText) aboutReleaseBlockerText.text = ReleaseBlockerStatusText();
        }

        private bool ModalWantsTimeFreeze()
        {
            return titleActive || paused || controlEditMode || (shopPanel && shopPanel.gameObject.activeSelf) || (settingsPanel && settingsPanel.gameObject.activeSelf) || (achievementPanel && achievementPanel.gameObject.activeSelf) || (runeCodexPanel && runeCodexPanel.gameObject.activeSelf) || (aboutPanel && aboutPanel.gameObject.activeSelf);
        }

        private bool GameplayInputLockStillValid()
        {
            return ModalWantsTimeFreeze()
                || rollingRune
                || RoomRewardPanelBlocksGameplay()
                || finalVictorySequenceRunning
                || (runePanel && runePanel.gameObject.activeSelf)
                || (victoryPanel && victoryPanel.gameObject.activeSelf);
        }

        private bool RoomRewardPanelBlocksGameplay()
        {
            return choosingRoomReward
                && pendingRoomRewards.Count > 0
                && roomRewardPanel
                && roomRewardPanel.gameObject.activeInHierarchy;
        }

        private void TickGameplayInputWatchdogs()
        {
            float dt = Time.unscaledDeltaTime > 0f ? Time.unscaledDeltaTime : Time.deltaTime;
            rollingRuneWatchdogTimer = rollingRune ? rollingRuneWatchdogTimer + dt : 0f;
            inputLockedWatchdogTimer = inputLocked ? inputLockedWatchdogTimer + dt : 0f;
        }

        private void RecoverHungRuneRollIfPossible()
        {
            if (!rollingRune || rollingRuneWatchdogTimer < 8f) return;
            bool completesStage = currentShrineCompletesStage;
            rollingRune = false;
            rollingRuneWatchdogTimer = 0f;
            lastRuneRollFinishTime = Time.time;
            if (slotShrine) Destroy(slotShrine);
            shrineAvailable = false;
            if (completesStage) stageRuneResolved = true;
            currentShrineCompletesStage = false;
            if (runePanel) runePanel.gameObject.SetActive(false);
            inputLocked = ModalWantsTimeFreeze();
            if (hitStopTimer <= 0f) Time.timeScale = inputLocked ? 0f : 1f;
            NormalizePlayerSupport(true);
            noticeText.text = "启封异常已自动收起：继续推进";
        }

        private void RecoverMovementInputLockIfPossible()
        {
            if (!inputLocked || GameplayInputLockStillValid()) return;
            choosingRoomReward = false;
            pendingRoomRewards.Clear();
            if (roomRewardPanel) roomRewardPanel.gameObject.SetActive(false);
            inputLocked = false;
            inputLockedWatchdogTimer = 0f;
            if (hitStopTimer <= 0f) Time.timeScale = 1f;
            NormalizePlayerSupport(true);
            ClearAutoAimTargetCue();
            HideSkillAimPreview();
        }

