        private void LoadSavedSettings()
        {
            EnsureLocalSaveSchema();
            assistMode = PlayerPrefs.GetInt("DestinyRanger.AssistMode", assistMode ? 1 : 0) == 1;
            autoAttackEnabled = PlayerPrefs.GetInt("DestinyRanger.AutoAttack", autoAttackEnabled ? 1 : 0) == 1;
            autoAimEnabled = PlayerPrefs.GetInt("DestinyRanger.AutoAim", autoAimEnabled ? 1 : 0) == 1;
            soundEnabled = PlayerPrefs.GetInt("DestinyRanger.Sound", soundEnabled ? 1 : 0) == 1;
            hapticsEnabled = PlayerPrefs.GetInt("DestinyRanger.Haptics", hapticsEnabled ? 1 : 0) == 1;
            effectsIntensity = PlayerPrefs.GetFloat("DestinyRanger.EffectsIntensity", effectsIntensity);
            masterVolume = Mathf.Clamp01(PlayerPrefs.GetFloat("DestinyRanger.MasterVolume", masterVolume));
            sfxVolume = Mathf.Clamp01(PlayerPrefs.GetFloat("DestinyRanger.SfxVolume", sfxVolume));
            musicVolume = Mathf.Clamp01(PlayerPrefs.GetFloat("DestinyRanger.MusicVolume", musicVolume));
            compactControls = PlayerPrefs.GetInt("DestinyRanger.CompactControls", compactControls ? 1 : 0) == 1;
            controlSizeMode = Mathf.Clamp(PlayerPrefs.GetInt("DestinyRanger.ControlSizeMode", controlSizeMode), 0, 2);
            controlReachMode = Mathf.Clamp(PlayerPrefs.GetInt("DestinyRanger.ControlReachMode", controlReachMode), 0, 2);
            controlOpacityMode = Mathf.Clamp(PlayerPrefs.GetInt("DestinyRanger.ControlOpacityMode", controlOpacityMode), 0, 2);
            trialHeatLevel = Mathf.Clamp(PlayerPrefs.GetInt("DestinyRanger.TrialHeatLevel", trialHeatLevel), 0, 3);
            combatControlCustomOffset = new Vector2(
                Mathf.Clamp(PlayerPrefs.GetFloat("DestinyRanger.CombatControlOffsetX", combatControlCustomOffset.x), -240f, 120f),
                Mathf.Clamp(PlayerPrefs.GetFloat("DestinyRanger.CombatControlOffsetY", combatControlCustomOffset.y), -90f, 180f));
            LoadCombatButtonOffsets();
            frameRateMode = Mathf.Clamp(PlayerPrefs.GetInt("DestinyRanger.FrameRateMode", frameRateMode), 0, 1);
            showHeroActionBeatHud = false;
            onboardingSeen = PlayerPrefs.GetInt("DestinyRanger.OnboardingSeen", 0) == 1;
            tutorialCompleted = PlayerPrefs.GetInt("DestinyRanger.TutorialCompleted", 0) == 1;
            bestClearTime = PlayerPrefs.GetFloat("DestinyRanger.BestClearTime", 0f);
            bestRunKills = PlayerPrefs.GetInt("DestinyRanger.BestRunKills", 0);
            savedDailySeed = PlayerPrefs.GetInt("DestinyRanger.DailySeed", 0);
            dailyBestTime = PlayerPrefs.GetFloat("DestinyRanger.DailyBestTime", 0f);
            dailyBestKills = PlayerPrefs.GetInt("DestinyRanger.DailyBestKills", 0);
            LoadUnlockedAchievements();
        }

        private void EnsureLocalSaveSchema()
        {
            int loadedSchema = PlayerPrefs.GetInt(SaveSchemaVersionKey, 0);
            if (loadedSchema == SaveSchemaVersion || loadedSchema > SaveSchemaVersion)
                return;

            MigrateLocalSaveSchema(loadedSchema);
            PlayerPrefs.SetInt(SaveSchemaVersionKey, SaveSchemaVersion);
            PlayerPrefs.Save();
        }

        private void MigrateLocalSaveSchema(int fromVersion)
        {
            // v0 -> v1 has no destructive migration. Individual settings are clamped during load.
            if (fromVersion < 2)
            {
                PlayerPrefs.SetInt("DestinyRanger.ControlReachMode", 2);
                if (!PlayerPrefs.HasKey("DestinyRanger.ControlSizeMode"))
                    PlayerPrefs.SetInt("DestinyRanger.ControlSizeMode", 1);
            }
            if (fromVersion < 3)
            {
                PlayerPrefs.SetFloat("DestinyRanger.CombatControlOffsetX", 0f);
                PlayerPrefs.SetFloat("DestinyRanger.CombatControlOffsetY", 0f);
                foreach (var id in CombatControlIds)
                {
                    PlayerPrefs.DeleteKey(CombatButtonOffsetXKey(id));
                    PlayerPrefs.DeleteKey(CombatButtonOffsetYKey(id));
                }
                PlayerPrefs.SetInt("DestinyRanger.ControlReachMode", 2);
                PlayerPrefs.SetInt("DestinyRanger.ControlSizeMode", 1);
            }
        }

        private void LoadUnlockedAchievements()
        {
            unlockedAchievements.Clear();
            foreach (var id in AchievementIds)
            {
                if (PlayerPrefs.GetInt(AchievementKey(id), 0) == 1)
                    unlockedAchievements.Add(id);
            }
        }

        private void SaveSettings()
        {
            PlayerPrefs.SetInt(SaveSchemaVersionKey, SaveSchemaVersion);
            PlayerPrefs.SetInt("DestinyRanger.AssistMode", assistMode ? 1 : 0);
            PlayerPrefs.SetInt("DestinyRanger.AutoAttack", autoAttackEnabled ? 1 : 0);
            PlayerPrefs.SetInt("DestinyRanger.AutoAim", autoAimEnabled ? 1 : 0);
            PlayerPrefs.SetInt("DestinyRanger.Sound", soundEnabled ? 1 : 0);
            PlayerPrefs.SetInt("DestinyRanger.Haptics", hapticsEnabled ? 1 : 0);
            PlayerPrefs.SetFloat("DestinyRanger.EffectsIntensity", effectsIntensity);
            PlayerPrefs.SetFloat("DestinyRanger.MasterVolume", masterVolume);
            PlayerPrefs.SetFloat("DestinyRanger.SfxVolume", sfxVolume);
            PlayerPrefs.SetFloat("DestinyRanger.MusicVolume", musicVolume);
            PlayerPrefs.SetInt("DestinyRanger.CompactControls", compactControls ? 1 : 0);
            PlayerPrefs.SetInt("DestinyRanger.ControlSizeMode", controlSizeMode);
            PlayerPrefs.SetInt("DestinyRanger.ControlReachMode", controlReachMode);
            PlayerPrefs.SetInt("DestinyRanger.ControlOpacityMode", controlOpacityMode);
            PlayerPrefs.SetInt("DestinyRanger.TrialHeatLevel", trialHeatLevel);
            PlayerPrefs.SetFloat("DestinyRanger.CombatControlOffsetX", combatControlCustomOffset.x);
            PlayerPrefs.SetFloat("DestinyRanger.CombatControlOffsetY", combatControlCustomOffset.y);
            SaveCombatButtonOffsets();
            PlayerPrefs.SetInt("DestinyRanger.FrameRateMode", frameRateMode);
            PlayerPrefs.SetInt("DestinyRanger.HeroActionBeatHud", showHeroActionBeatHud ? 1 : 0);
            PlayerPrefs.Save();
        }

        private void LoadCombatButtonOffsets()
        {
            combatButtonCustomOffsets.Clear();
            foreach (var id in CombatControlIds)
            {
                var offset = new Vector2(
                    Mathf.Clamp(PlayerPrefs.GetFloat(CombatButtonOffsetXKey(id), 0f), -260f, 180f),
                    Mathf.Clamp(PlayerPrefs.GetFloat(CombatButtonOffsetYKey(id), 0f), -180f, 240f));
                if (offset.sqrMagnitude > 1f)
                    combatButtonCustomOffsets[id] = offset;
            }
        }

        private void SaveCombatButtonOffsets()
        {
            foreach (var id in CombatControlIds)
            {
                var offset = CombatButtonOffset(id);
                PlayerPrefs.SetFloat(CombatButtonOffsetXKey(id), offset.x);
                PlayerPrefs.SetFloat(CombatButtonOffsetYKey(id), offset.y);
            }
        }

        private static string CombatButtonOffsetXKey(string id)
        {
            return "DestinyRanger.ControlButtonOffset." + id + ".X";
        }

        private static string CombatButtonOffsetYKey(string id)
        {
            return "DestinyRanger.ControlButtonOffset." + id + ".Y";
        }

        private void UpdateSettingsText()
        {
            RefreshVolumeSlider();
            UpdateSettingsComfortBadges();
            if (!settingsStatusText) return;
            string sizeLabel = controlSizeMode == 0 ? "小" : controlSizeMode == 2 ? "大" : "标准";
            string reachLabel = controlReachMode == 0 ? "靠内" : controlReachMode == 2 ? "贴右" : "标准";
            string opacityLabel = controlOpacityMode == 0 ? "清爽" : controlOpacityMode == 2 ? "清晰" : "标准";
            string volumeLabel = masterVolume > .85f ? "高" : masterVolume > .5f ? "中" : "低";
            string effectsLabel = effectsIntensity > .75f ? "标准" : "舒适低闪";
            string frameRateLabel = frameRateMode == 0 ? "省电" : "流畅";
            string controllerLabel = HasConnectedController() ? "已连接" : "触屏优先";
            settingsStatusText.text =
                $"辅助：{(assistMode ? "开 · 伤害-35% · 闪避宽容" : "关 · 标准挑战")} · 朝向{(autoAimEnabled ? "自动" : "手动")} · 攻击{(autoAttackEnabled ? "自动" : "手动")}\n" +
                $"反馈：音效{(soundEnabled ? "开" : "关")} {Mathf.RoundToInt(sfxVolume * 100f)}% · 音乐{Mathf.RoundToInt(musicVolume * 100f)}% · 总{volumeLabel}{Mathf.RoundToInt(masterVolume * 100f)}% · 震动{(hapticsEnabled ? "开" : "关")}\n" +
                $"触控：{(compactControls ? "紧凑" : "标准")} · 按钮{sizeLabel} · 右手{reachLabel} · 透明{opacityLabel}{Mathf.RoundToInt(CombatControlAlpha() * 100f)}% · 微调{(controlEditMode ? "拖动中" : HasCustomControlOffset() ? "已存" : "未调")}\n" +
                $"性能：{frameRateLabel} {CurrentTargetFrameRate()}FPS · 特效{effectsLabel} · 动作帧{(showHeroActionBeatHud ? "显示" : "隐藏")} · 控制器{controllerLabel}";
        }

        private void UpdateSettingsComfortBadges()
        {
            if (!settingsComfortBadgesText) return;
            string flash = effectsIntensity > .75f ? "标准特效" : "舒适低闪";
            string aim = autoAimEnabled ? "自动朝向" : "手动朝向";
            string controls = HasCustomControlOffset() ? "按键已微调" : controlReachMode == 2 ? "右手贴边" : "右手标准";
            string controller = HasConnectedController() ? "控制器已连接" : "触屏优先";
            string actionBeat = showHeroActionBeatHud ? "开发调帧" : "正式HUD";
            settingsComfortBadgesText.text = $"{flash}    {aim}    {controls}    {actionBeat}    前景清晰    {controller}    离线单机    无广告/无分析";
            settingsComfortBadgesText.color = effectsIntensity > .75f ? new Color(.78f, .94f, 1f, .84f) : C("#B8FFD6");
        }

        private static bool HasConnectedController()
        {
            var joystickNames = Input.GetJoystickNames();
            if (joystickNames == null) return false;
            foreach (var name in joystickNames)
            {
                if (!string.IsNullOrWhiteSpace(name))
                    return true;
            }
            return false;
        }

        private void PlaySfx(AudioClip clip, float volumeScale = 1f)
        {
            if (!soundEnabled || !audioSource || !clip) return;
            audioSource.PlayOneShot(clip, Mathf.Clamp01(volumeScale * masterVolume * sfxVolume));
        }

        private void ApplyAudioMix()
        {
            if (musicSource) musicSource.volume = Mathf.Clamp01(masterVolume * musicVolume);
        }

        private void HapticPulse()
        {
            HapticPulse(HapticTier.Medium);
        }

        private void HapticPulse(HapticTier tier)
        {
            if (!hapticsEnabled || !Application.isMobilePlatform) return;
            float minGap = HapticTierMinGap(tier);
            if (hapticCooldownTimer > 0f) return;
            hapticCooldownTimer = minGap;
            if (tier == HapticTier.Reward)
                StartCoroutine(RewardHapticEcho());
            else if (tier == HapticTier.Heavy)
                StartCoroutine(HeavyHapticEcho());
            else
                Handheld.Vibrate();
        }

        private static float HapticTierMinGap(HapticTier tier)
        {
            return tier == HapticTier.Light ? .18f : tier == HapticTier.Medium ? .24f : tier == HapticTier.Heavy ? .34f : .48f;
        }

        private IEnumerator HeavyHapticEcho()
        {
            Handheld.Vibrate();
            yield return new WaitForSecondsRealtime(.055f);
            if (hapticsEnabled && Application.isMobilePlatform) Handheld.Vibrate();
        }

        private IEnumerator RewardHapticEcho()
        {
            Handheld.Vibrate();
            yield return new WaitForSecondsRealtime(.08f);
            if (hapticsEnabled && Application.isMobilePlatform) Handheld.Vibrate();
            yield return new WaitForSecondsRealtime(.11f);
            if (hapticsEnabled && Application.isMobilePlatform) Handheld.Vibrate();
        }

        private void TogglePause()
        {
            if (shopPanel && shopPanel.gameObject.activeSelf)
            {
                CloseShop();
                return;
            }
            if (settingsPanel && settingsPanel.gameObject.activeSelf)
            {
                ToggleSettings();
                return;
            }
            if (titleActive) return;
            if (!pausePanel) return;
            paused = !paused;
            pausePanel.gameObject.SetActive(paused);
            if (paused) SetPauseReason("战斗已冻结，点继续返回当前房间");
            inputLocked = paused;
            Time.timeScale = paused ? 0f : 1f;
        }

        private void SetPauseReason(string reason)
        {
            if (pauseReasonText) pauseReasonText.text = reason;
        }

        private void UpdateSkillOverlay(Image overlay, SkillKind skill)
        {
            if (!overlay) return;
            if (!SkillVisibleOnHud(skill))
            {
                overlay.gameObject.SetActive(false);
                return;
            }
            float cd = skillCooldowns.TryGetValue(skill, out var value) ? Mathf.Max(0, value) : 0;
            bool insufficientMp = cd <= .05f && mp < SkillCost(skill);
            overlay.gameObject.SetActive(cd > 0 || insufficientMp);
            overlay.fillAmount = cd > 0 ? Mathf.Clamp01(cd / SkillMaxCooldown(skill)) : 1f;
            overlay.color = insufficientMp ? new Color(.16f, .035f, .045f, .52f) : new Color(.01f, .025f, .040f, .42f);
        }

        private void UpdateCooldownText(Text text, SkillKind skill)
        {
            float cd = skillCooldowns.TryGetValue(skill, out var value) ? Mathf.Max(0, value) : 0;
            if (!text) return;
            if (!SkillVisibleOnHud(skill))
            {
                text.gameObject.SetActive(false);
                return;
            }
            if (cd > .05f)
            {
                text.gameObject.SetActive(true);
                text.text = Mathf.CeilToInt(cd).ToString();
                text.color = C("#FFFFFF");
                return;
            }
            bool insufficientMp = mp < SkillCost(skill);
            text.gameObject.SetActive(insufficientMp);
            if (insufficientMp)
            {
                text.text = "MP";
                text.color = C("#A8F4FF");
            }
        }

        private void UpdateSkillCostText(Text text, SkillKind skill)
        {
            if (!text) return;
            text.gameObject.SetActive(false);
            text.text = "";
            text.color = Color.clear;
        }

        private void UpdateSecondsText(Text text, float seconds)
        {
            if (!text) return;
            bool show = seconds > .05f;
            text.gameObject.SetActive(show);
            if (show) text.text = Mathf.CeilToInt(seconds).ToString();
        }

        private void UpdateControlStateTexts()
        {
            bool modalOpen = inputLocked || rollingRune || (shopPanel && shopPanel.gameObject.activeSelf);
            UpdateAttackStateText(modalOpen);
            UpdateDodgeStateText(modalOpen);
            UpdateRuneStateText(modalOpen);
            foreach (var skill in VisibleHudSkills())
                UpdateSkillStateText(SkillStateTextFor(skill), skill, modalOpen);
        }

        private void UpdateAttackStateText(bool modalOpen)
        {
            if (!attackStateText) return;
            SetControlStateText(attackStateText, false, "", C("#BDEAFF"));
        }

        private void UpdateDodgeStateText(bool modalOpen)
        {
            if (!dodgeStateText) return;
            SetControlStateText(dodgeStateText, false, "", C("#D9F8FF"));
        }

        private void UpdateRuneStateText(bool modalOpen)
        {
            if (!runeStateText) return;
            if (modalOpen && !rollingRune)
            {
                SetControlStateText(runeStateText, true, "锁定", C("#C9CED8"));
                return;
            }
            if (shrineAvailable)
            {
                SetControlStateText(runeStateText, true, "启封", C("#8FFFF6"));
                return;
            }
            if (CanUseShopInteraction())
            {
                SetControlStateText(runeStateText, true, "补给", C("#9FF8FF"));
                return;
            }
            if (fateEnergy >= RuneAnticipationThreshold)
            {
                SetControlStateText(runeStateText, true, "临界", C("#9FF8FF"));
                return;
            }
            SetControlStateText(runeStateText, false, "", C("#BDEAFF"));
        }

        private void UpdateSkillStateText(Text text, SkillKind skill, bool modalOpen)
        {
            if (!text) return;
            if (!SkillVisibleOnHud(skill))
            {
                SetControlStateText(text, false, "", C("#E9FBFF"));
                return;
            }
            float cd = skillCooldowns.TryGetValue(skill, out var value) ? Mathf.Max(0f, value) : 0f;
            if (modalOpen)
            {
                SetControlStateText(text, false, "", C("#C9CED8"));
                return;
            }
            if (SkillBuffered(skill))
            {
                SetControlStateText(text, true, "待发", SkillButtonSignalColor(skill));
                return;
            }
            if (cd > .05f)
            {
                SetControlStateText(text, false, "", C("#E9FBFF"));
                return;
            }
            if (mp < SkillCost(skill))
            {
                SetControlStateText(text, false, "", C("#E9FBFF"));
                return;
            }
            SetControlStateText(text, false, "", C("#E9FBFF"));
        }

        private static void SetControlStateText(Text text, bool active, string value, Color color)
        {
            if (!text) return;
            text.gameObject.SetActive(active);
            if (!active)
            {
                text.text = "";
                text.color = Color.clear;
                return;
            }
            text.text = value;
            float pulse = .74f + Mathf.Sin(Time.unscaledTime * 8f) * .12f;
            text.color = new Color(color.r, color.g, color.b, pulse);
        }

        private void UpdateRuneReadyText()
        {
            bool shopReady = CanUseShopInteraction();
            bool runeReady = shrineAvailable || shopReady;
            bool nearReady = !runeReady && fateEnergy >= RuneAnticipationThreshold;
            if (runeButtonLabel)
                runeButtonLabel.text = shrineAvailable ? "启封!" : shopReady ? "补给" : nearReady ? "将启封" : "充能";
            if (runeCooldownOverlay)
            {
                runeCooldownOverlay.gameObject.SetActive(!runeReady);
                runeCooldownOverlay.fillAmount = Mathf.Clamp01(1f - fateEnergy / 100f);
                runeCooldownOverlay.color = nearReady ? new Color(.02f, .10f, .12f, .34f) : new Color(0, 0, 0, .50f);
            }
            if (!runeCooldownText) return;
            runeCooldownText.gameObject.SetActive(!runeReady);
            runeCooldownText.text = Mathf.FloorToInt(Mathf.Clamp(fateEnergy, 0f, 99f)) + "%";
            runeCooldownText.color = nearReady ? C("#9FF8FF") : Color.white;
        }

        private void UpdateControlFeedback()
        {
            ApplyVisibleSkillSet();
            TickControlPulses();
            float x = Input.GetAxisRaw("Horizontal");
            float y = Input.GetAxisRaw("Vertical");
            if (Input.GetKey(KeyCode.A) || Input.GetKey(KeyCode.LeftArrow)) x -= 1;
            if (Input.GetKey(KeyCode.D) || Input.GetKey(KeyCode.RightArrow)) x += 1;
            if (Input.GetKey(KeyCode.W) || Input.GetKey(KeyCode.UpArrow)) y += 1;
            if (Input.GetKey(KeyCode.S) || Input.GetKey(KeyCode.DownArrow)) y -= 1;
            if (touchMoveActive)
            {
                x = touchMoveInput.x;
                y = touchMoveInput.y;
            }
            else if (joystickBaseUi)
            {
                joystickBaseUi.anchoredPosition = Vector2.Lerp(joystickBaseUi.anchoredPosition, JoystickDefaultPosition, Time.deltaTime * 10f);
            }
            if (joystickKnobUi)
            {
                Vector2 basePos = joystickBaseUi ? joystickBaseUi.anchoredPosition : JoystickDefaultPosition;
                var target = basePos + Vector2.ClampMagnitude(new Vector2(x, y), 1f) * 54f;
                joystickKnobUi.anchoredPosition = Vector2.Lerp(joystickKnobUi.anchoredPosition, target, Time.deltaTime * 18f);
            }
            UpdateJoystickVisualState(new Vector2(x, y));

            SetButtonPressed(attackButtonUi, touchAttackHeld || IsControlPulsing(attackButtonUi) || Input.GetKey(KeyCode.J) || Input.GetKey(KeyCode.Space) || ControllerAttackHeld() || attackCooldown > .08f || attackBufferTimer > .03f);
            SetAttackButtonCombatFeedback();
            UpdateAttackComboIndicator();
            UpdateInputBufferIndicators();
            SetButtonPressed(jumpButtonUi, IsControlPulsing(jumpButtonUi) || Input.GetKey(KeyCode.K) || Input.GetKey(KeyCode.W) || Input.GetKey(KeyCode.UpArrow) || Input.GetKey(KeyCode.JoystickButton0) || jumpBufferTimer > .03f);
            SetButtonPressed(dodgeButtonUi, IsControlPulsing(dodgeButtonUi) || Input.GetKey(KeyCode.LeftShift) || Input.GetKey(KeyCode.RightShift) || Input.GetKey(KeyCode.JoystickButton1) || dodgeCooldown > 0 || dodgeBufferTimer > .03f);
            bool runeActionReady = shrineAvailable || CanUseShopInteraction();
            bool runeNearReady = fateEnergy >= RuneAnticipationThreshold;
            SetButtonPressed(runeButtonUi, IsControlPulsing(runeButtonUi) || Input.GetKey(KeyCode.R) || Input.GetKey(KeyCode.F) || Input.GetKey(KeyCode.JoystickButton8) || Input.GetKey(KeyCode.JoystickButton9) || runeActionReady || runeNearReady);
            SetSkillButtonPressedIfVisible(skill1ButtonUi, SkillKind.SlashWave, Input.GetKey(KeyCode.U) || Input.GetKey(KeyCode.JoystickButton3));
            ApplyRuneButtonAvailability();
            foreach (var skill in VisibleHudSkills())
                ApplySkillButtonAvailability(SkillButtonFor(skill), skill);
            TickTouchDownEchoes();
        }

        private void SetSkillButtonPressedIfVisible(RectTransform button, SkillKind skill, bool inputHeld)
        {
            if (!SkillVisibleOnHud(skill))
            {
                SetButtonPressed(button, false);
                return;
            }
            SetButtonPressed(button, IsControlPulsing(button) || inputHeld || SkillBuffered(skill));
        }

        private void ApplyRuneButtonAvailability()
        {
            if (!runeButtonUi) return;
            bool ready = shrineAvailable || CanUseShopInteraction();
            bool nearReady = !ready && fateEnergy >= RuneAnticipationThreshold;
            bool locked = CombatControlsLocked();
            var image = runeButtonUi.GetComponent<Image>();
            if (image)
            {
                Color target = ready ? C("#66FFF0") : nearReady ? C("#34D8E6") : C("#7FA6A8");
                image.color = Color.Lerp(image.color, target, Time.deltaTime * 10f);
            }
            ApplyButtonReadiness(runeButtonUi, (ready || nearReady) && !locked, locked, nearReady ? C("#9FF8FF") : C("#66FFF0"));
            ApplyReadyGlow(runeReadyGlow, (ready || nearReady) && !locked, nearReady ? C("#9FF8FF") : C("#66FFF0"), nearReady ? 1.04f : 1.08f);
        }

        private void ApplySkillButtonAvailability(RectTransform button, SkillKind skill)
        {
            if (!button) return;
            if (!SkillVisibleOnHud(skill))
            {
                button.gameObject.SetActive(false);
                return;
            }
            float cd = skillCooldowns.TryGetValue(skill, out var value) ? Mathf.Max(0, value) : 0;
            var image = button.GetComponent<Image>();
            if (!image) return;
            bool buffered = SkillBuffered(skill);
            bool blocked = CombatControlsLocked() || (cd > .05f && !buffered) || mp < SkillCost(skill);
            Color baseColor = SkillButtonReadyColor(skill);
            Color target = buffered ? Color.Lerp(C("#566170"), SkillButtonSignalColor(skill), .36f) : cd > .05f ? C("#566170") : mp < SkillCost(skill) ? C("#5A4650") : baseColor;
            image.color = Color.Lerp(image.color, target, Time.deltaTime * 10f);
            ApplyCombatButtonLabelColor(button, blocked ? new Color(.86f, .94f, 1f, .48f) : new Color(1f, 1f, 1f, .86f));
            Color signalColor = SkillButtonSignalColor(skill);
            ApplyButtonReadiness(button, !blocked || buffered, blocked && !buffered, signalColor);
            ApplyReadyGlow(SkillReadyGlowFor(skill), (!blocked || buffered), signalColor, buffered ? 1.02f : 1.04f);
        }

        private static void ApplyCombatButtonLabelColor(RectTransform button, Color color)
        {
            if (!button) return;
            var label = button.Find("Label");
            var text = label ? label.GetComponent<Text>() : null;
            if (text) text.color = color;
        }

        private bool CombatControlsLocked()
        {
            return inputLocked || rollingRune || (shopPanel && shopPanel.gameObject.activeSelf);
        }

        private static bool SkillVisibleOnHud(SkillKind skill)
        {
            return skill == SkillKind.SlashWave;
        }

        private static IEnumerable<SkillKind> VisibleHudSkills()
        {
            yield return SkillKind.SlashWave;
        }

        private void UpdateVisibleSkillHud()
        {
            foreach (var skill in VisibleHudSkills())
            {
                UpdateSkillOverlay(SkillCooldownOverlayFor(skill), skill);
                UpdateCooldownText(SkillCooldownTextFor(skill), skill);
                UpdateSkillCostText(SkillCostTextFor(skill), skill);
            }
        }

        private RectTransform SkillButtonFor(SkillKind skill)
        {
            if (skill == SkillKind.SlashWave) return skill1ButtonUi;
            if (skill == SkillKind.Fireball) return skill2ButtonUi;
            if (skill == SkillKind.FrostNova) return skill3ButtonUi;
            if (skill == SkillKind.ThunderStrike) return skill4ButtonUi;
            return null;
        }

        private Image SkillCooldownOverlayFor(SkillKind skill)
        {
            if (skill == SkillKind.SlashWave) return skill1CooldownOverlay;
            if (skill == SkillKind.Fireball) return skill2CooldownOverlay;
            if (skill == SkillKind.FrostNova) return skill3CooldownOverlay;
            if (skill == SkillKind.ThunderStrike) return skill4CooldownOverlay;
            return null;
        }

        private Text SkillCooldownTextFor(SkillKind skill)
        {
            if (skill == SkillKind.SlashWave) return skill1CooldownText;
            if (skill == SkillKind.Fireball) return skill2CooldownText;
            if (skill == SkillKind.FrostNova) return skill3CooldownText;
            if (skill == SkillKind.ThunderStrike) return skill4CooldownText;
            return null;
        }

        private Text SkillCostTextFor(SkillKind skill)
        {
            if (skill == SkillKind.SlashWave) return skill1CostText;
            if (skill == SkillKind.Fireball) return skill2CostText;
            if (skill == SkillKind.FrostNova) return skill3CostText;
            if (skill == SkillKind.ThunderStrike) return skill4CostText;
            return null;
        }

        private Text SkillStateTextFor(SkillKind skill)
        {
            if (skill == SkillKind.SlashWave) return skill1StateText;
            if (skill == SkillKind.Fireball) return skill2StateText;
            if (skill == SkillKind.FrostNova) return skill3StateText;
            if (skill == SkillKind.ThunderStrike) return skill4StateText;
            return null;
        }

        private Image SkillReadyGlowFor(SkillKind skill)
        {
            if (skill == SkillKind.SlashWave) return skill1ReadyGlow;
            if (skill == SkillKind.Fireball) return skill2ReadyGlow;
            if (skill == SkillKind.FrostNova) return skill3ReadyGlow;
            if (skill == SkillKind.ThunderStrike) return skill4ReadyGlow;
            return null;
        }

        private Color SkillButtonReadyColor(SkillKind skill)
        {
            if (skill == SkillKind.SlashWave) return C("#B884FF");
            if (skill == SkillKind.Fireball) return C("#4FBFEF");
            if (skill == SkillKind.FrostNova) return C("#78D8FF");
            if (skill == SkillKind.ThunderStrike) return C("#8FFFF6");
            return Color.white;
        }

        private Color SkillButtonSignalColor(SkillKind skill)
        {
            if (skill == SkillKind.SlashWave) return C("#B884FF");
            if (skill == SkillKind.Fireball) return C("#7EDCFF");
            if (skill == SkillKind.FrostNova) return C("#78D8FF");
            if (skill == SkillKind.ThunderStrike) return C("#8FFFF6");
            return Color.white;
        }

        private void ApplyButtonReadiness(RectTransform button, bool ready, bool blocked, Color readyColor)
        {
            if (!button) return;
            var rim = button.Find(button.name + "Rim");
            var rimImage = rim ? rim.GetComponent<Image>() : null;
            if (!rimImage) return;
            float pulse = ready ? .18f + Mathf.Sin(Time.time * 5.5f) * .042f : blocked ? .035f : .075f;
            Color target = ready ? new Color(readyColor.r, readyColor.g, readyColor.b, pulse) : new Color(1f, 1f, 1f, pulse);
            rimImage.color = Color.Lerp(rimImage.color, target, Time.deltaTime * 12f);
            float scale = ready ? 1.01f + Mathf.Sin(Time.time * 5.5f) * .012f : 1f;
            rim.localScale = Vector3.Lerp(rim.localScale, new Vector3(scale, scale, 1f), Time.deltaTime * 12f);
        }

        private void ApplyReadyGlow(Image glow, bool ready, Color color, float scaleBoost)
        {
            if (!glow) return;
            glow.gameObject.SetActive(ready);
            float alphaScale = effectsIntensity > .75f ? 1f : .72f;
            float pulse = .080f + Mathf.Sin(Time.unscaledTime * 5.5f) * .026f;
            glow.color = new Color(color.r, color.g, color.b, Mathf.Clamp01(pulse * alphaScale));
            float scale = scaleBoost + Mathf.Sin(Time.unscaledTime * 5.5f) * .018f;
            glow.rectTransform.localScale = new Vector3(scale, scale, 1f);
        }

        private void BuildAttackComboIndicator(RectTransform parent)
        {
            attackComboPips.Clear();
            if (!parent) return;
            for (int i = 0; i < 3; i++)
            {
                var pip = UICircle("AttackComboPip_" + i, parent, new Vector2(-42 + i * 42, 78), new Vector2(24, 24), new Vector2(.5f, .5f), new Vector2(.5f, .5f), new Color(1f, 1f, 1f, .22f));
                var image = pip.GetComponent<Image>();
                if (image) image.raycastTarget = false;
                attackComboPips.Add(image);
            }
            attackStepText = UIText("AttackStepText", parent, "", 18, TextAnchor.MiddleCenter, new Vector2(0, 48), new Vector2(146, 28), new Vector2(.5f, .5f), new Vector2(.5f, .5f));
            attackStepText.color = new Color(.78f, .96f, 1f, .86f);
            attackStepText.raycastTarget = false;
            attackRhythmWindowTrack = UIBox("AttackRhythmWindowTrack", parent, new Vector2(0, 24), new Vector2(146, 10), new Vector2(.5f, .5f), new Vector2(.5f, .5f), new Color(.02f, .05f, .08f, .50f)).GetComponent<Image>();
            attackRhythmWindowTrack.raycastTarget = false;
            attackRhythmWindowFill = UIFillBox("AttackRhythmWindowFill", attackRhythmWindowTrack.transform, new Vector2(146, 10), C("#9FF8FF")).GetComponent<Image>();
            attackRhythmWindowFill.raycastTarget = false;
            attackRhythmWindowText = UIText("AttackRhythmWindowText", parent, "", 14, TextAnchor.MiddleCenter, new Vector2(0, 6), new Vector2(150, 22), new Vector2(.5f, .5f), new Vector2(.5f, .5f));
            attackRhythmWindowText.color = new Color(.78f, .96f, 1f, .72f);
            attackRhythmWindowText.raycastTarget = false;
            attackStateText = UIButtonMicroText(parent, "AttackStateText", "", new Vector2(0, -104), C("#BDEAFF"));
            attackBufferText = UIButtonMicroText(parent, "AttackBufferText", "", new Vector2(0, -78), C("#BDEAFF"));
        }

        private void UpdateAttackComboIndicator()
        {
            if (attackComboPips.Count == 0) return;
            int chainStep = comboTimer > 0f ? Mathf.Clamp(combo, 0, 3) : 0;
            float urgency = Mathf.Clamp01(comboTimer / AttackComboWindow);
            for (int i = 0; i < attackComboPips.Count; i++)
            {
                var pip = attackComboPips[i];
                if (!pip) continue;
                bool filled = i < chainStep;
                bool nextHeavy = chainStep == 2 && i == 2;
                float pulse = nextHeavy ? .75f + Mathf.Sin(Time.time * 13f) * .20f : filled ? .82f : .24f;
                Color target = nextHeavy ? new Color(.55f, .96f, 1f, pulse) : filled ? new Color(.74f, .96f, 1f, .78f) : new Color(1f, 1f, 1f, .22f);
                pip.color = Color.Lerp(pip.color, target, Time.unscaledDeltaTime * 16f);
                float scale = nextHeavy ? 1.18f + Mathf.Sin(Time.time * 13f) * .08f : filled ? 1.08f : 1f;
                pip.rectTransform.localScale = Vector3.Lerp(pip.rectTransform.localScale, new Vector3(scale, scale, 1f), Time.unscaledDeltaTime * 16f);
            }
            if (!attackStepText) return;
            bool show = chainStep > 0 && comboTimer > .05f;
            attackStepText.gameObject.SetActive(false);
            UpdateAttackRhythmWindow(show, chainStep, urgency);
            if (!show) return;
            bool breakReady = chainStep == 2 && attackCooldown <= .055f && comboTimer > .12f && !CombatControlsLocked();
            if (breakReady) ShowBreakReadyCueOnce();
        }

        private void UpdateAttackRhythmWindow(bool show, int chainStep, float urgency)
        {
            if (attackRhythmWindowTrack)
                attackRhythmWindowTrack.gameObject.SetActive(show);
            if (attackRhythmWindowFill)
            {
                attackRhythmWindowFill.gameObject.SetActive(show);
                attackRhythmWindowFill.fillAmount = urgency;
                Color target = attackBufferConfirmTimer > .03f ? C("#B8FFF6") : chainStep == 2 ? C("#8FFFF6") : urgency < .35f ? C("#A8F4FF") : C("#9FF8FF");
                float alpha = Mathf.Lerp(.42f, .94f, urgency);
                attackRhythmWindowFill.color = new Color(target.r, target.g, target.b, alpha);
            }
            if (!attackRhythmWindowText) return;
            attackRhythmWindowText.gameObject.SetActive(false);
            attackRhythmWindowText.text = "";
            attackRhythmWindowText.color = Color.clear;
        }

