        private static void SetInputBufferText(Text text, bool active, string value)
        {
            if (!text) return;
            text.gameObject.SetActive(active);
            if (!active) return;
            text.text = value;
            float pulse = .74f + Mathf.Sin(Time.unscaledTime * 18f) * .18f;
            text.color = new Color(.74f, .92f, 1f, pulse);
        }

        private void SetAttackButtonCombatFeedback()
        {
            if (!attackButtonUi) return;
            var image = attackButtonUi.GetComponent<Image>();
            if (!image) return;
            if (attackCooldown > .08f)
                image.color = Color.Lerp(image.color, C("#D84A4A"), Time.deltaTime * 18f);
            else if (!touchAttackHeld && !Input.GetKey(KeyCode.J) && !Input.GetKey(KeyCode.Space))
                image.color = Color.Lerp(image.color, Color.white, Time.deltaTime * 12f);
        }

        private void UpdateJoystickVisualState(Vector2 input)
        {
            if (!joystickBaseUi || !joystickKnobUi) return;
            float strength = Mathf.Clamp01(input.magnitude);
            float active = touchMoveActive || strength > .08f ? 1f : 0f;
            float baseAlpha = Mathf.Lerp(.46f, .90f, active);
            float knobAlpha = Mathf.Lerp(.58f, 1f, active);
            SetUiImageAlpha(joystickBaseUi, baseAlpha);
            SetUiImageAlpha(joystickKnobUi, knobAlpha);
            float baseScale = 1f + strength * .035f;
            float knobScale = 1f + strength * .10f;
            joystickBaseUi.localScale = Vector3.Lerp(joystickBaseUi.localScale, new Vector3(baseScale, baseScale, 1f), Time.deltaTime * 14f);
            joystickKnobUi.localScale = Vector3.Lerp(joystickKnobUi.localScale, new Vector3(knobScale, knobScale, 1f), Time.deltaTime * 16f);
            UpdateJoystickIntentText(strength, input);
        }

        private void UpdateJoystickIntentText(float strength, Vector2 input)
        {
            if (!joystickIntentText) return;
            bool show = touchMoveActive && strength > .18f && !inputLocked;
            joystickIntentText.gameObject.SetActive(show);
            if (!show)
            {
                joystickIntentText.color = Color.clear;
                return;
            }

            if (Mathf.Abs(input.x) >= QuickRunJoystickThreshold && Mathf.Abs(input.x) > Mathf.Abs(input.y) * 1.15f)
                joystickIntentText.text = "疾跑";
            else if (joystickIntentMode == 1 && Mathf.Abs(input.x) > .58f)
                joystickIntentText.text = dodgeCooldown > .05f ? "闪避冷却" : "横划闪避";
            else if (joystickIntentMode == 2 && input.y > JoystickJumpAxisThreshold)
                joystickIntentText.text = grounded ? "上推跳跃" : "空中移动";
            else if (joystickIntentMode == 3 && input.y < -.58f)
                joystickIntentText.text = "下落";
            else
                joystickIntentText.text = "移动中";

            float alpha = Mathf.Lerp(.66f, 1f, Mathf.Clamp01(strength)) * (.82f + Mathf.Sin(Time.unscaledTime * 12f) * .10f);
            joystickIntentText.color = new Color(.78f, 1f, .96f, alpha);
        }

        private static void SetUiImageAlpha(RectTransform target, float alpha)
        {
            var image = target ? target.GetComponent<Image>() : null;
            if (!image) return;
            var color = image.color;
            color.a = Mathf.Clamp01(alpha);
            image.color = color;
        }

        private void AttachJoystickEvents(RectTransform target)
        {
            if (!target) return;
            var trigger = target.gameObject.AddComponent<EventTrigger>();
            AddEventTrigger(trigger, EventTriggerType.PointerDown, data => BeginTouchJoystick((PointerEventData)data));
            AddEventTrigger(trigger, EventTriggerType.Drag, data => UpdateTouchJoystick((PointerEventData)data));
            AddEventTrigger(trigger, EventTriggerType.PointerUp, data => EndTouchJoystick((PointerEventData)data));
            AddEventTrigger(trigger, EventTriggerType.PointerExit, _ => ReleaseTouchJoystick());
        }

        private void AttachHoldAttackEvents(RectTransform target)
        {
            if (!target) return;
            var trigger = target.gameObject.AddComponent<EventTrigger>();
            AddEventTrigger(trigger, EventTriggerType.PointerDown, _ =>
            {
                touchAttackHeld = true;
                RequestBasicAttack();
            });
            AddEventTrigger(trigger, EventTriggerType.PointerUp, _ => touchAttackHeld = false);
            AddEventTrigger(trigger, EventTriggerType.PointerExit, _ => touchAttackHeld = false);
        }

        private void AttachJumpButtonEvents(RectTransform target)
        {
            if (!target) return;
            var trigger = target.GetComponent<EventTrigger>() ?? target.gameObject.AddComponent<EventTrigger>();
            AddEventTrigger(trigger, EventTriggerType.PointerDown, _ =>
            {
                touchJumpHeld = true;
                RequestJump();
            });
            AddEventTrigger(trigger, EventTriggerType.PointerUp, _ =>
            {
                touchJumpHeld = false;
                CutJumpHeight();
            });
            AddEventTrigger(trigger, EventTriggerType.PointerExit, _ =>
            {
                touchJumpHeld = false;
                CutJumpHeight();
            });
        }

        private void AttachSkillPreviewEvents(RectTransform target, SkillKind skill)
        {
            if (!target) return;
            var trigger = target.GetComponent<EventTrigger>() ?? target.gameObject.AddComponent<EventTrigger>();
            AddEventTrigger(trigger, EventTriggerType.PointerDown, _ => ShowSkillAimPreview(skill));
            AddEventTrigger(trigger, EventTriggerType.PointerUp, _ => HideSkillAimPreview());
            AddEventTrigger(trigger, EventTriggerType.PointerExit, _ => HideSkillAimPreview());
        }

        private void AttachTouchDownFeedback(RectTransform target)
        {
            if (!target) return;
            var trigger = target.GetComponent<EventTrigger>() ?? target.gameObject.AddComponent<EventTrigger>();
            AddEventTrigger(trigger, EventTriggerType.PointerDown, _ => PulseTouchDownFeedback(target));
        }

        private void AttachCombatControlDragEvents(RectTransform target)
        {
            if (!target) return;
            var trigger = target.GetComponent<EventTrigger>() ?? target.gameObject.AddComponent<EventTrigger>();
            string controlId = target.name;
            AddEventTrigger(trigger, EventTriggerType.Drag, data => DragCombatControlButton(controlId, (PointerEventData)data));
            AddEventTrigger(trigger, EventTriggerType.PointerUp, _ => SaveCombatControlOffsetIfEditing());
        }

        private void DragCombatControlButton(string controlId, PointerEventData data)
        {
            if (!controlEditMode || string.IsNullOrEmpty(controlId) || !safeAreaRoot || data == null) return;
            Vector2 delta = data.delta / Mathf.Max(.35f, canvas ? canvas.scaleFactor : 1f);
            Vector2 offset = CombatButtonOffset(controlId) + delta;
            offset.x = Mathf.Clamp(offset.x, -260f, 180f);
            offset.y = Mathf.Clamp(offset.y, -180f, 240f);
            if (offset.sqrMagnitude > 1f)
                combatButtonCustomOffsets[controlId] = offset;
            else
                combatButtonCustomOffsets.Remove(controlId);
            ApplyControlLayout();
        }

        private void SaveCombatControlOffsetIfEditing()
        {
            if (!controlEditMode) return;
            SaveSettings();
            UpdateSettingsText();
        }

        private bool HasCustomControlOffset()
        {
            if (combatControlCustomOffset.sqrMagnitude > 1f) return true;
            foreach (var offset in combatButtonCustomOffsets.Values)
            {
                if (offset.sqrMagnitude > 1f) return true;
            }
            return false;
        }

        private void UpdateControlEditHint()
        {
            bool show = controlEditMode;
            if (controlEditHintText)
            {
                controlEditHintText.gameObject.SetActive(show);
                if (show) controlEditHintText.text = "按键微调：拖动任意右侧按钮可单独移动，命中提示会避开右手热区";
            }
            if (thumbReachSafeZone)
            {
                thumbReachSafeZone.gameObject.SetActive(show);
                float alpha = (effectsIntensity > .75f ? .12f : .08f) * CombatControlAlpha();
                thumbReachSafeZone.color = new Color(.08f, .28f, .36f, alpha);
            }
            if (thumbReachSafeZoneText)
            {
                thumbReachSafeZoneText.gameObject.SetActive(show);
                thumbReachSafeZoneText.color = show ? new Color(.78f, .96f, 1f, effectsIntensity > .75f ? .72f : .56f) : Color.clear;
            }
        }

        private void BeginTouchJoystick(PointerEventData data)
        {
            joystickPointerDownPosition = data.position;
            joystickPointerDownTime = Time.unscaledTime;
            joystickIntentMode = 0;
            joystickSwipeDodgeConsumed = false;
            MoveDynamicJoystickBase(data);
            UpdateTouchJoystick(data);
        }

        private void EndTouchJoystick(PointerEventData data)
        {
            var swipe = data.position - joystickPointerDownPosition;
            float elapsed = Time.unscaledTime - joystickPointerDownTime;
            bool canSwipeDodge = JoystickAllowsSwipeDodge(swipe, elapsed);
            ReleaseTouchJoystick();
            if (!canSwipeDodge) return;
            facing = swipe.x > 0 ? 1 : -1;
            playerSprite.flipX = facing < 0;
            RequestDodge();
        }

        private void UpdateTouchJoystick(PointerEventData data)
        {
            if (!joystickBaseUi || !joystickKnobUi) return;
            touchMoveActive = true;
            RectTransformUtility.ScreenPointToLocalPointInRectangle(joystickBaseUi, data.position, data.pressEventCamera, out var local);
            var clamped = Vector2.ClampMagnitude(local, joystickBaseUi.sizeDelta.x * .34f);
            UpdateJoystickIntentLock(data.position - joystickPointerDownPosition);
            touchMoveInput = new Vector2(
                Mathf.Clamp(clamped.x / (joystickBaseUi.sizeDelta.x * .34f), -1f, 1f),
                Mathf.Clamp(clamped.y / (joystickBaseUi.sizeDelta.y * .34f), -1f, 1f));
            joystickKnobUi.anchoredPosition = joystickBaseUi.anchoredPosition + clamped;
        }

        private void ReleaseTouchJoystick()
        {
            touchMoveActive = false;
            touchMoveInput = Vector2.zero;
            ResetJoystickIntentLock();
            if (joystickKnobUi && joystickBaseUi) joystickKnobUi.anchoredPosition = joystickBaseUi.anchoredPosition;
        }

        private void ResetJoystickIntentLock()
        {
            joystickIntentMode = 0;
            joystickSwipeDodgeConsumed = false;
        }

        private void ResetQuickRunIntent()
        {
            lastLeftTapTime = -999f;
            lastRightTapTime = -999f;
            quickRunDirection = 0;
            quickRunTimer = 0f;
            quickRunCueTimer = 0f;
            quickRunCameraTimer = 0f;
            quickRunAirCarryTimer = 0f;
            quickRunAirCarryDirection = 0;
        }

        private void UpdateJoystickIntentLock(Vector2 swipe)
        {
            if (joystickIntentMode != 0 || swipe.magnitude < JoystickIntentLockDistance) return;
            float absX = Mathf.Abs(swipe.x);
            float absY = Mathf.Abs(swipe.y);
            if (absX > absY * 1.35f)
                joystickIntentMode = 1;
            else if (absY > absX * 1.18f)
                joystickIntentMode = swipe.y > 0 ? 2 : 3;
            else
                joystickIntentMode = 4;
        }

        private bool JoystickAllowsJumpAxis()
        {
            return joystickIntentMode == 0 || joystickIntentMode == 2;
        }

        private bool JoystickAllowsSwipeDodge(Vector2 swipe, float elapsed)
        {
            if (inputLocked || joystickSwipeDodgeConsumed || elapsed > .28f) return false;
            if (joystickIntentMode != 1) return false;
            if (Mathf.Abs(swipe.x) < JoystickSwipeDodgeDistance) return false;
            if (Mathf.Abs(swipe.x) < Mathf.Abs(swipe.y) * 1.55f) return false;
            joystickSwipeDodgeConsumed = true;
            return true;
        }

        private void MoveDynamicJoystickBase(PointerEventData data)
        {
            if (!joystickBaseUi || data == null) return;
            var parent = joystickBaseUi.parent as RectTransform;
            if (!parent) return;
            RectTransformUtility.ScreenPointToLocalPointInRectangle(parent, data.position, data.pressEventCamera, out var local);
            Vector2 anchored = local + new Vector2(parent.rect.width * parent.pivot.x, parent.rect.height * parent.pivot.y);
            anchored.x = Mathf.Clamp(anchored.x, 150f, 610f);
            anchored.y = Mathf.Clamp(anchored.y, 118f, 360f);
            joystickBaseUi.anchoredPosition = anchored;
            if (joystickKnobUi) joystickKnobUi.anchoredPosition = anchored;
        }

        private static void AddEventTrigger(EventTrigger trigger, EventTriggerType type, UnityEngine.Events.UnityAction<BaseEventData> action)
        {
            var entry = new EventTrigger.Entry { eventID = type };
            entry.callback.AddListener(action);
            trigger.triggers.Add(entry);
        }

        private static void SetButtonPressed(RectTransform button, bool pressed)
        {
            if (!button) return;
            float scale = pressed ? 1.045f : 1f;
            button.localScale = Vector3.Lerp(button.localScale, new Vector3(scale, scale, 1), Time.deltaTime * 18f);
            var group = button.GetComponent<CanvasGroup>();
            if (group && pressed) group.alpha = Mathf.Max(group.alpha, .62f);
        }

        private void PulseControlButton(RectTransform button, float duration = .14f)
        {
            if (!button) return;
            controlPulseTimers[button] = Mathf.Max(duration, controlPulseTimers.TryGetValue(button, out var oldValue) ? oldValue : 0f);
        }

        private void PulseTouchDownFeedback(RectTransform button)
        {
            if (!button) return;
            controlTouchDownEchoTimers[button] = TouchDownEchoDuration;
            PulseControlButton(button, .10f);
        }

        private bool IsControlPulsing(RectTransform button)
        {
            return button && controlPulseTimers.TryGetValue(button, out var timeLeft) && timeLeft > 0f;
        }

        private void TickControlPulses()
        {
            if (controlPulseTimers.Count == 0) return;
            foreach (var key in controlPulseTimers.Keys.ToList())
            {
                float next = controlPulseTimers[key] - Time.unscaledDeltaTime;
                if (next <= 0f || !key) controlPulseTimers.Remove(key);
                else controlPulseTimers[key] = next;
            }
        }

        private void TickTouchDownEchoes()
        {
            if (controlTouchDownEchoTimers.Count == 0) return;
            foreach (var key in controlTouchDownEchoTimers.Keys.ToList())
            {
                float next = controlTouchDownEchoTimers[key] - Time.unscaledDeltaTime;
                if (next <= 0f || !key)
                {
                    ResetTouchDownEcho(key);
                    controlTouchDownEchoTimers.Remove(key);
                    continue;
                }
                controlTouchDownEchoTimers[key] = next;
                ApplyTouchDownEcho(key, Mathf.Clamp01(next / TouchDownEchoDuration));
            }
        }

        private static void ApplyTouchDownEcho(RectTransform button, float normalized)
        {
            if (!button) return;
            var rim = button.Find(button.name + "Rim");
            var rimImage = rim ? rim.GetComponent<Image>() : null;
            if (!rimImage) return;
            float bloom = Mathf.Sin((1f - normalized) * Mathf.PI);
            rim.localScale = new Vector3(1.015f + bloom * .026f, 1.015f + bloom * .026f, 1f);
            rimImage.color = new Color(.72f, 1f, 1f, Mathf.Lerp(.024f, .10f, normalized));
        }

        private static void ResetTouchDownEcho(RectTransform button)
        {
            if (!button) return;
            var rim = button.Find(button.name + "Rim");
            var rimImage = rim ? rim.GetComponent<Image>() : null;
            if (!rimImage) return;
            rim.localScale = Vector3.one;
            rimImage.color = new Color(1f, 1f, 1f, .11f);
        }

        private static Sprite[] Slice(Texture2D texture, int cols, int rows, float pixelsPerUnit)
        {
            if (!texture) return Array.Empty<Sprite>();
            texture = ChromaKeyGreen(texture);
            var list = new List<Sprite>();
            int w = texture.width / cols;
            int h = texture.height / rows;
            for (int row = 0; row < rows; row++)
            {
                for (int col = 0; col < cols; col++)
                {
                    var rect = new Rect(col * w, texture.height - (row + 1) * h, w, h);
                    list.Add(Sprite.Create(texture, rect, new Vector2(.5f, .5f), pixelsPerUnit));
                }
            }
            return list.ToArray();
        }

        private static Sprite[] SliceHeroSheet(Texture2D texture, float pixelsPerUnit)
        {
            if (!texture) return Array.Empty<Sprite>();
            string sheetName = texture.name ?? "";
            bool actionSheet = sheetName.IndexOf("action", StringComparison.OrdinalIgnoreCase) >= 0 || texture.width < 1600 || texture.height > 1000;
            return actionSheet ? SliceTrimmed(texture, 4, 3, pixelsPerUnit) : SliceTrimmed(texture, 8, 4, pixelsPerUnit);
        }

        private static Sprite[] SliceTrimmed(Texture2D texture, int cols, int rows, float pixelsPerUnit, bool keepLargestOpaqueComponent = false)
        {
            if (!texture) return Array.Empty<Sprite>();
            var list = new List<Sprite>();
            int cellW = texture.width / cols;
            int cellH = texture.height / rows;
            Color32[] pixels;
            try
            {
                pixels = texture.GetPixels32();
            }
            catch (Exception)
            {
                return Slice(texture, cols, rows, pixelsPerUnit);
            }
            for (int row = 0; row < rows; row++)
            {
                for (int col = 0; col < cols; col++)
                {
                    int x0 = col * cellW;
                    int y0 = texture.height - (row + 1) * cellH;
                    list.Add(CreateKeyedCellSprite(texture, pixels, x0, y0, cellW, cellH, pixelsPerUnit, keepLargestOpaqueComponent));
                }
            }
            return list.ToArray();
        }

        private static Sprite CreateKeyedCellSprite(Texture2D texture, Color32[] sourcePixels, int x0, int y0, int cellW, int cellH, float pixelsPerUnit, bool keepLargestOpaqueComponent = false)
        {
            var cellPixels = new Color32[cellW * cellH];
            for (int y = 0; y < cellH; y++)
                Array.Copy(sourcePixels, (y0 + y) * texture.width + x0, cellPixels, y * cellW, cellW);

            var cell = new Texture2D(cellW, cellH, TextureFormat.RGBA32, false);
            cell.name = (texture.name ?? "SpriteSheet") + "_KeyedCell";
            cell.SetPixels32(cellPixels);
            cell.Apply();

            try
            {
                cell = ChromaKeyGeneratedBackdrop(cell);
                if (keepLargestOpaqueComponent)
                    cell = KeepLargestOpaqueComponent(cell);
            }
            catch (Exception)
            {
                return Sprite.Create(texture, new Rect(x0, y0, cellW, cellH), new Vector2(.5f, .5f), pixelsPerUnit);
            }

            return CreateTrimmedSprite(cell, pixelsPerUnit);
        }

        private static Texture2D KeepLargestOpaqueComponent(Texture2D source)
        {
            Color32[] pixels;
            try
            {
                pixels = source.GetPixels32();
            }
            catch (Exception)
            {
                return source;
            }

            int width = source.width;
            int height = source.height;
            var visited = new bool[pixels.Length];
            var stack = new Stack<int>();
            var component = new List<int>();
            var best = new List<int>();

            for (int i = 0; i < pixels.Length; i++)
            {
                if (visited[i] || pixels[i].a <= 24) continue;
                component.Clear();
                visited[i] = true;
                stack.Push(i);
                while (stack.Count > 0)
                {
                    int index = stack.Pop();
                    component.Add(index);
                    int x = index % width;
                    int y = index / width;
                    TryPushOpaqueNeighbor(pixels, visited, stack, index - 1, x > 0);
                    TryPushOpaqueNeighbor(pixels, visited, stack, index + 1, x < width - 1);
                    TryPushOpaqueNeighbor(pixels, visited, stack, index - width, y > 0);
                    TryPushOpaqueNeighbor(pixels, visited, stack, index + width, y < height - 1);
                }

                if (component.Count > best.Count)
                    best = new List<int>(component);
            }

            if (best.Count <= 0) return source;
            var keep = new bool[pixels.Length];
            foreach (int index in best) keep[index] = true;
            for (int i = 0; i < pixels.Length; i++)
            {
                if (keep[i]) continue;
                var p = pixels[i];
                p.a = 0;
                pixels[i] = p;
            }

            var copy = new Texture2D(width, height, TextureFormat.RGBA32, false);
            copy.name = (source.name ?? "SpriteCell") + "_LargestComponent";
            copy.SetPixels32(pixels);
            copy.Apply();
            return copy;
        }

        private static void TryPushOpaqueNeighbor(Color32[] pixels, bool[] visited, Stack<int> stack, int index, bool valid)
        {
            if (!valid || index < 0 || index >= pixels.Length || visited[index] || pixels[index].a <= 24) return;
            visited[index] = true;
            stack.Push(index);
        }

        private static Sprite[] SpritesFromTextures(Texture2D[] textures, float pixelsPerUnit)
        {
            if (textures == null || textures.Length == 0) return Array.Empty<Sprite>();
            var list = new List<Sprite>();
            foreach (var texture in textures)
            {
                if (!texture) continue;
                list.Add(CreateTrimmedSprite(ChromaKeyGeneratedBackdrop(texture), pixelsPerUnit));
            }
            return list.ToArray();
        }

        private static Sprite CreateTrimmedSprite(Texture2D texture, float pixelsPerUnit)
        {
            if (!texture) return null;
            Color32[] pixels;
            try
            {
                pixels = texture.GetPixels32();
            }
            catch (Exception)
            {
                return Sprite.Create(texture, new Rect(0, 0, texture.width, texture.height), new Vector2(.5f, .5f), pixelsPerUnit);
            }

            int minX = texture.width, minY = texture.height, maxX = 0, maxY = 0;
            for (int y = 0; y < texture.height; y++)
            {
                int row = y * texture.width;
                for (int x = 0; x < texture.width; x++)
                {
                    if (pixels[row + x].a <= 32) continue;
                    if (x < minX) minX = x;
                    if (y < minY) minY = y;
                    if (x > maxX) maxX = x;
                    if (y > maxY) maxY = y;
                }
            }

            if (maxX <= minX || maxY <= minY)
                return Sprite.Create(texture, new Rect(0, 0, texture.width, texture.height), new Vector2(.5f, .5f), pixelsPerUnit);

            return Sprite.Create(texture, new Rect(minX, minY, maxX - minX + 1, maxY - minY + 1), new Vector2(.5f, .5f), pixelsPerUnit);
        }

        private static Sprite CreateFullRectSprite(Texture2D texture, float pixelsPerUnit)
        {
            if (!texture) return null;
            return Sprite.Create(texture, new Rect(0, 0, texture.width, texture.height), new Vector2(.5f, .5f), pixelsPerUnit);
        }

        private static Sprite CreateGroundWallSprite(Texture2D texture, float pixelsPerUnit)
        {
            if (!texture) return null;
            int cropHeight = Mathf.RoundToInt(texture.height * .84f);
            return Sprite.Create(texture, new Rect(0, 0, texture.width, cropHeight), new Vector2(.5f, .5f), pixelsPerUnit);
        }

        private static void FitSpriteToWorld(SpriteRenderer sr, float targetWidth, float targetHeight)
        {
            if (!sr || !sr.sprite) return;
            var size = sr.sprite.bounds.size;
            float scale = Mathf.Max(targetWidth / size.x, targetHeight / size.y);
            sr.transform.localScale = new Vector3(scale, scale, 1);
        }

        private static Texture2D ChromaKeyGreen(Texture2D source)
        {
            Color32[] pixels;
            try
            {
                pixels = source.GetPixels32();
            }
            catch (Exception)
            {
                return source;
            }
            for (int i = 0; i < pixels.Length; i++)
            {
                var p = pixels[i];
                int maxOther = Mathf.Max(p.r, p.b);
                bool pureChroma = p.g > 190 && p.r < 90 && p.b < 90;
                bool brightChromaSpill = p.g > 204 && maxOther < 184 && p.g - maxOther > 52;
                bool saturatedScreenEdge = p.g > 224 && maxOther < 218 && p.g > p.r * 1.10f && p.g > p.b * 1.10f;
                bool neonGreenFringe = p.g > 170 && p.r < 150 && p.b < 125 && p.g - maxOther > 46;
                bool pureMagenta = p.r > 205 && p.b > 175 && p.g < 92;
                bool magentaSpill = p.r > 162 && p.b > 124 && p.g < 152 && p.r - p.g > 36 && p.b - p.g > 24;
                if (pureChroma || brightChromaSpill || saturatedScreenEdge || neonGreenFringe || pureMagenta || magentaSpill) p.a = 0;
                if (p.a < 24) p.a = 0;
                pixels[i] = p;
            }
            CleanChromaFringeBesideTransparentPixels(pixels, source.width, source.height);
            var copy = new Texture2D(source.width, source.height, TextureFormat.RGBA32, false);
            copy.SetPixels32(pixels);
            copy.Apply();
            return copy;
        }

        private static void CleanChromaFringeBesideTransparentPixels(Color32[] pixels, int width, int height)
        {
            if (pixels == null || pixels.Length == 0) return;
            var cleaned = new Color32[pixels.Length];
            Array.Copy(pixels, cleaned, pixels.Length);
            for (int y = 1; y < height - 1; y++)
            {
                int row = y * width;
                for (int x = 1; x < width - 1; x++)
                {
                    int index = row + x;
                    var p = pixels[index];
                    if (p.a <= 24) continue;
                    bool nearTransparent = pixels[index - 1].a <= 24 || pixels[index + 1].a <= 24 || pixels[index - width].a <= 24 || pixels[index + width].a <= 24;
                    if (!nearTransparent) continue;
                    bool magentaFringe = p.r > 130 && p.b > 96 && p.g < 165 && p.r - p.g > 24 && p.b - p.g > 12;
                    bool greenFringe = p.g > 145 && p.r < 165 && p.b < 145 && p.g - Mathf.Max(p.r, p.b) > 34;
                    if (magentaFringe || greenFringe)
                    {
                        p.a = 0;
                        cleaned[index] = p;
                    }
                }
            }
            Array.Copy(cleaned, pixels, pixels.Length);
        }

        private static Texture2D ChromaKeyGeneratedBackdrop(Texture2D source)
        {
            var keyed = ChromaKeyGreen(source);
            Color32[] pixels;
            try
            {
                pixels = keyed.GetPixels32();
            }
            catch (Exception)
            {
                return keyed;
            }

            bool edgeBackdropRemoved = RemoveEdgeConnectedGeneratedBackdrop(pixels, keyed.width, keyed.height);
            Color32 edgeKey;
            if (!TryFindGeneratedBackdropKey(pixels, keyed.width, keyed.height, out edgeKey))
            {
                if (!edgeBackdropRemoved) return keyed;
                var edgeCleanCopy = new Texture2D(keyed.width, keyed.height, TextureFormat.RGBA32, false);
                edgeCleanCopy.SetPixels32(pixels);
                edgeCleanCopy.Apply();
                return edgeCleanCopy;
            }

            for (int i = 0; i < pixels.Length; i++)
            {
                var p = pixels[i];
                if (p.a <= 24)
                {
                    p.a = 0;
                }
                else
                {
                    int d = BackdropColorDistance(p, edgeKey);
                    if (d < 4200 || LooksLikeRelatedGeneratedBackdrop(p, edgeKey) || LooksLikeFlatGeneratedBackdropField(p, edgeKey))
                        p.a = 0;
                    else if (d < 9800)
                        p.a = (byte)Mathf.Min(p.a, 8);
                }
                pixels[i] = p;
            }

            var copy = new Texture2D(keyed.width, keyed.height, TextureFormat.RGBA32, false);
            copy.SetPixels32(pixels);
            copy.Apply();
            return copy;
        }

        private static bool RemoveEdgeConnectedGeneratedBackdrop(Color32[] pixels, int width, int height)
        {
            if (pixels == null || width <= 0 || height <= 0) return false;
            var visited = new bool[pixels.Length];
            var stack = new Stack<int>();
            for (int x = 0; x < width; x++)
            {
                TryPushGeneratedBackdropEdgePixel(pixels, visited, stack, x);
                TryPushGeneratedBackdropEdgePixel(pixels, visited, stack, (height - 1) * width + x);
            }
            for (int y = 1; y < height - 1; y++)
            {
                TryPushGeneratedBackdropEdgePixel(pixels, visited, stack, y * width);
                TryPushGeneratedBackdropEdgePixel(pixels, visited, stack, y * width + width - 1);
            }

            bool removed = false;
            while (stack.Count > 0)
            {
                int index = stack.Pop();
                var p = pixels[index];
                if (p.a != 0)
                {
                    p.a = 0;
                    pixels[index] = p;
                    removed = true;
                }
                int x = index % width;
                int y = index / width;
                if (x > 0) TryPushGeneratedBackdropNeighbor(pixels, visited, stack, index - 1);
                if (x < width - 1) TryPushGeneratedBackdropNeighbor(pixels, visited, stack, index + 1);
                if (y > 0) TryPushGeneratedBackdropNeighbor(pixels, visited, stack, index - width);
                if (y < height - 1) TryPushGeneratedBackdropNeighbor(pixels, visited, stack, index + width);
            }
            return removed;
        }

        private static void TryPushGeneratedBackdropEdgePixel(Color32[] pixels, bool[] visited, Stack<int> stack, int index)
        {
            if (index < 0 || index >= pixels.Length || visited[index]) return;
            var p = pixels[index];
            if (p.a <= 24 || LooksLikeGeneratedBackdropPlate(p))
            {
                visited[index] = true;
                stack.Push(index);
            }
        }

        private static void TryPushGeneratedBackdropNeighbor(Color32[] pixels, bool[] visited, Stack<int> stack, int index)
        {
            if (index < 0 || index >= pixels.Length || visited[index]) return;
            var p = pixels[index];
            if (p.a <= 24 || LooksLikeGeneratedBackdropPlate(p))
            {
                visited[index] = true;
                stack.Push(index);
            }
        }

        private static bool TryFindGeneratedBackdropKey(Color32[] pixels, int width, int height, out Color32 key)
        {
            int count = 0;
            int r = 0, g = 0, b = 0;
            int edgeSamples = Mathf.Max(1, width * 2 + height * 2 - 4);
            for (int y = 0; y < height; y++)
            {
                for (int x = 0; x < width; x++)
                {
                    if (x != 0 && y != 0 && x != width - 1 && y != height - 1) continue;
                    var p = pixels[y * width + x];
                    if (!LooksLikeGeneratedBackdropPlate(p)) continue;
                    r += p.r;
                    g += p.g;
                    b += p.b;
                    count++;
                }
            }

            if (count < Mathf.Max(6, edgeSamples / 12))
            {
                key = new Color32(0, 0, 0, 0);
                return false;
            }

            key = new Color32((byte)(r / count), (byte)(g / count), (byte)(b / count), 255);
            return true;
        }

        private static bool LooksLikeWarmGeneratedBackdrop(Color32 p)
        {
            return p.a > 32
                && p.r > 145
                && p.g > 105
                && p.g < 245
                && p.b < 150
                && p.r + 18 >= p.g
                && p.r - p.b > 40;
        }

        private static bool LooksLikeGeneratedBackdropPlate(Color32 p)
        {
            return LooksLikeWarmGeneratedBackdrop(p)
                || LooksLikeCoolGeneratedBackdrop(p)
                || LooksLikeCyanChromaGeneratedBackdrop(p)
                || LooksLikeDarkGeneratedBackdropPlate(p)
                || (p.a > 32 && p.r > 118 && p.g > 128 && p.g < 246 && p.b < 166 && p.g - p.r < 92 && p.g - p.b > 34)
                || (p.a > 32 && p.r > 182 && p.g > 166 && p.b > 118 && p.b < 206 && Mathf.Abs(p.r - p.g) < 58 && p.r - p.b > 18)
                || LooksLikePaleGeneratedBackdrop(p);
        }

        private static bool LooksLikeCyanChromaGeneratedBackdrop(Color32 p)
        {
            if (p.a <= 32) return false;
            bool greenCyanScreen = p.r < 82
                && p.r < 82
                && p.g > 178
                && p.b > 142
                && p.g >= p.b
                && p.g - p.r > 112
                && p.b - p.r > 88;
            bool blueCyanScreen = p.r < 92
                && p.g > 132
                && p.b > 168
                && p.b - p.r > 96
                && p.g - p.r > 62
                && Mathf.Abs(p.b - p.g) < 92;
            bool paleCyanPlate = p.r < 132
                && p.g > 156
                && p.b > 166
                && p.b - p.r > 58
                && p.g - p.r > 46
                && Mathf.Abs(p.b - p.g) < 72;
            return greenCyanScreen || blueCyanScreen || paleCyanPlate;
        }

        private static bool LooksLikeCoolGeneratedBackdrop(Color32 p)
        {
            if (p.a <= 32) return false;
            int max = Mathf.Max(p.r, Mathf.Max(p.g, p.b));
            int min = Mathf.Min(p.r, Mathf.Min(p.g, p.b));
            bool coolField = p.r < 178
                && p.g > 82
                && p.b > 82
                && (p.g - p.r > 18 || p.b - p.r > 20)
                && max - min < 132;
            bool mistyBlueField = p.r > 72
                && p.r < 178
                && p.g > 106
                && p.b > 116
                && p.b + 24 >= p.g
                && p.g + 18 >= p.b
                && max - min < 116;
            return coolField || mistyBlueField;
        }

        private static bool LooksLikeDarkGeneratedBackdropPlate(Color32 p)
        {
            return p.a > 32
                && p.r < 46
                && p.g < 54
                && p.b < 50
                && Mathf.Max(p.r, Mathf.Max(p.g, p.b)) - Mathf.Min(p.r, Mathf.Min(p.g, p.b)) < 30;
        }

        private static bool LooksLikePaleGeneratedBackdrop(Color32 p)
        {
            return p.a > 32
                && p.r > 154
                && p.g > 142
                && p.b > 86
                && p.b < 214
                && Mathf.Abs(p.r - p.g) < 76
                && p.r + p.g > p.b * 2 + 86
                && Mathf.Max(p.r, p.g) - p.b > 22;
        }

        private static bool LooksLikeRelatedGeneratedBackdrop(Color32 p, Color32 key)
        {
            if (!LooksLikeGeneratedBackdropPlate(p)) return false;
            return Mathf.Abs(p.r - key.r) < 70
                && Mathf.Abs(p.g - key.g) < 76
                && Mathf.Abs(p.b - key.b) < 86;
        }

        private static bool LooksLikeFlatGeneratedBackdropField(Color32 p, Color32 key)
        {
            if (p.a <= 32) return false;
            bool keyedWarm = LooksLikeGeneratedBackdropPlate(key);
            bool similarToKey = Mathf.Abs(p.r - key.r) < 84 && Mathf.Abs(p.g - key.g) < 90 && Mathf.Abs(p.b - key.b) < 98;
            bool yellowGreenPlate = p.r > 146 && p.g > 138 && p.g < 248 && p.b < 132 && p.r + 34 >= p.g;
            bool creamPlate = p.r > 172 && p.g > 154 && p.b > 92 && p.b < 192 && Mathf.Abs(p.r - p.g) < 70;
            return keyedWarm && similarToKey && (yellowGreenPlate || creamPlate || LooksLikePaleGeneratedBackdrop(p) || LooksLikeWarmGeneratedBackdrop(p));
        }

        private static int BackdropColorDistance(Color32 a, Color32 b)
        {
            int dr = a.r - b.r;
            int dg = a.g - b.g;
            int db = a.b - b.b;
            return dr * dr + dg * dg + db * db;
        }

        private IEnumerator SpriteFlash(SpriteRenderer sr, Color flash)
        {
            if (!sr) yield break;
            var old = sr.color;
            sr.color = Color.Lerp(old, flash, .32f);
            yield return new WaitForSeconds(.035f);
            if (sr) sr.color = old;
        }

        private static Image Bar(Transform parent, string name, Vector2 pos, Vector2 size, Color fill, Color bg, Sprite frameSprite = null)
        {
            var bgRt = UIBox(name + "Bg", parent, pos, size, new Vector2(0, 1), new Vector2(0, 1), bg);
            var bgImage = bgRt.GetComponent<Image>();
            if (bgImage) bgImage.raycastTarget = false;
            UIBox(name + "TopLight", bgRt, new Vector2(size.x * .5f, size.y * .22f), new Vector2(size.x * .94f, Mathf.Max(2f, size.y * .10f)), new Vector2(0, .5f), new Vector2(0, .5f), new Color(1f, 1f, 1f, .10f));
            var fillSize = new Vector2(size.x * .78f, size.y * .32f);
            var fillRt = UIFillBox(name + "Fill", bgRt, fillSize, fill);
            fillRt.anchoredPosition = new Vector2(size.x * .11f, -size.y * .04f);
            return fillRt.GetComponent<Image>();
        }

        private static RectTransform UIFillBox(string name, Transform parent, Vector2 size, Color color)
        {
            var rt = UIBox(name, parent, Vector2.zero, size, new Vector2(0, .5f), new Vector2(0, .5f), color);
            rt.pivot = new Vector2(0, .5f);
            rt.anchoredPosition = Vector2.zero;
            var image = rt.GetComponent<Image>();
            if (image)
            {
                image.type = Image.Type.Filled;
                image.fillMethod = Image.FillMethod.Horizontal;
                image.fillOrigin = (int)Image.OriginHorizontal.Left;
                image.fillAmount = 1f;
            }
            return rt;
        }

        private void ApplyUiArt(RectTransform target, int index)
        {
            if (uiSprites == null || index < 0 || index >= uiSprites.Length || !uiSprites[index]) return;
            ApplySprite(target, uiSprites[index], Color.white);
        }

        private Sprite ControlSprite(int index)
        {
            return controlUiSprites != null && index >= 0 && index < controlUiSprites.Length ? controlUiSprites[index] : null;
        }

        private Sprite RuneUiSprite(int index)
        {
            return runeUiSprites != null && index >= 0 && index < runeUiSprites.Length ? runeUiSprites[index] : null;
        }

        private Sprite CombatVfxSprite(int index)
        {
            return combatVfxSprites != null && index >= 0 && index < combatVfxSprites.Length ? combatVfxSprites[index] : null;
        }

        private GameObject SpawnTimedSprite(string name, Sprite sprite, Vector2 pos, Vector2 size, Color color, int order, float life)
        {
            if (ShouldDropMotionEnemyAttackPlateInstance(name, sprite, size, color)) return null;
            bool cleanPrimitive = IsCleanPrimitiveVfxName(name);
            bool forceProcedural = ShouldForceProceduralWorldVfx(name);
            if (cleanPrimitive || forceProcedural) sprite = SpriteCache.White;
            ClampCrispMotionVfx(name, ref size, ref color, ref life);
            var fx = SpriteObj(name, fxRoot, sprite, pos, size, color, order);
            if (cleanPrimitive || forceProcedural) RegisterCleanWorldVfx(fx);
            DestroyRuntimeObject(fx, life);
            return fx;
        }

        private static void ClampCrispMotionVfx(string name, ref Vector2 size, ref Color color, ref float life)
        {
            if (string.IsNullOrEmpty(name)) return;
            bool heroAction = IsHeroActionMotionVfxName(name);
            bool noEchoBody = name.IndexOf("NoEchoBody", StringComparison.Ordinal) >= 0;
            if (!heroAction && !IsMotionOrEnemyAttackPlateRiskName(name) && !noEchoBody) return;

            float width = Mathf.Abs(size.x);
            float height = Mathf.Abs(size.y);
            if (heroAction)
            {
                float widthCap = name.IndexOf("ComboFinisher", StringComparison.Ordinal) >= 0 ? ComboFinisherLineWidthCap : .72f;
                float heightCap = noEchoBody ? .010f : HeroActionLineHeightCap;
                if (width > widthCap)
                    size = new Vector2(Mathf.Sign(size.x == 0f ? 1f : size.x) * widthCap, size.y);
                if (height > heightCap && width > .08f)
                    size = new Vector2(size.x, Mathf.Sign(size.y == 0f ? 1f : size.y) * heightCap);
                width = Mathf.Abs(size.x);
                height = Mathf.Abs(size.y);
            }
            if (width > .72f && height > .018f)
                size = new Vector2(Mathf.Sign(size.x == 0f ? 1f : size.x) * .72f, Mathf.Sign(size.y == 0f ? 1f : size.y) * .018f);
            if (height > .030f && width > .20f)
                size = new Vector2(size.x, Mathf.Sign(size.y == 0f ? 1f : size.y) * .030f);

            float maxAlpha = name.IndexOf("Warn", StringComparison.Ordinal) >= 0 || name.IndexOf("Intent", StringComparison.Ordinal) >= 0 ? .12f : .18f;
            if (name.IndexOf("Attack", StringComparison.Ordinal) >= 0
                || name.IndexOf("Slash", StringComparison.Ordinal) >= 0
                || name.IndexOf("Melee", StringComparison.Ordinal) >= 0
                || noEchoBody)
                maxAlpha = Mathf.Min(maxAlpha, .14f);
            if (heroAction)
                maxAlpha = Mathf.Min(maxAlpha, noEchoBody ? HeroNoEchoBodyAlphaCap : name.IndexOf("ComboFinisher", StringComparison.Ordinal) >= 0 ? .105f : .11f);
            color = new Color(color.r, color.g, color.b, Mathf.Min(color.a, maxAlpha));
            life = Mathf.Min(life, noEchoBody ? .045f : .070f);
            if (heroAction)
                life = Mathf.Min(life, noEchoBody ? HeroNoEchoBodyLifeCap : name.IndexOf("ComboFinisher", StringComparison.Ordinal) >= 0 ? .040f : HeroActionVfxLifeCap);
        }

        private static bool IsHeroActionMotionVfxName(string name)
        {
            if (string.IsNullOrEmpty(name)) return false;
            return name.IndexOf("Hero", StringComparison.Ordinal) >= 0
                || name.IndexOf("PlayerAttack", StringComparison.Ordinal) >= 0
                || name.IndexOf("MeleeImpact", StringComparison.Ordinal) >= 0
                || name.IndexOf("MeleeHeavy", StringComparison.Ordinal) >= 0
                || name.IndexOf("HeavySlash", StringComparison.Ordinal) >= 0
                || name.IndexOf("ComboFinisher", StringComparison.Ordinal) >= 0
                || name.IndexOf("SkillRelease", StringComparison.Ordinal) >= 0
                || name.IndexOf("SkillCast", StringComparison.Ordinal) >= 0
                || name.IndexOf("PlayerSkill", StringComparison.Ordinal) >= 0;
        }

        private static bool IsCleanPrimitiveVfxName(string name)
        {
            if (string.IsNullOrEmpty(name)) return false;
            return name.IndexOf("NoYellowPlate", StringComparison.Ordinal) >= 0
                || name.IndexOf("NoPlate", StringComparison.Ordinal) >= 0
                || name.IndexOf("NoTexturePlate", StringComparison.Ordinal) >= 0
                || name.IndexOf("NoEchoBody", StringComparison.Ordinal) >= 0
                || name.IndexOf("NoBackdrop", StringComparison.Ordinal) >= 0
                || name.IndexOf("NoOcclude", StringComparison.Ordinal) >= 0
                || name.IndexOf("ThinNoBlur", StringComparison.Ordinal) >= 0
                || name.IndexOf("CleanThin", StringComparison.Ordinal) >= 0
                || name.IndexOf("CleanEllipse", StringComparison.Ordinal) >= 0
                || name.IndexOf("CleanTick", StringComparison.Ordinal) >= 0
                || name.IndexOf("NoText", StringComparison.Ordinal) >= 0
                || name.IndexOf("NeedleLine", StringComparison.Ordinal) >= 0
                || name.IndexOf("FootLine", StringComparison.Ordinal) >= 0
                || name.IndexOf("FrameSnap", StringComparison.Ordinal) >= 0
                || name.IndexOf("FrameRuler", StringComparison.Ordinal) >= 0
                || name.IndexOf("HandTick", StringComparison.Ordinal) >= 0
                || name.IndexOf("CenterTick", StringComparison.Ordinal) >= 0
                || name.IndexOf("Crisp", StringComparison.Ordinal) >= 0
                || name.IndexOf("CleanOnly", StringComparison.Ordinal) >= 0;
        }

        private static bool ShouldForceProceduralWorldVfx(string name)
        {
            if (string.IsNullOrEmpty(name)) return false;
            bool motionOrEnemyAttackRisk = IsMotionOrEnemyAttackPlateRiskName(name);
            if (IsGoldSemanticVfxName(name) && !motionOrEnemyAttackRisk) return false;
            return motionOrEnemyAttackRisk
                || IsHighFrequencyGameplayVfxName(name)
                || name.IndexOf("RoomObjective", StringComparison.Ordinal) >= 0
                || name.IndexOf("Proceed", StringComparison.Ordinal) >= 0
                || name.IndexOf("ClearPulse", StringComparison.Ordinal) >= 0;
        }

        private static Color SanitizeWorldVfxColor(string name, Color color)
        {
            if (IsAdventureSolidGroundName(name)) return color;
            bool backdropLike = IsGeneratedBackdropLikeVfxColor(color);
            bool motionOrEnemyAttackRisk = IsMotionOrEnemyAttackPlateRiskName(name);
            if (string.IsNullOrEmpty(name) || (!IsHighFrequencyGameplayVfxName(name) && !motionOrEnemyAttackRisk) || (!IsWarmYellowOrange(color) && !backdropLike)) return color;
            if (IsGoldSemanticVfxName(name) && !motionOrEnemyAttackRisk) return color;
            if (motionOrEnemyAttackRisk)
            {
                if (ShouldDropWarmMotionEnemyAttackVfx(name) || backdropLike || IsWarmYellowOrange(color))
                    return new Color(.72f, .96f, 1f, 0f);
                if (name.IndexOf("Boss", StringComparison.Ordinal) >= 0
                    || name.IndexOf("Warn", StringComparison.Ordinal) >= 0
                    || name.IndexOf("Threat", StringComparison.Ordinal) >= 0
                    || name.IndexOf("Intent", StringComparison.Ordinal) >= 0
                    || name.IndexOf("Enemy", StringComparison.Ordinal) >= 0
                    || name.IndexOf("Archer", StringComparison.Ordinal) >= 0)
                    return new Color(1f, .30f, .34f, Mathf.Min(color.a, MotionEnemyAttackWarmPlateAlpha));
                return new Color(.72f, .96f, 1f, Mathf.Min(color.a, MotionEnemyAttackWarmPlateAlpha));
            }
            if (name.IndexOf("Boss", StringComparison.Ordinal) >= 0
                || name.IndexOf("Warn", StringComparison.Ordinal) >= 0
                || name.IndexOf("Threat", StringComparison.Ordinal) >= 0
                || name.IndexOf("Intent", StringComparison.Ordinal) >= 0)
                return new Color(1f, .30f, .34f, 0f);
            return new Color(.72f, .96f, 1f, Mathf.Min(color.a, .16f));
        }

