        private static Color LimitWorldVfxPlateAlpha(string name, Vector2 size, Color color)
        {
            if (IsAdventureSolidGroundName(name)) return color;
            bool motionOrEnemyAttackRisk = IsMotionOrEnemyAttackPlateRiskName(name);
            if (string.IsNullOrEmpty(name) || (IsGoldSemanticVfxName(name) && !motionOrEnemyAttackRisk) || (!IsHighFrequencyGameplayVfxName(name) && !motionOrEnemyAttackRisk)) return color;
            float width = Mathf.Abs(size.x);
            float height = Mathf.Abs(size.y);
            float area = width * height;
            bool largePlate = area > .42f || (width > 1.35f && height > .055f) || height > .24f;
            if (motionOrEnemyAttackRisk)
                largePlate = largePlate || area > .080f || height > .020f || width > .56f;

            float maxAlpha = .18f;
            if (motionOrEnemyAttackRisk)
                maxAlpha = MotionEnemyAttackPlateAlpha;
            if (motionOrEnemyAttackRisk && (IsWarmYellowOrange(color) || IsGeneratedBackdropLikeVfxColor(color)))
                maxAlpha = MotionEnemyAttackWarmPlateAlpha;
            if (motionOrEnemyAttackRisk && ShouldDropWarmMotionEnemyAttackVfx(name) && (IsWarmYellowOrange(color) || IsGeneratedBackdropLikeVfxColor(color)) && (width > .20f || height > .006f))
                maxAlpha = Mathf.Min(maxAlpha, MotionEnemyAttackWarmPlateAlpha);
            if (!largePlate && !motionOrEnemyAttackRisk) return color;
            if (name.IndexOf("Warn", StringComparison.Ordinal) >= 0
                || name.IndexOf("Telegraph", StringComparison.Ordinal) >= 0
                || name.IndexOf("Aim", StringComparison.Ordinal) >= 0
                || name.IndexOf("GroundWarn", StringComparison.Ordinal) >= 0)
                maxAlpha = Mathf.Min(maxAlpha, motionOrEnemyAttackRisk ? .018f : .090f);
            if (name.IndexOf("Beam", StringComparison.Ordinal) >= 0
                || name.IndexOf("Laser", StringComparison.Ordinal) >= 0
                || name.IndexOf("LockWall", StringComparison.Ordinal) >= 0)
                maxAlpha = Mathf.Min(maxAlpha, motionOrEnemyAttackRisk ? .026f : .12f);
            if ((name.IndexOf("Spine", StringComparison.Ordinal) >= 0
                    || name.IndexOf("Sweep", StringComparison.Ordinal) >= 0
                    || name.IndexOf("Thunder", StringComparison.Ordinal) >= 0)
                && height > width * 5f)
                maxAlpha = Mathf.Min(maxAlpha, .018f);
            if (name.IndexOf("Pulse", StringComparison.Ordinal) >= 0
                || name.IndexOf("Ring", StringComparison.Ordinal) >= 0
                || name.IndexOf("Aura", StringComparison.Ordinal) >= 0)
                maxAlpha = Mathf.Min(maxAlpha, motionOrEnemyAttackRisk ? .020f : .10f);
            return new Color(color.r, color.g, color.b, Mathf.Min(color.a, maxAlpha));
        }

