        private static bool IsWarmYellowOrange(Color color)
        {
            return color.r > .82f && color.g > .42f && color.g < .96f && color.b < .70f;
        }

        private static bool IsGeneratedBackdropLikeVfxColor(Color color)
        {
            return color.a > .010f
                && color.r > .52f
                && color.g > .50f
                && color.b > .26f
                && color.b < .82f
                && Mathf.Abs(color.r - color.g) < .34f
                && color.r + color.g > color.b * 2f + .34f;
        }

        private static bool ShouldDropMotionEnemyAttackPlateInstance(string name, Sprite sprite, Vector2 size, Color color)
        {
            if (string.IsNullOrEmpty(name) || IsCleanPrimitiveVfxName(name)) return false;
            if (SuppressFootGuideLineVfx && ShouldSuppressFootGuideLineVfx(name, size)) return true;
            bool motionOrEnemyAttackRisk = IsMotionOrEnemyAttackPlateRiskName(name);
            if (!motionOrEnemyAttackRisk || (IsGoldSemanticVfxName(name) && !ShouldDropWarmMotionEnemyAttackVfx(name))) return false;
            if (ShouldForceProceduralWorldVfx(name) && !ShouldDropWarmMotionEnemyAttackVfx(name)) return false;

            float width = Mathf.Abs(size.x);
            float height = Mathf.Abs(size.y);
            bool notHairline = IsMotionEnemyAttackPlateSized(size);
            bool warmPlateColor = IsWarmYellowOrange(color) || IsGeneratedBackdropLikeVfxColor(color);
            bool dirtySpritePlate = sprite && sprite != SpriteCache.White && SpriteHasGeneratedBackdropPlate(sprite);
            bool externalMotionSheet = sprite && sprite != SpriteCache.White && ShouldDropWarmMotionEnemyAttackVfx(name);
            return notHairline && (dirtySpritePlate || warmPlateColor || externalMotionSheet);
        }

        private static bool ShouldDropMotionEnemyAttackPlateFrame(string name, Sprite frame)
        {
            if (string.IsNullOrEmpty(name) || IsCleanPrimitiveVfxName(name)) return false;
            if (SuppressFootGuideLineVfx && ShouldSuppressFootGuideLineVfx(name, Vector2.one)) return true;
            if (!IsMotionOrEnemyAttackPlateRiskName(name)) return false;
            return frame && frame != SpriteCache.White && SpriteHasGeneratedBackdropPlate(frame);
        }

        private static bool ShouldSuppressFootGuideLineVfx(string name, Vector2 size)
        {
            if (string.IsNullOrEmpty(name)) return false;
            bool footGuide = name.IndexOf("FootLine", StringComparison.Ordinal) >= 0
                || name.IndexOf("GroundCue", StringComparison.Ordinal) >= 0
                || name.IndexOf("GroundPulse", StringComparison.Ordinal) >= 0
                || name.IndexOf("Skid", StringComparison.Ordinal) >= 0
                || name.IndexOf("Trace", StringComparison.Ordinal) >= 0
                || name.IndexOf("Trail", StringComparison.Ordinal) >= 0
                || name.IndexOf("ProceedRoute", StringComparison.Ordinal) >= 0
                || name.IndexOf("PlayerProceed", StringComparison.Ordinal) >= 0;
            if (!footGuide) return false;
            bool importantHit = name.IndexOf("Impact", StringComparison.Ordinal) >= 0
                || name.IndexOf("Hit", StringComparison.Ordinal) >= 0
                || name.IndexOf("Break", StringComparison.Ordinal) >= 0
                || name.IndexOf("Boss", StringComparison.Ordinal) >= 0;
            if (importantHit) return false;
            float width = Mathf.Abs(size.x);
            float height = Mathf.Abs(size.y);
            return width > .16f || height > .006f;
        }

        private static bool IsMotionEnemyAttackPlateSized(Vector2 size)
        {
            float width = Mathf.Abs(size.x);
            float height = Mathf.Abs(size.y);
            return width > .20f || height > .006f || width * height > .015f;
        }

        private GameObject SpawnTimedRect(string name, Vector2 pos, Vector2 size, Color color, int order, float life)
        {
            if (ShouldDropMotionEnemyAttackPlateInstance(name, null, size, color)) return null;
            var fx = RectObj(name, fxRoot, pos, size, color, order);
            if (IsCleanPrimitiveVfxName(name) || ShouldForceProceduralWorldVfx(name)) RegisterCleanWorldVfx(fx);
            DestroyRuntimeObject(fx, life);
            return fx;
        }

        private void RegisterCleanWorldVfx(GameObject fx)
        {
            if (!fx || CleanWorldVfxBudget <= 0) return;
            cleanWorldVfxBudget.RemoveAll(item => !item);
            cleanWorldVfxBudget.Add(fx);
            while (cleanWorldVfxBudget.Count > CleanWorldVfxBudget)
            {
                var oldest = cleanWorldVfxBudget[0];
                cleanWorldVfxBudget.RemoveAt(0);
                if (oldest) DestroyRuntimeObject(oldest);
            }
        }

        private GameObject SpawnVfxSequence(string name, Sprite[] frames, Vector2 pos, Vector2 size, Color color, int order, float life, float fps = 24f, bool faceCurrentDirection = false)
        {
            if (frames == null || frames.Length == 0 || !frames[0]) return null;
            if (ShouldDropMotionEnemyAttackPlateInstance(name, frames[0], size, color)) return null;
            if (ShouldForceProceduralWorldVfx(name))
                return SpawnTimedSprite(name + "_ProceduralNoPlateFallback", SpriteCache.White, pos, new Vector2(Mathf.Min(Mathf.Abs(size.x), 1.18f) * Mathf.Sign(size.x == 0f ? 1f : size.x), Mathf.Min(Mathf.Abs(size.y), .030f)), new Color(.88f, .98f, 1f, Mathf.Min(color.a, .22f)), order, Mathf.Min(life, .11f));
            var fx = SpriteObj(name, fxRoot, frames[0], pos, size, color, order);
            if (faceCurrentDirection) fx.transform.localScale = new Vector3(Mathf.Abs(fx.transform.localScale.x) * facing, fx.transform.localScale.y, 1f);
            StartCoroutine(PlayVfxSequence(name, fx.GetComponent<SpriteRenderer>(), frames, Mathf.Max(1f, fps), life));
            DestroyRuntimeObject(fx, life);
            return fx;
        }

        private void DestroyRuntimeObject(UnityEngine.Object target, float delay = 0f)
        {
            if (!target) return;
            if (Application.isPlaying) Destroy(target, delay);
        }

        private IEnumerator PlayVfxSequence(string name, SpriteRenderer renderer, Sprite[] frames, float fps, float life)
        {
            if (!renderer || frames == null || frames.Length == 0) yield break;
            float elapsed = 0f;
            while (renderer && elapsed < life)
            {
                int frame = Mathf.Clamp(Mathf.FloorToInt(elapsed * fps), 0, frames.Length - 1);
                if (frames[frame] && !ShouldDropMotionEnemyAttackPlateFrame(name, frames[frame]))
                    renderer.sprite = frames[frame];
                elapsed += Time.deltaTime;
                yield return null;
            }
        }

        private void AddDangerPattern(GameObject root, DangerPatternKind kind, Color color, int orderOffset)
        {
            if (!root) return;
            var baseScale = root.transform.localScale;
            color.a = Mathf.Min(color.a <= 0f ? .12f : color.a, effectsIntensity > .75f ? .20f : .12f);
            string rootName = root.name ?? string.Empty;
            bool thinCombatReadability = rootName.IndexOf("ArcherAim", StringComparison.Ordinal) >= 0
                || rootName.IndexOf("EnemyMelee", StringComparison.Ordinal) >= 0
                || rootName.IndexOf("BossThunderThinCrosshairWarn", StringComparison.Ordinal) >= 0
                || rootName.IndexOf("PreviewBossWarn", StringComparison.Ordinal) >= 0;
            if (thinCombatReadability)
                color.a = Mathf.Min(color.a, effectsIntensity > .75f ? .018f : .012f);
            if (kind == DangerPatternKind.Crosshair)
            {
                AddDangerPatternLine(root.transform, "CrosshairH", Vector2.zero, new Vector2(.76f, .020f / Mathf.Max(.01f, baseScale.y)), 0f, color, orderOffset);
                AddDangerPatternLine(root.transform, "CrosshairV", Vector2.zero, new Vector2(.020f / Mathf.Max(.01f, baseScale.x), .76f), 0f, color, orderOffset);
                RectObj("DangerPatternInnerRing_NoYellowPlateLine", root.transform, Vector2.zero, new Vector2(.36f / Mathf.Max(.01f, baseScale.x), .018f / Mathf.Max(.01f, baseScale.y)), new Color(color.r, color.g, color.b, color.a * .24f), root.GetComponent<SpriteRenderer>().sortingOrder + orderOffset);
                if (!thinCombatReadability)
                    AddDangerPatternGlyph(root.transform, "DangerPatternCrosshairGlyph", "瞄", Vector2.zero, color, orderOffset + 2);
                return;
            }

            int count = Mathf.Clamp(Mathf.CeilToInt(baseScale.x / .42f), 3, 10);
            for (int i = 0; i < count; i++)
            {
                float t = count <= 1 ? .5f : i / (float)(count - 1);
                float x = Mathf.Lerp(-baseScale.x * .42f, baseScale.x * .42f, t);
                float rotation = kind == DangerPatternKind.ToxicWaves ? 0f : 28f;
                float localX = x / Mathf.Max(.01f, baseScale.x);
                Vector2 size = kind == DangerPatternKind.ToxicWaves
                    ? new Vector2(.034f / Mathf.Max(.01f, baseScale.x), .72f)
                    : new Vector2((thinCombatReadability ? .012f : .030f) / Mathf.Max(.01f, baseScale.x), thinCombatReadability ? .58f : 1.18f);
                AddDangerPatternLine(root.transform, kind == DangerPatternKind.ToxicWaves ? "ToxicWaveStripe" : "DangerStripe", new Vector2(localX, 0), size, rotation, color, orderOffset);
            }
            if (kind == DangerPatternKind.ToxicWaves)
                AddDangerPatternLine(root.transform, "ToxicWaveMidline", Vector2.zero, new Vector2(.78f, .035f / Mathf.Max(.01f, baseScale.y)), 0f, new Color(color.r, color.g, color.b, color.a * .62f), orderOffset);
            if (!thinCombatReadability)
                AddDangerPatternGlyph(root.transform, kind == DangerPatternKind.ToxicWaves ? "DangerPatternToxicGlyph" : "DangerPatternDamageGlyph", kind == DangerPatternKind.ToxicWaves ? "毒" : "!!", Vector2.zero, color, orderOffset + 2);
        }

        private static void AddDangerPatternLine(Transform parent, string name, Vector2 localPos, Vector2 size, float rotationZ, Color color, int orderOffset)
        {
            var parentRenderer = parent.GetComponent<SpriteRenderer>();
            int order = parentRenderer ? parentRenderer.sortingOrder + orderOffset : orderOffset;
            var line = RectObj(name, parent, localPos, size, color, order);
            line.transform.localRotation = Quaternion.Euler(0f, 0f, rotationZ);
        }

        private void AddDangerPatternGlyph(Transform parent, string name, string glyph, Vector2 localPos, Color color, int orderOffset)
        {
            if (!parent) return;
            var parentRenderer = parent.GetComponent<SpriteRenderer>();
            int order = parentRenderer ? parentRenderer.sortingOrder + orderOffset : orderOffset;
            var text = WorldText(name, parent, glyph, localPos, glyph.Length > 1 ? 20 : 24, order);
            float alpha = effectsIntensity > .75f ? .86f : .62f;
            text.color = new Color(color.r, color.g, color.b, alpha);
            text.characterSize = .055f;
            text.anchor = TextAnchor.MiddleCenter;
        }

        private static void ApplySprite(RectTransform target, Sprite sprite, Color color)
        {
            if (!target || !sprite) return;
            var image = target.GetComponent<Image>();
            if (!image) return;
            image.sprite = sprite;
            image.color = color;
            image.preserveAspect = true;
        }

        private static GameObject RectObj(string name, Transform parent, Vector2 pos, Vector2 size, Color color, int order)
        {
            color = SanitizeWorldVfxColor(name, color);
            color = LimitWorldVfxPlateAlpha(name, size, color);
            var go = new GameObject(name);
            go.transform.SetParent(parent);
            go.transform.localPosition = pos;
            go.transform.localScale = new Vector3(size.x, size.y, 1);
            var sr = go.AddComponent<SpriteRenderer>();
            sr.sprite = SpriteCache.White;
            sr.color = color;
            sr.sortingOrder = order;
            return go;
        }

        private static GameObject CircleObj(string name, Transform parent, Vector2 pos, float radius, Color color, int order)
        {
            var go = RectObj(name, parent, pos, new Vector2(radius * 2, radius * 2), color, order);
            go.GetComponent<SpriteRenderer>().sprite = SpriteCache.Circle;
            return go;
        }

        private static GameObject SpriteObj(string name, Transform parent, Sprite sprite, Vector2 pos, Vector2 size, Color color, int order)
        {
            if (ShouldForceProceduralWorldVfx(name)) sprite = SpriteCache.White;
            color = SanitizeWorldVfxColor(name, color);
            color = LimitWorldVfxPlateAlpha(name, size, color);
            var go = new GameObject(name);
            go.transform.SetParent(parent);
            go.transform.localPosition = pos;
            var sr = go.AddComponent<SpriteRenderer>();
            sr.sprite = sprite ? sprite : SpriteCache.Circle;
            sr.color = color;
            sr.sortingOrder = order;
            Vector2 bounds = sr.sprite ? (Vector2)sr.sprite.bounds.size : Vector2.one;
            go.transform.localScale = new Vector3(size.x / Mathf.Max(.01f, bounds.x), size.y / Mathf.Max(.01f, bounds.y), 1);
            return go;
        }

        private static void WorldButtonHint(Transform parent, string label, Vector2 pos, float radius, Color color, Sprite sprite)
        {
            SpriteObj("WorldButton_" + label.Replace("\n", "_"), parent, sprite, pos, new Vector2(radius * 2, radius * 2), new Color(color.r, color.g, color.b, .42f), 40);
            var text = WorldText("WorldButtonLabel_" + label.Replace("\n", "_"), parent, label, pos + new Vector2(0, -.03f), label.Length > 2 ? 24 : 30, 42);
            text.color = new Color(.90f, 1f, 1f, .72f);
        }

        private static TextMesh WorldText(string name, Transform parent, string value, Vector2 pos, int size, int order)
        {
            var go = new GameObject(name, typeof(TextMesh));
            go.transform.SetParent(parent);
            go.transform.localPosition = new Vector3(pos.x, pos.y, -.02f);
            var text = go.GetComponent<TextMesh>();
            int readableSize = WorldTextReadableFontSize(name, size);
            text.text = value;
            text.fontSize = readableSize;
            text.characterSize = readableSize / (IsTransientCombatWorldTextName(name) ? 980f : 900f);
            text.lineSpacing = .82f;
            text.anchor = TextAnchor.MiddleCenter;
            text.alignment = TextAlignment.Center;
            text.color = Color.white;
            var renderer = go.GetComponent<MeshRenderer>();
            renderer.sortingOrder = order;
            return text;
        }

        private static int WorldTextReadableFontSize(string name, int requestedSize)
        {
            if (string.IsNullOrEmpty(name)) return requestedSize;
            if (name.IndexOf("Boss", StringComparison.Ordinal) >= 0
                || name.IndexOf("FinalVictory", StringComparison.Ordinal) >= 0
                || name.IndexOf("DefeatText", StringComparison.Ordinal) >= 0)
                return requestedSize;
            if (name.IndexOf("AttackStepCue", StringComparison.Ordinal) >= 0
                || name.IndexOf("EnemyIntentText", StringComparison.Ordinal) >= 0
                || name.IndexOf("SkillCastCue", StringComparison.Ordinal) >= 0
                || name.IndexOf("HitFrameBeatText", StringComparison.Ordinal) >= 0)
                return Mathf.Min(requestedSize, 20);
            if (name.IndexOf("PerfectDodge", StringComparison.Ordinal) >= 0
                || name.IndexOf("ComboFinisher", StringComparison.Ordinal) >= 0
                || name.IndexOf("RoomClear", StringComparison.Ordinal) >= 0
                || name.IndexOf("PickupText", StringComparison.Ordinal) >= 0)
                return Mathf.Min(requestedSize, 18);
            return requestedSize;
        }

        private static bool IsTransientCombatWorldTextName(string name)
        {
            if (string.IsNullOrEmpty(name)) return false;
            return name.IndexOf("AttackStepCue", StringComparison.Ordinal) >= 0
                || name.IndexOf("EnemyIntentText", StringComparison.Ordinal) >= 0
                || name.IndexOf("SkillCastCue", StringComparison.Ordinal) >= 0
                || name.IndexOf("HitFrameBeatText", StringComparison.Ordinal) >= 0
                || name.IndexOf("PerfectDodge", StringComparison.Ordinal) >= 0
                || name.IndexOf("ComboFinisher", StringComparison.Ordinal) >= 0
                || name.IndexOf("RoomClear", StringComparison.Ordinal) >= 0
                || name.IndexOf("PickupText", StringComparison.Ordinal) >= 0;
        }

        private static RectTransform UIBox(string name, Transform parent, Vector2 pos, Vector2 size, Vector2 anchorMin, Vector2 anchorMax, Color color)
        {
            var go = new GameObject(name, typeof(RectTransform), typeof(Image));
            var rt = go.GetComponent<RectTransform>();
            rt.SetParent(parent, false);
            rt.anchorMin = anchorMin;
            rt.anchorMax = anchorMax;
            rt.pivot = new Vector2(.5f, .5f);
            rt.anchoredPosition = pos;
            if (size != Vector2.zero) rt.sizeDelta = size;
            go.GetComponent<Image>().color = color;
            return rt;
        }

        private static RectTransform UICircle(string name, Transform parent, Vector2 pos, Vector2 size, Vector2 anchorMin, Vector2 anchorMax, Color color)
        {
            var rt = UIBox(name, parent, pos, size, anchorMin, anchorMax, color);
            rt.GetComponent<Image>().sprite = SpriteCache.Circle;
            return rt;
        }

        private static RectTransform UIIcon(string name, Transform parent, Sprite sprite, Vector2 pos, Vector2 size, Vector2 anchorMin, Vector2 anchorMax, Color color)
        {
            var rt = UIBox(name, parent, pos, size, anchorMin, anchorMax, color);
            ApplySprite(rt, sprite, color);
            return rt;
        }

        private static Text UIText(string name, Transform parent, string value, int size, TextAnchor align, Vector2 pos, Vector2 wh, Vector2 anchorMin, Vector2 anchorMax)
        {
            var go = new GameObject(name, typeof(RectTransform), typeof(Text));
            var rt = go.GetComponent<RectTransform>();
            rt.SetParent(parent, false);
            rt.anchorMin = anchorMin; rt.anchorMax = anchorMax; rt.pivot = new Vector2(.5f, .5f); rt.anchoredPosition = pos; rt.sizeDelta = wh;
            var t = go.GetComponent<Text>();
            t.text = value; t.fontSize = size; t.alignment = align; t.color = Color.white; t.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf"); t.fontStyle = FontStyle.Bold;
            t.raycastTarget = false;
            return t;
        }

        private static void FitHudText(Text text, int minSize, int maxSize)
        {
            if (!text) return;
            text.resizeTextForBestFit = true;
            text.resizeTextMinSize = minSize;
            text.resizeTextMaxSize = maxSize;
            text.horizontalOverflow = HorizontalWrapMode.Wrap;
            text.verticalOverflow = VerticalWrapMode.Truncate;
        }

        private static RectTransform UIButton(string name, Transform parent, string value, int size, Vector2 pos, Vector2 wh, Vector2 anchorMin, Vector2 anchorMax, Color color, UnityEngine.Events.UnityAction action)
        {
            var rt = UIBox(name, parent, pos, wh, anchorMin, anchorMax, color);
            var btn = rt.gameObject.AddComponent<Button>();
            btn.onClick.AddListener(action);
            var label = UIText("Label", rt, value, size, TextAnchor.MiddleCenter, Vector2.zero, wh * .92f, new Vector2(.5f, .5f), new Vector2(.5f, .5f));
            label.resizeTextForBestFit = true;
            label.resizeTextMinSize = Mathf.Max(18, size - 10);
            label.resizeTextMaxSize = size;
            label.horizontalOverflow = HorizontalWrapMode.Wrap;
            label.verticalOverflow = VerticalWrapMode.Truncate;
            return rt;
        }

        private static Slider UISlider(string name, Transform parent, Vector2 pos, Vector2 size, Vector2 anchorMin, Vector2 anchorMax, float value, Sprite trackSprite)
        {
            var root = UIBox(name, parent, pos, size, anchorMin, anchorMax, Color.clear);
            var background = UIBox("Background", root, Vector2.zero, new Vector2(size.x, 14), new Vector2(.5f, .5f), new Vector2(.5f, .5f), new Color(.04f, .08f, .14f, .92f));
            ApplySprite(background, trackSprite, background.GetComponent<Image>().color);

            var fillArea = UIBox("FillArea", root, Vector2.zero, new Vector2(size.x, 14), new Vector2(.5f, .5f), new Vector2(.5f, .5f), Color.clear);
            var fill = UIBox("Fill", fillArea, Vector2.zero, new Vector2(size.x, 14), new Vector2(0, .5f), new Vector2(0, .5f), C("#2E9D66"));
            fill.pivot = new Vector2(0, .5f);
            ApplySprite(fill, trackSprite, fill.GetComponent<Image>().color);

            var handle = UICircle("Handle", root, Vector2.zero, new Vector2(42, 42), new Vector2(.5f, .5f), new Vector2(.5f, .5f), C("#8FFFF6"));
            var slider = root.gameObject.AddComponent<Slider>();
            slider.minValue = 0f;
            slider.maxValue = 1f;
            slider.wholeNumbers = false;
            slider.SetValueWithoutNotify(Mathf.Clamp01(value));
            slider.targetGraphic = handle.GetComponent<Image>();
            slider.fillRect = fill;
            slider.handleRect = handle;
            slider.direction = Slider.Direction.LeftToRight;
            return slider;
        }

        private static RectTransform UICircleButton(string name, Transform parent, string value, int fontSize, Vector2 pos, Vector2 size, Color color, UnityEngine.Events.UnityAction action, Sprite sprite = null, Vector2? anchorMin = null, Vector2? anchorMax = null)
        {
            var min = anchorMin ?? new Vector2(1, 0);
            var max = anchorMax ?? new Vector2(1, 0);
            var rt = UICircle(name, parent, pos, size, min, max, color);
            rt.gameObject.AddComponent<CanvasGroup>();
            if (sprite) ApplySprite(rt, sprite, Color.white);
            var outline = UICircle(name + "Rim", rt, Vector2.zero, size * .86f, new Vector2(.5f, .5f), new Vector2(.5f, .5f), new Color(1f, 1f, 1f, .18f));
            outline.SetAsFirstSibling();
            var btn = rt.gameObject.AddComponent<Button>();
            btn.onClick.AddListener(action);
            UIText("Label", rt, value, fontSize, TextAnchor.LowerCenter, new Vector2(0, -size.y * .18f), size * .56f, new Vector2(.5f, .5f), new Vector2(.5f, .5f));
            return rt;
        }

        private static Text UIButtonMicroText(RectTransform parent, string name, string value, Vector2 pos, Color color)
        {
            var text = UIText(name, parent, value, 16, TextAnchor.MiddleCenter, pos, new Vector2(138, 28), new Vector2(.5f, .5f), new Vector2(.5f, .5f));
            text.resizeTextForBestFit = true;
            text.resizeTextMinSize = 11;
            text.resizeTextMaxSize = 16;
            text.color = color;
            text.raycastTarget = false;
            text.gameObject.SetActive(false);
            return text;
        }

        private Image CooldownOverlay(RectTransform parent, string name)
        {
            var rt = UICircle(name, parent, Vector2.zero, parent.sizeDelta * .88f, new Vector2(.5f, .5f), new Vector2(.5f, .5f), new Color(0, 0, 0, .58f));
            var image = rt.GetComponent<Image>();
            image.type = Image.Type.Filled;
            image.fillMethod = Image.FillMethod.Radial360;
            image.fillOrigin = 2;
            image.fillClockwise = false;
            image.gameObject.SetActive(false);
            rt.SetAsLastSibling();
            return image;
        }

        private Image ReadyGlow(RectTransform parent, string name, Color color)
        {
            var rt = UICircle(name, parent, Vector2.zero, parent.sizeDelta * 1.10f, new Vector2(.5f, .5f), new Vector2(.5f, .5f), new Color(color.r, color.g, color.b, .22f));
            var image = rt.GetComponent<Image>();
            image.raycastTarget = false;
            rt.SetAsFirstSibling();
            return image;
        }

        private Text CooldownText(RectTransform parent, string name, int fontSize)
        {
            var text = UIText(name, parent, "", fontSize, TextAnchor.MiddleCenter, Vector2.zero, parent.sizeDelta * .62f, new Vector2(.5f, .5f), new Vector2(.5f, .5f));
            text.color = Color.white;
            var rt = text.rectTransform;
            rt.anchorMin = Vector2.zero;
            rt.anchorMax = Vector2.one;
            rt.offsetMin = Vector2.zero;
            rt.offsetMax = Vector2.zero;
            text.gameObject.SetActive(false);
            text.transform.SetAsLastSibling();
            return text;
        }

        private Text SkillCostText(RectTransform parent, string name, SkillKind skill)
        {
            var text = UIText(name, parent, $"{Mathf.RoundToInt(SkillCost(skill))}MP", 17, TextAnchor.MiddleCenter, new Vector2(0, -37), new Vector2(92, 28), new Vector2(.5f, .5f), new Vector2(.5f, .5f));
            text.color = new Color(.90f, .98f, 1f, .82f);
            return text;
        }

        private static Color C(string html)
        {
            ColorUtility.TryParseHtmlString(html, out var color);
            return color;
        }

        private static class SpriteCache
        {
            public static readonly Sprite White = MakeRect();
            public static readonly Sprite Circle = MakeCircle();

            private static Sprite MakeRect()
            {
                var tex = new Texture2D(8, 8);
                for (int y = 0; y < 8; y++) for (int x = 0; x < 8; x++) tex.SetPixel(x, y, Color.white);
                tex.Apply();
                return Sprite.Create(tex, new Rect(0, 0, 8, 8), new Vector2(.5f, .5f), 8);
            }

            private static Sprite MakeCircle()
            {
                var tex = new Texture2D(64, 64);
                for (int y = 0; y < 64; y++) for (int x = 0; x < 64; x++)
                    tex.SetPixel(x, y, Vector2.Distance(new Vector2(x, y), new Vector2(31.5f, 31.5f)) <= 31 ? Color.white : Color.clear);
                tex.Apply();
                return Sprite.Create(tex, new Rect(0, 0, 64, 64), new Vector2(.5f, .5f), 64);
            }
        }
    }
}
